    override fun onCreate() {
        super.onCreate()

        isRunning = false
        shuttingDown = false

        // R10.23: a new Service instance never inherits an executable voice session.
        // ACTION_START/null recovery explicitly re-enters WAKE after model readiness.
        voiceBackgroundCoordinator.invalidate(
            SystemClock.elapsedRealtime()
        )

        createNotificationChannel()
        createBatteryProactivityNotificationChannel()
        registerBatteryProactivityReceiver()

        promoteToForeground(
            "AYANA запускает локальное распознавание"
        )

        // IMPORTANT: onCreate() may be called for ACTION_STOP or another
        // service intent. Never create the overlay here. The single Orb is
        // created only after a real ACTION_START / active text command.
        ayanaPreferences.miniOrbEnabled = true

        currentStatusText =
            "AYANA запускается"

        currentStatusState =
            STATE_THINKING

        try {
            durableGoalStore
                .markInterruptedGoals(
                    "service_recreated"
                )
        } catch (_: Exception) {
        }

        prefetchReadyVoice()

        thread(
            start = true,
            name = "AyanaModelInit"
        ) {
            try {

                initSherpaModel()

                modelReady = true
                capabilityRegistry
                    .recordRecognitionReady(
                        true
                    )

                mainHandler.post {
                    if (
                        !shuttingDown &&
                        isRunning
                    ) {
                        startWakeListening()
                    }
                }

            } catch (_: Exception) {

                modelReady = false
                capabilityRegistry
                    .recordRecognitionReady(
                        false
                    )

                mainHandler.post {
                    broadcastStatus(
                        "Не удалось загрузить локальную модель",
                        STATE_ERROR
                    )

                    updateNotification(
                        "Ошибка локального распознавания"
                    )
                }
            }
        }

        // The worker waits until AYANA is fully active + wake-idle, so starting
        // the scheduler here does not compete with model initialization.
        backgroundImageIndexer.start()
    }

    override fun onStartCommand(
        intent: Intent?,
        flags: Int,
        startId: Int
    ): Int {

        when (intent?.action) {

            ACTION_STOP -> {
                shutdownAyana()
                return START_NOT_STICKY
            }

            ACTION_CANCEL_COMMAND -> {
                cancelCurrentCommand(
                    source = "button"
                )
                return START_STICKY
            }

            ACTION_RESUME_GOAL -> {

                isRunning =
                    true

                ensureOrbForActiveService()

                mainHandler.post {
                    resumeDurableGoal(
                        silent = true,
                        explicitConfirmation = false,
                        allowAutoResume = false
                    )
                }

                return START_STICKY
            }

            ACTION_CONFIRM_GOAL -> {

                isRunning =
                    true

                ensureOrbForActiveService()

                mainHandler.post {
                    resumeDurableGoal(
                        silent = true,
                        explicitConfirmation = true,
                        allowAutoResume = false
                    )
                }

                return START_STICKY
            }

            ACTION_CANCEL_GOAL -> {

                isRunning =
                    true

                ensureOrbForActiveService()
mainHandler.post {
                    cancelDurableGoalFromControl(
                        silent = true
                    )
                }

                return START_STICKY
            }

            ACTION_START -> {

                isRunning =
                    true

                ayanaPreferences.miniOrbEnabled =
                    true

                miniOrbController.refresh(
                    enabled = true,
                    state =
                        if (
                            currentStatusState ==
                            STATE_STOPPED
                        ) {
                            STATE_LISTENING
                        } else {
                            currentStatusState
                        }
                )

                if (
                    !shuttingDown &&
                    modelReady &&
                    !isRecording &&
                    listenMode != ListenMode.BUSY &&
                    listenMode != ListenMode.CANCEL
                ) {
                    startWakeListening()
                }

                maybeAutoResumeDurableGoal()
            }

            ACTION_REFRESH_OVERLAY -> {

                if (
                    isRunning &&
                    !shuttingDown &&
                    currentStatusState !=
                    STATE_STOPPED
                ) {

                    ayanaPreferences.miniOrbEnabled =
                        true

                    miniOrbController.refresh(
                        enabled = true,
                        state =
                            currentStatusState
                    )
                }
            }

            ACTION_MULTIMODAL_COMMAND -> {

                val command =
                    intent.getStringExtra(
                        EXTRA_TEXT_COMMAND
                    )
                        ?.trim()
                        .orEmpty()

                val manifest =
                    intent.getStringExtra(
                        EXTRA_MULTIMODAL_MANIFEST
                    )
                        ?.trim()
                        .orEmpty()

                if (
                    command.isNotBlank() &&
                    manifest.isNotBlank()
                ) {
                    isRunning = true
                    ayanaPreferences.miniOrbEnabled = true
                    miniOrbController.refresh(
                        enabled = true,
                        state = currentStatusState
                    )
                    stopSherpaListening()
                    mainHandler.post {
                        if (!shuttingDown) {
                            executeMultimodalCommand(
                                command,
                                manifest
                            )
                        }
                    }
                }
            }

            ACTION_TEXT_COMMAND -> {

                val command =
                    intent.getStringExtra(
                        EXTRA_TEXT_COMMAND
                    )
                        ?.trim()
                        .orEmpty()

                if (command.isNotBlank()) {

                    isRunning =
                        true

                    ayanaPreferences.miniOrbEnabled =
                        true

                    miniOrbController.refresh(
                        enabled = true,
                        state =
                            currentStatusState
                    )

                    stopSherpaListening()

                    // INSTANT TEXT v2.7.4.4
                    // Text input is already final; unlike voice it does not need an
                    // endpoint/grace delay. Queue it on the main handler immediately.
                    mainHandler.post {
                        if (!shuttingDown) {
                            executeCommand(
                                command,
                                silent = true
                            )
                        }
                    }
                }
            }

            null -> {
                // START_STICKY process recreation. Unlike BOOT_COMPLETED, this
                // is a service lifecycle recovery. Restore only a recent,
                // explicitly low-risk goal and keep the recovery bounded.
                isRunning =
                    true

                // R10.23: voice control-plane recovery is always WAKE-only. It never
                // replays a previously heard command; DurableGoalStore separately owns
                // any safe autonomous goal continuation.
                voiceBackgroundCoordinator.recoverService(
                    SystemClock.elapsedRealtime()
                )

                ensureOrbForActiveService()

                if (
                    !shuttingDown &&
                    modelReady &&
                    !isRecording
                ) {
                    startWakeListening()
                }

                maybeAutoResumeDurableGoal()
            }
        }

        if (
            isRunning &&
            !shuttingDown
        ) {
            currentBatteryIntent()
                ?.let { batteryIntent ->
                    handleBatteryProactivitySample(
                        intent = batteryIntent,
                        source = "service_start_or_command"
                    )
                }
        }

        return START_STICKY
    }

    override fun onBind(
        intent: Intent?
    ): IBinder? = null

    // =========================================================
    // FOREGROUND SERVICE
    // =========================================================

    private fun createNotificationChannel() {

        if (Build.VERSION.SDK_INT >= 26) {

            val channel =
                NotificationChannel(
                    CHANNEL_ID,
                    "AYANA Voice",
                    NotificationManager.IMPORTANCE_LOW
                ).apply {

                    description =
                        "Фоновая работа голосового помощника AYANA"

                    setShowBadge(false)
                }

            val manager =
                getSystemService(
                    NotificationManager::class.java
                )

            manager.createNotificationChannel(
                channel
            )
        }
    }

    private fun buildNotification(
        text: String
    ): Notification {

        val openIntent =
            Intent(
                this,
                MainActivity::class.java
            )

        val openPendingIntent =
            PendingIntent.getActivity(
                this,
                100,
                openIntent,
                PendingIntent.FLAG_UPDATE_CURRENT or
                    PendingIntent.FLAG_IMMUTABLE
            )

        val cancelIntent =
            Intent(
                this,
                AyanaVoiceService::class.java
            ).apply {
                action =
                    ACTION_CANCEL_COMMAND
            }

        val cancelPendingIntent =
            PendingIntent.getService(
                this,
                101,
                cancelIntent,
                PendingIntent.FLAG_UPDATE_CURRENT or
                    PendingIntent.FLAG_IMMUTABLE
            )

        val stopIntent =
            Intent(
                this,
                AyanaVoiceService::class.java
            ).apply {
                action = ACTION_STOP
            }

        val stopPendingIntent =
            PendingIntent.getService(
                this,
                102,
                stopIntent,
                PendingIntent.FLAG_UPDATE_CURRENT or
                    PendingIntent.FLAG_IMMUTABLE
            )

        val builder =
            if (Build.VERSION.SDK_INT >= 26) {

                Notification.Builder(
                    this,
                    CHANNEL_ID
                )

            } else {

                @Suppress("DEPRECATION")
                Notification.Builder(this)
            }

        return builder
            .setSmallIcon(
                android.R.drawable.ic_btn_speak_now
            )
            .setContentTitle("AYANA AI")
            .setContentText(text)
            .setSubText(
                "Голос AYANA синтезирован искусственным интеллектом"
            )
            .setOngoing(true)
            .setOnlyAlertOnce(true)
            .setContentIntent(openPendingIntent)
            .addAction(
                android.R.drawable.ic_media_pause,
                "Стоп команды",
                cancelPendingIntent
            )
            .addAction(
                android.R.drawable.ic_delete,
                "Остановить AYANA",
                stopPendingIntent
            )
            .build()
    }

    private fun promoteToForeground(
        text: String
    ) {

        val notification =
            buildNotification(text)

        if (Build.VERSION.SDK_INT >= 29) {

            startForeground(
                NOTIFICATION_ID,
                notification,
                ServiceInfo
                    .FOREGROUND_SERVICE_TYPE_MICROPHONE
            )

        } else {

            startForeground(
                NOTIFICATION_ID,
                notification
            )
        }
    }

    private fun updateNotification(
        text: String
    ) {

        val manager =
            getSystemService(
                NotificationManager::class.java
            )

        manager.notify(
            NOTIFICATION_ID,
            buildNotification(text)
        )
    }

    // =========================================================
    // SHERPA-ONNX
    // =========================================================

    private fun initSherpaModel() {

        val modelDir =
            "sherpa_ru"

        val modelConfig =
            OnlineModelConfig(
                transducer =
                    OnlineTransducerModelConfig(
                        encoder =
                            "$modelDir/encoder.int8.onnx",
                        decoder =
                            "$modelDir/decoder.onnx",
                        joiner =
                            "$modelDir/joiner.int8.onnx"
                    ),
                tokens =
                    "$modelDir/tokens.txt",
                numThreads = 2,
                debug = false,
                provider = "cpu",
                modelType = "zipformer2"
            )

        val config =
            OnlineRecognizerConfig(
                featConfig =
                    FeatureConfig(
                        sampleRate =
                            sampleRateInHz,
                        featureDim = 80,
                        dither = 0.0f
                    ),
                modelConfig =
                    modelConfig,
                enableEndpoint =
                    true,
                decodingMethod =
                    "greedy_search"
            )

        recognizer =
            OnlineRecognizer(
                assetManager = assets,
                config = config
            )
    }

    private fun startWakeListening() {

        if (
shuttingDown ||
            !modelReady
        ) {
            return
        }

        listenMode =
            ListenMode.WAKE

        voiceBackgroundCoordinator.enterWake(
            SystemClock.elapsedRealtime()
        )

        broadcastStatus(
            "Жду: «Аяна»",
            STATE_LISTENING
        )

        updateNotification(
            "Жду голосовую команду «Аяна»"
        )

        startSherpaListening()
    }

    private fun startQuickCommandListening() {

        if (
            shuttingDown ||
            !modelReady
        ) {
            return
        }

        listenMode =
            ListenMode.QUICK_COMMAND

        voiceBackgroundCoordinator.enterQuickCommand(
            SystemClock.elapsedRealtime()
        )

        broadcastStatus(
            "Слушаю…",
            STATE_COMMAND
        )

        updateNotification(
            "Слушаю продолжение команды"
        )

        startSherpaListening()
    }

    private fun startFollowUpOrWake() {

        // A CANCEL listener may still own the microphone while AYANA is
        // speaking. End that stream first so the next wake/follow-up mode starts
        // with a clean recognizer stream rather than inheriting TTS audio.
        stopCancelListenerWatchdog()
        stopSherpaListening()

        mainHandler.postDelayed(
            {
                if (
                    !shuttingDown &&
                    isRunning
                ) {

                    val audioManager =
                        getSystemService(
                            Context.AUDIO_SERVICE
                        ) as? AudioManager

                    if (
                        audioManager?.isMusicActive == true
                    ) {
                        startWakeListening()
                    } else {
                        startFollowUpListening()
                    }
                }
            },
            CANCEL_MODE_TRANSITION_MS
        )
    }

    private fun startFollowUpListening() {

        if (
            shuttingDown ||
            !modelReady
        ) {
            return
        }

        listenMode =
            ListenMode.FOLLOW_UP

        val voiceSession =
            voiceBackgroundCoordinator.enterFollowUp(
                SystemClock.elapsedRealtime()
            )
        followUpVoiceSessionGeneration =
            voiceSession.generation

        broadcastStatus(
            "Можно продолжить без «Аяна»",
            STATE_COMMAND
        )

        updateNotification(
            "Слушаю продолжение"
        )

        val deadlineToken =
            ++followUpDeadlineToken

        startSherpaListening()

        // FOLLOW-UP OWNERSHIP v12.11
        // Main-looper deadline owns the absolute follow-up lifetime even when
        // recognizer noise or partial hypotheses prevent an endpoint.
        mainHandler.postDelayed(
            {
if (
                    !shuttingDown &&
                    deadlineToken ==
                    followUpDeadlineToken &&
                    listenMode ==
                    ListenMode.FOLLOW_UP &&
                    voiceBackgroundCoordinator.isCurrent(
                        followUpVoiceSessionGeneration,
                        AyanaVoiceBackgroundCoordinator.Mode.FOLLOW_UP
                    )
                ) {
                    followUpDeadlineToken++
                    stopSherpaListening()
                    startWakeListening()
                }
            },
            FOLLOW_UP_HARD_LIMIT_MS
        )
    }

    private fun startCancelListening() {

        if (
            shuttingDown ||
            !modelReady ||
            !isRunning
        ) {
            return
        }

        listenMode =
            ListenMode.CANCEL

        voiceBackgroundCoordinator.enterCancel(
            SystemClock.elapsedRealtime()
        )

        // Do not overwrite THINKING / EXECUTING / SPEAKING visual status.
        // Keep a tiny local listener alive only for STOP/full-shutdown phrases.
        startCancelListenerWatchdog()

        if (
            !isRecording
        ) {
            startSherpaListening()
        }
    }

    private fun startCancelListenerWatchdog() {

        mainHandler.removeCallbacks(
            cancelListenerWatchdog
        )

        mainHandler.post(
            cancelListenerWatchdog
        )
    }

    private fun stopCancelListenerWatchdog() {

        mainHandler.removeCallbacks(
            cancelListenerWatchdog
        )
    }

    private fun shouldKeepCancelListener():
        Boolean {

        return !shuttingDown &&
            isRunning &&
            !cancelRequested &&
            currentStatusState in
            setOf(
                STATE_THINKING,
                STATE_EXECUTING,
                STATE_SPEAKING
            )
    }

    private fun startCommandListening() {

        if (
            shuttingDown ||
            !modelReady
        ) {
            return
        }

        listenMode =
            ListenMode.COMMAND

        voiceBackgroundCoordinator.enterCommand(
            SystemClock.elapsedRealtime()
        )

        broadcastStatus(
            "Слушаю команду…",
            STATE_COMMAND
        )

        updateNotification(
            "Слушаю вашу команду"
        )

        startSherpaListening()
    }

    private fun startSherpaListening() {

        if (
            shuttingDown ||
            !modelReady
        ) {
            return
        }

        if (
            checkSelfPermission(
                Manifest.permission.RECORD_AUDIO
            ) !=
            PackageManager.PERMISSION_GRANTED
        ) {

            broadcastStatus(
                "Нет доступа к микрофону",
                STATE_ERROR
            )

            updateNotification(
                "Нужен доступ к микрофону"
            )

            return
        }

        if (
            recordingThread?.isAlive == true ||
            isRecording
        ) {

            mainHandler.postDelayed(
                {
                    if (
                        !shuttingDown &&
                        !isRecording
                    ) {
                        startSherpaListening()
                    }
                },
                160L
            )

            return
        }

        val minBufferBytes =
            AudioRecord.getMinBufferSize(
                sampleRateInHz,
                channelConfig,
                audioFormat
            )

        if (minBufferBytes <= 0) {

            broadcastStatus(
                "Не удалось открыть микрофон",
                STATE_ERROR
            )

            return
        }

        var recorder: AudioRecord? =
            null

        var selectedAudioSource =
            -1

        val cancelDuringSpeech =
            listenMode ==
                ListenMode.CANCEL &&
                currentStatusState ==
                STATE_SPEAKING

        val audioSources =
            if (
                cancelDuringSpeech
            ) {
                intArrayOf(
                    MediaRecorder.AudioSource.VOICE_COMMUNICATION,
                    MediaRecorder.AudioSource.VOICE_RECOGNITION,
                    MediaRecorder.AudioSource.MIC
                )
            } else {
                intArrayOf(
                    MediaRecorder.AudioSource.VOICE_RECOGNITION,
                    MediaRecorder.AudioSource.MIC
                )
            }

        for (source in audioSources) {

            val candidate =
                try {
                    AudioRecord(
                        source,
                        sampleRateInHz,
                        channelConfig,
                        audioFormat,
                        minBufferBytes * 2
                    )
                } catch (_: Exception) {
                    null
                }

            if (
                candidate != null &&
                candidate.state ==
                AudioRecord.STATE_INITIALIZED
            ) {
                recorder = candidate
                selectedAudioSource = source
                break
            }

            try {
                candidate?.release()
            } catch (_: Exception) {
            }
        }

        if (
            recorder == null ||
            recorder.state !=
            AudioRecord.STATE_INITIALIZED
        ) {

            try {
                recorder?.release()
            } catch (_: Exception) {
            }

            broadcastStatus(
                "Микрофон недоступен",
                STATE_ERROR
            )

            return
        }

        val activeRecorder =
            recorder
                ?: return

        audioRecord =
            activeRecorder

        configureCancelAudioEffects(
            activeRecorder,
            enabled =
                cancelDuringSpeech
        )

        try {

            activeRecorder.startRecording()

            isRecording =
                true

            if (
                cancelDuringSpeech &&
                !bargeInAudioDiagnosticLogged
            ) {
                bargeInAudioDiagnosticLogged =
                    true

                val audioManager =
                    getSystemService(
                        Context.AUDIO_SERVICE
                    ) as AudioManager

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "barge_in_audio",
                    message = "Аудиоканал STOP активирован",
                    details =
                        "source=${audioSourceName(selectedAudioSource)};" +
                            " mode=${audioManager.mode};" +
                            " aec=${cancelEchoCanceler?.enabled == true};" +
                            " ns=${cancelNoiseSuppressor?.enabled == true}"
                )
            }

        } catch (_: Exception) {

            try {
                activeRecorder.release()
            } catch (_: Exception) {
            }

            audioRecord =
                null

            releaseCancelAudioEffects()

            isRecording =
                false

            broadcastStatus(
                "Не удалось начать прослушивание",
                STATE_ERROR
            )

            return
        }

        val sessionGeneration =
            ++micGeneration

        recordingThread =
            thread(
                start = true,
                name = "AyanaSherpaAudio"
            ) {

                processSherpaAudio(
                    activeRecorder,
                    sessionGeneration
                )
            }
    }

    private fun processSherpaAudio(
        recorder: AudioRecord,
        sessionGeneration: Long
    ) {

        val localRecognizer =
            recognizer
                ?: return

        val stream =
            try {
                localRecognizer
                    .createStream()
            } catch (_: Exception) {
                cleanupRecorder(
                    recorder
                )
                return
            }

        val intervalSeconds =
            0.10

        val sampleCount =
            (
                intervalSeconds *
                    sampleRateInHz
                ).toInt()

        val buffer =
            ShortArray(
                sampleCount
            )

        var wakeSeen =
            false

        val modeStartedAt =
            SystemClock.elapsedRealtime()

        var speechSeen =
            false

        // Sherpa can wait several seconds for an endpoint even after a complete
        // phrase. Track when the partial transcript last changed so selected
        // direct local commands can commit earlier without waiting for endpoint.
        var lastRecognitionText =
            ""

        var recognitionChangedAt =
            modeStartedAt

        var pendingAction:
            (() -> Unit)? = null

        var lastCancelDiagnosticText =
            ""

        var lastCancelDiagnosticAt =
            0L

        try {

            while (
                isRecording &&
                !shuttingDown
            ) {

                val count =
                    try {
                        recorder.read(
                            buffer,
                            0,
                            buffer.size
                        )
                    } catch (_: Exception) {
                        -1
                    }

                if (count <= 0) {
                    continue
                }

                var peak =
                    0.0f

                for (index in 0 until count) {
                    val level =
                        abs(
                            buffer[index] /
                                32768.0f
                        )

                    if (level > peak) {
                        peak = level
                    }
                }

                // Wake sensitivity v2.7.4:
                // Keep true near-silence unamplified, but boost very quiet
                // speech more consistently. This improves distant/soft «Аяна»
                // without changing the recognizer model or microphone source.
                val inputGain =
                    if (
                        listenMode ==
                        ListenMode.CANCEL &&
                        currentStatusState ==
                        STATE_SPEAKING
                    ) {

                        when {
                            peak < 0.00035f ->
                                1.0f

                            peak < 0.008f ->
                                5.8f

                            peak < 0.025f ->
                                4.4f

                            peak < 0.060f ->
                                3.0f

                            peak < 0.120f ->
                                1.9f

                            else ->
                                1.25f
                        }

                    } else {

                        when {
                            peak < 0.00035f ->
                                1.0f

                            peak < 0.0040f ->
                                5.5f

                            peak < 0.012f ->
                                4.8f

                            peak < 0.030f ->
                                3.5f

                            peak < 0.060f ->
                                2.4f

                            peak < 0.100f ->
                                1.7f

                            peak < 0.150f ->
                                1.25f

                            else ->
                                1.0f
                        }
                    }

                val samples =
                    FloatArray(count) {
                        (
                            buffer[it] /
                                32768.0f *
                                inputGain
                            )
                            .coerceIn(
                                -1.0f,
                                1.0f
                            )
                    }

                stream.acceptWaveform(
                    samples,
                    sampleRate =
                        sampleRateInHz
                )

                while (
                    localRecognizer
.isReady(stream)
                ) {

                    localRecognizer
                        .decode(stream)
                }

                val text =
                    normalizeRecognitionText(
                        localRecognizer
                            .getResult(stream)
                            .text
                    )

                if (text != lastRecognitionText) {
                    lastRecognitionText =
                        text
                    recognitionChangedAt =
                        SystemClock.elapsedRealtime()
                }

                if (
                    (
                        listenMode ==
                        ListenMode.QUICK_COMMAND ||
                        listenMode ==
                        ListenMode.FOLLOW_UP
                    ) &&
                    text.isNotBlank()
                ) {
                    speechSeen = true
                }

                val isEndpoint =
                    localRecognizer
                        .isEndpoint(stream)

                when (listenMode) {

                    ListenMode.WAKE -> {

                        if (
                            text.isNotBlank() &&
                            containsWakeWord(text)
                        ) {

                            wakeSeen = true

                            broadcastStatus(
                                "Слышу «Аяна»…",
                                STATE_COMMAND
                            )
                        }

                        // Fast local commit: once a complete direct-settings
                        // phrase has been stable briefly, execute it without
                        // waiting for Sherpa's slower endpoint. We deliberately
                        // exclude the generic settings page to avoid cutting off
                        // a user who pauses after «открой настройки…».
                        if (
                            !isEndpoint &&
                            wakeSeen &&
                            text.isNotBlank() &&
                            SystemClock.elapsedRealtime() -
                                recognitionChangedAt >=
                            FAST_LOCAL_PARTIAL_COMMIT_MS
                        ) {

                            val earlyCommand =
                                extractWakeCommand(
                                    text
                                )

                            val earlySection =
                                extractDirectSystemSettingsSection(
                                    earlyCommand
                                )

                            val earlyAppSettingsTarget =
                                extractSettingsAppSearchTarget(
                                    earlyCommand
                                )

                            val earlyMultiStep =
                                isMultiStepAgentCommand(
                                    earlyCommand
                                )

                            // ACCESSIBILITY PARTIAL GUARD v2.7.4.5
                            // Do not commit Accessibility from a partial transcript:
                            // the user may continue with «найди AYANA AI…». Waiting
                            // for the endpoint is slightly slower for the single-step
                            // Accessibility command, but prevents cutting off a real
                            // multi-step goal before Planner receives it.
                            if (
                                !earlyMultiStep &&
                                (
                                    earlyAppSettingsTarget != null ||
                                    (
                                        earlySection != null &&
                                        earlySection != "general" &&
                                        earlySection != "accessibility"
                                    )
                                )
                            ) {

                                wakeSeen =
                                    false

                                isRecording =
                                    false

                                pendingAction =
                                    {
                                        executeCommand(
                                            earlyCommand,
                                            silent = false
                                        )
                                    }

                                break
                            }
                        }

                        if (isEndpoint) {

                            val finalText =
                                text

                            val detected =
                                wakeSeen ||
                                    containsWakeWord(
                                        finalText
                                    )

                            if (detected) {

                                wakeSeen =
                                    false

                                val command =
                                    extractWakeCommand(
                                        finalText
                                    )

                                isRecording =
                                    false

                                pendingAction =
                                    if (
                                        command.isBlank()
                                    ) {

                                        {
                                            startQuickCommandListening()
                                        }

                                    } else {

                                        {
                                            executeCommand(
                                                command,
                                                silent = false
                                            )
                                        }
                                    }

                                break

                            } else {

                                wakeSeen =
                                    false

                                localRecognizer
                                    .reset(stream)
                            }
                        }
                    }

                    ListenMode.QUICK_COMMAND -> {

                        if (isEndpoint) {

                            val finalText =
                                text

                            if (finalText.isNotBlank()) {

                                isRecording =
                                    false

                                pendingAction =
                                    {
                                        executeCommand(
                                            finalText,
                                            silent = false
                                        )
                                    }

                                break

                            } else {

                                localRecognizer
                                    .reset(stream)
                            }
                        }

                        if (
                            !speechSeen &&
                            SystemClock.elapsedRealtime() -
                                modeStartedAt >=
                            QUICK_COMMAND_GRACE_MS
                        ) {

                            isRecording =
                                false

                            pendingAction =
                                {
                                    acknowledgeWakeAndListen()
                                }

                            break
                        }
                    }

                    ListenMode.FOLLOW_UP -> {

                        if (isEndpoint) {

                            val finalText =
                                text

                            val followUpCommand =
                                if (
                                    containsWakeWord(
                                        finalText
                                    )
                                ) {
                                    extractWakeCommand(
                                        finalText
                                    )
                                } else {
                                    finalText
                                }

                            if (followUpCommand.isNotBlank()) {

                                isRecording =
                                    false

                                pendingAction =
                                    {
                                        executeCommand(
                                            followUpCommand,
                                            silent = false
                                        )
                                    }

                                break

                            } else if (
                                finalText.isNotBlank() &&
                                containsWakeWord(
                                    finalText
                                )
                            ) {

                                isRecording =
                                    false

                                pendingAction =
                                    {
                                        acknowledgeWakeAndListen()
                                    }

                                break

                            } else {

                                localRecognizer
                                    .reset(stream)
                            }
                        }

                        val followUpNow =
                            SystemClock.elapsedRealtime()

                        val followUpDecision =
                            voiceBackgroundCoordinator.evaluateFollowUp(
                                sessionGeneration = followUpVoiceSessionGeneration,
                                speechSeen = speechSeen,
                                recognitionChangedAtMs = recognitionChangedAt,
                                nowMs = followUpNow
                            )

                        if (
                            followUpDecision.shouldReturnToWake
                        ) {

                            isRecording =
                                false

                            pendingAction =
                                {
                                    startWakeListening()
                                }

                            break
                        }
                    }

                    ListenMode.COMMAND -> {

                        if (isEndpoint) {

                            val finalText =
                                text

                            if (
                                finalText.isNotBlank()
                            ) {

                                isRecording =
                                    false

                                pendingAction =
                                    {
                                        executeCommand(
                                            finalText,
                                            silent = false
                                        )
                                    }

                                break

                            } else {

                                localRecognizer
                                    .reset(stream)
                            }
                        }
                    }

                    ListenMode.CANCEL -> {

                        if (
                            currentStatusState in
                            setOf(
                                STATE_THINKING,
                                STATE_EXECUTING,
                                STATE_SPEAKING
                            ) &&
                            text.isNotBlank() &&
                            text !=
                            lastCancelDiagnosticText &&
                            (
                                isEndpoint ||
                                SystemClock.elapsedRealtime() -
                                    lastCancelDiagnosticAt >=
                                CANCEL_DIAGNOSTIC_INTERVAL_MS
                            )
                        ) {
                            lastCancelDiagnosticText =
                                text

                            lastCancelDiagnosticAt =
                                SystemClock.elapsedRealtime()

                            commandHistoryStore.addEvent(
                                activeCommandHistoryId,
                                state = "cancel_heard",
message = text.take(
                                    220
                                )
                            )
                        }

                        if (
                            text.isNotBlank() &&
                            isShutdownAyanaPhrase(
                                text
                            )
                        ) {

                            isRecording =
                                false

                            pendingAction =
                                {
                                    shutdownAyana()
                                }

                            break
                        }

                        val cancelMatch =
                            if (text.isNotBlank()) {
                                cancelPhraseDetector.detect(
                                    value = text,
                                    speaking =
                                        currentStatusState ==
                                            STATE_SPEAKING,
                                    activeSpokenText =
                                        activeTtsTextNormalized
                                )
                            } else {
                                AyanaCancelPhraseDetector.Match(
                                    matched = false
                                )
                            }

                        if (cancelMatch.matched) {

                            commandHistoryStore.addEvent(
                                activeCommandHistoryId,
                                state = "cancel_match",
                                message = "STOP распознан локальным детектором",
                                details =
                                    (
                                        "reason=${cancelMatch.reason}; " +
                                            "token=${cancelMatch.token}; " +
                                            "speaking=${currentStatusState == STATE_SPEAKING}; " +
                                            "heard=${cancelMatch.normalized.take(160)}"
                                        ).take(420)
                            )

                            isRecording =
                                false

                            pendingAction =
                                {
                                    cancelCurrentCommand(
                                        source = "voice"
                                    )
                                }

                            break
                        }

                        if (
                            isEndpoint
                        ) {

                            localRecognizer.reset(
                                stream
                            )
                        }
                    }

                    ListenMode.BUSY -> {

                        isRecording =
                            false

                        break
                    }
                }
            }

        } catch (_: Exception) {

            if (
                !shuttingDown &&
                sessionGeneration ==
                micGeneration
            ) {

                pendingAction =
                    when (listenMode) {

                        ListenMode.WAKE -> {

                            if (wakeSeen) {

                                {
                                    acknowledgeWakeAndListen()
                                }

                            } else {
{
                                    broadcastStatus(
                                        "Перезапускаю микрофон…",
                                        STATE_THINKING
                                    )

                                    mainHandler.postDelayed(
                                        {
                                            startWakeListening()
                                        },
                                        900L
                                    )
                                }
                            }
                        }

                        ListenMode.QUICK_COMMAND -> {

                            {
                                acknowledgeWakeAndListen()
                            }
                        }

                        ListenMode.COMMAND -> {

                            {
                                broadcastStatus(
                                    "Перезапускаю микрофон…",
                                    STATE_THINKING
                                )

                                mainHandler.postDelayed(
                                    {
                                        startCommandListening()
                                    },
                                    900L
                                )
                            }
                        }

                        ListenMode.FOLLOW_UP -> {

                            {
                                mainHandler.postDelayed(
                                    {
                                        startWakeListening()
                                    },
                                    500L
                                )
                            }
                        }

                        ListenMode.CANCEL -> {

                            if (
                                activeCommandHistoryId !=
                                null &&
                                !cancelRequested
                            ) {
                                {
                                    mainHandler.postDelayed(
                                        {
                                            startCancelListening()
                                        },
                                        250L
                                    )
                                }
                            } else {
                                null
                            }
                        }

                        ListenMode.BUSY ->
                            null
                    }
            }

        } finally {

            try {
                stream.release()
            } catch (_: Exception) {
            }

            cleanupRecorder(
                recorder
            )

            val action =
                pendingAction

            if (
                action != null &&
                !shuttingDown &&
                sessionGeneration ==
                micGeneration
            ) {

                mainHandler.post(
                    action
                )
            }
        }
    }

    private fun cleanupRecorder(
        recorder: AudioRecord
    ) {

        try {

            if (
                recorder.recordingState ==
                AudioRecord.RECORDSTATE_RECORDING
            ) {
                recorder.stop()
            }

        } catch (_: Exception) {
        }

        try {
            recorder.release()
        } catch (_: Exception) {
        }

        if (
            audioRecord === recorder
        ) {

            releaseCancelAudioEffects()

            audioRecord =
                null
        }

        isRecording =
            false

        if (
            Thread.currentThread() ===
            recordingThread
        ) {
            recordingThread =
                null
        }
    }

    private fun configureCancelAudioEffects(
        recorder: AudioRecord,
        enabled: Boolean
    ) {

        releaseCancelAudioEffects()

        if (
            !enabled
        ) {
            return
        }

        try {

            if (
                AcousticEchoCanceler.isAvailable()
            ) {

                cancelEchoCanceler =
                    AcousticEchoCanceler.create(
                        recorder.audioSessionId
                    )
                        ?.apply {
                            this.enabled =
                                true
                        }
            }

        } catch (_: Exception) {

            cancelEchoCanceler =
                null
        }

        try {

            if (
                NoiseSuppressor.isAvailable()
            ) {

                cancelNoiseSuppressor =
                    NoiseSuppressor.create(
                        recorder.audioSessionId
                    )
                        ?.apply {
                            this.enabled =
                                true
                        }
            }

        } catch (_: Exception) {

            cancelNoiseSuppressor =
                null
        }
    }

    private fun releaseCancelAudioEffects() {

        try {
            cancelEchoCanceler
                ?.release()
        } catch (_: Exception) {
        }

        try {
            cancelNoiseSuppressor
                ?.release()
        } catch (_: Exception) {
        }

        cancelEchoCanceler =
            null

        cancelNoiseSuppressor =
            null
    }

    private fun stopSherpaListening() {

        // Invalidate the old recording loop before stopping AudioRecord. Any
        // catch/finally from that obsolete loop must NOT restart WAKE and steal
        // the microphone from the dedicated CANCEL listener.
        micGeneration++

        isRecording =
            false

        val recorder =
            audioRecord

        if (recorder != null) {

            try {

                if (
                    recorder.recordingState ==
                    AudioRecord.RECORDSTATE_RECORDING
                ) {
                    recorder.stop()
                }

            } catch (_: Exception) {
            }
        }
    }

    private fun resumeCurrentListeningMode() {

        if (
            shuttingDown ||
            !modelReady
        ) {
            return
        }

        when (listenMode) {

            ListenMode.WAKE ->
                startWakeListening()

            ListenMode.QUICK_COMMAND ->
                startQuickCommandListening()

            ListenMode.COMMAND ->
                startCommandListening()

            ListenMode.FOLLOW_UP ->
                startFollowUpListening()

            ListenMode.CANCEL ->
                startCancelListening()

            ListenMode.BUSY ->
                Unit
        }
    }

    private fun normalizeRecognitionText(
        text: String
    ): String {

        return text
            .lowercase(
                Locale.getDefault()
            )
            .replace('ё', 'е')
            .replace(
                Regex("[,!?;:.]"),
                " "
            )
            .replace(
                Regex("\\s+"),
                " "
            )
            .trim()
    }

    private fun containsWakeWord(
        text: String
    ): Boolean {

        val normalized =
            normalizeRecognitionText(
                text
            )

        if (
            WAKE_VARIANTS.any {
                normalized.contains(it)
            }
        ) {
            return true
        }

        // The local STT occasionally returns a one-letter phonetic miss for
        // «Аяна» (for example «айна»/«яна»). Accept a fuzzy match only at
        // the beginning of the utterance, where a wake word belongs.
        return fuzzyWakePrefixLength(
            normalized
        ) > 0
    }

    private fun fuzzyWakePrefixLength(
        normalized: String
    ): Int {

        if (normalized.isBlank()) {
            return 0
        }

        val firstSpace =
            normalized.indexOf(' ')

        val firstToken =
            if (firstSpace >= 0) {
                normalized.substring(0, firstSpace)
            } else {
                normalized
            }

        if (isWakeLikeToken(firstToken)) {
            return firstToken.length
        }

        // Also support split recognition such as «а яна».
        if (firstSpace > 0) {
            val secondSpace =
                normalized.indexOf(
                    ' ',
                    firstSpace + 1
                )

            val prefixEnd =
                if (secondSpace >= 0) {
                    secondSpace
                } else {
                    normalized.length
                }

            val compactTwo =
                normalized
                    .substring(0, prefixEnd)
                    .replace(" ", "")

            if (isWakeLikeToken(compactTwo)) {
                return prefixEnd
            }
        }

        return 0
    }

    private fun isWakeLikeToken(
        token: String
    ): Boolean {

        if (token.length !in 3..6) {
            return false
        }

        val compactTargets =
            listOf(
                "аяна",
                "айана",
                "айяна",
                "ayana"
            )

        return compactTargets.any { target ->
            editDistanceAtMostOne(
                token,
                target
            )
        }
    }

    private fun editDistanceAtMostOne(
        left: String,
        right: String
    ): Boolean {

        if (left == right) {
            return true
        }

        val lengthDiff =
            kotlin.math.abs(
                left.length -
                    right.length
            )

        if (lengthDiff > 1) {
            return false
        }

        var i = 0
        var j = 0
        var edits = 0

        while (
            i < left.length &&
            j < right.length
        ) {

            if (left[i] == right[j]) {
                i++
                j++
                continue
            }

            edits++
            if (edits > 1) {
                return false
            }

            when {
                left.length > right.length ->
                    i++

                right.length > left.length ->
                    j++

                else -> {
                    i++
                    j++
                }
            }
        }

        if (
            i < left.length ||
            j < right.length
        ) {
            edits++
        }

        return edits <= 1
    }

    private fun extractWakeCommand(
        phrase: String
    ): String {

        var normalized =
            normalizeRecognitionText(
                phrase
            )

        // If exact variants did not survive STT but the first token is a
        // one-edit phonetic match, strip that fuzzy wake prefix too.
        val fuzzyPrefixLength =
            fuzzyWakePrefixLength(
                normalized
            )

        if (
            fuzzyPrefixLength > 0 &&
            !WAKE_VARIANTS.any {
                normalized.startsWith(it)
            }
        ) {
            normalized =
                normalized
                    .substring(
                        fuzzyPrefixLength
                    )
                    .trim()
                    .trimStart(
                        '-',
                        '—'
                    )
                    .trim()
}

        var found =
            false

        do {

            found =
                false

            for (
                wake in
                WAKE_VARIANTS
            ) {

                val index =
                    normalized
                        .indexOf(wake)

                if (index >= 0) {

                    normalized =
                        normalized
                            .substring(
                                index +
                                    wake.length
                            )
                            .trim()
                            .trimStart(
                                '-',
                                '—'
                            )
                            .trim()

                    found =
                        true

                    break
                }
            }

        } while (
            found &&
            WAKE_VARIANTS.any {
                normalized
                    .startsWith(it)
            }
        )

        return normalized
            .trim()
    }

    // =========================================================
    // WAKE ACKNOWLEDGEMENT
    // =========================================================

    private fun prefetchReadyVoice() {

        if (
            readyFile.exists() &&
            readyFile.length() > 1000
        ) {
            return
        }

        thread(
            start = true,
            name = "AyanaReadyVoice"
        ) {
            try {

                downloadTtsToFile(
                    "Да?",
                    readyFile
                )

            } catch (_: Exception) {
            }
        }
    }

    private fun acknowledgeWakeAndListen() {

        stopSherpaListening()

        listenMode =
            ListenMode.BUSY

        broadcastStatus(
            "Аяна услышала вас",
            STATE_COMMAND
        )

        if (
            readyFile.exists() &&
            readyFile.length() > 1000
        ) {

            playFile(
                readyFile,
                deleteAfter = false
            ) {
                startFollowUpListening()
            }

        } else {

            try {

                val tone =
                    ToneGenerator(
                        AudioManager.STREAM_MUSIC,
                        65
                    )

                tone.startTone(
                    ToneGenerator.TONE_PROP_ACK,
                    110
                )

                mainHandler.postDelayed(
                    {
                        try {
                            tone.release()
                        } catch (_: Exception) {
                        }
                    },
                    160L
                )

            } catch (_: Exception) {
            }

            mainHandler.postDelayed(
                {
                    startFollowUpListening()
                },
                190L
            )
        }
    }

    // =========================================================
    // COMMANDS
    // =========================================================

    private fun executeCommand(
        originalCommand: String,
        silent: Boolean
    ) {

        // v12.9.0 MAIN-THREAD EXECUTION ISOLATION.
        // Voice endpoint and text-mode entrypoints both arrive through mainHandler.
        // Re-enter this same method from a serialized worker so deterministic routes
        // containing polling/sleeps/Accessibility IPC cannot trigger an Android ANR.
        if (Looper.myLooper() == Looper.getMainLooper()) {
            val commandSnapshot =
                originalCommand

            thread(
                start = true,
                name = "AyanaCommandRouter"
            ) {
                synchronized(
                    commandDispatchLock
                ) {
                    if (!shuttingDown) {
                        executeCommand(
                            originalCommand = commandSnapshot,
                            silent = silent
                        )
                    }
                }
            }
            return
        }

        stopSherpaListening()

        listenMode =
            ListenMode.BUSY

        voiceBackgroundCoordinator.enterBusy(
            SystemClock.elapsedRealtime()
        )

        val normalized =
            sanitizeRoutingEnvelope(
                normalizeRecognitionText(
                    originalCommand
                )
                    .replace(
                        "пожалуйста",
                        ""
                    )
                    .replace(
                        Regex("\\s+"),
                        " "
                    )
                    .trim()
            )

        if (normalized.isBlank()) {

            if (silent) {
                showTextAndResume(
                    "Команда пустая."
                )
            } else {
                startWakeListening()
            }

            return
        }

        // R10.23: a recognizer/endpoint race must never execute the same VOICE command
        // twice. Text mode remains unaffected, and the dedupe window is intentionally
        // short so a deliberate later repetition is treated as a new command.
        if (!silent) {
            val dispatchClaim =
                voiceBackgroundCoordinator.claimVoiceDispatch(
                    command = normalized,
                    nowMs = SystemClock.elapsedRealtime()
                )

            if (!dispatchClaim.allowed) {
                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "voice_duplicate_dispatch_suppressed",
                    message = "Повторный voice-dispatch подавлен до выполнения действия",
                    details =
                        "reason=${dispatchClaim.reason}; fingerprint=${dispatchClaim.fingerprint}; " +
                            "window_ms=${AyanaVoiceBackgroundCoordinator.DEFAULT_DUPLICATE_VOICE_DISPATCH_WINDOW_MS}"
                )
                mainHandler.post {
                    if (!shuttingDown && isRunning) {
                        startFollowUpListening()
                    }
                }
                return
            }
        }

        // ROUTING REPAIR v9.0
        // Never rewrite the user's stored/original command. Only the deterministic
        // local router receives a conservative repaired form for known Sherpa
        // distortions observed on the target tablet.
        val routingNormalized =
            sanitizeRoutingEnvelope(
                repairCommonRecognitionForRouting(
                    normalized
                )
            )

        if (
            handlePendingPreExecutionConfirmationInput(
                originalCommand = originalCommand,
                silent = silent
            )
        ) {
            return
        }

        if (
            isShutdownAyanaPhrase(
                normalized
            )
        ) {
            shutdownAyana()
            return
        }

        if (
            isCancelCommandPhrase(
                normalized
            ) &&
            !isDurableGoalCancelPhrase(
                routingNormalized
            )
        ) {

            if (
                activeCommandHistoryId !=
                null
            ) {
                cancelCurrentCommand(
                    source =
                        if (
                            silent
                        ) {
                            "text"
                        } else {
                            "voice"
                        }
                )
            } else {
                startWakeListening()
            }

            return
        }

        if (
            isLocalOrbControlCommand(
                normalized
            )
        ) {

            cancelRequested =
                false

            activeCommandToken =
                ++commandGeneration

            activeCommandHistoryId =
                commandHistoryStore.begin(
                    command =
                        originalCommand,
                    source =
                        if (
                            silent
                        ) {
                            "text"
                        } else {
                            "voice"
                        }
                )

            beginExecutionSession(
                objective = originalCommand,
                source = if (silent) "text" else "voice",
                lane = "local_control",
                executor = "orb_control_executor"
            )

            broadcastStatus(
                "Настраиваю Orb AYANA…",
                STATE_EXECUTING
            )

            ayanaPreferences.miniOrbEnabled =
                true

            if (
                miniOrbController.canDrawOverlays()
            ) {

                miniOrbController.refresh(
                    enabled = true,
                    state =
                        STATE_LISTENING
                )

                finishLocalCommand(
                    "Orb AYANA активен поверх всех окон",
                    silent
                )

            } else {

                respondAndResume(
                    "Для Orb нужно разрешение «Поверх других приложений».",
                    silent,
                    success = false
                )
            }

            return
        }

        cancelRequested =
            false

        activeCommandToken =
            ++commandGeneration

        activeCommandHistoryId =
            commandHistoryStore.begin(
                command = originalCommand,
                source = if (silent) "text" else "voice"
            )

        beginExecutionSession(
            objective = originalCommand,
            source = if (silent) "text" else "voice",
            lane = "command_router",
            executor = "deterministic_router"
        )

        capabilityRegistry
            .recordCommandContext(
                source =
                    if (silent) {
                        "text"
                    } else {
                        "voice"
                    },
                ttsExpected =
                    !silent
            )

        broadcastStatus(
            if (silent) {
                "Текст: $originalCommand"
            } else {
                "Выполняю: $originalCommand"
            },
            STATE_THINKING
        )

        if (
            isDurableGoalStatusPhrase(
                routingNormalized
            )
        ) {
            showDurableGoalStatus(
                silent
            )
            return
        }
if (
            isDurableGoalCancelPhrase(
                routingNormalized
            )
        ) {
            cancelDurableGoalFromControl(
                silent
            )
            return
        }

        if (
            isDurableGoalConfirmPhrase(
                routingNormalized
            )
        ) {
            resumeDurableGoal(
                silent = silent,
                explicitConfirmation = true,
                allowAutoResume = false
            )
            return
        }

        if (
            isPreviousDurableGoalResumePhrase(
                routingNormalized
            )
        ) {
            val selected =
                durableGoalStore
                    .selectPreviousRecoverable()
            if (selected == null) {
                respondAndResume(
                    "Предыдущей незавершённой цели нет.",
                    silent,
                    success = false
                )
            } else {
                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "goal_selected",
                    message = "Выбрана предыдущая сохранённая цель",
                    details = selected.optString("command").take(500)
                )
                resumeDurableGoal(
                    silent = silent,
                    explicitConfirmation = false,
                    allowAutoResume = false
                )
            }
            return
        }

        if (
            isDurableGoalResumePhrase(
                routingNormalized
            )
        ) {
            resumeDurableGoal(
                silent = silent,
                explicitConfirmation = false,
                allowAutoResume = false
            )
            return
        }

        if (confirmedPreExecutionOriginal.isNotBlank()) {
            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "confirmation_granted",
                message = "Пользователь подтвердил ожидающее действие",
                details = confirmedPreExecutionOriginal.take(500)
            )
            confirmedPreExecutionOriginal =
                ""
        }

        // R10.0 BOUNDED CONTROLLED PROACTIVITY ROUTING.
        // R10.0 UNIFIED SCREEN INTELLIGENCE acceptance owns foreground truth before
        // any ordinary app-control route. It is read-only apart from bounded app opens
        // and always restores AYANA; no persistent mutation is authorized.
        if (
            isUnifiedScreenIntelligenceAcceptanceCommand(
                originalCommand
            )
        ) {
            runUnifiedScreenIntelligenceAcceptance(
                silent = silent
            )
            return
        }

        // These local commands only manage an explicit notification-only battery
        // rule or run its bounded acceptance. They do not grant mutation authority.
        if (
            isBatteryProactivityAcceptanceCommand(
                originalCommand
            )
        ) {
            runBatteryProactivityAcceptance(
                silent = silent
            )
            return
        }

        if (
            isBatteryProactivityEnableCommand(
originalCommand
            )
        ) {
            runBatteryProactivityEnable(
                command = originalCommand,
                silent = silent
            )
            return
        }

        if (
            isBatteryProactivityDisableCommand(
                originalCommand
            )
        ) {
            runBatteryProactivityDisable(
                silent = silent
            )
            return
        }

        if (
            isBatteryProactivityStatusCommand(
                originalCommand
            )
        ) {
            runBatteryProactivityStatus(
                silent = silent
            )
            return
        }

        // R9.9 VERIFIED UNDO PRECEDENCE. Durable-goal cancel/resume phrases were
        // resolved above. The undo executor has its own current-state guard and
        // read-back verification, so generic multi-step/action classifiers cannot
        // reinterpret a bounded rollback command before it reaches that contract.
        if (
            isUndoLastReversibleActionCommand(
                originalCommand
            )
        ) {
            runLocalUndoLastReversibleAction(
                silent = silent
            )
            return
        }

        if (
            isReversibleActionJournalStatusCommand(
                originalCommand
            )
        ) {
            runLocalReversibleActionJournalStatus(
                silent = silent
            )
            return
        }

        if (
            isReversibleBrightnessUndoAcceptanceCommand(
                originalCommand
            )
        ) {
            runLocalReversibleBrightnessUndoAcceptance(
                silent = silent
            )
            return
        }

        if (
            isReversibleActionJournalAcceptanceCommand(
                originalCommand
            )
        ) {
            runLocalReversibleActionJournalAcceptance(
                silent = silent
            )
            return
        }

        // v12.11.2 UNIVERSAL PRE-EXECUTION GOAL GATE.
        // This is evaluated before any local executor. Data-only/quoted commands
        // terminate without dispatch; all other gated goals still pass Safety
        // before their executable clauses are preflighted.
        val rawPreExecutionDecision =
            AyanaCompositeIntentGate
                .analyze(
                    originalCommand
                )

        val constraintOverride =
            confirmedPreExecutionConstraints

        confirmedPreExecutionConstraints =
            null

        val preExecutionDecision =
            if (
                constraintOverride != null &&
                (
                    constraintOverride.forbidSettings ||
                    constraintOverride.forbidNetwork
                ) &&
                rawPreExecutionDecision.type ==
                    AyanaCompositeIntentGate.DecisionType.PASS_THROUGH
            ) {
                AyanaCompositeIntentGate.Decision(
                    type =
                        AyanaCompositeIntentGate.DecisionType.ENVIRONMENT_CONSTRAINED,
                    original = originalCommand,
                    executableCommand = originalCommand,
                    constraints = constraintOverride,
                    reason = "confirmed_constraint_continuation"
                )
            } else {
                rawPreExecutionDecision
            }

        if (
            preExecutionDecision.type ==
            AyanaCompositeIntentGate.DecisionType.DATA_ONLY
        ) {
            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "pre_execution_data_only",
                message = "Исполняемая фраза распознана только как данные",
                details = preExecutionDecision.reason.take(240)
            )
            finishLocalCommand(
                "Фраза принята только как данные. Действия на устройстве не выполнялись.",
                silent
            )
            return
        }

        // AUTONOMOUS CORE v10.2 — command-level local Safety gate.
        // Explicit attempts to type credentials are rejected BEFORE Agent Core,
        // so the protection remains effective even if Worker/model routing changes.
        val commandSafetyDecision =
            try {
                safetyPolicy
                    .evaluateUserCommand(
                        originalCommand
                    )
            } catch (_: Exception) {
                AyanaSafetyPolicy.Decision(
                    allowed = false,
                    requiresConfirmation = false,
                    riskLevel = AyanaSafetyPolicy.RISK_PROHIBITED,
                    riskName = "policy_error",
                    reason = "Локальный Safety Engine не смог надёжно проверить команду ввода."
                )
            }

        if (
            !commandSafetyDecision.allowed
        ) {
            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "safety_gate",
                message = commandSafetyDecision.riskName,
                details = commandSafetyDecision.reason.take(260)
            )

            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "safety_blocked",
                message = "Команда заблокирована локальным Safety Engine",
                details = "risk=${commandSafetyDecision.riskLevel}"
            )

            respondBlockedAndResume(
                text = commandSafetyDecision.reason,
                silent = silent,
                technical =
                    "local_command_safety_blocked:" +
                        commandSafetyDecision.riskName
            )
            return
        }

        // R10.27.1 GitHub App setup/status stays deterministic and local. Client ID is
        // public metadata; access/refresh tokens are never accepted as command text.
        if (
            runLocalGitHubSetupOrStatusIfMatched(
                originalCommand = originalCommand,
                routingNormalized = routingNormalized,
                silent = silent
            )
        ) {
            return
        }

        // v12.14 NEGATIVE CAPABILITY TERMINAL TRUTH.
        // Known unavailable execution lanes fail locally as UNSUPPORTED instead of
        // spending an Agent Core turn and then recording a natural-language refusal
        // as SUCCESS. Source/patch generation remains supported and is not blocked.
        unsupportedExecutionCapabilityReason(
            originalCommand
        )
            ?.let { reason ->
                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "capability_execution_unsupported",
                    message = "Запрошен отсутствующий execution capability",
                    details = originalCommand.take(600)
                )
                respondUnsupportedAndResume(
                    text = reason,
                    silent = silent,
                    technical = "known_execution_capability_unavailable"
                )
                return
            }

        // v12.14 WHOLE-GOAL ROUTING GUARDS.
        // These are evaluated after Safety but before generic composite/local fast paths.
        // Their purpose is not to "special-case" brands; it is to preserve the user's
        // full terminal criterion when one clause would otherwise greedily consume it.
        extractVerifiedAppOpenRequest(
            originalCommand
        )
            ?.let { request ->
                val launchResolution =
                    try {
                        appResolver.resolve(request.first)
                    } catch (_: Exception) {
                        null
                    }

                val verificationResolution =
                    request.second
                        ?.takeIf { it.isNotBlank() }
                        ?.let { verifyName ->
                            try {
                                appResolver.resolve(verifyName)
                            } catch (_: Exception) {
                                null
                            }
                        }

                val sameTarget =
                    verificationResolution == null ||
                        (
                            launchResolution != null &&
                                launchResolution.success &&
                                verificationResolution.success &&
                                launchResolution.packageName.isNotBlank() &&
                                launchResolution.packageName == verificationResolution.packageName
                            )

                val wholeGoalCollapseAllowed =
                    sameTarget &&
                        preExecutionDecision.type !in
                            setOf(
                                AyanaCompositeIntentGate.DecisionType.DATA_ONLY,
                                AyanaCompositeIntentGate.DecisionType.INVALID,
                                AyanaCompositeIntentGate.DecisionType.REQUIRE_CONFIRMATION,
                                AyanaCompositeIntentGate.DecisionType.CONDITIONAL
                            ) &&
                        !preExecutionDecision.constraints.forbidNetwork &&
                        !(
                            preExecutionDecision.constraints.forbidSettings &&
                                launchResolution?.packageName == "com.android.settings"
                            )

                if (wholeGoalCollapseAllowed) {
                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state = "whole_goal_lifecycle_verification",
                        message = "App launch + foreground verification collapsed to one verified lifecycle goal",
                        details =
                            "app=${request.first.take(160)}; verify=${request.second.orEmpty().take(160)}"
                    )
                    clearPendingLifecycleContext()
                    handleLocalAppLifecycleRequest(
                        action = "open",
                        requestedName = request.first,
                        silent = silent
                    )
                    return
                }
            }

        extractCompositeAppDetailFinalGoal(
            originalCommand
        )
            ?.takeIf {
                preExecutionDecision.type !in
                    setOf(
                        AyanaCompositeIntentGate.DecisionType.DATA_ONLY,
                        AyanaCompositeIntentGate.DecisionType.INVALID,
                        AyanaCompositeIntentGate.DecisionType.REQUIRE_CONFIRMATION,
                        AyanaCompositeIntentGate.DecisionType.CONDITIONAL
                    ) &&
                    !preExecutionDecision.constraints.forbidSettings
            }
            ?.let { goal ->
                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "whole_goal_app_detail",
                    message = "Составной Settings-маршрут свёрнут к конечной проверяемой цели",
                    details =
                        "app=${goal.appName.take(180)}; section=${goal.section}"
                )

                val result =
                    agentOpenAppSettings(
                        requestedName = goal.appName,
                        section = goal.section
                    )

                val message =
                    result.optString(
                        "message",
                        if (result.optBoolean("success", false)) {
                            "Открыт запрошенный раздел приложения ${goal.appName}."
                        } else {
                            "Не удалось подтвердить запрошенный раздел приложения ${goal.appName}."
                        }
                    )

                if (
                    result.optBoolean("success", false) &&
                    result.optBoolean("verified", true)
                ) {
                    finishLocalCommand(
                        message,
                        silent
                    )
                } else {
                    respondAndResume(
                        text = message,
                        silent = silent,
                        success = false,
                        terminalStatus =
                            when (result.optString("terminal_status").uppercase(Locale.ROOT)) {
                                "BLOCKED" -> AyanaCommandHistoryStore.STATUS_BLOCKED
                                "UNSUPPORTED" -> AyanaCommandHistoryStore.STATUS_UNSUPPORTED
                                else -> null
                            },
                        technical =
                            "whole_goal_app_detail_unverified:${result.optString("reason", result.optString("status"))}"
                    )
                }
                return
            }


        // R10.24 FIELD HARDENING — verified reversible brightness round-trip.
        // A phrase such as «запомни текущую яркость, установи 20%, проверь, отмени и проверь»
        // is one whole goal. It must never be collapsed into MemoryRemember merely because the
        // first verb is «запомни». This route reads the original state, performs one bounded
        // mutation, verifies it, records undo provenance, restores and verifies the original.
        extractBrightnessVerifiedRoundTripTarget(originalCommand)
            ?.let { targetPercent ->
                runLocalBrightnessVerifiedRoundTrip(
                    targetPercent = targetPercent,
                    silent = silent
                )
                return
            }

        // R10.23 VOICE & BACKGROUND 2.0 ACCEPTANCE.
        // Live Service/model/microphone readiness + deterministic wake/follow-up/recovery truth.
        if (
            isR10_23VoiceBackgroundAcceptanceCommand(
                routingNormalized
            )
        ) {
            runR10_23VoiceBackgroundAcceptance(
                silent = silent
            )
            return
        }

        // R10.22 NOTIFICATIONS & COMMUNICATION ASSISTANT ACCEPTANCE.
        // Reversible live NotificationListener probe + local grouping/draft/send-policy truth.
        if (
            isR10_22CommunicationAssistantAcceptanceCommand(
                routingNormalized
            )
        ) {
            runR10_22CommunicationAssistantAcceptance(
                silent = silent
            )
            return
        }

        // R10.21 DOCUMENT & OFFICE ENGINE 2.0 ACCEPTANCE.
        // Local read/edit/reopen truth plus one real published-and-deleted PPTX artifact.
        if (
            isR10_21DocumentOffice2AcceptanceCommand(
                routingNormalized
            )
        ) {
            runR10_21DocumentOffice2Acceptance(
                silent = silent
            )
            return
        }

        // R10.20 PERSONAL SEARCH 2.0 ACCEPTANCE.
        // Local-only reversible probe: seeded History fact -> semantic alias search ->
        // provenance/fingerprint envelope -> cleanup. No Agent Core or external UI action.
        if (
            isR10_20PersonalSearch2AcceptanceCommand(
                routingNormalized
            )
        ) {
            runR10_20PersonalSearch2Acceptance(
                silent = silent
            )
            return
        }

        // R10.19 AUTONOMOUS MULTI-APP TASKS 2.0 ACCEPTANCE.
        // Runs the production Dynamic Goal Planner with an eight-subgoal DAG across
        // Browser -> YouTube -> App Info/Permissions -> Calendar DRAFT_ONLY.
        if (
            isR10_19AutonomousMultiAppAcceptanceCommand(
                routingNormalized
            )
        ) {
            runR10_19AutonomousMultiAppAcceptance(
                silent = silent
            )
            return
        }

        // R10.10 PRODUCTION DYNAMIC PLANNER.
        // This is a normal user-command route, not an acceptance shortcut. It may claim only
        // a locally decomposable multi-step objective after the existing composite safety gate.
        // All other commands continue through the established deterministic / Agent Core routes.
        if (
            preExecutionDecision.type !in
                setOf(
                    AyanaCompositeIntentGate.DecisionType.DATA_ONLY,
                    AyanaCompositeIntentGate.DecisionType.INVALID,
                    AyanaCompositeIntentGate.DecisionType.REQUIRE_CONFIRMATION,
                    AyanaCompositeIntentGate.DecisionType.CONDITIONAL
                ) &&
            !preExecutionDecision.constraints.forbidNetwork &&
            runR10_10ProductionDynamicPlannerIfSupported(
                command = originalCommand,
                silent = silent
            )
        ) {
            return
        }

        val requestedAggregateMetrics =
            extractRequestedAggregateMetrics(
                originalCommand
            )

        if (
            aggregateMetricLocalRouteEligible(
                requestedAggregateMetrics
            ) &&
            preExecutionDecision.type !in
                setOf(
                    AyanaCompositeIntentGate.DecisionType.DATA_ONLY,
                    AyanaCompositeIntentGate.DecisionType.INVALID,
                    AyanaCompositeIntentGate.DecisionType.REQUIRE_CONFIRMATION,
                    AyanaCompositeIntentGate.DecisionType.CONDITIONAL
                )
        ) {
            runLocalMultiMetricCommand(
                metrics = requestedAggregateMetrics,
                command = originalCommand,
                silent = silent
            )
            return
        }

        val explicitArtifactGoal =
            requestsArtifactDeliverable(
                originalCommand
            )

        if (
            explicitArtifactGoal &&
            shouldDelegateArtifactWholeGoalToAgent(
                preExecutionDecision
            )
        ) {
            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "artifact_whole_goal_handoff",
                message = "Запрошенный артефакт сохраняет владение всей исходной целью",
                details =
                    "pre_execution=${preExecutionDecision.type.name}; command=${originalCommand.take(420)}"
            )
            askAyana(
                originalCommand,
                silent
            )
            return
        }

        if (
            handlePreExecutionDecision(
                decision = preExecutionDecision,
                silent = silent
            )
        ) {
            return
        }

        extractLocalTextInputRequest(
            originalCommand
        )
            ?.let {
                request ->
                runLocalTextInputCommand(
                    request = request,
                    silent = silent
                )
                return
            }

        // v12.19.4 CLIPBOARD ROUTING TRUTH.
        // Clipboard mutation is a deterministic Android side effect already backed
        // by write/read-back verification. Claim explicit clipboard-copy grammar
        // locally before any generic parser/model fallback can turn a refusal into
        // an unrelated Agent Core final.
        extractLocalClipboardCopyRequest(
            originalCommand
        )
            ?.let { clipboardText ->
                runLocalClipboardCopy(
                    text = clipboardText,
                    silent = silent
                )
                return
            }

        // R8.3B SEARCH RESULT ACTION PRECEDENCE.
        // «Открой результат 2» belongs to the latest Personal Search result map, not
        // to generic app-launch parsing. Claim it before lifecycle/App Resolver routes.
        extractSearchResultOpenIndex(
            originalCommand
        )
            ?.let { resultNumber ->
                runOpenSearchResult(
                    resultNumber = resultNumber,
                    silent = silent
                )
                return
            }

        // v12.14 VOLUME TARGET PRECEDENCE.
        // A phrase such as «уменьши громкость до 2» names an absolute target,
        // not a -1 relative delta. Resolve exact target semantics before the
        // structured relative-volume router so History and post-write truth agree.
        extractExactMediaVolumeRequest(
            routingNormalized
        )
            ?.let { request ->
                runLocalExactMediaVolumeCommand(
                    request = request,
                    silent = silent
                )
                return
            }

        // R8.3D BACKGROUND IMAGE INDEX STATUS.
        // A read-only progress request must not be mistaken for a photo search.
        if (
            isImageIndexProgressCommand(
                routingNormalized
            )
        ) {
            runLocalImageIndexProgress(
                silent = silent
            )
            return
        }

        // R8.4 UNIFIED PERSONAL SEARCH FOLLOW-UPS.
        // These commands intentionally omit the original query text, so resolve them
        // against the bounded local Personal Search session before generic routing.
        AyanaPersonalSearchEngine
            .parseFollowUp(
                originalCommand
            )
            ?.let { followUp ->
                runLocalPersonalSearchFollowUp(
                    followUp = followUp,
                    silent = silent
                )
                return
            }

        // R8.4 PERSONAL GLOBAL SEARCH — LOCAL-FIRST, PAGED FOLLOW-UPS + SOURCE FILTERS.
        // Claim only explicit personal/local-search grammar. Google/Internet/YouTube/Map/App
        // search stays outside this engine by parser contract. Current search covers Memory,
        // Command History, Tasks/Reminders, NotificationListener records, Android-visible
        // file/photo metadata, local document content and progressive local OCR/image labels.
        // Background indexing uses the same local persisted visual index; no cloud turn is used.
        AyanaPersonalSearchEngine
            .parseRequest(
                originalCommand
            )
            ?.let { personalSearchRequest ->
                runLocalPersonalGlobalSearch(
                    request = personalSearchRequest,
                    silent = silent,
                    reasoningGoal =
                        originalCommand.takeIf {
                            personalSearchRequiresReasoningContinuation(it)
                        }
                )
                return
            }

        // v12.11 STRUCTURED LOCAL-FIRST ROUTER.
        // Typed arguments are resolved locally before generic lifecycle/Settings
        // or Agent Core fallback. This prevents command parameters such as
        // notification limit/app filter and relative volume delta from being
        // discarded after the top-level intent has been recognised.
        AyanaStructuredLocalCommandRouter
            .parse(
                originalCommand
            )
            ?.let { structuredIntent ->
                if (
                    shouldDeferStructuredNotificationReadToCommunication(
                        command = originalCommand,
                        intent = structuredIntent
                    )
                ) {
                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state = "structured_notification_read_communication_bypassed",
                        message = "Structured NotificationRead уступил whole-goal Communication Assistant intent",
                        details = originalCommand.take(600)
                    )
                } else if (
                    shouldDeferStructuredMemoryRememberToWholeGoal(
                        command = originalCommand,
                        intent = structuredIntent
                    )
                ) {
                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state = "structured_memory_remember_whole_goal_bypassed",
                        message = "Structured MemoryRemember не получил владение составной device-action целью",
                        details = originalCommand.take(600)
                    )
                } else if (
                    shouldDeferStructuredUnknownCapabilityToConversation(
                        command = originalCommand,
                        intent = structuredIntent
                    )
                ) {
                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state = "structured_unknown_capability_conversation_bypassed",
                        message = "Structured UnknownCapability не получил приоритет над разговорным intent",
                        details = originalCommand.take(600)
                    )
                } else if (
                    runStructuredLocalCommand(
                        intent = structuredIntent,
                        silent = silent
                    )
                ) {
                    return
                }
            }

        // R9.4 MULTI-APP TASK ORCHESTRATION.
        // Claims only explicit 2..5-step registered app commands (or the dedicated R9.4
        // acceptance command). Single-app commands remain owned by the existing R9.3 route.
        if (
            runLocalMultiAppTaskCommand(
                command = originalCommand,
                silent = silent
            )
        ) {
            return
        }

        // R9.3.4 APP INTEGRATION DEVICE ACCEPTANCE.
        // One explicit command performs all five real navigation handoffs and restores
        // AYANA after every step. It is intentionally separate from full diagnostics so
        // ordinary acceptance runs do not unexpectedly switch windows five times.
        if (
            isAppIntegrationDeviceAcceptanceCommand(
                routingNormalized
            )
        ) {
            runLocalAppIntegrationDeviceAcceptance(
                silent = silent
            )
            return
        }

        // R9.3 APP INTEGRATION FRAMEWORK — deterministic app actions before
        // generic lifecycle/Agent Core routing. Personal Search already had priority
        // above this block, so file/photo content search remains owned by that engine.
        if (
            runLocalAppIntegrationCommand(
                command = originalCommand,
                silent = silent
            )
        ) {
            return
        }

        // LOCAL CONVERSATION FAST-PATH v11.2
        // Trivial acknowledgements should not spend a network round-trip.
        // Durable-goal confirmation phrases were handled above, so «ок» here
        // cannot accidentally approve a waiting sensitive action.
        localAcknowledgementReply(
            routingNormalized
        )
            ?.let {
                reply ->
                respondAndResume(
                    reply,
                    silent,
                    success = true
                )
                return
            }

        // R9.8.1 MASTER FULL ACCEPTANCE.
        // This is intentionally more invasive than ordinary full diagnostics:
        // after the exhaustive local/adaptive suite it runs bounded real-device
        // app/screen/transfer regressions and restores AYANA after every step.
        if (
            isMasterFullAcceptanceRequest(
                originalCommand
            )
        ) {
            runLocalMasterFullAcceptanceCommand(
                silent = silent
            )
            return
        }

        // R10.18 UNIVERSAL UI ACTION ENGINE ACCEPTANCE.
        // One safe external navigation action proves semantic role normalization, live
        // Accessibility mutation authority, single dispatch and fresh post-condition truth.
        if (
            isR10_18UniversalUiActionAcceptanceCommand(
                routingNormalized
            )
        ) {
            runR10_18UniversalUiActionAcceptance(
                silent = silent
            )
            return
        }

        // R10.17 SCREEN INTELLIGENCE 2.0 ACCEPTANCE.
        // Specific gate must run before the generic acceptance router so the real-device
        // Settings + Browser fusion scenario is not collapsed to an older acceptance mode.
        if (
            isR10_17ScreenIntelligenceAcceptanceCommand(
                routingNormalized
            )
        ) {
            runR10_17ScreenIntelligenceAcceptance(
                silent = silent
            )
            return
        }

        // v12.13 LOCAL ACCEPTANCE ROUTER.
        // Requests to test AYANA herself are owned locally before the generic
        // diagnostics/self-review/Agent Core paths. This prevents the 2-3 cloud
        // turns observed in v12.12 for what should be deterministic local evidence.
        localAcceptanceTestMode(
            originalCommand
        )
            ?.let { acceptanceMode ->
                runLocalAcceptanceTestCommand(
                    mode = acceptanceMode,
                    silent = silent
                )
                return
            }

        // R10.16 PERCEPTION PROCESS RECOVERY + SAFE REBIND ACCEPTANCE.
        // Kills only the isolated :perception process while main AYANA stays alive, then
        // requires a new provider PID/epoch, Accessibility rebind and a fresh screen read.
        if (
            isR10_16PerceptionProcessRecoveryAcceptanceCommand(
                routingNormalized
            )
        ) {
            runR10_16PerceptionProcessRecoveryAcceptance(
                silent = silent
            )
            return
        }

        // R10.14 PERCEPTION PROCESS ISOLATION + CROSS-PROCESS ACCESSIBILITY ACCEPTANCE.
        // The main AYANA process is killed after verified Browser/visual producer work while
        // AgentAccessibilityService remains alive in :perception. The recovered objective must
        // reconnect to the same perception PID/epoch and complete an external YouTube suffix.
        if (
            isR10_14PerceptionProcessIsolationAcceptanceCommand(
                routingNormalized
            )
        ) {
            runR10_14PerceptionProcessIsolationAcceptance(
                silent = silent
            )
            return
        }

        // R10.13 FULL PROCESS-DEATH RECOVERY ACCEPTANCE.
        // Persists a safe production objective after verified Browser/visual work, then kills
        // the AYANA app process. START_STICKY/system restart must create a new PID/process epoch
        // and recover only from durable disk state without replaying VERIFIED producer work.
        if (
            isR10_13FullProcessDeathRecoveryAcceptanceCommand(
                routingNormalized
            )
        ) {
            runR10_13FullProcessDeathRecoveryAcceptance(
                silent = silent
            )
            return
        }

        // R10.12 NATURAL LIFECYCLE RECOVERY + BACKGROUND CONTINUATION ACCEPTANCE.
        // Persists a safe production objective after verified Browser/visual work, then
        // actually stops and recreates AyanaVoiceService. The new Service instance must
        // auto-discover the interrupted goal and continue only the unresolved suffix.
        if (
            isR10_12NaturalLifecycleRecoveryAcceptanceCommand(
                routingNormalized
            )
        ) {
            runR10_12NaturalLifecycleRecoveryAcceptance(
                silent = silent
            )
            return
        }

        // R10.11 PRODUCTION REPLAN + DURABLE RECOVERY ACCEPTANCE.
        // Uses the same production planner/DurableGoalStore path as normal objectives. The
        // acceptance profile injects one verified pre-dispatch YouTube failure, requires a
        // different contract-validated suffix, reopens the durable store and resumes only the
        // unresolved suffix. Browser/visual verified work must not replay.
        if (
            isR10_11ProductionReplanRecoveryAcceptanceCommand(
                routingNormalized
            )
        ) {
            runR10_11ProductionReplanRecoveryAcceptance(
                silent = silent
            )
            return
        }

        // R10.9 DYNAMIC GOAL DECOMPOSITION + PLANNER CONTRACT ACCEPTANCE.
        // A bounded free-form objective is decomposed locally into a validated DAG. Invalid
        // cycles/executors/authority are rejected before dispatch; a verified suffix revision
        // then survives durable restart without changing the already verified prefix.
        if (
            isR10_9DynamicGoalDecompositionAcceptanceCommand(
                routingNormalized
            )
        ) {
            runR10_9DynamicGoalDecompositionAcceptance(
                silent = silent
            )
            return
        }

        // R10.8 GENERAL-PURPOSE LONG AUTONOMOUS OBJECTIVE ACCEPTANCE.
        // Dependency-aware subgoals publish only verified partial results; one persisted
        // result survives restart and is consumed without replaying its Browser/visual producer.
        if (
            isR10_8GeneralPurposeLongObjectiveAcceptanceCommand(
                routingNormalized
            )
        ) {
            runR10_8GeneralPurposeLongObjectiveAcceptance(
                silent = silent
            )
            return
        }

        // R10.7 CROSS-LANE DURABLE RECOVERY ACCEPTANCE. One objective executes
        // verified work across three lanes, persists the common ledgers, crosses a
        // service-style interruption boundary and resumes the verified suffix without
        // replaying the Browser or the failed read transition.
        if (
            isR10_7CrossLaneDurableRecoveryAcceptanceCommand(
                routingNormalized
            )
        ) {
            runR10_7CrossLaneDurableRecoveryAcceptance(
                silent = silent
            )
            return
        }

        // R10.6 CROSS-LANE ADAPTIVE CONTINUITY ACCEPTANCE. One bounded objective
        // uses the existing Agent Core executor, Android Goal executor and Multi-App
        // integration path under one adaptive ledger and one authority ceiling.
        if (
            isR10_6CrossLaneAdaptiveContinuityAcceptanceCommand(
                routingNormalized
            )
        ) {
            runR10_6CrossLaneAdaptiveContinuityAcceptance(
                silent = silent
            )
            return
        }

        // R10.4 ADAPTIVE VERIFIED EXECUTION LOOP ACCEPTANCE. The gate executes one
        // bounded real-device plan, records a safe failed observation, replans only the
        // remaining suffix from the verified Browser state, continues through verified
        // structured visual evidence and finishes only after a verified consumer step.
        if (
            isR10_4AdaptiveLoopAcceptanceCommand(
                routingNormalized
            )
        ) {
            runR10_4AdaptiveLoopAcceptance(
                silent = silent
            )
            return
        }

        // R10.3 LONG TASK RECOVERY ACCEPTANCE. This is a bounded local persistent
        // round-trip: it uses a dedicated test Durable Goal file, simulates service
        // interruption/re-instantiation, proves resume-from-next-verified-step and
        // proves that an in-flight step is reconciled instead of blindly replayed.
        if (
            isR10_3LongTaskRecoveryAcceptanceCommand(
                routingNormalized
            )
        ) {
            runR10_3LongTaskRecoveryAcceptance(
                silent = silent
            )
            return
        }

        // R10.2 UNIFIED PERSONAL SEARCH ACCEPTANCE. This dedicated gate runs a
        // bounded local search across every registered Personal Search source and
        // verifies the file/document/notification/history/photo evidence contract.
        if (
            isR10_2UnifiedPersonalSearchAcceptanceCommand(
                routingNormalized
            )
        ) {
            runR10_2UnifiedPersonalSearchAcceptance(
                silent = silent
            )
            return
        }

        // R10.1 LOCAL SELF-AUDIT. Explicit capability inventory/audit requests
        // are fully local and must never depend on a long Agent Core completion.
        if (
            isR10LocalSelfAuditRequest(
                routingNormalized
            )
        ) {
            runR10LocalSelfAuditCommand(
                silent = silent
            )
            return
        }

        // v12.9.0 LOCAL SELF-DIAGNOSTICS TRUTH.
        // Diagnostics must observe the previous Agent Core measurement, not create a
        // fresh Agent Core request first and overwrite the latency/error being measured.
        if (
            isExplicitSelfDiagnosticsRequest(
                routingNormalized
            )
        ) {
            runLocalSelfDiagnosticsCommand(
                silent = silent
            )
            return
        }

        // v12.12 LOCAL SELF-REVIEW / AUTONOMY TRUTH.
        // Questions about what AYANA herself still needs must not spend 15–20 s
        // waiting for a generic model answer that can forget already implemented
        // capabilities. Build the review from the live Capability Registry instead.
        if (
            isLocalSelfReviewOrAutonomyRequest(
                routingNormalized
            )
        ) {
            runLocalSelfReviewCommand(
                silent = silent
            )
            return
        }

        if (
            isStructuredSemanticScreenAcceptanceCommand(
                routingNormalized
            )
        ) {
            runStructuredSemanticScreenAcceptance(
                silent = silent
            )
            return
        }

        if (
            isLocalDeviceStateRequest(
                routingNormalized
            )
        ) {
            runLocalDeviceStateCommand(
                silent = silent
            )
            return
        }

        if (
            isLocalScreenStateRequest(
                routingNormalized
            )
        ) {
            runLocalScreenStateCommand(
                silent = silent
            )
            return
        }

        localSingleScrollDirection(
            routingNormalized
        )
            ?.let {
                direction ->
                runLocalSingleScrollCommand(
                    direction = direction,
                    silent = silent
                )
                return
            }

        // CAPABILITY TRUTH FAST-PATH v11.3 / v12.9.0 scope guard.
        // Only narrow media/document capability questions stay local. Higher-level
        // development/project questions (APK, GitHub, source code, AI agents, etc.)
        // must reach Agent Core for contextual reasoning.
localCapabilityTruthReply(
            routingNormalized
        )
            ?.let {
                reply ->
                respondAndResume(
                    reply,
                    silent,
                    success = true
                )
                return
            }

        // GOOGLE IMAGES FAST-PATH v11.3
        // Obvious "show/find pictures" commands are deterministic browser
        // actions and must not spend 6-8 seconds on Agent Core + Planner.
        extractLocalImageSearchQuery(
            routingNormalized
        )
            ?.takeIf {
                it.isNotBlank()
            }
            ?.let {
                query ->
                openGoogleImageSearch(
                    query,
                    silent
                )
                return
            }

        // NETWORK TEST FAST-PATH v11.3
        // FAST.com starts measurement automatically. AYANA still does not claim
        // an Mbps result because current screen content is not reliably readable.
        if (
            isInternetSpeedTestRequest(
                routingNormalized
            )
        ) {
            openInternetSpeedTest(
                specificallyMobile =
                    routingNormalized.contains(
                        "мобиль"
                    ),
                silent =
                    silent
            )
            return
        }

        // R10.22 COMMUNICATION ASSISTANT LOCAL ROUTES.
        // Drafting and notification analysis stay local. Direct send is deliberately
        // fail-closed until a verified per-target send executor exists.
        if (isCommunicationSendFromNotificationRequest(routingNormalized)) {
            runLocalCommunicationSendBlocked(
                silent = silent
            )
            return
        }

        if (isCommunicationDraftRequest(routingNormalized)) {
            runLocalCommunicationDraft(
                silent = silent
            )
            return
        }

        if (isCommunicationDigestRequest(routingNormalized)) {
            runLocalCommunicationDigest(
                silent = silent
            )
            return
        }

        // v12.10.2 READ-ONLY NOTIFICATION ROUTER.
        // Reading recent notifications is a distinct capability from opening the
        // Android notification Settings screen. A missing listener permission is
        // BLOCKED and never substituted with a Settings SUCCESS.
        if (
            isRecentNotificationsReadRequest(
                routingNormalized
            )
        ) {
            runLocalRecentNotificationsCommand(
                silent = silent
            )
            return
        }

        // BASIC LOCAL CALCULATOR v8.9
        // Simple two-number arithmetic must not spend a network round-trip.
        val localCalculation =
            evaluateSimpleCalculation(
                routingNormalized
            )
if (localCalculation != null) {
            respondAndResume(
                localCalculation,
                silent,
                success = true
            )
            return
        }

        // APP EXECUTION ROUTER v11.5
        // One deterministic path owns simple app open/minimize/close commands.
        // It also consumes a short local clarification context before any Agent Core
        // handoff. No command-specific YouTube patching is used here.
        val pendingLifecycleAction =
            extractPendingLifecycleFollowUpAction(
                routingNormalized
            )

        if (pendingLifecycleAction != null) {
            val pendingTarget =
                consumePendingLifecycleTarget()

            if (!pendingTarget.isNullOrBlank()) {
                handleLocalAppLifecycleRequest(
                    action = pendingLifecycleAction,
                    requestedName = pendingTarget,
                    silent = silent
                )
                return
            }
        } else {
            clearExpiredOrInterruptedLifecycleContext()
        }

        val lifecycleRequest =
            extractLocalAppLifecycleRequest(
                routingNormalized
            )

        if (lifecycleRequest != null) {
            clearPendingLifecycleContext()
            handleLocalAppLifecycleRequest(
                action = lifecycleRequest.first,
                requestedName = lifecycleRequest.second,
                silent = silent
            )
            return
        }

        val lifecycleClarificationTarget =
            extractLifecycleClarificationTarget(
                routingNormalized
            )

        if (!lifecycleClarificationTarget.isNullOrBlank()) {
            beginLocalLifecycleClarification(
                candidate = lifecycleClarificationTarget,
                silent = silent
            )
            return
        }

        // FAST APP DETAIL ROUTER v8.8
        // Common read-only app-settings destinations can be resolved locally even
        // when the user phrases them as two steps, e.g.
        // «открой настройки приложения YouTube и перейди в уведомления».
        // This avoids a network classifier round-trip for an already deterministic
        // Android destination. State-changing phrases are intentionally excluded.
        val fastAppDetailGoal =
            extractFastAppDetailGoal(
                routingNormalized
            )

        if (
            fastAppDetailGoal !=
            null
        ) {
            val appTarget =
                fastAppDetailGoal.first

            val section =
                fastAppDetailGoal.second

            val result =
                agentOpenAppSettings(
                    requestedName = appTarget,
                    section = section
                )

            val resultMessage =
                result.optString(
                    "message",
                    if (
                        result.optBoolean(
                            "success",
                            false
                        )
                    ) {
                        "Открываю параметры приложения $appTarget"
                    } else {
                        "Не удалось открыть параметры приложения $appTarget"
                    }
                )

            if (
                result.optBoolean(
                    "success",
                    false
                )
            ) {
                finishLocalCommand(
                    resultMessage,
                    silent
                )
            } else {
                respondAndResume(
                    resultMessage,
                    silent,
                    success = false
                )
            }

            return
        }

        // PLANNER HANDOFF v2.7.4.1
        // Fast local routes are only allowed to finish SINGLE-STEP commands.
        // Multi-step goals must reach Agent Core so the planner can continue
        // after the first Android screen instead of returning early.
        val multiStepRequest =
            isMultiStepAgentCommand(
                routingNormalized
            )

        // Direct local route for app-specific settings such as
        // «открой уведомления YouTube». This MUST run before the generic
        // «открой <app>» router, otherwise the whole phrase may be treated
        // as an application name (for example «уведомления ютуб»).
        val directAppSettingsTarget =
            extractDirectAppSettingsTarget(
                routingNormalized
            )

        if (
            directAppSettingsTarget != null &&
            !multiStepRequest
        ) {

            val section =
                directAppSettingsTarget.first

            val appTarget =
                directAppSettingsTarget.second

            val result =
                agentOpenAppSettings(
                    requestedName = appTarget,
                    section = section
                )

            val resultMessage =
                result
                    .optString(
                        "message",
                        if (
                            result.optBoolean(
                                "success",
                                false
                            )
                        ) {
                            "Открываю параметры приложения $appTarget"
                        } else {
                            "Не удалось открыть параметры приложения $appTarget"
                        }
                    )

            if (
                result.optBoolean(
"success",
                    false
                )
            ) {
                finishLocalCommand(
                    resultMessage,
                    silent
                )
            } else {
                respondAndResume(
                    resultMessage,
                    silent,
                    success = false
                )
            }

            return
        }

        // Direct local route for requests such as
        // «открой информацию о приложении Галерея».
        // This check MUST run before the generic «открой <app>» router,
        // otherwise voice commands may be mistaken for a normal app launch.
        val directAppInfoTarget =
            extractDirectAppInfoTarget(
                routingNormalized
            )

        // HYBRID APP SUBPAGE ROUTER v2.7.4.2
        // Common app-info subpages should not spend one Agent Core round-trip
        // merely deciding the obvious first/second step. Open App info locally,
        // then use semantic Accessibility navigation. If Samsung/Android layout
        // differs, fall back to Planner v2 instead of failing the whole task.
        val appInfoSubpageGoal =
            if (multiStepRequest) {
                extractAppInfoSubpageGoal(
                    routingNormalized
                )
            } else {
                null
            }

        if (
            appInfoSubpageGoal != null
        ) {

            val appTarget =
                appInfoSubpageGoal.first

            val subpage =
                appInfoSubpageGoal.second

            val openResult =
                agentOpenAppInfo(
                    appTarget
                )

            if (
                openResult.optBoolean(
                    "success",
                    false
                )
            ) {

                try {
                    Thread.sleep(
                        UI_SETTLE_DELAY_MS
                    )
                } catch (_: Exception) {
                }

                val subpageResult =
                    tryOpenAppInfoSubpageLocally(
                        subpage = subpage,
                        appTarget =
                            openResult.optString(
                                "label",
                                appTarget
                            )
                    )

                if (
                    subpageResult.optBoolean(
                        "success",
                        false
                    )
                ) {

                    val spokenTarget =
                        when (subpage) {

                            "permissions" ->
                                "разрешения приложения $appTarget"

                            "battery" ->
                                "использование батареи приложения $appTarget"

                            "storage" ->
                                "хранилище приложения $appTarget"

                            else ->
                                "нужный раздел приложения $appTarget"
                        }

                    finishLocalCommand(
                        "Открываю $spokenTarget",
                        silent
                    )

                    return
                }
            }

            // Layout can vary between One UI / Android versions. Planner v2 is
            // the safe fallback for unusual screens; never stop on App info.
            askAyana(
                originalCommand,
                silent
            )

            return
        }

        if (
            !directAppInfoTarget
                .isNullOrBlank() &&
            !multiStepRequest
        ) {

            val result =
                agentOpenAppInfo(
                    directAppInfoTarget
                )

            val resultMessage =
                result
                    .optString(
                        "message",
                        if (
                            result.optBoolean(
                                "success",
                                false
                            )
                        ) {
                            "Открываю информацию о приложении $directAppInfoTarget"
                        } else {
                            "Не удалось открыть информацию о приложении $directAppInfoTarget"
                        }
                    )

            if (
                result.optBoolean(
                    "success",
                    false
                )
            ) {
                finishLocalCommand(
                    resultMessage,
                    silent
                )
            } else {
                respondAndResume(
                    resultMessage,
                    silent,
                    success = false
                )
            }

            return
        }

        // HYBRID SETTINGS TARGET v2.7.4.5
        // Example: «открой настройки, зайди в приложения и найди YouTube».
        // This shortcut is intentionally limited to an EXPLICIT Apps-settings
        // route. A phrase such as «специальные возможности, найди AYANA AI среди
        // установленных приложений» belongs to Accessibility and must reach
        // Agent Core instead of being collapsed to ordinary App info.
        val settingsAppSearchTarget =
            extractSettingsAppSearchTarget(
                routingNormalized
            )

        if (
            !settingsAppSearchTarget
                .isNullOrBlank()
        ) {

            val result =
                agentOpenAppInfo(
                    settingsAppSearchTarget
                )

            if (
                result.optBoolean(
                    "success",
                    false
                )
            ) {
                finishLocalCommand(
                    result.optString(
                        "message",
                        "Открываю $settingsAppSearchTarget в настройках"
                    ),
                    silent
                )
                return
            }
            // If the direct resolver cannot find the app, do not fail early.
            // Fall through to Agent Core so Screen Intelligence can continue.
        }

        // FAST LOCAL ROUTER v2.7.4
        // Common Android settings commands must never wait for Agent Core.
        // Route them directly on-device before the generic command / app router.
        val directSystemSettingsSection =
            extractDirectSystemSettingsSection(
                routingNormalized
            )

        if (
            !directSystemSettingsSection
                .isNullOrBlank() &&
            !multiStepRequest
        ) {

            val result =
                agentOpenSettings(
                    directSystemSettingsSection
                )

            val resultMessage =
                result
                    .optString(
                        "message",
                        if (
                            result.optBoolean(
                                "success",
                                false
                            )
                        ) {
                            "Открываю настройки"
                        } else {
                            "Не удалось открыть настройки"
                        }
                    )

            if (
                result.optBoolean(
                    "success",
                    false
                )
            ) {
                finishLocalCommand(
                    resultMessage,
                    silent
                )
            } else {
                respondAndResume(
                    resultMessage,
                    silent,
                    success = false
                )
            }

            return
        }

        when {

            routingNormalized ==
                "назад" ||
                routingNormalized ==
                "вернись назад" -> {

                val result =
                    screenIntelligence
                        .pressBack()

                result.optJSONObject("screen")?.let { screen ->
                    capabilityRegistry.recordScreenObservation(screen)
                }

                if (result.optBoolean("success", false)) {
                    finishLocalCommand(
                        "Назад",
                        silent
                    )
                } else {
                    respondAndResume(
                        result.optString("message")
                            .ifBlank { "Не удалось выполнить Назад." },
                        silent,
                        success = false,
                        terminalStatus =
                            when (result.optString("terminal_status")) {
                                "BLOCKED" -> AyanaCommandHistoryStore.STATUS_BLOCKED
                                "UNSUPPORTED" -> AyanaCommandHistoryStore.STATUS_UNSUPPORTED
                                else -> null
                            }
                    )
                }

                return
            }

            routingNormalized ==
                "домой" ||
                routingNormalized ==
                "на главный экран" ||
                routingNormalized ==
                "главный экран" -> {

                val result =
                    screenIntelligence
                        .pressHome()

                result.optJSONObject("screen")?.let { screen ->
                    capabilityRegistry.recordScreenObservation(screen)
                }

                if (result.optBoolean("success", false)) {
                    finishLocalCommand(
                        "Главный экран",
                        silent
                    )
                } else {
                    respondAndResume(
                        result.optString("message")
                            .ifBlank { "Не удалось открыть главный экран." },
                        silent,
                        success = false,
                        terminalStatus =
                            when (result.optString("terminal_status")) {
                                "BLOCKED" -> AyanaCommandHistoryStore.STATUS_BLOCKED
                                "UNSUPPORTED" -> AyanaCommandHistoryStore.STATUS_UNSUPPORTED
                                else -> null
                            }
                    )
                }

                return
            }

            normalized ==
                "повтори" ||
                normalized ==
                "повтори ответ" -> {

                val lastAnswer =
                    conversationHistory
                        .lastOrNull()
                        ?.second

                if (
                    lastAnswer != null
                ) {
                    respondAndResume(
                        lastAnswer,
                        silent
                    )
                } else {
                    respondAndResume(
                        "Мне пока нечего повторять.",
                        silent
                    )
                }

                return
            }

            normalized ==
                "забудь разговор" ||
                normalized ==
                "очисти историю" -> {

                conversationHistory
                    .clear()

                agentPreviousResponseId =
                    null

                respondAndResume(
                    "Хорошо. История текущего разговора очищена.",
                    silent
                )

                return
            }

            normalized ==
                "очисти память" ||
                normalized ==
                "забудь все что помнишь" ||
                normalized ==
                "забудь всё что помнишь" ||
                normalized ==
                "очисти долговременную память" -> {

                val removed =
                    memoryStore.clear()

                agentPreviousResponseId =
                    null

                respondAndResume(
                    if (removed > 0) {
                        "Хорошо. Долговременная память очищена."
                    } else {
                        "Долговременная память уже пуста."
                    },
                    silent
                )

                return
            }

            isVolumeUpCommand(
                routingNormalized
            ) -> {

                changeVolume(
                    AudioManager.ADJUST_RAISE
                )

                finishLocalCommand(
                    "Громкость увеличена",
                    silent
                )

                return
            }

            isVolumeDownCommand(
                routingNormalized
            ) -> {

                changeVolume(
                    AudioManager.ADJUST_LOWER
                )

                finishLocalCommand(
                    "Громкость уменьшена",
                    silent
                )

                return
            }

            isMuteCommand(
                routingNormalized
            ) -> {

                changeVolume(
                    AudioManager.ADJUST_MUTE
                )

                finishLocalCommand(
                    "Звук выключен",
                    silent
                )

                return
            }

            isUnmuteCommand(
                routingNormalized
            ) -> {

                changeVolume(
                    AudioManager.ADJUST_UNMUTE
                )

                finishLocalCommand(
                    "Звук включён",
                    silent
                )

                return
            }

            (
                (
                    routingNormalized.contains("прокрути") ||
                        routingNormalized.contains("пролистай")
                    ) &&
                    (
                        routingNormalized.contains("экран") ||
                            routingNormalized.contains("страниц")
                        ) &&
                    routingNormalized.contains("до конца")
                ) -> {

                val direction =
                    if (
                        routingNormalized.contains("вверх") ||
                        routingNormalized.contains("наверх")
                    ) {
                        "up"
                    } else {
                        "down"
                    }

                executeLocalScrollToBoundary(
                    direction = direction,
                    silent = silent
                )

                return
            }

            normalized
                .startsWith(
                    "нажми "
                ) -> {

                val target =
                    normalized
                        .removePrefix(
                            "нажми "
                        )
                        .trim()

                clickByText(
                    target,
                    silent
                )

                return
            }

            normalized
                .startsWith(
                    "выбери "
                ) -> {

                val target =
                    normalized
                        .removePrefix(
                            "выбери "
                        )
                        .trim()

                clickByText(
                    target,
                    silent
                )

                return
            }

            (
                normalized.contains(
                    "ютуб"
                ) ||
                    normalized.contains(
                        "youtube"
                    )
                ) &&
                (
                    normalized.contains(
                        "найди "
                    ) ||
                        normalized.contains(
                            "ищи "
                        ) ||
                        normalized.contains(
                            "поищи "
                        ) ||
                        normalized.contains(
                            "поиск "
                        )
                    ) -> {

                val query =
                    extractYouTubeQuery(
                        normalized
                    )

                if (
                    query.isNotBlank()
                ) {

                    openYouTubeSearch(
                        query,
                        silent
                    )

                } else {

                    openApp(
                        "YouTube",
                        silent,
                        "com.google.android.youtube"
                    )
                }

                return
            }

            normalized
                .startsWith(
                    "найди в google "
                ) ||
                normalized
                    .startsWith(
                        "найди в гугле "
                    ) ||
                normalized
                    .startsWith(
                        "найди мне в google "
                    ) ||
                normalized
                    .startsWith(
                        "найди мне в гугле "
                    ) ||
                normalized
                    .startsWith(
                        "поищи в google "
                    ) ||
                normalized
                    .startsWith(
                        "поищи в гугле "
                    ) -> {

                val query =
                    if (
                        normalized.contains(
                            "google"
                        )
                    ) {

                        normalized
                            .substringAfter(
                                "google"
                            )
                            .trim()

                    } else {

                        normalized
                            .substringAfter(
                                "гугле"
                            )
                            .trim()
                    }

                if (
                    query.isNotBlank()
                ) {
                    openGoogleSearch(
                        query,
                        silent
                    )
                } else {
                    startWakeListening()
                }

                return
            }

            normalized
                .startsWith(
                    "найди на карте "
                ) ||
                normalized
                    .startsWith(
                        "найди мне на карте "
                    ) ||
                normalized
                    .startsWith(
                        "найди в картах "
                    ) ||
                normalized
                    .startsWith(
                        "покажи на карте "
                    ) ||
                normalized
                    .startsWith(
                        "покажи мне на карте "
                    ) -> {

                val query =
                    when {

                        normalized.startsWith(
                            "найди на карте "
                        ) ->
                            normalized
                                .removePrefix(
                                    "найди на карте "
                                )
                                .trim()

                        normalized.startsWith(
                            "найди мне на карте "
                        ) ->
                            normalized
                                .removePrefix(
                                    "найди мне на карте "
                                )
                                .trim()

                        normalized.startsWith(
                            "найди в картах "
                        ) ->
                            normalized
                                .removePrefix(
                                    "найди в картах "
                                )
                                .trim()

                        normalized.startsWith(
                            "покажи мне на карте "
                        ) ->
                            normalized
                                .removePrefix(
                                    "покажи мне на карте "
                                )
                                .trim()

                        else ->
                            normalized
                                .removePrefix(
                                    "покажи на карте "
                                )
                                .trim()
                    }

                if (
                    query.isNotBlank()
                ) {
                    openMapSearch(
                        query,
                        silent
                    )
                } else {
                    startWakeListening()
                }

                return
            }
        }

        val target =
            routingNormalized
                // Longest/natural launch phrases first. The resolver still validates
                // the final app against the real launcher map before any launch.
                .removePrefix(
                    "открой мне приложение "
                )
                .removePrefix(
"открой мне программу "
                )
                .removePrefix(
                    "запусти мне приложение "
                )
                .removePrefix(
                    "запусти мне программу "
                )
                .removePrefix(
                    "зайди в приложение "
                )
                .removePrefix(
                    "перейди в приложение "
                )
                .removePrefix(
                    "покажи приложение "
                )
                .removePrefix(
                    "открой приложение "
                )
                .removePrefix(
                    "запусти приложение "
                )
                .removePrefix(
                    "включи приложение "
                )
                .removePrefix(
                    "открой программу "
                )
                .removePrefix(
                    "запусти программу "
                )
                .removePrefix(
                    "включи программу "
                )
                .removePrefix(
                    "открой мне "
                )
                .removePrefix(
                    "запусти мне "
                )
                .removePrefix(
                    "открой "
                )
                .removePrefix(
                    "запусти "
                )
                .removePrefix(
                    "включи "
                )
                .trim()

        when (target) {

            "youtube",
            "ютуб" ->
                openApp(
                    "YouTube",
                    silent,
                    "com.google.android.youtube"
                )

            "chrome",
            "хром",
            "гугл хром" ->
                openApp(
                    "Chrome",
                    silent,
                    "com.android.chrome"
                )
"браузер",
            "интернет",
            "самсунг интернет" ->
                openApp(
                    "браузер",
                    silent,
                    "com.sec.android.app.sbrowser",
                    "com.android.chrome"
                )

            "gmail",
            "джимейл",
            "почта",
            "электронная почта" ->
                openApp(
                    "почту",
                    silent,
                    "com.google.android.gm",
                    "com.samsung.android.email.provider"
                )

            "карты",
            "google maps",
            "гугл карты" ->
                openApp(
                    "Google Maps",
                    silent,
                    "com.google.android.apps.maps"
                )

            "play market",
            "play store",
            "плей маркет",
            "гугл плей" ->
                openApp(
                    "Google Play",
                    silent,
                    "com.android.vending"
                )

            "камера",
            "камеру" ->
                openApp(
                    "камеру",
                    silent,
                    "com.sec.android.app.camera"
                )

            "галерея",
            "галерею",
            "фото",
            "фотографии" ->
                openApp(
                    "галерею",
                    silent,
                    "com.sec.android.gallery3d",
                    "com.google.android.apps.photos"
                )

            "переводчик",
            "переводчика",
            "google переводчик",
            "гугл переводчик",
            "translate",
            "google translate" ->
                openApp(
                    "переводчик",
                    silent,
                    "com.google.android.apps.translate"
                )

            "google фото",
            "гугл фото" ->
                openApp(
                    "Google Фото",
                    silent,
                    "com.google.android.apps.photos",
                    "com.sec.android.gallery3d"
                )

            "файлы",
            "мои файлы" ->
                openApp(
                    "Мои файлы",
                    silent,
                    "com.sec.android.app.myfiles"
                )

            "калькулятор" ->
                openApp(
                    "калькулятор",
                    silent,
                    "com.sec.android.app.popupcalculator"
                )

            "календарь" ->
                openApp(
                    "календарь",
                    silent,
                    "com.samsung.android.calendar",
                    "com.google.android.calendar"
                )

            "часы",
            "будильник" ->
                openApp(
                    "часы",
                    silent,
                    "com.sec.android.app.clockpackage"
                )

            "сообщения",
            "смс" ->
                openApp(
                    "сообщения",
                    silent,
                    "com.samsung.android.messaging",
                    "com.google.android.apps.messaging"
                )

            "контакты" ->
                openApp(
                    "контакты",
                    silent,
                    "com.samsung.android.app.contacts",
                    "com.google.android.contacts"
                )

            "chatgpt",
            "chat gpt",
            "чат gpt",
            "чат гпт",
            "чат жпт",
            "чатгпт",
            "чатжпт",
            "чат джипити",
            "чат жипити",
            "чат джи пи ти",
            "джипити" ->
                openApp(
                    "ChatGPT",
                    silent,
                    "com.openai.chatgpt"
                )

            "telegram",
            "телеграм",
            "телеграмм",
            "телега",
            "телегу",
            "телеги" ->
                openApp(
                    "Telegram",
                    silent,
                    "org.telegram.messenger"
                )

            "whatsapp",
            "whats app",
            "ватсап",
            "вотсап",
            "вацап",
            "ватс апп",
            "вотс апп" ->
                openApp(
                    "WhatsApp",
                    silent,
                    "com.whatsapp"
                )

            "google",
            "гугл" ->
                openApp(
                    "Google",
                    silent,
                    "com.google.android.googlequicksearchbox"
                )

            "диск",
"google диск",
            "гугл диск" ->
                openApp(
                    "Google Диск",
                    silent,
                    "com.google.android.apps.docs"
                )

            "заметки",
            "samsung notes",
            "самсунг ноутс" ->
                openApp(
                    "Samsung Notes",
                    silent,
                    "com.samsung.android.app.notes"
                )

            "настройки" ->
                openSystemScreen(
                    Settings.ACTION_SETTINGS,
                    "настройки",
                    silent
                )

            "wifi",
            "wi-fi",
            "вай фай",
            "вайфай" ->
                openSystemScreen(
                    Settings.ACTION_WIFI_SETTINGS,
                    "настройки Wi-Fi",
                    silent
                )

            "bluetooth",
            "блютуз" ->
                openSystemScreen(
                    Settings.ACTION_BLUETOOTH_SETTINGS,
                    "настройки Bluetooth",
                    silent
                )

            "звук",
            "настройки звука" ->
                openSystemScreen(
                    Settings.ACTION_SOUND_SETTINGS,
                    "настройки звука",
                    silent
                )

            "экран",
            "настройки экрана",
            "дисплей" ->
                openSystemScreen(
                    Settings.ACTION_DISPLAY_SETTINGS,
                    "настройки экрана",
                    silent
                )

            "специальные возможности",
            "спец возможности" ->
                openSystemScreen(
                    Settings.ACTION_ACCESSIBILITY_SETTINGS,
                    "специальные возможности",
                    silent
                )

            "геолокация",
            "местоположение",
            "локация" ->
                openSystemScreen(
                    Settings.ACTION_LOCATION_SOURCE_SETTINGS,
                    "настройки местоположения",
                    silent
                )

            "безопасность",
            "настройки безопасности" ->
                openSystemScreen(
                    Settings.ACTION_SECURITY_SETTINGS,
                    "настройки безопасности",
                    silent
                )

            "дата и время",
            "время и дата" ->
                openSystemScreen(
                    Settings.ACTION_DATE_SETTINGS,
                    "настройки даты и времени",
                    silent
                )

            else -> {

                if (
                    isMultiStepAgentCommand(
                        normalized
                    )
                ) {

                    askAyana(
                        originalCommand,
                        silent
                    )

                } else if (
                    target in
                        KNOWN_LOCAL_LAUNCH_ALIASES
                ) {

                    // Exact known aliases stay on the zero-fuzz deterministic path.
                    openInstalledAppByName(
                        target,
                        silent
                    )

                } else if (
                    tryOpenPhoneticInstalledApp(
                        target = target,
                        wholeCommand = routingNormalized,
                        silent = silent
                    )
                ) {
                    // v12.5: a short ASR-distorted app name may stay local only
                    // after phonetic ranking AND device-observed package resolution.
                    Unit

                } else if (
                    isAppLaunchCommand(
                        routingNormalized
                    )
                ) {

                    // Explicit launches that are not safe phonetic matches still
                    // use the normal App Resolver and fail honestly if unresolved.
                    openInstalledAppByName(
                        target,
                        silent
                    )

                } else {

                    askAyana(
                        originalCommand,
                        silent
                    )
                }
            }
        }
    }

    private fun extractFastAppDetailGoal(
        command: String
    ): Pair<String, String>? {

        val section =
            detectAppDetailSection(
                command
            )
                ?: return null

        // Goal-integrity guard: this fast path is ONLY for navigation to a
        // read-only app-details destination. If anything actionable follows the
        // requested section (for example «...в разрешения и нажми Камера» or
        // «...в уведомления и выключи их»), the complete command must go to
        // Planner/Task Engine instead of returning a partial local SUCCESS.
        val sectionPattern =
            appDetailSectionRegex(
                section
            )
                ?: return null

        val lastSectionMatch =
            Regex(
                "(?:" +
                    sectionPattern +
                    ")"
            )
                .findAll(
                    command
                )
                .lastOrNull()
                ?: return null

        val trailingAfterSection =
            command
                .substring(
                    lastSectionMatch
                        .range
                        .last +
                        1
                )
                .trim(
                    ' ',
                    '.',
                    ',',
                    '!',
                    '?',
                    ':',
                    ';',
                    '«',
                    '»',
                    '"',
                    '\''
                )

        if (
            trailingAfterSection
                .isNotBlank()
        ) {
            return null
        }

        // Strongest multi-step form:
        // «открой информацию о приложении Chrome и зайди в разрешения».
        // Reuse the app-info extractor because it already removes the trailing
        // navigation clause and preserves the app name exactly.
        val appFromInfo =
            extractDirectAppInfoTarget(
                command
            )

        if (
            !appFromInfo
                .isNullOrBlank()
        ) {
            return appFromInfo to section
        }

        // «открой настройки приложения Chrome и перейди в уведомления»
        // «покажи параметры приложения Gmail, затем открой разрешения»
        val settingsPattern =
            Regex(
                """(?:(?:открой|покажи|зайди\s+в|перейди\s+в)\s+)?(?:настройк\p{L}*|параметр\p{L}*)\s+приложени\p{L}*\s+(.+?)(?:\s+и\s+|\s+(?:потом|затем|после\s+этого)\s+)(?:перейди|зайди|открой|покажи)?\s*(?:в\s+)?"""
            )

        val settingsMatch =
            settingsPattern.find(
                command
            )

        val appFromSettings =
            settingsMatch
                ?.groupValues
                ?.getOrNull(1)
                .orEmpty()
                .let(
                    ::cleanExtractedAppTarget
                )

        if (
            appFromSettings
                .isNotBlank()
        ) {
            return appFromSettings to section
        }

        // Natural two-step shorthand:
        // «открой Chrome и зайди в разрешения».
        val launchThenDetail =
            Regex(
                """^(?:(?:открой|запусти|включи|покажи)(?:\s+мне)?\s+)(?:приложени\p{L}*\s+|программ\p{L}*\s+)?(.+?)(?:\s+и\s+|\s+(?:потом|затем|после\s+этого)\s+)(?:перейди|зайди|открой|покажи)\s+(?:в\s+)?"""
            )
                .find(
                    command
                )

        val appFromLaunch =
            launchThenDetail
                ?.groupValues
                ?.getOrNull(1)
                .orEmpty()
                .let(
                    ::cleanExtractedAppTarget
                )

        if (
            appFromLaunch
                .isNotBlank()
        ) {
            return appFromLaunch to section
        }

        return null
    }

    private fun extractDirectAppSettingsTarget(
        command: String
    ): Pair<String, String>? {

        val section =
            detectAppDetailSection(
                command
            )
                ?: return null

        val sectionPattern =
            appDetailSectionRegex(
                section
            )
                ?: return null

        val actionPrefix =
            """(?:(?:(?:открой|покажи)(?:\s+мне)?|зайди\s+в|перейди\s+в)\s+)?"""

        val settingsPrefix =
            """(?:(?:настройк\p{L}*|параметр\p{L}*)\s+)?"""

        val patterns =
            listOf(
                // «открой разрешения Chrome»
                // «открой язык приложения Chrome»
                Regex(
                    "^" +
                        actionPrefix +
                        settingsPrefix +
                        "(?:" +
                        sectionPattern +
                        ")" +
                        """(?:\s+(?:для|у|в|во))?(?:\s+приложени\p{L}*)?\s+(.+)$"""
                ),

                // «открой разрешения для приложения Chrome»
                Regex(
                    "^" +
                        actionPrefix +
                        settingsPrefix +
                        "(?:" +
                        sectionPattern +
                        ")" +
                        """\s+(?:для|у|в|во)\s+приложени\p{L}*\s+(.+)$"""
                ),

                // «открой у Chrome разрешения»
                // «перейди в Chrome в разрешения»
                Regex(
                    "^" +
                        actionPrefix +
                        settingsPrefix +
                        """(?:для|у|в|во)\s+(.+?)\s+(?:в\s+)?(?:""" +
                        sectionPattern +
                        ")$"
                ),

                // «открой настройки приложения Chrome разрешения»
                Regex(
                    "^" +
                        actionPrefix +
                        settingsPrefix +
                        """приложени\p{L}*\s+(.+?)\s+(?:""" +
                        sectionPattern +
                        ")$"
                )
            )

        for (pattern in patterns) {

            val match =
                pattern.find(
                    command
                )
                    ?: continue

            val target =
                match
                    .groupValues
                    .getOrNull(1)
                    .orEmpty()
                    .let(
                        ::cleanExtractedAppTarget
                    )

            if (
                target
                    .isNotBlank()
            ) {
                return section to target
            }
        }

        return null
    }

    private fun detectAppDetailSection(
        command: String
    ): String? {

        val c =
            command
                .lowercase(
                    Locale.ROOT
                )
                .replace('ё', 'е')
                .replace(
                    Regex("\\s+"),
                    " "
                )
                .trim()

        return when {

            c.contains(
                "разрешен"
            ) ->
                "permissions"

            c.contains(
                "мобильные дан"
            ) ||
                c.contains(
                    "мобильный трафик"
                ) ||
                c.contains(
                    "использование дан"
                ) ||
                c.contains(
                    "расход трафика"
                ) ->
                "mobile_data"

            c.contains(
                "батаре"
            ) ||
                c.contains(
                    "аккумулятор"
                ) ||
                c.contains(
                    "энергопотреб"
                ) ->
                "battery"

            c.contains(
                "хранилищ"
            ) ||
                c.contains(
                    "памят"
                ) ||
                c.contains(
                    "кэш"
                ) ||
                c.contains(
                    "кеш"
                ) ->
                "storage"

            c.contains(
                "уведомлен"
            ) ->
                "notifications"

            c.contains(
                "по умолчани"
            ) ||
                c.contains(
                    "открытие ссыл"
                ) ||
                c.contains(
                    "открывать ссыл"
                ) ->
                "open_by_default"

            c.contains(
                "язык"
            ) ||
                c.contains(
                    "локаль прилож"
                ) ->
                "language"

            else ->
                null
        }
    }

    private fun appDetailSectionRegex(
        section: String
    ): String? {

        return when (
            section
        ) {

            "permissions" ->
                """разрешен\p{L}*"""

            "battery" ->
                """(?:(?:(?:использовани|расход)\p{L}*\s+)?батаре\p{L}*|аккумулятор\p{L}*|энергопотреблени\p{L}*)"""

            "storage" ->
                """(?:хранилищ\p{L}*|памят\p{L}*|кэш\p{L}*|кеш\p{L}*)"""

            "mobile_data" ->
                """(?:мобильн\p{L}*\s+данн\p{L}*|мобильн\p{L}*\s+трафик\p{L}*|использовани\p{L}*\s+данн\p{L}*|расход\p{L}*\s+трафик\p{L}*)"""

            "notifications" ->
                """уведомлен\p{L}*"""

            "open_by_default" ->
                """(?:(?:открыти\p{L}*\s+)?по\s+умолчани\p{L}*|открывать\s+по\s+умолчани\p{L}*|открыти\p{L}*\s+ссыл\p{L}*|открывать\s+ссыл\p{L}*)"""

            "language" ->
                """(?:язык\p{L}*|локал\p{L}*)"""

            else ->
                null
        }
    }

    private fun cleanExtractedAppTarget(
        value: String
    ): String {

        var result =
            value
                .trim()
                .removePrefix(
                    "приложения "
                )
                .removePrefix(
                    "приложение "
                )
                .removePrefix(
                    "для "
                )
                .removePrefix(
                    "про "
                )
                .trim()

        val tailMarkers =
            listOf(
                " и зайди ",
                " и перейди ",
                " и открой ",
                " и покажи ",
                " потом ",
                " затем ",
                " после этого ",
                " открой раздел ",
                " перейди в раздел ",
                " зайди в раздел "
            )

        val tailIndex =
            tailMarkers
                .map { marker ->
                    result.indexOf(
                        marker
                    )
                }
                .filter { index ->
                    index > 0
                }
                .minOrNull()

        if (
            tailIndex !=
            null
        ) {
            result =
                result
                    .substring(
                        0,
                        tailIndex
                    )
                    .trim()
        }

        return result
            .trim(
                '"',
                '\'',
                '«',
                '»',
                '“',
                '”',
                '.',
                ',',
                '!',
                '?',
                ':',
                ';'
            )
            .trim()
    }

    private fun extractDirectAppInfoTarget(
        command: String
    ): String? {

        val patterns =
            listOf(
                Regex(
                    """(?:информац\p{L}*|сведени\p{L}*|инфо)\s+(?:(?:о|об|про|и)\s+)?приложени\p{L}*\s+(.+)"""
                ),
                // Natural explicit app-settings form. Requiring the word
                // «приложение» keeps this separate from global settings such as
                // «настройки Wi-Fi» or «параметры батареи».
                Regex(
                    """^(?:(?:открой|покажи)(?:\s+мне)?\s+)?(?:настройк\p{L}*|параметр\p{L}*)\s+приложени\p{L}*\s+(.+)"""
                )
            )

        val match =
            patterns
                .firstNotNullOfOrNull { pattern ->
                    pattern.find(
                        command
                    )
                }
                ?: return null

        var target =
            match
                .groupValues
                .getOrNull(1)
                .orEmpty()
                .trim()
                .removePrefix(
                    "для "
                )
                .removePrefix(
                    "про "
                )
                .trim()

        // In a multi-step phrase the regex above also sees the trailing goal,
        // e.g. «YouTube зайди в использование батареи». Keep only app name.
        val tailMarkers =
            listOf(
                " и зайди ",
                " и перейди ",
                " и открой ",
                " зайди ",
                " перейди ",
                " потом ",
                " затем ",
                " после этого ",
                " остановись ",
                " открой раздел "
            )

        val tailIndex =
            tailMarkers
                .map { marker ->
                    target.indexOf(
                        marker
                    )
                }
                .filter { index ->
                    index > 0
                }
                .minOrNull()

        if (tailIndex != null) {
            target =
                target
                    .substring(
                        0,
                        tailIndex
                    )
                    .trim()
        }

        target =
            target.trim(
                '"',
                '\'',
                '«',
                '»',
                '.',
                ',',
                '!',
                '?'
            )

        return target
            .takeIf {
                it.isNotBlank()
            }
    }

    private fun extractAppInfoSubpageGoal(
        command: String
    ): Pair<String, String>? {

        val appTarget =
            extractDirectAppInfoTarget(
                command
            )
                ?: return null

        val subpage =
            detectAppDetailSection(
                command
            )
                ?: return null

        return appTarget to subpage
    }

    private fun tryOpenAppInfoSubpageLocally(
        subpage: String,
        appTarget: String
    ): JSONObject {

        val targets =
            appDetailClickTargets(
                subpage
            )

        if (
            targets.isEmpty()
        ) {
            return JSONObject()
                .put(
                    "success",
                    false
                )
                .put(
                    "message",
                    "Локальная цель подстраницы не определена"
                )
        }

        var lastResult =
            JSONObject()
                .put(
                    "success",
                    false
                )
                .put(
                    "message",
                    "Подстраница пока не подтверждена"
                )

        repeat(4) { attempt ->

            val screenBefore =
                try {
                    screenIntelligence
                        .getScreenState()
                } catch (_: Exception) {
                    JSONObject()
                }

            val normalizedScreen =
                normalizeVerificationText(
                    screenVerificationTextForInteraction(
                        screenBefore
                    )
)

            val visibleTarget =
                targets.firstOrNull { target ->
                    normalizedScreen.contains(
                        normalizeVerificationText(
                            target
                        )
                    )
                }

            val candidates =
                linkedSetOf<String>()
                    .apply {
                        if (
                            visibleTarget !=
                            null
                        ) {
                            add(
                                visibleTarget
                            )
                        }

                        // v12.8.11: always try canonical Settings row labels before
                        // scrolling. Screen Intelligence v4.4 remains fail-closed and
                        // can recover an exact visible row through Android's native
                        // Accessibility text provider even when Samsung omits it from
                        // the serialized snapshot. This avoids moving the wrong pane
                        // before giving the factual current viewport a chance.
                        addAll(
                            targets
                        )
                    }

            for (
                target in
                candidates
            ) {

                val clickResult =
                    screenIntelligence
                        .click(
                            target = target,
                            confirmed = false
                        )

                lastResult =
                    clickResult

                if (
                    clickResult.optBoolean(
                        "requires_confirmation",
                        false
                    )
                ) {
                    return clickResult
                }

                val clickAccepted =
                    clickResult.optBoolean(
                        "success",
                        false
                    )

                val screenChanged =
                    clickResult.optBoolean(
                        "screen_changed",
                        false
                    )
if (
                    clickAccepted ||
                    screenChanged
                ) {

                    val verification =
                        awaitVerifiedAppDetailScreen(
                            appTarget = appTarget,
                            section = subpage,
                            timeoutMs = APP_DETAIL_VERIFY_TIMEOUT_MS
                        )

                    // v12.10.2 Samsung verified continuation. The App Info page
                    // was already strictly proven before this helper is entered.
                    // Some One UI subpages (especially Permissions) omit the app
                    // label from the same accessibility context even though the
                    // destination semantic surface is strongly proven. Accept that
                    // narrow continuation only after a real click/screen change and
                    // a fresh Settings semantic surface; never use it for a direct
                    // unproven Settings launch.
                    val semanticContinuation =
                        if (
                            verification.optBoolean(
                                "success",
                                false
                            )
                        ) {
                            JSONObject()
                                .put(
                                    "success",
                                    false
                                )
                        } else {
                            verifyAppDetailSemanticContinuation(
                                screen =
                                    verification.optJSONObject(
                                        "screen"
                                    )
                                        ?: JSONObject(),
                                section = subpage
                            )
                        }

                    if (
                        verification.optBoolean(
                            "success",
                            false
                        ) ||
                        semanticContinuation.optBoolean(
                            "success",
                            false
                        )
                    ) {
                        val verifiedScreen =
                            verification.optJSONObject(
                                "screen"
                            )
                                ?: semanticContinuation
                                    .optJSONObject(
                                        "screen"
                                    )

                        return JSONObject(
                            clickResult.toString()
                        ).apply {
                            put(
                                "success",
                                true
                            )
                            put(
                                "local_goal_reached",
                                true
                            )
                            put(
                                "verified",
                                true
                            )
                            put(
                                "verification_mode",
                                if (
                                    semanticContinuation.optBoolean(
                                        "success",
                                        false
                                    )
                                ) {
                                    "verified_app_info_semantic_continuation"
                                } else {
                                    "same_context_app_label_and_marker"
                                }
                            )
                            put(
                                "screen",
                                verifiedScreen
                            )
                            put(
                                "message",
                                "Локальная подстраница подтверждена: $target"
                            )
                        }
                    }
                }
            }

            if (
                attempt <
                3
            ) {

                val scrollResult =
                    screenIntelligence
                        .scroll(
                            "down"
                        )

                lastResult =
                    scrollResult

                try {
                    Thread.sleep(
                        120L
                    )
                } catch (_: Exception) {
                }
            }
        }

        return JSONObject(
            lastResult.toString()
        ).apply {
            put(
                "success",
                false
            )
            put(
                "verified",
                false
            )
            put(
                "message",
                "Нужная подстраница не подтверждена по фактическому экрану"
            )
        }
    }

    private fun appDetailClickTargets(
        section: String
    ): List<String> {

        return when (
            section
        ) {

            "permissions" ->
                listOf(
                    "Разрешения",
                    "Permissions"
                )

            "battery" ->
                listOf(
                    "Батарея",
                    "Использование батареи",
                    "Аккумулятор",
                    "Battery"
                )

            "storage" ->
                listOf(
                    "Хранилище",
                    "Память",
                    "Storage"
                )

            "mobile_data" ->
                listOf(
                    "Мобильные данные",
                    "Использование мобильных данных",
                    "Использование данных",
                    "Мобильный трафик",
                    "Mobile data",
"Data usage"
                )

            "notifications" ->
                listOf(
                    "Уведомления",
                    "Notifications"
                )

            "open_by_default" ->
                listOf(
                    "Использование по умолчанию",
                    "По умолчанию",
                    "Открытие ссылок",
                    "Open by default",
                    "Opening links"
                )

            "language" ->
                listOf(
                    "Язык",
                    "Languages",
                    "Language"
                )

            else ->
                emptyList()
        }
    }

    private fun appDetailVerificationMarkers(
        section: String
    ): List<String> {

        return when (
            section
        ) {

            "permissions" ->
                listOf(
                    "разрешен",
                    "permission"
                )

            "battery" ->
                listOf(
                    "батаре",
                    "аккумулятор",
                    "battery"
                )

            "storage" ->
                listOf(
                    "хранилищ",
                    "память",
                    "storage"
                )

            "mobile_data" ->
                listOf(
                    "мобильн",
                    "использование дан",
                    "расход трафик",
                    "mobile data",
                    "data usage"
                )

            "notifications" ->
                listOf(
                    "уведомлен",
                    "notification"
                )

            "open_by_default" ->
                listOf(
                    "по умолчани",
                    "открытие ссыл",
                    "поддерживаем",
                    "open by default",
                    "opening links",
                    "supported links"
                )

            "language" ->
                listOf(
                    "язык",
                    "языки прилож",
                    "language",
                    "app languages"
                )

            "info" ->
                listOf(
                    "информация о приложении",
                    "сведения о приложении",
                    "app info"
                )

            else ->
                emptyList()
        }
    }

    private fun normalizeVerificationText(
        value: String
    ): String {

        return value
            .lowercase(
                Locale.ROOT
            )
            .replace('ё', 'е')
            .replace(
                Regex("[^a-zа-я0-9\\s]"),
                " "
            )
            .replace(
                Regex("\\s+"),
                " "
            )
            .trim()
    }

    /**
     * Preserve an already-proven Settings owner across Samsung transient window-list gaps.
     * This helper never infers foreground from an Intent: it is called only after the caller
     * has verified the actual app-detail screen.
     */
    private fun attestVerifiedSettingsOwnerFromScreen(
        screen: JSONObject,
        source: String
    ): Boolean {

        val windows =
            screen.optJSONArray("windows")
                ?: return false

        var best: JSONObject? = null
        var bestScore = Int.MIN_VALUE

        for (index in 0 until windows.length()) {
            val window = windows.optJSONObject(index) ?: continue

            if (window.optString("package") != "com.android.settings") {
                continue
            }

            val evidenceAge =
                window.optLong("evidence_age_ms", -1L)

            val freshEvidence =
                evidenceAge in 0L..SETTINGS_ATTESTATION_EVIDENCE_MAX_AGE_MS

            val provenContext =
                window.optBoolean("interaction_context", false) ||
                    window.optBoolean("active", false) ||
                    window.optBoolean("focused", false) ||
                    freshEvidence

            if (!provenContext) {
                continue
            }

            var score = 0
            if (window.optBoolean("interaction_context", false)) score += 100
            if (window.optBoolean("focused", false)) score += 80
            if (window.optBoolean("active", false)) score += 60
            if (freshEvidence) score += 40
            if (window.optString("semantic_surface").isNotBlank()) score += 20

            if (score > bestScore) {
                best = window
                bestScore = score
            }
        }

        val provenWindow =
            best
                ?: return false

        return perceptionBridge
            .attestVerifiedForegroundOwner(
                ownerPackage = "com.android.settings",
                windowId = provenWindow.optInt("window_id", -1),
                source = source
            )
    }

    private fun verifyAppDetailSemanticContinuation(
        screen: JSONObject,
        section: String
    ): JSONObject {
        if (!screen.optBoolean("success", false)) {
            return JSONObject()
                .put("success", false)
        }

        val expectedSurface =
            when (section) {
                "notifications" -> "app_notifications"
                "permissions" -> "app_permissions"
                "battery" -> "app_battery"
                "storage" -> "app_storage"
                "open_by_default" -> "app_defaults"
                else -> ""
            }

        if (expectedSurface.isBlank()) {
            return JSONObject()
                .put("success", false)
        }

        val windows =
            screen.optJSONArray("windows")
                ?: return JSONObject()
                    .put("success", false)

        for (index in 0 until windows.length()) {
            val window =
                windows.optJSONObject(index)
                    ?: continue

            if (window.optString("package") != "com.android.settings") {
                continue
            }

            val factualContext =
                window.optBoolean("interaction_context", false) ||
                    window.optBoolean("active", false) ||
                    window.optBoolean("focused", false)

            if (!factualContext) {
                continue
            }

            if (window.optString("semantic_surface") != expectedSurface) {
                continue
            }

            val confidence =
                window.optInt(
                    "semantic_surface_confidence",
                    0
                )

            if (confidence < 80) {
                continue
            }

            val evidenceAge =
                window.optLong(
                    "evidence_age_ms",
                    -1L
                )

            if (
                evidenceAge >= 0L &&
                evidenceAge > SETTINGS_ATTESTATION_EVIDENCE_MAX_AGE_MS
            ) {
                continue
            }

            val windowId =
                window.optInt(
                    "window_id",
                    -1
                )

            perceptionBridge
                .attestVerifiedForegroundOwner(
                    ownerPackage = "com.android.settings",
                    windowId = windowId,
                    source = "app_info_semantic_continuation"
                )

            return JSONObject()
                .put("success", true)
                .put("verified", true)
                .put("surface", expectedSurface)
                .put("confidence", confidence)
                .put("evidence_age_ms", evidenceAge)
                .put("settings_window_id", windowId)
                .put("screen", screen)
        }

        // Samsung large-screen Settings can render the factual detail pane as a
        // sibling application window with an empty package while the left pane
        // remains the active/focused com.android.settings owner. This function
        // is called only after verified App Info + an accepted local row action,
        // so a fresh semantic marker in that sibling pane is valid continuation
        // evidence and must stop any fallback scrolling immediately.
        val ownerWindow =
            (0 until windows.length())
                .mapNotNull { index ->
                    windows.optJSONObject(
                        index
                    )
                }
                .firstOrNull { window ->
                    window.optString(
                        "package"
                    ) ==
                        "com.android.settings" &&
                        (
                            window.optBoolean(
                                "interaction_context",
                                false
                            ) ||
                                window.optBoolean(
                                    "active",
                                    false
                                ) ||
                                window.optBoolean(
                                    "focused",
                                    false
                                )
                            )
                }

        if (ownerWindow != null) {
            val markers =
                appDetailVerificationMarkers(
                    section
                )
                    .map {
                        normalizeVerificationText(
                            it
                        )
                    }
                    .filter {
                        it.isNotBlank()
                    }

            for (index in 0 until windows.length()) {
                val window =
                    windows.optJSONObject(
                        index
                    )
                        ?: continue

                if (
                    window.optString(
                        "type_name"
                    ) ==
                    "input_method"
                ) {
                    continue
                }

                val candidateText =
                    buildString {
                        append(
                            window.optString(
                                "title"
                            )
                        )
                        append(
                            " "
                        )
                        append(
                            window.optString(
                                "verification_text"
                            )
                        )

                        val visible =
                            window.optJSONArray(
                                "visible_text"
                            )

                        if (visible != null) {
                            for (
                                itemIndex in
                                0 until visible.length()
                            ) {
                                append(
                                    " "
                                )
                                append(
                                    visible.optString(
                                        itemIndex
                                    )
                                )
                            }
                        }
                    }

                val normalizedCandidate =
                    normalizeVerificationText(
                        candidateText
                    )

                val markerFound =
                    markers.any { marker ->
                        normalizedCandidate.contains(
                            marker
                        )
                    }

                if (!markerFound) {
                    continue
                }

                val ownerWindowId =
                    ownerWindow.optInt(
                        "window_id",
                        -1
                    )

                perceptionBridge
                    .attestVerifiedForegroundOwner(
                        ownerPackage =
                            "com.android.settings",
                        windowId =
                            ownerWindowId,
                        source =
                            "app_info_split_pane_semantic_continuation"
                    )

                return JSONObject()
                    .put(
                        "success",
                        true
                    )
                    .put(
                        "verified",
                        true
                    )
                    .put(
                        "surface",
                        expectedSurface
                    )
                    .put(
                        "confidence",
                        85
                    )
                    .put(
                        "settings_window_id",
                        ownerWindowId
                    )
                    .put(
                        "detail_window_id",
                        window.optInt(
                            "window_id",
                            -1
                        )
                    )
                    .put(
                        "verification_mode",
                        "verified_app_info_split_pane_marker"
                    )
                    .put(
                        "screen",
                        screen
                    )
            }
        }

        return JSONObject()
            .put("success", false)
    }

    private fun isVerifiedAppDetailScreen(
        screen: JSONObject,
        appTarget: String,
        section: String
    ): Boolean {

        if (!screen.optBoolean("success", false)) {
            return false
        }

        val markers =
            appDetailVerificationMarkers(section)

        if (markers.isEmpty()) {
            return false
        }

        val normalizedMarkers =
            markers
                .map { normalizeVerificationText(it) }
                .filter { it.isNotBlank() }

        val normalizedApp =
            normalizeVerificationText(appTarget)

        val contexts =
            appDetailVerificationContexts(screen)

        if (contexts.isEmpty()) {
            return false
        }

        return contexts.any { contextText ->
            val normalizedContext =
                normalizeVerificationText(contextText)

            if (normalizedContext.isBlank()) {
                return@any false
            }

            val markerFound =
                normalizedMarkers.any { marker ->
                    normalizedContext.contains(marker)
                }

            if (!markerFound) {
                return@any false
            }

            val appFound =
                normalizedApp.isBlank() ||
                    normalizedContext.contains(normalizedApp)

            if (!appFound) {
                return@any false
            }

            if (section != "info") {
                val stillOnAppInfo =
                    normalizedContext.contains("информация о приложении") ||
                        normalizedContext.contains("сведения о приложении") ||
                        normalizedContext.contains("app info")

                if (stillOnAppInfo) {
                    return@any false
                }
            }

            true
        }
    }

    private fun screenVerificationTextForInteraction(
        screen: JSONObject
    ): String {

        val windows = screen.optJSONArray("windows")
        if (windows != null) {
            val values = mutableListOf<String>()
            var hasInteractionContext = false

            for (index in 0 until windows.length()) {
                val window = windows.optJSONObject(index) ?: continue
                if (window.optBoolean("interaction_context", false)) {
                    hasInteractionContext = true
                    val verification =
                        window.optString("verification_text").trim()
                    if (verification.isNotBlank()) {
                        values.add(verification)
                    }
                }
            }

            if (hasInteractionContext) {
                return values.joinToString(" | ")
            }
        }

        return screen.optString("verification_text")
            .ifBlank {
                val visible = screen.optJSONArray("visible_text")
                buildString {
                    if (visible != null) {
                        for (index in 0 until visible.length()) {
                            val value = visible.optString(index).trim()
                            if (value.isBlank()) continue
                            if (isNotEmpty()) append(" | ")
                            append(value)
                        }
                    }
                }
            }
    }

    /**
     * Never prove a terminal screen by combining words from unrelated visible
     * windows. Window Context Manager v1 exposes one visible_text array per
     * context; marker + app label must coexist inside the same context.
     */
    private fun appDetailVerificationContexts(
        screen: JSONObject
    ): List<String> {

        val result =
            mutableListOf<String>()

        val windows =
            screen.optJSONArray("windows")

        if (windows != null) {
            var hasInteractionContext = false
            for (index in 0 until windows.length()) {
                val window = windows.optJSONObject(index) ?: continue
                if (window.optBoolean("interaction_context", false)) {
                    hasInteractionContext = true
                    break
                }
            }

            val structuredWindowContext =
                screen.optString("window_context_mode").isNotBlank()

            // New Window Context snapshots fail closed if no interaction window
            // was selected. Never fall back to combining all visible windows.
            if (structuredWindowContext && !hasInteractionContext) {
                return emptyList()
            }

            for (index in 0 until windows.length()) {
                val window = windows.optJSONObject(index) ?: continue

                if (
                    hasInteractionContext &&
                    !window.optBoolean("interaction_context", false)
                ) {
                    continue
                }

                val typeName =
                    window.optString("type_name")

                if (typeName == "input_method") {
                    continue
                }

                val occlusion =
                    window.optDouble("occlusion_ratio", 0.0)

                if (occlusion >= 0.95) {
                    continue
                }

                val text =
                    window.optString("verification_text").trim()

                if (text.isNotBlank()) {
                    result.add(text)
                }
            }
        }

        if (result.isNotEmpty()) {
            return result
        }

        // Backward-compatible fallback for old snapshots. New v3.6 snapshots
        // should normally take the structured branch above.
        val fallback =
            screen.optString("verification_text")
                .ifBlank {
                    val visible = screen.optJSONArray("visible_text")
                    buildString {
                        if (visible != null) {
                            for (index in 0 until visible.length()) {
                                val value = visible.optString(index).trim()
                                if (value.isBlank()) continue
                                if (isNotEmpty()) append(" | ")
                                append(value)
                            }
                        }
                    }
                }

        return if (fallback.isBlank()) emptyList() else listOf(fallback)
    }

    private fun appDetailVerificationDiagnosticSummary(
        screen: JSONObject
    ): String {

        if (!screen.optBoolean("success", false)) {
            return "screen_success=false"
        }

        val windows = screen.optJSONArray("windows")
            ?: return (
                "legacy_snapshot; package=${screen.optString("package")}; " +
                    "visible=${screen.optJSONArray("visible_text")?.toString().orEmpty().take(500)}"
                ).take(700)

        return buildString {
            append("primary=")
            append(screen.optString("primary_context_id"))
            append("; owner=")
            append(screen.optString("foreground_owner_package"))
            append(" owner_wid=")
            append(screen.optInt("foreground_owner_window_id", -1))
            append(" owner_age=")
            append(screen.optLong("foreground_owner_age_ms", -1L))
            append(" owner_source=")
            append(screen.optString("foreground_owner_source"))
            append(" event_pkg=")
            append(screen.optString("event_package"))
            append(" event_wid=")
            append(screen.optInt("event_window_id", -1))
            append("; windows=")
            append(windows.length())

            val limit = minOf(windows.length(), 5)
            for (index in 0 until limit) {
                val window = windows.optJSONObject(index) ?: continue
                append(" || ")
                append(window.optString("context_id"))
                append(" pkg=")
                append(window.optString("package"))
                append(" type=")
                append(window.optString("type_name"))
                append(" layer=")
                append(window.optInt("layer", 0))
                append(" active=")
                append(window.optBoolean("active", false))
                append(" focused=")
                append(window.optBoolean("focused", false))
                append(" evidence_age=")
                append(window.optLong("evidence_age_ms", -1L))
                append(" content=")
                append(window.optString("content_state"))
                append(" live=")
                append(window.optInt("live_readable_text_count", 0))
                append(" evidence=")
                append(window.optInt("evidence_readable_text_count", 0))
                append(" acq=")
                append(window.optString("acquisition_source"))
                append(" surface=")
                append(window.optString("semantic_surface"))
                append(" surface_conf=")
                append(window.optInt("semantic_surface_confidence", 0))
                append(" title=")
                append(window.optString("title").take(120))
                append(" text=")
                append(
                    window.optJSONArray("visible_text")
                        ?.toString()
                        .orEmpty()
                        .take(260)
                )
            }
        }.take(1800)
    }

    private fun awaitVerifiedAppDetailScreen(
        appTarget: String,
        section: String,
        timeoutMs: Long
    ): JSONObject {

        val deadline =
            System.currentTimeMillis() +
                timeoutMs
.coerceAtLeast(
                        0L
                    )

        var latest =
            JSONObject()
                .put(
                    "success",
                    false
                )

        do {

            latest =
                try {
                    screenIntelligence
                        .getScreenState()
                } catch (_: Exception) {
                    JSONObject()
                        .put(
                            "success",
                            false
                        )
                }

            if (
                isVerifiedAppDetailScreen(
                    screen = latest,
                    appTarget = appTarget,
                    section = section
                )
            ) {
                attestVerifiedSettingsOwnerFromScreen(
                    screen = latest,
                    source = "verified_app_detail_screen"
                )

                return JSONObject()
                    .put(
                        "success",
                        true
                    )
                    .put(
                        "verified",
                        true
                    )
                    .put(
                        "screen",
                        latest
                    )
            }

            if (
                System.currentTimeMillis() >=
                deadline
            ) {
                break
            }

            try {
                Thread.sleep(
                    APP_DETAIL_VERIFY_POLL_MS
                )
            } catch (_: InterruptedException) {
                Thread.currentThread()
                    .interrupt()
                break
            }
} while (
            !cancelRequested &&
            !shuttingDown
        )

        return JSONObject()
            .put(
                "success",
                false
            )
            .put(
                "verified",
                false
            )
            .put(
                "screen",
                latest
            )
    }

    private fun verifySettingsIntentAttestation(
        screen: JSONObject,
        targetPackage: String,
        section: String,
        dispatchedAtMs: Long
    ): JSONObject {
        if (targetPackage.isBlank() || !screen.optBoolean("success", false)) {
            return JSONObject().put("success", false)
        }

        val dispatchAge =
            (System.currentTimeMillis() - dispatchedAtMs)
                .coerceAtLeast(0L)

        if (dispatchAge > APP_DETAIL_VERIFY_TIMEOUT_MS + 1500L) {
            return JSONObject()
                .put("success", false)
                .put("reason", "intent_attestation_stale")
        }

        val expectedSurface =
            when (section) {
                "info" -> setOf("app_info", "app_info_structure")
                "notifications" -> setOf("app_notifications")
                "permissions" -> setOf("app_permissions")
                "battery" -> setOf("app_battery")
                "storage" -> setOf("app_storage")
                "open_by_default" -> setOf("app_defaults")
                else -> emptySet()
            }

        if (expectedSurface.isEmpty()) {
            return JSONObject()
                .put("success", false)
                .put("reason", "surface_not_attestable")
        }

        val windows = screen.optJSONArray("windows") ?: JSONArray()

        for (index in 0 until windows.length()) {
            val window = windows.optJSONObject(index) ?: continue
            if (
                window.optString("package") != "com.android.settings" ||
                !(window.optBoolean("active", false) || window.optBoolean("focused", false))
            ) {
                continue
            }

            val surface = window.optString("semantic_surface").trim()
            val confidence = window.optInt("semantic_surface_confidence", 0)
            val evidenceAge = window.optLong("evidence_age_ms", -1L)

            if (surface !in expectedSurface) {
                continue
            }

            val structuralOnly = surface == "app_info_structure"
            val evidenceFreshEnough =
                !structuralOnly ||
                    (evidenceAge in 0L..SETTINGS_ATTESTATION_EVIDENCE_MAX_AGE_MS)

            val threshold = if (structuralOnly) 70 else 80

            if (confidence >= threshold && evidenceFreshEnough) {
                val settingsWindowId =
                    window.optInt("window_id", -1)

                perceptionBridge
                    .attestVerifiedForegroundOwner(
                        ownerPackage = "com.android.settings",
                        windowId = settingsWindowId,
                        source = "settings_intent_attestation"
                    )

                return JSONObject()
                    .put("success", true)
                    .put("verified", true)
                    .put("surface", surface)
                    .put("confidence", confidence)
                    .put("evidence_age_ms", evidenceAge)
                    .put("dispatch_age_ms", dispatchAge)
                    .put("settings_window_id", settingsWindowId)
                    .put("foreground_owner_handoff", true)
                    .put("target_package", targetPackage)
                    .put("section", section)
                    .put("verification_mode", "exact_intent_plus_same_window_semantic_surface")
            }
        }

        return JSONObject()
            .put("success", false)
            .put("reason", "semantic_surface_not_proven")
            .put("target_package", targetPackage)
            .put("section", section)
    }

    private fun extractSettingsAppSearchTarget(
        command: String
    ): String? {

        val c =
            command
                .lowercase(
                    Locale.getDefault()
                )
                .replace('ё', 'е')
                .replace(
                    Regex("\\s+"),
                    " "
                )
                .trim()

        // ACCESSIBILITY ROUTE GUARD v2.7.4.5
        // The word «приложения» is not enough to mean Settings > Apps.
        // Accessibility screens also contain phrases such as
        // «установленные приложения/службы». Those tasks must stay with
        // Planner + Screen Intelligence so AYANA can reach the service page.
        val accessibilityContext =
            listOf(
                "специальные возможност",
                "спец возможност",
                "accessibility",
                "установленные службы",
                "установленных служб",
                "служба специальных возможностей"
            ).any { marker ->
                c.contains(marker)
            }

        if (accessibilityContext) {
            return null
        }

        // Only collapse a command to App info when the user explicitly
        // describes the normal Settings > Apps route. Merely mentioning an
        // installed application somewhere in a longer goal is not sufficient.
        val explicitAppsRoute =
            listOf(
                "зайди в приложени",
                "зайти в приложени",
                "перейди в приложени",
                "перейти в приложени",
                "открой приложени",
                "открыть приложени",
                "раздел приложени",
                "настройки приложени",
                "список приложени"
            ).any { marker ->
                c.contains(marker)
            }

        if (!explicitAppsRoute) {
            return null
        }

        val markers =
            listOf(
                "найди приложение ",
                "найти приложение ",
                "найди ",
                "найти ",
"поищи ",
                "выбери "
            )

        var bestIndex =
            -1

        var bestMarker =
            ""

        for (marker in markers) {
            val index =
                c.lastIndexOf(marker)

            if (
                index > bestIndex ||
                (
                    index == bestIndex &&
                    marker.length > bestMarker.length
                )
            ) {
                bestIndex =
                    index
                bestMarker =
                    marker
            }
        }

        if (bestIndex < 0) {
            return null
        }

        var target =
            c
                .substring(
                    bestIndex +
                        bestMarker.length
                )
                .trim()

        // Keep only the app name when the command continues with another goal.
        val tailMarkers =
            listOf(
                " и останов",
                " останов",
                " и зайди ",
                " и перейди ",
                " потом ",
                " затем ",
                " после этого ",
                " и открой "
            )

        val tailIndex =
            tailMarkers
                .map { marker ->
                    target.indexOf(marker)
                }
                .filter { index ->
                    index >= 0
                }
                .minOrNull()
                ?: -1

        if (tailIndex >= 0) {
            target =
                target
                    .substring(
                        0,
                        tailIndex
                    )
                    .trim()
        }

        target =
            target
                .trim(
                    '"',
                    '\'',
                    '«',
                    '»',
                    '.',
                    ',',
                    '!',
                    '?'
                )

        if (
            target.isBlank() ||
            target in
                setOf(
                    "приложение",
                    "приложения",
                    "нужное приложение"
                )
        ) {
            return null
        }

        return target
    }

    /**
     * R9.7.1 conversation-vs-execution truth.
     *
     * Capability words are DATA until the user actually asks AYANA to perform an
     * external/development action. A sentence may mention GitHub/commit/push/APK
     * while criticising, comparing or discussing AYANA; keyword presence alone must
     * never manufacture an execution intent.
     */
    private fun normalizedConversationIntentText(
        command: String
    ): String {
        var normalized =
            normalizeRecognitionText(
                command
            )
                .replace(
                    Regex(
                        "^(?:аяна|ayana)\\s+"
                    ),
                    ""
                )
                .trim()

        // Remove discourse/politeness lead-ins only from the beginning. The remaining
        // first semantic token owns intent; words inside the sentence are never enough.
        repeat(4) {
            val stripped =
                normalized
                    .replace(
                        Regex(
                            "^(?:а|ну|но|так|слушай|смотри|вообще|короче|пожалуйста)\\s+"
                        ),
                        ""
                    )
                    .trim()

            if (stripped == normalized) {
                return normalized
            }

            normalized = stripped
        }

        return normalized
    }

    private fun hasExplicitUnavailableExecutionIntent(
        command: String
    ): Boolean {
        val c =
            normalizedConversationIntentText(
                command
            )

        if (c.isBlank()) {
            return false
        }

        val directImperative =
            Regex(
                "^(?:измени|запиши|обнови|загрузи|удали|сделай|сделайте|делай|делайте|выполни|выполните|выполняй|выполняйте|запусти|отправь|собери|подпиши|дай|передай|закоммить|закоммитьте|коммить|коммитьте|запушь|запушьте|пушь|пушьте|commit|push|коммит|пуш)(?:\\s|$)"
            )
                .containsMatchIn(
                    c
                )

        val modalExecutionRequest =
            Regex(
                "^(?:можешь|сможешь)\\s+(?!ли(?:\\s|$))(?:мне\\s+)?(?:изменить|записать|обновить|загрузить|удалить|сделать|выполнить|запустить|отправить|собрать|подписать|дать|передать|закоммитить|запушить|commit|push|коммит|пуш)(?:\\s|$)"
            )
                .containsMatchIn(
                    c
                )

        val explicitApkDeliveryRequest =
            Regex(
                "^(?:мне\\s+)?(?:дай|передай)\\s+(?:мне\\s+)?(?:готовый\\s+)?(?:apk|апк)(?:\\s|$)"
            )
                .containsMatchIn(
                    c
                )

        val explicitDesiredExecution =
            Regex(
                "^(?:(?:я\\s+)?хочу|мне\\s+(?:нужно|надо)|нужно|надо)\\s+(?:чтобы\\s+ты\\s+)?(?:изменил(?:а)?|изменить|записал(?:а)?|записать|обновил(?:а)?|обновить|загрузил(?:а)?|загрузить|удалил(?:а)?|удалить|сделал(?:а)?|сделать|выполнил(?:а)?|выполнить|запустил(?:а)?|запустить|отправил(?:а)?|отправить|собрал(?:а)?|собрать|подписал(?:а)?|подписать|дал(?:а)?|дать|передал(?:а)?|передать|закоммитил(?:а)?|закоммитить|запушил(?:а)?|запушить)(?:\\s|$)"
            )
                .containsMatchIn(
                    c
                )

        return directImperative ||
            modalExecutionRequest ||
            explicitApkDeliveryRequest ||
            explicitDesiredExecution
    }

    private fun hasExplicitAgentSideEffectIntent(
        command: String
    ): Boolean {
        val c =
            normalizedConversationIntentText(
                command
            )

        if (c.isBlank()) {
            return false
        }

        val modalSideEffectRequest =
            Regex(
                "^(?:можешь|сможешь)\\s+(?!ли(?:\\s|$))(?:мне\\s+)?(?:открыть|закрыть|свернуть|запустить|включить|выключить|установить|поставить|уменьшить|увеличить|создать|удалить|скопировать|копировать|записать|поместить|сохранить|положить|нажать|выбрать|перейти|зайти|проверить|выполнить|напомнить)(?:\\s|$)"
            )
                .containsMatchIn(
                    c
                )

        val desiredSideEffectRequest =
            Regex(
                "^(?:(?:я\\s+)?хочу|мне\\s+(?:нужно|надо)|нужно|надо)\\s+(?:чтобы\\s+ты\\s+)?(?:открыл(?:а)?|открыть|закрыл(?:а)?|закрыть|свернул(?:а)?|свернуть|запустил(?:а)?|запустить|включил(?:а)?|включить|выключил(?:а)?|выключить|установил(?:а)?|установить|поставил(?:а)?|поставить|уменьшил(?:а)?|уменьшить|увеличил(?:а)?|увеличить|создал(?:а)?|создать|удалил(?:а)?|удалить|скопировал(?:а)?|скопировать|записал(?:а)?|записать|сохранил(?:а)?|сохранить|нажал(?:а)?|нажать|выбрал(?:а)?|выбрать|перешел|перешла|перейти|зашел|зашла|зайти|проверил(?:а)?|проверить|выполнил(?:а)?|выполнить|напомнил(?:а)?|напомнить)(?:\\s|$)"
            )
                .containsMatchIn(
                    c
                )

        return AGENT_FAIL_CLOSED_ACTION_PREFIXES.any { prefix ->
                c.startsWith(
                    prefix
                )
            } ||
            modalSideEffectRequest ||
            desiredSideEffectRequest ||
            hasExplicitUnavailableExecutionIntent(
                c
            )
    }

    private fun agentConversationGuidance(
        message: String
    ): String {
        val c =
            normalizeRecognitionText(
                message
            )

        val broadAutonomyQuestion =
            (
                c.contains("что ты умеешь") ||
                    c.contains("что умеешь") ||
                    c.contains("что ты можешь") ||
                    c.contains("твои возможности") ||
                    c.contains("твои функции")
                ) &&
                (
                    c.contains("автоном") ||
                        c.contains("ии агент") ||
                        c.contains("ai agent") ||
                        c.contains("ai агент")
                    )

        return buildString {
            append(
                "R9.7.1 CONVERSATION INTENT POLICY: capability names mentioned inside discussion, criticism, comparison or explanation are data, not execution requests. Treat an external/development action as requested only when the user explicitly asks to perform it. "
            )
            append(
                "A complete read-only conversational answer must not be converted into an execution failure merely because the user used criticism or a statement instead of a question. "
            )

            if (broadAutonomyQuestion) {
                append(
                    "For this broad autonomy/capability question, lead with verified positive autonomous capabilities and the main functional gaps. Do not volunteer GitHub/commit/push/APK limitations unless the user directly asks about development tooling or those limits are necessary to answer the current goal. "
                )
            }
        }
            .trim()
    }

    private fun extractGitHubClientIdConfiguration(
        command: String
    ): String? {
        val patterns =
            listOf(
                Regex(
                    "(?i)^\\s*(?:настрой|сохрани|установи)\\s+(?:github|гитхаб)\\s+(?:app\\s+)?client[_ -]?id\\s+([A-Za-z0-9_.-]{8,160})\\s*$"
                ),
                Regex(
                    "(?i)^\\s*(?:github|гитхаб)\\s+(?:app\\s+)?client[_ -]?id\\s+([A-Za-z0-9_.-]{8,160})\\s*$"
                )
            )

        patterns.forEach { pattern ->
            val match = pattern.find(command)
            if (match != null) {
                return match.groupValues.getOrNull(1)?.trim()
            }
        }

        return null
    }

    private fun isGitHubConnectRequest(
        normalized: String
    ): Boolean {
        val c = normalized.trim()
        return c.matches(
            Regex(
                "^(?:подключи|подключить|авторизуй|авторизовать|подсоедини|подсоединить)\\s+(?:github|гитхаб)(?:\\s+(?:к\\s+ayana|к\\s+аяна|для\\s+ayana|для\\s+аяна))?$"
            )
        )
    }

    private fun isGitHubStatusRequest(
        normalized: String
    ): Boolean {
        val c = normalized.trim()
        return c.matches(
            Regex(
                "^(?:(?:проверь|проверить)(?:\\s+подключение)?\\s+(?:github|гитхаб)|(?:статус|состояние)\\s+(?:github|гитхаб)|(?:github|гитхаб)\\s+(?:статус|состояние))$"
            )
        )
    }

    private fun isGitHubActionsReadinessRequest(
        normalized: String
    ): Boolean {
        val c = normalized.trim()
        val mentionsActions =
            c.contains("github actions") ||
                c.contains("гитхаб actions") ||
                c.contains("github экшен") ||
                c.contains("гитхаб экшен")
        val readiness =
            c.contains("готов") ||
                c.contains("доступ") ||
                c.contains("разреш") ||
                c.contains("проверь") ||
                c.contains("проверить")

        return mentionsActions &&
            readiness &&
            !c.contains("собери") &&
            !c.contains("собрать") &&
            !c.contains("запусти") &&
            !c.contains("запустить")
    }

    private fun isGitHubBuildStatusRequest(
        normalized: String
    ): Boolean {
        val c = normalized.trim()
        val buildMention =
            c.contains("сборк") ||
                c.contains("build")
        val githubMention =
            c.contains("github") ||
                c.contains("гитхаб")
        val statusIntent =
            c.contains("проверь") ||
                c.contains("проверить") ||
                c.contains("статус") ||
                c.contains("состояние") ||
                c.contains("готова ли") ||
                c.contains("готов ли")

        return buildMention &&
            githubMention &&
            statusIntent &&
            !c.contains("готовност")
    }

    private fun isDevelopmentTransactionStatusRequest(
        normalized: String
    ): Boolean {
        val c = normalized.trim()
        return c.contains("транзакц") &&
            c.contains("разработ") &&
            (
                c.contains("проверь") ||
                    c.contains("проверить") ||
                    c.contains("статус") ||
                    c.contains("состояние")
                ) &&
            !c.contains("откат") &&
            !c.contains("прими") &&
            !c.contains("принять") &&
            !c.contains("отмени")
    }

    private fun isDevelopmentTransactionAcceptRequest(
        normalized: String
    ): Boolean {
        val c = normalized.trim()
        return c.matches(
            Regex("^(?:прими|принять|подтверди принятие|подтвердить принятие)\\s+(?:текущую\\s+)?транзакц\\p{L}*\\s+разработ\\p{L}*$")
        )
    }

    private fun isDevelopmentTransactionRollbackRequest(
        normalized: String
    ): Boolean {
        val c = normalized.trim()
        return c.matches(
            Regex("^(?:откати|откатить|верни назад)\\s+(?:текущую\\s+)?транзакц\\p{L}*\\s+разработ\\p{L}*$")
        )
    }

    private fun isDevelopmentTransactionCancelPreparedRequest(
        normalized: String
    ): Boolean {
        val c = normalized.trim()
        return c.matches(
            Regex("^(?:отмени|отменить)\\s+(?:текущую\\s+)?транзакц\\p{L}*\\s+разработ\\p{L}*$")
        )
    }

    private fun runLocalGitHubSetupOrStatusIfMatched(
        originalCommand: String,
        routingNormalized: String,
        silent: Boolean
    ): Boolean {
        val clientId = extractGitHubClientIdConfiguration(originalCommand)

        val result =
            when {
                clientId != null ->
                    githubRepositoryExecutor.configureClientId(clientId)

                isGitHubConnectRequest(routingNormalized) ->
                    githubRepositoryExecutor.startDeviceFlow()

                isDevelopmentTransactionRollbackRequest(routingNormalized) ->
                    executeAgentTool(
                        "github_development_transaction_control",
                        JSONObject().put("action", "rollback"),
                        trustedUserConfirmation = true
                    )

                isDevelopmentTransactionAcceptRequest(routingNormalized) ->
                    executeAgentTool(
                        "github_development_transaction_control",
                        JSONObject().put("action", "accept"),
                        trustedUserConfirmation = true
                    )

                isDevelopmentTransactionCancelPreparedRequest(routingNormalized) ->
                    executeAgentTool(
                        "github_development_transaction_control",
                        JSONObject().put("action", "cancel"),
                        trustedUserConfirmation = true
                    )

                isDevelopmentTransactionStatusRequest(routingNormalized) ->
                    githubRepositoryExecutor.developmentTransactionStatus()

                isGitHubBuildStatusRequest(routingNormalized) ->
                    githubRepositoryExecutor.buildStatus()

                isGitHubActionsReadinessRequest(routingNormalized) ->
                    githubRepositoryExecutor.actionsStatus()

                isGitHubStatusRequest(routingNormalized) ->
                    githubRepositoryExecutor.status(allowPendingPoll = true)

                else ->
                    return false
            }

        if (
            result.optBoolean("success", false) &&
            result.optString("status") in
                setOf(
                    "development_transaction_accepted",
                    "development_transaction_rolled_back",
                    "development_transaction_cancelled"
                )
        ) {
            finalizeDevelopmentTransactionDurableGoal(result)
        }

        val message =
            result.optString(
                "message",
                if (result.optBoolean("success", false)) {
                    "GitHub операция выполнена."
                } else {
                    "GitHub операция не выполнена."
                }
            )

        val successfulSetupStep = result.optBoolean("success", false)

        respondAndResume(
            text = message,
            silent = silent,
            success = successfulSetupStep,
            technical =
                JSONObject(result.toString())
                    .apply {
                        remove("access_token")
                        remove("refresh_token")
                        remove("device_code")
                    }
                    .toString()
                    .take(1800)
        )

        return true
    }

    private fun finalizeDevelopmentTransactionDurableGoal(
        result: JSONObject
    ) {
        val transactionId = result.optString("transaction_id").trim()
        if (transactionId.isBlank()) return

        val goals =
            try {
                durableGoalStore.getRecoverableJson(20)
            } catch (_: Exception) {
                JSONArray()
            }

        for (index in 0 until goals.length()) {
            val goal = goals.optJSONObject(index) ?: continue
            if (goal.optString("last_tool_name") != "github_development_transaction") continue

            val lastResult =
                try {
                    JSONObject(goal.optString("last_result"))
                } catch (_: Exception) {
                    JSONObject()
                }

            if (lastResult.optString("transaction_id") != transactionId) continue

            val goalId = goal.optString("id")
            try {
                if (result.optString("status") == "development_transaction_cancelled") {
                    durableGoalStore.markCancelled(
                        goalId,
                        "Development transaction отменена до GitHub mutation."
                    )
                } else {
                    durableGoalStore.markCompleted(
                        goalId,
                        result.optString("message", "Development transaction завершена.")
                    )
                }

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "development_transaction_goal_finalized",
                    message = result.optString("status"),
                    details = "goal_id=$goalId; transaction_id=$transactionId"
                )
            } catch (_: Exception) {
            }
            break
        }
    }

    private fun unsupportedExecutionCapabilityReason(
        command: String
    ): String? {
        val c =
            command
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()

        if (c.isBlank()) {
            return null
        }

        // R9.7.1: negative capability terminal truth is an EXECUTION guard, not a
        // keyword detector. Discussion of a limitation must reach normal conversation.
        if (
            !hasExplicitUnavailableExecutionIntent(
                c
            )
        ) {
            return null
        }

        // R10.27.3: GitHub write, fixed APK build and bounded development transaction are implemented and must reach
        // Agent Core + the two-phase github_apk_build executor. Only direct delivery /
        // download / installation remains unsupported in this checkpoint.
        val apkDeliveryOrInstall =
            (c.contains("apk") || c.contains("апк")) &&
                (
                    c.contains("дай мне apk") ||
                        c.contains("дай мне апк") ||
                        c.contains("передай apk") ||
                        c.contains("передай апк") ||
                        c.contains("отправь apk") ||
                        c.contains("отправь апк") ||
                        c.contains("скачай apk") ||
                        c.contains("скачай апк") ||
                        c.contains("установи apk") ||
                        c.contains("установи апк") ||
                        c.contains("установить apk") ||
                        c.contains("установить апк")
                    )

        if (!apkDeliveryOrInstall) {
            return null
        }

        return "R10.27.3 уже умеет commit/push, доказательно проверить APK build и выполнять bounded development transaction с rollback, " +
            "но прямое скачивание/передача/установка APK на планшет пока не реализованы и не должны подменяться ложным SUCCESS."

    }

    private data class DirectAppDetailFinalGoal(
        val appName: String,
        val section: String
    )

    /**
     * v12.14: A verification suffix does not create a second side effect.
     * "Открой Камеру и проверь, что на переднем плане Камера" is one app-open
     * goal whose existing lifecycle executor already verifies the fresh package.
     */
    private fun extractVerifiedAppOpenRequest(
        command: String
    ): Pair<String, String?>? {
        val c =
            normalizeLifecycleRoutingText(
                command
            )

        val match =
            Regex(
                """^(?:открой|открыть|запусти|запустить|включи|включить)(?:\s+мне)?\s+(?:приложени\p{L}*\s+|программ\p{L}*\s+)?(.+?)\s+и\s+(?:проверь|проверить|убедись|убедиться|подтверди|подтвердить)(?=\s|[,.:;!?—-]|$)(.*)$"""
            )
                .find(c)
                ?: return null

        val target =
            match.groupValues
                .getOrNull(1)
                .orEmpty()
                .trim()

        val verificationTail =
            match.groupValues
                .getOrNull(2)
                .orEmpty()
                .trim()

        if (
            target.isBlank() ||
            verificationTail.isBlank() ||
            target in LIFECYCLE_INVALID_TARGETS
        ) {
            return null
        }

        val foregroundIntent =
            verificationTail.contains("передн") &&
                (
                    verificationTail.contains("план") ||
                        verificationTail.contains("экран")
                    ) ||
                verificationTail.contains("foreground")

        if (!foregroundIntent) {
            return null
        }

        val verifyTarget =
            Regex(
                """(?:^|[,\s])(?:что\s+)?(?:на\s+)?(?:передн\p{L}*\s+(?:план\p{L}*|экран\p{L}*)|foreground)(?:\s+сейчас)?(?:\s+именно)?(?:\s+(?:находится|открыт[ао]?|это))?\s+(.+)$"""
            )
                .find(verificationTail)
                ?.groupValues
                ?.getOrNull(1)
                ?.trim()
                ?.trim(' ', '"', '«', '»', '.', ',', '!', '?')
                ?.takeIf { it.isNotBlank() }

        return target to verifyTarget
    }

    /**
     * Collapses a safe read-only Settings>Apps path to its observable final target.
     * This preserves the user's goal while avoiding a brittle literal navigation route.
     */
    private fun extractCompositeAppDetailFinalGoal(
        command: String
    ): DirectAppDetailFinalGoal? {
        val appTarget =
            extractSettingsAppSearchTarget(
                command
            )
                ?.trim()
                ?.takeIf { it.isNotBlank() }
                ?: return null

        val c =
            command
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()

        // Require an explicit continuation to a final app-detail section.
        if (
            !c.contains(" и ") &&
            !c.contains(" затем ") &&
            !c.contains(" потом ") &&
            !c.contains(" после этого ")
        ) {
            return null
        }

        val section =
            when {
                c.contains("разрешен") -> "permissions"
                c.contains("батаре") || c.contains("аккумулятор") -> "battery"
                c.contains("хранилищ") || c.contains("памят") -> "storage"
                c.contains("мобильн") && c.contains("данн") -> "mobile_data"
                c.contains("уведомлен") -> "notifications"
                c.contains("открыт") && c.contains("по умолч") -> "open_by_default"
                c.contains("ссылк") && c.contains("по умолч") -> "open_by_default"
                c.contains("язык") -> "language"
                c.contains("информац") || c.contains("сведени") -> "info"
                else -> null
            }
                ?: return null

        return DirectAppDetailFinalGoal(
            appName = appTarget,
            section = section
        )
    }

    private enum class AggregateMetric {
        BATTERY,
        NETWORK,
        STORAGE,
        MEDIA_VOLUME,
        BRIGHTNESS,
        ORIENTATION
    }

    /**
     * Detect read-only multi-metric requests before the single-metric structured router.
     * A state-changing or artifact-producing goal is deliberately excluded.
     */
    private fun extractRequestedAggregateMetrics(
        command: String
    ): Set<AggregateMetric> {
        val artifactGoal =
            requestsArtifactDeliverable(command)

        val c =
            command
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()

        val readIntent =
            listOf(
                "проверь",
                "покажи",
                "скажи",
                "какой",
                "какая",
                "каково",
                "сколько",
                "состояни",
                "параметр",
                "текущ",
                "статус"
            ).any { c.contains(it) }

        if (!readIntent) {
            return emptySet()
        }

        val stateChangingMarkers =
            listOf(
                "установи",
                "установить",
                "открой",
                "открыть",
                "запусти",
                "запустить",
                "зайди",
                "зайти",
                "перейди",
                "перейти",
                "нажми",
                "нажать",
                "выбери",
                "выбрать",
                "найди",
                "найти",
                "измени",
                "изменить",
                "увелич",
                "уменьш",
                "включи",
                "выключи",
                "закрой",
                "сверни",
                "удали",
                "очисти"
            ) +
                if (artifactGoal) {
                    emptyList()
                } else {
                    listOf(
                        "создай",
                        "создать",
                        "сделай",
                        "сделать"
                    )
                }

        if (stateChangingMarkers.any { c.contains(it) }) {
            return emptySet()
        }

        val result =
            linkedSetOf<AggregateMetric>()

        if (c.contains("батар") || c.contains("заряд") || c.contains("аккумулятор")) {
            result += AggregateMetric.BATTERY
        }

        if (
            c.contains("интернет") ||
            c.contains("подключен") ||
            c.contains("сеть") ||
            c.contains("wi-fi") ||
            c.contains("wifi")
        ) {
            result += AggregateMetric.NETWORK
        }

        if (c.contains("хранилищ") || c.contains("свободн") && c.contains("мест")) {
            result += AggregateMetric.STORAGE
        }

        if (c.contains("громкост")) {
            result += AggregateMetric.MEDIA_VOLUME
        }

        if (c.contains("яркост")) {
            result += AggregateMetric.BRIGHTNESS
        }

        if (c.contains("ориентац") || c.contains("альбомн") || c.contains("портретн")) {
            result += AggregateMetric.ORIENTATION
        }

        // R10.24 freshness rule for broad current-state artifacts. If the user asks for
        // a file/presentation about the *current* tablet/device state without naming
        // individual metrics, capture one fresh local snapshot instead of silently using
        // historical Agent context as if it were current.
        if (
            result.isEmpty() &&
            artifactGoal &&
            (c.contains("текущ") || c.contains("сейчас")) &&
            (c.contains("состояни") || c.contains("параметр") || c.contains("статус")) &&
            (c.contains("планш") || c.contains("устройств"))
        ) {
            result += AggregateMetric.BATTERY
            result += AggregateMetric.NETWORK
            result += AggregateMetric.STORAGE
            result += AggregateMetric.MEDIA_VOLUME
            result += AggregateMetric.BRIGHTNESS
            result += AggregateMetric.ORIENTATION
        }

        return result
    }

    /**
     * Production ownership rule for local aggregate metric reads.
     *
     * Multi-metric reads stay local as before. NETWORK is additionally allowed as a
     * single metric because network truth is a deterministic device fact and must not
     * fall through to Agent Core where missing tool evidence could become false SUCCESS.
     */
    private fun aggregateMetricLocalRouteEligible(
        metrics: Set<AggregateMetric>
    ): Boolean =
        metrics.size >= 2 ||
            (
                metrics.size == 1 &&
                    AggregateMetric.NETWORK in metrics
                )

    /**
     * Completion ownership gate for aggregate device reads.
     *
     * The local executor is intentionally conservative: it terminal-completes only a
     * presentation-only request whose meaningful tokens are covered by read/metric/summary
     * vocabulary. Any other semantic residue is treated as an unfinished goal and is handed
     * to Agent Core with the already verified snapshot. This is safer than maintaining a
     * growing list of special phrases such as "если" or "сделай вывод".
     */
    private fun aggregateMetricHasRemainingSemanticGoal(
        command: String
    ): Boolean {
        val normalized =
            command
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("[^\\p{L}\\p{N}%]+"), " ")
                .replace(Regex("\\s+"), " ")
                .trim()

        if (normalized.isBlank()) {
            return false
        }

        val neutralWords =
            setOf(
                "и", "или", "а", "но", "в", "во", "на", "из", "к", "ко", "с", "со",
                "по", "о", "об", "для", "мне", "мой", "моем", "моём", "этом", "этого",
                "сейчас", "теперь", "ли", "есть", "между", "все", "всё"
            )

        val presentationRoots =
            listOf(
                "пров", "покаж", "ска", "како", "сколь", "состоя", "статус",
                "устрой", "планш", "парамет", "показател",
                "заряд", "батар", "аккумуля",
                "интернет", "подключ", "сет", "wifi", "вайф",
                "хранил", "свобод", "мест", "памят",
                "громк", "мультимед", "ярк", "ориент", "альбом", "портрет",
                "три", "трех", "трём", "трем", "два", "двум", "перв", "втор", "один",
                "затем", "потом", "после", "дай", "общ", "еди", "результ", "итог",
                "текущ", "параметр"
            )

        return normalized
            .split(' ')
            .filter { it.isNotBlank() }
            .any { token ->
                if (
                    token in neutralWords ||
                    token.toDoubleOrNull() != null ||
                    token.endsWith("%") && token.dropLast(1).toDoubleOrNull() != null
                ) {
                    false
                } else {
                    presentationRoots.none { root ->
                        token.startsWith(root)
                    }
                }
            }
    }

    private fun verifiedAggregateFactsPayload(
        metrics: Set<AggregateMetric>,
        state: JSONObject,
        summary: String
    ): String {
        val facts = JSONObject()
            .put("provenance", "android_local_verified_snapshot")
            .put("fresh_current_snapshot", true)
            .put("captured_at_ms", System.currentTimeMillis())
            .put("captured_local_datetime", LocalDateTime.now().toString())
            .put("summary", summary)
            .put("requested_metrics", JSONArray(metrics.map { it.name }))

        fun copyIfPresent(key: String) {
            if (state.has(key)) {
                facts.put(key, state.opt(key))
            }
        }

        if (AggregateMetric.BATTERY in metrics) {
            listOf(
                "battery_percent",
                "charging"
            ).forEach(::copyIfPresent)
        }

        if (AggregateMetric.NETWORK in metrics) {
            listOf(
                "network_observation_available",
                "network_connected",
                "network_validated",
                "network_transport",
                "network_observation_error"
            ).forEach(::copyIfPresent)
        }

        if (AggregateMetric.STORAGE in metrics) {
            listOf(
                "storage_free_bytes",
                "storage_total_bytes"
            ).forEach(::copyIfPresent)
        }
if (AggregateMetric.MEDIA_VOLUME in metrics) {
            listOf(
                "media_volume",
                "media_volume_max"
            ).forEach(::copyIfPresent)
        }

        if (AggregateMetric.BRIGHTNESS in metrics) {
            copyIfPresent(
                "brightness_percent"
            )
        }

        if (AggregateMetric.ORIENTATION in metrics) {
            copyIfPresent(
                "orientation"
            )
        }

        return facts.toString()
    }

    private fun runLocalMultiMetricCommand(
        metrics: Set<AggregateMetric>,
        command: String,
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_multi_device_metric",
            executor = "multi_device_metric_executor"
        )

        val state =
            try {
                agentGetDeviceState()
            } catch (_: Exception) {
                JSONObject()
            }

        val parts =
            mutableListOf<String>()

        val missing =
            mutableListOf<String>()

        for (metric in metrics) {
            when (metric) {
                AggregateMetric.BATTERY -> {
                    val battery = state.optInt("battery_percent", -1)
                    if (battery >= 0) {
                        parts +=
                            "заряд батареи $battery%" +
                                if (state.optBoolean("charging", false)) " (заряжается)" else ""
                    } else {
                        missing += "battery"
                    }
                }

                AggregateMetric.NETWORK -> {
                    val observationAvailable =
                        state.optBoolean(
                            "network_observation_available",
                            state.has("network_connected")
                        )

                    if (observationAvailable && state.has("network_connected")) {
                        val connected = state.optBoolean("network_connected", false)
                        val validated = state.optBoolean("network_validated", false)
                        val transport = state.optString("network_transport", "unknown")
                        val transportLabel =
                            when (transport) {
                                "wifi" -> "Wi-Fi"
                                "cellular" -> "мобильную сеть"
                                "ethernet" -> "Ethernet"
                                "vpn" -> "VPN"
                                "other" -> "другой транспорт"
                                else -> transport
                            }
                        parts +=
                            if (connected) {
                                "сеть активна" +
                                    (
                                        if (validated) {
                                            ", доступ в интернет подтверждён Android"
                                        } else {
                                            ", доступ в интернет Android пока не подтвердил"
                                        }
                                    ) +
                                    (
                                        if (
                                            transport.isNotBlank() &&
                                            transport != "unknown" &&
                                            transport != "none"
                                        ) {
                                            " через $transportLabel"
                                        } else {
                                            ""
                                        }
                                    )
                            } else {
                                "активное интернет-подключение не обнаружено"
                            }
                    } else {
                        missing += "network"
                    }
                }

                AggregateMetric.STORAGE -> {
                    val free = state.optLong("storage_free_bytes", -1L)
                    val total = state.optLong("storage_total_bytes", -1L)
                    if (free >= 0L && total > 0L) {
                        parts += "хранилище: свободно ${formatStorageGiB(free)} ГБ из ${formatStorageGiB(total)} ГБ"
                    } else {
                        missing += "storage"
                    }
                }

                AggregateMetric.MEDIA_VOLUME -> {
                    val current = state.optInt("media_volume", -1)
                    val max = state.optInt("media_volume_max", -1)
                    if (current >= 0 && max > 0) {
                        parts += "громкость мультимедиа $current из $max"
                    } else {
                        missing += "media_volume"
                    }
                }

                AggregateMetric.BRIGHTNESS -> {
                    val brightness = state.optInt("brightness_percent", -1)
                    if (brightness >= 0) {
                        parts += "яркость примерно $brightness%"
                    } else {
                        missing += "brightness"
                    }
                }

                AggregateMetric.ORIENTATION -> {
                    val orientation = state.optString("orientation")
                    if (orientation.isNotBlank() && orientation != "unknown") {
                        parts +=
                            "ориентация " +
                                when (orientation) {
                                    "landscape" -> "альбомная"
                                    "portrait" -> "портретная"
                                    else -> orientation
                                }
                    } else {
                        missing += "orientation"
                    }
                }
            }
        }

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = if (missing.isEmpty()) "multi_metric_verified" else "multi_metric_incomplete",
            message =
                if (missing.isEmpty()) {
                    "Все запрошенные метрики устройства получены"
                } else {
                    "Часть запрошенных метрик устройства недоступна"
                },
            details =
                "requested=${metrics.joinToString(",")}; missing=${missing.joinToString(",")}; state=${state.toString().take(1200)}"
        )

        val answer =
            if (parts.isEmpty()) {
                "Не удалось получить запрошенные параметры устройства."
            } else {
                "Состояние планшета: ${parts.joinToString("; ")}."
            }

        if (missing.isNotEmpty()) {
            respondAndResume(
                text = answer + " Не получены: ${missing.joinToString(", ")}.",
                silent = silent,
                success = false,
                technical = "multi_metric_incomplete:${missing.joinToString(",")}"
            )
            return
        }

        if (aggregateMetricHasRemainingSemanticGoal(command)) {
            val verifiedFacts =
                verifiedAggregateFactsPayload(
                    metrics = metrics,
                    state = state,
                    summary = answer
                )

            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "multi_metric_remaining_goal_handoff",
                message = "Метрики подтверждены; исходная цель требует дальнейшего смыслового завершения",
                details =
                    "requested=${metrics.joinToString(",")}; terminal=RUNNING; facts=${verifiedFacts.take(1200)}"
            )

            askAyana(
                message = command,
                silent = silent,
                verifiedDeviceFacts = verifiedFacts
            )
            return
        }

        finishLocalCommand(
            answer,
            silent
        )
    }

    private fun requestsArtifactDeliverable(
        command: String
    ): Boolean {
        val c =
            command
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()

        val action =
            Regex(
                """(?:^|\s)(?:создай|создать|сделай|сделать|сгенерируй|сгенерировать|сохрани|сохранить|экспортируй|экспортировать|подготовь|подготовить|сформируй|сформировать|выгрузи|выгрузить)(?=\s|$)"""
            )
                .containsMatchIn(c) ||
                Regex("""(?:^|\s)дай\s+(?:мне\s+)?(?:готовый\s+)?[^.!?]{0,80}\bфайл\b""")
                    .containsMatchIn(c)

        if (!action) {
            return false
        }

        return listOf(
            "файл",
            "документ",
            "txt",
            "docx",
            "word",
            "ворд",
            "pdf",
            "пдф",
            "xlsx",
            "excel",
            "эксел",
            "pptx",
            "powerpoint",
            "power point",
            "пауэрпоинт",
            "паверпоинт",
            "презентац",
            "jpeg",
"jpg",
            "изображен",
            "график",
"диаграмм"
        ).any { marker ->
            c.contains(marker)
        }
    }

    private fun shouldDelegateArtifactWholeGoalToAgent(
        decision: AyanaCompositeIntentGate.Decision
    ): Boolean {
        if (
            decision.constraints.forbidNetwork ||
            decision.type == AyanaCompositeIntentGate.DecisionType.DATA_ONLY ||
            decision.type == AyanaCompositeIntentGate.DecisionType.INVALID ||
            decision.type == AyanaCompositeIntentGate.DecisionType.REQUIRE_CONFIRMATION ||
            decision.type == AyanaCompositeIntentGate.DecisionType.CONDITIONAL
        ) {
            return false
        }

        return decision.type == AyanaCompositeIntentGate.DecisionType.PASS_THROUGH ||
            decision.type == AyanaCompositeIntentGate.DecisionType.COMPOSITE ||
            decision.type == AyanaCompositeIntentGate.DecisionType.ENVIRONMENT_CONSTRAINED
    }

    private fun extractDirectSystemSettingsSection(
        command: String
    ): String? {

        val c =
            command
                .lowercase(
                    Locale.getDefault()
                )
                .replace('ё', 'е')
                .replace(
                    Regex("\\s+"),
                    " "
                )
                .trim()

        // App-specific routes (for example «уведомления YouTube») are
        // handled earlier and must not be mistaken for global settings.
        fun hasAny(
            vararg parts: String
        ): Boolean =
            parts.any {
                c.contains(it)
            }

        fun opensSettingsTopic(): Boolean =
            c.startsWith("открой ") ||
                c.startsWith("открой мне ") ||
                c.startsWith("покажи ") ||
                c.startsWith("покажи мне ") ||
                c.startsWith("зайди ") ||
                c.startsWith("перейди ") ||
                c.startsWith("настройки ") ||
                c.startsWith("открой настройки ") ||
                c.startsWith("покажи настройки ")

        if (!opensSettingsTopic()) {
            return null
        }

        // v12.10.2 semantic separation: read-only requests such as
        // «покажи последние уведомления на планшете» must be handled by the
        // notification reader, never by Settings navigation.
        if (isRecentNotificationsReadRequest(c)) {
            return null
        }

        return when {

            hasAny(
                "подключения",
                "подключение",
                "подключений",
                "connections",
                "сеть и интернет",
                "сети и интернет",
                "network and internet",
                "network & internet"
            ) ->
                "connections"

            hasAny(
                "обслуживание устройства",
                "обслуживания устройства",
                "уход за устройством",
                "battery and device care",
                "device care"
            ) ->
                "device_care"

            (
                (c.contains("оптимизац") && c.contains("батар")) ||
                    c.contains("экономия батареи для прилож") ||
                    c.contains("игнорирование оптимизац")
                ) ->
                "battery_optimization"

            hasAny(
                "батаре",
                "аккумулятор",
                "энергосбереж",
                "экономия энергии"
            ) ->
                "battery"

            hasAny(
                "хранилищ",
                "память устройства",
                "внутренняя память"
            ) ->
                "storage"

            hasAny(
                "уведомлен"
            ) ->
                "notifications"

            hasAny(
                "мобильные данные",
                "использование данных",
                "расход трафика",
                "трафик"
            ) ->
                "data_usage"

            hasAny(
                "vpn",
                "впн"
            ) ->
                "vpn"

            hasAny(
                "nfc",
                "нфс"
            ) ->
                "nfc"

            hasAny(
                "клавиатур",
                "метод ввода"
            ) ->
                "keyboard"

            hasAny(
                "приложения по умолчанию",
                "приложение по умолчанию"
            ) ->
                "default_apps"

            hasAny(
                "для разработчиков",
                "параметры разработчика",
                "режим разработчика"
            ) ->
                "developer_options"

            hasAny(
                "сведения об устройстве",
                "информация об устройстве",
                "о планшете",
                "об устройстве"
            ) ->
                "device_info"

            hasAny(
                "конфиденциальност",
                "приватност"
            ) ->
                "privacy"

            hasAny(
                "специальные возможности",
                "спец возможности",
                "accessibility"
            ) ->
                "accessibility"

            hasAny(
                "местополож",
                "геолокац",
                "локац"
            ) ->
                "location"

            hasAny(
                "безопасност"
            ) ->
                "security"

            (
                hasAny(
                    "дата и время",
                    "дату и время",
                    "даты и времени",
                    "время и дата",
                    "время и дату",
                    "date and time"
                ) ||
                    (
                        c.contains("дат") &&
                            c.contains("врем")
                        )
                ) ->
                "date_time"

            hasAny(
                "bluetooth",
                "блютуз"
            ) ->
                "bluetooth"

            hasAny(
                "wi-fi",
                "wifi",
                "вай фай",
                "вайфай"
            ) ->
                "wifi"

            hasAny(
                "звук",
                "громкост"
            ) ->
                "sound"

            hasAny(
                "экран",
                "диспле"
            ) ->
                "display"

            hasAny(
                "язык",
                "локаль"
            ) ->
                "language"

            hasAny(
                "приложени"
            ) &&
                !hasAny(
                    "информация о приложении",
                    "сведения о приложении",
                    "уведомления приложения",
                    "язык приложения"
                ) ->
                "apps"

            c == "открой настройки" ||
                c == "покажи настройки" ||
                c == "настройки" ->
                "general"

            else ->
                null
        }
    }

    private fun isMultiStepAgentCommand(
        command: String
    ): Boolean {

        val c =
            command
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(
                    Regex("\\s+"),
                    " "
                )
                .trim()

        // v12.11.6 ROUTING INTEGRITY.
        // A bare conjunction is not proof of a multi-step goal:
        // «дата и время», «звуки и вибрация», «сеть и интернет» are names of
        // single Settings destinations. Multi-step ownership requires either
        // an explicit sequencing connector or at least two actual action verbs.
        val strongSequenceConnectors =
            listOf(
                " потом ",
                " затем ",
                " после этого ",
                " а потом "
            )

        if (
            strongSequenceConnectors.any {
                c.contains(it)
            }
        ) {
            return true
        }

        val actionPattern =
            Regex(
                """(?:^|\s)(?:открой|открыть|запусти|запустить|включи|включить|найди|найти|поищи|поискать|нажми|нажать|выбери|выбрать|зайди|зайти|перейди|перейти|проверь|проверить|убедись|убедиться|подтверди|подтвердить|остановись|остановиться)(?=\s|$)"""
            )

        val actionMatches =
            actionPattern
                .findAll(c)
                .count()

        if (actionMatches >= 2) {
            return true
        }

        // «и» counts as a step separator only when there is a real action on
        // both sides. This keeps ordinary compound Settings labels local while
        // preserving goals such as «открой YouTube и найди музыку».
        val conjunctionIndex =
            c.indexOf(" и ")

        if (conjunctionIndex > 0) {
            val left =
                c.substring(
                    0,
                    conjunctionIndex
                )
            val right =
                c.substring(
                    conjunctionIndex + 3
                )

            val leftHasAction =
                actionPattern.containsMatchIn(left)

            val rightHasAction =
                actionPattern.containsMatchIn(right)

            if (
                leftHasAction &&
                rightHasAction
            ) {
                return true
            }
        }

        return false
    }

    private fun isAppLaunchCommand(
        command: String
    ): Boolean {

        return APP_LAUNCH_PREFIXES
            .any {
                command.startsWith(it)
            }
    }

    // =========================================================
    // APP EXECUTION ROUTER — v11.5
    // =========================================================

    private fun extractPendingLifecycleFollowUpAction(
        command: String
    ): String? {

        val clean =
            normalizeLifecycleRoutingText(
                command
            )

        return when (clean) {
            "сверни",
            "свернуть",
            "просто сверни",
            "сверни его",
            "сверни ее",
            "сверни приложение" ->
                "minimize"

            "закрой",
            "закрыть",
            "просто закрой",
            "полностью закрой",
            "закрой его",
            "закрой ее",
            "заверши",
            "заверши приложение" ->
                "close"

            "открой",
            "открыть",
            "просто открой",
            "открой его",
            "открой ее",
            "запусти",
            "включи" ->
                "open"

            else ->
                null
        }
    }

    private fun extractLocalAppLifecycleRequest(
        command: String
    ): Pair<String, String>? {

        val clean =
            normalizeLifecycleRoutingText(
                command
            )

        if (clean.isBlank()) {
            return null
        }

        // Short action-only commands are deterministic device actions. With no
        // pending clarification, minimize/close refer to the currently foreground
        // app. This is what prevents a bare «сверни» from reaching Agent Core.
        when (clean) {
            "сверни",
            "свернуть",
            "просто сверни",
            "сверни приложение" ->
                return "minimize" to FOREGROUND_APP_SENTINEL

            "закрой",
            "закрыть",
            "просто закрой",
            "полностью закрой",
            "заверши",
            "заверши приложение" ->
                return "close" to FOREGROUND_APP_SENTINEL
        }

        // Windows/dialogs/Recents are not named application lifecycle requests.
        val excludedPrefixes =
            listOf(
                "закрой все",
                "закрой окно",
                "закрой вкладку",
                "закрой диалог",
                "закрой меню",
                "закрой клавиатуру",
                "сверни все",
                "сверни окно"
            )

        if (
            excludedPrefixes.any {
                clean.startsWith(it)
            }
        ) {
            return null
        }

        val minimizePrefixes =
            listOf(
                "сверни приложение ",
                "сверни "
            )

        for (prefix in minimizePrefixes) {
            if (clean.startsWith(prefix)) {
                val target =
                    lifecycleTargetAfterPrefix(
                        clean,
                        prefix
                    )

                if (
                    target.isBlank() ||
                    target in LIFECYCLE_INVALID_TARGETS
                ) {
                    return null
                }

                return "minimize" to target
            }
        }

        val closePrefixes =
            listOf(
                "полностью закрой приложение ",
                "полностью закрой ",
                "закрой приложение ",
                "заверши приложение ",
                "закрой "
            )

        for (prefix in closePrefixes) {
            if (clean.startsWith(prefix)) {
                val target =
                    lifecycleTargetAfterPrefix(
                        clean,
                        prefix
                    )

                if (
                    target.isBlank() ||
                    target in LIFECYCLE_INVALID_CLOSE_TARGETS
                ) {
                    return null
                }

                return "close" to target
            }
        }

        // Simple app launches now use the same resolver + verification contract as
        // minimize. Complex/settings/search commands intentionally remain with their
        // dedicated routers below.
        val openPrefix =
            APP_LAUNCH_PREFIXES
                .firstOrNull {
                    clean.startsWith(it)
                }

        if (openPrefix != null) {
            val target =
                lifecycleTargetAfterPrefix(
                    clean,
                    openPrefix
                )

            if (
                target.isBlank() ||
                !isSafeSimpleLifecycleOpenTarget(
                    target = target,
                    wholeCommand = clean
                )
            ) {
                return null
            }

            return "open" to target
        }

        return null
    }

    private fun normalizeLifecycleRoutingText(
        value: String
    ): String =
        value
            .lowercase(
                Locale.ROOT
            )
            .replace(
                'ё',
                'е'
            )
            .trim()
            .trim(
                ' ',
                '"',
                '«',
                '»',
                '.',
                ',',
                '!',
                '?',
                ';',
                ':'
            )
            .replace(
                Regex("\\s+"),
                " "
            )

    private fun lifecycleTargetAfterPrefix(
        command: String,
        prefix: String
    ): String =
        command
            .removePrefix(
                prefix
            )
            .trim()
            .trim(
                ' ',
                '"',
                '«',
                '»',
                '.',
                ',',
                '!',
                '?',
                ';',
                ':'
            )

    private fun isSafeSimpleLifecycleOpenTarget(
        target: String,
        wholeCommand: String
    ): Boolean {

        if (
            target in LIFECYCLE_NON_APP_OPEN_TARGETS
        ) {
            return false
        }

        if (
            wholeCommand.contains(" и ") ||
            wholeCommand.contains(" затем ") ||
            wholeCommand.contains(" потом ")
        ) {
            return false
        }

        if (
            LIFECYCLE_OPEN_DELEGATE_MARKERS.any {
                target.contains(it)
            }
        ) {
            return false
        }

        return target
            .split(' ')
            .count {
                it.isNotBlank()
            } <=
            5
    }

    /**
     * Detects a short ASR fragment that still contains one known app alias but no
     * trustworthy action verb. Example observed on-device: «ни ютуб». This is a
     * generic app-fragment rule across the alias set, not a phrase-specific repair.
     */
    private fun extractLifecycleClarificationTarget(
        command: String
    ): String? {

        val clean =
            normalizeLifecycleRoutingText(
                command
            )

        val wordCount =
            clean
                .split(' ')
                .count {
                    it.isNotBlank()
                }

        if (
            wordCount !in
            2..4
        ) {
            return null
        }

        if (
            LIFECYCLE_CLARIFICATION_EXCLUSION_MARKERS.any {
                clean.contains(it)
            }
        ) {
            return null
        }

        val alias =
            KNOWN_LOCAL_LAUNCH_ALIASES
                .asSequence()
                .filter {
                    it.isNotBlank() &&
                        clean != it
                }
                .sortedByDescending {
                    it.length
                }
                .firstOrNull { candidate ->
                    Regex(
                        "(^|\\s)" +
                            Regex.escape(candidate) +
                            "($|\\s)"
                    )
                        .containsMatchIn(
                            clean
                        )
                }
                ?: return null

        // v12.9.0 ROUTING INTEGRITY:
        // clarification is only for a short ASR fragment around a known app alias
        // (for example «ни ютуб» / «и ютуб»). Meaningful residual words such as
        // «подробно», «история», «возможности», «что такое» are conversational intent
        // and must reach Agent Core rather than being collapsed to app lifecycle.
        val aliasRegex =
            Regex(
                "(^|\\s)" +
                    Regex.escape(alias) +
                    "($|\\s)"
            )

        val residual =
            clean
                .replaceFirst(
                    aliasRegex,
                    " "
                )
                .replace(
                    Regex("\\s+"),
                    " "
                )
                .trim()

        if (
            residual.isBlank()
        ) {
            return null
        }

        val residualTokens =
            residual
                .split(
                    ' '
                )
                .filter {
                    it.isNotBlank()
                }

        if (
            residualTokens.any {
                token ->
                token !in
                    LIFECYCLE_CLARIFICATION_NOISE_TOKENS
            }
        ) {
            return null
        }

        return alias
    }

    private fun beginLocalLifecycleClarification(
        candidate: String,
        silent: Boolean
    ) {

        val commandToken =
            activeCommandToken

        thread(
            start = true,
            name = "AyanaLifecycleClarify"
        ) {
            val resolution =
try {
                    appResolver.resolve(
                        candidate
                    )
                } catch (_: Exception) {
                    null
                }

            if (
                resolution == null ||
                !resolution.success ||
                resolution.packageName.isBlank()
            ) {
                mainHandler.post {
                    if (
                        commandToken == activeCommandToken &&
                        !cancelRequested &&
                        !shuttingDown
                    ) {
                        askAyana(
                            candidate,
                            silent
                        )
                    }
                }
                return@thread
            }

            pendingLifecycleTarget =
                resolution.label
                    .ifBlank {
                        candidate
                    }

            pendingLifecycleLabel =
                resolution.label
                    .ifBlank {
                        candidate
                    }

            pendingLifecycleExpiresAtMs =
                SystemClock.elapsedRealtime() +
                    LIFECYCLE_CONTEXT_TTL_MS

            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "lifecycle_clarification",
                message = "Приложение распознано локально, действие не определено",
                details =
                    "candidate=${candidate.take(120)}; " +
                        "label=${resolution.label.take(120)}; " +
                        "package=${resolution.packageName.take(180)}; " +
                        "confidence=${resolution.confidence}; source=${resolution.source}"
            )

            val label =
                resolution.label
                    .ifBlank {
                        candidate
                    }

            mainHandler.post {
                if (
                    commandToken == activeCommandToken &&
                    !cancelRequested &&
                    !shuttingDown
                ) {
                    respondAndResume(
                        "Что сделать с $label: открыть, свернуть или закрыть?",
                        silent,
                        success = true
                    )
                }
            }
        }
    }

    private fun consumePendingLifecycleTarget(): String? {

        val now =
            SystemClock.elapsedRealtime()

        val target =
            pendingLifecycleTarget

        val valid =
            !target.isNullOrBlank() &&
                pendingLifecycleExpiresAtMs >
                    now

        clearPendingLifecycleContext()

        return if (valid) {
            target
        } else {
            null
        }
    }

    private fun clearExpiredOrInterruptedLifecycleContext() {

        if (
            pendingLifecycleTarget == null
        ) {
            return
        }

        if (
            pendingLifecycleExpiresAtMs <=
            SystemClock.elapsedRealtime()
        ) {
            clearPendingLifecycleContext()
            return
        }

        // A different complete command supersedes the old clarification context.
        clearPendingLifecycleContext()
    }

    private fun clearPendingLifecycleContext() {
        pendingLifecycleTarget =
            null
        pendingLifecycleLabel =
            null
        pendingLifecycleExpiresAtMs =
            0L
    }

    private fun isTrueAppCloseRequest(
        command: String
    ): Boolean =
        extractLocalAppLifecycleRequest(
            repairCommonRecognitionForRouting(
                normalizeRecognitionText(
                    command
                )
            )
        )
            ?.first ==
            "close"

    private fun currentForegroundPackage(): String =
        try {
            screenIntelligence
                .effectiveForegroundPackage()
        } catch (_: Exception) {
            ""
        }

    private fun appLabelForPackage(
        packageName: String
    ): String {

        if (packageName.isBlank()) {
            return "приложение"
        }

        return try {
            val info =
                packageManager
                    .getApplicationInfo(
                        packageName,
                        0
                    )

            packageManager
                .getApplicationLabel(
                    info
                )
                .toString()
                .trim()
                .ifBlank {
                    packageName.substringAfterLast('.')
                }
        } catch (_: Exception) {
            packageName.substringAfterLast('.')
                .ifBlank {
                    "приложение"
                }
        }
    }

    private fun defaultHomePackage(): String =
        try {
            packageManager
                .resolveActivity(
                    Intent(
                        Intent.ACTION_MAIN
                    ).apply {
                        addCategory(
                            Intent.CATEGORY_HOME
                        )
                    },
                    PackageManager.MATCH_DEFAULT_ONLY
                )
                ?.activityInfo
                ?.packageName
                .orEmpty()
                .trim()
        } catch (_: Exception) {
            ""
        }

    private fun waitForR10_13PostProcessRuntimeReadiness(
        commandToken: Long,
        timeoutMs: Long = R10_13_POST_PROCESS_READINESS_TIMEOUT_MS
    ): JSONObject {
        val startedAt = SystemClock.elapsedRealtime()
        val deadline = startedAt + timeoutMs
        var attempts = 0
        var accessibilityReady = false
        var screenEvidenceReady = false
        var foregroundPackage = ""
        var lastScreenStatus = ""

        do {
            if (
                isCommandCancelled(commandToken) ||
                commandToken != activeCommandToken ||
                cancelRequested ||
                shuttingDown
            ) {
                break
            }

            attempts++
            try {
                val bridge = perceptionBridge.status()
                accessibilityReady =
                    bridge.optBoolean("accessibility_connected", false)
                lastScreenStatus = bridge.optString("content_status")
                foregroundPackage =
                    bridge.optString("effective_foreground_package").trim()
                screenEvidenceReady =
                    bridge.optBoolean("screen_evidence_available", false) &&
                        foregroundPackage.isNotBlank()
            } catch (_: Exception) {
                accessibilityReady = false
                screenEvidenceReady = false
            }

            if (accessibilityReady && screenEvidenceReady) {
                val waited = SystemClock.elapsedRealtime() - startedAt
                return JSONObject()
                    .put("verified", true)
                    .put("accessibility_ready", true)
                    .put("screen_evidence_ready", true)
                    .put("foreground_package", foregroundPackage)
                    .put("screen_status", lastScreenStatus)
                    .put("attempts", attempts)
                    .put("waited_ms", waited)
                    .put("reason", "post_process_runtime_ready")
            }

            try {
                Thread.sleep(R10_13_POST_PROCESS_READINESS_POLL_MS)
            } catch (_: InterruptedException) {
                break
            }
        } while (SystemClock.elapsedRealtime() < deadline)

        return JSONObject()
            .put("verified", false)
            .put("accessibility_ready", accessibilityReady)
            .put("screen_evidence_ready", screenEvidenceReady)
            .put("foreground_package", foregroundPackage)
            .put("screen_status", lastScreenStatus)
            .put("attempts", attempts)
            .put("waited_ms", SystemClock.elapsedRealtime() - startedAt)
            .put("reason", "post_process_runtime_not_ready")
    }

    private fun reconcileR10_13DispatchedNavigation(
        rawResult: JSONObject,
        commandToken: Long
    ): JSONObject {
        val result = JSONObject(rawResult.toString())

        if (
            result.optBoolean("verified", false) ||
            !result.optBoolean("action_dispatched", false)
        ) {
            return result
                .put("r10_13_reconciliation_attempted", false)
                .put("reconciliation_complete", result.optBoolean("verified", false))
        }

        val expectedPackage = result.optString("target_package").trim()
        if (expectedPackage.isBlank()) {
            return result
                .put("r10_13_reconciliation_attempted", false)
                .put("reconciliation_complete", false)
        }

        val startedAt = SystemClock.elapsedRealtime()
        val deadline = startedAt + R10_13_POST_PROCESS_RECONCILE_TIMEOUT_MS
        var observed = result.optString("observed_package").trim()
        var attempts = 0

        do {
            if (
                isCommandCancelled(commandToken) ||
                commandToken != activeCommandToken ||
                cancelRequested ||
                shuttingDown
            ) {
                break
            }

            attempts++
            observed = currentForegroundPackage()
            if (observed == expectedPackage) {
                val waited = SystemClock.elapsedRealtime() - startedAt
                return result
                    .put("success", true)
                    .put("verified", true)
                    .put("terminal_status", "SUCCESS")
                    .put("observed_package", observed)
                    .put("action_committed", false)
                    .put("reconciliation_complete", true)
                    .put("r10_13_reconciliation_attempted", true)
                    .put("r10_13_reconciliation_verified", true)
                    .put("r10_13_reconciliation_waited_ms", waited)
                    .put("r10_13_reconciliation_attempts", attempts)
                    .put("message", "Navigation foreground confirmed during post-process reconciliation without redispatch.")
            }

            try {
                Thread.sleep(R10_13_POST_PROCESS_RECONCILE_POLL_MS)
            } catch (_: InterruptedException) {
                break
            }
        } while (SystemClock.elapsedRealtime() < deadline)

        return result
            .put("success", false)
            .put("verified", false)
            .put("action_committed", false)
            .put("reconciliation_complete", false)
            .put("r10_13_reconciliation_attempted", true)
            .put("r10_13_reconciliation_verified", false)
            .put("r10_13_reconciliation_waited_ms", SystemClock.elapsedRealtime() - startedAt)
            .put("r10_13_reconciliation_attempts", attempts)
            .put("observed_package", observed)
            .put("reason", "post_process_navigation_foreground_not_reconciled")
    }

    private fun waitForForegroundPackage(
        expectedPackage: String,
        timeoutMs: Long = LIFECYCLE_VERIFY_TIMEOUT_MS
    ): String {

        val deadline =
            SystemClock.elapsedRealtime() +
                timeoutMs

        var latest =
            ""

        do {
            latest =
                currentForegroundPackage()

            if (
                latest == expectedPackage
            ) {
                return latest
            }

            try {
                Thread.sleep(
                    LIFECYCLE_VERIFY_POLL_MS
                )
            } catch (_: InterruptedException) {
                break
            }
        } while (
            SystemClock.elapsedRealtime() <
            deadline &&
            !cancelRequested &&
            !shuttingDown
        )

        return latest
    }

    private fun waitForForegroundToLeave(
        targetPackage: String,
        timeoutMs: Long = LIFECYCLE_VERIFY_TIMEOUT_MS
    ): String {

        val deadline =
SystemClock.elapsedRealtime() +
timeoutMs

        var latest =
            targetPackage

        do {
            latest =
                currentForegroundPackage()

            if (
                latest.isNotBlank() &&
                latest != targetPackage
            ) {
                return latest
            }

            try {
                Thread.sleep(
                    LIFECYCLE_VERIFY_POLL_MS
                )
            } catch (_: InterruptedException) {
                break
            }
        } while (
            SystemClock.elapsedRealtime() <
            deadline &&
            !cancelRequested &&
            !shuttingDown
        )

        return latest
    }

    private fun handleLocalAppLifecycleRequest(
        action: String,
        requestedName: String,
        silent: Boolean
    ) {

        val commandToken =
            activeCommandToken

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "lifecycle_intent",
            message =
                when (action) {
                    "open" ->
                        "Локальная команда открытия приложения"

                    "minimize" ->
                        "Локальная команда сворачивания приложения"

                    else ->
                        "Локальная команда закрытия приложения"
                },
            details =
                "action=$action; app=${requestedName.take(160)}"
        )

        if (
            action == "close" &&
            !silent
        ) {
            executionPhase(
                phase = "lifecycle_close_prepare",
                executor = "app_task_removal_executor"
            )

            startCancelListening()

            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "cancel_listener_armed",
                message = "STOP активирован для App Lifecycle",
                details =
                    "lane=app_lifecycle; execution=${executionKernel.current()?.id.orEmpty()}"
            )
        }

        val lifecycleWorker =
            thread(
                start = false,
                name = "AyanaAppLifecycle"
            ) {

            val foregroundMode =
                requestedName ==
                    FOREGROUND_APP_SENTINEL

            var label =
                requestedName

            var packageName =
                ""

            if (foregroundMode) {
                packageName =
                    currentForegroundPackage()

                if (packageName.isBlank()) {
                    mainHandler.post {
                        if (
                            commandToken == activeCommandToken &&
                            !cancelRequested &&
                            !shuttingDown
                        ) {
                            respondAndResume(
                                "Не могу надёжно определить текущее приложение.",
                                silent,
                                success = false
                            )
                        }
                    }
                    return@thread
                }

                label =
                    appLabelForPackage(
                        packageName
                    )

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "lifecycle_foreground_resolved",
                    message = "Текущее приложение определено по свежему screen state",
                    details =
                        "label=${label.take(120)}; package=${packageName.take(180)}"
                )
            } else {
                val resolution =
                    try {
                        appResolver.resolve(
                            requestedName
                        )
                    } catch (_: Exception) {
                        null
                    }

                if (
                    resolution == null ||
                    !resolution.success ||
                    resolution.packageName.isBlank()
                ) {
                    mainHandler.post {
                        if (
                            commandToken == activeCommandToken &&
                            !cancelRequested &&
                            !shuttingDown
                        ) {
                            respondAndResume(
                                "Не нашла установленное приложение $requestedName.",
                                silent,
                                success = false
                            )
                        }
                    }
                    return@thread
                }

                label =
                    resolution.label
                        .ifBlank {
                            requestedName
                        }

                packageName =
                    resolution.packageName

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "lifecycle_app_resolved",
                    message = "Приложение определено",
                    details =
                        "label=${label.take(120)}; package=${packageName.take(180)}; " +
                            "confidence=${resolution.confidence}; source=${resolution.source}"
                )
            }

            if (
                commandToken != activeCommandToken ||
                cancelRequested ||
                shuttingDown
            ) {
                if (
                    action == "close" &&
                    cancelRequested &&
                    commandToken == activeCommandToken &&
                    !shuttingDown
                ) {
                    mainHandler.post {
                        finishDeferredCancellationFromExecutor(
                            source =
                                pendingCancelSource
                                    .ifBlank {
                                        "voice"
                                    }
                        )
                    }
                }
                return@thread
            }

            if (action == "close") {
                val originalForegroundPackage =
                    currentForegroundPackage()

                val protectedCloseReason =
                    when {
                        packageName ==
                            this@AyanaVoiceService.packageName ->
                            "self_app_requires_dedicated_shutdown"

                        defaultHomePackage().let { homePackage ->
                            homePackage.isNotBlank() &&
                                packageName == homePackage
                        } ->
                            "home_package_not_removable_task"

                        else ->
                            ""
                    }

                if (protectedCloseReason.isNotBlank()) {
                    val protectedMessage =
                        if (
                            protectedCloseReason ==
                            "self_app_requires_dedicated_shutdown"
                        ) {
                            "AYANA не закрывает собственную службу через список недавних. Для остановки используется отдельная команда завершения AYANA."
                        } else {
                            "Главный экран Android нельзя закрывать как обычное приложение."
                        }

                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state = "lifecycle_close_blocked",
                        message = protectedMessage,
                        details =
                            "package=$packageName; reason=$protectedCloseReason"
                    )

                    mainHandler.post {
                        if (
                            commandToken == activeCommandToken &&
                            !cancelRequested &&
                            !shuttingDown
                        ) {
                            respondBlockedAndResume(
                                text = protectedMessage,
                                silent = silent,
                                technical =
                                    "package=$packageName; reason=$protectedCloseReason"
                            )
                        }
                    }
                    return@thread
                }

                executionPhase(
                    phase = "lifecycle_close_task_removal",
                    executor = "app_task_removal_executor"
                )

                executionKernel.addEvidence(
                    type = "lifecycle_target",
                    source = "app_resolver",
                    detail =
                        "action=close; label=${label.take(120)}; package=${packageName.take(180)}; " +
                            "original_foreground=${originalForegroundPackage.take(180)}",
                    confidence = 100
                )

                val closeResult =
                    appLifecycleExecutor
                        .removeTask(
                            targetPackage = packageName,
                            targetLabel = label,
                            originalForegroundPackage = originalForegroundPackage
                        )

                val terminalStatus =
                    closeResult.optString(
                        "terminal_status",
                        if (
                            closeResult.optBoolean(
                                "success",
                                false
                            )
                        ) {
                            "SUCCESS"
                        } else {
                            "ERROR"
                        }
                    ).uppercase(
                        Locale.ROOT
                    )

                val verified =
                    closeResult.optBoolean(
                        "success",
                        false
                    ) &&
                        closeResult.optBoolean(
                            "verified",
                            false
                        ) &&
                        terminalStatus ==
                        "SUCCESS"

                val historyState =
                    when {
                        verified ->
                            "lifecycle_close_verified"

                        terminalStatus ==
                            "BLOCKED" ->
                            "lifecycle_close_blocked"

                        terminalStatus ==
                            "UNSUPPORTED" ->
                            "lifecycle_close_unsupported"

                        terminalStatus ==
                            "CANCELLED" ->
                            "lifecycle_close_cancelled"

                        else ->
                            "lifecycle_close_unverified"
                    }

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = historyState,
                    message =
                        closeResult.optString(
                            "message",
                            if (verified) {
                                "Закрытие подтверждено удалением задачи из недавних"
                            } else {
                                "Закрытие не подтверждено"
                            }
                        ),
                    details =
                        closeResult
                            .toString()
                            .take(
                                1800
                            )
                )

                executionKernel.addEvidence(
                    type =
                        if (verified) {
                            "task_removal_verified"
                        } else {
                            "task_removal_terminal"
                        },
                    source = "app_task_removal_executor",
                    detail =
                        closeResult
                            .toString(),
                    confidence =
                        if (verified) {
                            100
                        } else {
                            80
                        }
                )

                mainHandler.post {
                    if (
                        commandToken == activeCommandToken &&
                        !shuttingDown
                    ) {
                        val technical =
                            closeResult
                                .toString()
                                .take(
                                    1800
                                )

                        val actionDispatched =
                            closeResult.optBoolean(
                                "action_dispatched",
                                false
                            )

                        val reconciliationComplete =
                            closeResult.optBoolean(
                                "reconciliation_complete",
                                !actionDispatched
                            )

                        when {
                            verified &&
                                cancelRequested -> {
                                commandHistoryStore.addEvent(
                                    activeCommandHistoryId,
                                    state = "cancel_after_commit",
                                    message = "STOP получен после подтверждённого удаления задачи",
                                    details =
                                        "semantic_terminal=SUCCESS; " +
                                            "action_dispatched=$actionDispatched; " +
                                            "reconciliation_complete=$reconciliationComplete; " +
                                            "source=${pendingCancelSource.ifBlank { "voice" }}"
                                )

                                finishActiveCommandHistory(
                                    success = true,
                                    result = "$label закрыт.",
                                    technical = technical
                                )

                                broadcastStatus(
                                    "$label закрыт.",
                                    STATE_SUCCESS
                                )

                                updateNotification(
                                    "$label закрыт • STOP получен после фактического commit"
                                )

                                resumeAfterCancellation(
                                    attempt = 0
                                )
                            }

                            terminalStatus ==
                                "CANCELLED" &&
                                cancelRequested -> {
                                finishDeferredCancellationFromExecutor(
                                    source =
                                        pendingCancelSource
                                            .ifBlank {
                                                "voice"
                                            }
                                )
                            }

                            terminalStatus ==
                                "ERROR" &&
                                actionDispatched &&
                                cancelRequested -> {
                                val factualMessage =
                                    closeResult.optString(
                                        "message",
                                        "Android-действие было запущено, но фактический результат не удалось подтвердить."
                                    )

                                commandHistoryStore.addEvent(
                                    activeCommandHistoryId,
                                    state = "cancel_after_dispatch_unverified",
                                    message = "STOP получен после destructive dispatch; сохраняю factual ERROR",
                                    details =
                                        "semantic_terminal=ERROR; " +
                                            "action_dispatched=true; " +
                                            "reconciliation_complete=$reconciliationComplete; " +
                                            "source=${pendingCancelSource.ifBlank { "voice" }}"
                                )

                                finishActiveCommandHistory(
                                    success = false,
                                    result = factualMessage,
                                    technical = technical
                                )

                                broadcastStatus(
                                    factualMessage,
                                    STATE_ERROR
                                )

                                updateNotification(
                                    "Результат Android-действия не подтверждён"
                                )

                                resumeAfterCancellation(
                                    attempt = 0
                                )
                            }

                            verified ->
                                respondAndResume(
                                    "$label закрыт.",
                                    silent,
                                    success = true,
                                    technical = technical
                                )

                            terminalStatus ==
                                "BLOCKED" ->
                                respondBlockedAndResume(
                                    text = closeResult.optString(
                                        "message",
                                        "Закрытие заблокировано текущим оконным режимом."
                                    ),
                                    silent = silent,
                                    technical = technical
                                )

                            terminalStatus ==
                                "UNSUPPORTED" ->
                                respondUnsupportedAndResume(
                                    text = closeResult.optString(
                                        "message",
                                        "Надёжный исполнитель закрытия сейчас недоступен."
                                    ),
                                    silent = silent,
                                    technical = technical
                                )

                            terminalStatus !=
                                "CANCELLED" ->
                                respondAndResume(
                                    text = closeResult.optString(
                                        "message",
                                        "Закрытие $label не удалось надёжно подтвердить."
                                    ),
                                    silent = silent,
                                    success = false,
                                    technical = technical
                                )
                        }
                    }
                }
                return@thread
            }

            if (action == "open") {
                val launchResult =
                    try {
                        appResolver.launch(
                            requestedName
                        )
                    } catch (error: Exception) {
                        JSONObject()
                            .put(
                                "success",
                                false
                            )
                            .put(
                                "message",
                                error.message
                                    ?: "Ошибка запуска приложения"
                            )
                    }

                val afterPackage =
                    if (
                        launchResult.optBoolean(
                            "success",
                            false
                        )
                    ) {
                        waitForForegroundPackage(
                            packageName
                        )
                    } else {
                        currentForegroundPackage()
                    }

                val verified =
                    launchResult.optBoolean(
                        "success",
                        false
                    ) &&
                        afterPackage == packageName

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state =
                        if (verified) {
                            "lifecycle_verified"
                        } else {
                            "lifecycle_unverified"
                        },
                    message =
                        if (verified) {
                            "Открытие подтверждено по свежему foreground package"
                        } else {
                            "Открытие не удалось надёжно подтвердить"
                        },
                    details =
                        "action=open; target=$packageName; after=$afterPackage; " +
                            "launch_success=${launchResult.optBoolean("success", false)}"
                )

                mainHandler.post {
                    if (
                        commandToken == activeCommandToken &&
                        !cancelRequested &&
                        !shuttingDown
                    ) {
                        if (verified) {
                            respondAndResume(
                                "Открываю $label.",
                                silent,
                                success = true
                            )
                        } else {
                            respondAndResume(
                                "Запуск $label не удалось надёжно подтвердить.",
                                silent,
                                success = false
                            )
                        }
                    }
}
                return@thread
            }

            val beforePackage =
                currentForegroundPackage()

            if (beforePackage.isBlank()) {
                mainHandler.post {
                    if (
                        commandToken == activeCommandToken &&
                        !cancelRequested &&
                        !shuttingDown
                    ) {
                        respondAndResume(
                            "Не могу надёжно определить приложение на переднем плане, поэтому ничего не сворачиваю вслепую.",
                            silent,
                            success = false
                        )
                    }
                }
                return@thread
            }

            if (
                !foregroundMode &&
                beforePackage != packageName
            ) {
                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "lifecycle_verified",
                    message = "Целевое приложение уже не на переднем плане",
                    details =
                        "target=$packageName; foreground=$beforePackage"
                )

                mainHandler.post {
                    if (
                        commandToken == activeCommandToken &&
                        !cancelRequested &&
                        !shuttingDown
                    ) {
                        respondAndResume(
                            "$label уже не находится на переднем плане.",
                            silent,
                            success = true
                        )
                    }
                }
                return@thread
            }

            if (foregroundMode) {
                packageName =
                    beforePackage
                label =
                    appLabelForPackage(
                        packageName
                    )
            }

            val homePackage =
                defaultHomePackage()

            if (
                homePackage.isNotBlank() &&
                packageName == homePackage
            ) {
                mainHandler.post {
                    if (
                        commandToken == activeCommandToken &&
                        !cancelRequested &&
                        !shuttingDown
                    ) {
                        respondAndResume(
                            "Уже открыт главный экран.",
                            silent,
                            success = true
                        )
                    }
                }
                return@thread
            }

            val homeResult =
                try {
                    screenIntelligence
                        .pressHome()
                } catch (_: Exception) {
                    JSONObject()
                        .put(
                            "success",
                            false
                        )
                }

            // v11.5 intentionally ignores an embedded post-action snapshot as final
            // proof. Poll a fresh Screen Intelligence state until the target leaves
            // foreground or the bounded verification deadline expires.
            val afterPackage =
                waitForForegroundToLeave(
                    packageName
                )

            val verified =
                homeResult.optBoolean(
                    "success",
                    false
                ) &&
                    afterPackage.isNotBlank() &&
                    afterPackage != packageName

            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state =
                    if (verified) {
                        "lifecycle_verified"
                    } else {
                        "lifecycle_unverified"
                    },
                message =
                    if (verified) {
                        "Сворачивание подтверждено свежим foreground state"
                    } else {
                        "Сворачивание не удалось надёжно подтвердить"
                    },
                details =
                    "target=$packageName; before=$beforePackage; after=$afterPackage; " +
                        "home_success=${homeResult.optBoolean("success", false)}"
            )

            mainHandler.post {
                if (
                    commandToken == activeCommandToken &&
                    !cancelRequested &&
                    !shuttingDown
                ) {
                    if (verified) {
                        respondAndResume(
                            "$label свёрнут.",
                            silent,
                            success = true
                        )
                    } else {
                        respondAndResume(
                            "Результат сворачивания $label не удалось надёжно подтвердить.",
                            silent,
                            success = false
                        )
                    }
                }
            }
        }

        if (action == "close") {
            executionKernel.bindThread(
                lifecycleWorker
            )
        }

        lifecycleWorker.start()
    }

    private fun isUnifiedScreenIntelligenceAcceptanceCommand(
        command: String
    ): Boolean {
        val normalized =
            command
                .trim()
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")

        return normalized in
            setOf(
                "проверь единый screen intelligence",
                "протестируй единый screen intelligence",
                "проверь unified screen intelligence",
                "протестируй unified screen intelligence",
                "проверь единое понимание экрана",
                "протестируй единое понимание экрана"
            )
    }

    private fun normalizeBatteryProactivityCommand(
        value: String
    ): String =
        value
            .trim()
            .lowercase(Locale.ROOT)
            .replace('ё', 'е')
            .replace(Regex("\\s+"), " ")

    private fun isBatteryProactivityAcceptanceCommand(
        command: String
    ): Boolean {
        val normalized =
            normalizeBatteryProactivityCommand(command)

        return normalized in
            setOf(
                "проверь контролируемую проактивность",
                "протестируй контролируемую проактивность",
                "проверь контроль низкого заряда",
                "протестируй контроль низкого заряда",
                "проверь proactive battery monitor",
                "протестируй proactive battery monitor"
            )
    }

    private fun isBatteryProactivityEnableCommand(
        command: String
    ): Boolean {
        val normalized =
            normalizeBatteryProactivityCommand(command)

        val enable =
            normalized.contains("включи") ||
                normalized.contains("включить") ||
                normalized.contains("следи") ||
                normalized.contains("отслеживай") ||
                normalized.contains("предупреждай")

        val battery =
            normalized.contains("заряд") ||
                normalized.contains("батар")

        val low =
            normalized.contains("низк") ||
                normalized.contains("меньше") ||
                normalized.contains("ниже") ||
                normalized.contains("при ")

        return enable && battery && low
    }

    private fun isBatteryProactivityDisableCommand(
        command: String
    ): Boolean {
        val normalized =
            normalizeBatteryProactivityCommand(command)

        val disable =
            normalized.contains("выключи") ||
                normalized.contains("отключи") ||
                normalized.contains("перестань") ||
                normalized.contains("не следи")

        val battery =
            normalized.contains("заряд") ||
                normalized.contains("батар")

        return disable && battery
    }

    private fun isBatteryProactivityStatusCommand(
        command: String
    ): Boolean {
        val normalized =
            normalizeBatteryProactivityCommand(command)

        return normalized in
            setOf(
                "покажи контроль низкого заряда",
                "какой контроль низкого заряда",
                "контроль низкого заряда",
                "покажи проактивные правила",
                "какие проактивные правила включены",
                "покажи активные проактивные правила"
            )
    }

    private fun extractBatteryProactivityThreshold(
        command: String
    ): Int? {
        val normalized =
            normalizeBatteryProactivityCommand(command)

        val percentMatch =
            Regex(
                "(\\d{1,2})\\s*(?:%|процент(?:а|ов|ы)?)"
            )
                .find(normalized)
                ?.groupValues
                ?.getOrNull(1)
                ?.toIntOrNull()

        val fallback =
            percentMatch ?:
                Regex("\\b(\\d{1,2})\\b")
                    .find(normalized)
                    ?.groupValues
                    ?.getOrNull(1)
                    ?.toIntOrNull()

        return fallback
    }

    private fun registerBatteryProactivityReceiver() {
        if (
            batteryProactivityReceiverRegistered ||
            shuttingDown
        ) {
            return
        }

        val filter =
            IntentFilter(
                Intent.ACTION_BATTERY_CHANGED
            )

        batteryProactivityReceiverRegistered =
            try {
                if (Build.VERSION.SDK_INT >= 33) {
                    registerReceiver(
                        batteryProactivityReceiver,
                        filter,
                        Context.RECEIVER_NOT_EXPORTED
                    )
                } else {
                    @Suppress("DEPRECATION")
                    registerReceiver(
                        batteryProactivityReceiver,
                        filter
                    )
                }
                true
            } catch (_: Exception) {
                false
            }
    }

    private fun unregisterBatteryProactivityReceiver() {
        if (!batteryProactivityReceiverRegistered) {
            return
        }

        try {
            unregisterReceiver(
                batteryProactivityReceiver
            )
        } catch (_: Exception) {
        } finally {
            batteryProactivityReceiverRegistered =
                false
        }
    }

    private fun currentBatteryIntent():
        Intent? =
        try {
            val filter =
                IntentFilter(
                    Intent.ACTION_BATTERY_CHANGED
                )

            if (Build.VERSION.SDK_INT >= 33) {
                registerReceiver(
                    null,
                    filter,
                    Context.RECEIVER_NOT_EXPORTED
                )
            } else {
                @Suppress("DEPRECATION")
                registerReceiver(
                    null,
                    filter
                )
            }
        } catch (_: Exception) {
            null
        }

    private data class BatteryProactivitySample(
        val percent: Int,
        val charging: Boolean
    )

    private fun parseBatteryProactivitySample(
        intent: Intent?
    ): BatteryProactivitySample? {
        if (intent == null) {
            return null
        }

        val level =
            intent.getIntExtra(
                BatteryManager.EXTRA_LEVEL,
                -1
            )

        val scale =
            intent.getIntExtra(
BatteryManager.EXTRA_SCALE,
                100
            )
                .takeIf {
                    it > 0
                }
                ?: 100

        if (level < 0) {
            return null
        }

        val percent =
            (
                level
                    .toDouble()
                    .div(scale.toDouble())
                    .times(100.0)
                )
                .toInt()
                .coerceIn(
                    0,
                    100
                )

        val status =
            intent.getIntExtra(
                BatteryManager.EXTRA_STATUS,
                -1
            )

        val plugged =
            intent.getIntExtra(
                BatteryManager.EXTRA_PLUGGED,
                0
            )

        val charging =
            status ==
                BatteryManager.BATTERY_STATUS_CHARGING ||
                status ==
                    BatteryManager.BATTERY_STATUS_FULL ||
                plugged != 0

        return BatteryProactivitySample(
            percent = percent,
            charging = charging
        )
    }

    private fun handleBatteryProactivitySample(
        intent: Intent?,
        source: String
    ) {
        val sample =
            parseBatteryProactivitySample(intent)
                ?: return

        lastBatteryProactivitySampleAtMs =
            System.currentTimeMillis()

        lastBatteryProactivityPercent =
            sample.percent

        lastBatteryProactivityCharging =
            sample.charging

        if (
            !isRunning ||
            shuttingDown
        ) {
            return
        }

        val decision =
            try {
                batteryProactivityController.evaluate(
                    batteryPercent = sample.percent,
                    charging = sample.charging
                )
            } catch (_: Exception) {
                return
            }

        if (!decision.allowed) {
            return
        }

        val posted =
            postBatteryProactivityNotification(
                batteryPercent = sample.percent,
                thresholdPercent =
                    decision.thresholdPercent,
                notificationId =
                    BATTERY_PROACTIVITY_NOTIFICATION_ID,
                testMode = false
            )

        if (!posted) {
            return
        }

        try {
            batteryProactivityController
                .markNotificationDelivered()
        } catch (_: Exception) {
        }

        // Proactive activity is auditable without attaching it to an unrelated
        // foreground command. If a command is currently active, only a compact
        // event is appended to that command; no terminal state is modified.
        val historyId =
            activeCommandHistoryId

        if (historyId != null) {
            commandHistoryStore.addEvent(
                historyId,
                state = "controlled_proactivity_notification",
                message = "R9.9.2 low-battery notification emitted",
                details =
                    "source=$source; battery=${sample.percent}; threshold=${decision.thresholdPercent}; mutation_authority=false"
            )
        }
    }

    private fun createBatteryProactivityNotificationChannel() {
        if (Build.VERSION.SDK_INT < 26) {
            return
        }

        val manager =
            getSystemService(
                NotificationManager::class.java
            )

        val existing =
            manager.getNotificationChannel(
                BATTERY_PROACTIVITY_CHANNEL_ID
            )

        if (existing != null) {
            return
        }

        val channel =
            NotificationChannel(
                BATTERY_PROACTIVITY_CHANNEL_ID,
                "AYANA — контроль заряда",
                NotificationManager.IMPORTANCE_LOW
            ).apply {
                description =
                    "Контролируемые уведомления AYANA о низком заряде"
                setShowBadge(false)
            }

        manager.createNotificationChannel(
            channel
        )
    }

    private fun canPostBatteryProactivityNotification():
        Boolean =
        Build.VERSION.SDK_INT < 33 ||
            checkSelfPermission(
                Manifest.permission.POST_NOTIFICATIONS
            ) ==
            PackageManager.PERMISSION_GRANTED

    private fun postBatteryProactivityNotification(
        batteryPercent: Int,
        thresholdPercent: Int,
        notificationId: Int,
        testMode: Boolean
    ): Boolean {
        if (!canPostBatteryProactivityNotification()) {
            return false
        }

        createBatteryProactivityNotificationChannel()

        val openIntent =
            Intent(
                this,
                MainActivity::class.java
            )

        val pendingIntent =
            PendingIntent.getActivity(
                this,
                notificationId,
                openIntent,
                PendingIntent.FLAG_UPDATE_CURRENT or
                    PendingIntent.FLAG_IMMUTABLE
            )

        val builder =
            if (Build.VERSION.SDK_INT >= 26) {
                Notification.Builder(
                    this,
                    BATTERY_PROACTIVITY_CHANNEL_ID
                )
            } else {
                @Suppress("DEPRECATION")
                Notification.Builder(this)
            }

        val title =
            if (testMode) {
                "AYANA — тест проактивности"
            } else {
                "AYANA — низкий заряд"
            }

        val message =
            if (testMode) {
                "Проверка notification-only proactivity без изменения настроек устройства."
            } else {
                "Заряд $batteryPercent%. Порог $thresholdPercent%. Подключите зарядное устройство."
            }

        val notification =
            builder
                .setSmallIcon(
                    android.R.drawable.ic_popup_reminder
                )
                .setContentTitle(title)
                .setContentText(message)
                .setAutoCancel(true)
                .setOnlyAlertOnce(true)
                .setCategory(
                    Notification.CATEGORY_STATUS
                )
                .setContentIntent(
                    pendingIntent
                )
                .build()

        return try {
            val manager =
                getSystemService(
                    NotificationManager::class.java
                )

            manager.notify(
                notificationId,
                notification
            )
            true
        } catch (_: Exception) {
            false
        }
    }

    private fun isNotificationActive(
        notificationId: Int
    ): Boolean {
        if (Build.VERSION.SDK_INT < 23) {
            return false
        }

        return try {
            val manager =
                getSystemService(
                    NotificationManager::class.java
                )

            manager.activeNotifications
                .any {
                    it.id == notificationId
                }
        } catch (_: Exception) {
            false
        }
    }

    private fun cancelProactivityNotification(
        notificationId: Int
    ) {
        try {
            val manager =
                getSystemService(
                    NotificationManager::class.java
                )

            manager.cancel(
                notificationId
            )
        } catch (_: Exception) {
        }
    }

    private fun runBatteryProactivityEnable(
        command: String,
        silent: Boolean
    ) {
        executionPhase(
            phase = "controlled_battery_proactivity_configure",
            executor = "battery_proactivity_controller"
        )

        val requestedThreshold =
            extractBatteryProactivityThreshold(
                command
            ) ?:
                AyanaBatteryProactivityController
                    .DEFAULT_THRESHOLD_PERCENT

        val rule =
            try {
                batteryProactivityController
                    .enable(
                        requestedThreshold
                    )
            } catch (_: Exception) {
                null
            }

        if (rule == null) {
            respondAndResume(
                "Порог низкого заряда должен быть от ${AyanaBatteryProactivityController.MIN_THRESHOLD_PERCENT}% до ${AyanaBatteryProactivityController.MAX_THRESHOLD_PERCENT}%.",
                silent,
                success = false
            )
            return
        }

        // Evaluate the current sticky battery state immediately after explicit
        // opt-in. The rule may only post a notification; no device mutation.
        currentBatteryIntent()
            ?.let { intent ->
                handleBatteryProactivitySample(
                    intent = intent,
                    source = "user_enable_immediate_sample"
                )
            }

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "controlled_proactivity_rule_enabled",
            message = "R9.9.2 low-battery rule enabled",
            details =
                "threshold=${rule.thresholdPercent}; cooldown_ms=${rule.cooldownMs}; max_notifications_per_hour=${rule.maxNotificationsPerHour}; mutation_authority=false"
        )

        finishLocalCommand(
            "Контроль низкого заряда включён: AYANA предупредит уведомлением при ${rule.thresholdPercent}% или ниже. Изменять настройки или запускать действия самостоятельно этот контроль не может.",
            silent
        )
    }

    private fun runBatteryProactivityDisable(
        silent: Boolean
    ) {
        executionPhase(
            phase = "controlled_battery_proactivity_configure",
            executor = "battery_proactivity_controller"
        )

        val rule =
            try {
                batteryProactivityController
                    .disable()
            } catch (_: Exception) {
                null
            }

        if (rule == null) {
            respondAndResume(
                "Не удалось сохранить состояние контроля низкого заряда.",
                silent,
                success = false
            )
            return
        }

        cancelProactivityNotification(
            BATTERY_PROACTIVITY_NOTIFICATION_ID
        )

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "controlled_proactivity_rule_disabled",
            message = "R9.9.2 low-battery rule disabled",
            details = "mutation_authority=false"
        )

        finishLocalCommand(
            "Контроль низкого заряда выключен.",
            silent
        )
    }

    private fun runBatteryProactivityStatus(
        silent: Boolean
    ) {
        executionPhase(
            phase = "controlled_battery_proactivity_status",
            executor = "battery_proactivity_controller"
        )

        val rule =
            try {
                batteryProactivityController
                    .currentRule()
            } catch (_: Exception) {
                null
            }

        if (rule == null) {
            respondAndResume(
                "Не удалось прочитать правило контроля низкого заряда.",
                silent,
                success = false
            )
            return
        }

        val sampleText =
            if (
                lastBatteryProactivityPercent >= 0 &&
                lastBatteryProactivitySampleAtMs > 0L
            ) {
                " Последний battery sample: ${lastBatteryProactivityPercent}%, charging=$lastBatteryProactivityCharging."
            } else {
                ""
            }

        finishLocalCommand(
            if (rule.enabled) {
                "Контроль низкого заряда включён: порог ${rule.thresholdPercent}%, cooldown ${rule.cooldownMs / 60_000L} мин, максимум ${rule.maxNotificationsPerHour} уведомление в час.$sampleText"
            } else {
                "Контроль низкого заряда выключен.$sampleText"
            },
            silent
        )
    }

    private fun runBatteryProactivityAcceptance(
        silent: Boolean
    ) {
        executionPhase(
            phase = "controlled_battery_proactivity_acceptance",
            executor = "battery_proactivity_controller"
        )

        val ruleBefore =
            try {
                batteryProactivityController
                    .currentRule()
            } catch (_: Exception) {
                null
            }

        val controllerSelfTest =
            try {
                batteryProactivityController
                    .selfTest()
            } catch (_: Exception) {
                false
            }

        val foundationPolicySelfTest =
            try {
                controlledProactivityPolicy
                    .selfTest()
            } catch (_: Exception) {
                false
            }

        val liveSample =
            parseBatteryProactivitySample(
                currentBatteryIntent()
            )

        val notificationPermission =
            canPostBatteryProactivityNotification()

        var notificationPosted =
            false

        var notificationVerified =
            false

        var notificationCleanupVerified =
            false

        try {
            cancelProactivityNotification(
                BATTERY_PROACTIVITY_TEST_NOTIFICATION_ID
            )

            notificationPosted =
                postBatteryProactivityNotification(
                    batteryPercent =
                        liveSample?.percent ?: 0,
                    thresholdPercent =
                        AyanaBatteryProactivityController
                            .DEFAULT_THRESHOLD_PERCENT,
                    notificationId =
                        BATTERY_PROACTIVITY_TEST_NOTIFICATION_ID,
                    testMode = true
                )

            if (notificationPosted) {
                SystemClock.sleep(120L)
                notificationVerified =
                    isNotificationActive(
                        BATTERY_PROACTIVITY_TEST_NOTIFICATION_ID
                    )
            }
        } finally {
            cancelProactivityNotification(
                BATTERY_PROACTIVITY_TEST_NOTIFICATION_ID
            )
            SystemClock.sleep(120L)
            notificationCleanupVerified =
                !isNotificationActive(
                    BATTERY_PROACTIVITY_TEST_NOTIFICATION_ID
                )
        }

        val ruleAfter =
            try {
                batteryProactivityController
                    .currentRule()
            } catch (_: Exception) {
                null
            }

        val ruleUnchanged =
            ruleBefore != null &&
                ruleAfter != null &&
                ruleBefore == ruleAfter

        val liveReceiverObserved =
            batteryProactivityReceiverRegistered &&
                (
                    lastBatteryProactivitySampleAtMs > 0L ||
                        liveSample != null
                    )

        val ok =
            controllerSelfTest &&
                foundationPolicySelfTest &&
                notificationPermission &&
                notificationPosted &&
                notificationVerified &&
                notificationCleanupVerified &&
                ruleUnchanged &&
                liveReceiverObserved

        val evidence =
            JSONObject()
                .put(
                    "controller_version",
                    AyanaBatteryProactivityController.VERSION
                )
                .put(
                    "controller_self_test",
                    controllerSelfTest
                )
                .put(
                    "foundation_policy_self_test",
                    foundationPolicySelfTest
                )
                .put(
                    "receiver_registered",
                    batteryProactivityReceiverRegistered
                )
                .put(
                    "live_battery_sample_available",
                    liveSample != null
                )
                .put(
                    "live_battery_percent",
                    liveSample?.percent ?: -1
                )
                .put(
                    "live_battery_charging",
                    liveSample?.charging ?: false
                )
                .put(
                    "notification_permission",
                    notificationPermission
                )
                .put(
                    "test_notification_posted",
                    notificationPosted
                )
                .put(
                    "test_notification_verified",
                    notificationVerified
                )
                .put(
                    "test_notification_cleanup_verified",
                    notificationCleanupVerified
                )
                .put(
                    "persistent_rule_mutation",
                    !ruleUnchanged
                )
                .put(
                    "device_mutation_authority",
                    false
                )
                .put(
                    "broad_proactivity_claimed",
false
                )

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state =
                if (ok) {
                    "controlled_battery_proactivity_acceptance_verified"
                } else {
                    "controlled_battery_proactivity_acceptance_failed"
                },
            message =
                if (ok) {
                    "R9.9.2 opt-in low-battery controlled proactivity подтверждена"
                } else {
                    "R9.9.2 controlled proactivity acceptance обнаружил отклонение"
                },
            details =
                evidence
                    .toString()
                    .take(2200)
        )

        if (ok) {
            finishLocalCommand(
                "R9.9.2 контролируемая проактивность подтверждена: opt-in battery watcher активен, test notification verified/cleaned, mutation authority отсутствует.",
                silent
            )
        } else {
            respondAndResume(
                "R9.9.2 контролируемая проактивность не прошла acceptance. Проверь technical evidence в истории команды.",
                silent,
                success = false
            )
        }
    }

    private fun normalizeReversibleUndoCommand(
        value: String
    ): String =
        value
            .trim()
            .lowercase(Locale.ROOT)
            .replace('ё', 'е')
            .replace(Regex("\\s+"), " ")

    private fun isUndoLastReversibleActionCommand(
        command: String
    ): Boolean {
        val normalized =
            normalizeReversibleUndoCommand(command)

        if (normalized.isBlank()) {
            return false
        }

        // Durable-goal/task cancellation keeps its existing owner.
        if (
            normalized.contains("текущ") ||
            normalized.contains("активн")
        ) {
            if (
                normalized.contains("задач") ||
                normalized.contains("цель") ||
                normalized.contains("команд")
            ) {
                return false
            }
        }

        return normalized in
            setOf(
                "отмени последнее действие",
                "отмени последнее изменение",
                "верни последнее действие",
                "верни последнее изменение",
                "откати последнее действие",
                "откати последнее изменение",
                "undo последнее действие",
                "undo последнее изменение"
            )
    }

    private fun isReversibleActionJournalStatusCommand(
        command: String
    ): Boolean {
        val normalized =
            normalizeReversibleUndoCommand(command)

        return normalized in
            setOf(
                "что можно отменить",
                "какое последнее действие можно отменить",
                "покажи журнал отмены",
                "покажи журнал отмены действий",
                "покажи обратимые действия"
            )
    }

    private fun isReversibleBrightnessUndoAcceptanceCommand(
        command: String
    ): Boolean {
        val normalized =
            normalizeReversibleUndoCommand(command)

        return normalized in
            setOf(
                "проверь отмену яркости",
                "протестируй отмену яркости",
                "проверь rollback яркости",
                "протестируй rollback яркости"
            )
    }

    private fun isReversibleActionJournalAcceptanceCommand(
        command: String
    ): Boolean {
        val normalized =
            normalizeReversibleUndoCommand(command)

        return normalized in
            setOf(
                "проверь журнал отмены действий",
                "протестируй журнал отмены действий",
                "проверь отмену последнего действия",
                "протестируй отмену последнего действия",
                "проверь verified undo",
                "протестируй verified undo"
            )
    }

    private fun recordVerifiedReversibleVolume(
        beforeLevel: Int,
        afterLevel: Int,
        deviceMin: Int,
        deviceMax: Int,
        source: String
    ): AyanaReversibleActionJournal.Entry? {
        val entry =
            try {
                reversibleActionJournal.recordVolume(
                    beforeLevel = beforeLevel,
                    afterLevel = afterLevel,
                    deviceMin = deviceMin,
                    deviceMax = deviceMax,
                    source = source
                )
            } catch (_: Exception) {
                null
            }

        if (entry != null) {
            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "reversible_action_recorded",
                message = "Подтверждённое изменение громкости добавлено в R9.9 undo journal",
                details =
                    "id=${entry.id}; kind=${entry.kind.wireName}; before=$beforeLevel; after=$afterLevel; source=$source"
            )
        }

        return entry
    }

    private fun recordVerifiedReversibleBrightness(
        beforeMode: Int,
        beforeRaw: Int,
        afterMode: Int,
        afterRaw: Int,
        source: String
    ): AyanaReversibleActionJournal.Entry? {
        val entry =
            try {
                reversibleActionJournal.recordBrightness(
                    beforeMode = beforeMode,
                    beforeRaw = beforeRaw,
                    afterMode = afterMode,
                    afterRaw = afterRaw,
                    source = source
                )
            } catch (_: Exception) {
                null
            }

        if (entry != null) {
            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "reversible_action_recorded",
                message = "Подтверждённое изменение яркости добавлено в R9.9 undo journal",
                details =
                    "id=${entry.id}; kind=${entry.kind.wireName}; before_mode=$beforeMode; before_raw=$beforeRaw; after_mode=$afterMode; after_raw=$afterRaw; source=$source"
            )
        }

        return entry
    }

    private fun runLocalReversibleActionJournalStatus(
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_reversible_action_journal_status",
            executor = "reversible_action_journal"
        )

        val latest =
            try {
                reversibleActionJournal.latestUndoable()
            } catch (_: Exception) {
                null
            }

        if (latest == null) {
            finishLocalCommand(
                "Сейчас нет подтверждённого обратимого действия, которое AYANA может безопасно отменить.",
                silent
            )
            return
        }

        val label =
            when (latest.kind) {
                AyanaReversibleActionJournal.Kind.MEDIA_VOLUME ->
                    "последнее изменение громкости"

                AyanaReversibleActionJournal.Kind.SCREEN_BRIGHTNESS ->
                    "последнее изменение яркости"
            }

        finishLocalCommand(
            "Можно отменить $label. Перед откатом AYANA ещё раз проверит, что текущее состояние не изменилось после записанного действия.",
            silent
        )
    }

    private fun runLocalUndoLastReversibleAction(
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_reversible_undo",
            executor = "reversible_action_journal"
        )

        val entry =
            try {
                reversibleActionJournal.latestUndoable()
            } catch (_: Exception) {
                null
            }

        if (entry == null) {
            respondUnsupportedAndResume(
                text = "Нет подтверждённого обратимого действия для отмены. AYANA не заявляет универсальную отмену действий.",
                silent = silent,
                technical = "reversible_undo_no_undoable_entry"
            )
            return
        }

        val result =
            performReversibleUndo(
                entry = entry,
                trackExecutionKernel = true
            )

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state =
                if (result.optBoolean("success", false)) {
                    "reversible_undo_verified"
                } else {
                    "reversible_undo_rejected"
                },
            message =
                result.optString("message")
                    .ifBlank {
                        "Verified undo завершён"
                    },
            details =
                result
                    .toString()
                    .take(1800)
        )

        if (result.optBoolean("success", false)) {
            finishLocalCommand(
                result.optString("message"),
                silent
            )
        } else {
            val reason =
                result.optString("reason")

            if (
                reason == "current_state_diverged" ||
                reason == "write_settings_permission_required"
            ) {
                respondBlockedAndResume(
                    text = result.optString("message"),
                    silent = silent,
                    technical = "reversible_undo:$reason"
                )
            } else {
                respondAndResume(
                    text = result.optString("message")
                        .ifBlank {
                            "Не удалось подтверждённо отменить последнее действие."
                        },
                    silent = silent,
                    success = false,
                    technical = "reversible_undo:${reason.ifBlank { "verification_failed" }}"
                )
            }
        }
    }

    private fun performReversibleUndo(
        entry: AyanaReversibleActionJournal.Entry,
        trackExecutionKernel: Boolean
    ): JSONObject {
        return when (entry.kind) {
            AyanaReversibleActionJournal.Kind.MEDIA_VOLUME ->
                performVolumeUndo(
                    entry = entry,
                    trackExecutionKernel = trackExecutionKernel
                )

            AyanaReversibleActionJournal.Kind.SCREEN_BRIGHTNESS ->
                performBrightnessUndo(
                    entry = entry,
                    trackExecutionKernel = trackExecutionKernel
                )
        }
    }

    private fun performVolumeUndo(
        entry: AyanaReversibleActionJournal.Entry,
        trackExecutionKernel: Boolean
    ): JSONObject {
        val beforeLevel =
            entry.before.optInt("level", -1)

        val afterLevel =
            entry.after.optInt("level", -1)

        val recordedMin =
            entry.before.optInt("device_min", -1)

        val recordedMax =
            entry.before.optInt("device_max", -1)

        val audioManager =
            getSystemService(Context.AUDIO_SERVICE) as AudioManager

        val liveMax =
            try {
                audioManager.getStreamMaxVolume(
                    AudioManager.STREAM_MUSIC
                )
            } catch (_: Exception) {
                -1
            }

        val liveMin =
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
                try {
                    audioManager.getStreamMinVolume(
                        AudioManager.STREAM_MUSIC
                    )
                } catch (_: Exception) {
                    -1
                }
            } else {
                0
            }

        val current =
            try {
                audioManager.getStreamVolume(
                    AudioManager.STREAM_MUSIC
                )
            } catch (_: Exception) {
                -1
            }

        val precondition =
            reversibleActionJournal
                .validateVolumeUndoPrecondition(
                    entry = entry,
                    currentLevel = current,
                    deviceMin = liveMin,
                    deviceMax = liveMax
                )
if (
            !precondition.optBoolean(
                "allowed",
                false
            )
        ) {
            return JSONObject()
                .put("success", false)
                .put("verified", false)
                .put(
                    "reason",
                    precondition.optString(
                        "reason",
                        "current_state_diverged"
                    )
                )
                .put("kind", entry.kind.wireName)
                .put("precondition", precondition)
                .put(
                    "message",
                    "Отмена остановлена: текущая громкость уже отличается от состояния сразу после записанного действия. AYANA ничего не изменила."
                )
        }

        if (
            trackExecutionKernel &&
            !beginLocalVerifiedSideEffect(
                kind = "reversible_undo_media_volume",
                detail = "journal=${entry.id}; current=$current; restore=$beforeLevel"
            )
        ) {
            return JSONObject()
                .put("success", false)
                .put("verified", false)
                .put("reason", "dispatch_cancelled")
                .put("message", "Отмена остановлена до изменения громкости.")
        }

        val dispatched =
            try {
                audioManager.setStreamVolume(
                    AudioManager.STREAM_MUSIC,
                    beforeLevel,
                    AudioManager.FLAG_SHOW_UI
                )
                true
            } catch (_: Exception) {
                false
            }

        if (trackExecutionKernel && dispatched) {
            executionKernel.markIrreversibleDispatchAccepted(
                "reversible_undo_media_volume:${entry.id}"
            )
            executionKernel.markSideEffectReconciliationStarted(
                "verify_reversible_undo_media_volume"
            )
        }

        try {
            Thread.sleep(80L)
        } catch (_: Exception) {
        }

        val actual =
            try {
                audioManager.getStreamVolume(
                    AudioManager.STREAM_MUSIC
                )
            } catch (_: Exception) {
                -1
            }

        val verified =
            dispatched &&
                actual == beforeLevel

        if (trackExecutionKernel) {
            if (!dispatched) {
                markLocalSideEffectNotCommitted(
                    "reversible_undo_media_volume_dispatch_failed"
                )
            } else {
                executionKernel.markSideEffectReconciled(
                    committed = verified,
                    detail = "restore=$beforeLevel; actual=$actual"
                )
            }
        }

        try {
            reversibleActionJournal.markUndoResult(
                id = entry.id,
                verified = verified,
                reason =
                    if (verified) {
                        "verified_restore:$actual"
                    } else {
                        "restore_failed:$actual"
                    }
            )
        } catch (_: Exception) {
        }

        return JSONObject()
            .put("success", verified)
            .put("verified", verified)
            .put(
                "reason",
                if (verified) {
                    "verified_undo"
                } else {
                    "verification_failed"
                }
            )
            .put("kind", entry.kind.wireName)
            .put("expected_current", afterLevel)
            .put("actual_before_undo", current)
            .put("restore_target", beforeLevel)
            .put("actual_after_undo", actual)
            .put(
                "message",
                if (verified) {
                    "Последнее изменение громкости отменено и подтверждено: $afterLevel → $actual из $liveMax."
                } else {
                    "Не удалось подтвердить отмену изменения громкости: ожидалось $beforeLevel, фактически $actual."
                }
            )
    }

    private fun performBrightnessUndo(
        entry: AyanaReversibleActionJournal.Entry,
        trackExecutionKernel: Boolean
    ): JSONObject {
        if (
            Build.VERSION.SDK_INT >= Build.VERSION_CODES.M &&
            !Settings.System.canWrite(this)
        ) {
            return JSONObject()
                .put("success", false)
                .put("verified", false)
                .put("reason", "write_settings_permission_required")
                .put(
                    "message",
                    "Отмена яркости требует системный доступ «Изменение системных настроек». Состояние не изменено."
                )
        }

        val beforeMode =
            entry.before.optInt("mode", -1)
        val beforeRaw =
            entry.before.optInt("raw", -1)
        val afterMode =
            entry.after.optInt("mode", -1)
        val afterRaw =
            entry.after.optInt("raw", -1)

        val currentMode =
            try {
                Settings.System.getInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS_MODE,
                    -1
                )
            } catch (_: Exception) {
                -1
            }

        val currentRaw =
            try {
                Settings.System.getInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS,
                    -1
                )
            } catch (_: Exception) {
                -1
            }

        val precondition =
            reversibleActionJournal
                .validateBrightnessUndoPrecondition(
                    entry = entry,
                    currentMode = currentMode,
                    currentRaw = currentRaw
                )

        if (
            !precondition.optBoolean(
                "allowed",
                false
            )
        ) {
            return JSONObject()
                .put("success", false)
                .put("verified", false)
                .put(
                    "reason",
                    precondition.optString(
                        "reason",
                        "current_state_diverged"
                    )
                )
                .put("kind", entry.kind.wireName)
                .put("precondition", precondition)
                .put(
                    "message",
                    "Отмена остановлена: яркость или режим экрана уже изменились после записанного действия. AYANA ничего не изменила."
                )
        }

        if (
            trackExecutionKernel &&
            !beginLocalVerifiedSideEffect(
                kind = "reversible_undo_screen_brightness",
                detail = "journal=${entry.id}; restore_mode=$beforeMode; restore_raw=$beforeRaw"
            )
        ) {
            return JSONObject()
                .put("success", false)
                .put("verified", false)
                .put("reason", "dispatch_cancelled")
                .put("message", "Отмена остановлена до изменения яркости.")
        }

        val rawWritten =
            try {
                Settings.System.putInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS,
                    beforeRaw
                )
            } catch (_: Exception) {
                false
            }

        val modeWritten =
            try {
                Settings.System.putInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS_MODE,
                    beforeMode
                )
            } catch (_: Exception) {
                false
            }

        val dispatched =
            rawWritten &&
                modeWritten

        if (trackExecutionKernel && dispatched) {
            executionKernel.markIrreversibleDispatchAccepted(
                "reversible_undo_screen_brightness:${entry.id}"
            )
            executionKernel.markSideEffectReconciliationStarted(
                "verify_reversible_undo_screen_brightness"
            )
        }

        try {
            Thread.sleep(120L)
        } catch (_: Exception) {
        }

        val restoredMode =
            try {
                Settings.System.getInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS_MODE,
                    -1
                )
            } catch (_: Exception) {
                -1
            }

        val restoredRaw =
            try {
                Settings.System.getInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS,
                    -1
                )
            } catch (_: Exception) {
                -1
            }

        val rawVerified =
            if (
                beforeMode ==
                Settings.System.SCREEN_BRIGHTNESS_MODE_MANUAL
            ) {
                restoredRaw >= 0 &&
                    abs(restoredRaw - beforeRaw) <= 2
            } else {
                // Automatic mode may immediately choose another numeric brightness.
                true
            }

        val verified =
            dispatched &&
                restoredMode == beforeMode &&
                rawVerified

        if (trackExecutionKernel) {
            if (!dispatched) {
                markLocalSideEffectNotCommitted(
                    "reversible_undo_screen_brightness_dispatch_failed"
                )
            } else {
                executionKernel.markSideEffectReconciled(
                    committed = verified,
                    detail =
                        "mode=$beforeMode/$restoredMode; raw=$beforeRaw/$restoredRaw"
                )
            }
        }

        try {
            reversibleActionJournal.markUndoResult(
                id = entry.id,
                verified = verified,
                reason =
                    if (verified) {
                        "verified_restore:mode=$restoredMode;raw=$restoredRaw"
                    } else {
                        "restore_failed:mode=$restoredMode;raw=$restoredRaw"
                    }
            )
        } catch (_: Exception) {
        }

        return JSONObject()
            .put("success", verified)
            .put("verified", verified)
            .put(
                "reason",
                if (verified) {
                    "verified_undo"
                } else {
                    "verification_failed"
                }
            )
            .put("kind", entry.kind.wireName)
            .put("restore_mode", beforeMode)
            .put("restore_raw", beforeRaw)
            .put("actual_mode", restoredMode)
            .put("actual_raw", restoredRaw)
            .put(
                "message",
                if (verified) {
                    "Последнее изменение яркости отменено и подтверждено."
                } else {
                    "Не удалось подтверждённо восстановить предыдущее состояние яркости."
                }
            )
    }

    private fun runLocalReversibleBrightnessUndoAcceptance(
        silent: Boolean
    ) {
        executionPhase(
            phase = "reversible_brightness_undo_acceptance",
            executor = "reversible_action_journal"
        )

        if (
            Build.VERSION.SDK_INT >= Build.VERSION_CODES.M &&
            !Settings.System.canWrite(this)
        ) {
            respondUnsupportedAndResume(
                text = "R9.9.1 acceptance яркости требует системный доступ «Изменение системных настроек».",
                silent = silent,
                technical = "r9_9_1_brightness_acceptance_write_settings_required"
            )
            return
        }

        val originalMode =
            try {
                Settings.System.getInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS_MODE,
                    -1
                )
            } catch (_: Exception) {
                -1
            }

        val originalRaw =
            try {
                Settings.System.getInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS,
                    -1
                )
            } catch (_: Exception) {
                -1
            }

        if (originalMode < 0 || originalRaw !in 0..255) {
            respondAndResume(
                text = "R9.9.1 acceptance: исходное состояние яркости не удалось прочитать.",
                silent = silent,
                success = false,
                technical = "r9_9_1_brightness_acceptance_original_unavailable"
            )
            return
        }

        val targetMode =
            Settings.System.SCREEN_BRIGHTNESS_MODE_MANUAL

        val targetRaw =
            if (originalRaw <= 223) {
                (originalRaw + 24).coerceAtMost(255)
            } else {
                (originalRaw - 24).coerceAtLeast(0)
            }

        var entry: AyanaReversibleActionJournal.Entry? = null
        var observedTargetMode = originalMode
        var observedTargetRaw = originalRaw
        var observedRestoredMode = originalMode
        var observedRestoredRaw = originalRaw
        var undoResult = JSONObject()
        var cleanup = false

        try {
            val modeWritten =
                Settings.System.putInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS_MODE,
                    targetMode
                )

            val rawWritten =
                Settings.System.putInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS,
                    targetRaw
                )

            Thread.sleep(120L)

            observedTargetMode =
                Settings.System.getInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS_MODE,
                    -1
                )

            observedTargetRaw =
                Settings.System.getInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS,
                    -1
                )

            val targetVerified =
                modeWritten &&
                    rawWritten &&
                    observedTargetMode == targetMode &&
                    abs(observedTargetRaw - targetRaw) <= 2

            if (!targetVerified) {
                respondAndResume(
                    text = "R9.9.1 acceptance: тестовое изменение яркости не подтвердилось.",
                    silent = silent,
                    success = false,
                    technical = "r9_9_1_brightness_acceptance_target_not_verified"
                )
                return
            }

            entry =
                recordVerifiedReversibleBrightness(
                    beforeMode = originalMode,
                    beforeRaw = originalRaw,
                    afterMode = observedTargetMode,
                    afterRaw = observedTargetRaw,
                    source = "r9_9_1_brightness_device_acceptance"
                )

            if (entry == null) {
                respondAndResume(
                    text = "R9.9.1 acceptance: journal не создал verified brightness undo record.",
                    silent = silent,
                    success = false,
                    technical = "r9_9_1_brightness_acceptance_record_missing"
                )
                return
            }

            undoResult =
                performReversibleUndo(
                    entry = entry,
                    trackExecutionKernel = false
                )

            observedRestoredMode =
                Settings.System.getInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS_MODE,
                    -1
                )

            observedRestoredRaw =
                Settings.System.getInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS,
                    -1
                )

            val rawRestored =
                if (
                    originalMode ==
                    Settings.System.SCREEN_BRIGHTNESS_MODE_MANUAL
                ) {
                    abs(observedRestoredRaw - originalRaw) <= 2
                } else {
                    true
                }

            val contractOk =
                try {
                    reversibleActionJournal.selfTest()
                } catch (_: Exception) {
                    false
                }

            cleanup =
                try {
                    reversibleActionJournal.remove(entry.id)
                } catch (_: Exception) {
                    false
                }

            val ok =
                contractOk &&
                    undoResult.optBoolean("success", false) &&
                    undoResult.optBoolean("verified", false) &&
                    observedRestoredMode == originalMode &&
                    rawRestored &&
                    cleanup

            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state =
                    if (ok) {
                        "reversible_brightness_undo_acceptance_verified"
                    } else {
                        "reversible_brightness_undo_acceptance_failed"
                    },
                message =
                    if (ok) {
                        "R9.9.1 brightness verified undo acceptance подтверждён"
                    } else {
                        "R9.9.1 brightness verified undo acceptance обнаружил отклонение"
                    },
                details =
                    JSONObject()
                        .put("journal_version", AyanaReversibleActionJournal.VERSION)
                        .put("original_mode", originalMode)
                        .put("original_raw", originalRaw)
                        .put("target_mode", targetMode)
                        .put("target_raw", targetRaw)
                        .put("observed_target_mode", observedTargetMode)
                        .put("observed_target_raw", observedTargetRaw)
                        .put("observed_restored_mode", observedRestoredMode)
                        .put("observed_restored_raw", observedRestoredRaw)
                        .put("undo", undoResult)
                        .put("contract_self_test", contractOk)
                        .put("persistent_mutation_detected", !ok && (observedRestoredMode != originalMode || !rawRestored))
                        .put("test_entry_cleanup_verified", cleanup)
                        .toString()
                        .take(3000)
            )

            if (ok) {
                finishLocalCommand(
                    "R9.9.1 verified undo яркости подтверждён: mode/raw $originalMode/$originalRaw → $observedTargetMode/$observedTargetRaw → $observedRestoredMode/$observedRestoredRaw, rollback read-back verified.",
                    silent
                )
            } else {
                respondAndResume(
                    text = "R9.9.1 verified undo яркости не прошёл acceptance: исходное состояние не было полностью подтверждено после rollback.",
                    silent = silent,
                    success = false,
                    technical = "r9_9_1_brightness_undo_acceptance_failed"
                )
            }
        } catch (error: Exception) {
            respondAndResume(
                text = "R9.9.1 brightness undo acceptance завершился ошибкой: ${error.message ?: error.javaClass.simpleName}",
                silent = silent,
                success = false,
                technical = "r9_9_1_brightness_acceptance_exception:${error.javaClass.simpleName}"
            )
        } finally {
            try {
                Settings.System.putInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS,
                    originalRaw
                )
                Settings.System.putInt(
contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS_MODE,
                    originalMode
                )
                Thread.sleep(120L)
            } catch (_: Exception) {
            }

            val id = entry?.id
            if (!cleanup && !id.isNullOrBlank()) {
                cleanup =
                    try {
                        reversibleActionJournal.remove(id)
                    } catch (_: Exception) {
                        false
                    }
            }

            if (!cleanup && !entry?.id.isNullOrBlank()) {
                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "reversible_brightness_undo_acceptance_cleanup_warning",
                    message = "Тестовая запись R9.9.1 яркости не была удалена из журнала",
                    details = "entry=${entry?.id}"
                )
            }
        }
    }

    private fun runLocalReversibleActionJournalAcceptance(
        silent: Boolean
    ) {
        executionPhase(
            phase = "reversible_action_journal_acceptance",
            executor = "reversible_action_journal"
        )

        val audioManager =
            getSystemService(Context.AUDIO_SERVICE) as AudioManager

        val max =
            audioManager.getStreamMaxVolume(
                AudioManager.STREAM_MUSIC
            )

        val min =
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
                audioManager.getStreamMinVolume(
                    AudioManager.STREAM_MUSIC
                )
            } else {
                0
            }

        val original =
            audioManager.getStreamVolume(
                AudioManager.STREAM_MUSIC
            )

        if (max <= min) {
            respondUnsupportedAndResume(
                text = "Диапазон media volume не позволяет выполнить R9.9 acceptance.",
                silent = silent,
                technical = "r9_9_acceptance_volume_range_unavailable"
            )
            return
        }

        val target =
            if (original < max) {
                original + 1
            } else {
                original - 1
            }.coerceIn(min, max)

        var entry: AyanaReversibleActionJournal.Entry? = null
        var observedTarget = original
        var observedRestored = original
        var undoResult = JSONObject()
        var cleanup = false

        try {
            audioManager.setStreamVolume(
                AudioManager.STREAM_MUSIC,
                target,
                0
            )
            Thread.sleep(90L)
            observedTarget =
                audioManager.getStreamVolume(
                    AudioManager.STREAM_MUSIC
                )

            if (observedTarget != target) {
                respondAndResume(
                    text = "R9.9 acceptance: тестовое изменение громкости не подтвердилось.",
                    silent = silent,
                    success = false,
                    technical = "r9_9_acceptance_target_not_verified"
                )
                return
            }

            entry =
                recordVerifiedReversibleVolume(
                    beforeLevel = original,
                    afterLevel = observedTarget,
                    deviceMin = min,
                    deviceMax = max,
                    source = "r9_9_device_acceptance"
                )

            if (entry == null) {
                respondAndResume(
                    text = "R9.9 acceptance: journal не создал verified undo record.",
                    silent = silent,
                    success = false,
                    technical = "r9_9_acceptance_record_missing"
                )
                return
            }

            undoResult =
                performReversibleUndo(
                    entry = entry,
                    trackExecutionKernel = false
                )

            observedRestored =
                audioManager.getStreamVolume(
                    AudioManager.STREAM_MUSIC
                )

            val contractOk =
                try {
                    reversibleActionJournal.selfTest()
                } catch (_: Exception) {
                    false
                }

            cleanup =
                try {
                    reversibleActionJournal.remove(entry.id)
                } catch (_: Exception) {
                    false
                }

            val ok =
                contractOk &&
                    undoResult.optBoolean("success", false) &&
                    undoResult.optBoolean("verified", false) &&
                    observedRestored == original &&
                    cleanup &&
                    reversibleActionJournal
                        .summary(8)
                        .optBoolean("universal_undo_claimed", true)
                        .not()

            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state =
                    if (ok) {
                        "reversible_action_journal_acceptance_verified"
                    } else {
                        "reversible_action_journal_acceptance_failed"
                    },
                message =
                    if (ok) {
                        "R9.9 verified undo acceptance подтверждён"
                    } else {
                        "R9.9 verified undo acceptance обнаружил отклонение"
                    },
                details =
                    JSONObject()
                        .put("journal_version", AyanaReversibleActionJournal.VERSION)
                        .put("original", original)
                        .put("target", target)
                        .put("observed_target", observedTarget)
                        .put("observed_restored", observedRestored)
                        .put("undo", undoResult)
                        .put("contract_self_test", contractOk)
                        .put("persistent_mutation_detected", observedRestored != original)
                        .put("test_entry_cleanup_verified", cleanup)
                        .toString()
                        .take(2600)
            )

            if (ok) {
                finishLocalCommand(
                    "R9.9 verified undo подтверждён: media volume $original → $target → $observedRestored, rollback read-back verified, persistent mutation отсутствует.",
                    silent
                )
            } else {
                respondAndResume(
                    text = "R9.9 verified undo не прошёл acceptance: исходное состояние не было полностью подтверждено после rollback.",
                    silent = silent,
                    success = false,
                    technical = "r9_9_reversible_undo_acceptance_failed"
                )
            }
        } catch (error: Exception) {
            respondAndResume(
                text = "R9.9 verified undo acceptance завершился ошибкой: ${error.message ?: error.javaClass.simpleName}",
                silent = silent,
                success = false,
                technical = "r9_9_acceptance_exception:${error.javaClass.simpleName}"
            )
        } finally {
            try {
                val current =
                    audioManager.getStreamVolume(
                        AudioManager.STREAM_MUSIC
                    )

                if (current != original) {
                    audioManager.setStreamVolume(
                        AudioManager.STREAM_MUSIC,
                        original,
                        0
                    )
                    Thread.sleep(90L)
                }
            } catch (_: Exception) {
            }

            val id = entry?.id
            if (!cleanup && !id.isNullOrBlank()) {
                cleanup =
                    try {
                        reversibleActionJournal.remove(id)
                    } catch (_: Exception) {
                        false
                    }
            }

            if (!cleanup && !entry?.id.isNullOrBlank()) {
                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "reversible_action_journal_acceptance_cleanup_warning",
                    message = "Тестовая запись R9.9 не была удалена из журнала",
                    details = "entry=${entry?.id}"
                )
            }
        }
    }

    private data class ExactMediaVolumeRequest(
        val requestedLevel: Int,
        val requestedScaleMax: Int?,
        val percent: Boolean = false
    )

    private fun isRecentNotificationsReadRequest(
        command: String
    ): Boolean {
        val c =
            command
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()

        if (!c.contains("уведомлен")) {
            return false
        }

        val settingsIntent =
            c.contains("настрой") ||
                c.contains("разреш") ||
                c.contains("доступ к уведом") ||
                c.contains("категор") ||
                c.contains("выключ") ||
                c.contains("включ")

        if (settingsIntent) {
            return false
        }

        return c.contains("последн") ||
            c.contains("недавн") ||
            c.contains("текущ") ||
            c.contains("новые уведом") ||
            c.contains("какие уведом") ||
            c.contains("что пришло") ||
            c.contains("прочитай уведом") ||
            c.contains("прочти уведом") ||
            c.contains("перечисли уведом") ||
            (
                c.contains("покажи") &&
                    (
                        c.contains("на планшете") ||
                            c.contains("мои уведом")
                        )
                )
    }

    private fun runLocalRecentNotificationsCommand(
        silent: Boolean,
        limit: Int = 8,
        appFilter: String? = null,
        projection: String = AyanaNotificationListenerService.PROJECTION_FULL
    ) {
        val normalizedProjection =
            when (projection) {
                AyanaNotificationListenerService.PROJECTION_APP_NAMES_ONLY ->
                    AyanaNotificationListenerService.PROJECTION_APP_NAMES_ONLY

                AyanaNotificationListenerService.PROJECTION_TITLES ->
                    AyanaNotificationListenerService.PROJECTION_TITLES

                else ->
                    AyanaNotificationListenerService.PROJECTION_FULL
            }

        val result =
            AyanaNotificationListenerService
                .readRecent(
                    context = this,
                    limit = limit,
                    appFilter = appFilter,
                    projection = normalizedProjection
                )

        if (!result.optBoolean("success", false)) {
            respondAndResume(
                result.optString("message")
                    .ifBlank {
                        "Не удалось прочитать последние уведомления."
                    },
                silent,
                success = false,
                terminalStatus =
                    when (result.optString("terminal_status")) {
                        "BLOCKED" -> AyanaCommandHistoryStore.STATUS_BLOCKED
                        "UNSUPPORTED" -> AyanaCommandHistoryStore.STATUS_UNSUPPORTED
                        else -> null
                    }
            )
            return
        }

        val items =
            result.optJSONArray("notifications")
                ?: JSONArray()

        if (items.length() == 0) {
            finishLocalCommand(
                if (
                    normalizedProjection ==
                    AyanaNotificationListenerService.PROJECTION_APP_NAMES_ONLY
                ) {
                    "Приложений с последними уведомлениями, доступными AYANA, сейчас нет."
                } else {
                    "Последних уведомлений, доступных AYANA, сейчас нет."
                },
                silent
            )
            return
        }

        val lines =
            ArrayList<String>()

        when (normalizedProjection) {
            AyanaNotificationListenerService.PROJECTION_APP_NAMES_ONLY -> {
                val seenApps =
                    linkedSetOf<String>()

                for (index in 0 until items.length()) {
                    val item = items.optJSONObject(index) ?: continue
                    val app =
                        item.optString("app")
                            .trim()
                            .ifBlank { "Приложение" }

                    val dedupeKey =
                        item.optString("package")
                            .trim()
                            .lowercase(Locale.ROOT)
                            .ifBlank {
                                app.lowercase(Locale.ROOT)
                            }

                    if (!seenApps.add(dedupeKey)) {
                        continue
                    }

                    lines.add(
                        "${lines.size + 1}). $app"
                    )
                }
            }
AyanaNotificationListenerService.PROJECTION_TITLES -> {
                for (index in 0 until items.length()) {
                    val item = items.optJSONObject(index) ?: continue
                    val app =
                        item.optString("app")
                            .trim()
                            .ifBlank { "Приложение" }
                    val title =
                        item.optString("title")
                            .replace(Regex("\\s+"), " ")
                            .trim()
                            .take(180)

                    lines.add(
                        buildString {
                            append(index + 1)
                            append("). ")
                            append(app)
                            if (title.isNotBlank()) {
                                append(" — ")
                                append(title)
                            }
                        }
                    )
                }
            }

            else -> {
                for (index in 0 until items.length()) {
                    val item = items.optJSONObject(index) ?: continue
                    val app = item.optString("app").trim()
                    val title = item.optString("title").trim()
                    val text = item.optString("text").trim()

                    val content =
                        listOf(title, text)
                            .filter { it.isNotBlank() }
                            .distinct()
                            .joinToString(": ")
                            .replace(
                                Regex("\\s+"),
                                " "
                            )
                            .trim()
                            .take(320)

                    lines.add(
                        buildString {
                            append(index + 1)
                            append("). ")
                            append(app.ifBlank { "Приложение" })
                            if (content.isNotBlank()) {
                                append(" — ")
                                append(content)
                            }
                        }
                    )
                }
            }
        }

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "notifications_read",
            message = "Последние уведомления прочитаны локально с privacy projection",
            details =
                "projection=$normalizedProjection; requested_limit=$limit; " +
                    "app_filter=${appFilter.orEmpty().take(80)}; count=${lines.size}; " +
                    "listener_connected=${result.optBoolean("listener_connected", false)}"
        )

        finishLocalCommand(
            lines.joinToString("\n"),
            silent
        )
    }

    private fun normalizeRussianSmallNumbersForRouting(
        text: String
    ): String {
        var out = text

        val replacements =
            listOf(
                "пятнадцати" to "15", "пятнадцать" to "15",
                "четырнадцати" to "14", "четырнадцать" to "14",
                "тринадцати" to "13", "тринадцать" to "13",
                "двенадцати" to "12", "двенадцать" to "12",
                "одиннадцати" to "11", "одиннадцать" to "11",
                "десяти" to "10", "десять" to "10",
                "девяти" to "9", "девять" to "9",
                "восьми" to "8", "восемь" to "8",
                "семи" to "7", "семь" to "7",
                "шести" to "6", "шесть" to "6",
                "пяти" to "5", "пять" to "5",
                "четырех" to "4", "четыре" to "4",
                "трех" to "3", "три" to "3",
                "двух" to "2", "две" to "2", "два" to "2",
                "одного" to "1", "одну" to "1", "одна" to "1", "один" to "1",
                "нуля" to "0", "ноль" to "0", "нуль" to "0"
            )

        replacements.forEach { (word, number) ->
            out =
                out.replace(
                    Regex("(?<![\\p{L}\\p{N}])${Regex.escape(word)}(?![\\p{L}\\p{N}])"),
                    number
                )
        }

        return out
            .replace(Regex("\\s+"), " ")
            .trim()
    }

    private fun extractBrightnessVerifiedRoundTripTarget(
        command: String
    ): Int? {
        val c =
            normalizeRussianSmallNumbersForRouting(
                command
                    .lowercase(Locale.ROOT)
                    .replace('ё', 'е')
                    .replace(Regex("\\s+"), " ")
                    .trim()
            )

        if (!c.contains("ярк")) return null

        val captureOriginal =
            c.contains("запомни текущ") ||
                c.contains("сохрани текущ") ||
                c.contains("исходн")

        val setIntent =
            c.contains("установ") ||
                c.contains("постав") ||
                c.contains("выстав")

        val undoIntent =
            c.contains("отмени") ||
                c.contains("верни") ||
                c.contains("восстанов")

        val verifyIntent =
            c.contains("проверь") ||
                c.contains("подтверд")

        if (!captureOriginal || !setIntent || !undoIntent || !verifyIntent) {
            return null
        }

        val percent =
            Regex("""(\d{1,3})\s*(?:%|процент(?:а|ов)?)""")
                .find(c)
                ?.groupValues
                ?.getOrNull(1)
                ?.toIntOrNull()
                ?: return null

        return percent.takeIf { it in 0..100 }
    }

    private fun runLocalBrightnessVerifiedRoundTrip(
        targetPercent: Int,
        silent: Boolean
    ) {
        executionPhase(
            phase = "field_brightness_roundtrip",
            executor = "brightness_executor+reversible_action_journal"
        )

        if (
            Build.VERSION.SDK_INT >= Build.VERSION_CODES.M &&
            !Settings.System.canWrite(this)
        ) {
            respondBlockedAndResume(
                text = "Для проверяемого изменения и возврата яркости нужен системный доступ «Изменение системных настроек». Ничего не изменено.",
                silent = silent,
                technical = "field_brightness_roundtrip_write_settings_required"
            )
            return
        }

        val originalMode =
            try {
                Settings.System.getInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS_MODE,
                    -1
                )
            } catch (_: Exception) {
                -1
            }

        val originalRaw =
            try {
                Settings.System.getInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS,
                    -1
                )
            } catch (_: Exception) {
                -1
            }

        if (originalMode < 0 || originalRaw !in 0..255) {
            respondAndResume(
                text = "Не удалось надёжно прочитать исходную яркость; изменение не выполнялось.",
                silent = silent,
                success = false,
                technical = "field_brightness_roundtrip_original_unavailable"
            )
            return
        }

        val targetRaw =
            ((targetPercent / 100.0) * 255.0)
                .toInt()
                .coerceIn(0, 255)

        if (
            !beginLocalVerifiedSideEffect(
                kind = "screen_brightness_verified_roundtrip",
                detail = "original_mode=$originalMode; original_raw=$originalRaw; target_percent=$targetPercent; target_raw=$targetRaw"
            )
        ) {
            respondAndResume(
                text = "Проверяемое изменение яркости отменено до dispatch.",
                silent = silent,
                success = false,
                technical = "field_brightness_roundtrip_dispatch_rejected"
            )
            return
        }

        var dispatchAccepted = false
        var targetVerified = false
        var restoredVerified = false
        var observedTargetMode = originalMode
        var observedTargetRaw = originalRaw
        var observedRestoredMode = originalMode
        var observedRestoredRaw = originalRaw
        var entry: AyanaReversibleActionJournal.Entry? = null
        var failure = ""

        try {
            val modeWritten =
                Settings.System.putInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS_MODE,
                    Settings.System.SCREEN_BRIGHTNESS_MODE_MANUAL
                )

            val rawWritten =
                Settings.System.putInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS,
                    targetRaw
                )

            dispatchAccepted = modeWritten || rawWritten
            if (dispatchAccepted) {
                executionKernel.markIrreversibleDispatchAccepted(
                    "field_brightness_roundtrip_target=$targetRaw"
                )
                executionKernel.markSideEffectReconciliationStarted(
                    "field_brightness_roundtrip_verify_target_then_restore"
                )
            }

            Thread.sleep(120L)

            observedTargetMode =
                Settings.System.getInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS_MODE,
                    -1
                )

            observedTargetRaw =
                Settings.System.getInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS,
                    -1
                )

            targetVerified =
                modeWritten &&
                    rawWritten &&
                    observedTargetMode == Settings.System.SCREEN_BRIGHTNESS_MODE_MANUAL &&
                    abs(observedTargetRaw - targetRaw) <= 2

            if (!targetVerified) {
                failure = "target_not_verified"
            } else {
                entry =
                    recordVerifiedReversibleBrightness(
                        beforeMode = originalMode,
                        beforeRaw = originalRaw,
                        afterMode = observedTargetMode,
                        afterRaw = observedTargetRaw,
                        source = "r10_24_field_brightness_roundtrip"
                    )

                if (entry == null) {
                    failure = "journal_record_missing"
                } else {
                    val undo =
                        performReversibleUndo(
                            entry = entry!!,
                            trackExecutionKernel = false
                        )

                    if (!undo.optBoolean("verified", false)) {
                        failure = "undo_not_verified:${undo.optString("reason")}"
                    }
                }
            }
        } catch (error: Exception) {
            failure = "exception:${error.javaClass.simpleName}"
        } finally {
            // Last-resort restore is unconditional. The user's requested terminal state is
            // the exact original mode/value; no temporary test mutation may be left behind.
            try {
                Settings.System.putInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS,
                    originalRaw
                )
                Settings.System.putInt(
                    contentResolver,
                    Settings.System.SCREEN_BRIGHTNESS_MODE,
                    originalMode
                )
                Thread.sleep(120L)
            } catch (_: Exception) {
            }

            observedRestoredMode =
                try {
                    Settings.System.getInt(
                        contentResolver,
                        Settings.System.SCREEN_BRIGHTNESS_MODE,
                        -1
                    )
                } catch (_: Exception) {
                    -1
                }

            observedRestoredRaw =
                try {
                    Settings.System.getInt(
                        contentResolver,
                        Settings.System.SCREEN_BRIGHTNESS,
                        -1
                    )
                } catch (_: Exception) {
                    -1
                }

            val rawRestored =
                if (originalMode == Settings.System.SCREEN_BRIGHTNESS_MODE_MANUAL) {
                    observedRestoredRaw >= 0 &&
                        abs(observedRestoredRaw - originalRaw) <= 2
                } else {
                    true
                }

            restoredVerified =
                observedRestoredMode == originalMode &&
                    rawRestored

            if (dispatchAccepted) {
                // R10.24.1 terminal convergence: the side-effect boundary here is the
                // *round-trip operation*, not a persistent brightness mutation. A verified
                // set -> verify -> undo -> restore sequence is therefore a committed
                // successful operation even though persistent_mutation=false.
                val roundTripOperationCommitted =
                    targetVerified &&
                        entry != null &&
                        restoredVerified &&
                        failure.isBlank()

                executionKernel.markSideEffectReconciled(
                    committed = roundTripOperationCommitted,
                    detail =
                        "field_brightness_roundtrip_complete=$roundTripOperationCommitted; " +
                            "restored=$restoredVerified; persistent_mutation=${!restoredVerified}; " +
                            "original=$originalMode/$originalRaw; restored_state=$observedRestoredMode/$observedRestoredRaw"
                )
            } else {
                markLocalSideEffectNotCommitted(
                    "field_brightness_roundtrip_no_dispatch"
                )
            }
        }

        val ok =
            targetVerified &&
                entry != null &&
                restoredVerified &&
                failure.isBlank()

        val evidence =
            JSONObject()
                .put("target_percent", targetPercent)
                .put("original_mode", originalMode)
                .put("original_raw", originalRaw)
                .put("observed_target_mode", observedTargetMode)
                .put("observed_target_raw", observedTargetRaw)
                .put("target_verified", targetVerified)
                .put("journal_recorded", entry != null)
                .put("restored_mode", observedRestoredMode)
                .put("restored_raw", observedRestoredRaw)
                .put("restored_verified", restoredVerified)
                .put("persistent_mutation", !restoredVerified)
                .put("failure", failure)

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state =
                if (ok) {
                    "field_brightness_roundtrip_verified"
                } else {
                    "field_brightness_roundtrip_failed"
                },
            message =
                if (ok) {
                    "R10.24 brightness read → set → verify → undo → verify подтверждён"
                } else {
                    "R10.24 brightness round-trip не прошёл полную проверку"
                },
            details = evidence.toString().take(2600)
        )

        if (ok) {
            val originalPercent =
                ((originalRaw * 100.0) / 255.0)
                    .toInt()
                    .coerceIn(0, 100)

            finishLocalCommand(
                "Яркость проверена: исходно примерно $originalPercent%, установлено $targetPercent%, изменение подтверждено, затем отменено; исходное состояние восстановлено и проверено.",
                silent,
                technical = evidence.toString()
            )
        } else {
            respondAndResume(
                text =
                    if (restoredVerified) {
                        "Полный тест яркости не подтверждён, но исходное состояние восстановлено."
                    } else {
                        "Полный тест яркости не подтверждён, и восстановление исходного состояния требует проверки пользователя."
                    },
                silent = silent,
                success = false,
                technical = evidence.toString()
            )
        }
    }

    private fun extractExactMediaVolumeRequest(
        command: String
    ): ExactMediaVolumeRequest? {
        val c =
            normalizeRussianSmallNumbersForRouting(
                command
                    .lowercase(Locale.ROOT)
                    .replace('ё', 'е')
                    .replace(Regex("\\s+"), " ")
                    .trim()
            )

        if (
            !c.contains("громк") &&
            !c.contains("звук")
        ) {
            return null
        }

        val directionalTargetIntent =
            (
                c.contains("уменьш") ||
                    c.contains("увелич")
                ) &&
                Regex("""(?:^|\s)до\s+\d{1,3}(?:\s|$)""")
                    .containsMatchIn(c)

        val readOnlyVolumeQuestion =
            c.contains("какая громк") ||
                c.contains("какой уровень громк") ||
                c.contains("сколько громк") ||
                c.contains("текущая громк") ||
                c.contains("текущий уровень громк") ||
                c.startsWith("уровень громкости")

        // R10.24.1: short spoken commands often arrive without an imperative verb:
        // «громкость девять из пятнадцати». The explicit X/Y ratio itself is an
        // absolute-target contract when the phrase is not a read-only question.
        val implicitScaledTarget =
            !readOnlyVolumeQuestion &&
                Regex("""(?:^|\s)\d{1,3}\s*(?:из|/)\s*\d{1,3}(?:\s|$)""")
                    .containsMatchIn(c)

        val setIntent =
            c.contains("установ") ||
                c.contains("постав") ||
                c.contains("выстав") ||
                c.contains("задай") ||
                c.contains("сделай громкость") ||
                directionalTargetIntent ||
                implicitScaledTarget

        if (!setIntent) {
            return null
        }

        Regex("""(\d{1,3})\s*(?:из|/)\s*(\d{1,3})""")
            .find(c)
            ?.let { match ->
                val level = match.groupValues[1].toIntOrNull() ?: return null
                val scale = match.groupValues[2].toIntOrNull() ?: return null
                return ExactMediaVolumeRequest(level, scale, false)
            }

        Regex("""(\d{1,3})\s*(?:%|процент(?:а|ов)?)""")
            .find(c)
            ?.let { match ->
                val level = match.groupValues[1].toIntOrNull() ?: return null
                return ExactMediaVolumeRequest(level, 100, true)
            }

        Regex("""(?:на|до)\s+(\d{1,3})(?:\s|$)""")
            .find(c)
            ?.let { match ->
                val level = match.groupValues[1].toIntOrNull() ?: return null
                return ExactMediaVolumeRequest(level, null, false)
            }

        return null
    }

    private fun runLocalExactMediaVolumeCommand(
        request: ExactMediaVolumeRequest,
        silent: Boolean
    ) {
        val result =
            setExactMediaVolume(request)

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state =
                if (result.optBoolean("success", false)) {
                    "volume_exact_verified"
                } else {
                    "volume_exact_failed"
                },
            message =
                if (result.optBoolean("success", false)) {
                    "Точный уровень громкости подтверждён"
                } else {
                    "Точный уровень громкости не подтверждён"
                },
            details =
                (
                    "requested=${request.requestedLevel}; " +
                        "scale=${request.requestedScaleMax ?: -1}; " +
                        "target=${result.optInt("target_level", -1)}; " +
                        "actual=${result.optInt("actual_level", -1)}; " +
                        "max=${result.optInt("device_max", -1)}"
                    ).take(500)
        )

        if (result.optBoolean("success", false)) {
            finishLocalCommand(
                result.optString("message"),
                silent
            )
        } else {
            respondAndResume(
                result.optString("message")
                    .ifBlank {
                        "Не удалось подтвердить точный уровень громкости."
                    },
                silent,
                success = false
            )
        }
    }

    private fun setExactMediaVolume(
        request: ExactMediaVolumeRequest
    ): JSONObject {
        val audioManager =
            getSystemService(Context.AUDIO_SERVICE) as AudioManager

        val maxVolume =
            audioManager.getStreamMaxVolume(AudioManager.STREAM_MUSIC)

        val minVolume =
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
                audioManager.getStreamMinVolume(AudioManager.STREAM_MUSIC)
            } else {
                0
            }

        if (maxVolume <= minVolume) {
            return toolResult(
                false,
                "Точный диапазон громкости мультимедиа сейчас недоступен."
            )
        }

        val beforeVolume =
            try {
                audioManager.getStreamVolume(
                    AudioManager.STREAM_MUSIC
                )
            } catch (_: Exception) {
                -1
            }

        val target =
            if (request.requestedScaleMax != null) {
                val scale = request.requestedScaleMax
                if (
                    scale <= 0 ||
                    request.requestedLevel < 0 ||
                    request.requestedLevel > scale
                ) {
                    return toolResult(
                        false,
                        "Некорректный уровень громкости: ${request.requestedLevel} из $scale."
                    )
                }

                (
                    (
                        request.requestedLevel.toLong() *
                            (maxVolume - minVolume).toLong() +
                            scale / 2L
                        ) /
                        scale.toLong()
                    ).toInt() + minVolume
            } else {
                if (
                    request.requestedLevel < minVolume ||
                    request.requestedLevel > maxVolume
                ) {
                    return toolResult(
                        false,
                        "Уровень ${request.requestedLevel} вне диапазона устройства $minVolume–$maxVolume."
                    )
                }
                request.requestedLevel
            }

        if (
            !executionKernel.tryBeginIrreversibleDispatch(
                kind = "media_volume_exact_set",
                detail = "target=$target; max=$maxVolume"
            )
        ) {
            return toolResult(
                false,
                "Установка громкости отменена до изменения состояния устройства."
            )
                .put("before_level", beforeVolume)
                .put("target_level", target)
                .put("actual_level", audioManager.getStreamVolume(AudioManager.STREAM_MUSIC))
                .put("device_min", minVolume)
                .put("device_max", maxVolume)
        }

        return try {
            audioManager.setStreamVolume(
                AudioManager.STREAM_MUSIC,
                target,
                AudioManager.FLAG_SHOW_UI
            )

            executionKernel.markIrreversibleDispatchAccepted(
                "media_volume_target=$target"
            )
            executionKernel.markSideEffectReconciliationStarted(
                "verify_media_volume_target=$target"
            )

            try {
                Thread.sleep(80L)
            } catch (_: Exception) {
            }

            val actual =
                audioManager.getStreamVolume(AudioManager.STREAM_MUSIC)

            val success =
                actual == target

            executionKernel.markSideEffectReconciled(
                committed = success,
                detail = "target=$target; actual=$actual"
            )

            if (
                success &&
                beforeVolume in minVolume..maxVolume &&
                beforeVolume != actual
            ) {
                recordVerifiedReversibleVolume(
                    beforeLevel = beforeVolume,
                    afterLevel = actual,
                    deviceMin = minVolume,
                    deviceMax = maxVolume,
                    source = "media_volume_exact_set"
                )
            }

            JSONObject()
                .put("success", success)
                .put("before_level", beforeVolume)
                .put("target_level", target)
                .put("actual_level", actual)
                .put("device_min", minVolume)
                .put("device_max", maxVolume)
                .put(
                    "message",
                    if (success) {
                        if (request.requestedScaleMax != null) {
                            val suffix =
                                if (request.percent) "%" else " из ${request.requestedScaleMax}"
                            "Громкость мультимедиа установлена: ${request.requestedLevel}$suffix. На устройстве: $actual из $maxVolume."
                        } else {
                            "Громкость мультимедиа установлена: $actual из $maxVolume."
                        }
                    } else {
                        "Android принял установку громкости, но проверка дала $actual из $maxVolume вместо $target. SUCCESS не выставлен."
                    }
                )
        } catch (error: Exception) {
            val actual =
                try {
                    audioManager.getStreamVolume(AudioManager.STREAM_MUSIC)
                } catch (_: Exception) {
                    -1
                }

            // Even if Android threw during dispatch, factual post-read owns truth.
            executionKernel.markIrreversibleDispatchAccepted(
                "media_volume_dispatch_exception"
            )
            executionKernel.markSideEffectReconciliationStarted(
                "verify_after_media_volume_exception"
            )
            executionKernel.markSideEffectReconciled(
                committed = actual == target,
                detail = "target=$target; actual=$actual; error=${error.javaClass.simpleName}"
            )

            if (
                actual == target &&
                beforeVolume in minVolume..maxVolume &&
                beforeVolume != actual
            ) {
                recordVerifiedReversibleVolume(
                    beforeLevel = beforeVolume,
                    afterLevel = actual,
                    deviceMin = minVolume,
                    deviceMax = maxVolume,
                    source = "media_volume_exact_set_exception_reconciled"
                )
            }

            JSONObject()
                .put("success", actual == target)
                .put("before_level", beforeVolume)
                .put("target_level", target)
                .put("actual_level", actual)
                .put("device_min", minVolume)
                .put("device_max", maxVolume)
                .put(
                    "message",
                    if (actual == target) {
                        "Громкость мультимедиа установлена и подтверждена после системного исключения: $actual из $maxVolume."
                    } else {
                        "Не удалось установить точную громкость: ${error.message ?: error.javaClass.simpleName}"
                    }
                )
        }
    }

    private fun isVolumeUpCommand(
        command: String
    ): Boolean {

        return command == "громче" ||
            command.contains("погромч") ||
            (
                command.contains("прибав") &&
                    (
                        command.contains("громк") ||
                            command.contains("звук")
                        )
                ) ||
            (
                command.contains("увелич") &&
                    (
                        command.contains("громк") ||
                            command.contains("звук")
                        )
                ) ||
            (
                command.contains("сделай") &&
                    command.contains("громч")
                )
    }

    private fun isVolumeDownCommand(
        command: String
    ): Boolean {

        return command == "тише" ||
            command.contains("потише") ||
            (
                command.contains("убав") &&
                    (
                        command.contains("громк") ||
                            command.contains("звук")
                        )
                ) ||
            (
                command.contains("уменьш") &&
                    (
                        command.contains("громк") ||
                            command.contains("звук")
                        )
                ) ||
            (
                command.contains("сделай") &&
                    command.contains("тиш")
                )
    }

    private fun isMuteCommand(
        command: String
    ): Boolean {

        return command == "без звука" ||
            (
                command.contains("выключ") &&
                    command.contains("звук")
                ) ||
            command.contains("убери звук")
    }

    private fun isUnmuteCommand(
        command: String
    ): Boolean {

        return (
            command.contains("включ") &&
                command.contains("звук")
            ) ||
            command.contains("верни звук")
    }

    private fun tryOpenPhoneticInstalledApp(
        target: String,
        wholeCommand: String,
        silent: Boolean
    ): Boolean {

        val explicitLaunch =
            isAppLaunchCommand(
                wholeCommand
            )

        val candidates =
            localAppPhoneticRouter
                .rank(
                    query = target,
                    aliases = KNOWN_LOCAL_LAUNCH_ALIASES,
                    explicitLaunch = explicitLaunch
                )

        if (candidates.isEmpty()) {
            return false
        }

        val selection =
            localAppPhoneticRouter
                .selectResolved(
                    candidates = candidates,
                    resolver = { alias ->
                        val resolution =
                            try {
                                appResolver.resolve(
                                    alias
                                )
                            } catch (_: Exception) {
                                null
                            }

                        if (
                            resolution == null ||
                            !resolution.success ||
                            resolution.packageName.isBlank()
                        ) {
                            null
                        } else {
                            AyanaLocalAppPhoneticRouter.ResolvedTarget(
                                packageName = resolution.packageName,
                                label = resolution.label
                            )
                        }
                    }
                )

        if (selection.ambiguous) {
            val runnerUp =
                selection.runnerUp

            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "local_app_phonetic_ambiguous",
                message = "Фонетическое имя приложения неоднозначно",
                details =
                    (
                        "target=${target.take(100)}; " +
                            "runner_up=${runnerUp?.alias.orEmpty()}:" +
                            "${runnerUp?.packageName.orEmpty()}:" +
                            "${runnerUp?.score ?: 0}"
                        ).take(500)
            )
            return false
        }

        val best =
            selection.selected
                ?: return false

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "local_app_phonetic_match",
            message = "Короткая команда приложения распознана локально",
            details =
                (
                    "target=${target.take(100)}; alias=${best.alias}; " +
                        "label=${best.label.take(100)}; package=${best.packageName}; " +
                        "score=${best.score}; literal=${best.literalScore}; " +
                        "phonetic=${best.phoneticScore}; explicit_launch=$explicitLaunch"
                    ).take(700)
        )

        openInstalledAppByName(
            requestedName = best.alias,
            silent = silent
        )

        return true
    }

    private fun openInstalledAppByName(
        requestedName: String,
        silent: Boolean
    ) {

        val query =
            normalizeAppName(
                requestedName
            )

        if (
            query.isBlank()
        ) {
            respondAndResume(
                "Не поняла, какое приложение открыть.",
                silent,
                success = false
            )
            return
        }

        val result =
            appResolver
                .launch(
                    requestedName
                )

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state =
                if (
                    result.optBoolean(
                        "success",
                        false
                    )
                ) {
                    "app_resolved"
                } else {
                    "app_resolver_miss"
                },
            message =
                result.optString(
                    "message",
                    "App Resolver v2"
                ),
            details =
                "package=${result.optString("package")}; " +
                    "confidence=${result.optInt("confidence", 0)}; " +
                    "source=${result.optString("source")}; " +
"reason=${result.optString("reason")}".take(520)
        )

        if (
            result.optBoolean(
                "success",
                false
            )
        ) {
            finishLocalCommand(
                result.optString(
                    "message",
                    "Открываю ${result.optString("label", requestedName)}"
                ),
                silent
            )
        } else {
            respondAndResume(
                result.optString(
                    "message",
                    "Приложение $requestedName не найдено."
                ),
                silent,
                success = false
            )
        }
    }

    private fun knownAppForQuery(
        query: String
    ): Pair<String, List<String>>? {

        return when {

            query in setOf(
                "youtube",
                "ютуб"
            ) ->
                "YouTube" to
                    listOf(
                        "com.google.android.youtube"
                    )

            query in setOf(
                "переводчик",
                "переводчика",
                "гугл переводчик",
                "google переводчик",
                "google translate",
                "translate"
            ) ->
                "переводчик" to
                    listOf(
                        "com.google.android.apps.translate"
                    )

            query in setOf(
                "галерея",
                "галерею",
                "фото",
                "фотографии"
            ) ->
                "галерею" to
                    listOf(
                        "com.sec.android.gallery3d",
                        "com.google.android.apps.photos"
                    )

            query in setOf(
                "камера",
                "камеру"
            ) ->
                "камеру" to
                    listOf(
                        "com.sec.android.app.camera"
                    )

            query in setOf(
                "калькулятор",
                "калькулятора"
            ) ->
                "калькулятор" to
                    listOf(
                        "com.sec.android.app.popupcalculator"
                    )

            query in setOf(
                "файлы",
                "мои файлы"
            ) ->
                "Мои файлы" to
                    listOf(
                        "com.sec.android.app.myfiles"
                    )

            query in setOf(
                "telegram",
                "телеграм",
                "телеграмм"
            ) ->
                "Telegram" to
                    listOf(
                        "org.telegram.messenger"
                    )

            query in setOf(
                "whatsapp",
                "ватсап",
                "вотсап"
            ) ->
                "WhatsApp" to
                    listOf(
                        "com.whatsapp"
                    )

            else ->
                null
        }
    }

    private fun normalizeAppName(
        value: String
    ): String {

        return normalizeRecognitionText(
            value
        )
            .removePrefix(
                "приложение "
            )
            .removePrefix(
                "программу "
            )
            .removePrefix(
                "программа "
            )
            .trim()
    }

    private fun appNameScore(
        query: String,
        label: String
    ): Int {

        val q =
            normalizeAppName(
                query
            )

        val l =
            normalizeAppName(
                label
            )

        if (
            q.isBlank() ||
            l.isBlank()
        ) {
            return 0
        }

        if (q == l) {
            return 100
        }

        if (
            l.contains(q) ||
            q.contains(l)
        ) {
            return 92
        }

        val qTokens =
            q.split(" ")
                .filter {
                    it.isNotBlank()
                }

        val lTokens =
            l.split(" ")
                .filter {
                    it.isNotBlank()
                }

        if (
            qTokens.isEmpty() ||
            lTokens.isEmpty()
        ) {
            return 0
        }

        val qStems =
            qTokens.map {
                appStem(it)
            }

        val lStems =
            lTokens.map {
                appStem(it)
            }

        val matched =
            qStems.count { qStem ->

                lStems.any { lStem ->

                    qStem.length >= 3 &&
                        lStem.length >= 3 &&
                        (
                            qStem == lStem ||
                                qStem.startsWith(
                                    lStem
                                ) ||
                                lStem.startsWith(
                                    qStem
                                )
                            )
                }
            }

        if (matched == 0) {
            return 0
        }

        return 70 +
            (
                25 *
                    matched /
                    qStems.size
                )
    }

    private fun appStem(
        value: String
    ): String {

        var result =
            value
                .lowercase(
                    Locale.getDefault()
                )
                .replace('ё', 'е')
                .replace(
                    Regex("[^a-zа-я0-9]"),
                    ""
                )

        if (result.length <= 4) {
            return result
        }

        val endings =
            listOf(
                "иями",
                "ями",
                "ами",
                "ого",
                "его",
                "ому",
                "ему",
                "ыми",
                "ими",
                "ую",
                "юю",
                "ая",
                "яя",
                "ое",
                "ее",
                "ой",
                "ей",
                "ом",
                "ем",
                "ах",
                "ях",
                "ам",
                "ям",
                "ов",
                "ев",
                "ы",
                "и",
                "а",
                "я",
                "у",
                "ю",
                "е",
                "о"
            )

        for (ending in endings) {

            if (
                result.endsWith(
                    ending
                ) &&
                result.length -
                    ending.length >= 3
            ) {

                result =
                    result.dropLast(
                        ending.length
                    )

                break
            }
        }

        return result
    }

    private fun extractYouTubeQuery(
        command: String
    ): String {

        val markers =
            listOf(
                "поищи ",
                "найди ",
                "ищи ",
                "поиск "
            )

        for (
            marker in markers
        ) {

            val index =
                command.indexOf(
                    marker
                )

            if (index >= 0) {

                var query =
                    command
                        .substring(
                            index +
                                marker.length
                        )
                        .trim()

                query =
                    query
                        .removePrefix(
                            "мне "
                        )
                        .removePrefix(
                            "в ютубе "
                        )
                        .removePrefix(
                            "на ютубе "
                        )
                        .removePrefix(
                            "youtube "
                        )
                        .removePrefix(
                            "ютуб "
                        )
                        .removePrefix(
                            "музыку "
                        )
                        .removePrefix(
                            "музыка "
                        )
                        .trim()

                return query
            }
        }

        return ""
    }

    private fun executeLocalScrollToBoundary(
        direction: String,
        silent: Boolean
    ) {

        val commandToken =
            activeCommandToken

        executionPhase(
            phase = "local_scroll_boundary",
            executor = "screen_intelligence"
        )

        broadcastStatus(
            "Прокручиваю экран до границы…",
            STATE_EXECUTING
        )
if (!silent) {
            startCancelListening()
        } else {
            stopCancelListenerWatchdog()
            stopSherpaListening()
        }

        val worker =
            thread(
                start = false,
                name = "AyanaLocalScrollBoundary"
            ) {

                try {
                    val result =
                        try {
                            screenIntelligence
                                .scrollToBoundary(
                                    direction = direction,
                                    maxSteps = 6,
                                    shouldCancel = {
                                        cancelRequested ||
                                            executionKernel.isCancelled() ||
                                            shuttingDown ||
                                            commandToken != activeCommandToken
                                    }
                                )
                        } catch (error: Exception) {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                                .put("action_accepted", false)
                                .put("terminal_status", "ERROR")
                                .put("status", "local_scroll_boundary_exception")
                                .put(
                                    "reason",
                                    error.message
                                        ?: "local_scroll_boundary_exception"
                                )
                                .put(
                                    "message",
                                    "Локальная прокрутка до границы завершилась ошибкой"
                                )
                        }

                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state = "local_scroll_boundary",
                        message = result.optString(
                            "status",
                            "scroll_boundary_unknown"
                        ),
                        details = result.toString().take(1800)
                    )

                    if (
                        result.optString(
                            "terminal_status"
                        ) == "CANCELLED" ||
                        isCommandCancelled(
                            commandToken
                        ) ||
                        shuttingDown
                    ) {
                        return@thread
                    }

                    mainHandler.post {
                        if (
                            shuttingDown ||
                            commandToken != activeCommandToken ||
                            isCommandCancelled(
                                commandToken
                            )
                        ) {
                            return@post
                        }

                        val message =
                            result
                                .optString(
                                    "message"
                                )
                                .trim()
                                .ifBlank {
                                    "Прокрутка до границы не подтверждена"
                                }

                        when (
                            result
                                .optString(
                                    "terminal_status",
                                    "ERROR"
                                )
                                .uppercase(
                                    Locale.ROOT
                                )
                        ) {
                            "SUCCESS" ->
                                finishLocalCommand(
                                    "Экран прокручен до подтверждённой границы.",
                                    silent
                                )

                            "BLOCKED" ->
                                respondBlockedAndResume(
                                    text = message,
                                    silent = silent,
                                    technical =
                                        "local_scroll_boundary:" +
                                            result.optString("reason")
                                )

                            "UNSUPPORTED" ->
                                respondUnsupportedAndResume(
                                    text = message,
                                    silent = silent,
                                    technical =
                                        "local_scroll_boundary:" +
                                            result.optString("reason")
                                )

                            else ->
respondAndResume(
                                    text = message,
                                    silent = silent,
                                    success = false,
                                    technical =
                                        "local_scroll_boundary:" +
                                            result.optString("reason")
                                )
                        }
                    }
                } finally {
                    if (
                        Thread.currentThread() ===
                        currentAgentThread
                    ) {
                        currentAgentThread =
                            null
                    }
                }
            }

        currentAgentThread =
            worker

        executionKernel.bindThread(
            worker
        )

        worker.start()
    }

    private fun clickByText(
        target: String,
        silent: Boolean
    ) {

        if (target.isBlank()) {

            respondAndResume(
                "Скажите, что именно нажать.",
                silent,
                success = false
            )

            return
        }

        // Local voice shortcuts ("нажми …" / "выбери …") must pass the
        // same fail-closed Safety Engine as Agent Core tool calls. Otherwise a
        // direct shortcut could bypass the policy layer entirely.
        val safetyDecision =
            try {
                safetyPolicy.evaluateTool(
                    "click_text",
                    JSONObject()
                        .put(
                            "text",
                            target
                        )
                )
            } catch (error: Exception) {
                AyanaSafetyPolicy.Decision(
                    allowed = false,
                    requiresConfirmation = false,
                    riskLevel = AyanaSafetyPolicy.RISK_PROHIBITED,
                    riskName = "policy_error",
                    reason = error.message
                        ?: "Ошибка локальной политики безопасности"
                )
            }

        if (!safetyDecision.allowed) {
            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "safety_gate",
                message = safetyDecision.riskName,
                details = safetyDecision.reason.take(260)
            )

            respondBlockedAndResume(
                text =
                    safetyDecision.reason
                        .ifBlank {
                            "Действие остановлено локальным Safety Engine AYANA."
                        },
                silent = silent,
                technical =
                    "local_click_safety_blocked:" +
                        safetyDecision.riskName
            )

            return
        }

        // v12.8: local voice click no longer bypasses Screen Intelligence.
        // The universal semantic resolver owns identity/ambiguity before Android
        // receives input; low-level Accessibility remains the physical executor.
        val result =
            universalUiActionEngine.click(
                target = target,
                confirmed = false
            )

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "semantic_action",
            message = result.optString("reason", "click_text"),
            details =
                "requested=${target.take(140)}; " +
                    "resolved=${result.optString("resolved_target").take(140)}; " +
                    "accepted=${result.optBoolean("action_accepted", false)}; " +
                    "verified=${result.optBoolean("verified", false)}; " +
                    "terminal=${result.optString("terminal_status").take(32)}"
        )

        result.optJSONObject("screen")?.let { screen ->
            capabilityRegistry.recordScreenObservation(screen)
        }

        if (result.optBoolean("success", false)) {

            finishLocalCommand(
                "Нажимаю: $target",
                silent
            )

        } else {

            respondAndResume(
                result.optString("message")
                    .ifBlank {
                        "Я не смогла надёжно подтвердить элемент $target."
                    },
                silent,
                success = false,
                terminalStatus =
                    when (result.optString("terminal_status")) {
                        "BLOCKED" -> AyanaCommandHistoryStore.STATUS_BLOCKED
                        "UNSUPPORTED" -> AyanaCommandHistoryStore.STATUS_UNSUPPORTED
                        else -> null
                    }
            )
        }
    }

    private fun changeVolume(
        direction: Int
    ) {

        val audioManager =
            getSystemService(
                Context.AUDIO_SERVICE
            ) as AudioManager

        audioManager.adjustStreamVolume(
            AudioManager.STREAM_MUSIC,
            direction,
            AudioManager.FLAG_SHOW_UI
        )
    }

    /**
     * v11.1 APP RESOLVER INTEGRATION.
     *
     * Legacy fast local routes still provide their historical package list, but
     * it is no longer trusted as a launch target. AyanaAppResolver validates every
     * hint against the actual launcher map and launches the observed component.
     * This keeps the v10.x fast path while making App Resolver the single source
     * of truth for direct app launches as well as Agent/Goal Engine launches.
     */
    private fun openApp(
        displayName: String,
        silent: Boolean,
        vararg packages: String
    ) {

        val result =
            appResolver
                .launchWithHints(
                    requestedName = displayName,
                    preferredPackages = packages.toList()
                )

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state =
                if (
                    result.optBoolean(
                        "success",
                        false
                    )
                ) {
                    "app_resolved"
                } else {
                    "app_resolver_miss"
                },
            message =
                result.optString(
                    "message",
                    "App Resolver v2.1"
                ),
            details =
                "package=${result.optString("package")}; " +
                    "confidence=${result.optInt("confidence", 0)}; " +
                    "source=${result.optString("source")}; " +
                    "reason=${result.optString("reason")}".take(620)
        )

        if (
            result.optBoolean(
                "success",
                false
            )
        ) {
            finishLocalCommand(
                result.optString(
                    "message",
                    "Открываю $displayName"
                ),
                silent
            )
        } else {
            respondAndResume(
                result.optString(
                    "message",
                    "Приложение $displayName не найдено."
                ),
                silent,
                success = false
            )
        }
    }

    private fun openSystemScreen(
        action: String,
        displayName: String,
        silent: Boolean
    ) {

        try {

            startActivity(
                Intent(action).apply {

                    addFlags(
                        Intent.FLAG_ACTIVITY_NEW_TASK
                    )
                }
            )

            finishLocalCommand(
                "Открываю $displayName",
                silent
            )

        } catch (
            _: ActivityNotFoundException
        ) {

            respondAndResume(
                "Не удалось открыть $displayName.",
                silent,
                success = false
            )
        }
    }

    private fun isAppIntegrationDeviceAcceptanceCommand(
        value: String
    ): Boolean {
        val normalized =
            value
                .trim()
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")

        return normalized in
            setOf(
                "проверь интеграции приложений",
                "проверь интеграции приложений ayana",
                "протестируй интеграции приложений",
                "протестируй интеграции приложений ayana",
                "проверь app integration",
                "протестируй app integration",
                "проверь работу ayana с приложениями",
                "протестируй работу ayana с приложениями"
            )
    }

    private fun runLocalAppIntegrationDeviceAcceptance(
        silent: Boolean
    ) {
        executionPhase(
            phase = "app_integration_device_acceptance",
            executor = "app_integration_device_probe"
        )

        val commandToken =
            activeCommandToken

        val originalPage =
            currentAyanaPageKeyForAppIntegrationProbe()

        val worker =
            thread(
                start = false,
                name = "AyanaAppIntegrationDeviceProbe"
            ) {
                try {
                    val report =
                        appIntegrationDeviceProbe.run(
                            execute = { step ->
                                if (
                                    isCommandCancelled(commandToken) ||
                                    commandToken != activeCommandToken
                                ) {
                                    JSONObject()
                                        .put("success", false)
                                        .put("verified", false)
                                        .put("terminal_status", "CANCELLED")
                                        .put("message", "Команда отменена до следующего app-action.")
                                } else {
                                    commandHistoryStore.addEvent(
                                        activeCommandHistoryId,
                                        state = "app_integration_device_probe_step",
                                        message = "Проверка ${step.key}",
                                        details =
                                            "app=${step.appKey}; action=${step.actionKey}; phase=dispatch"
                                    )

                                    val stepResult =
                                        executeAppIntegrationAction(
                                            appKey = step.appKey,
                                            actionKey = step.actionKey,
                                            payload = step.payload
                                        )

                                    commandHistoryStore.addEvent(
                                        activeCommandHistoryId,
                                        state = "app_integration_device_probe_step_result",
                                        message =
                                            "${step.key}: ${
                                                if (
                                                    stepResult.optBoolean("success", false) &&
                                                    stepResult.optBoolean("verified", false)
                                                ) {
                                                    "PASS"
                                                } else {
                                                    "FAIL"
                                                }
                                            }",
                                        details =
                                            stepResult
                                                .toString()
                                                .take(2200)
                                    )

                                    stepResult
                                }
                            },
                            restore = { step ->
                                restoreAyanaAfterAppIntegrationProbe(
                                    pageKey = originalPage,
                                    stepKey = step.key
                                )
                            },
                            shouldCancel = {
                                isCommandCancelled(commandToken) ||
                                    commandToken != activeCommandToken ||
                                    Thread.currentThread().isInterrupted
                            }
                        )

                    if (
                        report.optBoolean(
                            "cancelled",
                            false
                        ) ||
                        isCommandCancelled(commandToken) ||
                        commandToken != activeCommandToken
                    ) {
                        return@thread
                    }

                    val success =
                        report.optBoolean(
                            "success",
                            false
                        ) &&
                            report.optBoolean(
                                "verified",
                                false
                            )

                    val resultText =
                        renderAppIntegrationDeviceProbeSummary(
                            report
                        )

                    val technical =
                        buildString {
                            append("app_integration_device_probe=")
                            append(AyanaAppIntegrationDeviceProbe.VERSION)
                            append("; passed=")
                            append(report.optInt("passed", 0))
                            append("/")
                            append(report.optInt("steps_total", 0))
                            append("; failed=")
                            append(report.optInt("failed", 0))
                            append("; duration_ms=")
                            append(report.optLong("duration_ms", 0L))
                            append("; mutation_committed_detected=")
                            append(
                                report.optBoolean(
                                    "mutation_committed_detected",
                                    false
                                )
                            )
                            append("; report=")
                            append(
                                report
                                    .toString()
                                    .take(3600)
                            )
                        }

                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state = "app_integration_device_probe_complete",
                        message =
                            if (success) {
                                "Пять app-integration device checks подтверждены"
                            } else {
                                "App-integration device acceptance обнаружил отклонения"
                            },
                        details = technical.take(4200)
                    )

                    mainHandler.post {
                        if (
                            isCommandCancelled(commandToken) ||
                            commandToken != activeCommandToken
                        ) {
                            return@post
                        }

                        respondAndResume(
                            text = resultText,
                            silent = silent,
                            success = success,
                            technical = technical
                        )
                    }
                } finally {
                    if (
                        Thread.currentThread() ===
                        currentAgentThread
                    ) {
                        currentAgentThread =
                            null
                    }
                }
            }

        currentAgentThread =
            worker

        executionKernel
            .bindThread(
                worker
            )

        worker.start()
    }

    private fun currentAyanaPageKeyForAppIntegrationProbe(): String =
        try {
            getSharedPreferences(
                MainActivity.UI_STATE_PREFS,
                Context.MODE_PRIVATE
            )
                .getString(
                    MainActivity.UI_STATE_CURRENT_PAGE,
                    ""
                )
                .orEmpty()
.trim()
        } catch (_: Exception) {
            ""
        }

    private fun restoreAyanaAfterAppIntegrationProbe(
        pageKey: String,
        stepKey: String
    ): JSONObject {
        var dispatched =
            false

        var dispatchError =
            ""

        try {
            startActivity(
                Intent(
                    this,
                    MainActivity::class.java
                ).apply {
                    if (
                        pageKey.isNotBlank()
                    ) {
                        putExtra(
                            MainActivity.EXTRA_OPEN_PAGE,
                            pageKey
                        )
                    }

                    addFlags(
                        Intent.FLAG_ACTIVITY_NEW_TASK or
                            Intent.FLAG_ACTIVITY_CLEAR_TOP or
                            Intent.FLAG_ACTIVITY_SINGLE_TOP
                    )
                }
            )

            dispatched =
                true
        } catch (error: Exception) {
            dispatchError =
                error.message
                    ?: error.javaClass.simpleName
        }

        val observed =
            if (dispatched) {
                waitForForegroundPackage(
                    expectedPackage = packageName,
                    timeoutMs = APP_INTEGRATION_PROBE_RESTORE_TIMEOUT_MS
                )
            } else {
                currentForegroundPackage()
            }

        val verified =
            dispatched &&
                observed ==
                packageName

        return JSONObject()
            .put("success", verified)
            .put("verified", verified)
            .put(
                "terminal_status",
                if (verified) {
                    "SUCCESS"
                } else {
                    "ERROR"
                }
            )
            .put("step_key", stepKey)
            .put("action_dispatched", dispatched)
            .put("target_package", packageName)
            .put("observed_package", observed)
            .put("requested_page", pageKey)
            .put(
                "dispatch_error",
                dispatchError.take(400)
            )
    }

    private fun isSemanticVisualAcceptanceProbe(
        step: AyanaMultiAppTaskOrchestrator.TaskStep
    ): Boolean {
        val captureSpec =
            step.captureSpec
                ?: return false

        return step.key == "browser-visual-semantic-marker" &&
            step.appKey == "browser" &&
            step.actionKey == AyanaAppIntegrationRegistry.ACTION_OPEN_URL &&
            step.payload == AyanaMultiAppTaskOrchestrator.SEMANTIC_FALLBACK_ACCEPTANCE_URL &&
            captureSpec.kind ==
                AyanaVerifiedResultTransfer.CaptureKind.SCREEN_MARKER &&
            captureSpec.marker ==
                AyanaMultiAppTaskOrchestrator.SEMANTIC_FALLBACK_ACCEPTANCE_MARKER
    }

    private fun attemptVerifiedSemanticScreenMarkerFallback(
        step: AyanaMultiAppTaskOrchestrator.TaskStep,
        actionResult: JSONObject,
        expectedPackage: String,
        commandToken: Long
    ): JSONObject {
        val captureSpec =
            step.captureSpec
                ?: return JSONObject()
                    .put("success", false)
                    .put("verified", false)
                    .put("reason", "semantic_fallback_capture_spec_missing")

        if (
            captureSpec.kind !=
            AyanaVerifiedResultTransfer.CaptureKind.SCREEN_MARKER
        ) {
            return JSONObject()
                .put("success", false)
                .put("verified", false)
                .put("reason", "semantic_fallback_kind_not_supported")
                .put("semantic_visual_fallback_attempted", false)
        }

        val marker =
            captureSpec.marker.trim()

        if (marker.isBlank()) {
            return JSONObject()
                .put("success", false)
                .put("verified", false)
                .put("reason", "semantic_fallback_marker_missing")
        }

        val forcedAcceptanceProbe =
            isSemanticVisualAcceptanceProbe(step)

        if (
            !actionResult.optBoolean("success", false) ||
            !actionResult.optBoolean("verified", false) ||
            expectedPackage.isBlank() ||
            expectedPackage == packageName
        ) {
            return JSONObject()
                .put("success", false)
                .put("verified", false)
                .put("reason", "semantic_fallback_source_not_verified_external_app")
        }

        if (
            isCommandCancelled(commandToken) ||
            commandToken != activeCommandToken ||
            Thread.currentThread().isInterrupted ||
            shuttingDown
        ) {
            return JSONObject()
                .put("success", false)
                .put("verified", false)
                .put("reason", "semantic_fallback_cancelled")
                .put("semantic_visual_fallback_attempted", false)
        }

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "semantic_visual_fallback_started",
            message =
                if (forcedAcceptanceProbe) {
                    "R9.6.1 acceptance: Accessibility sample получен; принудительно проверяю package-bound screenshot"
                } else {
                    "R9.6: Accessibility не дал exact-marker; проверяю package-bound screenshot"
                },
            details =
                "step=${step.key}; package=$expectedPackage; marker=${marker.take(180)}; " +
                    "forced_acceptance_probe=$forcedAcceptanceProbe"
        )

        val screenshot =
            try {
                visualScreenEvidence.captureVerifiedExternalWindow(
                    expectedPackage = expectedPackage
                )
            } catch (error: Exception) {
                JSONObject()
                    .put("success", false)
                    .put("verified", false)
                    .put("reason", "semantic_fallback_screenshot_exception")
                    .put(
                        "detail",
                        (error.message ?: error.javaClass.simpleName).take(240)
                    )
            }

        if (
            !screenshot.optBoolean("success", false) ||
            !screenshot.optBoolean("verified", false)
        ) {
            val result =
                JSONObject(screenshot.toString())
                    .put("success", false)
                    .put("verified", false)
                    .put("semantic_visual_fallback_attempted", true)
                    .put("semantic_visual_fallback_stage", "screenshot")

            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "semantic_visual_fallback_failed",
                message = "R9.6 screenshot evidence не подтверждено",
                details =
                    "step=${step.key}; reason=${result.optString("reason").take(180)}; " +
                        "capture_mode=${result.optString("capture_mode")}; " +
                        "screenshot_error=${result.optString("screenshot_error")}"
            )

            return result
        }

        try {
            if (
                isCommandCancelled(commandToken) ||
                commandToken != activeCommandToken ||
                Thread.currentThread().isInterrupted ||
                shuttingDown
            ) {
                return JSONObject()
                    .put("success", false)
                    .put("verified", false)
                    .put("reason", "semantic_fallback_cancelled_after_screenshot")
                    .put("semantic_visual_fallback_attempted", true)
            }

            val manifest =
                JSONObject()
                    .put(
                        "kind",
                        AyanaMultimodalAttachmentManager.KIND_IMAGE
                    )
                    .put(
                        "display_name",
                        "ayana_verified_screen_fallback.jpg"
                    )
                    .put("mime_type", "image/jpeg")
                    .put("path", screenshot.optString("path"))

            val model =
                try {
                    callMultimodalCore(
                        prompt =
                            verifiedSemanticObservation
                                .promptForExactMarker(marker),
                        manifest = manifest
                    )
                } catch (error: Exception) {
                    JSONObject()
                        .put("success", false)
                        .put("reply", "")
                        .put(
                            "technical",
                            "semantic_fallback_multimodal_exception=" +
                                (error.message ?: error.javaClass.simpleName).take(240)
                        )
                }

            if (
                isCommandCancelled(commandToken) ||
                commandToken != activeCommandToken ||
                Thread.currentThread().isInterrupted ||
                shuttingDown
            ) {
                return JSONObject()
                    .put("success", false)
                    .put("verified", false)
                    .put("reason", "semantic_fallback_cancelled_after_model")
                    .put("semantic_visual_fallback_attempted", true)
            }

            if (!model.optBoolean("success", false)) {
                val result =
                    JSONObject()
                        .put("success", false)
                        .put("verified", false)
                        .put("reason", "semantic_fallback_multimodal_failed")
                        .put("semantic_visual_fallback_attempted", true)
                        .put("semantic_visual_fallback_stage", "multimodal")
                        .put(
                            "semantic_model_technical",
                            model.optString("technical").take(500)
                        )

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "semantic_visual_fallback_failed",
                    message = "R9.6 multimodal marker verification не выполнена",
                    details = result.toString().take(1200)
                )

                return result
            }

            val verified =
                verifiedSemanticObservation.verifyExactMarker(
                    expectedPackage = expectedPackage,
                    marker = marker,
                    screenshotEvidence = screenshot,
                    modelReply = model.optString("reply")
                )
                    .put("semantic_visual_fallback_attempted", true)
                    .put("semantic_visual_fallback_stage", "verified_semantic_observation")
                    .put(
                        "semantic_model_technical",
                        model.optString("technical").take(500)
                    )

            if (verified.optBoolean("verified", false)) {
                val unifiedVisual =
                    JSONObject(verified.toString())
                        .put("expected_package", expectedPackage)
                        .put("captured_package", screenshot.optString("captured_package", expectedPackage))
                        .put("screenshot_sha256", screenshot.optString("screenshot_sha256"))
                        .put("capture_mode", screenshot.optString("capture_mode"))
                        .put(
                            "source_context_mode",
                            verified.optString("source_context_mode")
                                .ifBlank { "r9_6_visual_screenshot_fallback" }
                        )
                screenIntelligence.recordVerifiedVisualObservation(unifiedVisual)
            }

            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state =
                    if (verified.optBoolean("verified", false)) {
                        "semantic_visual_fallback_verified"
                    } else {
                        "semantic_visual_fallback_failed"
                    },
                message =
                    if (verified.optBoolean("verified", false)) {
                        "R9.6 exact-marker подтверждён visual fallback"
                    } else {
                        "R9.6 visual fallback не подтвердил exact-marker"
                    },
                details =
                    "step=${step.key}; package=$expectedPackage; marker=${marker.take(180)}; " +
                        "reason=${verified.optString("reason")}; capture_mode=${screenshot.optString("capture_mode")}; " +
                        "sha=${screenshot.optString("screenshot_sha256").take(16)}..."
            )

            return verified
        } finally {
            visualScreenEvidence.deleteEvidenceFile(screenshot)
        }
    }

    private fun observeVerifiedResultTransferScreen(
        step: AyanaMultiAppTaskOrchestrator.TaskStep,
        actionResult: JSONObject,
        commandToken: Long
    ): JSONObject {
        val expectedPackage =
            actionResult
                .optString("observed_package")
                .trim()
                .ifBlank {
                    actionResult
                        .optString("target_package")
                        .trim()
                }

        if (
            !actionResult.optBoolean("success", false) ||
            !actionResult.optBoolean("verified", false) ||
            expectedPackage.isBlank()
        ) {
            return JSONObject()
                .put("success", false)
                .put("verified", false)
                .put("reason", "source_action_not_verified_for_observation")
                .put("expected_package", expectedPackage)
        }

        val forceVisualAcceptanceProbe =
            isSemanticVisualAcceptanceProbe(step)

        val startedAt =
            SystemClock.elapsedRealtime()

        val deadline =
            startedAt +
                RESULT_TRANSFER_OBSERVATION_TIMEOUT_MS
var attempts = 0
        var forcedVisualProbeAfterAccessibilitySample = false
        var bestRank = Int.MIN_VALUE
        var best =
            JSONObject()
                .put("success", false)
                .put("verified", false)
                .put("reason", "no_screen_sample")

        do {
            if (
                isCommandCancelled(commandToken) ||
                commandToken != activeCommandToken ||
                Thread.currentThread().isInterrupted
            ) {
                return JSONObject(best.toString())
                    .put("success", false)
                    .put("verified", false)
                    .put("transfer_observation_cancelled", true)
                    .put("transfer_observation_attempts", attempts)
                    .put("expected_package", expectedPackage)
            }

            val screen =
                try {
                    screenIntelligence.getScreenState()
                } catch (error: Exception) {
                    JSONObject()
                        .put("success", false)
                        .put(
                            "reason",
                            error.message ?: error.javaClass.simpleName
                        )
                }

            attempts++

            val observedPackage =
                screen
                    .optString("effective_foreground_package")
                    .trim()
                    .ifBlank {
                        screen
                            .optString("package")
                            .trim()
                    }
                    .ifBlank {
                        screen
                            .optString("interaction_package")
                            .trim()
                    }

            val contentState =
                screen
                    .optString("primary_content_state")
                    .trim()
                    .lowercase(Locale.ROOT)
                    .ifBlank {
                        screen
                            .optString("content_state")
                            .trim()
                            .lowercase(Locale.ROOT)
                    }
                    .ifBlank {
                        screen
                            .optString("content_status")
                            .trim()
                            .lowercase(Locale.ROOT)
                    }
                    .ifBlank { "unknown" }

            val packageMatch =
                observedPackage ==
                    expectedPackage

            val stateRank =
                when (contentState) {
                    "readable" -> 40
                    "partial" -> 30
                    "structure_only" -> 20
                    "unavailable" -> 10
                    else -> 0
                }

            val textEvidence =
                screen
                    .optString("verification_text")
                    .isNotBlank() ||
                    screen
                        .optString("primary_window_title")
                        .isNotBlank() ||
                    (
                        screen
                            .optJSONArray("visible_text")
                            ?.length()
                            ?: 0
                        ) > 0

            val rank =
                (if (screen.optBoolean("success", false)) 10 else 0) +
                    (if (packageMatch) 100 else 0) +
                    stateRank +
                    (if (textEvidence) 5 else 0)

            if (rank > bestRank) {
                bestRank = rank
                best =
                    JSONObject(screen.toString())
                        .put("expected_package", expectedPackage)
                        .put("observed_package_for_transfer", observedPackage)
                        .put("transfer_package_match", packageMatch)
                        .put("transfer_content_state", contentState)
            }

            val captureSpec =
                step.captureSpec

            val captureKind =
                captureSpec?.kind

            val contentTransferEligible =
                when (captureKind) {
                    AyanaVerifiedResultTransfer.CaptureKind.SCREEN_MARKER ->
                        contentState == "readable" ||
                            contentState == "partial"

                    AyanaVerifiedResultTransfer.CaptureKind.SCREEN_TITLE ->
                        contentState == "readable"

                    else ->
                        contentState == "readable"
                }

            val captureEvidenceReady =
                captureSpec != null &&
                    verifiedResultTransfer
                        .isObservationReadyForCapture(
                            spec = captureSpec,
                            observation = screen
                        )

            if (
                forceVisualAcceptanceProbe &&
                screen.optBoolean("success", false) &&
                packageMatch
            ) {
                forcedVisualProbeAfterAccessibilitySample = true

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "semantic_visual_acceptance_accessibility_sampled",
                    message =
                        "R9.6.1 acceptance: Accessibility проверен; screenshot branch обязателен для device proof",
                    details =
                        "step=${step.key}; package=$observedPackage; content=$contentState; " +
                            "marker_ready=$captureEvidenceReady; attempts=$attempts"
                )

                break
            }

            if (
                screen.optBoolean("success", false) &&
                packageMatch &&
                contentTransferEligible &&
                textEvidence &&
                captureEvidenceReady
            ) {
                val verifiedSample =
                    JSONObject(screen.toString())
                        .put("verified", true)
                        .put("expected_package", expectedPackage)
                        .put("observed_package_for_transfer", observedPackage)
                        .put("transfer_package_match", true)
                        .put("transfer_content_state", contentState)
                        .put(
                            "transfer_capture_kind",
                            captureKind?.name.orEmpty()
                        )
                        .put(
                            "transfer_content_eligible",
                            true
                        )
                        .put("transfer_observation_attempts", attempts)
                        .put(
                            "transfer_observation_elapsed_ms",
                            (
                                SystemClock.elapsedRealtime() -
                                    startedAt
                                )
                                .coerceAtLeast(0L)
                        )
                        .put("transfer_observation_timeout", false)

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "verified_result_transfer_observation",
                    message =
                        "R9.5 source observation verified: ${step.appKey}:${step.actionKey}",
                    details =
                        "step=${step.key}; package=$observedPackage; " +
                            "content=$contentState; capture_kind=${captureKind?.name.orEmpty()}; " +
                            "capture_ready=$captureEvidenceReady; attempts=$attempts"
                )

                return verifiedSample
            }

            try {
                Thread.sleep(
                    RESULT_TRANSFER_OBSERVATION_POLL_MS
                )
            } catch (_: InterruptedException) {
                Thread.currentThread()
                    .interrupt()
                break
            }
        } while (
            SystemClock.elapsedRealtime() <
                deadline &&
            !shuttingDown
        )

        val accessibilityTimeout =
            JSONObject(best.toString())
                .put("verified", false)
                .put("expected_package", expectedPackage)
                .put("transfer_observation_attempts", attempts)
                .put(
                    "transfer_observation_elapsed_ms",
                    (
                        SystemClock.elapsedRealtime() -
                            startedAt
                        )
                        .coerceAtLeast(0L)
                )
                .put(
                    "transfer_observation_timeout",
                    !forcedVisualProbeAfterAccessibilitySample
                )
                .put(
                    "transfer_observation_forced_visual_probe",
                    forcedVisualProbeAfterAccessibilitySample
                )
                .put(
                    "transfer_expected_marker",
                    step.captureSpec
                        ?.takeIf {
                            it.kind ==
                                AyanaVerifiedResultTransfer.CaptureKind.SCREEN_MARKER
                        }
                        ?.marker
                        .orEmpty()
                        .take(240)
                )
                .put(
                    "transfer_marker_observed",
                    step.captureSpec
                        ?.takeIf {
                            it.kind ==
                                AyanaVerifiedResultTransfer.CaptureKind.SCREEN_MARKER
                        }
                        ?.let { spec ->
                            verifiedResultTransfer
                                .isMarkerObserved(
                                    observation = best,
                                    marker = spec.marker
                                )
                        }
                        ?: false
                )

        val shouldTryVisualFallback =
            forceVisualAcceptanceProbe ||
                (
                    step.captureSpec?.kind ==
                        AyanaVerifiedResultTransfer.CaptureKind.SCREEN_MARKER &&
                        !accessibilityTimeout.optBoolean("transfer_marker_observed", false)
                    )

        if (shouldTryVisualFallback) {
            val visual =
                attemptVerifiedSemanticScreenMarkerFallback(
                    step = step,
                    actionResult = actionResult,
                    expectedPackage = expectedPackage,
                    commandToken = commandToken
                )

            if (
                visual.optBoolean("success", false) &&
                visual.optBoolean("verified", false)
            ) {
                return JSONObject(visual.toString())
                    .put("accessibility_first", true)
                    .put(
                        "accessibility_marker_observed",
                        accessibilityTimeout.optBoolean(
                            "transfer_marker_observed",
                            false
                        )
                    )
                    .put(
                        "accessibility_observation_timeout",
                        accessibilityTimeout.optBoolean(
                            "transfer_observation_timeout",
                            true
                        )
                    )
                    .put(
                        "semantic_visual_acceptance_forced",
                        forceVisualAcceptanceProbe
                    )
                    .put("accessibility_observation_attempts", attempts)
                    .put(
                        "accessibility_observation_elapsed_ms",
                        accessibilityTimeout.optLong(
                            "transfer_observation_elapsed_ms",
                            0L
                        )
                    )
                    .put("expected_package", expectedPackage)
                    .put("observed_package_for_transfer", expectedPackage)
                    .put("transfer_package_match", true)
                    .put("transfer_content_state", "readable")
                    .put("transfer_capture_kind", "SCREEN_MARKER")
                    .put("transfer_content_eligible", true)
                    .put("transfer_observation_timeout", false)
            }

            return JSONObject(accessibilityTimeout.toString())
                .put(
                    "reason",
                    "semantic_visual_fallback_failed:" +
                        visual.optString("reason").ifBlank { "not_verified" }.take(220)
                )
                .put("semantic_visual_fallback_attempted", true)
                .put(
                    "semantic_visual_fallback_verified",
                    visual.optBoolean("verified", false)
                )
                .put(
                    "semantic_visual_fallback_reason",
                    visual.optString("reason").take(260)
                )
                .put(
                    "semantic_visual_fallback_stage",
                    visual.optString("semantic_visual_fallback_stage")
                )
                .put(
                    "semantic_visual_capture_mode",
                    visual.optString("capture_mode")
                )
                .put(
                    "semantic_visual_screenshot_error",
                    visual.optString("screenshot_error")
                )
        }

        return accessibilityTimeout
    }

    private fun renderAppIntegrationDeviceProbeSummary(
        report: JSONObject
    ): String {
        val passed =
            report.optInt(
                "passed",
                0
            )

        val total =
            report.optInt(
                "steps_total",
                AyanaAppIntegrationDeviceProbe.EXPECTED_STEP_COUNT
            )

        val failedKeys =
            mutableListOf<String>()

        val results =
            report.optJSONArray(
                "results"
            ) ?: JSONArray()

        for (
            index in
            0 until results.length()
        ) {
            val item =
                results.optJSONObject(index)
                    ?: continue

            if (
                !item.optBoolean(
                    "success",
                    false
                )
            ) {
                failedKeys +=
                    item
                        .optString(
                            "key",
                            "step_${index + 1}"
                        )
            }
        }

        return if (
            report.optBoolean(
                "success",
                false
            )
        ) {
            "Интеграции приложений проверены на планшете: $passed/$total PASS. " +
                "Мои файлы, Галерея, поиск YouTube, браузер и черновик Календаря подтверждены; " +
                "AYANA возвращена на передний план после каждого шага. " +
                "Событие календаря не сохранялось."
        } else {
            "Проверка интеграций приложений завершена: $passed/$total PASS. " +
                "Не подтверждены: ${
                    failedKeys
                        .joinToString(", ")
                        .ifBlank { "неизвестный шаг" }
                }. " +
                "Постоянные изменения не выполнялись; событие календаря не сохранялось."
        }
    }

    private fun isR10_5LiveAdaptiveAcceptanceCommand(
        command: String
    ): Boolean {
        val normalized =
            command
                .trim()
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")

        return normalized in
            setOf(
                "проверь живую адаптивную автономность",
                "протестируй живую адаптивную автономность",
                "проверь generalized live adaptive autonomy",
                "проверь live adaptive autonomy",
                "проверь r10.5"
            )
    }

    private fun runLocalMultiAppTaskCommand(
        command: String,
        silent: Boolean
    ): Boolean {
        val r10_5Acceptance =
            isR10_5LiveAdaptiveAcceptanceCommand(
                command
            )

        val effectivePlanCommand =
            if (r10_5Acceptance) {
                "проверь семантическое чтение внешнего экрана"
            } else {
                command
            }

        val plan =
            multiAppTaskOrchestrator
                .parse(effectivePlanCommand)
                ?: return false

        executionPhase(
            phase =
                if (r10_5Acceptance) {
                    "r10_5_live_adaptive_autonomy_acceptance"
                } else {
                    "multi_app_task_orchestration"
                },
            executor =
                if (r10_5Acceptance) {
                    "adaptive_execution_loop_v1_1+multi_app_task_orchestrator"
                } else {
                    "multi_app_task_orchestrator"
                }
        )

        val commandToken =
            activeCommandToken

        val originalPage =
            currentAyanaPageKeyForAppIntegrationProbe()

        val worker =
            thread(
                start = false,
                name = "AyanaMultiAppTaskOrchestrator"
            ) {
                var goalId: String? = null

                try {
                    val durable =
                        durableGoalStore.startGoal(
                            command = plan.originalCommand,
                            source = if (silent) "text" else "voice",
                            mode = AyanaDurableGoalStore.MODE_ORCHESTRATOR,
                            safeAutoResume = false
                        )

                    goalId =
                        durable
                            .optString("id")
                            .trim()
                            .takeIf { it.isNotBlank() }

                    currentDurableGoalId =
                        goalId

                    val envelope =
                        multiAppTaskOrchestrator
                            .plannerEnvelope(plan)

                    durableGoalStore
                        .attachPlannerEnvelope(
                            goalId,
                            envelope
                        )

                    val taskGraph =
                        AyanaAutonomousTaskGraph.create(
                            goal = plan.originalCommand,
                            plannerEnvelope = envelope
                        )

                    val adaptiveExecutionLoop =
                        AyanaAdaptiveExecutionLoop.create(
                            objective =
                                if (r10_5Acceptance) {
                                    "R10.5 live adaptive multi-app acceptance"
                                } else {
                                    plan.originalCommand
                                },
                            executionLane = "multi_app",
                            authorityContext =
                                "app_integration_registry+verified_result_transfer+screen_intelligence"
                        )

                    val crossLaneContinuity =
                        AyanaCrossLaneAdaptiveContinuity.create(
                            objective =
                                if (r10_5Acceptance) {
                                    "R10.5 live adaptive multi-app acceptance"
                                } else {
                                    plan.originalCommand
                                },
                            adaptiveLoop = adaptiveExecutionLoop,
                            initialLane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                            initialAuthority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP,
                            authorityCeiling =
                                AyanaCrossLaneAdaptiveContinuity.defaultUnifiedAuthorityCeiling()
                        )

                    val adaptiveBeforeStateByStep =
                        mutableMapOf<String, String>()

                    val adaptiveArgumentsByStep =
                        mutableMapOf<String, JSONObject>()

                    val adaptiveProposalByStep =
                        mutableMapOf<String, JSONObject>()

                    var adaptiveReplanObserved =
                        false

                    var adaptiveReplanTrigger =
                        ""

                    var adaptiveVerifiedPrefixPreserved =
                        false

                    var adaptiveSameFailedReplayBlocked =
                        false

                    var adaptiveVisualContinuationVerified =
                        false

                    var adaptiveSnapshotPersisted =
                        false

                    var browserOpenDispatchCount =
                        0

                    val initialAdaptiveCheckpoint =
                        durableGoalStore.checkpoint(
                            goalId,
                            JSONObject()
                                .put(
                                    "task_graph",
                                    taskGraph.persistenceSnapshot()
                                )
                                .put(
                                    "adaptive_execution_loop",
                                    adaptiveExecutionLoop.persistenceSnapshot()
                                )
                                .put(
                                    "cross_lane_continuity",
                                    crossLaneContinuity.persistenceSnapshot(
                                        adaptiveExecutionLoop
                                    )
                                )
                                .put("adaptive_lane", "multi_app")
                                .put(
                                    "adaptive_authority",
"app_integration_registry+verified_result_transfer+screen_intelligence"
                                )
                                .put("safe_auto_resume", false)
                                .put("last_checkpoint", "r10_5_multi_app_started")
                        )

                    adaptiveSnapshotPersisted =
                        initialAdaptiveCheckpoint !=
                            null

                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state = "multi_app_task_started",
                        message =
                            "Multi-App Task Orchestrator v${AyanaMultiAppTaskOrchestrator.VERSION} запущен: ${plan.steps.size} шага",
                        details =
                            "goal_id=${goalId.orEmpty()}; plan=${plan.key}; " +
                                "source=${plan.source}; graph=${taskGraph.compactSummary()}"
                    )

                    val report =
                        multiAppTaskOrchestrator.run(
                            plan = plan,
                            taskGraph = taskGraph,
                            execute = { step ->
                                if (
                                    isCommandCancelled(commandToken) ||
                                    commandToken != activeCommandToken
                                ) {
                                    JSONObject()
                                        .put("success", false)
                                        .put("verified", false)
                                        .put("terminal_status", "CANCELLED")
                                        .put("action_dispatched", false)
                                        .put("message", "Команда отменена до следующего app-step.")
                                } else {
                                    val adaptiveProposal =
                                        adaptiveProposalByStep[
                                            step.key
                                        ]

                                    if (
                                        adaptiveProposal ==
                                        null ||
                                        !adaptiveProposal.optBoolean(
                                            "allowed",
                                            false
                                        )
                                    ) {
                                        JSONObject()
                                            .put("success", false)
                                            .put("verified", false)
                                            .put("terminal_status", "BLOCKED")
                                            .put("action_dispatched", false)
                                            .put(
                                                "message",
                                                "R10.5 adaptive ledger не разрешил dispatch шага ${step.key}."
                                            )
                                            .put(
                                                "adaptive_reason",
                                                adaptiveProposal
                                                    ?.optString("reason")
                                                    .orEmpty()
                                                    .ifBlank {
                                                        "proposal_not_persisted"
                                                    }
                                            )
                                    } else {
                                        commandHistoryStore.addEvent(
                                            activeCommandHistoryId,
                                            state = "multi_app_task_step",
                                            message =
                                                "Шаг ${step.appKey}:${step.actionKey}",
                                            details =
                                                "payload=${step.payload.take(260)}; phase=dispatch; " +
                                                    "adaptive_revision=${adaptiveExecutionLoop.currentRevision()}"
                                        )

                                        if (
                                            step.appKey ==
                                            AyanaAppIntegrationRegistry.APP_BROWSER
                                        ) {
                                            browserOpenDispatchCount++
                                        }

                                        val actionResult =
                                            executeAppIntegrationAction(
                                                appKey = step.appKey,
                                                actionKey = step.actionKey,
                                                payload = step.payload
                                            )

                                        val adaptiveArgs =
                                            adaptiveArgumentsByStep[
                                                step.key
                                            ] ?: JSONObject()
                                                .put("app_key", step.appKey)
                                                .put("action_key", step.actionKey)
                                                .put("payload", step.payload)

                                        val beforeState =
                                            adaptiveBeforeStateByStep[
                                                step.key
                                            ].orEmpty()

                                        val afterState =
                                            AyanaAdaptiveExecutionLoop
                                                .fingerprintState(
                                                    actionResult.toString()
                                                )

                                        val actionVerified =
                                            actionResult.optBoolean(
                                                "success",
                                                false
                                            ) &&
                                                actionResult.optBoolean(
                                                    "verified",
                                                    false
                                                )

                                        val adaptiveRecord =
                                            adaptiveExecutionLoop
                                                .recordResult(
                                                    toolName =
                                                        "app_integration:${step.appKey}:${step.actionKey}",
                                                    arguments = adaptiveArgs,
                                                    beforeStateFingerprint = beforeState,
                                                    afterStateFingerprint = afterState,
                                                    success = actionVerified,
                                                    verified = actionVerified,
                                                    actionDispatched =
                                                        actionResult.optBoolean(
                                                            "action_dispatched",
                                                            false
                                                        ),
                                                    actionCommitted =
                                                        actionResult.optBoolean(
                                                            "action_committed",
                                                            false
                                                        ),
                                                    reconciliationComplete =
                                                        actionResult.optBoolean(
                                                            "reconciliation_complete",
                                                            actionVerified
                                                        ),
                                                    evidence =
                                                        actionResult.optString(
                                                            "message",
                                                            actionResult.optString(
                                                                "reason"
                                                            )
                                                        ),
                                                    failureLayer =
                                                        actionResult.optString(
                                                            "failure_layer"
                                                        ),
                                                    replanRecommended =
                                                        actionResult.optBoolean(
                                                            "replan_recommended",
                                                            false
                                                        )
                                                )

                                        commandHistoryStore.addEvent(
                                            activeCommandHistoryId,
                                            state = "adaptive_multi_app_action_recorded",
                                            message =
                                                if (adaptiveRecord.optBoolean("verified", false)) {
                                                    "R10.5 App Integration action вошёл в verified prefix"
                                                } else {
                                                    "R10.5 App Integration action не подтверждён"
                                                },
                                            details =
                                                (
                                                    adaptiveRecord.toString() +
                                                        "; " +
                                                        adaptiveExecutionLoop.compactSummary()
                                                    )
                                                    .take(1600)
                                        )

                                        actionResult
                                    }
                                }
                            },
                            observe = { step, actionResult ->
                                val observationArgs =
                                    JSONObject()
                                        .put("step_key", step.key)
                                        .put("app_key", step.appKey)
                                        .put("action_key", step.actionKey)
                                        .put(
                                            "capture_kind",
                                            step.captureSpec
                                                ?.kind
                                                ?.name
                                                .orEmpty()
                                        )
                                        .put(
                                            "marker",
                                            step.captureSpec
                                                ?.marker
                                                .orEmpty()
                                                .take(240)
                                        )

                                val observationState =
                                    AyanaAdaptiveExecutionLoop
                                        .fingerprintState(
                                            actionResult.toString()
                                        )

                                val accessibilityTool =
                                    "screen_observe_accessibility"

                                val accessibilityProposal =
                                    adaptiveExecutionLoop
                                        .propose(
                                            toolName = accessibilityTool,
                                            arguments = observationArgs,
                                            stateFingerprint = observationState,
                                            mayMutate = false,
                                            authoritySource =
                                                "screen_intelligence:accessibility+verified_result_transfer"
                                        )

                                if (
                                    !accessibilityProposal.optBoolean(
                                        "allowed",
                                        false
                                    )
                                ) {
                                    JSONObject()
                                        .put("success", false)
                                        .put("verified", false)
                                        .put(
                                            "reason",
                                            "adaptive_observation_proposal_blocked:" +
                                                accessibilityProposal.optString("reason")
                                        )
                                        .put("action_dispatched", false)
                                } else {
                                    val observation =
                                        observeVerifiedResultTransferScreen(
                                            step = step,
                                            actionResult = actionResult,
                                            commandToken = commandToken
                                        )

                                    val observationVerified =
                                        observation.optBoolean(
                                            "success",
                                            false
                                        ) &&
                                            observation.optBoolean(
                                                "verified",
                                                false
                                            )

                                    val visualPathUsed =
                                        observationVerified &&
                                            observation.optBoolean(
                                                "accessibility_first",
                                                false
                                            )

                                    val accessibilityMarkerObserved =
                                        observation.optBoolean(
                                            "accessibility_marker_observed",
                                            false
                                        )

                                    val naturalAccessibilityMiss =
                                        visualPathUsed &&
                                            !accessibilityMarkerObserved

                                    val controlledAcceptanceMiss =
                                        r10_5Acceptance &&
                                            visualPathUsed &&
                                            accessibilityMarkerObserved

                                    if (
                                        naturalAccessibilityMiss ||
                                        controlledAcceptanceMiss
                                    ) {
                                        val failedObservationTool =
                                            if (naturalAccessibilityMiss) {
                                                accessibilityTool
                                            } else {
                                                "screen_observe_accessibility_alternate"
                                            }

                                        if (controlledAcceptanceMiss) {
                                            // The actual Accessibility branch succeeded, so the dedicated
                                            // acceptance adds a separate PRE-DISPATCH read-only alternative
                                            // candidate only to prove revision/replay semantics. No Android
                                            // action or screenshot is repeated by this synthetic miss.
                                            adaptiveExecutionLoop
                                                .recordResult(
                                                    toolName = accessibilityTool,
                                                    arguments = observationArgs,
                                                    beforeStateFingerprint = observationState,
                                                    afterStateFingerprint = observationState,
                                                    success = true,
                                                    verified = true,
                                                    actionDispatched = false,
                                                    actionCommitted = false,
                                                    reconciliationComplete = true,
                                                    evidence = "Accessibility marker was already observable"
                                                )

                                            adaptiveExecutionLoop
                                                .propose(
                                                    toolName = failedObservationTool,
                                                    arguments = observationArgs,
                                                    stateFingerprint = observationState,
                                                    mayMutate = false,
                                                    authoritySource =
                                                        "controlled_pre_dispatch_read_only_alternative"
                                                )
                                        }

                                        val failedRecord =
                                            adaptiveExecutionLoop
                                                .recordResult(
                                                    toolName = failedObservationTool,
                                                    arguments = observationArgs,
                                                    beforeStateFingerprint = observationState,
                                                    afterStateFingerprint = observationState,
                                                    success = false,
                                                    verified = false,
                                                    actionDispatched = false,
                                                    actionCommitted = false,
                                                    reconciliationComplete = true,
                                                    evidence =
                                                        if (naturalAccessibilityMiss) {
                                                            "Accessibility primary marker not observed; visual package-bound alternative required"
                                                        } else {
                                                            "Controlled pre-dispatch alternate observation miss for adaptive acceptance"
                                                        },
                                                    failureLayer = "observation",
                                                    replanRecommended = true
                                                )

                                        val replayProbe =
                                            adaptiveExecutionLoop
                                                .propose(
                                                    toolName = failedObservationTool,
                                                    arguments = observationArgs,
                                                    stateFingerprint = observationState,
                                                    mayMutate = false,
                                                    authoritySource =
                                                        if (naturalAccessibilityMiss) {
                                                            "screen_intelligence:accessibility+verified_result_transfer"
                                                        } else {
                                                            "controlled_pre_dispatch_read_only_alternative"
                                                        }
                                                )

                                        adaptiveSameFailedReplayBlocked =
                                            !replayProbe.optBoolean(
                                                "allowed",
                                                true
                                            ) &&
                                                replayProbe.optString(
                                                    "reason"
                                                ) ==
                                                "failed_transition_replay_blocked"

                                        adaptiveReplanTrigger =
                                            if (naturalAccessibilityMiss) {
                                                "multi_app_accessibility_marker_not_observed"
                                            } else {
                                                "controlled_pre_dispatch_observation_branch"
                                            }

                                        val adaptiveReplan =
                                            adaptiveExecutionLoop
                                                .beginReplan(
                                                    reason = adaptiveReplanTrigger,
                                                    stateFingerprint = observationState
                                                )

                                        adaptiveReplanObserved =
                                            adaptiveReplan.optBoolean(
                                                "allowed",
                                                false
                                            )

                                        adaptiveVerifiedPrefixPreserved =
                                            adaptiveReplanObserved &&
                                                adaptiveReplan.optInt(
                                                    "verified_prefix_count",
                                                    0
                                                ) >=
                                                1

                                        commandHistoryStore.addEvent(
                                            activeCommandHistoryId,
                                            state =
                                                if (adaptiveReplanObserved) {
                                                    "adaptive_multi_app_replan_started"
                                                } else {
                                                    "adaptive_multi_app_replan_blocked"
                                                },
                                            message =
                                                "R10.5 Multi-App observation-path revision",
                                            details =
                                                (
"failed=${failedRecord.toString()}; " +
                                                        "replay=${replayProbe.toString()}; " +
                                                        "replan=${adaptiveReplan.toString()}"
                                                    )
                                                    .take(1900)
                                        )

                                        if (!adaptiveReplanObserved) {
                                            JSONObject(observation.toString())
                                                .put("success", false)
                                                .put("verified", false)
                                                .put(
                                                    "reason",
                                                    "adaptive_multi_app_replan_blocked:" +
                                                        adaptiveReplan.optString("reason")
                                                )
                                        } else {
                                            val visualProposal =
                                                adaptiveExecutionLoop
                                                    .propose(
                                                        toolName =
                                                            "screen_observe_package_bound_visual",
                                                        arguments = observationArgs,
                                                        stateFingerprint = observationState,
                                                        mayMutate = false,
                                                        authoritySource =
                                                            "r9_7_package_bound_visual+screen_intelligence"
                                                    )

                                            if (
                                                !visualProposal.optBoolean(
                                                    "allowed",
                                                    false
                                                )
                                            ) {
                                                JSONObject(observation.toString())
                                                    .put("success", false)
                                                    .put("verified", false)
                                                    .put(
                                                        "reason",
                                                        "adaptive_visual_proposal_blocked:" +
                                                            visualProposal.optString("reason")
                                                    )
                                            } else {
                                                val visualRecord =
                                                    adaptiveExecutionLoop
                                                        .recordResult(
                                                            toolName =
                                                                "screen_observe_package_bound_visual",
                                                            arguments = observationArgs,
                                                            beforeStateFingerprint = observationState,
                                                            afterStateFingerprint =
                                                                AyanaAdaptiveExecutionLoop
                                                                    .fingerprintState(
                                                                        observation.toString()
                                                                    ),
                                                            success = observationVerified,
                                                            verified = observationVerified,
                                                            actionDispatched = false,
                                                            actionCommitted = false,
                                                            reconciliationComplete = true,
                                                            evidence =
                                                                observation.optString(
                                                                    "reason",
                                                                    "package-bound visual observation"
                                                                ),
                                                            failureLayer =
                                                                if (observationVerified) {
                                                                    ""
                                                                } else {
                                                                    "visual_observation"
                                                                }
                                                        )

                                                adaptiveVisualContinuationVerified =
                                                    visualRecord.optBoolean(
                                                        "verified",
                                                        false
                                                    )

                                                observation
                                            }
                                        }
                                    } else {
                                        adaptiveExecutionLoop
                                            .recordResult(
                                                toolName = accessibilityTool,
                                                arguments = observationArgs,
                                                beforeStateFingerprint = observationState,
                                                afterStateFingerprint =
                                                    AyanaAdaptiveExecutionLoop
                                                        .fingerprintState(
                                                            observation.toString()
                                                        ),
                                                success = observationVerified,
                                                verified = observationVerified,
                                                actionDispatched = false,
                                                actionCommitted = false,
                                                reconciliationComplete = true,
                                                evidence =
                                                    observation.optString(
                                                        "reason",
                                                        "Accessibility observation"
                                                    ),
                                                failureLayer =
                                                    if (observationVerified) {
                                                        ""
                                                    } else {
                                                        "observation"
                                                    },
                                                replanRecommended = false
                                            )

                                        observation
                                    }
                                }
                            },
                            restore = { step ->
                                restoreAyanaAfterAppIntegrationProbe(
                                    pageKey = originalPage,
                                    stepKey = step.key
                                )
                            },
                            checkpoint = { phase, index, step, evidence ->
                                val graphSnapshot =
                                    evidence
                                        .optJSONObject("task_graph")
                                        ?: taskGraph.persistenceSnapshot()

                                if (
                                    phase == "before_step" &&
                                    step != null
                                ) {
                                    val continuityGate =
                                        crossLaneContinuity.transitionTo(
                                            adaptiveLoop = adaptiveExecutionLoop,
                                            targetLane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                                            targetAuthority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP,
                                            stateFingerprint =
                                                adaptiveBeforeStateByStep[
                                                    step.key
                                                ].orEmpty(),
                                            reason = "multi_app_step_context"
                                        )

                                    val adaptiveArgs =
                                        JSONObject()
                                            .put("app_key", step.appKey)
                                            .put("action_key", step.actionKey)
                                            .put("payload", step.payload)

                                    val stateBefore =
                                        try {
                                            AyanaAdaptiveExecutionLoop
                                                .fingerprintState(
                                                    screenIntelligence
                                                        .getScreenState()
                                                        .toString()
                                                )
                                        } catch (_: Exception) {
                                            AyanaAdaptiveExecutionLoop
                                                .fingerprintState(
                                                    "multi_app_before:${step.key}:${index}"
                                                )
                                        }

                                    val proposal =
                                        if (
                                            continuityGate.optBoolean(
                                                "allowed",
                                                false
                                            )
                                        ) {
                                            adaptiveExecutionLoop
                                                .propose(
                                                    toolName =
                                                        "app_integration:${step.appKey}:${step.actionKey}",
                                                    arguments = adaptiveArgs,
                                                    stateFingerprint = stateBefore,
                                                    mayMutate = false,
                                                    authoritySource =
                                                        "app_integration_registry:autonomous_allowed_non_mutation"
                                                )
                                        } else {
                                            JSONObject(continuityGate.toString())
                                                .put("allowed", false)
                                                .put(
                                                    "reason",
                                                    continuityGate.optString(
                                                        "reason",
                                                        "cross_lane_context_blocked"
                                                    )
                                                )
                                        }

                                    adaptiveBeforeStateByStep[
                                        step.key
                                    ] =
                                        stateBefore

                                    adaptiveArgumentsByStep[
                                        step.key
                                    ] =
                                        adaptiveArgs

                                    adaptiveProposalByStep[
                                        step.key
                                    ] =
                                        proposal

                                    commandHistoryStore.addEvent(
                                        activeCommandHistoryId,
                                        state =
                                            if (proposal.optBoolean("allowed", false)) {
                                                "adaptive_multi_app_proposal"
                                            } else {
                                                "adaptive_multi_app_proposal_blocked"
                                            },
                                        message =
                                            "R10.5 Multi-App plan-step прошёл adaptive proposal gate",
                                        details =
                                            proposal.toString().take(1400)
                                    )
                                }

                                val savedAdaptiveCheckpoint =
                                    durableGoalStore.checkpoint(
                                        goalId,
                                        JSONObject()
                                            .put("task_graph", graphSnapshot)
                                            .put(
                                                "adaptive_execution_loop",
                                                adaptiveExecutionLoop.persistenceSnapshot()
                                            )
                                            .put(
                                                "cross_lane_continuity",
                                                crossLaneContinuity.persistenceSnapshot(
                                                    adaptiveExecutionLoop
                                                )
                                            )
                                            .put(
                                                "adaptive_lane",
                                                adaptiveExecutionLoop.executionLane()
                                            )
                                            .put(
                                                "adaptive_revision",
                                                adaptiveExecutionLoop.currentRevision()
                                            )
                                            .put(
                                                "adaptive_authority",
                                                adaptiveExecutionLoop.authorityContext()
                                            )
                                            .put("safe_auto_resume", false)
                                            .put(
                                                "last_checkpoint",
                                                "r10_5_${phase.take(60)}"
                                            )
                                            .put(
                                                "last_tool_name",
                                                if (step == null) {
                                                    "multi_app_orchestrator"
                                                } else {
                                                    "app_integration:${step.appKey}:${step.actionKey}"
                                                }
                                            )
                                            .put(
                                                "last_result",
                                                evidence
                                                    .toString()
                                                    .take(1400)
                                            )
                                    )

                                adaptiveSnapshotPersisted =
                                    adaptiveSnapshotPersisted ||
                                        savedAdaptiveCheckpoint !=
                                        null

                                commandHistoryStore.addEvent(
                                    activeCommandHistoryId,
                                    state = "multi_app_task_checkpoint",
                                    message =
                                        "Multi-App checkpoint: $phase",
                                    details =
                                        "goal_id=${goalId.orEmpty()}; index=$index; " +
                                            "step=${step?.key.orEmpty()}; " +
                                            "adaptive_revision=${adaptiveExecutionLoop.currentRevision()}; " +
                                            "adaptive_saved=${savedAdaptiveCheckpoint != null}"
                                )
                            },
                            shouldCancel = {
                                isCommandCancelled(commandToken) ||
                                    commandToken != activeCommandToken ||
                                    Thread.currentThread().isInterrupted
                            }
                        )

                    val cancelled =
                        report.optBoolean("cancelled", false) ||
                            isCommandCancelled(commandToken) ||
                            commandToken != activeCommandToken

                    var success =
                        !cancelled &&
                            report.optBoolean("success", false) &&
                            report.optBoolean("verified", false)

                    var youtubeConsumerVerified =
                        false

                    val multiAppResults =
                        report.optJSONArray(
                            "results"
                        ) ?: JSONArray()

                    for (
                        resultIndex in
                        0 until multiAppResults.length()
                    ) {
                        val row =
                            multiAppResults.optJSONObject(
                                resultIndex
                            ) ?: continue

                        if (
                            row.optString(
                                "app_key"
                            ) ==
                            AyanaAppIntegrationRegistry.APP_YOUTUBE &&
                            row.optBoolean(
                                "success",
                                false
                            )
                        ) {
                            youtubeConsumerVerified =
                                true
                        }
                    }

                    val adaptiveTerminalDecision =
                        if (success) {
                            adaptiveExecutionLoop
                                .markTerminal(
                                    verified = true,
                                    evidence =
                                        "Multi-App report verified: " +
                                            report.toString().take(1600)
                                )
                        } else {
                            JSONObject()
                                .put(
                                    "allowed",
                                    false
                                )
                                .put(
                                    "reason",
                                    "multi_app_report_not_verified"
                                )
                        }

                    if (
                        success &&
                        !adaptiveTerminalDecision.optBoolean(
                            "allowed",
                            false
                        )
                    ) {
                        success =
                            false
                    }

                    if (!goalId.isNullOrBlank()) {
                        try {
                            val finalAdaptiveCheckpoint =
                                durableGoalStore
                                    .checkpoint(
                                        goalId,
                                        JSONObject()
                                            .put(
                                                "adaptive_execution_loop",
                                                adaptiveExecutionLoop.persistenceSnapshot()
                                            )
                                            .put(
                                                "adaptive_lane",
                                                adaptiveExecutionLoop.executionLane()
                                            )
                                            .put(
                                                "adaptive_revision",
                                                adaptiveExecutionLoop.currentRevision()
                                            )
                                            .put(
                                                "adaptive_authority",
                                                adaptiveExecutionLoop.authorityContext()
                                            )
                                            .put(
                                                "last_checkpoint",
                                                if (success) {
                                                    "r10_5_adaptive_terminal_verified"
                                                } else {
                                                    "r10_5_adaptive_terminal_not_verified"
                                                }
                                            )
                                    )

                            adaptiveSnapshotPersisted =
                                adaptiveSnapshotPersisted ||
                                    finalAdaptiveCheckpoint !=
                                    null
                        } catch (_: Exception) {
                        }
                    }

                    val r10_5AcceptanceEvidence =
                        JSONObject()
                            .put(
                                "adaptive_loop_version",
                                AyanaAdaptiveExecutionLoop.VERSION
                            )
                            .put(
                                "execution_lane",
                                adaptiveExecutionLoop.executionLane()
                            )
                            .put(
                                "authority_context",
                                adaptiveExecutionLoop.authorityContext()
                            )
                            .put(
                                "initial_revision",
                                0
                            )
                            .put(
                                "final_revision",
                                adaptiveExecutionLoop.currentRevision()
                            )
                            .put(
                                "replan_count",
                                adaptiveExecutionLoop.replanCount()
                            )
                            .put(
                                "verified_step_count",
                                adaptiveExecutionLoop.verifiedStepCount()
                            )
                            .put(
                                "failed_transition_count",
                                adaptiveExecutionLoop.failedTransitionCount()
                            )
                            .put(
                                "replan_trigger",
                                adaptiveReplanTrigger
                            )
                            .put(
                                "verified_prefix_preserved",
                                adaptiveVerifiedPrefixPreserved
                            )
                            .put(
                                "same_failed_transition_replay_blocked",
                                adaptiveSameFailedReplayBlocked
                            )
                            .put(
                                "browser_open_dispatch_count",
                                browserOpenDispatchCount
                            )
                            .put(
                                "browser_open_replayed",
                                browserOpenDispatchCount >
                                    1
                            )
                            .put(
                                "structured_visual_verified",
                                adaptiveVisualContinuationVerified
                            )
                            .put(
                                "youtube_consumer_verified",
                                youtubeConsumerVerified
                            )
                            .put(
                                "verified_result_continued_after_replan",
                                adaptiveVisualContinuationVerified &&
                                    youtubeConsumerVerified
                            )
                            .put(
                                "adaptive_snapshot_persisted",
                                adaptiveSnapshotPersisted
                            )
                            .put(
                                "r10_3_recovery_compatible",
                                adaptiveSnapshotPersisted &&
                                    !goalId.isNullOrBlank()
                            )
                            .put(
                                "capability_authority_persisted",
                                adaptiveExecutionLoop
                                    .authorityContext()
                                    .isNotBlank()
                            )
                            .put(
                                "unresolved_side_effect",
                                adaptiveExecutionLoop
                                    .hasUnresolvedSideEffect()
                            )
                            .put(
                                "terminal_verified",
                                adaptiveTerminalDecision
                                    .optBoolean(
                                        "allowed",
                                        false
                                    )
                            )
                            .put(
                                "restore_verified",
                                !report.optBoolean(
                                    "restore_failure_detected",
                                    false
                                )
                            )
                            .put(
                                "mutation_committed_detected",
                                report.optBoolean(
                                    "mutation_committed_detected",
                                    false
                                )
                            )
                            .put(
                                "blind_replay_allowed",
                                false
                            )
                            .put(
                                "persistent_user_data_mutation",
                                false
                            )
                            .put(
                                "agent_core_turns",
                                0
                            )
                            .put(
                                "worker_visual_turns",
                                if (
                                    adaptiveVisualContinuationVerified
                                ) {
                                    1
                                } else {
                                    0
                                }
                            )
                            .put(
                                "multi_app_live_path",
                                true
                            )
                            .put(
                                "multi_app_orchestrator_version",
                                AyanaMultiAppTaskOrchestrator.VERSION
                            )
                            .put(
                                "adaptive_summary",
                                adaptiveExecutionLoop.compactSummary()
                            )

                    val r10_5AcceptanceOk =
                        r10_5Acceptance &&
                            success &&
                            adaptiveExecutionLoop.currentRevision() >=
                            1 &&
                            adaptiveExecutionLoop.replanCount() >=
                            1 &&
                            adaptiveVerifiedPrefixPreserved &&
                            adaptiveSameFailedReplayBlocked &&
                            browserOpenDispatchCount ==
                            1 &&
                            adaptiveVisualContinuationVerified &&
                            youtubeConsumerVerified &&
                            adaptiveSnapshotPersisted &&
                            !adaptiveExecutionLoop
                                .hasUnresolvedSideEffect() &&
                            adaptiveTerminalDecision
                                .optBoolean(
                                    "allowed",
                                    false
                                ) &&
                            !report.optBoolean(
                                "restore_failure_detected",
                                false
                            ) &&
                            !report.optBoolean(
                                "mutation_committed_detected",
                                false
                            )

                    if (r10_5Acceptance) {
                        r10_5AcceptanceEvidence
                            .put(
"acceptance_ok",
                                r10_5AcceptanceOk
                            )
                            .put(
                                "voice_service_release",
                                AYANA_VOICE_SERVICE_RELEASE
                            )
                            .put(
                                "accepted_checkpoint",
                                AYANA_ACCEPTED_FEATURE_CHECKPOINT
                            )
                            .put(
                                "current_release",
                                AYANA_CURRENT_FEATURE_RELEASE
                            )

                        if (!r10_5AcceptanceOk) {
                            success =
                                false

                            if (
                                adaptiveExecutionLoop.canDeclareSuccess()
                            ) {
                                adaptiveExecutionLoop
                                    .markTerminal(
                                        verified = false,
                                        evidence =
                                            "R10.5 acceptance gate not fully verified"
                                    )
                            }
                        }
                    }

                    when {
                        cancelled ->
                            durableGoalStore.markCancelled(
                                goalId,
                                "R10.5 multi-app adaptive task cancelled"
                            )

                        success ->
                            durableGoalStore.markCompleted(
                                goalId,
                                if (r10_5Acceptance) {
                                    "R10.5 live adaptive multi-app acceptance verified"
                                } else {
                                    "R10.5 verified adaptive multi-app task ${report.optInt("passed", 0)}/${report.optInt("steps_total", 0)}"
                                }
                            )

                        report.optBoolean("mutation_committed_detected", false) ||
                            report.optString("terminal_status") == "PAUSED" ||
                            adaptiveExecutionLoop.hasUnresolvedSideEffect() ->
                            durableGoalStore.markPaused(
                                goalId,
                                "R10.5 stopped on uncertain/unexpected side effect; blind replay blocked"
                            )

                        else ->
                            durableGoalStore.markFailed(
                                goalId,
                                if (r10_5Acceptance) {
                                    "R10.5 live adaptive acceptance failed verification"
                                } else {
                                    "R10.5 adaptive multi-app step/result transfer failed verification"
                                }
                            )
                    }

                    if (cancelled) {
                        return@thread
                    }

                    val resultText =
                        if (r10_5Acceptance) {
                            if (r10_5AcceptanceOk) {
                                "R10.5 Generalized Live Adaptive Autonomy подтверждён: обычный Multi-App execution вошёл в единый adaptive ledger, verified Browser-prefix сохранён, failed observation-path не повторён, revision продолжена через package-bound visual evidence, результат дошёл до YouTube и terminal state подтверждён."
                            } else {
                                "R10.5 Generalized Live Adaptive Autonomy выполнен fail-closed: один или несколько live-lane/replan gates не подтверждены."
                            }
                        } else {
                            renderMultiAppTaskSummary(
                                report = report,
                                acceptanceProbe = plan.acceptanceProbe
                            )
                        }

                    val technical =
                        if (r10_5Acceptance) {
                            r10_5AcceptanceEvidence
                                .toString()
                        } else {
                            buildString {
                                append("multi_app_orchestrator=")
                                append(AyanaMultiAppTaskOrchestrator.VERSION)
                                append("; adaptive_loop_version=")
                                append(AyanaAdaptiveExecutionLoop.VERSION)
                                append("; adaptive_lane=")
                                append(adaptiveExecutionLoop.executionLane())
                                append("; adaptive_revision=")
                                append(adaptiveExecutionLoop.currentRevision())
                                append("; adaptive_replans=")
                                append(adaptiveExecutionLoop.replanCount())
                                append("; adaptive_verified=")
                                append(adaptiveExecutionLoop.verifiedStepCount())
                                append("; adaptive_snapshot_persisted=")
                                append(adaptiveSnapshotPersisted)
                                append("; goal_id=")
                                append(goalId.orEmpty())
                                append("; passed=")
                                append(report.optInt("passed", 0))
                                append("/")
                                append(report.optInt("steps_total", 0))
                                append("; failed=")
                                append(report.optInt("failed", 0))
                                append("; terminal=")
                                append(report.optString("terminal_status"))
                                append("; mutation_committed_detected=")
                                append(report.optBoolean("mutation_committed_detected", false))
                                append("; restore_failure_detected=")
                                append(report.optBoolean("restore_failure_detected", false))
                                append("; result_transfer_version=")
                                append(report.optString("result_transfer_version"))
                                append("; transfer_count=")
                                append(report.optInt("transfer_count", 0))
                                append("; generic_result_transfer=")
                                append(report.optBoolean("generic_result_transfer", false))
                                append("; transfer_edge_count=")
                                append(report.optInt("transfer_edge_count", 0))
                                append("; typed_transfer_contracts=")
                                append(report.optBoolean("typed_transfer_contracts", false))
                                append("; first_failure_stage=")
                                append(report.optString("first_failure_stage"))
                                append("; first_failure_reason=")
                                append(report.optString("first_failure_reason").take(300))
                                append("; adaptive_summary=")
                                append(adaptiveExecutionLoop.compactSummary())
                                append("; report=")
                                append(report.toString().take(4200))
                            }
                        }

                    if (report.optBoolean("generic_result_transfer", false)) {
                        commandHistoryStore.addEvent(
                            activeCommandHistoryId,
                            state =
                                if (success) {
                                    "generic_result_transfer_verified"
                                } else {
                                    "generic_result_transfer_failed"
                                },
                            message =
                                if (success) {
                                    "R9.8 generic verified result transfer подтверждён"
                                } else {
                                    "R9.8 generic verified result transfer остановлен fail-closed"
                                },
                            details =
                                "edges=${report.optInt("transfer_edge_count", 0)}; " +
                                    "records=${report.optInt("transfer_count", 0)}; " +
                                    "typed=${report.optBoolean("typed_transfer_contracts", false)}; " +
                                    "terminal=${report.optString("terminal_status")}"
                        )
                    }

                    if (r10_5Acceptance) {
                        commandHistoryStore.addEvent(
                            activeCommandHistoryId,
                            state =
                                if (r10_5AcceptanceOk) {
                                    "r10_5_live_adaptive_autonomy_verified"
                                } else {
                                    "r10_5_live_adaptive_autonomy_not_verified"
                                },
                            message =
                                if (r10_5AcceptanceOk) {
                                    "R10.5 подтверждён: live Multi-App lane использует общий adaptive revision ledger"
                                } else {
                                    "R10.5 не прошёл все generalized live adaptive gates"
                                },
                            details =
                                r10_5AcceptanceEvidence
                                    .toString()
                                    .take(4600)
                        )
                    }

                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state = "multi_app_task_complete",
                        message =
                            if (success) {
                                "R9.6 multi-app task подтверждена"
                            } else {
                                "R9.6 multi-app task остановлена fail-closed"
                            },
                        details = technical.take(4600)
                    )

                    mainHandler.post {
                        if (
                            isCommandCancelled(commandToken) ||
                            commandToken != activeCommandToken
                        ) {
                            return@post
                        }

                        respondAndResume(
                            text = resultText,
                            silent = silent,
                            success = success,
                            technical = technical
                        )
                    }
                } catch (error: Exception) {
                    try {
                        durableGoalStore.markFailed(
                            goalId,
                            "R9.6 orchestrator exception: ${error.message ?: error.javaClass.simpleName}"
                        )
                    } catch (_: Exception) {
                    }

                    mainHandler.post {
                        if (
                            !isCommandCancelled(commandToken) &&
                            commandToken == activeCommandToken
                        ) {
                            respondAndResume(
                                text = "Многошаговая задача остановлена: внутренний orchestrator не смог подтвердить безопасное продолжение.",
                                silent = silent,
                                success = false,
                                technical =
                                    "multi_app_orchestrator=${AyanaMultiAppTaskOrchestrator.VERSION}; " +
                                        "error=${(error.message ?: error.javaClass.simpleName).take(500)}"
                            )
                        }
                    }
                } finally {
                    if (
                        currentDurableGoalId == goalId
                    ) {
                        currentDurableGoalId = null
                    }

                    if (
                        Thread.currentThread() ===
                        currentAgentThread
                    ) {
                        currentAgentThread = null
                    }
                }
            }

        currentAgentThread =
            worker

        executionKernel
            .bindThread(worker)

        worker.start()
        return true
    }

    private fun renderMultiAppTaskSummary(
        report: JSONObject,
        acceptanceProbe: Boolean
    ): String {
        val passed = report.optInt("passed", 0)
        val total = report.optInt("steps_total", 0)
        val failed = report.optInt("failed", 0)
        val terminal = report.optString("terminal_status")

        val planKey =
            report.optString("plan_key")

        return if (
            report.optBoolean("success", false) &&
            report.optBoolean("verified", false)
        ) {
            when {
                planKey ==
                    "r9.8-generic-result-transfer-device-acceptance" -> {
                    val ledger =
                        report.optJSONObject("transfer_ledger")
                            ?: JSONObject()

                    val first =
                        ledger.optJSONObject("r9_8_edge_1_2")

                    val second =
                        ledger.optJSONObject("r9_8_edge_2_3")

                    val firstType =
                        first?.optString("value_type")
                            .orEmpty()
                            .ifBlank { "UNKNOWN" }

                    val secondType =
                        second?.optString("value_type")
                            .orEmpty()
                            .ifBlank { "UNKNOWN" }

                    "R9.8 универсальный перенос результатов подтверждён: $passed/$total PASS. " +
                        "Generic compiler построил цепочку YouTube -> Browser -> Calendar без отдельного сценария под этот порядок; " +
                        "созданы ${report.optInt("transfer_edge_count", 0)} typed transfer-edge и " +
                        "${report.optInt("transfer_count", 0)} verified record ($firstType -> $secondType). " +
                        "Каждый вход получен только из verified provenance; Календарь остался DRAFT_ONLY, " +
                        "AYANA восстановлена после каждого шага, постоянных изменений нет."
                }

                planKey ==
                    "r9.6-semantic-fallback-device-acceptance" -> {
                    val ledger =
                        report.optJSONObject("transfer_ledger")
                            ?: JSONObject()

                    val record =
                        ledger.optJSONObject(
                            AyanaMultiAppTaskOrchestrator
                                .SEMANTIC_FALLBACK_ACCEPTANCE_KEY
                        )

                    val value =
                        record
                            ?.optString("value")
                            .orEmpty()
                            .ifBlank { "подтверждённый маркер" }

                    "R9.6.1 visual fallback acceptance подтверждён: $passed/$total PASS. " +
                        "Диагностический маршрут сначала проверил Accessibility, затем намеренно потребовал " +
                        "package-bound screenshot и exact-marker «${value.take(100)}» с visual provenance. " +
                        "Только после screenshot-подтверждения значение передано в YouTube и несохранённый " +
                        "черновик Календаря. Постоянных изменений нет."
                }

                planKey ==
                    "r9.5-result-transfer-device-acceptance" -> {
                    val ledger =
                        report.optJSONObject("transfer_ledger")
                            ?: JSONObject()

                    val record =
                        ledger.optJSONObject(
                            AyanaMultiAppTaskOrchestrator
                                .RESULT_TRANSFER_ACCEPTANCE_KEY
                        )

                    val value =
                        record
                            ?.optString("value")
                            .orEmpty()
                            .ifBlank { "подтверждённый результат" }

                    "Перенос результата между приложениями подтверждён: $passed/$total PASS. " +
                        "Browser app-step подтвердил открытие URL «${value.take(100)}»; это allow-listed значение " +
                        "из verified action-result использовано в поиске YouTube и в несохранённом черновике Календаря. " +
                        "AYANA возвращена после каждого шага; постоянных изменений нет."
                }

                report.optBoolean("generic_result_transfer", false) ->
                    "Универсальная многошаговая передача результата выполнена и подтверждена: $passed/$total шага. " +
                        "Typed transfer edges=${report.optInt("transfer_edge_count", 0)}, " +
                        "verified records=${report.optInt("transfer_count", 0)}; " +
                        "каждый consumer получил только проверенный input, постоянные изменения не выполнялись."

                acceptanceProbe ->
                    "Многошаговая работа приложений подтверждена: $passed/$total PASS. " +
                        "Браузер, YouTube и черновик Календаря выполнены одной задачей; " +
                        "после каждого шага AYANA возвращена на передний план. " +
                        "Событие календаря не сохранялось."

                else ->
                    "Многошаговая задача выполнена и подтверждена: $passed/$total шага. " +
                        "Каждый переход приложения проверен, AYANA возвращена после каждого шага; " +
                        "постоянные изменения не выполнялись."
            }
        } else {
            "Многошаговая задача остановлена: подтверждено $passed/$total, ошибок=$failed, terminal=$terminal. " +
                "AYANA не продолжила выполнение после неподтверждённого шага и не повторяла действие вслепую."
        }
    }

    private fun runLocalAppIntegrationCommand(
        command: String,
        silent: Boolean
    ): Boolean {
        val parsed =
            appIntegrationRegistry
                .parse(command)
                ?: return false

        executionPhase(
            phase = "local_app_integration",
            executor = "app_integration_registry"
        )

        if (
            parsed.actionKey ==
            AyanaAppIntegrationRegistry.ACTION_DESCRIBE
        ) {
            respondAndResume(
                appIntegrationRegistry.describe(parsed.appKey),
                silent,
                success = true,
                technical =
                    "app_integration_registry=${AyanaAppIntegrationRegistry.VERSION}; " +
                        "app=${parsed.appKey}; source=${parsed.source}"
            )
            return true
        }

        val result =
            executeAppIntegrationAction(
                appKey = parsed.appKey,
                actionKey = parsed.actionKey,
                payload = parsed.payload
            )

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "app_integration",
            message =
                "${parsed.appKey}:${parsed.actionKey}",
            details =
                result.toString().take(1600)
        )

        val success =
            result.optBoolean("success", false) &&
                result.optBoolean("verified", false)

        val message =
            result
                .optString("message")
                .ifBlank {
                    if (success) {
                        "Действие приложения выполнено и подтверждено."
} else {
                        "Действие приложения не удалось подтвердить."
                    }
                }

        if (success) {
            finishLocalCommand(
                message,
                silent,
                technical =
                    "app_integration=${parsed.appKey}:${parsed.actionKey}; " +
                        "verified=true; observed=${result.optString("observed_package")}" 
            )
        } else {
            respondAndResume(
                message,
                silent,
                success = false,
                technical =
                    "app_integration=${parsed.appKey}:${parsed.actionKey}; " +
                        "verified=${result.optBoolean("verified", false)}; " +
                        "dispatched=${result.optBoolean("action_dispatched", false)}; " +
                        "observed=${result.optString("observed_package")}"
            )
        }

        return true
    }

    private fun executeAppIntegrationAction(
        appKey: String,
        actionKey: String,
        payload: String = ""
    ): JSONObject {
        val spec =
            appIntegrationRegistry.app(appKey)
                ?: return appIntegrationFailure(
                    appKey = appKey,
                    actionKey = actionKey,
                    message = "Интеграция приложения не зарегистрирована."
                )

        val action =
            appIntegrationRegistry.action(
                appKey,
                actionKey
            )
                ?: return appIntegrationFailure(
                    appKey = appKey,
                    actionKey = actionKey,
                    message = "Действие не зарегистрировано для ${spec.displayName}."
                )

        if (
            !action.autonomousAllowed ||
            action.commitSemantics ==
            AyanaAppIntegrationRegistry.CommitSemantics.MUTATION
        ) {
            return appIntegrationFailure(
                appKey = appKey,
                actionKey = actionKey,
                message = "Это действие не разрешено автономному App Integration v1.0."
            )
                .put("terminal_status", "BLOCKED")
        }

        return when (actionKey) {
            AyanaAppIntegrationRegistry.ACTION_OPEN ->
                launchRegisteredIntegrationApp(spec)

            AyanaAppIntegrationRegistry.ACTION_SEARCH ->
                when (appKey) {
                    AyanaAppIntegrationRegistry.APP_YOUTUBE ->
                        openRegisteredUriAction(
                            spec = spec,
                            actionKey = actionKey,
                            uri =
                                Uri.parse(
                                    "https://www.youtube.com/results?search_query=" +
                                        Uri.encode(payload.trim())
                                ),
                            successMessage =
                                "Открыт и подтверждён поиск YouTube: ${payload.trim()}"
                        )
                            .put(
                                "requested_query",
                                payload.trim().take(240)
                            )

                    AyanaAppIntegrationRegistry.APP_BROWSER ->
                        openRegisteredUriAction(
                            spec = spec,
                            actionKey = actionKey,
                            uri =
                                Uri.parse(
                                    "https://www.google.com/search?q=" +
                                        Uri.encode(payload.trim())
                                ),
                            successMessage =
                                "Открыт и подтверждён веб-поиск: ${payload.trim()}"
                        )
                            .put(
                                "requested_query",
                                payload.trim().take(240)
                            )

                    else ->
                        appIntegrationFailure(
                            appKey = appKey,
                            actionKey = actionKey,
                            message = "Поиск для ${spec.displayName} не зарегистрирован."
                        )
                }

            AyanaAppIntegrationRegistry.ACTION_OPEN_URL -> {
                val target = normalizeAppIntegrationUrl(payload)
                if (target == null) {
                    appIntegrationFailure(
                        appKey = appKey,
                        actionKey = actionKey,
                        message = "Не удалось безопасно разобрать адрес сайта."
                    )
                } else {
                    openRegisteredUriAction(
                        spec = spec,
                        actionKey = actionKey,
                        uri = Uri.parse(target),
                        successMessage = "Сайт открыт и браузер подтверждён."
                    )
                        .put("requested_url", target)
                }
            }

            AyanaAppIntegrationRegistry.ACTION_CREATE_EVENT_DRAFT ->
                openCalendarEventDraft(
                    spec = spec,
                    title = payload.trim()
                )

            else ->
                appIntegrationFailure(
                    appKey = appKey,
                    actionKey = actionKey,
                    message = "Действие App Integration пока не имеет Android executor."
                )
        }
            .put("registry_version", AyanaAppIntegrationRegistry.VERSION)
            .put("app_key", appKey)
            .put("action_key", actionKey)
            .put("commit_semantics", action.commitSemantics.name)
            .put("verification_mode", action.verificationMode.name)
    }

    private fun launchRegisteredIntegrationApp(
        spec: AyanaAppIntegrationRegistry.AppSpec
    ): JSONObject {
        val launch =
            try {
                appResolver.launchWithHints(
                    requestedName = spec.displayName,
                    preferredPackages = spec.preferredPackages
                )
            } catch (error: Exception) {
                JSONObject()
                    .put("success", false)
                    .put(
                        "message",
                        error.message ?: "Ошибка App Resolver"
                    )
            }

        val dispatched =
            launch.optBoolean("success", false)

        val expectedPackage =
            launch.optString("package").trim()

        val observed =
            if (
                dispatched &&
                expectedPackage.isNotBlank()
            ) {
                waitForForegroundPackage(
                    expectedPackage = expectedPackage
                )
            } else {
                currentForegroundPackage()
            }

        val verified =
            dispatched &&
                expectedPackage.isNotBlank() &&
                observed == expectedPackage

        return JSONObject()
            .put("success", verified)
            .put("verified", verified)
            .put("terminal_status", if (verified) "SUCCESS" else "ERROR")
            .put("action_dispatched", dispatched)
            .put("target_package", expectedPackage)
            .put("observed_package", observed)
            .put(
                "resolver_source",
                launch.optString("source")
            )
            .put(
                "message",
                if (verified) {
                    "Открыто и подтверждено приложение ${spec.displayName}."
                } else {
                    "Открытие ${spec.displayName} не удалось подтвердить."
                }
            )
    }

    private fun openRegisteredUriAction(
        spec: AyanaAppIntegrationRegistry.AppSpec,
        actionKey: String,
        uri: Uri,
        successMessage: String
    ): JSONObject {
        val resolution =
            resolveRegisteredIntegrationApp(spec)

        if (!resolution.success) {
            return appIntegrationFailure(
                appKey = spec.key,
                actionKey = actionKey,
                message =
                    "${spec.displayName} не найден среди запускаемых приложений этого устройства."
            )
                .put("resolver_reason", resolution.reason)
        }

        val expectedPackage =
            resolution.packageName.trim()

        var dispatched = false
        var dispatchError = ""

        try {
            startActivity(
                Intent(
                    Intent.ACTION_VIEW,
                    uri
                ).apply {
                    setPackage(expectedPackage)
                    addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                }
            )
            dispatched = true
        } catch (error: Exception) {
            dispatchError =
                error.message
                    ?: error.javaClass.simpleName
        }

        val observed =
            if (dispatched) {
                waitForForegroundPackage(expectedPackage)
            } else {
                currentForegroundPackage()
            }

        val verified =
            dispatched &&
                observed == expectedPackage

        return JSONObject()
            .put("success", verified)
            .put("verified", verified)
            .put("terminal_status", if (verified) "SUCCESS" else "ERROR")
            .put("action_dispatched", dispatched)
            .put("target_package", expectedPackage)
            .put("observed_package", observed)
            .put("uri_scheme", uri.scheme.orEmpty())
            .put("dispatch_error", dispatchError.take(400))
            .put(
                "message",
                if (verified) {
                    successMessage
                } else {
                    "Действие в ${spec.displayName} было отправлено, но foreground не подтверждён."
                }
            )
    }

    private fun openCalendarEventDraft(
        spec: AyanaAppIntegrationRegistry.AppSpec,
        title: String
    ): JSONObject {
        if (title.isBlank()) {
            return appIntegrationFailure(
                appKey = spec.key,
                actionKey = AyanaAppIntegrationRegistry.ACTION_CREATE_EVENT_DRAFT,
                message = "Не указан заголовок события."
            )
        }

        val resolution =
            resolveRegisteredIntegrationApp(spec)

        if (!resolution.success) {
            return appIntegrationFailure(
                appKey = spec.key,
                actionKey = AyanaAppIntegrationRegistry.ACTION_CREATE_EVENT_DRAFT,
                message = "Календарь не найден среди запускаемых приложений устройства."
            )
        }

        val expectedPackage = resolution.packageName.trim()
        var dispatched = false
        var dispatchError = ""

        try {
            startActivity(
                Intent(Intent.ACTION_INSERT).apply {
                    data = CalendarContract.Events.CONTENT_URI
                    setPackage(expectedPackage)
                    putExtra(
                        CalendarContract.Events.TITLE,
                        title.take(240)
                    )
                    addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                }
            )
            dispatched = true
        } catch (error: Exception) {
            dispatchError =
                error.message
                    ?: error.javaClass.simpleName
        }

        val observed =
            if (dispatched) {
                waitForForegroundPackage(expectedPackage)
            } else {
                currentForegroundPackage()
            }

        val verified =
            dispatched &&
                observed == expectedPackage

        return JSONObject()
            .put("success", verified)
            .put("verified", verified)
            .put("terminal_status", if (verified) "SUCCESS" else "ERROR")
            .put("action_dispatched", dispatched)
            .put("action_committed", false)
            .put("draft_only", true)
            .put("requested_title", title.take(240))
            .put("target_package", expectedPackage)
            .put("observed_package", observed)
            .put("dispatch_error", dispatchError.take(400))
            .put(
                "message",
                if (verified) {
                    "Черновик события «${title.take(120)}» открыт в календаре. Событие ещё не сохранено."
                } else {
                    "Не удалось подтвердить открытие черновика события в календаре."
                }
            )
    }

    private fun resolveRegisteredIntegrationApp(
        spec: AyanaAppIntegrationRegistry.AppSpec
    ): AyanaAppResolver.Resolution =
        appResolver.resolveWithHints(
            requestedName = spec.displayName,
            preferredPackages = spec.preferredPackages
        )

    private fun normalizeAppIntegrationUrl(
        raw: String
    ): String? {
        val value = raw.trim()
        if (value.isBlank() || value.contains(" ")) return null

        val candidate =
            if (
                value.startsWith("https://", ignoreCase = true) ||
                value.startsWith("http://", ignoreCase = true)
            ) {
                value
            } else {
                "https://$value"
            }

        val parsed =
            try {
                Uri.parse(candidate)
            } catch (_: Exception) {
                return null
            }

        val scheme = parsed.scheme?.lowercase(Locale.ROOT).orEmpty()
        val host = parsed.host.orEmpty()

        return candidate.takeIf {
            scheme in setOf("http", "https") &&
                host.contains('.') &&
                host.length >= 3
        }
    }

    private fun appIntegrationFailure(
        appKey: String,
        actionKey: String,
        message: String
    ): JSONObject =
        JSONObject()
            .put("success", false)
            .put("verified", false)
            .put("terminal_status", "ERROR")
            .put("action_dispatched", false)
            .put("app_key", appKey)
            .put("action_key", actionKey)
            .put("message", message)

