    private fun appendJsonObjects(
        target: JSONArray,
        source: JSONArray
    ) {
        for (index in 0 until source.length()) {
            source
                .optJSONObject(index)
                ?.let {
                    target.put(
                        JSONObject(
                            it.toString()
                        )
                    )
                }
        }
    }

    private fun finalizeMasterAcceptanceResult(
        base: JSONObject,
        supplemental: JSONArray,
        manual: JSONArray,
        evidenceSweep: JSONObject,
        startedAtMs: Long
    ): JSONObject {
        val tests =
            JSONArray()

        appendJsonObjects(
            tests,
            base.optJSONArray("tests")
                ?: JSONArray()
        )

        appendJsonObjects(
            tests,
            supplemental
        )

        appendJsonObjects(
            tests,
            manual
        )

        var pass = 0
        var warning = 0
        var failed = 0
        var blocked = 0
        var unsupported = 0
        var noData = 0
        var cancelled = 0
        var manualRequired = 0
        var criticalFailures = 0

        for (index in 0 until tests.length()) {
            val item =
                tests.optJSONObject(index)
                    ?: continue

            val status =
                item
                    .optString("status")
                    .uppercase(Locale.ROOT)

            when (status) {
                AyanaAcceptanceTestEngine.STATUS_PASS ->
                    pass += 1

                AyanaAcceptanceTestEngine.STATUS_WARNING ->
                    warning += 1

                AyanaAcceptanceTestEngine.STATUS_FAIL -> {
                    failed += 1
                    if (
                        item.optBoolean(
                            "critical",
                            false
                        )
                    ) {
                        criticalFailures += 1
                    }
                }

                AyanaAcceptanceTestEngine.STATUS_BLOCKED ->
                    blocked += 1

                AyanaAcceptanceTestEngine.STATUS_UNSUPPORTED ->
                    unsupported += 1

                AyanaAcceptanceTestEngine.STATUS_NO_DATA ->
                    noData += 1

                AyanaAcceptanceTestEngine.STATUS_CANCELLED ->
                    cancelled += 1

                MASTER_STATUS_MANUAL_REQUIRED ->
                    manualRequired += 1

                else ->
                    warning += 1
            }
        }

        val automatedGrade =
            when {
                criticalFailures > 0 ||
                    failed > 0 ->
                    AyanaAcceptanceTestEngine
                        .GRADE_NOT_READY

                blocked > 0 ||
                    unsupported > 0 ||
                    noData > 0 ||
                    warning > 0 ->
                    AyanaAcceptanceTestEngine
                        .GRADE_READY_WITH_LIMITATIONS

                else ->
                    AyanaAcceptanceTestEngine
                        .GRADE_READY
            }

        val grade =
            when {
                cancelled > 0 ->
                    AyanaAcceptanceTestEngine
                        .GRADE_CANCELLED

                automatedGrade ==
                    AyanaAcceptanceTestEngine
                        .GRADE_NOT_READY ->
                    automatedGrade

                manualRequired > 0 ->
                    AyanaAcceptanceTestEngine
                        .GRADE_READY_WITH_LIMITATIONS

                else ->
                    automatedGrade
            }

        val finishedAtMs =
            System.currentTimeMillis()

        val executionSuccess =
            base.optBoolean(
                "execution_success",
                false
            ) &&
                cancelled == 0

        val summary =
            "MASTER FULL ACCEPTANCE завершён: PASS $pass, WARNING $warning, FAIL $failed, " +
                "BLOCKED $blocked, UNSUPPORTED $unsupported, NO_DATA $noData, " +
                "MANUAL_REQUIRED $manualRequired. Automated grade=$automatedGrade; overall grade=$grade."

        return JSONObject(
            base.toString()
        )
            .put("success", executionSuccess)
            .put(
                "execution_success",
                executionSuccess
            )
            .put(
                "engine",
                "AyanaMasterFullAcceptance"
)
            .put(
                "engine_version",
                MASTER_ACCEPTANCE_VERSION
            )
            .put(
                "base_engine",
                base.optString(
                    "engine",
                    "AyanaAcceptanceTestEngine"
                )
            )
            .put(
                "base_engine_version",
                base.optString(
                    "engine_version",
                    AyanaAcceptanceTestEngine.ENGINE_VERSION
                )
            )
            .put(
                "mode",
                MASTER_ACCEPTANCE_MODE
            )
            .put(
                "accepted_baseline",
                AYANA_ACCEPTED_FEATURE_CHECKPOINT
            )
            .put(
                "current_release",
                AYANA_CURRENT_FEATURE_RELEASE
            )
            .put("started_at_ms", startedAtMs)
            .put("finished_at_ms", finishedAtMs)
            .put(
                "duration_ms",
                (
                    finishedAtMs -
                        startedAtMs
                    ).coerceAtLeast(0L)
            )
            .put("tests", tests)
            .put(
                "tests_requested",
                tests.length()
            )
            .put(
                "tests_completed",
                tests.length()
            )
            .put(
                "baseline_tests_requested",
                base.optInt(
                    "baseline_tests_requested",
                    base.optInt(
                        "tests_requested",
                        0
                    )
                )
            )
            .put(
                "adaptive_tests_generated",
                base.optInt(
                    "adaptive_tests_generated",
                    0
                )
            )
            .put(
                "master_supplemental_tests",
                supplemental.length()
            )
            .put(
                "manual_required",
                manualRequired
            )
            .put(
                "automated_tests_completed",
                tests.length() -
                    manualRequired
            )
            .put("passed", pass)
            .put("warnings", warning)
            .put("failed", failed)
            .put("blocked", blocked)
            .put("unsupported", unsupported)
            .put("no_data", noData)
            .put("cancelled", cancelled)
            .put(
                "critical_failures",
                criticalFailures
            )
            .put(
                "automated_grade",
                automatedGrade
            )
            .put("grade", grade)
            .put(
                "device_evidence_sweep",
                evidenceSweep
            )
            .put(
                "master_external_device_scenarios",
                supplemental.length()
            )
            .put(
                "summary",
                summary
            )
            .put(
                "voice_summary",
                summary
            )
    }

    private fun runLocalMasterFullAcceptanceCommand(
        silent: Boolean
    ) {
        executionPhase(
            phase = "master_full_acceptance",
            executor = "master_acceptance_engine"
        )

        broadcastStatus(
            "Провожу MASTER FULL ACCEPTANCE: базовая диагностика и реальные device-сценарии…",
            STATE_EXECUTING
        )

        val startedAtMs =
            System.currentTimeMillis()

        val commandToken =
            activeCommandToken

        val originalPage =
            currentAyanaPageKeyForAppIntegrationProbe()

        val evidenceSweep =
            try {
                runCapabilityProofSweep()
            } catch (error: Exception) {
                JSONObject()
                    .put(
                        "version",
                        "master-fallback"
                    )
                    .put(
                        "error",
                        error.message
                            ?: error.javaClass.simpleName
                    )
            }

        val base =
            try {
                acceptanceTestEngine.run(
                    AyanaAcceptanceTestEngine
                        .Mode
                        .EXHAUSTIVE_ACCEPTANCE
                )
            } catch (error: Exception) {
                JSONObject()
                    .put("success", false)
                    .put(
                        "execution_success",
                        false
                    )
                    .put(
                        "engine",
                        "AyanaAcceptanceTestEngine"
                    )
                    .put(
                        "engine_version",
                        AyanaAcceptanceTestEngine
                            .ENGINE_VERSION
                    )
                    .put(
                        "mode",
                        AyanaAcceptanceTestEngine
                            .Mode
                            .EXHAUSTIVE_ACCEPTANCE
                            .wireName
                    )
                    .put(
                        "grade",
                        AyanaAcceptanceTestEngine
                            .GRADE_NOT_READY
                    )
                    .put("tests", JSONArray())
                    .put("known_limits", JSONArray())
                    .put(
                        "summary",
                        "Базовая exhaustive acceptance не завершена: ${error.message ?: error.javaClass.simpleName}"
                    )
            }

        if (
            base.optBoolean(
                "execution_success",
                false
            )
        ) {
            reconcileAcceptancePostProbeRuntimeTruth(
                base
            )
        }

        val supplemental =
            JSONArray()

        fun addScenario(
            test: JSONObject
        ) {
            supplemental.put(test)

            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "master_acceptance_scenario",
                message =
                    "${test.optString("id")}: ${test.optString("status")}",
                details =
                    (
                        "title=${test.optString("title")}; " +
                            "duration_ms=${test.optLong("duration_ms", 0L)}; " +
                            "message=${test.optString("message").take(500)}"
                        ).take(1000)
            )
        }

        if (
            base.optBoolean(
                "execution_success",
                false
            ) &&
            !isCommandCancelled(commandToken) &&
            commandToken == activeCommandToken
        ) {
            addScenario(
                runMasterAppIntegrationDeviceScenario(
                    commandToken = commandToken,
                    originalPage = originalPage
                )
            )

            addScenario(
                runMasterMultiAppScenario(
                    id = "MASTER-R94-001",
                    title = "R9.4 verified multi-app orchestration regression",
                    command =
                        "проверь многошаговую работу приложений",
                    expectedPlanKey =
                        "r9.4-device-acceptance",
                    commandToken = commandToken,
                    originalPage = originalPage
                )
            )

            addScenario(
                runMasterMultiAppScenario(
                    id = "MASTER-R95-001",
                    title = "R9.5 verified action-result transfer regression",
                    command =
                        "проверь перенос результата между приложениями",
                    expectedPlanKey =
                        "r9.5-result-transfer-device-acceptance",
                    commandToken = commandToken,
                    originalPage = originalPage,
                    requiredTransferCount = 1
                )
            )

            addScenario(
                runMasterMultiAppScenario(
                    id = "MASTER-R96-001",
                    title = "R9.6.1 exact-marker visual provenance regression",
                    command =
                        "проверь семантическое чтение внешнего экрана",
                    expectedPlanKey =
                        "r9.6-semantic-fallback-device-acceptance",
                    commandToken = commandToken,
                    originalPage = originalPage,
                    requiredTransferCount = 1,
                    requireVisualScreenshotProvenance = true
                )
            )

            addScenario(
                runMasterStructuredScreenScenario(
                    commandToken = commandToken,
                    originalPage = originalPage
                )
            )

            addScenario(
                runMasterMultiAppScenario(
                    id = "MASTER-R98-001",
                    title = "R9.8 generic typed result-transfer regression",
                    command =
                        "проверь универсальный перенос результатов между приложениями",
                    expectedPlanKey =
                        "r9.8-generic-result-transfer-device-acceptance",
                    commandToken = commandToken,
                    originalPage = originalPage,
                    requiredTransferCount = 2,
                    requireGenericTransfer = true
                )
            )
        }

        val manual =
            masterManualRequiredTests()

        val result =
            finalizeMasterAcceptanceResult(
                base = base,
                supplemental = supplemental,
                manual = manual,
                evidenceSweep = evidenceSweep,
                startedAtMs = startedAtMs
            )

        try {
            capabilityRegistry
                .recordAcceptanceResult(
                    mode = MASTER_ACCEPTANCE_MODE,
                    grade =
                        result.optString(
                            "grade",
                            AyanaAcceptanceTestEngine
                                .GRADE_NOT_READY
                        ),
                    passed =
                        result.optInt(
                            "passed",
                            0
                        ),
                    warnings =
                        result.optInt(
                            "warnings",
                            0
                        ),
                    failed =
                        result.optInt(
                            "failed",
                            0
                        ),
                    blocked =
                        result.optInt(
                            "blocked",
                            0
                        ),
                    unsupported =
                        result.optInt(
                            "unsupported",
                            0
                        ),
                    noData =
                        result.optInt(
                            "no_data",
                            0
                        ),
                    durationMs =
                        result.optLong(
                            "duration_ms",
                            0L
                        ),
                    executionSuccess =
                        result.optBoolean(
                            "execution_success",
                            false
                        )
                )
        } catch (_: Exception) {
        }

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "master_acceptance_result",
            message =
                "R9.8.1 MASTER: ${result.optString("grade", "UNKNOWN")}",
            details =
                (
                    "pass=${result.optInt("passed")}; " +
                        "warning=${result.optInt("warnings")}; " +
                        "fail=${result.optInt("failed")}; " +
                        "blocked=${result.optInt("blocked")}; " +
                        "unsupported=${result.optInt("unsupported")}; " +
                        "no_data=${result.optInt("no_data")}; " +
                        "manual_required=${result.optInt("manual_required")}; " +
                        "tests=${result.optInt("tests_completed")}; " +
                        "duration_ms=${result.optLong("duration_ms")}"
                    ).take(1200)
        )

        if (
            !result.optBoolean(
                "execution_success",
                false
            )
        ) {
            respondAndResume(
                text =
                    result.optString(
                        "summary",
                        "MASTER FULL ACCEPTANCE не завершён."
                    ),
                silent = silent,
                success = false,
                technical =
                    "master_acceptance_execution_failed; " +
                        "grade=${result.optString("grade")}; " +
                        "tests=${result.optInt("tests_completed", 0)}"
            )
            return
        }

        executionPhase(
            phase = "master_acceptance_report_publish",
            executor = "artifact_engine"
        )

        val reportText =
            try {
                buildAcceptanceDetailedReport(
                    result
                )
            } catch (error: Exception) {
                respondAndResume(
                    text =
                        result.optString("summary") +
                            "\n\nТесты выполнены, но MASTER TXT-отчёт сформировать не удалось.",
                    silent = silent,
                    success = false,
                    technical =
"master_acceptance_report_build_failed:" +
                            (
                                error.message
                                    ?: error.javaClass.simpleName
                                ).take(500)
                )
                return
            }

        val filename =
            "AYANA_MASTER_FULL_ACCEPTANCE_" +
                DateTimeFormatter
                    .ofPattern(
                        "yyyy-MM-dd_HHmmss"
                    )
                    .format(
                        LocalDateTime.now()
                    ) +
                ".txt"

        val published =
            try {
                artifactEngine.create(
                    arguments =
                        JSONObject()
                            .put("kind", "txt")
                            .put(
                                "filename",
                                filename
                            )
                            .put(
                                "title",
                                "AYANA Master Full Acceptance"
                            )
                            .put(
                                "content",
                                reportText
                            )
                            .put(
                                "columns",
                                JSONArray()
                            )
                            .put(
                                "rows",
                                JSONArray()
                            )
                            .put(
                                "column_types",
                                JSONArray()
                            )
                            .put(
                                "chart_type",
                                "none"
                            ),
                    tryBeginPublish = { detail ->
                        executionKernel
                            .tryBeginIrreversibleDispatch(
                                kind =
                                    "master_acceptance_report_publish",
                                detail = detail
                            )
                    },
                    onPublishAccepted = { detail ->
                        executionKernel
                            .markIrreversibleDispatchAccepted(
                                detail
                            )
                    },
                    onPublishReconciliationStarted = { detail ->
                        executionKernel
                            .markSideEffectReconciliationStarted(
                                detail
                            )
                    },
                    onPublishReconciled = { committed, detail ->
                        executionKernel
                            .markSideEffectReconciled(
                                committed = committed,
                                detail = detail
                            )
                    }
                )
            } catch (error: Exception) {
                JSONObject()
                    .put("success", false)
                    .put("verified", false)
                    .put(
                        "message",
                        error.message
                            ?: error.javaClass.simpleName
                    )
            }

        val reportVerified =
            published.optBoolean(
                "success",
                false
            ) &&
                published
                    .optString(
                        "artifact_reference"
                    )
                    .isNotBlank()

        if (!reportVerified) {
            respondAndResume(
                text =
                    result.optString("summary") +
                        "\n\nMASTER FULL ACCEPTANCE выполнен, но сохранение TXT-отчёта не подтверждено.",
                silent = silent,
                success = false,
                technical =
                    "master_acceptance_report_publish_unverified:" +
                        published.toString().take(1000)
            )
            return
        }

        val finalName =
            published
                .optString(
                    "name",
                    filename
                )
                .ifBlank {
                    filename
                }

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "master_acceptance_report_verified",
            message = "MASTER FULL ACCEPTANCE TXT создан и подтверждён",
            details =
                (
                    "name=$finalName; grade=${result.optString("grade")}; " +
                        "tests=${result.optInt("tests_completed")}; " +
                        "manual_required=${result.optInt("manual_required")}"
                    ).take(1000)
        )

        finishLocalCommand(
            result.optString("summary") +
                "\n\nПодробный MASTER TXT-отчёт сохранён в Downloads/AYANA: $finalName",
            silent
        )
    }

    private fun runLocalAcceptanceTestCommand(
        mode: AyanaAcceptanceTestEngine.Mode,
        silent: Boolean
    ) {
        executionPhase(
            phase = "local_acceptance_test",
            executor = "acceptance_test_executor"
        )

        broadcastStatus(
            when (mode) {
                AyanaAcceptanceTestEngine.Mode.QUICK_HEALTH ->
                    "Провожу быструю локальную проверку…"

                AyanaAcceptanceTestEngine.Mode.CAPABILITY_AUDIT ->
                    "Проверяю возможности сборки…"

                AyanaAcceptanceTestEngine.Mode.FULL_ACCEPTANCE ->
                    "Провожу локальный acceptance-test AYANA…"

                AyanaAcceptanceTestEngine.Mode.EXHAUSTIVE_ACCEPTANCE ->
                    "Провожу базовые и самонаправленные тесты AYANA…"
            },
            STATE_EXECUTING
        )

        val evidenceSweep =
            if (
                mode == AyanaAcceptanceTestEngine.Mode.FULL_ACCEPTANCE ||
                mode == AyanaAcceptanceTestEngine.Mode.EXHAUSTIVE_ACCEPTANCE
            ) {
                runCapabilityProofSweep()
            } else {
                JSONObject()
                    .put("version", "1.0")
                    .put("requested", 0)
                    .put("pending_before", 0)
                    .put("confirmed_now", 0)
                    .put("failed_now", 0)
                    .put("skipped_already_confirmed", 0)
                    .put("duration_ms", 0L)
                    .put("results", JSONArray())
            }

        val result =
            try {
                acceptanceTestEngine.run(mode)
            } catch (error: Exception) {
                JSONObject()
                    .put("success", false)
                    .put("execution_success", false)
                    .put("engine", "AyanaAcceptanceTestEngine")
                    .put("engine_version", AyanaAcceptanceTestEngine.ENGINE_VERSION)
                    .put("mode", mode.wireName)
                    .put("grade", AyanaAcceptanceTestEngine.GRADE_NOT_READY)
                    .put("passed", 0)
                    .put("warnings", 0)
                    .put("failed", 1)
                    .put("blocked", 0)
                    .put("unsupported", 0)
                    .put("no_data", 0)
                    .put("cancelled", 0)
                    .put("critical_failures", 1)
                    .put("network_turns", 0)
                    .put("duration_ms", 0L)
                    .put("tests", JSONArray())
                    .put("known_limits", JSONArray())
                    .put(
                        "summary",
                        "Локальный acceptance-test не завершён: ${error.message ?: error.javaClass.simpleName}"
                    )
            }

        if (
            mode == AyanaAcceptanceTestEngine.Mode.FULL_ACCEPTANCE ||
            mode == AyanaAcceptanceTestEngine.Mode.EXHAUSTIVE_ACCEPTANCE
        ) {
            reconcileAcceptancePostProbeRuntimeTruth(
                result
            )
        }

        result.put(
            "device_evidence_sweep",
            evidenceSweep
        )

        try {
            capabilityRegistry.recordAcceptanceResult(
                mode = mode.wireName,
                grade = result.optString("grade", AyanaAcceptanceTestEngine.GRADE_NOT_READY),
                passed = result.optInt("passed", 0),
                warnings = result.optInt("warnings", 0),
                failed = result.optInt("failed", 0),
                blocked = result.optInt("blocked", 0),
                unsupported = result.optInt("unsupported", 0),
                noData = result.optInt("no_data", 0),
                durationMs = result.optLong("duration_ms", 0L),
                executionSuccess = result.optBoolean("execution_success", false)
            )
        } catch (_: Exception) {
        }

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "acceptance_test_result",
            message =
                "${mode.wireName}: ${result.optString("grade", "UNKNOWN")}",
            details =
                (
                    "engine=${result.optString("engine_version", AyanaAcceptanceTestEngine.ENGINE_VERSION)}; " +
                        "pass=${result.optInt("passed")}; " +
                        "warning=${result.optInt("warnings")}; " +
                        "fail=${result.optInt("failed")}; " +
                        "blocked=${result.optInt("blocked")}; " +
                        "unsupported=${result.optInt("unsupported")}; " +
                        "no_data=${result.optInt("no_data")}; " +
                        "duration_ms=${result.optLong("duration_ms")}; " +
                        "network_turns=${result.optInt("network_turns", 0)}; " +
                        "baseline_tests=${result.optInt("baseline_tests_requested", result.optInt("tests_requested", 0))}; " +
                        "adaptive_tests=${result.optInt("adaptive_tests_generated", 0)}; " +
                        "evidence_sweep_confirmed=${evidenceSweep.optInt("confirmed_now", 0)}; " +
                        "evidence_sweep_failed=${evidenceSweep.optInt("failed_now", 0)}; " +
                        "evidence_sweep_pending_before=${evidenceSweep.optInt("pending_before", 0)}"
                    ).take(1200)
        )

        val baseSummary =
            result
                .optString(
                    if (silent) {
                        "summary"
                    } else {
                        "voice_summary"
                    }
                )
                .ifBlank {
                    result.optString("summary")
                }
                .ifBlank {
                    "Локальная проверка завершена, но итоговый отчёт не сформирован."
                }

        if (!result.optBoolean("execution_success", false)) {
            respondAndResume(
                text = baseSummary,
                silent = silent,
                success = false,
                technical = "acceptance_test_execution_failed:${mode.wireName}"
            )
            return
        }

        // FULL_ACCEPTANCE owns the user-requested end-to-end diagnostic artifact.
        // The suite result may legitimately be NOT_READY while this command itself
        // still succeeds: SUCCESS here means "tests executed and verified report saved".
        if (
            mode == AyanaAcceptanceTestEngine.Mode.FULL_ACCEPTANCE ||
            mode == AyanaAcceptanceTestEngine.Mode.EXHAUSTIVE_ACCEPTANCE
        ) {
            executionPhase(
                phase = "acceptance_report_publish",
                executor = "artifact_engine"
            )

            val reportText =
                try {
                    buildAcceptanceDetailedReport(result)
                } catch (error: Exception) {
                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state = "acceptance_report_failed",
                        message = "Не удалось сформировать TXT-отчёт диагностики",
                        details = (error.message ?: error.javaClass.simpleName).take(600)
                    )

                    respondAndResume(
                        text =
                            "$baseSummary\n\nТесты выполнены, но TXT-отчёт сформировать не удалось.",
                        silent = silent,
                        success = false,
                        technical = "acceptance_report_build_failed"
                    )
                    return
                }

            val filename =
                (
                    if (mode == AyanaAcceptanceTestEngine.Mode.EXHAUSTIVE_ACCEPTANCE) {
                        "AYANA_EXHAUSTIVE_DIAGNOSTICS_"
                    } else {
                        "AYANA_FULL_DIAGNOSTICS_"
                    }
                    ) +
                    DateTimeFormatter
                        .ofPattern("yyyy-MM-dd_HHmmss")
                        .format(LocalDateTime.now()) +
                    ".txt"

            val artifactArguments =
                JSONObject()
                    .put("kind", "txt")
                    .put("filename", filename)
                    .put(
                        "title",
                        if (mode == AyanaAcceptanceTestEngine.Mode.EXHAUSTIVE_ACCEPTANCE) {
                            "AYANA Exhaustive Autonomous Diagnostics"
                        } else {
                            "AYANA Full Diagnostics"
                        }
                    )
                    .put("content", reportText)
                    .put("columns", JSONArray())
                    .put("rows", JSONArray())
                    .put("column_types", JSONArray())
                    .put("chart_type", "none")

            val published =
                try {
                    artifactEngine.create(
                        arguments = artifactArguments,
                        tryBeginPublish = { detail ->
                            executionKernel.tryBeginIrreversibleDispatch(
                                kind = "acceptance_report_publish",
                                detail = detail
                            )
                        },
                        onPublishAccepted = { detail ->
                            executionKernel.markIrreversibleDispatchAccepted(
                                detail
                            )
                        },
                        onPublishReconciliationStarted = { detail ->
                            executionKernel.markSideEffectReconciliationStarted(
                                detail
                            )
                        },
                        onPublishReconciled = { committed, detail ->
                            executionKernel.markSideEffectReconciled(
                                committed = committed,
                                detail = detail
                            )
                        }
                    )
                } catch (error: Exception) {
                    JSONObject()
                        .put("success", false)
                        .put("verified", false)
                        .put("message", error.message ?: error.javaClass.simpleName)
                }

            val reportVerified =
                published.optBoolean("success", false) &&
                    published.optString("artifact_reference").isNotBlank()

            if (!reportVerified) {
                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "acceptance_report_failed",
                    message = "Полная диагностика выполнена, но TXT-отчёт не подтверждён",
                    details = published.toString().take(1800)
                )

                respondAndResume(
                    text =
                        "$baseSummary\n\nТесты выполнены, но сохранение итогового TXT-отчёта не подтверждено.",
                    silent = silent,
                    success = false,
                    technical =
                        "acceptance_report_publish_unverified:" +
                            published.toString().take(1200)
                )
                return
            }

            val finalName =
                published
                    .optString("name", filename)
                    .ifBlank { filename }

            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "acceptance_report_verified",
                message = "TXT-отчёт полной диагностики создан и проверен",
                details =
                    (
                        "name=$finalName; " +
                            "artifact_reference=${published.optString("artifact_reference").take(600)}; " +
                            "grade=${result.optString("grade")}; " +
                            "tests=${result.optInt("tests_completed", 0)}"
                        ).take(1200)
            )

            finishLocalCommand(
                "$baseSummary\n\nПодробный TXT-отчёт сохранён в Downloads/AYANA: $finalName",
                silent
            )
            return
        }

        finishLocalCommand(
            baseSummary,
            silent
        )
    }

    /**
     * v12.16 diagnostic artifact renderer.
     *
     * It renders only the exact statuses/evidence returned by AyanaAcceptanceTestEngine;
     * it never re-grades a test. This keeps the acceptance engine as the single source
     * of PASS/FAIL truth while allowing the service to persist a human-readable TXT
     * without requiring a parallel Agent Core turn.
     */
    /**
     * R9.0.3 post-probe truth reconciliation.
     *
     * HEALTH-001 is intentionally executed near the beginning of the baseline suite,
     * while ONLINE-001..003 execute later. Those online probes use the isolated
     * acceptance transport and therefore historically did not refresh Capability
     * Registry Agent Core health. R9.3.3 closes that temporal gap when ONLINE-001
     * plus one additional independent online probe are verified PASS. It never invents
     * PASS from reachability alone and never rewrites a failed specialized online probe.
     */
    private fun reconcileAcceptancePostProbeRuntimeTruth(
        result: JSONObject
    ) {
        val tests =
            result.optJSONArray("tests")
                ?: return

        fun testById(
            id: String
        ): JSONObject? {
            for (index in 0 until tests.length()) {
                val item =
                    tests.optJSONObject(index)
                        ?: continue

                if (item.optString("id") == id) {
                    return item
                }
            }

            return null
        }

        val onlineIds =
            listOf(
                "ONLINE-001",
                "ONLINE-002",
                "ONLINE-003"
            )

        val onlineRows =
            onlineIds.mapNotNull {
                testById(it)
            }

        val verifiedOnlineRows =
            onlineRows.filter { row ->
                row.optString("status") ==
                    AyanaAcceptanceTestEngine.STATUS_PASS &&
                    row.optBoolean("verified", false)
            }

        val ordinaryOnlinePassed =
            testById("ONLINE-001")
                ?.let { row ->
                    row.optString("status") ==
                        AyanaAcceptanceTestEngine.STATUS_PASS &&
                        row.optBoolean("verified", false)
                } ==
                true

        // R9.3.3: health freshness is about live Agent Core availability, not
        // whether every specialized online contract passed. Require ONLINE-001
        // plus one additional independent verified online success. A real
        // specialized FAIL remains visible in its own row and is never rewritten.
        val enoughLiveAgentCoreProof =
            ordinaryOnlinePassed &&
                verifiedOnlineRows.size >=
                2

        if (!enoughLiveAgentCoreProof) {
            return
        }

        val ordinaryElapsedMs =
            testById("ONLINE-001")
                ?.optJSONObject("evidence")
                ?.optLong("elapsed_ms", 0L)
                ?.coerceAtLeast(0L)
                ?: 0L

        try {
            capabilityRegistry.recordAgentCoreResult(
                success = true,
                latencyMs = ordinaryElapsedMs
            )
        } catch (_: Exception) {
            return
        }

        val reconciledAt =
            System.currentTimeMillis()

        fun mergeProbeIntoExistingRow(
            id: String,
            probe: JSONObject
        ) {
            val row =
                testById(id)
                    ?: return

            row
                .put(
                    "status",
                    probe.optString(
                        "status",
                        row.optString("status")
)
                )
                .put(
                    "verified",
                    probe.optBoolean(
                        "verified",
                        row.optBoolean("verified", false)
                    )
                )
                .put(
                    "message",
                    probe.optString(
                        "message",
                        row.optString("message")
                    )
                )
                .put(
                    "evidence_scope",
                    probe.optString(
                        "evidence_scope",
                        row.optString("evidence_scope")
                    )
                )

            val evidence =
                probe.optJSONObject("evidence")
                    ?: JSONObject()

            evidence
                .put("post_probe_reconciled", true)
                .put("agent_core_live_probe_passes", verifiedOnlineRows.size)
                .put("agent_core_reconciled_at_ms", reconciledAt)
                .put("agent_core_reconciled_latency_ms", ordinaryElapsedMs)

            row.put(
                "evidence",
                evidence
            )
        }

        val recoveryEvidence =
            JSONObject()
                .put(
                    "agent_core_verified_successes",
                    verifiedOnlineRows.size
                )
                .put(
                    "agent_core_verified_at",
                    reconciledAt
                )

        // R9.0.3: HEALTH-001 is measured before ONLINE/TTS probes. If Marin is
        // UNKNOWN only because its previous measurement is stale, perform a tiny
        // production /tts round-trip without AudioTrack playback, persist that live
        // result, then re-run the diagnostic presentation probes. This proves the
        // actual Worker voice contract (Marin/profile/speed + first PCM bytes) and
        // does not infer TTS health from generic network reachability.
        val ttsFreshnessNeeded =
            acceptanceHealthNeedsFreshTts(
                testById("HEALTH-001")
            )

        val ttsProof =
            if (ttsFreshnessNeeded) {
                runAcceptanceTtsFreshnessProof()
            } else {
                JSONObject()
                    .put("attempted", false)
                    .put("success", true)
                    .put("reason", "fresh_tts_measurement_already_present")
            }

        if (ttsFreshnessNeeded) {
            result.put(
                "network_turns",
                result.optInt("network_turns", 0) + 1
            )

            result.put(
                "duration_ms",
                result.optLong("duration_ms", 0L) +
                    ttsProof.optLong("elapsed_ms", 0L)
            )
        }

        // Re-run only the two diagnostic presentation probes after fresh, verified
        // Agent Core evidence and optional live Marin evidence have been persisted.
        // DiagnosticClosure v1.1 receives Agent Core recovery evidence separately,
        // so it can close a matching historical network incident without pretending
        // acceptance probes were user commands.
        mergeProbeIntoExistingRow(
            "HEALTH-001",
            acceptanceDiagnosticsProbe(
                recoveryEvidence = recoveryEvidence
            )
        )

        mergeProbeIntoExistingRow(
            "EXT-001",
            acceptanceDiagnosticsDetailProbe(
                recoveryEvidence = recoveryEvidence
            )
        )

        testById("HEALTH-001")
            ?.optJSONObject("evidence")
            ?.apply {
                put(
                    "tts_live_probe_attempted",
                    ttsProof.optBoolean("attempted", false)
                )
                put(
                    "tts_live_probe_success",
                    ttsProof.optBoolean("success", false)
                )
                put(
                    "tts_live_probe_http_code",
                    ttsProof.optInt("http_code", -1)
                )
                put(
                    "tts_live_probe_first_byte_ms",
                    ttsProof.optLong("first_byte_ms", -1L)
                )
                put(
                    "tts_live_probe_bytes_observed",
                    ttsProof.optInt("bytes_observed", 0)
                )
                put(
                    "tts_live_probe_voice_contract_verified",
                    ttsProof.optBoolean(
                        "voice_contract_verified",
                        false
                    )
                )
                put(
                    "tts_live_probe_error",
                    ttsProof.optString("error")
                )
            }

        result
            .put("post_probe_health_reconciled", true)
            .put("post_probe_agent_core_passes", verifiedOnlineRows.size)
            .put("post_probe_agent_core_reconciled_at_ms", reconciledAt)
            .put(
                "post_probe_tts_reconciliation_attempted",
                ttsProof.optBoolean("attempted", false)
            )
            .put(
                "post_probe_tts_reconciliation_success",
                ttsProof.optBoolean("success", false)
            )
            .put(
                "post_probe_tts_first_byte_ms",
                ttsProof.optLong("first_byte_ms", -1L)
            )

        // R9.2.1: Adaptive hypotheses are generated before the post-probe
        // Agent Core/TTS reconciliation. If a baseline non-PASS row becomes PASS
        // after fresh evidence, remove only that now-stale follow-up hypothesis.
        // Other adaptive hypotheses and historical anomalies remain untouched.
        reconcileAdaptiveHypothesesAgainstFinalTests(
            result
        )

        recalculateAcceptanceOutcomeAfterReconciliation(
            result
        )

        // MainActivity's HOME health cards are render-time snapshots. Re-dispatch the
        // current internal page so freshly persisted Agent Core / Marin results become
        // visible without requiring the user to navigate away and back manually.
        refreshCurrentOwnAppPageForRuntimeTruth()
    }

    private fun reconcileAdaptiveHypothesesAgainstFinalTests(
        result: JSONObject
    ) {
        val hypotheses =
            result.optJSONArray("adaptive_hypotheses")
                ?: return

        val tests =
            result.optJSONArray("tests")
                ?: return

        val finalStatuses =
            mutableMapOf<String, String>()

        for (index in 0 until tests.length()) {
            val item =
                tests.optJSONObject(index)
                    ?: continue

            val id =
                item.optString("id")
                    .trim()

            if (id.isNotBlank()) {
                finalStatuses[id] =
                    item.optString("status")
            }
        }

        val reconciled =
            JSONArray()

        var removed =
            0

        for (index in 0 until hypotheses.length()) {
            val item =
                hypotheses.optJSONObject(index)
                    ?: continue

            val staleBaselineFollowUp =
                item.optString("kind") ==
                    "baseline_non_pass_follow_up" &&
                    finalStatuses[
                        item.optString("source_test_id")
                    ] ==
                    AyanaAcceptanceTestEngine.STATUS_PASS

            if (staleBaselineFollowUp) {
                removed++
                continue
            }

            reconciled.put(
                JSONObject(
                    item.toString()
                )
            )
        }

        result
            .put(
                "adaptive_hypotheses",
                reconciled
            )
            .put(
                "adaptive_hypotheses_reconciled",
                true
            )
            .put(
                "adaptive_hypotheses_removed_after_reconciliation",
                removed
            )

        result
            .optJSONObject(
                "adaptive_coverage"
            )
            ?.apply {
                put(
                    "hypotheses_generated",
                    reconciled.length()
                )
                put(
                    "hypotheses_reconciled_removed",
                    removed
                )
            }
    }

    private fun acceptanceHealthNeedsFreshTts(
        healthRow: JSONObject?
    ): Boolean {
        val nonPass =
            healthRow
                ?.optJSONObject("evidence")
                ?.optJSONArray("non_pass_checks")
                ?: return false

        for (index in 0 until nonPass.length()) {
            val item =
                nonPass.optJSONObject(index)
                    ?: continue

            if (
                item.optString("id") == "tts" &&
                item.optString("status") ==
                    AyanaDiagnosticClosure.STATUS_UNKNOWN
            ) {
                return true
            }
        }

        return false
    }

    private fun runAcceptanceTtsFreshnessProof(): JSONObject {
        val startedAt =
            SystemClock.elapsedRealtime()

        var connection:
            HttpsURLConnection? = null

        var httpCode =
            -1

        var firstByteMs =
            -1L

        var bytesObserved =
            0

        var voiceContractVerified =
            false

        return try {
            connection =
                URL(
                    "$WORKER_URL/tts"
                )
                    .openConnection()
                    as HttpsURLConnection

            executionKernel.bindConnection(
                connection
            )

            connection.requestMethod =
                "POST"

            connection.setRequestProperty(
                "Content-Type",
                "application/json"
            )

            connection.setRequestProperty(
                "Accept",
                "application/octet-stream"
            )

            connection.connectTimeout =
                TTS_CONNECT_TIMEOUT_MS

            connection.readTimeout =
                TTS_READ_TIMEOUT_MS

            connection.doOutput =
                true

            val requestJson =
                JSONObject()
                    .put(
                        "text",
                        "Да."
                    )
                    .put(
                        "format",
                        "pcm"
                    )
                    .put(
                        "voice_profile",
                        TTS_VOICE_PROFILE
                    )

            val requestBytes =
                requestJson
                    .toString()
                    .toByteArray(
                        Charsets.UTF_8
                    )

            connection.setFixedLengthStreamingMode(
                requestBytes.size
            )

            connection.outputStream
                .use { output ->
                    output.write(
                        requestBytes
                    )
                }

            httpCode =
                connection.responseCode

            if (httpCode !in 200..299) {
                val body =
                    try {
                        connection.errorStream
                            ?.bufferedReader()
                            ?.use {
                                it.readText()
                            }
                            .orEmpty()
                            .take(400)
                    } catch (_: Exception) {
                        ""
                    }

                throw IllegalStateException(
                    "TTS HTTP $httpCode ${body.trim()}"
                        .trim()
                )
            }

            verifyTtsVoiceContract(
                connection
            )

            voiceContractVerified =
                true

            connection.inputStream
                .use { input ->
                    val buffer =
                        ByteArray(
                            512
                        )

                    val read =
                        input.read(
                            buffer
                        )

                    if (read <= 0) {
                        throw IllegalStateException(
                            "TTS PCM health probe was empty"
                        )
                    }

                    bytesObserved =
                        read

                    firstByteMs =
                        (
                            SystemClock.elapsedRealtime() -
                                startedAt
)
                            .coerceAtLeast(0L)
                }

            capabilityRegistry.recordTtsResult(
                success = true,
                firstByteMs = firstByteMs,
                error = ""
            )

            JSONObject()
                .put("attempted", true)
                .put("success", true)
                .put("http_code", httpCode)
                .put("first_byte_ms", firstByteMs)
                .put("bytes_observed", bytesObserved)
                .put(
                    "voice_contract_verified",
                    voiceContractVerified
                )
                .put(
                    "elapsed_ms",
                    (
                        SystemClock.elapsedRealtime() -
                            startedAt
                        )
                        .coerceAtLeast(0L)
                )
                .put("error", "")
        } catch (error: Exception) {
            val technical =
                ttsTechnicalError(
                    error
                )

            try {
                capabilityRegistry.recordTtsResult(
                    success = false,
                    firstByteMs = firstByteMs,
                    error = technical
                )
            } catch (_: Exception) {
            }

            JSONObject()
                .put("attempted", true)
                .put("success", false)
                .put("http_code", httpCode)
                .put("first_byte_ms", firstByteMs)
                .put("bytes_observed", bytesObserved)
                .put(
                    "voice_contract_verified",
                    voiceContractVerified
                )
                .put(
                    "elapsed_ms",
                    (
                        SystemClock.elapsedRealtime() -
                            startedAt
                        )
                        .coerceAtLeast(0L)
                )
                .put(
                    "error",
                    technical.take(600)
                )
        } finally {
            connection
                ?.let {
                    executionKernel.clearConnection(
                        it
                    )
                }

            try {
                connection?.disconnect()
            } catch (_: Exception) {
            }
        }
    }

    private fun recalculateAcceptanceOutcomeAfterReconciliation(
        result: JSONObject
    ) {
        val tests =
            result.optJSONArray("tests")
                ?: return

        var passed = 0
        var warnings = 0
        var failed = 0
        var blocked = 0
        var unsupported = 0
        var noData = 0
        var cancelled = 0
        var criticalFailures = 0

        for (index in 0 until tests.length()) {
            val item =
                tests.optJSONObject(index)
                    ?: continue

            when (item.optString("status")) {
                AyanaAcceptanceTestEngine.STATUS_PASS ->
                    passed++

                AyanaAcceptanceTestEngine.STATUS_WARNING ->
                    warnings++

                AyanaAcceptanceTestEngine.STATUS_FAIL -> {
                    failed++
                    if (item.optBoolean("critical", false)) {
                        criticalFailures++
                    }
                }

                AyanaAcceptanceTestEngine.STATUS_BLOCKED ->
                    blocked++

                AyanaAcceptanceTestEngine.STATUS_UNSUPPORTED ->
                    unsupported++

                AyanaAcceptanceTestEngine.STATUS_NO_DATA ->
                    noData++

                AyanaAcceptanceTestEngine.STATUS_CANCELLED ->
                    cancelled++

                else -> {
                    failed++
                    if (item.optBoolean("critical", false)) {
                        criticalFailures++
                    }
                }
            }
        }

        val limits =
            result.optJSONArray("known_limits")
                ?: JSONArray()

        val grade =
            when {
                cancelled > 0 ->
                    AyanaAcceptanceTestEngine.GRADE_CANCELLED

                criticalFailures > 0 || failed > 0 ->
                    AyanaAcceptanceTestEngine.GRADE_NOT_READY

                blocked > 0 ||
                    unsupported > 0 ||
                    noData > 0 ||
                    warnings > 0 ->
                    AyanaAcceptanceTestEngine.GRADE_READY_WITH_LIMITATIONS

                result.optString("mode") !=
                    AyanaAcceptanceTestEngine.Mode.QUICK_HEALTH.wireName &&
                    limits.length() > 0 ->
                    AyanaAcceptanceTestEngine.GRADE_READY_WITH_LIMITATIONS

                else ->
                    AyanaAcceptanceTestEngine.GRADE_READY
            }

        result
            .put("passed", passed)
            .put("warnings", warnings)
            .put("failed", failed)
            .put("blocked", blocked)
            .put("unsupported", unsupported)
            .put("no_data", noData)
            .put("cancelled", cancelled)
            .put("critical_failures", criticalFailures)
            .put("grade", grade)
            .put("execution_success", cancelled == 0)
            .put("success", cancelled == 0)
            .put(
                "summary",
                buildReconciledAcceptanceSummary(
                    result = result,
                    voice = false
                )
            )
            .put(
                "voice_summary",
                buildReconciledAcceptanceSummary(
                    result = result,
                    voice = true
                )
            )
    }

    private fun buildReconciledAcceptanceSummary(
        result: JSONObject,
        voice: Boolean
    ): String {
        val tests =
            result.optJSONArray("tests")
                ?: JSONArray()

        val nonPass =
            mutableListOf<JSONObject>()

        for (index in 0 until tests.length()) {
            val item =
                tests.optJSONObject(index)
                    ?: continue

            if (
                item.optString("status") !=
                AyanaAcceptanceTestEngine.STATUS_PASS
            ) {
                nonPass += item
            }
        }

        val priorityOrder =
            mapOf(
                AyanaAcceptanceTestEngine.STATUS_FAIL to 0,
                AyanaAcceptanceTestEngine.STATUS_BLOCKED to 1,
                AyanaAcceptanceTestEngine.STATUS_WARNING to 2,
                AyanaAcceptanceTestEngine.STATUS_UNSUPPORTED to 3,
                AyanaAcceptanceTestEngine.STATUS_NO_DATA to 4,
                MASTER_STATUS_MANUAL_REQUIRED to 5,
                AyanaAcceptanceTestEngine.STATUS_CANCELLED to 6
            )

        val prioritized =
            nonPass
                .sortedWith(
                    compareBy<JSONObject> {
                        priorityOrder[
                            it.optString("status")
                        ] ?: 99
                    }.thenByDescending {
                        it.optBoolean("critical", false)
                    }
                )
                .take(
                    if (voice) {
                        3
                    } else {
                        5
                    }
                )

        val modeLabel =
            if (
                result.optString("mode") ==
                AyanaAcceptanceTestEngine.Mode.EXHAUSTIVE_ACCEPTANCE.wireName
            ) {
                "Всесторонняя автономная диагностика AYANA завершена."
            } else {
                "Полная диагностика AYANA завершена."
            }

        return buildString {
            append(modeLabel)
            append("\n\n")
            append(
                "Итог: PASS ${result.optInt("passed", 0)}, " +
                    "WARNING ${result.optInt("warnings", 0)}, " +
                    "FAIL ${result.optInt("failed", 0)}, " +
                    "BLOCKED ${result.optInt("blocked", 0)}, " +
                    "UNSUPPORTED ${result.optInt("unsupported", 0)}, " +
                    "NO_DATA ${result.optInt("no_data", 0)}, " +
                    "MANUAL_REQUIRED ${result.optInt("manual_required", 0)}."
            )
            append("\n")
            append(
                "Статус готовности: ${result.optString("grade", AyanaAcceptanceTestEngine.GRADE_NOT_READY)}."
            )
            append("\n")
            append(
                "Время теста: ${result.optLong("duration_ms", 0L)} мс. " +
                    "Сетевых обращений Agent Core/Worker: ${result.optInt("network_turns", 0)}. " +
                    "Всего проверок: ${result.optInt("tests_completed", tests.length())}; " +
                    "самонаправленно сгенерировано: ${result.optInt("adaptive_tests_generated", 0)}."
            )

            if (prioritized.isNotEmpty()) {
                append("\n\nТребуют внимания:\n")
                prioritized.forEachIndexed { index, item ->
                    append(index + 1)
                    append(". ")
                    append(item.optString("title"))
                    append(": ")
                    append(
                        when (item.optString("status")) {
                            AyanaAcceptanceTestEngine.STATUS_FAIL -> "ошибка"
                            AyanaAcceptanceTestEngine.STATUS_WARNING -> "предупреждение"
                            AyanaAcceptanceTestEngine.STATUS_NO_DATA -> "нет данных"
                            AyanaAcceptanceTestEngine.STATUS_BLOCKED -> "заблокировано"
                            AyanaAcceptanceTestEngine.STATUS_UNSUPPORTED -> "не поддерживается"
                            else -> item.optString("status").lowercase(Locale.ROOT)
                        }
                    )
                    append(" — ")
                    append(
                        item.optString("message")
                            .replace("\n", " ")
                            .take(
                                if (voice) {
                                    280
                                } else {
                                    560
                                }
                            )
                    )
                    append("\n")
                }
            }

            if (!voice) {
                append(
                    "\nПолный список ${tests.length()} проверок сохранён в подробном TXT-отчёте; " +
                        "в ответе показаны только приоритетные отклонения."
                )
            }
        }
    }

    private fun refreshCurrentOwnAppPageForRuntimeTruth() {
        try {
            val prefs =
                getSharedPreferences(
                    MainActivity.UI_STATE_PREFS,
                    Context.MODE_PRIVATE
                )

            val page =
                prefs.getString(
                    MainActivity.UI_STATE_CURRENT_PAGE,
                    "HOME"
                )
                    .orEmpty()
                    .takeIf {
                        it in setOf(
                            "HOME",
                            "TASKS",
                            "MEMORY",
                            "HISTORY",
                            "DIAGNOSTICS",
                            "SETTINGS"
                        )
                    }
                    ?: "HOME"

            startActivity(
                Intent(
                    this,
                    MainActivity::class.java
                ).apply {
                    putExtra(
                        MainActivity.EXTRA_OPEN_PAGE,
                        page
                    )
                    addFlags(
                        Intent.FLAG_ACTIVITY_NEW_TASK or
                            Intent.FLAG_ACTIVITY_CLEAR_TOP or
                            Intent.FLAG_ACTIVITY_SINGLE_TOP
                    )
                }
            )
        } catch (_: Exception) {
            // Registry truth is already persisted; UI refresh is best-effort only.
        }
    }

    private fun buildAcceptanceDetailedReport(
        result: JSONObject
    ): String {
        val tests =
            result.optJSONArray("tests")
                ?: JSONArray()

        val limits =
            result.optJSONArray("known_limits")
                ?: JSONArray()

        val durationMs =
            result.optLong("duration_ms", 0L)

        val generatedAt =
            result.optLong("finished_at_ms", System.currentTimeMillis())

        val startedAt =
            result.optLong(
                "started_at_ms",
                if (durationMs > 0L) {
                    (generatedAt - durationMs).coerceAtLeast(0L)
                } else {
                    0L
                }
            )

        val nonPass =
            mutableListOf<JSONObject>()

        for (index in 0 until tests.length()) {
            val item =
                tests.optJSONObject(index)
                    ?: continue

            if (
                item.optString("status") !=
                AyanaAcceptanceTestEngine.STATUS_PASS
            ) {
                nonPass += item
            }
        }

        val priorityOrder =
            mapOf(
                AyanaAcceptanceTestEngine.STATUS_FAIL to 0,
                AyanaAcceptanceTestEngine.STATUS_BLOCKED to 1,
                AyanaAcceptanceTestEngine.STATUS_WARNING to 2,
                AyanaAcceptanceTestEngine.STATUS_UNSUPPORTED to 3,
                AyanaAcceptanceTestEngine.STATUS_NO_DATA to 4,
                MASTER_STATUS_MANUAL_REQUIRED to 5,
                AyanaAcceptanceTestEngine.STATUS_CANCELLED to 6
            )

        val prioritized =
            nonPass.sortedWith(
                compareBy<JSONObject> {
                    priorityOrder[
                        it.optString("status")
                    ] ?: 99
                }.thenByDescending {
                    it.optBoolean(
                        "critical",
                        false
                    )
                }
            )

        val detailedReport = buildString {
            append(
                when (
                    result.optString("mode")
                ) {
                    MASTER_ACCEPTANCE_MODE ->
                        "AYANA — MASTER FULL ACCEPTANCE & DIAGNOSTIC REPORT\n"

                    AyanaAcceptanceTestEngine.Mode.EXHAUSTIVE_ACCEPTANCE.wireName ->
                        "AYANA — ВСЕСТОРОННИЙ АВТОНОМНЫЙ ОТЧЁТ ДИАГНОСТИКИ\n"

                    else ->
                        "AYANA — ПОЛНЫЙ ОТЧЁТ ДИАГНОСТИКИ\n"
                }
            )
            append("========================================\n")
            append("Engine: ${result.optString("engine", "AyanaAcceptanceTestEngine")} v${result.optString("engine_version", "unknown")}\n")
            append("Режим: ${result.optString("mode", "full_acceptance")}\n")
            append("Начало: ${formatAcceptanceReportTime(startedAt)}\n")
            append("Окончание: ${formatAcceptanceReportTime(generatedAt)}\n")
            append("Длительность: $durationMs мс\n")
            append("Agent Core network turns: ${result.optInt("network_turns", 0)}\n")
            append("Выполнение набора тестов завершено: ${result.optBoolean("execution_success", false)}\n")
            append("Readiness grade: ${result.optString("grade", AyanaAcceptanceTestEngine.GRADE_NOT_READY)}\n")
            append("\n")
            append("ИТОГОВЫЕ СЧЁТЧИКИ\n")
            append("----------------------------------------\n")
            append("PASS: ${result.optInt("passed", 0)}\n")
            append("WARNING: ${result.optInt("warnings", 0)}\n")
            append("FAIL: ${result.optInt("failed", 0)}\n")
            append("BLOCKED: ${result.optInt("blocked", 0)}\n")
            append("UNSUPPORTED: ${result.optInt("unsupported", 0)}\n")
            append("NO_DATA: ${result.optInt("no_data", 0)}\n")
            append("MANUAL_REQUIRED: ${result.optInt("manual_required", 0)}\n")
            append("CANCELLED: ${result.optInt("cancelled", 0)}\n")
            append("Critical failures: ${result.optInt("critical_failures", 0)}\n")
            append("Тестов запрошено: ${result.optInt("tests_requested", tests.length())}\n")
            append("Тестов завершено: ${result.optInt("tests_completed", tests.length())}\n")
            append("Baseline tests: ${result.optInt("baseline_tests_requested", result.optInt("tests_requested", tests.length()))}\n")
            append("Self-directed tests generated: ${result.optInt("adaptive_tests_generated", 0)}\n")
            val adaptiveEngine = result.optString("adaptive_engine")
            if (adaptiveEngine.isNotBlank()) {
                append("Adaptive engine: $adaptiveEngine v${result.optString("adaptive_engine_version", "unknown")}\n")
            }

            val evidenceSweep =
                result.optJSONObject("device_evidence_sweep")
                    ?: JSONObject()

            if (evidenceSweep.length() > 0) {
                append(
                    "Device evidence sweep: pending_before=${evidenceSweep.optInt("pending_before", 0)}; " +
                        "confirmed_now=${evidenceSweep.optInt("confirmed_now", 0)}; " +
                        "failed_now=${evidenceSweep.optInt("failed_now", 0)}; " +
                        "skipped=${evidenceSweep.optInt("skipped_already_confirmed", 0)}; " +
                        "duration=${evidenceSweep.optLong("duration_ms", 0L)} мс\n"
                )

                fun compactSweepIds(
                    key: String
                ): String {
                    val values =
                        evidenceSweep.optJSONArray(key)
                            ?: JSONArray()

                    val items =
                        arrayListOf<String>()

                    for (index in 0 until values.length()) {
                        values.optString(index)
                            .trim()
                            .takeIf {
                                it.isNotBlank()
                            }
                            ?.let {
                                items.add(it)
                            }
                    }

                    return items.joinToString(", ")
                }

                val confirmedIds =
                    compactSweepIds(
                        "confirmed_ids"
                    )

                val failedIds =
                    compactSweepIds(
                        "failed_ids"
                    )

                if (confirmedIds.isNotBlank()) {
                    append(
                        "Device evidence confirmed: $confirmedIds\n"
                    )
                }

                if (failedIds.isNotBlank()) {
                    append(
                        "Device evidence failed: $failedIds\n"
                    )
                }
            }
            append("\n")
            append("КОНТРАКТ ДОСТОВЕРНОСТИ\n")
            append("----------------------------------------\n")
            append("execution_success=true означает только то, что сам набор диагностики завершился.\n")
            append("Это не означает, что все функции AYANA исправны. Готовность определяется grade и статусами каждого теста.\n")

            if (prioritized.isNotEmpty()) {
                append("\nПРИОРИТЕТНЫЕ ПРОБЛЕМЫ\n")
                append("----------------------------------------\n")

                prioritized.forEachIndexed {
                    index,
                    item ->
                    append(
                        "${index + 1}. ${item.optString("status")} — " +
                            "${item.optString("id")} — ${item.optString("title")}\n"
                    )
                    append("   Critical: ${item.optBoolean("critical", false)}\n")
                    append(
                        "   Message: " +
                            item.optString("message")
                                .take(ACCEPTANCE_REPORT_MESSAGE_LIMIT) +
                            "\n"
                    )
                    append("   Evidence scope: ${item.optString("evidence_scope")}\n")
                }
            }
append("\nВСЕ ТЕСТЫ\n")
            append("========================================\n")

            for (index in 0 until tests.length()) {
                val item =
                    tests.optJSONObject(index)
                        ?: continue

                val status =
                    item.optString("status")

                val id =
                    item.optString("id")

                val compactAdaptivePass =
                    id.startsWith("AUTO-") &&
                        status == AyanaAcceptanceTestEngine.STATUS_PASS

                append(
                    "[${index + 1}/${tests.length()}] $status — " +
                        "$id — ${item.optString("title")}\n"
                )

                // Generated PASS matrices can be numerous. Preserve every test row
                // while avoiding repetitive successful evidence in the TXT artifact.
                // Every baseline test and every non-PASS adaptive test stays detailed.
                if (compactAdaptivePass) {
                    continue
                }

                append("Critical: ${item.optBoolean("critical", false)}\n")
                append("Verified: ${item.optBoolean("verified", false)}\n")
                append("Duration: ${item.optLong("duration_ms", 0L)} мс\n")
                append("Evidence scope: ${item.optString("evidence_scope")}\n")
                append(
                    "Message: " +
                        item.optString("message")
                            .take(ACCEPTANCE_REPORT_MESSAGE_LIMIT) +
                        "\n"
                )

                val evidence =
                    item.optJSONObject("evidence")
                        ?: JSONObject()

                if (evidence.length() > 0) {
                    append("Evidence: ")
                    append(
                        evidence
                            .toString(2)
                            .take(ACCEPTANCE_REPORT_EVIDENCE_LIMIT)
                    )
                    append("\n")
                }

                append("----------------------------------------\n")
            }

            val adaptiveCoverage =
                result.optJSONObject("adaptive_coverage")
                    ?: JSONObject()
            val adaptiveHypotheses =
                result.optJSONArray("adaptive_hypotheses")
                    ?: JSONArray()
            val adaptiveAnomalies =
                result.optJSONArray("adaptive_anomalies")
                    ?: JSONArray()

            if (adaptiveCoverage.length() > 0) {
                append("\nSELF-DIRECTED COVERAGE\n")
                append("========================================\n")
                append(adaptiveCoverage.toString(2).take(ACCEPTANCE_REPORT_EVIDENCE_LIMIT))
                append("\n")
            }

            if (adaptiveHypotheses.length() > 0) {
                append("\nАВТОНОМНО СФОРМИРОВАННЫЕ ГИПОТЕЗЫ / СЛЕДУЮЩИЕ ПРОВЕРКИ\n")
                append("========================================\n")
                for (index in 0 until adaptiveHypotheses.length()) {
                    val item = adaptiveHypotheses.optJSONObject(index) ?: continue
                    append("${index + 1}. ${item.optString("priority", "normal").uppercase(Locale.ROOT)} — ${item.optString("kind")}\n")
                    append("   ${item.optString("hypothesis").take(ACCEPTANCE_REPORT_MESSAGE_LIMIT)}\n")
                    val sourceTest = item.optString("source_test_id")
                    val capabilityId = item.optString("capability_id")
                    if (sourceTest.isNotBlank()) append("   source_test=$sourceTest\n")
                    if (capabilityId.isNotBlank()) append("   capability=$capabilityId\n")
                    append("   safe_execution=${item.optString("safe_execution")}\n")
                }
            }

            if (adaptiveAnomalies.length() > 0) {
                append("\nАНОМАЛИИ, НАЙДЕННЫЕ ПО РЕАЛЬНОЙ ИСТОРИИ\n")
                append("========================================\n")
                for (index in 0 until adaptiveAnomalies.length()) {
                    val item = adaptiveAnomalies.optJSONObject(index) ?: continue
                    append("${index + 1}. ${item.optString("kind")} — ${item.optString("message").take(ACCEPTANCE_REPORT_MESSAGE_LIMIT)}\n")
                    append("   history_id=${item.optString("history_id")}\n")
                    append("   command=${item.optString("command").take(500)}\n")
}
            }

            if (limits.length() > 0) {
                append("\nИЗВЕСТНЫЕ ОГРАНИЧЕНИЯ\n")
                append("========================================\n")

                for (index in 0 until limits.length()) {
                    val raw =
                        limits.opt(index)

                    when (raw) {
                        is JSONObject -> {
                            append("${index + 1}. ")
                            append(
                                raw.optString("label")
                                    .ifBlank {
                                        raw.optString("id")
                                    }
                                    .ifBlank {
                                        raw.toString()
                                    }
                                    .take(ACCEPTANCE_REPORT_MESSAGE_LIMIT)
                            )

                            val note =
                                raw.optString("note")
                                    .ifBlank {
                                        raw.optString("next")
                                    }
                                    .ifBlank {
                                        raw.optString("message")
                                    }

                            if (note.isNotBlank()) {
                                append(
                                    " — " +
                                        note.take(
                                            ACCEPTANCE_REPORT_MESSAGE_LIMIT
                                        )
                                )
                            }

                            append("\n")
                        }

                        else ->
                            append(
                                "${index + 1}. " +
                                    raw
                                        ?.toString()
                                        .orEmpty()
                                        .take(ACCEPTANCE_REPORT_MESSAGE_LIMIT) +
                                    "\n"
                            )
                    }
                }
            }

            append("\nСВОДКА\n")
            append("========================================\n")
            append(
                result.optString("summary")
                    .take(ACCEPTANCE_REPORT_SUMMARY_LIMIT)
            )
            append("\n")
            append(
                "REPORT_COMPLETE tests=${tests.length()}; " +
                    "adaptive=${result.optInt("adaptive_tests_generated", 0)}; " +
                    "renderer=v12.21.0-r7.9\n"
            )
        }

        if (
            detailedReport.length <=
            ACCEPTANCE_REPORT_SAFE_CHAR_BUDGET
        ) {
            return detailedReport
        }

        return buildAcceptanceCompactReport(
            result
        )
    }

    /**
     * Last-resort persistence renderer.
     *
     * If adaptive coverage grows beyond the safe detailed TXT budget, rebuild a
     * complete one-line index of every test rather than letting Artifact Engine
     * silently cut the report tail.
     */
    private fun buildAcceptanceCompactReport(
        result: JSONObject
    ): String {
        val tests =
            result.optJSONArray("tests")
                ?: JSONArray()

        val nonPass =
            mutableListOf<JSONObject>()

        for (index in 0 until tests.length()) {
            val item =
                tests.optJSONObject(index)
                    ?: continue

            if (
                item.optString("status") !=
                AyanaAcceptanceTestEngine.STATUS_PASS
            ) {
                nonPass += item
            }
        }

        val compact =
            buildString {
                append("AYANA — COMPACT COMPLETE DIAGNOSTIC INDEX\n")
                append("========================================\n")
                append("Engine: ${result.optString("engine")} v${result.optString("engine_version")}\n")
                append("Mode: ${result.optString("mode")}\n")
                append("Grade: ${result.optString("grade")}\n")
                append(
                    "PASS=${result.optInt("passed", 0)}; " +
                        "WARNING=${result.optInt("warnings", 0)}; " +
                        "FAIL=${result.optInt("failed", 0)}; " +
                        "BLOCKED=${result.optInt("blocked", 0)}; " +
                        "UNSUPPORTED=${result.optInt("unsupported", 0)}; " +
                        "NO_DATA=${result.optInt("no_data", 0)}; " +
                        "MANUAL_REQUIRED=${result.optInt("manual_required", 0)}\n"
                )
                append(
                    "tests=${tests.length()}; " +
                        "baseline=${result.optInt("baseline_tests", 0)}; " +
                        "adaptive=${result.optInt("adaptive_tests_generated", 0)}\n"
                )
                append(
                    "NOTE: compact fallback activated before TXT artifact limit; " +
                        "no test rows were omitted.\n"
                )

                if (nonPass.isNotEmpty()) {
                    append("\nNON-PASS DETAILS\n")
                    append("----------------------------------------\n")
                    nonPass.forEach { item ->
                        append(
                            "${item.optString("status")} — " +
                                "${item.optString("id")} — " +
                                "${item.optString("title")}\n"
                        )
                        append(
                            "Message: " +
                                item.optString("message")
                                    .take(ACCEPTANCE_REPORT_MESSAGE_LIMIT) +
                                "\n"
                        )
                        append(
                            "Scope: ${item.optString("evidence_scope")}; " +
                                "critical=${item.optBoolean("critical", false)}; " +
                                "verified=${item.optBoolean("verified", false)}\n"
                        )
                    }
                }

                append("\nALL TESTS — COMPLETE INDEX\n")
                append("========================================\n")

                for (index in 0 until tests.length()) {
                    val item =
                        tests.optJSONObject(index)
                            ?: continue

                    append(
                        "[${index + 1}/${tests.length()}] " +
                            "${item.optString("status")} — " +
                            "${item.optString("id")} — " +
                            item.optString("title")
                                .replace("\n", " ")
                                .take(260) +
                            "\n"
                    )
                }

                append("\n")
                append(
                    "REPORT_COMPLETE tests=${tests.length()}; " +
                        "adaptive=${result.optInt("adaptive_tests_generated", 0)}; " +
                        "renderer=v12.21.0-r7.9-compact\n"
                )
            }

        if (
            compact.length >
            ACCEPTANCE_REPORT_HARD_CHAR_BUDGET
        ) {
            throw IllegalStateException(
                "acceptance_report_too_large_even_compact:" +
                    compact.length
            )
        }

        return compact
    }

    private fun formatAcceptanceReportTime(
        timestampMs: Long
    ): String {
        if (timestampMs <= 0L) {
            return "нет данных"
        }

        return try {
            java.text.SimpleDateFormat(
                "yyyy-MM-dd HH:mm:ss Z",
                Locale.getDefault()
            ).format(
                java.util.Date(
                    timestampMs
                )
            )
        } catch (_: Exception) {
            timestampMs.toString()
        }
    }

