    // =========================================================
    // v12.17 EXHAUSTIVE AUTONOMOUS ACCEPTANCE PROBES
    // =========================================================

    private fun acceptanceDiagnosticsDetailProbe(
        recoveryEvidence: JSONObject? = null
    ): JSONObject {
        val rawResult =
            selfDiagnostics.run(
                focus = "all"
            )

        val result =
            diagnosticClosure
                .normalizeSelfDiagnostics(
                    raw = rawResult,
                    recentHistory =
                        commandHistoryStore
                            .recent(
                                24
                            ),
                    recoveryEvidence = recoveryEvidence
                )

        val checks =
            result.optJSONArray("checks")
                ?: JSONArray()

        val nonPass =
            mutableListOf<JSONObject>()

        for (index in 0 until checks.length()) {
            val item =
                checks.optJSONObject(index)
                    ?: continue

            if (
                item.optString("status") !=
                AyanaDiagnosticClosure.STATUS_PASS
            ) {
                nonPass += item
            }
        }

        val report =
            try {
                diagnosticClosure.reportFromNormalized(
                    result
                )
            } catch (_: Exception) {
                ""
            }

        val missingFromReport =
            nonPass
                .mapNotNull { item ->
                    val name =
                        item.optString("name")
                            .ifBlank {
                                item.optString("id")
                            }
                            .trim()

                    if (
                        name.isNotBlank() &&
                        !report.contains(
                            name,
                            ignoreCase = true
                        )
                    ) {
                        name
                    } else {
                        null
                    }
                }

        val ok =
            report.isNotBlank() &&
                missingFromReport.isEmpty()

        return acceptanceProbeResult(
            status =
                if (ok) {
                    AyanaAcceptanceTestEngine.STATUS_PASS
                } else {
                    AyanaAcceptanceTestEngine.STATUS_FAIL
                },
            message =
                if (ok) {
                    "Self-Diagnostics R9 раскрывает все ${nonPass.size} актуальные non-PASS проверки в каноническом отчёте."
                } else {
                    "Self-Diagnostics R9 не раскрыл все актуальные non-PASS проверки: ${missingFromReport.joinToString(", ")}."
                },
            evidenceScope = "live_runtime_contract_r9_freshness",
            verified = ok,
            evidence =
                JSONObject()
                    .put("non_pass_count", nonPass.size)
                    .put("missing_from_report", JSONArray(missingFromReport))
                    .put(
                        "diagnostic_closure_version",
                        AyanaDiagnosticClosure.VERSION
                    )
                    .put(
                        "successes_after_last_error",
                        result.optInt(
                            "successes_after_last_error",
                            0
                        )
                    )
                    .put(
                        "live_agent_core_recovery_passes",
                        result.optInt(
                            "live_agent_core_recovery_passes",
                            0
                        )
                    )
                    .put(
                        "live_agent_core_recovery_applied",
                        result.optBoolean(
                            "live_agent_core_recovery_applied",
                            false
                        )
                    )
                    .put("report", report.take(5000))
        )
    }

    private fun acceptanceReleaseMetadataProbe(): JSONObject {
        val snapshot =
            capabilityRegistry.snapshot()

        val registryBuild =
            snapshot.optString("build")
                .trim()

        val appVersion =
            currentAppVersionName()

        val engineVersion =
            AyanaAcceptanceTestEngine.ENGINE_VERSION

        val registryMatchesBaseLineage =
            registryBuild.contains(
                "12.21.0",
                ignoreCase = true
            ) &&
                registryBuild.contains(
                    "r7_9",
                    ignoreCase = true
                )

        val metadataComplete =
            registryBuild.isNotBlank() &&
                appVersion != "unknown" &&
                AYANA_VOICE_SERVICE_RELEASE.isNotBlank() &&
                AYANA_PERSONAL_SEARCH_ENGINE_RELEASE.isNotBlank() &&
                AYANA_RELEASE_LINEAGE.isNotBlank()

        val ok =
            registryMatchesBaseLineage &&
                metadataComplete

        return acceptanceProbeResult(
            status =
                if (ok) {
                    AyanaAcceptanceTestEngine.STATUS_PASS
                } else {
                    AyanaAcceptanceTestEngine.STATUS_WARNING
                },
            message =
                if (ok) {
                    "Release metadata согласованы: accepted=$AYANA_ACCEPTED_FEATURE_CHECKPOINT; current=$AYANA_CURRENT_FEATURE_RELEASE; Personal Search=$AYANA_PERSONAL_SEARCH_ENGINE_RELEASE."
                } else {
                    "Release metadata неполны или Capability Registry build-label не соответствует base v12.21.0 / R7.9: build=$registryBuild; app=$appVersion."
                },
            evidenceScope = "live_release_metadata_plus_compiled_feature_lineage",
            verified = ok,
            evidence =
                JSONObject()
                    .put("capability_registry_build", registryBuild)
                    .put("capability_registry_version", AYANA_CAPABILITY_REGISTRY_RELEASE)
                    .put("app_version", appVersion)
                    .put("voice_service_release", AYANA_VOICE_SERVICE_RELEASE)
                    .put("personal_search_engine_release", AYANA_PERSONAL_SEARCH_ENGINE_RELEASE)
                    .put("acceptance_engine_version", engineVersion)
                    .put("worker_release", AYANA_WORKER_RELEASE)
                    .put("accepted_feature_checkpoint", AYANA_ACCEPTED_FEATURE_CHECKPOINT)
                    .put("current_feature_release", AYANA_CURRENT_FEATURE_RELEASE)
                    .put("release_lineage", AYANA_RELEASE_LINEAGE)
                    .put("expected_registry_base_lineage", "v12.21.0_r7_9")
        )
    }

    private fun acceptanceDeviceStateSchemaProbe(): JSONObject {
        val state =
            try {
                agentGetDeviceState()
            } catch (error: Exception) {
                return acceptanceProbeResult(
                    status = AyanaAcceptanceTestEngine.STATUS_FAIL,
                    message =
                        "get_device_state завершился исключением: " +
                            (error.message ?: error.javaClass.simpleName),
                    evidenceScope = "live_device_state",
                    verified = false
                )
            }

        val required =
            listOf(
                "battery_percent",
                "charging",
                "media_volume",
                "media_volume_max",
                "orientation",
                "network_observation_available",
                "network_connected",
                "network_validated",
                "network_transport",
                "storage_free_bytes",
                "storage_total_bytes",
                "brightness_percent",
                "screen"
            )

        val missing =
            required.filterNot(
                state::has
            )

        val ok =
            state.optBoolean("success", false) &&
                missing.isEmpty()

        return acceptanceProbeResult(
status =
                if (ok) {
                    AyanaAcceptanceTestEngine.STATUS_PASS
                } else {
                    AyanaAcceptanceTestEngine.STATUS_FAIL
                },
            message =
                if (ok) {
                    "get_device_state содержит все обязательные поля: ${required.size}."
                } else {
                    "get_device_state неполон; отсутствуют: ${missing.joinToString(", ")}."
                },
            evidenceScope = "live_device_state",
            verified = ok,
            evidence =
                JSONObject()
                    .put("required_fields", JSONArray(required))
                    .put("missing_fields", JSONArray(missing))
                    .put("state", JSONObject(state.toString()))
        )
    }

