    private fun acceptanceDirectWorkerReachability(): JSONObject {
        val started =
            SystemClock.elapsedRealtime()

        var connection:
            HttpsURLConnection? =
            null

        return try {
            connection =
                (
                    URL(WORKER_URL)
                        .openConnection() as
                        HttpsURLConnection
                    ).apply {
requestMethod = "GET"
                    connectTimeout = 5000
                    readTimeout = 5000
                    instanceFollowRedirects = false
                    useCaches = false
                }
val code =
                connection.responseCode

            JSONObject()
                .put(
                    "reachable",
                    code in 100..599
                )
                .put(
                    "http_code",
                    code
                )
                .put(
                    "elapsed_ms",
                    (
                        SystemClock.elapsedRealtime() -
                            started
                        ).coerceAtLeast(0L)
                )
        } catch (error: Exception) {
            JSONObject()
                .put(
                    "reachable",
                    false
                )
                .put(
                    "error",
                    (error.message ?: error.javaClass.simpleName).take(500)
                )
                .put(
                    "elapsed_ms",
                    (
                        SystemClock.elapsedRealtime() -
                            started
                        ).coerceAtLeast(0L)
                )
        } finally {
            try {
                connection?.disconnect()
            } catch (_: Exception) {
            }
        }
    }

    private fun acceptanceNetworkLiveProbe(): JSONObject {
        val state =
            agentGetDeviceState()

        val observationAvailable =
            state.optBoolean(
                "network_observation_available",
                state.has("network_connected")
            )

        val observationError =
            state.optString(
                "network_observation_error"
            )

        val sensorConnected =
            state.optBoolean(
                "network_connected",
                false
            )

        val sensorValidated =
            state.optBoolean(
                "network_validated",
                false
            )

        val transport =
            state.optString(
                "network_transport",
                "unknown"
            )

        val direct =
            acceptanceDirectWorkerReachability()

        val reachable =
            direct.optBoolean(
                "reachable",
                false
            )

        val status =
            when {
                reachable && !observationAvailable ->
                    AyanaAcceptanceTestEngine.STATUS_FAIL

                reachable && !sensorConnected ->
                    AyanaAcceptanceTestEngine.STATUS_FAIL

                reachable && sensorConnected ->
                    AyanaAcceptanceTestEngine.STATUS_PASS

                !reachable && observationAvailable && sensorConnected ->
                    AyanaAcceptanceTestEngine.STATUS_WARNING

                else ->
                    AyanaAcceptanceTestEngine.STATUS_NO_DATA
            }

        val message =
            when (status) {
                AyanaAcceptanceTestEngine.STATUS_FAIL ->
                    if (!observationAvailable) {
                        "Сетевой сенсор недоступен при реально достижимом Worker: ${observationError.ifBlank { "unknown_observation_error" }}."
                    } else {
                        "Сетевой сенсор дал false-negative: Android сообщает disconnected, но Worker реально достижим."
                    }

                AyanaAcceptanceTestEngine.STATUS_PASS ->
                    "Network sensor согласован с прямой достижимостью Worker; transport=$transport, validated=$sensorValidated."

                AyanaAcceptanceTestEngine.STATUS_WARNING ->
                    "Android сообщает сеть подключённой, но прямой Worker reachability не подтверждён."

                else ->
                    "И Android sensor, и direct Worker reachability сейчас не подтверждают интернет; отличить корректный offline от sensor false-negative невозможно."
            }

        return acceptanceProbeResult(
            status = status,
            message = message,
            evidenceScope = "live_device_plus_direct_network",
            verified =
                status ==
                    AyanaAcceptanceTestEngine.STATUS_PASS,
            evidence =
                JSONObject()
                    .put("network_observation_available", observationAvailable)
                    .put("network_observation_error", observationError)
                    .put("network_connected", sensorConnected)
                    .put("network_validated", sensorValidated)
                    .put("network_transport", transport)
                    .put("direct_reachability", direct)
        )
            .put("network_turns", 1)
    }

    private fun acceptanceNetworkSingleRoutingProbe(): JSONObject {
        val query =
            "проверь подключение к интернету"

        val metrics =
            extractRequestedAggregateMetrics(
                query
            )

        val hasRemainingGoal =
            aggregateMetricHasRemainingSemanticGoal(
                query
            )

        val locallyOwned =
            aggregateMetricLocalRouteEligible(
                metrics
            ) &&
                !hasRemainingGoal

        val ok =
            metrics.size == 1 &&
                AggregateMetric.NETWORK in metrics &&
                locallyOwned

        return acceptanceProbeResult(
            status =
                if (ok) {
                    AyanaAcceptanceTestEngine.STATUS_PASS
                } else {
                    AyanaAcceptanceTestEngine.STATUS_FAIL
                },
            message =
                if (ok) {
                    "Одиночный NETWORK запрос принадлежит production local aggregate route и не требует Agent Core."
                } else {
                    "Одиночный NETWORK запрос не принадлежит production local route; metrics=${metrics.joinToString(",")}, remaining_goal=$hasRemainingGoal, owned=$locallyOwned."
                },
            evidenceScope = "live_pure_production_routing_contract",
            verified = ok,
            evidence =
                JSONObject()
                    .put(
                        "requested_metrics",
                        JSONArray(
                            metrics.map { it.name }
                        )
                    )
                    .put(
                        "remaining_semantic_goal",
                        hasRemainingGoal
                    )
                    .put(
                        "local_route_eligible",
                        locallyOwned
                    )
        )
    }

    private fun acceptanceWorkerRequest(
        payload: JSONObject,
        readTimeoutMs: Int
    ): JSONObject {
        val started =
            SystemClock.elapsedRealtime()

        var connection:
            HttpsURLConnection? =
            null

        return try {
            connection =
                (
                    URL(
                        "$WORKER_URL/agent"
                    ).openConnection() as
                    HttpsURLConnection
                    ).apply {
                    requestMethod = "POST"
                    connectTimeout = 8000
                    readTimeout =
                        readTimeoutMs.coerceIn(
                            5000,
                            60000
                        )
                    doOutput = true
                    useCaches = false
                    setRequestProperty(
                        "Content-Type",
                        "application/json; charset=utf-8"
                    )
                    setRequestProperty(
                        "Accept",
                        "application/json"
                    )
                }

            val bytes =
                payload
                    .toString()
                    .toByteArray(
                        Charsets.UTF_8
                    )

            connection.setFixedLengthStreamingMode(
                bytes.size
            )

            connection.outputStream.use {
                output ->
                output.write(
                    bytes
                )
                output.flush()
            }

            val code =
                connection.responseCode

            val stream =
                try {
                    if (
                        code in 200..299
                    ) {
                        connection.inputStream
                    } else {
                        connection.errorStream
                    }
                } catch (_: Exception) {
                    connection.errorStream
                }

            val body =
                stream
                    ?.bufferedReader(
                        Charsets.UTF_8
                    )
                    ?.use {
                        it.readText()
                    }
                    .orEmpty()

            val data =
                try {
                    JSONObject(
                        body
                    )
                } catch (_: Exception) {
                    JSONObject()
                        .put(
                            "_raw",
                            body.take(8000)
                        )
                }

            JSONObject()
                .put(
                    "http_code",
                    code
                )
                .put(
                    "elapsed_ms",
                    (
                        SystemClock.elapsedRealtime() -
                            started
                        ).coerceAtLeast(0L)
                )
                .put(
                    "data",
                    data
                )
        } catch (error: Exception) {
            JSONObject()
                .put(
                    "http_code",
                    -1
                )
                .put(
                    "elapsed_ms",
                    (
                        SystemClock.elapsedRealtime() -
                            started
                        ).coerceAtLeast(0L)
                )
                .put(
                    "error",
                    (error.message ?: error.javaClass.simpleName).take(1200)
                )
                .put(
                    "data",
                    JSONObject()
                )
        } finally {
            try {
                connection?.disconnect()
            } catch (_: Exception) {
            }
        }
    }

    private fun acceptanceAgentMessagePayload(
        message: String,
        previousResponseId: String? = null
    ): JSONObject {
        val payload =
            JSONObject()
                .put(
                    "message",
                    message
                )
                .put(
                    "source",
                    "text"
                )
                .put(
                    "device_local_datetime",
                    LocalDateTime.now().toString()
                )
                .put(
                    "device_timezone",
                    ZoneId.systemDefault().id
                )

        if (
            !previousResponseId.isNullOrBlank()
        ) {
            payload.put(
                "previous_response_id",
                previousResponseId
            )
        }

        return payload
    }

    private fun acceptanceRequiredFactGateProbe(): JSONObject {
        val first =
            acceptanceWorkerRequest(
                payload =
                    acceptanceAgentMessagePayload(
                        "проверь подключение к интернету"
                    ),
                readTimeoutMs = 25000
            )

        val firstCode =
            first.optInt(
                "http_code",
                -1
            )

        val firstData =
            first.optJSONObject(
                "data"
            ) ?: JSONObject()

        if (
            firstCode !in 200..299
        ) {
            return acceptanceProbeResult(
                status = AyanaAcceptanceTestEngine.STATUS_NO_DATA,
                message =
                    "Required-fact gate не проверен: первый Agent Core turn недоступен, HTTP=$firstCode.",
                evidenceScope = "bounded_online_agent_core",
                verified = false,
                evidence = first
            )
                .put(
                    "network_turns",
                    1
                )
        }

        if (
            firstData.optString(
                "type"
            ) ==
            "final"
        ) {
            val terminal =
                firstData.optString(
                    "terminal_status"
                )

            return acceptanceProbeResult(
                status =
                    if (
                        terminal ==
                        "SUCCESS"
                    ) {
                        AyanaAcceptanceTestEngine.STATUS_FAIL
                    } else {
                        AyanaAcceptanceTestEngine.STATUS_PASS
                    },
                message =
                    if (
                        terminal ==
                        "SUCCESS"
                    ) {
                        "Agent Core завершил factual NETWORK query без tool evidence."
                    } else {
                        "Agent Core не выставил SUCCESS без device evidence."
                    },
                evidenceScope = "bounded_online_agent_core",
                verified =
                    terminal !=
                        "SUCCESS",
                evidence =
                    JSONObject()
                        .put(
                            "first",
                            firstData
                        )
            )
                .put(
                    "network_turns",
                    1
                )
        }

        val calls =
            firstData.optJSONArray(
                "calls"
            ) ?: JSONArray()

        var targetCallId =
            ""

        for (
            index in
            0 until calls.length()
        ) {
            val call =
                calls.optJSONObject(
                    index
                ) ?: continue

            if (
                call.optString(
                    "name"
                ) ==
                "get_device_state"
            ) {
                targetCallId =
                    call.optString(
                        "call_id"
                    )
                break
            }
        }

        if (
            targetCallId.isBlank()
        ) {
            return acceptanceProbeResult(
                status = AyanaAcceptanceTestEngine.STATUS_WARNING,
                message =
                    "NETWORK factual probe не запросил get_device_state; required-fact guard нельзя проверить этим turn.",
                evidenceScope = "bounded_online_agent_core",
                verified = false,
                evidence =
                    JSONObject()
                        .put(
                            "first",
                            firstData
                        )
            )
                .put(
                    "network_turns",
                    1
                )
        }

        val responseId =
            firstData.optString(
                "response_id"
            )

        val toolResults =
            JSONArray()
                .put(
                    JSONObject()
                        .put(
                            "call_id",
                            targetCallId
                        )
                        .put(
                            "output",
                            JSONObject()
                                .put(
                                    "success",
                                    true
                                )
                                .put(
                                    "screen",
                                    JSONObject()
                                        .put(
                                            "success",
                                            true
                                        )
                                )
                                .toString()
                        )
                )

        val secondPayload =
            JSONObject()
                .put(
                    "source",
                    "text"
                )
                .put(
                    "previous_response_id",
                    responseId
                )
                .put(
                    "tool_results",
                    toolResults
                )

        val second =
            acceptanceWorkerRequest(
                payload = secondPayload,
                readTimeoutMs = 25000
            )

        val secondCode =
            second.optInt(
                "http_code",
                -1
            )

        val secondData =
            second.optJSONObject(
                "data"
            ) ?: JSONObject()

        val terminal =
            secondData.optString(
                "terminal_status"
            )

        val secondType =
            secondData.optString(
                "type"
            )

        val ok =
            secondCode in 200..299 &&
                (
                    secondType ==
                        "tool_calls" ||
                        terminal !=
                        "SUCCESS"
                    )

        return acceptanceProbeResult(
            status =
                if (ok) {
                    AyanaAcceptanceTestEngine.STATUS_PASS
                } else {
                    AyanaAcceptanceTestEngine.STATUS_FAIL
                },
            message =
                if (ok) {
                    "Required-device-fact gate не принимает неполный get_device_state как factual SUCCESS."
                } else {
                    "FALSE SUCCESS: после screen-only get_device_state Agent Core завершил NETWORK query как SUCCESS."
                },
            evidenceScope = "bounded_online_missing_evidence_injection",
            verified = ok,
            evidence =
                JSONObject()
                    .put(
                        "first_type",
                        firstData.optString("type")
                    )
                    .put(
                        "second_http",
                        secondCode
                    )
                    .put(
                        "second_type",
                        secondType
                    )
                    .put(
                        "second_terminal_status",
                        terminal
                    )
                    .put(
                        "second_reply",
                        secondData.optString("reply").take(1500)
                    )
        )
            .put(
                "network_turns",
                2
            )
    }

    private fun acceptanceCalculatorProbe(): JSONObject {
        val expression =
            evaluateSimpleCalculation(
                "сколько будет 125 умножить на 48 плюс 375"
            )

        val divideByZero =
            evaluateSimpleCalculation(
                "десять разделить на ноль"
            )

        val expressionOk =
            expression
                ?.contains(
                    "6375"
                ) ==
                true

        val zeroOk =
            divideByZero
                ?.contains(
                    "ноль",
                    ignoreCase = true
                ) ==
                true

        val ok =
            expressionOk &&
                zeroOk

        return acceptanceProbeResult(
            status =
                if (ok) {
                    AyanaAcceptanceTestEngine.STATUS_PASS
                } else {
                    AyanaAcceptanceTestEngine.STATUS_FAIL
                },
            message =
                if (ok) {
                    "Локальный calculator прошёл составное выражение и деление на ноль."
                } else {
                    "Calculator regression: expression=$expression; divide_by_zero=$divideByZero."
                },
            evidenceScope = "live_pure_local",
            verified = ok,
            evidence =
                JSONObject()
                    .put(
                        "expression_result",
                        expression
                    )
                    .put(
                        "divide_by_zero_result",
                        divideByZero
                    )
        )
    }

    private fun acceptanceNotificationRoutingProbe(): JSONObject {
        val intent =
            AyanaStructuredLocalCommandRouter
                .parse(
                    "покажи последние 5 уведомлений"
                )

        val ok =
            intent is
                AyanaStructuredLocalCommandRouter.Intent.NotificationRead &&
                intent.limit ==
                5

        return acceptanceProbeResult(
            status =
                if (ok) {
                    AyanaAcceptanceTestEngine.STATUS_PASS
                } else {
                    AyanaAcceptanceTestEngine.STATUS_FAIL
                },
            message =
                if (ok) {
                    "Read-only notification intent распознан локально с limit=5."
                } else {
                    "Notification routing regression: ${intent?.javaClass?.simpleName ?: "null"}."
                },
            evidenceScope = "live_pure_routing_contract",
            verified = ok,
            evidence =
                JSONObject()
                    .put(
                        "intent_type",
                        intent?.javaClass?.simpleName
                            ?: "null"
                    )
                    .put(
                        "limit",
                        if (
                            intent is
                            AyanaStructuredLocalCommandRouter.Intent.NotificationRead
                        ) {
                            intent.limit
                                ?: JSONObject.NULL
                        } else {
                            JSONObject.NULL
                        }
                    )
        )
    }

    private fun acceptanceExactVolumeRoutingProbe(): JSONObject {
        val first =
            extractExactMediaVolumeRequest(
                "установи громкость мультимедиа на 5 из 15"
            )

        val second =
            extractExactMediaVolumeRequest(
                "уменьшить громкость до 2"
            )

        val spokenImplicit =
            extractExactMediaVolumeRequest(
                "громкость девять из пятнадцати"
            )

        val readOnlyQueryRejected =
            extractExactMediaVolumeRequest(
                "какая сейчас громкость"
            ) == null

        val ok =
            first?.requestedLevel ==
                5 &&
                first.requestedScaleMax ==
                15 &&
                !first.percent &&
                second?.requestedLevel ==
                2 &&
                second.requestedScaleMax ==
                null &&
                !second.percent &&
                spokenImplicit?.requestedLevel ==
                9 &&
                spokenImplicit.requestedScaleMax ==
                15 &&
                !spokenImplicit.percent &&
                readOnlyQueryRejected

        return acceptanceProbeResult(
            status =
                if (ok) {
                    AyanaAcceptanceTestEngine.STATUS_PASS
                } else {
                    AyanaAcceptanceTestEngine.STATUS_FAIL
                },
            message =
                if (ok) {
                    "Exact media-volume parser сохраняет absolute target semantics для 5/15 и «до 2»."
                } else {
                    "Exact-volume routing regression."
                },
            evidenceScope = "live_pure_routing_contract",
            verified = ok,
            evidence =
                JSONObject()
                    .put(
                        "first_level",
                        first?.requestedLevel
                            ?: -1
                    )
                    .put(
                        "first_scale",
                        first?.requestedScaleMax
                            ?: -1
                    )
                    .put(
                        "second_level",
                        second?.requestedLevel
                            ?: -1
                    )
        )
    }

    private fun acceptanceHistoryShortRoundTripProbe(): JSONObject {
        val marker =
            "AYANA_SELFTEST_HISTORY_SHORT_" +
                UUID.randomUUID()
                    .toString()
                    .take(8)

        val id =
            commandHistoryStore.begin(
                command = marker,
                source = "self_test"
            )

        var deleted =
            false

        return try {
            commandHistoryStore.addEvent(
                id = id,
                state = "self_test",
                message = marker,
                details = "short_roundtrip"
            )

            val expected =
                "SELFTEST_SHORT_RESULT_$marker"

            commandHistoryStore.finish(
                id = id,
                success = true,
                result = expected,
                technical = "self_test_short"
            )

            val record =
                commandHistoryStore
                    .recent(
                        80
                    )
                    .firstOrNull {
it.optString(
                            "id"
                        ) ==
                            id
                    }

            val actual =
                record?.let(
                    commandHistoryStore::fullResult
                )
                    .orEmpty()

            val persisted =
                record !=
                    null &&
                    actual ==
                    expected &&
                    record.optString(
                        "status"
                    ) ==
                    AyanaCommandHistoryStore.STATUS_SUCCESS

            deleted =
                commandHistoryStore.delete(
                    id
                )

            val ok =
                persisted &&
                    deleted

            acceptanceProbeResult(
                status =
                    if (ok) {
                        AyanaAcceptanceTestEngine.STATUS_PASS
                    } else {
                        AyanaAcceptanceTestEngine.STATUS_FAIL
                    },
                message =
                    if (ok) {
                        "History short record begin/event/finish/read/delete round-trip подтверждён."
                    } else {
                        "History short round-trip или cleanup не подтверждён."
                    },
                evidenceScope = "live_reversible_persistence",
                verified = ok,
                evidence =
                    JSONObject()
                        .put(
                            "record_found",
                            record != null
                        )
                        .put(
                            "result_match",
                            actual ==
                                expected
                        )
                        .put(
                            "cleanup_deleted",
                            deleted
                        )
            )
        } catch (error: Exception) {
            if (!deleted) {
                try {
                    deleted =
                        commandHistoryStore.delete(
                            id
                        )
                } catch (_: Exception) {
                }
            }

            acceptanceProbeResult(
                status = AyanaAcceptanceTestEngine.STATUS_FAIL,
                message =
                    "History short round-trip exception: " +
                        (error.message ?: error.javaClass.simpleName),
                evidenceScope = "live_reversible_persistence",
                verified = false,
                evidence =
                    JSONObject()
                        .put(
                            "cleanup_deleted",
                            deleted
                        )
            )
        }
    }

