    private fun acceptanceArtifactRoundTripProbe(
        kind: String
    ): JSONObject {
        val stamp =
            System.currentTimeMillis()
                .toString()

        val extension =
            when (kind) {
                "txt" -> "txt"
                "docx" -> "docx"
                "pdf" -> "pdf"
                "xlsx" -> "xlsx"
                "jpeg" -> "jpg"
                "graph" -> "jpg"
                else -> kind
            }

        val filename =
            "AYANA_SELFTEST_${kind.uppercase(Locale.ROOT)}_$stamp.$extension"

        val arguments =
            acceptanceArtifactArguments(
                kind = kind,
                filename = filename
            )

        val result =
            try {
                artifactEngine.create(
                    arguments = arguments,
                    tryBeginPublish = {
                        true
                    },
                    onPublishAccepted = {
                    },
                    onPublishReconciliationStarted = {
                    },
                    onPublishReconciled = {
                        _,
                        _ ->
                    }
                )
            } catch (error: Exception) {
                JSONObject()
                    .put(
                        "success",
                        false
                    )
                    .put(
                        "verified",
                        false
                    )
                    .put(
                        "message",
                        error.message
                            ?: error.javaClass.simpleName
                    )
            }

        val reference =
            result.optString(
                "artifact_reference"
            )
                .trim()

        val created =
            result.optBoolean(
                "success",
                false
            ) &&
                result.optBoolean(
                    "verified",
                    false
                ) &&
                reference.isNotBlank()

        var cleanupDeleted =
            false

        if (
            reference.isNotBlank()
        ) {
            cleanupDeleted =
                try {
                    contentResolver.delete(
                        Uri.parse(
                            reference
                        ),
                        null,
                        null
                    ) >
                        0
                } catch (_: Exception) {
                    false
                }
        }

        val status =
            when {
                created &&
                    cleanupDeleted ->
                    AyanaAcceptanceTestEngine.STATUS_PASS

                created ->
                    AyanaAcceptanceTestEngine.STATUS_WARNING

                else ->
                    AyanaAcceptanceTestEngine.STATUS_FAIL
            }

        return acceptanceProbeResult(
            status = status,
            message =
                when (status) {
                    AyanaAcceptanceTestEngine.STATUS_PASS ->
                        "$kind artifact реально создан, verified и тестовый файл удалён."

                    AyanaAcceptanceTestEngine.STATUS_WARNING ->
                        "$kind artifact создан и verified, но cleanup тестового файла не подтверждён: $filename."

                    else ->
                        "$kind artifact round-trip не подтвердил реальное создание/verification."
                },
            evidenceScope = "live_artifact_roundtrip",
            verified =
                status ==
                    AyanaAcceptanceTestEngine.STATUS_PASS,
            evidence =
                JSONObject()
                    .put(
                        "kind",
                        kind
                    )
                    .put(
                        "name",
                        result.optString(
                            "name",
                            filename
                        )
                    )
                    .put(
                        "success",
                        result.optBoolean(
                            "success",
                            false
                        )
                    )
                    .put(
                        "verified",
                        result.optBoolean(
                            "verified",
                            false
                        )
                    )
                    .put(
                        "artifact_reference_present",
                        reference.isNotBlank()
                    )
                    .put(
                        "cleanup_deleted",
                        cleanupDeleted
                    )
                    .put(
                        "message",
                        result.optString(
                            "message"
                        ).take(1200)
                    )
        )
    }

