    private fun acceptanceWakeGrammarProbe(): JSONObject {
        val command =
            removeLeadingWakeWord(
                "аяна открой ютуб"
            )

        val wakeOnly =
            removeLeadingWakeWord(
                "аяна"
            )

        val noWake =
            removeLeadingWakeWord(
                "открой ютуб"
            )

        val variant =
            removeLeadingWakeWord(
                "айана проверь батарею"
            )

        val ok =
            command ==
                "открой ютуб" &&
                wakeOnly.isBlank() &&
                noWake ==
                "открой ютуб" &&
                variant ==
                "проверь батарею"

        return acceptanceProbeResult(
            status =
