    private fun acceptanceAgentCoreContextProbe(): JSONObject {
        val first =
            acceptanceWorkerRequest(
                payload =
                    acceptanceAgentMessagePayload(
                        "что такое фотосинтез"
                    ),
                readTimeoutMs = 26000
            )

        val firstData =
            first.optJSONObject(
                "data"
            ) ?: JSONObject()

        val firstId =
            firstData.optString(
                "response_id"
            )

        if (
            first.optInt(
                "http_code",
                -1
            ) !in
            200..299 ||
            firstId.isBlank()
        ) {
            return acceptanceProbeResult(
                status = AyanaAcceptanceTestEngine.STATUS_NO_DATA,
                message =
                    "Context probe остановлен: базовый Agent Core turn не завершён.",
                evidenceScope = "bounded_online_agent_core_context",
                verified = false,
                evidence = first
            )
                .put(
                    "network_turns",
                    1
                )
        }

        val follow =
            acceptanceWorkerRequest(
                payload =
                    acceptanceAgentMessagePayload(
                        message = "а подробнее?",
                        previousResponseId = firstId
                    ),
                readTimeoutMs = 32000
            )

        val followData =
            follow.optJSONObject(
                "data"
            ) ?: JSONObject()

        val followId =
            followData.optString(
                "response_id"
            )

        if (
            follow.optInt(
                "http_code",
                -1
            ) !in
            200..299 ||
            followId.isBlank()
        ) {
            return acceptanceProbeResult(
                status = AyanaAcceptanceTestEngine.STATUS_FAIL,
                message =
                    "Follow-up context turn не завершён.",
                evidenceScope = "bounded_online_agent_core_context",
                verified = false,
                evidence =
                    JSONObject()
                        .put(
                            "first",
                            firstData
                        )
                        .put(
                            "follow",
                            followData
                        )
            )
                .put(
                    "network_turns",
                    2
                )
        }

        val boundary =
            acceptanceWorkerRequest(
                payload =
                    acceptanceAgentMessagePayload(
                        message =
                            "галактика это что подробно",
                        previousResponseId =
                            followId
                    ),
                readTimeoutMs = 42000
            )

        val boundaryData =
            boundary.optJSONObject(
                "data"
            ) ?: JSONObject()

        val followContinued =
            followData.optString(
                "context_mode"
            ) ==
                "continued_follow_up"

        val boundaryFresh =
            boundaryData.optString(
                "context_mode"
            ) ==
                "fresh_topic_boundary"

        val boundaryOk =
            boundary.optInt(
                "http_code",
                -1
            ) in
                200..299 &&
                boundaryData.optString(
                    "type"
                ) ==
                "final"

        val ok =
            followContinued &&
                boundaryFresh &&
                boundaryOk

        return acceptanceProbeResult(
            status =
                if (ok) {
                    AyanaAcceptanceTestEngine.STATUS_PASS
                } else {
                    AyanaAcceptanceTestEngine.STATUS_FAIL
                },
            message =
                if (ok) {
                    "Context continuity корректна: follow-up continued, новая detailed тема fresh_topic_boundary."
                } else {
                    "Context boundary regression: follow=${followData.optString("context_mode")}, new_topic=${boundaryData.optString("context_mode")}, HTTP=${boundary.optInt("http_code", -1)}."
                },
            evidenceScope = "bounded_online_agent_core_context",
            verified = ok,
            evidence =
                JSONObject()
                    .put(
                        "base_context_mode",
                        firstData.optString(
                            "context_mode"
                        )
                    )
                    .put(
                        "follow_context_mode",
                        followData.optString(
                            "context_mode"
                        )
                    )
                    .put(
                        "boundary_context_mode",
                        boundaryData.optString(
                            "context_mode"
                        )
                    )
                    .put(
                        "boundary_http",
                        boundary.optInt(
                            "http_code",
                            -1
                        )
                    )
                    .put(
                        "boundary_completion_integrity",
                        boundaryData.optString(
                            "completion_integrity"
                        )
                    )
        )
            .put(
                "network_turns",
                3
            )
    }

    private fun acceptanceKnownLimitsProbe(): JSONObject {
        val snapshot =
            reconcileGitHubCapabilityRegistry(
                capabilityRegistry.snapshot()
            )
        val limits = JSONArray()

        val labels =
            linkedMapOf(
                "development_agent_transaction" to "R10.27.3 development transaction реализована, но текущая GitHub Contents:write/Actions:write authority ещё не подтверждена",
                "github_repository_write" to "R10.27.1 GitHub executor реализован, но текущая authorization/write readiness не подтверждена",
                "github_commit_push" to "R10.27.1 commit executor реализован, но текущая authorization/write readiness не подтверждена",
                "android_apk_build" to "R10.27.2 APK build executor реализован, но текущая Actions:write readiness ещё не подтверждена",
                "external_mail_calendar_files" to "нет авторизованных внешних mail/calendar/files account executors; R9.3 local app integration не заменяет account API",
                "video_audio_analysis" to "аудиодорожка видео не анализируется",
                "offline_llm" to "полноценный offline LLM отсутствует",
                "controlled_proactivity" to "R9.9.2 добавляет только explicit opt-in low-battery notification watcher; широкая/general proactivity и silent device mutations по-прежнему не реализованы"
            )

        labels.forEach { (id, label) ->
            val item = acceptanceCapability(snapshot, id)
            if (
                item == null ||
                !item.optBoolean("implemented", false) ||
                !item.optBoolean("available_now", false)
            ) {
                limits.put(
                    JSONObject()
                        .put("id", id)
                        .put("label", label)
                )
            }
        }

        val liveScreen =
            try {
                screenIntelligence.getScreenState()
            } catch (_: Exception) {
                JSONObject()
            }

        val screenState =
            liveScreen.optString(
                "primary_content_state",
                liveScreen.optString(
                    "content_status",
                    "unknown"
                )
            )

        if (screenState != "readable") {
            limits.put(
                JSONObject()
                    .put("id", "live_visual_screen_fallback")
                    .put(
                        "label",
                        "live visual screen fallback ещё не закрывает Accessibility partial/unavailable; current=$screenState"
                    )
            )
        }

        limits.put(
            JSONObject()
                .put("id", "verified_result_transfer_semantics_v1")
                .put(
                    "label",
                    "R9.8 generic transfer использует только provenance-bound typed verified fields/structured visible data; скрытое содержимое и свободная семантическая интерпретация не считаются verified result"
                )
        )

        return JSONObject()
            .put("success", true)
            .put("status", AyanaAcceptanceTestEngine.STATUS_PASS)
            .put("limits", limits)
    }

    private fun acceptanceCapability(
        snapshot: JSONObject,
        id: String
    ): JSONObject? {
        val array = snapshot.optJSONArray("capabilities") ?: return null

        for (index in 0 until array.length()) {
            val item = array.optJSONObject(index) ?: continue
            if (item.optString("id") == id) {
                return item
            }
        }

        return null
    }

    private fun acceptanceProbeResult(
        status: String,
        message: String,
        evidenceScope: String,
        verified: Boolean = status == AyanaAcceptanceTestEngine.STATUS_PASS,
        evidence: JSONObject = JSONObject()
    ): JSONObject =
        JSONObject()
            .put("success", status != AyanaAcceptanceTestEngine.STATUS_FAIL)
            .put("verified", verified)
            .put("status", status)
            .put("message", message)
            .put("evidence_scope", evidenceScope)
            .put("evidence", evidence)




    // R10.10 ADAPTIVE PLANNER EXECUTION IN PRODUCTION PATH.
    // This route is intentionally bounded: only objectives that the already accepted
    // Dynamic Goal Planner can decompose into >=2 registered primitives are claimed.
    // Unsupported/free-form objectives continue to the existing Agent Core path.
    private fun runR10_10ProductionDynamicPlannerIfSupported(
        command: String,
        silent: Boolean
    ): Boolean {
        if (requestsArtifactDeliverable(command)) {
            return false
        }

        val proposal =
            try {
                AyanaDynamicGoalPlanner.localProposal(command)
            } catch (_: Exception) {
                return false
            }

        if (!proposal.optBoolean("supported", false)) {
            return false
        }

        val planner =
            try {
                AyanaDynamicGoalPlanner.compile(
                    objective = command,
                    proposal = proposal
                )
            } catch (error: Throwable) {
                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "r10_10_production_plan_validation_failed",
                    message = "Production planner proposal отклонён до dispatch",
                    details = (error.message ?: error.javaClass.simpleName).take(600)
                )
                respondAndResume(
                    text = "Я остановила многошаговую цель до выполнения: план не прошёл локальную проверку.",
                    silent = silent,
                    success = false,
                    terminalStatus = AyanaCommandHistoryStore.STATUS_BLOCKED,
                    technical =
                        JSONObject()
                            .put("production_dynamic_planner", true)
                            .put("plan_validated_pre_dispatch", false)
                            .put("invalid_plan_dispatch_count", 0)
                            .put("reason", error.message ?: error.javaClass.simpleName)
                            .toString()
                )
                return true
            }

        if (planner.subgoalCount() < 2) {
            return false
        }

        startR10_10ProductionDynamicPlannerWorker(
            command = command,
            silent = silent,
            planner = planner,
            resumeGoal = null,
            automaticRecovery = false
        )
        return true
    }

    private fun startR10_10ProductionDynamicPlannerWorker(
        command: String,
        silent: Boolean,
        planner: AyanaDynamicGoalPlanner,
        resumeGoal: JSONObject?,
        automaticRecovery: Boolean,
        initialRuntimeContext: JSONObject? = null
    ) {
        val r10_19Session =
            initialRuntimeContext?.optBoolean("r10_19_acceptance", false) == true ||
                resumeGoal
                    ?.optJSONObject("dynamic_planner_runtime_context")
                    ?.optBoolean("r10_19_acceptance", false) == true

        val r10_14Session =
            !r10_19Session &&
                (
                    initialRuntimeContext?.optBoolean("r10_14_acceptance", false) == true ||
                        resumeGoal
                            ?.optJSONObject("dynamic_planner_runtime_context")
                            ?.optBoolean("r10_14_acceptance", false) == true
                )

        val r10_13Session =
            !r10_19Session &&
            !r10_14Session &&
                (
                    initialRuntimeContext?.optBoolean("r10_13_acceptance", false) == true ||
                        resumeGoal
                            ?.optJSONObject("dynamic_planner_runtime_context")
                            ?.optBoolean("r10_13_acceptance", false) == true
                )

        val r10_12Session =
            !r10_19Session &&
            !r10_14Session &&
            !r10_13Session &&
                (
                    initialRuntimeContext?.optBoolean("r10_12_acceptance", false) == true ||
                        resumeGoal
                            ?.optJSONObject("dynamic_planner_runtime_context")
                            ?.optBoolean("r10_12_acceptance", false) == true
                )

        val r10_11Session =
            !r10_19Session &&
            !r10_14Session &&
            !r10_13Session &&
            !r10_12Session &&
                (
                    initialRuntimeContext?.optBoolean("r10_11_acceptance", false) == true ||
                        resumeGoal
                            ?.optJSONObject("dynamic_planner_runtime_context")
                            ?.optBoolean("r10_11_acceptance", false) == true
                )

        executionPhase(
            phase =
                when {
                    r10_19Session && resumeGoal != null ->
                        "r10_19_autonomous_multi_app_tasks_2_0_resume"
                    r10_19Session ->
                        "r10_19_autonomous_multi_app_tasks_2_0_acceptance"
                    r10_14Session && resumeGoal != null ->
                        "r10_14_perception_process_isolation_resume"
                    r10_14Session ->
                        "r10_14_perception_process_isolation"
                    r10_13Session && resumeGoal != null ->
                        "r10_13_full_process_death_recovery_resume"
                    r10_13Session ->
                        "r10_13_full_process_death_recovery"
                    r10_12Session && resumeGoal != null ->
                        "r10_12_natural_lifecycle_recovery_resume"
                    r10_12Session ->
                        "r10_12_natural_lifecycle_recovery"
                    r10_11Session && resumeGoal != null ->
                        "r10_11_production_replan_recovery_resume"
                    r10_11Session ->
                        "r10_11_production_replan_recovery"
                    resumeGoal == null ->
                        "r10_10_production_dynamic_planner"
                    else ->
                        "r10_10_production_dynamic_planner_recovery"
                },
            executor =
                when {
                    r10_19Session ->
                        "dynamic_goal_planner_v1_2+long_objective_v1_1+adaptive_loop_v1_1+universal_ui_action_engine_v1_1"
                    r10_14Session ->
                        "perception_bridge_v1_1+process_death_recovery_v1_2+dynamic_goal_planner_v1_2+long_objective_v1_1"
                    r10_13Session ->
                        "process_death_recovery_v1_2+dynamic_goal_planner_v1_2+long_objective_v1_1"
                    r10_12Session ->
                        "lifecycle_recovery_v1_2+dynamic_goal_planner_v1_2+long_objective_v1_1"
                    r10_11Session ->
                        "dynamic_goal_planner_v1_2+long_objective_v1_1+durable_recovery"
                    else ->
                        "dynamic_goal_planner_v1_2+long_objective_v1_1"
                }
        )

        stopSherpaListening()
        listenMode = ListenMode.BUSY

        broadcastStatus(
            if (resumeGoal == null) {
                "Выполняю длинную автономную цель…"
            } else {
                "Продолжаю сохранённую автономную цель…"
            },
            STATE_EXECUTING
        )

        updateNotification(
            if (resumeGoal == null) {
                "AYANA выполняет production planner objective…"
            } else {
                "AYANA восстанавливает production planner objective…"
            }
        )

        val commandToken = activeCommandToken

        val worker =
            thread(
                start = false,
                name = "AyanaR10_10ProductionPlanner"
            ) {
                var goalId: String? = null

                try {
                    val goalSnapshot =
                        if (resumeGoal == null) {
                            val created =
                                durableGoalStore.startGoal(
                                    command = command,
                                    source = if (silent) "text" else "voice",
                                    mode = AyanaDurableGoalStore.MODE_ORCHESTRATOR,
                                    safeAutoResume = true
                                )
                            goalId =
                                created
                                    .optString("id")
                                    .trim()
                                    .takeIf { it.isNotBlank() }

                            if (goalId == null) {
                                throw IllegalStateException(
                                    "R10.10 production durable goal_id was not created"
                                )
                            }
                            created
                        } else {
                            goalId =
                                resumeGoal
                                    .optString("id")
                                    .trim()
                                    .takeIf { it.isNotBlank() }

                            if (goalId == null) {
                                throw IllegalStateException(
                                    "R10.10 recovery durable goal_id missing"
                                )
                            }
                            JSONObject(resumeGoal.toString())
                        }

                    currentDurableGoalId = goalId

                    if (
                        resumeGoal != null &&
                        goalSnapshot.optBoolean("step_in_flight", false)
                    ) {
                        val reason =
                            "R10.10 recovery остановлен: предыдущий subgoal был in-flight; blind replay запрещён."

                        durableGoalStore.markPaused(
                            goalId,
                            reason
                        )

                        commandHistoryStore.addEvent(
                            activeCommandHistoryId,
                            state = "r10_10_inflight_recovery_paused",
                            message = "Production planner не повторил неопределённый in-flight subgoal",
                            details =
                                "goal_id=${goalId.orEmpty()}; step=${goalSnapshot.optString("last_step_id")}; " +
                                    "executor=${goalSnapshot.optString("last_step_action")}"
                        )

                        mainHandler.post {
                            if (
                                !isCommandCancelled(commandToken) &&
                                commandToken == activeCommandToken
                            ) {
                                respondAndResume(
                                    text = reason,
                                    silent = silent,
                                    success = false,
                                    technical =
                                        JSONObject()
                                            .put("production_dynamic_planner", true)
                                            .put("recovery", true)
                                            .put("blind_replay_allowed", false)
                                            .put("step_in_flight", true)
                                            .put("goal_id", goalId.orEmpty())
                                            .toString()
                                )
                            }
                        }
                        return@thread
                    }

                    val initialScreen =
                        try {
                            screenIntelligence.getScreenState()
                        } catch (_: Exception) {
                            JSONObject()
                        }

                    val initialState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            initialScreen.toString()
                        )

                    var adaptiveLoop =
                        if (resumeGoal == null) {
                            AyanaAdaptiveExecutionLoop.create(
                                objective = command,
                                stateFingerprint = initialState,
                                executionLane =
                                    AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                                authorityContext =
                                    AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                            )
                        } else {
                            AyanaAdaptiveExecutionLoop.restore(
                                snapshot =
                                    goalSnapshot.optJSONObject(
                                        "adaptive_execution_loop"
                                    ),
                                fallbackObjective = command,
                                fallbackExecutionLane =
                                    AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                                fallbackAuthorityContext =
                                    AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                            )
                        }

                    var continuity =
                        if (resumeGoal == null) {
                            AyanaCrossLaneAdaptiveContinuity.create(
                                objective = command,
                                adaptiveLoop = adaptiveLoop,
                                initialLane =
                                    AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                                initialAuthority =
                                    AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE,
                                authorityCeiling =
                                    AyanaCrossLaneAdaptiveContinuity.defaultUnifiedAuthorityCeiling()
                            )
                        } else {
                            AyanaCrossLaneAdaptiveContinuity.restore(
                                snapshot =
                                    goalSnapshot.optJSONObject(
                                        "cross_lane_continuity"
                                    ),
                                fallbackObjective = command,
                                adaptiveLoop = adaptiveLoop,
                                fallbackAuthorityCeiling =
                                    AyanaCrossLaneAdaptiveContinuity.defaultUnifiedAuthorityCeiling()
                            )
}

                    var longObjective =
                        if (resumeGoal == null) {
                            AyanaLongObjectiveCoordinator.create(
                                objectiveId = continuity.objectiveId(),
                                objective = command,
                                specs = planner.toLongObjectiveSpecs()
                            )
                        } else {
                            AyanaLongObjectiveCoordinator.restore(
                                goalSnapshot.optJSONObject(
                                    "long_objective_plan"
                                )
                            )
                        }

                    val runtimeContext =
                        goalSnapshot
                            .optJSONObject("dynamic_planner_runtime_context")
                            ?.let { JSONObject(it.toString()) }
                            ?: initialRuntimeContext
                                ?.let { JSONObject(it.toString()) }
                            ?: JSONObject()

                    if (
                        runtimeContext
                            .optString("origin_command_history_id")
                            .isBlank()
                    ) {
                        activeCommandHistoryId
                            ?.trim()
                            ?.takeIf { it.isNotBlank() }
                            ?.let { historyId ->
                                runtimeContext.put(
                                    "origin_command_history_id",
                                    historyId
                                )
                            }
                    }

                    if (resumeGoal != null) {
                        val persistedPlanner =
                            AyanaDynamicGoalPlanner.restore(
                                goalSnapshot.optJSONObject(
                                    "dynamic_planner_plan"
                                )
                            )

                        if (
                            persistedPlanner.planFingerprint() !=
                            planner.planFingerprint()
                        ) {
                            throw IllegalStateException(
                                "R10.10 planner fingerprint mismatch on recovery"
                            )
                        }

                        val crossRestore =
                            crossLaneRecoveryContinuity.verifyRestored(
                                persistedGoal = goalSnapshot,
                                adaptiveLoop = adaptiveLoop,
                                continuity = continuity
                            )

                        val longRestore =
                            longObjective.verifyRestoredAgainst(
                                goalSnapshot.optJSONObject(
                                    "long_objective_plan"
                                )
                            )

                        if (
                            !crossRestore.optBoolean("verified", false) ||
                            !longRestore.optBoolean("verified", false)
                        ) {
                            throw IllegalStateException(
                                "R10.10 persisted planner/continuity state failed recovery verification"
                            )
                        }

                        if (runtimeContext.optBoolean("r10_14_acceptance", false)) {
                            val lifecycleRestore =
                                lifecycleRecoveryCoordinator.verifyRestoredLifecycle(
                                    goal = goalSnapshot,
                                    currentServiceInstanceId = serviceInstanceId,
                                    currentProcessId = android.os.Process.myPid(),
                                    currentProcessEpochId = processEpochId
                                )

                            val preVerified =
                                runtimeContext.optInt("r10_14_pre_death_verified_prefix", -1)
                            val prePlanRevision =
                                runtimeContext.optInt("r10_14_pre_death_plan_revision", -1)
                            val preAdaptiveRevision =
                                runtimeContext.optInt("r10_14_pre_death_adaptive_revision", -1)
                            val prePartialFingerprint =
                                runtimeContext.optString("r10_14_pre_death_partial_fingerprint")
                            val restoredPartial =
                                longObjective.partialResult("page_title")

                            val browserReplayProbe =
                                longObjective.beginSubgoal(
                                    subgoalId = "open_example",
                                    lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                                    authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                                )
                            val visualReplayProbe =
                                longObjective.beginSubgoal(
                                    subgoalId = "read_title",
                                    lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                                    authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                                )

                            val browserReplayBlocked =
                                !browserReplayProbe.optBoolean("allowed", true) &&
                                    browserReplayProbe.optString("reason") ==
                                    "verified_subgoal_replay_blocked"
                            val visualReplayBlocked =
                                !visualReplayProbe.optBoolean("allowed", true) &&
                                    visualReplayProbe.optString("reason") ==
                                    "verified_subgoal_replay_blocked"

                            val bridgeStatus =
                                try {
                                    perceptionBridge.status()
                                } catch (_: Throwable) {
                                    JSONObject()
                                }

                            val originPerceptionPid =
                                runtimeContext.optInt("r10_14_origin_perception_process_id", -1)
                            val restoredPerceptionPid =
                                bridgeStatus.optInt("perception_process_id", -1)
                            val originPerceptionEpoch =
                                runtimeContext.optString("r10_14_origin_perception_process_epoch_id")
                            val restoredPerceptionEpoch =
                                bridgeStatus.optString("perception_process_epoch_id")
                            val perceptionProcessSurvived =
                                originPerceptionPid > 0 &&
                                    restoredPerceptionPid == originPerceptionPid &&
                                    originPerceptionEpoch.isNotBlank() &&
                                    restoredPerceptionEpoch == originPerceptionEpoch

                            val expectedBrowserPackage =
                                runtimeContext.optString("browser_package").trim()
                            val observedForegroundPackage =
                                bridgeStatus.optString("effective_foreground_package").trim()
                            val crossProcessScreenEvidenceVerified =
                                bridgeStatus.optBoolean("accessibility_connected", false) &&
                                    bridgeStatus.optBoolean("screen_evidence_available", false) &&
                                    expectedBrowserPackage.isNotBlank() &&
                                    observedForegroundPackage == expectedBrowserPackage

                            val diskOnlyRestoreVerified =
                                lifecycleRestore.optBoolean("verified", false) &&
                                    lifecycleRestore.optBoolean("process_recreated", false) &&
                                    lifecycleRestore.optBoolean("process_epoch_recreated", false) &&
                                    automaticRecovery

                            runtimeContext
                                .put("r10_14_lifecycle_restore_verified",
                                    lifecycleRestore.optBoolean("verified", false))
                                .put("r10_14_service_instance_recreated",
                                    lifecycleRestore.optBoolean("service_instance_recreated", false))
                                .put("r10_14_process_recreated",
                                    lifecycleRestore.optBoolean("process_recreated", false))
                                .put("r10_14_process_epoch_recreated",
                                    lifecycleRestore.optBoolean("process_epoch_recreated", false))
                                .put("r10_14_current_service_instance_id", serviceInstanceId)
                                .put("r10_14_current_process_id", android.os.Process.myPid())
                                .put("r10_14_current_process_epoch_id", processEpochId)
                                .put("r10_14_disk_only_restore_verified", diskOnlyRestoreVerified)
                                .put("r10_14_restored_perception_process_id", restoredPerceptionPid)
                                .put("r10_14_restored_perception_process_epoch_id", restoredPerceptionEpoch)
                                .put("r10_14_perception_process_survived_main_process_death", perceptionProcessSurvived)
                                .put("r10_14_bridge_reconnected_after_process_death",
                                    bridgeStatus.optBoolean("success", false))
                                .put("r10_14_accessibility_continuity_verified",
                                    bridgeStatus.optBoolean("accessibility_connected", false))
                                .put("r10_14_cross_process_screen_evidence_verified", crossProcessScreenEvidenceVerified)
                                .put("r10_14_observed_foreground_package_after_process_death", observedForegroundPackage)
                                .put("r10_14_verified_prefix_preserved_after_process_death",
                                    preVerified >= 0 &&
                                        longObjective.verifiedSubgoalCount() == preVerified)
                                .put("r10_14_plan_revision_preserved_after_process_death",
                                    prePlanRevision >= 0 &&
                                        longObjective.planRevision() == prePlanRevision)
                                .put("r10_14_adaptive_revision_preserved_after_process_death",
                                    preAdaptiveRevision >= 0 &&
                                        adaptiveLoop.currentRevision() == preAdaptiveRevision)
                                .put("r10_14_partial_result_preserved_after_process_death",
                                    prePartialFingerprint.isNotBlank() &&
                                        restoredPartial.optBoolean("available", false) &&
                                        restoredPartial.optBoolean("verified", false) &&
                                        restoredPartial.optString("fingerprint") == prePartialFingerprint)
                                .put("r10_14_browser_replay_blocked_after_process_death", browserReplayBlocked)
                                .put("r10_14_visual_replay_blocked_after_process_death", visualReplayBlocked)
                                .put("r10_14_background_auto_resume", automaticRecovery)
                                .put("r10_14_external_ui_continuation_proven", false)

                            commandHistoryStore.addEvent(
                                activeCommandHistoryId,
                                state = "r10_14_restore_gate_diagnostic",
                                message = "R10.14.2 restore gates evaluated before continuation",
                                details =
                                    JSONObject()
                                        .put("lifecycle", lifecycleRestore)
                                        .put("bridge", bridgeStatus)
                                        .put("perception_process_survived", perceptionProcessSurvived)
                                        .put("cross_process_screen_evidence_verified", crossProcessScreenEvidenceVerified)
                                        .put("verified_prefix_preserved", runtimeContext.optBoolean("r10_14_verified_prefix_preserved_after_process_death", false))
                                        .put("plan_revision_preserved", runtimeContext.optBoolean("r10_14_plan_revision_preserved_after_process_death", false))
                                        .put("adaptive_revision_preserved", runtimeContext.optBoolean("r10_14_adaptive_revision_preserved_after_process_death", false))
                                        .put("partial_result_preserved", runtimeContext.optBoolean("r10_14_partial_result_preserved_after_process_death", false))
                                        .put("browser_replay_blocked", browserReplayBlocked)
                                        .put("visual_replay_blocked", visualReplayBlocked)
                                        .put("automatic_recovery", automaticRecovery)
                                        .toString()
                                        .take(4200)
                            )

                            if (
                                !lifecycleRestore.optBoolean("verified", false) ||
                                !lifecycleRestore.optBoolean("process_recreated", false) ||
                                !lifecycleRestore.optBoolean("process_epoch_recreated", false) ||
                                !diskOnlyRestoreVerified ||
                                !perceptionProcessSurvived ||
                                !bridgeStatus.optBoolean("accessibility_connected", false) ||
                                !crossProcessScreenEvidenceVerified ||
                                !runtimeContext.optBoolean("r10_14_verified_prefix_preserved_after_process_death", false) ||
                                !runtimeContext.optBoolean("r10_14_plan_revision_preserved_after_process_death", false) ||
                                !runtimeContext.optBoolean("r10_14_adaptive_revision_preserved_after_process_death", false) ||
                                !runtimeContext.optBoolean("r10_14_partial_result_preserved_after_process_death", false) ||
                                !browserReplayBlocked ||
                                !visualReplayBlocked ||
                                !automaticRecovery
                            ) {
                                throw IllegalStateException(
                                    "R10.14 perception/process-death restore verification failed"
                                )
                            }

                            commandHistoryStore.addEvent(
                                activeCommandHistoryId,
                                state = "r10_14_perception_bridge_restore_verified",
                                message = "R10.14 подтвердил новый main process и живой :perception bridge",
                                details =
                                    JSONObject()
                                        .put("lifecycle", lifecycleRestore)
                                        .put("bridge", bridgeStatus)
                                        .put("perception_process_survived", perceptionProcessSurvived)
                                        .put("cross_process_screen_evidence_verified", crossProcessScreenEvidenceVerified)
                                        .toString()
                                        .take(3200)
                            )
                        }

                        if (runtimeContext.optBoolean("r10_13_acceptance", false)) {
                            val lifecycleRestore =
                                lifecycleRecoveryCoordinator.verifyRestoredLifecycle(
                                    goal = goalSnapshot,
                                    currentServiceInstanceId = serviceInstanceId,
                                    currentProcessId = android.os.Process.myPid(),
                                    currentProcessEpochId = processEpochId
                                )

                            val preVerified =
                                runtimeContext.optInt("r10_13_pre_death_verified_prefix", -1)
                            val prePlanRevision =
                                runtimeContext.optInt("r10_13_pre_death_plan_revision", -1)
                            val preAdaptiveRevision =
                                runtimeContext.optInt("r10_13_pre_death_adaptive_revision", -1)
                            val prePartialFingerprint =
                                runtimeContext.optString("r10_13_pre_death_partial_fingerprint")
                            val restoredPartial =
                                longObjective.partialResult("page_title")

                            val browserReplayProbe =
                                longObjective.beginSubgoal(
                                    subgoalId = "open_example",
                                    lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                                    authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                                )
                            val visualReplayProbe =
                                longObjective.beginSubgoal(
                                    subgoalId = "read_title",
                                    lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                                    authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                                )

                            val browserReplayBlocked =
                                !browserReplayProbe.optBoolean("allowed", true) &&
                                    browserReplayProbe.optString("reason") ==
                                    "verified_subgoal_replay_blocked"
                            val visualReplayBlocked =
                                !visualReplayProbe.optBoolean("allowed", true) &&
                                    visualReplayProbe.optString("reason") ==
                                    "verified_subgoal_replay_blocked"

                            val diskOnlyRestoreVerified =
                                lifecycleRestore.optBoolean("verified", false) &&
                                    lifecycleRestore.optBoolean("process_recreated", false) &&
                                    lifecycleRestore.optBoolean("process_epoch_recreated", false) &&
                                    automaticRecovery

                            runtimeContext
                                .put("r10_13_lifecycle_restore_verified",
                                    lifecycleRestore.optBoolean("verified", false))
                                .put("r10_13_service_instance_recreated",
                                    lifecycleRestore.optBoolean("service_instance_recreated", false))
                                .put("r10_13_process_recreated",
                                    lifecycleRestore.optBoolean("process_recreated", false))
                                .put("r10_13_process_epoch_recreated",
                                    lifecycleRestore.optBoolean("process_epoch_recreated", false))
                                .put("r10_13_current_service_instance_id", serviceInstanceId)
                                .put("r10_13_current_process_id", android.os.Process.myPid())
                                .put("r10_13_current_process_epoch_id", processEpochId)
                                .put("r10_13_disk_only_restore_verified", diskOnlyRestoreVerified)
                                .put("r10_13_verified_prefix_preserved_after_process_death",
                                    preVerified >= 0 &&
                                        longObjective.verifiedSubgoalCount() == preVerified)
                                .put("r10_13_plan_revision_preserved_after_process_death",
                                    prePlanRevision >= 0 &&
                                        longObjective.planRevision() == prePlanRevision)
                                .put("r10_13_adaptive_revision_preserved_after_process_death",
                                    preAdaptiveRevision >= 0 &&
                                        adaptiveLoop.currentRevision() == preAdaptiveRevision)
                                .put("r10_13_partial_result_preserved_after_process_death",
                                    prePartialFingerprint.isNotBlank() &&
                                        restoredPartial.optBoolean("available", false) &&
                                        restoredPartial.optBoolean("verified", false) &&
                                        restoredPartial.optString("fingerprint") == prePartialFingerprint)
                                .put("r10_13_browser_replay_blocked_after_process_death",
                                    browserReplayBlocked)
                                .put("r10_13_visual_replay_blocked_after_process_death",
                                    visualReplayBlocked)
                                .put("r10_13_background_auto_resume", automaticRecovery)

                            if (
                                !lifecycleRestore.optBoolean("verified", false) ||
                                !lifecycleRestore.optBoolean("process_recreated", false) ||
                                !lifecycleRestore.optBoolean("process_epoch_recreated", false) ||
                                !diskOnlyRestoreVerified ||
                                !runtimeContext.optBoolean("r10_13_verified_prefix_preserved_after_process_death", false) ||
                                !runtimeContext.optBoolean("r10_13_plan_revision_preserved_after_process_death", false) ||
                                !runtimeContext.optBoolean("r10_13_adaptive_revision_preserved_after_process_death", false) ||
                                !runtimeContext.optBoolean("r10_13_partial_result_preserved_after_process_death", false) ||
                                !browserReplayBlocked ||
                                !visualReplayBlocked ||
                                !automaticRecovery
                            ) {
                                throw IllegalStateException(
                                    "R10.13 full process-death restore/replay verification failed"
                                )
                            }

                            commandHistoryStore.addEvent(
                                activeCommandHistoryId,
                                state = "r10_13_process_death_restore_verified",
                                message = "R10.13 подтвердил новый процесс и disk-only auto-resume",
                                details = lifecycleRestore.toString().take(2400)
                            )

                            // R10.13.2 correction: full process-death recovery must be proved
                            // independently from Samsung AccessibilityService rebinding latency.
                            // The acceptance DAG deliberately leaves only a local Agent Core
                            // device-state suffix after the disk-only restore. UI-control after
                            // total process death is a separate perception-process milestone.
                            runtimeContext
                                .put("r10_13_post_process_readiness_required", false)
                                .put("r10_13_post_process_suffix_accessibility_independent", true)
                                .put("r10_13_post_process_ui_control_required", false)
                                .put("r10_13_external_ui_continuation_proven", false)

                            commandHistoryStore.addEvent(
                                activeCommandHistoryId,
                                state = "r10_13_process_death_local_suffix_ready",
                                message = "R10.13.2 disk-only restore подтверждён; продолжаю только Accessibility-independent suffix",
                                details =
                                    "verified_prefix=${longObjective.verifiedSubgoalCount()}; " +
                                        "remaining=${longObjective.subgoalCount() - longObjective.verifiedSubgoalCount()}; " +
                                        "ui_control_required=false"
                            )
                        }

                        if (runtimeContext.optBoolean("r10_12_acceptance", false)) {
                            val lifecycleRestore =
                                lifecycleRecoveryCoordinator.verifyRestoredLifecycle(
                                    goal = goalSnapshot,
                                    currentServiceInstanceId = serviceInstanceId,
                                    currentProcessId = android.os.Process.myPid(),
                                    currentProcessEpochId = processEpochId
                                )

                            val preVerified =
                                runtimeContext.optInt("r10_12_pre_recreation_verified_prefix", -1)
                            val prePlanRevision =
                                runtimeContext.optInt("r10_12_pre_recreation_plan_revision", -1)
                            val preAdaptiveRevision =
                                runtimeContext.optInt("r10_12_pre_recreation_adaptive_revision", -1)
                            val prePartialFingerprint =
                                runtimeContext.optString("r10_12_pre_recreation_partial_fingerprint")
                            val restoredPartial =
                                longObjective.partialResult("page_title")

                            val browserReplayProbe =
                                longObjective.beginSubgoal(
                                    subgoalId = "open_example",
                                    lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                                    authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                                )
                            val visualReplayProbe =
                                longObjective.beginSubgoal(
                                    subgoalId = "read_title",
                                    lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                                    authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                                )

                            val browserReplayBlocked =
                                !browserReplayProbe.optBoolean("allowed", true) &&
                                    browserReplayProbe.optString("reason") ==
                                    "verified_subgoal_replay_blocked"
                            val visualReplayBlocked =
                                !visualReplayProbe.optBoolean("allowed", true) &&
                                    visualReplayProbe.optString("reason") ==
                                    "verified_subgoal_replay_blocked"

                            runtimeContext
                                .put("r10_12_lifecycle_restore_verified",
                                    lifecycleRestore.optBoolean("verified", false))
                                .put("r10_12_service_instance_recreated",
                                    lifecycleRestore.optBoolean("service_instance_recreated", false))
                                .put("r10_12_process_recreated",
                                    lifecycleRestore.optBoolean("process_recreated", false))
                                .put("r10_12_current_service_instance_id", serviceInstanceId)
                                .put("r10_12_current_process_id", android.os.Process.myPid())
                                .put("r10_12_verified_prefix_preserved_after_recreation",
                                    preVerified >= 0 &&
                                        longObjective.verifiedSubgoalCount() == preVerified)
                                .put("r10_12_plan_revision_preserved_after_recreation",
                                    prePlanRevision >= 0 &&
                                        longObjective.planRevision() == prePlanRevision)
                                .put("r10_12_adaptive_revision_preserved_after_recreation",
                                    preAdaptiveRevision >= 0 &&
                                        adaptiveLoop.currentRevision() == preAdaptiveRevision)
                                .put("r10_12_partial_result_preserved_after_recreation",
                                    prePartialFingerprint.isNotBlank() &&
                                        restoredPartial.optBoolean("available", false) &&
                                        restoredPartial.optBoolean("verified", false) &&
                                        restoredPartial.optString("fingerprint") == prePartialFingerprint)
                                .put("r10_12_browser_replay_blocked_after_recreation",
                                    browserReplayBlocked)
                                .put("r10_12_visual_replay_blocked_after_recreation",
                                    visualReplayBlocked)
                                .put("r10_12_background_auto_resume", automaticRecovery)

                            if (
                                !lifecycleRestore.optBoolean("verified", false) ||
                                !runtimeContext.optBoolean("r10_12_verified_prefix_preserved_after_recreation", false) ||
                                !runtimeContext.optBoolean("r10_12_plan_revision_preserved_after_recreation", false) ||
                                !runtimeContext.optBoolean("r10_12_adaptive_revision_preserved_after_recreation", false) ||
                                !runtimeContext.optBoolean("r10_12_partial_result_preserved_after_recreation", false) ||
                                !browserReplayBlocked ||
                                !visualReplayBlocked ||
                                !automaticRecovery
                            ) {
                                throw IllegalStateException(
                                    "R10.12 lifecycle restore/replay verification failed"
                                )
                            }

                            commandHistoryStore.addEvent(
                                activeCommandHistoryId,
                                state = "r10_12_lifecycle_restore_verified",
                                message = "R10.12 подтвердил реальное пересоздание Service и безопасный auto-resume",
                                details = lifecycleRestore.toString().take(2200)
                            )
                        }

                        if (runtimeContext.optBoolean("r10_11_acceptance", false)) {
                            val preVerified =
                                runtimeContext.optInt("r10_11_pre_restart_verified_prefix", -1)
                            val prePlanRevision =
                                runtimeContext.optInt("r10_11_pre_restart_plan_revision", -1)
                            val preAdaptiveRevision =
                                runtimeContext.optInt("r10_11_pre_restart_adaptive_revision", -1)
                            val prePartialFingerprint =
                                runtimeContext.optString("r10_11_pre_restart_partial_fingerprint")
                            val restoredPartial =
                                longObjective.partialResult("page_title")

                            runtimeContext
                                .put("r10_11_restore_verified", true)
                                .put(
                                    "r10_11_verified_prefix_preserved_after_restart",
                                    preVerified >= 0 &&
                                        longObjective.verifiedSubgoalCount() == preVerified
                                )
                                .put(
                                    "r10_11_plan_revision_preserved_after_restart",
                                    prePlanRevision >= 0 &&
                                        longObjective.planRevision() == prePlanRevision
                                )
                                .put(
                                    "r10_11_adaptive_revision_preserved_after_restart",
                                    preAdaptiveRevision >= 0 &&
                                        adaptiveLoop.currentRevision() == preAdaptiveRevision
                                )
                                .put(
                                    "r10_11_partial_result_preserved_after_restart",
                                    prePartialFingerprint.isNotBlank() &&
                                        restoredPartial.optBoolean("available", false) &&
                                        restoredPartial.optBoolean("verified", false) &&
                                        restoredPartial.optString("fingerprint") == prePartialFingerprint
                                )

                            val failedTool =
                                runtimeContext.optString("r10_11_failed_tool_name")
                            val failedArgs =
                                runtimeContext.optJSONObject("r10_11_failed_arguments")
                                    ?: JSONObject()
                            val failedBeforeState =
                                runtimeContext.optString("r10_11_failed_before_state")
                            val failedReplayProbe =
                                if (
                                    failedTool.isNotBlank() &&
                                    failedBeforeState.isNotBlank()
                                ) {
                                    adaptiveLoop.propose(
                                        toolName = failedTool,
                                        arguments = failedArgs,
                                        stateFingerprint = failedBeforeState,
                                        mayMutate = true,
                                        authoritySource =
                                            AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                                    )
                                } else {
                                    JSONObject()
                                        .put("allowed", true)
                                        .put("reason", "failed_replay_probe_context_missing")
                                }

                            val failedReplayBlocked =
                                !failedReplayProbe.optBoolean("allowed", true) &&
                                    failedReplayProbe.optString("reason") ==
                                    "failed_transition_replay_blocked"

                            val browserReplayProbe =
                                longObjective.beginSubgoal(
                                    subgoalId = "open_example",
                                    lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                                    authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                                )
                            val verifiedPrefixReplayBlocked =
                                !browserReplayProbe.optBoolean("allowed", true) &&
                                    browserReplayProbe.optString("reason") ==
                                    "verified_subgoal_replay_blocked"

                            val failedLedgerPreserved =
                                adaptiveLoop.failedTransitionCount() >
                                    runtimeContext.optInt(
                                        "r10_11_failed_transition_count_before",
                                        -1
                                    )

                            runtimeContext
                                .put(
                                    "r10_11_failed_transition_ledger_preserved_after_restart",
                                    failedLedgerPreserved
                                )
                                .put(
                                    "r10_11_failed_transition_replay_blocked_after_restart",
                                    failedReplayBlocked
                                )
                                .put(
                                    "r10_11_verified_prefix_replay_blocked_after_restart",
                                    verifiedPrefixReplayBlocked
                                )

                            if (
                                !failedLedgerPreserved ||
                                !failedReplayBlocked ||
                                !verifiedPrefixReplayBlocked
                            ) {
                                throw IllegalStateException(
                                    "R10.11 replay/recovery ledger verification failed"
                                )
                            }
                        }
                    }

                    val initialCheckpoint =
                        r10_10BuildProductionPlannerCheckpoint(
                            planner = planner,
                            longObjective = longObjective,
                            adaptiveLoop = adaptiveLoop,
                            continuity = continuity,
                            runtimeContext = runtimeContext,
                            checkpointTag =
                                when {
                                    r10_19Session && resumeGoal == null ->
                                        "r10_19_multi_app_started"
                                    r10_19Session ->
                                        "r10_19_multi_app_recovered"
                                    resumeGoal == null ->
                                        "r10_10_production_started"
                                    else ->
                                        "r10_10_production_recovered"
                                },
                            safeAutoResume = true,
                            stepInFlight = false,
                            lastStepId = "",
                            lastExecutor = ""
                        )

                    val initialPersisted =
                        durableGoalStore.checkpoint(
                            goalId,
                            initialCheckpoint
                        ) != null

                    if (!initialPersisted) {
                        throw IllegalStateException(
                            "R10.10 production start/recovery checkpoint not persisted"
                        )
                    }

                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state =
                            when {
                                r10_19Session && resumeGoal == null ->
                                    "r10_19_production_multi_app_plan_started"
                                r10_19Session ->
                                    "r10_19_production_multi_app_plan_restored"
                                resumeGoal == null ->
                                    "r10_10_production_plan_started"
                                else ->
                                    "r10_10_production_plan_restored"
                            },
                        message =
                            when {
                                r10_19Session && resumeGoal == null ->
                                    "R10.19 production planner принял проверенный 8-step multi-app DAG"
                                r10_19Session ->
                                    "R10.19 production planner восстановил проверенный multi-app DAG"
                                resumeGoal == null ->
                                    "R10.10 production planner принял проверенный DAG"
                                else ->
                                    "R10.10 production planner восстановил проверенный DAG"
                            },
                        details =
                            "goal_id=${goalId.orEmpty()}; fingerprint=${planner.planFingerprint()}; " +
                                "subgoals=${planner.subgoalCount()}; verified=${longObjective.verifiedSubgoalCount()}"
                    )

                    val result =
                        executeR10_10ProductionPlannerLoop(
                            goalId = goalId.orEmpty(),
                            command = command,
                            planner = planner,
                            longObjective = longObjective,
                            adaptiveLoop = adaptiveLoop,
                            continuity = continuity,
                            runtimeContext = runtimeContext,
                            commandToken = commandToken,
                            automaticRecovery = automaticRecovery
                        )

                    if (result.optBoolean("process_death_handoff_required", false)) {
                        val handoffGoalId =
                            result.optString("goal_id").trim()
                        val r10_14Handoff =
                            result.optBoolean("r10_14_acceptance", false)

                        commandHistoryStore.addEvent(
                            activeCommandHistoryId,
                            state =
                                if (r10_14Handoff) {
                                    "r10_14_main_process_death_requested"
                                } else {
                                    "r10_13_process_death_requested"
                                },
                            message =
                                if (r10_14Handoff) {
                                    "R10.14 останавливает main AYANA process; :perception должен остаться жив"
                                } else {
                                    "R10.13 запускает полную остановку текущего AYANA process"
                                },
                            details =
                                "goal_id=$handoffGoalId; service_instance=$serviceInstanceId; " +
                                    "process_id=${android.os.Process.myPid()}; process_epoch=$processEpochId"
                        )

                        scheduleR10_13ProcessDeath()
                        return@thread
                    }

                    if (result.optBoolean("service_recreation_handoff_required", false)) {
                        val handoffGoalId =
                            result.optString("goal_id").trim()

                        commandHistoryStore.addEvent(
                            activeCommandHistoryId,
                            state = "r10_12_service_recreation_requested",
                            message = "R10.12 запускает реальное пересоздание Android Service",
                            details =
                                "goal_id=$handoffGoalId; service_instance=$serviceInstanceId; " +
                                    "process_id=${android.os.Process.myPid()}"
                        )

                        scheduleR10_12ServiceRecreation()
                        return@thread
                    }

                    if (result.optBoolean("restart_handoff_required", false)) {
                        val handoffGoal = result.optJSONObject("resume_goal")
                            ?: throw IllegalStateException(
                                "R10.11 durable recovery handoff snapshot missing"
                            )

                        commandHistoryStore.addEvent(
                            activeCommandHistoryId,
                            state = "r10_11_recovery_worker_handoff",
                            message = "R10.11 продолжает production objective из переоткрытого DurableGoalStore",
                            details =
                                "goal_id=${handoffGoal.optString("id")}; " +
                                    "recovery=${handoffGoal.optInt("recovery_count", 0)}; " +
                                    "checkpoint=${handoffGoal.optString("last_checkpoint")}"
                        )

                        mainHandler.post {
                            if (
                                !isCommandCancelled(commandToken) &&
                                commandToken == activeCommandToken
                            ) {
                                resumeR10_10ProductionDynamicPlanner(
                                    goal = handoffGoal,
                                    silent = silent,
                                    automaticRecovery = true
                                )
                            }
                        }
                        return@thread
                    }

                    val success =
                        result.optBoolean("success", false) &&
                            result.optBoolean("verified", false) &&
                            result.optBoolean("terminal_verified", false)

                    val r10_19Result =
                        result.optBoolean("r10_19_acceptance", false)
                    val r10_14Result =
                        !r10_19Result &&
                            result.optBoolean("r10_14_acceptance", false)
                    val r10_13Result =
                        !r10_19Result &&
                        !r10_14Result &&
                            result.optBoolean("r10_13_acceptance", false)
                    val r10_12Result =
                        !r10_19Result &&
                        !r10_14Result &&
                        !r10_13Result &&
                            result.optBoolean("r10_12_acceptance", false)
                    val r10_11Result =
                        !r10_19Result &&
                        !r10_14Result &&
                        !r10_13Result &&
                        !r10_12Result &&
                            result.optBoolean("r10_11_acceptance", false)

                    if (success) {
                        durableGoalStore.markCompleted(
                            goalId,
                            when {
                                r10_19Result ->
                                    "R10.19 autonomous multi-app tasks 2.0 verified ${result.optInt("verified_subgoal_count", 0)}/${result.optInt("subgoal_count", 0)}"
                                r10_14Result ->
                                    "R10.14 perception-process isolation verified ${result.optInt("verified_subgoal_count", 0)}/${result.optInt("subgoal_count", 0)}"
                                r10_13Result ->
                                    "R10.13 full process-death recovery verified ${result.optInt("verified_subgoal_count", 0)}/${result.optInt("subgoal_count", 0)}"
                                r10_12Result ->
                                    "R10.12 natural lifecycle recovery verified ${result.optInt("verified_subgoal_count", 0)}/${result.optInt("subgoal_count", 0)}"
                                r10_11Result ->
                                    "R10.11 production replan/recovery verified ${result.optInt("verified_subgoal_count", 0)}/${result.optInt("subgoal_count", 0)}"
                                else ->
                                    "R10.10 production dynamic planner objective verified ${result.optInt("verified_subgoal_count", 0)}/${result.optInt("subgoal_count", 0)}"
                            }
                        )
                    } else {
                        durableGoalStore.markPaused(
                            goalId,
                            result.optString(
                                "reason",
                                when {
                                    r10_19Result ->
                                        "R10.19 autonomous multi-app tasks 2.0 stopped fail-closed"
                                    r10_14Result ->
                                        "R10.14 perception-process isolation stopped fail-closed"
                                    r10_13Result ->
                                        "R10.13 full process-death recovery stopped fail-closed"
                                    r10_12Result ->
                                        "R10.12 lifecycle recovery stopped fail-closed"
                                    r10_11Result ->
                                        "R10.11 production replan/recovery stopped fail-closed"
                                    else ->
                                        "R10.10 production planner stopped fail-closed"
                                }
                            )
                        )
                    }

                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state =
                            when {
                                r10_19Result && success ->
                                    "r10_19_autonomous_multi_app_tasks_2_0_verified"
                                r10_19Result ->
                                    "r10_19_autonomous_multi_app_tasks_2_0_not_verified"
                                r10_14Result && success ->
                                    "r10_14_perception_process_isolation_verified"
                                r10_14Result ->
                                    "r10_14_perception_process_isolation_not_verified"
                                r10_13Result && success ->
                                    "r10_13_full_process_death_recovery_verified"
                                r10_13Result ->
                                    "r10_13_full_process_death_recovery_not_verified"
                                r10_12Result && success ->
                                    "r10_12_natural_lifecycle_recovery_verified"
                                r10_12Result ->
                                    "r10_12_natural_lifecycle_recovery_not_verified"
                                r10_11Result && success ->
                                    "r10_11_production_replan_recovery_verified"
                                r10_11Result ->
                                    "r10_11_production_replan_recovery_not_verified"
                                success ->
                                    "r10_10_production_dynamic_objective_verified"
                                else ->
                                    "r10_10_production_dynamic_objective_paused"
                            },
                        message =
                            when {
                                r10_19Result && success ->
                                    "R10.19 production multi-app chain Browser -> YouTube -> Settings -> Calendar подтверждена"
                                r10_19Result ->
                                    "R10.19 production multi-app chain остановлена fail-closed"
                                r10_14Result && success ->
                                    "R10.14 perception process пережил смерть main process; внешний UI suffix продолжен через IPC"
                                r10_14Result ->
                                    "R10.14 perception-process isolation не прошёл все gates"
                                r10_13Result && success ->
                                    "R10.13 full process-death recovery + disk-only continuation подтверждён"
                                r10_13Result ->
                                    "R10.13 process-death recovery не прошёл все gates"
                                r10_12Result && success ->
                                    "R10.12 real Service lifecycle recovery + background continuation подтверждён"
                                r10_12Result ->
                                    "R10.12 lifecycle recovery не прошёл все gates"
                                r10_11Result && success ->
                                    "R10.11 production replan/recovery подтверждён"
                                r10_11Result ->
                                    "R10.11 production replan/recovery не прошёл все gates"
                                success ->
                                    "R10.10 production planner завершил обычную пользовательскую цель"
                                else ->
                                    "R10.10 production planner остановил цель fail-closed"
                            },
                        details = result.toString().take(6200)
                    )

                    mainHandler.post {
                        if (
                            isCommandCancelled(commandToken) ||
                            commandToken != activeCommandToken
                        ) {
                            return@post
                        }

                        respondAndResume(
                            text =
                                when {
                                    r10_19Result && success ->
                                        "R10.19 подтверждён: 8/8 production subgoals VERIFIED. Browser title «${result.optString("r10_19_verified_title").take(80)}» передан по verified provenance в YouTube и Calendar DRAFT_ONLY; Universal UI шаг «Разрешения» подтверждён одним dispatch, AYANA восстановлена, blind mutation replay запрещён."
                                    r10_19Result ->
                                        "R10.19 выполнен fail-closed: автономная multi-app цепочка не прошла все обязательные verification gates."
                                    r10_14Result && success ->
                                        "R10.14 подтверждён: :perception пережил полную смерть main AYANA process, новый process восстановил objective с диска и продолжил внешний UI suffix через cross-process Accessibility без replay Browser/visual."
                                    r10_14Result ->
                                        "R10.14 выполнен fail-closed: cross-process perception continuity не подтверждена по всем обязательным gates."
                                    r10_13Result && success ->
                                        "R10.13 подтверждён: production objective пережил полную смену AYANA process и автоматически продолжил только незавершённый suffix из durable disk state без replay Browser/visual."
                                    r10_13Result ->
                                        "R10.13 выполнен fail-closed: полное process-death recovery не подтверждено по всем обязательным gates."
                                    r10_12Result && success ->
                                        "R10.12 подтверждён: production objective пережил реальное пересоздание Android Service и автоматически продолжил только незавершённый suffix без replay Browser/visual."
                                    r10_12Result ->
                                        "R10.12 выполнен fail-closed: lifecycle recovery не подтверждён по всем обязательным gates."
                                    r10_11Result && success ->
                                        "R10.11 подтверждён: production objective пережил verified failure, suffix replan и durable recovery без replay VERIFIED prefix."
                                    r10_11Result ->
                                        "R10.11 выполнен fail-closed: production replan/recovery не подтверждён по всем обязательным gates."
                                    success ->
                                        "Длинная автономная цель выполнена и подтверждена: ${result.optInt("verified_subgoal_count", 0)}/${result.optInt("subgoal_count", 0)} subgoals VERIFIED."
                                    else ->
                                        "Длинная автономная цель остановлена безопасно: ${result.optString("reason", "не подтверждён следующий шаг")}."
                                },
                            silent = silent,
                            success = success,
                            technical = result.toString()
                        )
                    }
                } catch (error: Exception) {
                    try {
                        durableGoalStore.markPaused(
                            goalId,
                            "R10.10 production planner exception: ${error.message ?: error.javaClass.simpleName}"
                        )
                    } catch (_: Exception) {
                    }

                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state = "r10_10_production_dynamic_objective_error",
                        message = "R10.10 production planner остановлен fail-closed",
                        details = (error.message ?: error.javaClass.simpleName).take(1200)
                    )

                    mainHandler.post {
                        if (
                            !isCommandCancelled(commandToken) &&
                            commandToken == activeCommandToken
                        ) {
                            respondAndResume(
                                text = "Длинная автономная цель остановлена: безопасное продолжение не подтверждено.",
                                silent = silent,
                                success = false,
                                technical =
                                    JSONObject()
                                        .put("production_dynamic_planner", true)
                                        .put("success", false)
                                        .put("verified", false)
                                        .put("terminal_verified", false)
                                        .put("blind_replay_allowed", false)
                                        .put("goal_id", goalId.orEmpty())
                                        .put(
                                            "error",
                                            error.message ?: error.javaClass.simpleName
                                        )
                                        .toString()
                            )
                        }
                    }
                } finally {
                    if (currentDurableGoalId == goalId) {
                        currentDurableGoalId = null
                    }

                    if (
                        Thread.currentThread() ===
                        currentAgentThread
                    ) {
                        currentAgentThread = null
                    }
                }
            }

        currentAgentThread = worker
        executionKernel.bindThread(worker)
        worker.start()
    }

    private fun executeR10_10ProductionPlannerLoop(
        goalId: String,
        command: String,
        planner: AyanaDynamicGoalPlanner,
        longObjective: AyanaLongObjectiveCoordinator,
        adaptiveLoop: AyanaAdaptiveExecutionLoop,
        continuity: AyanaCrossLaneAdaptiveContinuity,
        runtimeContext: JSONObject,
        commandToken: Long,
        automaticRecovery: Boolean
    ): JSONObject {
        var currentState =
            AyanaAdaptiveExecutionLoop.fingerprintState(
                try {
                    screenIntelligence.getScreenState().toString()
                } catch (_: Exception) {
                    runtimeContext.toString()
                }
            )

        var dispatchCount = runtimeContext.optInt("r10_11_dispatch_count", 0)
        var browserDispatchCount = runtimeContext.optInt("r10_11_browser_dispatch_count", 0)
        var visualReadCount = runtimeContext.optInt("r10_11_visual_read_count", 0)
        var replanAttemptCount = runtimeContext.optInt("r10_11_replan_attempt_count", 0)
        var replanAppliedCount = runtimeContext.optInt("r10_11_replan_applied_count", 0)
        var durableStepCheckpointCount = runtimeContext.optInt("r10_11_durable_checkpoint_count", 0)
        var lastFailure = ""

        for (subgoal in planner.subgoals()) {
            if (
                isCommandCancelled(commandToken) ||
                commandToken != activeCommandToken
            ) {
                return JSONObject()
                    .put("production_dynamic_planner", true)
                    .put("success", false)
                    .put("verified", false)
                    .put("terminal_verified", false)
                    .put("cancelled", true)
                    .put("reason", "command_cancelled")
                    .put("goal_id", goalId)
                    .put("blind_replay_allowed", false)
            }

            if (
                longObjective.statusOf(subgoal.id) ==
                AyanaLongObjectiveCoordinator.STATUS_VERIFIED
            ) {
                continue
            }

            if (
                longObjective.statusOf(subgoal.id) ==
                AyanaLongObjectiveCoordinator.STATUS_FAILED
            ) {
                replanAttemptCount++
                runtimeContext.put("r10_11_replan_attempt_count", replanAttemptCount)
                val replan =
                    r10_10AttemptProductionSuffixReplan(
                        command = command,
                        planner = planner,
                        longObjective = longObjective,
                        adaptiveLoop = adaptiveLoop,
failedSubgoalId = subgoal.id,
                        failureReason = "persisted_failed_subgoal",
                        stateFingerprint = currentState
                    )

                if (replan.optBoolean("applied", false)) {
                    replanAppliedCount++
                    runtimeContext.put("r10_11_replan_applied_count", replanAppliedCount)
                    return r10_11ContinueAfterAppliedReplan(
                        goalId = goalId,
                        command = command,
                        replan = replan,
                        longObjective = longObjective,
                        adaptiveLoop = adaptiveLoop,
                        continuity = continuity,
                        runtimeContext = runtimeContext,
                        commandToken = commandToken,
                        automaticRecovery = automaticRecovery,
                        dispatchCount = dispatchCount,
                        browserDispatchCount = browserDispatchCount,
                        visualReadCount = visualReadCount,
                        replanAttemptCount = replanAttemptCount,
                        replanAppliedCount = replanAppliedCount,
                        durableStepCheckpointCount = durableStepCheckpointCount
                    )
                } else {
                    lastFailure =
                        replan.optString(
                            "reason",
                            "failed_subgoal_requires_new_plan"
                        )
                    break
                }
            }

            val begin =
                longObjective.beginSubgoal(
                    subgoalId = subgoal.id,
                    lane = subgoal.lane,
                    authority = subgoal.authority
                )

            if (!begin.optBoolean("allowed", false)) {
                lastFailure =
                    begin.optString(
                        "reason",
                        "subgoal_begin_blocked"
                    )
                break
            }

            val laneGate =
                continuity.transitionTo(
                    adaptiveLoop = adaptiveLoop,
                    targetLane = subgoal.lane,
                    targetAuthority = subgoal.authority,
                    stateFingerprint = currentState,
                    reason = "r10_10_production:${subgoal.id}"
                )

            if (!laneGate.optBoolean("allowed", false)) {
                longObjective.recordFailure(
                    subgoal.id,
                    laneGate.optString(
                        "reason",
                        "lane_transition_blocked"
                    )
                )
                lastFailure =
                    laneGate.optString(
                        "reason",
                        "lane_transition_blocked"
                    )
                break
            }

            val executorContract =
                AyanaDynamicGoalPlanner.executorRegistry()[subgoal.executor]

            if (executorContract == null) {
                longObjective.recordFailure(
                    subgoal.id,
                    "registered_executor_missing"
                )
                lastFailure = "registered_executor_missing"
                break
            }

            val plannerArguments =
                planner.argumentsFor(
                    subgoal.id
                )

            val adaptiveToolName =
                r10_10AdaptiveToolName(
                    subgoal.executor
                )

            val adaptiveArguments =
                r10_10AdaptiveArguments(
                    executor = subgoal.executor,
                    plannerArguments = plannerArguments,
                    longObjective = longObjective,
                    subgoalId = subgoal.id,
                    runtimeContext = runtimeContext
                )

            val proposal =
                adaptiveLoop.propose(
                    toolName = adaptiveToolName,
                    arguments = adaptiveArguments,
                    stateFingerprint = currentState,
                    mayMutate = executorContract.mayMutateRuntime,
                    authoritySource = subgoal.authority
                )

            if (!proposal.optBoolean("allowed", false)) {
                longObjective.recordFailure(
                    subgoal.id,
                    proposal.optString(
                        "reason",
                        "adaptive_proposal_blocked"
                    )
                )
                lastFailure =
                    proposal.optString(
                        "reason",
                        "adaptive_proposal_blocked"
                    )
                break
            }

            val beforeDispatch =
                r10_10BuildProductionPlannerCheckpoint(
                    planner = planner,
                    longObjective = longObjective,
                    adaptiveLoop = adaptiveLoop,
                    continuity = continuity,
                    runtimeContext = runtimeContext,
                    checkpointTag =
                        "r10_10_before_${subgoal.id}",
                    safeAutoResume = false,
                    stepInFlight = true,
                    lastStepId = subgoal.id,
                    lastExecutor = subgoal.executor
                )

            if (
                durableGoalStore.checkpoint(
                    goalId,
                    beforeDispatch
                ) ==
                null
            ) {
                longObjective.recordFailure(
                    subgoal.id,
                    "pre_dispatch_checkpoint_failed"
                )
                lastFailure =
                    "pre_dispatch_checkpoint_failed"
                break
            }

            durableStepCheckpointCount++
            runtimeContext.put("r10_11_durable_checkpoint_count", durableStepCheckpointCount)

            if (
                runtimeContext.optBoolean("r10_11_acceptance", false) &&
                subgoal.executor == AyanaDynamicGoalPlanner.EXEC_YOUTUBE_SEARCH &&
                runtimeContext.optBoolean("r10_11_inject_youtube_failure_once", false) &&
                !runtimeContext.optBoolean("r10_11_youtube_failure_injected", false)
            ) {
                runtimeContext
                    .put("r10_11_failed_tool_name", adaptiveToolName)
                    .put("r10_11_failed_arguments", JSONObject(adaptiveArguments.toString()))
                    .put("r10_11_failed_before_state", currentState)
                    .put("r10_11_failed_transition_count_before", adaptiveLoop.failedTransitionCount())
            }

            val executorResult =
                executeR10_10RegisteredPlannerSubgoal(
                    planner = planner,
                    longObjective = longObjective,
                    subgoal = subgoal,
                    goalId = goalId,
                    commandToken = commandToken,
                    runtimeContext = runtimeContext
                )

            val actionDispatched =
                executorResult.optBoolean(
                    "action_dispatched",
                    false
                )

            if (actionDispatched) {
                dispatchCount++
                runtimeContext.put("r10_11_dispatch_count", dispatchCount)
            }

            if (
                subgoal.executor ==
                AyanaDynamicGoalPlanner.EXEC_BROWSER_OPEN_URL &&
                actionDispatched
            ) {
                browserDispatchCount++
                runtimeContext.put("r10_11_browser_dispatch_count", browserDispatchCount)
            }

            if (
                subgoal.executor ==
                AyanaDynamicGoalPlanner.EXEC_STRUCTURED_SCREEN_READ
            ) {
                visualReadCount++
                runtimeContext.put("r10_11_visual_read_count", visualReadCount)
            }

            val verified =
                executorResult.optBoolean("success", false) &&
                    executorResult.optBoolean(
                        "verified",
                        executorResult.optBoolean("success", false)
                    )

            val afterState =
                AyanaAdaptiveExecutionLoop.fingerprintState(
                    executorResult.toString()
                )

            val adaptiveRecord =
                adaptiveLoop.recordResult(
                    toolName = adaptiveToolName,
                    arguments = adaptiveArguments,
                    beforeStateFingerprint = currentState,
                    afterStateFingerprint = afterState,
                    success = verified,
                    verified = verified,
                    actionDispatched = actionDispatched,
                    actionCommitted =
                        executorResult.optBoolean(
                            "action_committed",
                            false
                        ),
                    reconciliationComplete =
                        executorResult.optBoolean(
                            "reconciliation_complete",
                            verified
                        ),
                    evidence =
                        executorResult.optString(
                            "message",
                            "R10.10 production planner subgoal result"
                        ),
                    failureLayer =
                        if (verified) {
                            ""
                        } else {
                            executorResult.optString(
                                "failure_layer",
                                "verification"
                            )
                        }
                )

            val resultValue =
                if (
                    subgoal.resultKey.isNotBlank() &&
                    verified
                ) {
                    executorResult
                        .optString("verified_result_value")
                        .trim()
                        .ifBlank {
                            executorResult
                                .optString("semantic_title")
                                .trim()
                        }
                } else {
                    ""
                }

            if (runtimeContext.optBoolean("r10_19_acceptance", false)) {
                when (subgoal.executor) {
                    AyanaDynamicGoalPlanner.EXEC_BROWSER_OPEN_URL ->
                        runtimeContext.put("r10_19_browser_verified", verified)

                    AyanaDynamicGoalPlanner.EXEC_STRUCTURED_SCREEN_READ ->
                        runtimeContext
                            .put("r10_19_structured_read_verified", verified)
                            .put("r10_19_verified_title", resultValue.take(240))

                    AyanaDynamicGoalPlanner.EXEC_YOUTUBE_SEARCH ->
                        runtimeContext.put("r10_19_youtube_verified", verified)

                    AyanaDynamicGoalPlanner.EXEC_APP_INFO ->
                        runtimeContext.put("r10_19_app_info_step_verified", verified)

                    AyanaDynamicGoalPlanner.EXEC_UNIVERSAL_UI_CLICK ->
                        runtimeContext.put("r10_19_permissions_step_verified", verified)

                    AyanaDynamicGoalPlanner.EXEC_CALENDAR_DRAFT ->
                        runtimeContext.put("r10_19_calendar_step_verified", verified)
                }

                if (subgoal.id == "r10_19_device_state_before") {
                    runtimeContext.put("r10_19_initial_device_state_verified", verified)
                }
                if (subgoal.id == "r10_19_device_state_after") {
                    runtimeContext.put("r10_19_final_device_state_verified", verified)
                }
            }

            if (verified) {
                longObjective.recordVerified(
                    subgoalId = subgoal.id,
                    lane = subgoal.lane,
                    authority = subgoal.authority,
                    evidence =
                        executorResult.optString(
                            "message",
                            "verified production subgoal"
                        ),
                    resultValue = resultValue
                )
            } else {
                longObjective.recordFailure(
                    subgoal.id,
                    executorResult.optString(
                        "reason",
                        executorResult.optString(
                            "message",
                            "subgoal_not_verified"
                        )
                    )
                )
            }

            val afterDispatch =
                r10_10BuildProductionPlannerCheckpoint(
                    planner = planner,
                    longObjective = longObjective,
                    adaptiveLoop = adaptiveLoop,
                    continuity = continuity,
                    runtimeContext = runtimeContext,
                    checkpointTag =
                        if (verified) {
                            "r10_10_verified_${subgoal.id}"
                        } else {
                            "r10_10_failed_${subgoal.id}"
                        },
                    safeAutoResume =
                        verified &&
                            !adaptiveLoop.hasUnresolvedSideEffect(),
                    stepInFlight = false,
                    lastStepId = subgoal.id,
                    lastExecutor = subgoal.executor
                )
                    .put(
                        "last_step_success",
                        verified
                    )
                    .put(
                        "last_step_status",
                        if (verified) {
                            "VERIFIED"
                        } else {
                            "FAILED"
                        }
                    )
                    .put(
                        "last_failure_layer",
                        if (verified) {
                            ""
                        } else {
                            executorResult.optString(
                                "failure_layer",
                                "verification"
                            )
                        }
                    )

            if (
                durableGoalStore.checkpoint(
                    goalId,
                    afterDispatch
                ) ==
                null
            ) {
                lastFailure =
                    "post_step_checkpoint_failed"
                break
            }

            durableStepCheckpointCount++
            runtimeContext.put("r10_11_durable_checkpoint_count", durableStepCheckpointCount)

            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state =
                    if (verified) {
                        "r10_10_production_subgoal_verified"
                    } else {
                        "r10_10_production_subgoal_failed"
                    },
                message =
                    if (verified) {
                        "Production planner subgoal VERIFIED: ${subgoal.id}"
                    } else {
                        "Production planner subgoal не подтверждён: ${subgoal.id}"
                    },
                details =
                    "executor=${subgoal.executor}; lane=${subgoal.lane}; " +
                        "adaptive_verified=${adaptiveRecord.optBoolean("verified", false)}; " +
                        "result=${executorResult.toString().take(1800)}"
            )

            if (
                verified &&
                runtimeContext.optBoolean("r10_14_acceptance", false) &&
                subgoal.id == "read_title" &&
                !runtimeContext.optBoolean("r10_14_process_death_requested", false)
            ) {
                val partial =
                    longObjective.partialResult("page_title")

                val bridgeStatus =
                    try {
                        perceptionBridge.status()
                    } catch (_: Throwable) {
                        JSONObject()
                    }

                val perceptionPid =
                    bridgeStatus.optInt("perception_process_id", -1)
                val perceptionEpoch =
                    bridgeStatus.optString("perception_process_epoch_id")
                val expectedBrowserPackage =
                    runtimeContext.optString("browser_package").trim()
                val observedBrowserPackage =
                    bridgeStatus.optString("effective_foreground_package").trim()

                val perceptionReady =
                    bridgeStatus.optBoolean("success", false) &&
                        bridgeStatus.optBoolean("accessibility_connected", false) &&
                        bridgeStatus.optBoolean("screen_evidence_available", false) &&
                        perceptionPid > 0 &&
                        perceptionPid != android.os.Process.myPid() &&
                        perceptionEpoch.isNotBlank() &&
                        expectedBrowserPackage.isNotBlank() &&
                        observedBrowserPackage == expectedBrowserPackage

                if (!perceptionReady) {
                    lastFailure = "r10_14_perception_bridge_not_ready_before_process_death"
                    break
                }

                runtimeContext
                    .put("r10_14_process_death_requested", true)
                    .put("r10_14_origin_service_instance_id", serviceInstanceId)
                    .put("r10_14_origin_process_id", android.os.Process.myPid())
                    .put("r10_14_origin_process_epoch_id", processEpochId)
                    .put("r10_14_origin_perception_process_id", perceptionPid)
                    .put("r10_14_origin_perception_process_epoch_id", perceptionEpoch)
                    .put("r10_14_pre_death_verified_prefix", longObjective.verifiedSubgoalCount())
                    .put("r10_14_pre_death_plan_revision", longObjective.planRevision())
                    .put("r10_14_pre_death_adaptive_revision", adaptiveLoop.currentRevision())
                    .put("r10_14_pre_death_browser_dispatch_count", browserDispatchCount)
                    .put("r10_14_pre_death_visual_read_count", visualReadCount)
                    .put("r10_14_pre_death_partial_fingerprint", partial.optString("fingerprint"))
                    .put("r10_14_pre_death_checkpoint_persisted", false)
                    .put("r10_14_pre_death_cross_process_screen_evidence_verified", true)

                val processCheckpoint =
                    r10_10BuildProductionPlannerCheckpoint(
                        planner = planner,
                        longObjective = longObjective,
                        adaptiveLoop = adaptiveLoop,
                        continuity = continuity,
                        runtimeContext = runtimeContext,
                        checkpointTag = "r10_14_pre_process_death",
                        safeAutoResume = true,
                        stepInFlight = false,
                        lastStepId = subgoal.id,
                        lastExecutor = subgoal.executor
                    )

                val processPersisted =
                    durableGoalStore.checkpoint(
                        goalId,
                        processCheckpoint
                    ) != null

                if (!processPersisted) {
                    lastFailure = "r10_14_pre_death_checkpoint_failed"
                    break
                }

                runtimeContext.put("r10_14_pre_death_checkpoint_persisted", true)

                val proofCheckpoint =
                    r10_10BuildProductionPlannerCheckpoint(
                        planner = planner,
                        longObjective = longObjective,
                        adaptiveLoop = adaptiveLoop,
                        continuity = continuity,
                        runtimeContext = runtimeContext,
                        checkpointTag = "r10_14_process_death_handoff_ready",
                        safeAutoResume = true,
                        stepInFlight = false,
                        lastStepId = subgoal.id,
                        lastExecutor = subgoal.executor
                    )

                if (durableGoalStore.checkpoint(goalId, proofCheckpoint) == null) {
                    lastFailure = "r10_14_handoff_proof_checkpoint_failed"
                    break
                }

                durableStepCheckpointCount += 2
                runtimeContext.put("r10_11_durable_checkpoint_count", durableStepCheckpointCount)

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "history_recovery_origin_persisted",
                    message = "Исходная history-запись сохранена в durable recovery context",
                    details =
                        "goal_id=$goalId; origin_history_id=${runtimeContext.optString("origin_command_history_id")}"
                )

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "r10_14_process_death_handoff_ready",
                    message = "R10.14 сохранил production objective; :perception остаётся жив при kill main process",
                    details =
                        "goal_id=$goalId; main_pid=${android.os.Process.myPid()}; main_epoch=$processEpochId; " +
                            "perception_pid=$perceptionPid; perception_epoch=$perceptionEpoch; " +
                            "verified=${longObjective.verifiedSubgoalCount()}; browser_dispatch=$browserDispatchCount; visual_read=$visualReadCount"
                )

                return JSONObject()
                    .put("production_dynamic_planner", true)
                    .put("r10_14_acceptance", true)
                    .put("process_death_handoff_required", true)
                    .put("goal_id", goalId)
                    .put("success", false)
                    .put("verified", false)
                    .put("terminal_verified", false)
                    .put("reason", "r10_14_process_death_handoff")
                    .put("blind_replay_allowed", false)
            }

            if (
                verified &&
                runtimeContext.optBoolean("r10_13_acceptance", false) &&
                subgoal.id == "read_title" &&
                !runtimeContext.optBoolean("r10_13_process_death_requested", false)
            ) {
                val partial =
                    longObjective.partialResult("page_title")

                runtimeContext
                    .put("r10_13_process_death_requested", true)
                    .put("r10_13_origin_service_instance_id", serviceInstanceId)
                    .put("r10_13_origin_process_id", android.os.Process.myPid())
                    .put("r10_13_origin_process_epoch_id", processEpochId)
                    .put("r10_13_pre_death_verified_prefix", longObjective.verifiedSubgoalCount())
                    .put("r10_13_pre_death_plan_revision", longObjective.planRevision())
                    .put("r10_13_pre_death_adaptive_revision", adaptiveLoop.currentRevision())
                    .put("r10_13_pre_death_browser_dispatch_count", browserDispatchCount)
                    .put("r10_13_pre_death_visual_read_count", visualReadCount)
                    .put("r10_13_pre_death_partial_fingerprint", partial.optString("fingerprint"))
                    .put("r10_13_pre_death_checkpoint_persisted", false)

                val processCheckpoint =
                    r10_10BuildProductionPlannerCheckpoint(
                        planner = planner,
                        longObjective = longObjective,
                        adaptiveLoop = adaptiveLoop,
                        continuity = continuity,
                        runtimeContext = runtimeContext,
                        checkpointTag = "r10_13_pre_process_death",
                        safeAutoResume = true,
                        stepInFlight = false,
                        lastStepId = subgoal.id,
                        lastExecutor = subgoal.executor
                    )

                val processPersisted =
                    durableGoalStore.checkpoint(
                        goalId,
                        processCheckpoint
                    ) != null

                if (!processPersisted) {
                    lastFailure = "r10_13_pre_death_checkpoint_failed"
                    break
                }

                runtimeContext.put("r10_13_pre_death_checkpoint_persisted", true)
                val proofCheckpoint =
                    r10_10BuildProductionPlannerCheckpoint(
                        planner = planner,
                        longObjective = longObjective,
                        adaptiveLoop = adaptiveLoop,
                        continuity = continuity,
                        runtimeContext = runtimeContext,
                        checkpointTag = "r10_13_process_death_handoff_ready",
                        safeAutoResume = true,
                        stepInFlight = false,
                        lastStepId = subgoal.id,
                        lastExecutor = subgoal.executor
                    )

                if (durableGoalStore.checkpoint(goalId, proofCheckpoint) == null) {
                    lastFailure = "r10_13_handoff_proof_checkpoint_failed"
                    break
                }

                durableStepCheckpointCount += 2
                runtimeContext.put("r10_11_durable_checkpoint_count", durableStepCheckpointCount)

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "r10_13_process_death_handoff_ready",
                    message = "R10.13 сохранил production objective перед полной остановкой process",
                    details =
                        "goal_id=$goalId; process_id=${android.os.Process.myPid()}; process_epoch=$processEpochId; " +
                            "verified=${longObjective.verifiedSubgoalCount()}; browser_dispatch=$browserDispatchCount; visual_read=$visualReadCount"
                )

                return JSONObject()
                    .put("production_dynamic_planner", true)
                    .put("r10_13_acceptance", true)
                    .put("process_death_handoff_required", true)
                    .put("goal_id", goalId)
                    .put("success", false)
                    .put("verified", false)
                    .put("terminal_verified", false)
                    .put("reason", "process_death_handoff")
                    .put("blind_replay_allowed", false)
            }

            if (
                verified &&
                runtimeContext.optBoolean("r10_12_acceptance", false) &&
                subgoal.id == "read_title" &&
                !runtimeContext.optBoolean("r10_12_service_recreation_requested", false)
            ) {
                val partial =
                    longObjective.partialResult("page_title")

                runtimeContext
                    .put("r10_12_service_recreation_requested", true)
                    .put("r10_12_origin_service_instance_id", serviceInstanceId)
                    .put("r10_12_origin_process_id", android.os.Process.myPid())
                    .put("r10_12_origin_process_epoch_id", processEpochId)
                    .put("r10_12_pre_recreation_verified_prefix", longObjective.verifiedSubgoalCount())
                    .put("r10_12_pre_recreation_plan_revision", longObjective.planRevision())
                    .put("r10_12_pre_recreation_adaptive_revision", adaptiveLoop.currentRevision())
                    .put("r10_12_pre_recreation_browser_dispatch_count", browserDispatchCount)
                    .put("r10_12_pre_recreation_visual_read_count", visualReadCount)
                    .put("r10_12_pre_recreation_partial_fingerprint", partial.optString("fingerprint"))
                    .put("r10_12_pre_recreation_checkpoint_persisted", false)

                val lifecycleCheckpoint =
                    r10_10BuildProductionPlannerCheckpoint(
                        planner = planner,
                        longObjective = longObjective,
                        adaptiveLoop = adaptiveLoop,
                        continuity = continuity,
                        runtimeContext = runtimeContext,
                        checkpointTag = "r10_12_pre_service_recreation",
                        safeAutoResume = true,
                        stepInFlight = false,
                        lastStepId = subgoal.id,
                        lastExecutor = subgoal.executor
                    )

                val lifecyclePersisted =
                    durableGoalStore.checkpoint(
                        goalId,
                        lifecycleCheckpoint
                    ) != null

                if (!lifecyclePersisted) {
                    lastFailure = "r10_12_pre_recreation_checkpoint_failed"
                    break
                }

                runtimeContext.put("r10_12_pre_recreation_checkpoint_persisted", true)
                val proofCheckpoint =
                    r10_10BuildProductionPlannerCheckpoint(
                        planner = planner,
                        longObjective = longObjective,
                        adaptiveLoop = adaptiveLoop,
                        continuity = continuity,
                        runtimeContext = runtimeContext,
                        checkpointTag = "r10_12_service_recreation_handoff_ready",
                        safeAutoResume = true,
                        stepInFlight = false,
                        lastStepId = subgoal.id,
                        lastExecutor = subgoal.executor
                    )

                if (durableGoalStore.checkpoint(goalId, proofCheckpoint) == null) {
                    lastFailure = "r10_12_handoff_proof_checkpoint_failed"
                    break
                }

                durableStepCheckpointCount += 2
                runtimeContext.put("r10_11_durable_checkpoint_count", durableStepCheckpointCount)

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "r10_12_service_recreation_handoff_ready",
                    message = "R10.12 сохранил production objective перед реальным пересозданием Service",
                    details =
                        "goal_id=$goalId; service_instance=$serviceInstanceId; " +
                            "verified=${longObjective.verifiedSubgoalCount()}; " +
                            "browser_dispatch=$browserDispatchCount; visual_read=$visualReadCount"
                )

                return JSONObject()
                    .put("production_dynamic_planner", true)
                    .put("r10_12_acceptance", true)
                    .put("service_recreation_handoff_required", true)
                    .put("goal_id", goalId)
                    .put("success", false)
                    .put("verified", false)
                    .put("terminal_verified", false)
                    .put("reason", "service_recreation_handoff")
                    .put("blind_replay_allowed", false)
            }

            if (!verified) {
                replanAttemptCount++
                runtimeContext.put("r10_11_replan_attempt_count", replanAttemptCount)
                val failureReason =
                    executorResult.optString(
                        "reason",
                        executorResult.optString(
                            "message",
                            "verified_failure_no_safe_alternative"
                        )
                    )
                val replan =
                    r10_10AttemptProductionSuffixReplan(
                        command = command,
                        planner = planner,
                        longObjective = longObjective,
                        adaptiveLoop = adaptiveLoop,
                        failedSubgoalId = subgoal.id,
                        failureReason = failureReason,
                        stateFingerprint = afterState
                    )

                if (replan.optBoolean("applied", false)) {
                    replanAppliedCount++
                    runtimeContext.put("r10_11_replan_applied_count", replanAppliedCount)
                    return r10_11ContinueAfterAppliedReplan(
                        goalId = goalId,
                        command = command,
                        replan = replan,
                        longObjective = longObjective,
                        adaptiveLoop = adaptiveLoop,
                        continuity = continuity,
                        runtimeContext = runtimeContext,
                        commandToken = commandToken,
                        automaticRecovery = automaticRecovery,
                        dispatchCount = dispatchCount,
                        browserDispatchCount = browserDispatchCount,
                        visualReadCount = visualReadCount,
                        replanAttemptCount = replanAttemptCount,
                        replanAppliedCount = replanAppliedCount,
                        durableStepCheckpointCount = durableStepCheckpointCount
                    )
                } else {
                    lastFailure =
                        replan.optString(
                            "reason",
                            failureReason
                        )
                    break
                }
            }

            currentState = afterState
        }

        // R10.19 acceptance cleanup is deliberately outside the app-step graph.
        // The Calendar step remains DRAFT_ONLY; after the final factual read AYANA is
        // restored to the original page without inventing another planner mutation.
        if (runtimeContext.optBoolean("r10_19_acceptance", false)) {
            val originalPage =
                runtimeContext
                    .optString("r10_19_original_page")
                    .trim()

            val restore =
                try {
                    restoreAyanaAfterAppIntegrationProbe(
                        pageKey = originalPage,
                        stepKey = "r10.19-autonomous-multi-app"
                    )
                } catch (error: Throwable) {
                    JSONObject()
                        .put("success", false)
                        .put("verified", false)
                        .put("reason", "r10_19_restore_exception")
                        .put(
                            "error",
                            (error.message ?: error.javaClass.simpleName)
                                .take(600)
                        )
                }

            val restoreVerified =
                restore.optBoolean("success", false) &&
                    restore.optBoolean(
                        "verified",
                        restore.optBoolean("success", false)
                    )

            runtimeContext
                .put("r10_19_restore_verified", restoreVerified)
                .put(
                    "r10_19_restore_reason",
                    restore.optString(
                        "reason",
                        restore.optString("message")
                    )
                )

            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state =
                    if (restoreVerified) {
                        "r10_19_ayana_restore_verified"
                    } else {
                        "r10_19_ayana_restore_not_verified"
                    },
                message =
                    if (restoreVerified) {
                        "R10.19 вернул AYANA после production multi-app chain"
                    } else {
                        "R10.19 не смог подтвердить возврат AYANA после multi-app chain"
                    },
                details = restore.toString().take(1800)
            )
        }

        val longTerminal =
            longObjective.canDeclareSuccess()

        val terminalGate =
            adaptiveLoop.markTerminal(
                verified =
                    longTerminal &&
                        lastFailure.isBlank() &&
                        !adaptiveLoop.hasUnresolvedSideEffect(),
                evidence =
                    "R10.10 production long_terminal=$longTerminal; " +
                        "verified=${longObjective.verifiedSubgoalCount()}/${longObjective.subgoalCount()}; " +
                        "failure=$lastFailure"
            )

        val terminalVerified =
            adaptiveLoop.canDeclareSuccess() &&
                longTerminal &&
                lastFailure.isBlank() &&
                !adaptiveLoop.hasUnresolvedSideEffect()

        val finalCheckpoint =
            r10_10BuildProductionPlannerCheckpoint(
                planner = planner,
                longObjective = longObjective,
                adaptiveLoop = adaptiveLoop,
                continuity = continuity,
                runtimeContext = runtimeContext,
                checkpointTag =
                    when {
                        runtimeContext.optBoolean("r10_19_acceptance", false) &&
                            terminalVerified ->
                            "r10_19_multi_app_terminal"
                        runtimeContext.optBoolean("r10_19_acceptance", false) ->
                            "r10_19_multi_app_paused"
                        terminalVerified ->
                            "r10_10_production_terminal"
                        else ->
