                } else {
                    runtimeContext.optBoolean("r10_13_adaptive_revision_preserved_after_process_death", false)
                }
            )
            .put(
                "partial_result_preserved_after_process_death",
                if (r10_14Acceptance) {
                    runtimeContext.optBoolean("r10_14_partial_result_preserved_after_process_death", false)
                } else {
                    runtimeContext.optBoolean("r10_13_partial_result_preserved_after_process_death", false)
                }
            )
            .put(
                "browser_replay_blocked_after_process_death",
                if (r10_14Acceptance) {
                    runtimeContext.optBoolean("r10_14_browser_replay_blocked_after_process_death", false)
                } else {
                    runtimeContext.optBoolean("r10_13_browser_replay_blocked_after_process_death", false)
                }
            )
            .put(
                "visual_replay_blocked_after_process_death",
                if (r10_14Acceptance) {
                    runtimeContext.optBoolean("r10_14_visual_replay_blocked_after_process_death", false)
                } else {
                    runtimeContext.optBoolean("r10_13_visual_replay_blocked_after_process_death", false)
                }
            )
            .put(
                "origin_process_id",
                if (r10_14Acceptance) {
                    runtimeContext.optInt("r10_14_origin_process_id", -1)
                } else {
                    runtimeContext.optInt("r10_13_origin_process_id", -1)
                }
            )
            .put(
                "restored_process_id",
                if (r10_14Acceptance) {
                    runtimeContext.optInt("r10_14_current_process_id", -1)
                } else {
                    runtimeContext.optInt("r10_13_current_process_id", -1)
                }
            )
            .put(
                "origin_process_epoch_id",
                if (r10_14Acceptance) {
                    runtimeContext.optString("r10_14_origin_process_epoch_id")
                } else {
                    runtimeContext.optString("r10_13_origin_process_epoch_id")
                }
            )
            .put(
                "restored_process_epoch_id",
                if (r10_14Acceptance) {
                    runtimeContext.optString("r10_14_current_process_epoch_id")
                } else {
                    runtimeContext.optString("r10_13_current_process_epoch_id")
                }
            )
            .put(
                "service_instance_recreated_after_process_death",
                if (r10_14Acceptance) {
                    runtimeContext.optBoolean("r10_14_service_instance_recreated", false)
                } else {
                    runtimeContext.optBoolean("r10_13_service_instance_recreated", false)
                }
            )
            .put(
                "origin_process_service_instance_id",
                if (r10_14Acceptance) {
                    runtimeContext.optString("r10_14_origin_service_instance_id")
                } else {
                    runtimeContext.optString("r10_13_origin_service_instance_id")
                }
            )
            .put(
                "restored_process_service_instance_id",
                if (r10_14Acceptance) {
                    runtimeContext.optString("r10_14_current_service_instance_id")
                } else {
                    runtimeContext.optString("r10_13_current_service_instance_id")
                }
            )
            .put("r10_12_acceptance", r10_12Acceptance)
            .put(
                "service_recreation_requested",
                runtimeContext.optBoolean("r10_12_service_recreation_requested", false)
            )
            .put(
                "service_instance_recreated",
                runtimeContext.optBoolean("r10_12_service_instance_recreated", false)
            )
            .put(
                "service_recreation_process_changed",
                runtimeContext.optBoolean("r10_12_process_recreated", false)
            )
            .put(
                "background_auto_resume",
                when {
                    r10_14Acceptance ->
                        runtimeContext.optBoolean("r10_14_background_auto_resume", false)
                    r10_13Acceptance ->
                        runtimeContext.optBoolean("r10_13_background_auto_resume", false)
                    else ->
                        runtimeContext.optBoolean("r10_12_background_auto_resume", false)
                }
            )
            .put(
                "lifecycle_restore_verified",
                runtimeContext.optBoolean("r10_12_lifecycle_restore_verified", false)
            )
            .put(
                "verified_prefix_preserved_after_service_recreation",
                runtimeContext.optBoolean("r10_12_verified_prefix_preserved_after_recreation", false)
            )
            .put(
                "plan_revision_preserved_after_service_recreation",
                runtimeContext.optBoolean("r10_12_plan_revision_preserved_after_recreation", false)
            )
            .put(
                "adaptive_revision_preserved_after_service_recreation",
                runtimeContext.optBoolean("r10_12_adaptive_revision_preserved_after_recreation", false)
            )
            .put(
                "partial_result_preserved_after_service_recreation",
                runtimeContext.optBoolean("r10_12_partial_result_preserved_after_recreation", false)
            )
            .put(
                "browser_replay_blocked_after_service_recreation",
                runtimeContext.optBoolean("r10_12_browser_replay_blocked_after_recreation", false)
            )
            .put(
                "visual_replay_blocked_after_service_recreation",
                runtimeContext.optBoolean("r10_12_visual_replay_blocked_after_recreation", false)
            )
            .put(
                "origin_service_instance_id",
                runtimeContext.optString("r10_12_origin_service_instance_id")
            )
            .put(
                "restored_service_instance_id",
                runtimeContext.optString("r10_12_current_service_instance_id")
            )
            .put(
                "user_stop_reinterpreted_as_recovery",
                false
            )
            .put(
                "acceptance_ok",
                when {
                    r10_19Acceptance -> r10_19AcceptanceOk
                    r10_14Acceptance -> r10_14AcceptanceOk
                    r10_13Acceptance -> r10_13AcceptanceOk
                    r10_12Acceptance -> r10_12AcceptanceOk
                    else -> r10_11AcceptanceOk
                }
            )
            .put("goal_id", goalId)
            .put("reason", lastFailure)
            .put("long_objective_summary", longObjective.compactSummary())
            .put("continuity_summary", continuity.compactSummary(adaptiveLoop))
            .put("voice_service_release", AYANA_VOICE_SERVICE_RELEASE)
            .put("accepted_checkpoint", AYANA_ACCEPTED_FEATURE_CHECKPOINT)
            .put("current_release", AYANA_CURRENT_FEATURE_RELEASE)
    }

    private fun executeR10_10RegisteredPlannerSubgoal(
        planner: AyanaDynamicGoalPlanner,
        longObjective: AyanaLongObjectiveCoordinator,
        subgoal: AyanaDynamicGoalPlanner.PlannedSubgoal,
        goalId: String,
        commandToken: Long,
        runtimeContext: JSONObject
    ): JSONObject {
        val arguments =
            planner.argumentsFor(
                subgoal.id
            )

        return when (subgoal.executor) {
            AyanaDynamicGoalPlanner.EXEC_DEVICE_STATE -> {
                executeAgentTool(
                    name = "get_device_state",
                    arguments = JSONObject()
                )
            }

            AyanaDynamicGoalPlanner.EXEC_ANDROID_GOAL -> {
                executeAndroidGoal(
                    arguments = JSONObject(arguments.toString()),
                    checkpointStore = durableGoalStore,
                    checkpointGoalId = goalId
                )
            }

            AyanaDynamicGoalPlanner.EXEC_BROWSER_OPEN_URL -> {
                val url =
                    arguments
                        .optString("url")
                        .trim()

                val result =
                    executeAppIntegrationAction(
                        appKey = AyanaAppIntegrationRegistry.APP_BROWSER,
                        actionKey = AyanaAppIntegrationRegistry.ACTION_OPEN_URL,
                        payload = url
                    )

                val packageName =
                    result
                        .optString("observed_package")
                        .trim()
                        .ifBlank {
                            result
                                .optString("target_package")
                                .trim()
                        }

                if (packageName.isNotBlank()) {
                    runtimeContext.put(
                        "browser_package",
                        packageName
                    )
                }

                runtimeContext.put(
                    "browser_url",
                    url
                )

                result
            }

            AyanaDynamicGoalPlanner.EXEC_STRUCTURED_SCREEN_READ -> {
                val expectedPackage =
                    runtimeContext
                        .optString("browser_package")
                        .trim()
                        .ifBlank {
                            try {
                                screenIntelligence
                                    .getScreenState()
                                    .optString("effective_foreground_package")
                                    .trim()
                                    .ifBlank {
                                        screenIntelligence
                                            .getScreenState()
                                            .optString("package")
                                            .trim()
                                    }
                            } catch (_: Exception) {
                                ""
                            }
                        }

                val result =
                    if (expectedPackage.isNotBlank()) {
                        attemptVerifiedStructuredSemanticScreenRead(
                            expectedPackage = expectedPackage,
                            commandToken = commandToken
                        )
                    } else {
                        JSONObject()
                            .put("success", false)
                            .put("verified", false)
                            .put(
                                "reason",
                                "expected_browser_package_missing"
                            )
                    }

                val title =
                    result
                        .optString("semantic_title")
                        .trim()

                val verified =
                    result.optBoolean("success", false) &&
                        result.optBoolean("verified", false) &&
                        result.optBoolean(
                            "semantic_structured_read_verified",
                            false
                        ) &&
                        title.isNotBlank()

                JSONObject(result.toString())
                    .put("verified", verified)
                    .put(
                        "verified_result_value",
                        if (verified) title else ""
                    )
                    .put(
                        "message",
                        if (verified) {
                            "Structured screen title verified"
                        } else {
                            result.optString(
                                "reason",
                                "Structured screen title not verified"
                            )
                        }
                    )
            }

            AyanaDynamicGoalPlanner.EXEC_PARTIAL_RESULT_CHECK -> {
                val inputKey =
                    arguments
                        .optString("input_result_key")
                        .trim()

                val partial =
                    longObjective.partialResult(
                        key = inputKey,
                        consumerSubgoalId = subgoal.id
                    )

                val verified =
                    partial.optBoolean("available", false) &&
                        partial.optBoolean("verified", false)

                JSONObject()
                    .put("success", verified)
                    .put("verified", verified)
                    .put("action_dispatched", false)
                    .put("reconciliation_complete", true)
                    .put(
                        "verified_result_value",
                        partial.optString("value")
                    )
                    .put(
                        "message",
                        if (verified) {
                            "Verified partial-result provenance confirmed"
                        } else {
                            partial.optString(
                                "reason",
                                "partial_result_not_verified"
                            )
                        }
                    )
            }

            AyanaDynamicGoalPlanner.EXEC_YOUTUBE_SEARCH -> {
                if (
                    runtimeContext.optBoolean(
                        "r10_11_inject_youtube_failure_once",
                        false
                    ) &&
                    !runtimeContext.optBoolean(
                        "r10_11_youtube_failure_injected",
                        false
                    )
                ) {
                    runtimeContext.put(
                        "r10_11_youtube_failure_injected",
                        true
                    )
                    return JSONObject()
                        .put("success", false)
                        .put("verified", false)
                        .put("action_dispatched", false)
                        .put("action_committed", false)
                        .put("reconciliation_complete", true)
                        .put("failure_layer", "controlled_pre_dispatch_verification")
                        .put("reason", "r10_11_controlled_youtube_pre_dispatch_failure")
                        .put("message", "R10.11 verified failure injected before YouTube dispatch")
                }

                val inputKey =
                    arguments
                        .optString("input_result_key")
                        .trim()

                val partial =
                    longObjective.partialResult(
                        key = inputKey,
                        consumerSubgoalId = subgoal.id
                    )

                if (
                    !partial.optBoolean("available", false) ||
                    !partial.optBoolean("verified", false)
                ) {
                    if (runtimeContext.optBoolean("r10_19_acceptance", false)) {
                        runtimeContext
                            .put("r10_19_youtube_input_verified", false)
                            .put("r10_19_youtube_input_fingerprint", "")
                    }

                    JSONObject()
                        .put("success", false)
                        .put("verified", false)
                        .put("action_dispatched", false)
                        .put(
                            "reason",
                            "youtube_input_partial_result_not_verified"
                        )
                } else {
                    if (runtimeContext.optBoolean("r10_19_acceptance", false)) {
                        runtimeContext
                            .put("r10_19_youtube_input_verified", true)
                            .put(
                                "r10_19_youtube_input_fingerprint",
                                partial.optString("fingerprint")
                            )
                            .put(
                                "r10_19_youtube_input_value",
                                partial.optString("value").trim().take(240)
                            )
                    }

                    val rawResult =
                        executeAppIntegrationAction(
                            appKey = AyanaAppIntegrationRegistry.APP_YOUTUBE,
                            actionKey = AyanaAppIntegrationRegistry.ACTION_SEARCH,
                            payload =
                                partial
                                    .optString("value")
                                    .trim()
                        )

                    val navigationResult =
                        if (
                            (
                                runtimeContext.optBoolean("r10_14_acceptance", false) &&
                                    runtimeContext.optBoolean("r10_14_lifecycle_restore_verified", false)
                                ) ||
                            (
                                runtimeContext.optBoolean("r10_13_acceptance", false) &&
                                    runtimeContext.optBoolean("r10_13_lifecycle_restore_verified", false)
                                )
                        ) {
                            if (
                                rawResult.optBoolean("action_dispatched", false) &&
                                !rawResult.optBoolean("verified", false)
                            ) {
                                reconcileR10_13DispatchedNavigation(
                                    rawResult = rawResult,
                                    commandToken = commandToken
                                )
                            } else {
                                JSONObject(rawResult.toString())
                                    .put(
                                        "reconciliation_complete",
                                        rawResult.optBoolean("verified", false)
                                    )
                                    .put("r10_13_reconciliation_attempted", false)
                                    .put("r10_13_reconciliation_verified", rawResult.optBoolean("verified", false))
                                    .put("r10_13_reconciliation_waited_ms", 0L)
                            }
                        } else {
                            JSONObject(rawResult.toString())
                                .put(
                                    "reconciliation_complete",
                                    rawResult.optBoolean("verified", false)
                                )
                        }

                    if (runtimeContext.optBoolean("r10_13_acceptance", false)) {
                        runtimeContext
                            .put("r10_13_navigation_reconciliation_attempted", navigationResult.optBoolean("r10_13_reconciliation_attempted", false))
                            .put("r10_13_navigation_reconciliation_verified", navigationResult.optBoolean("r10_13_reconciliation_verified", false))
                            .put("r10_13_navigation_reconciliation_waited_ms", navigationResult.optLong("r10_13_reconciliation_waited_ms", 0L))
                    }

                    if (
                        runtimeContext.optBoolean("r10_14_acceptance", false) &&
                        runtimeContext.optBoolean("r10_14_lifecycle_restore_verified", false)
                    ) {
                        val bridgeStatus =
                            try {
                                perceptionBridge.status()
                            } catch (_: Throwable) {
                                JSONObject()
                            }

                        val expectedPackage =
                            navigationResult.optString("target_package").trim()
                        val observedPackage =
                            bridgeStatus.optString("effective_foreground_package").trim()
                        val originPerceptionPid =
                            runtimeContext.optInt("r10_14_origin_perception_process_id", -1)
                        val restoredPerceptionPid =
                            bridgeStatus.optInt("perception_process_id", -1)
                        val originPerceptionEpoch =
                            runtimeContext.optString("r10_14_origin_perception_process_epoch_id")
                        val restoredPerceptionEpoch =
                            bridgeStatus.optString("perception_process_epoch_id")

                        val samePerceptionProcess =
                            originPerceptionPid > 0 &&
                                restoredPerceptionPid == originPerceptionPid &&
                                originPerceptionEpoch.isNotBlank() &&
                                restoredPerceptionEpoch == originPerceptionEpoch

                        val externalUiVerified =
                            navigationResult.optBoolean("verified", false) &&
                                bridgeStatus.optBoolean("accessibility_connected", false) &&
                                bridgeStatus.optBoolean("screen_evidence_available", false) &&
                                expectedPackage.isNotBlank() &&
                                observedPackage == expectedPackage &&
                                samePerceptionProcess

                        runtimeContext
                            .put("r10_14_navigation_reconciliation_attempted", navigationResult.optBoolean("r10_13_reconciliation_attempted", false))
                            .put("r10_14_navigation_reconciliation_verified", navigationResult.optBoolean("r10_13_reconciliation_verified", false))
                            .put("r10_14_navigation_reconciliation_waited_ms", navigationResult.optLong("r10_13_reconciliation_waited_ms", 0L))
                            .put("r10_14_post_death_youtube_verified", navigationResult.optBoolean("verified", false))
                            .put("r10_14_cross_process_foreground_after_youtube_verified", externalUiVerified)
                            .put("r10_14_perception_process_still_same_after_youtube", samePerceptionProcess)
                            .put("r10_14_external_ui_continuation_proven", externalUiVerified)

                        navigationResult
                            .put("cross_process_perception_verified", externalUiVerified)
                            .put("perception_process_id", restoredPerceptionPid)
                            .put("perception_process_epoch_id", restoredPerceptionEpoch)
                    } else {
                        navigationResult
                    }
                }
            }

            AyanaDynamicGoalPlanner.EXEC_APP_INFO -> {
                val app =
                    arguments
                        .optString("app")
                        .trim()

                val raw =
                    agentOpenAppInfo(
                        app
                    )

                val verified =
                    raw.optBoolean("success", false) &&
                        raw.optBoolean("verified", false)

                val dispatchObserved =
                    verified ||
                        raw
                            .optString("message")
                            .contains("Android принял переход", ignoreCase = true)

                if (runtimeContext.optBoolean("r10_19_acceptance", false)) {
                    runtimeContext
                        .put("r10_19_app_info_verified", verified)
                        .put("r10_19_app_info_target", app)
                }

                JSONObject(raw.toString())
                    .put("action_dispatched", dispatchObserved)
                    .put("action_committed", false)
                    .put("reconciliation_complete", verified)
                    .put(
                        "message",
                        raw.optString(
                            "message",
                            if (verified) {
                                "App Info verified"
                            } else {
                                "App Info not verified"
                            }
                        )
                    )
            }

            AyanaDynamicGoalPlanner.EXEC_UNIVERSAL_UI_CLICK -> {
                val target =
                    arguments
                        .optString("target")
                        .trim()

                val result =
                    universalUiActionEngine.click(
                        target = target,
                        confirmed = false
                    )

                val verified =
                    result.optBoolean("success", false) &&
                        result.optBoolean("verified", false) &&
                        result.optBoolean("postcondition_verified", false)

                if (runtimeContext.optBoolean("r10_19_acceptance", false)) {
                    runtimeContext
                        .put("r10_19_universal_ui_action_verified", verified)
                        .put("r10_19_ui_single_dispatch_verified", result.optInt("dispatch_count", 0) == 1)
                        .put("r10_19_ui_postcondition_verified", result.optBoolean("postcondition_verified", false))
                        .put("r10_19_ui_visual_action_authority", result.optBoolean("visual_grants_action_authority", false))
                        .put("r10_19_ui_unresolved_side_effect", result.optBoolean("unresolved_side_effect", false))
                        .put("r10_19_ui_target", target)
                }

                result
            }

            AyanaDynamicGoalPlanner.EXEC_CALENDAR_DRAFT -> {
                val inputKey =
                    arguments
                        .optString("input_result_key")
                        .trim()

                val partial =
                    if (inputKey.isNotBlank()) {
                        longObjective.partialResult(
                            key = inputKey,
                            consumerSubgoalId = subgoal.id
                        )
                    } else {
                        JSONObject()
                    }

                val verifiedInput =
                    inputKey.isBlank() ||
                        (
                            partial.optBoolean("available", false) &&
                                partial.optBoolean("verified", false)
                            )

                if (!verifiedInput) {
                    JSONObject()
                        .put("success", false)
                        .put("verified", false)
                        .put("action_dispatched", false)
                        .put("action_committed", false)
                        .put("reconciliation_complete", true)
                        .put("reason", "calendar_draft_input_partial_result_not_verified")
                } else {
                    val title =
                        if (inputKey.isNotBlank()) {
                            partial.optString("value").trim()
                        } else {
                            arguments.optString("title").trim()
                        }

                    if (title.isBlank()) {
                        JSONObject()
                            .put("success", false)
                            .put("verified", false)
                            .put("action_dispatched", false)
                            .put("action_committed", false)
                            .put("reconciliation_complete", true)
                            .put("reason", "calendar_draft_title_empty")
                    } else {
                        val raw =
                            executeAppIntegrationAction(
                                appKey = AyanaAppIntegrationRegistry.APP_CALENDAR,
                                actionKey = AyanaAppIntegrationRegistry.ACTION_CREATE_EVENT_DRAFT,
                                payload = title
                            )

                        val verified =
                            raw.optBoolean("success", false) &&
                                raw.optBoolean("verified", false)

                        if (runtimeContext.optBoolean("r10_19_acceptance", false)) {
                            runtimeContext
                                .put("r10_19_calendar_draft_verified", verified)
                                .put("r10_19_calendar_draft_only", true)
                                .put("r10_19_calendar_input_verified", verifiedInput)
                                .put("r10_19_calendar_input_key", inputKey)
                                .put("r10_19_calendar_input_fingerprint", partial.optString("fingerprint"))
                                .put("r10_19_calendar_title", title.take(240))
                        }

                        JSONObject(raw.toString())
                            .put("reconciliation_complete", verified)
                            .put("verified_input", verifiedInput)
                            .put("verified_input_key", inputKey)
                            .put("verified_input_fingerprint", partial.optString("fingerprint"))
                    }
                }
            }

            else -> {
                JSONObject()
                    .put("success", false)
                    .put("verified", false)
                    .put("action_dispatched", false)
                    .put(
                        "reason",
                        "planner_executor_not_registered_at_runtime"
                    )
            }
        }
    }

    private fun r10_10AdaptiveToolName(
        executor: String
    ): String =
        when (executor) {
            AyanaDynamicGoalPlanner.EXEC_DEVICE_STATE ->
                "get_device_state"

            AyanaDynamicGoalPlanner.EXEC_ANDROID_GOAL ->
                "execute_android_goal"

            AyanaDynamicGoalPlanner.EXEC_BROWSER_OPEN_URL ->
                "app_integration:browser:open_url"

            AyanaDynamicGoalPlanner.EXEC_STRUCTURED_SCREEN_READ ->
                "screen_observe_package_bound_visual"

            AyanaDynamicGoalPlanner.EXEC_PARTIAL_RESULT_CHECK ->
                "partial_result_check"

            AyanaDynamicGoalPlanner.EXEC_YOUTUBE_SEARCH ->
                "app_integration:youtube:search"

            AyanaDynamicGoalPlanner.EXEC_APP_INFO ->
                "android_settings:app_info"

            AyanaDynamicGoalPlanner.EXEC_UNIVERSAL_UI_CLICK ->
                "universal_ui_action:click"

            AyanaDynamicGoalPlanner.EXEC_CALENDAR_DRAFT ->
                "app_integration:calendar:create_event_draft"

            else ->
                "unsupported_planner_executor"
        }

    private fun r10_10AdaptiveArguments(
        executor: String,
        plannerArguments: JSONObject,
        longObjective: AyanaLongObjectiveCoordinator,
        subgoalId: String,
        runtimeContext: JSONObject
    ): JSONObject =
        when (executor) {
            AyanaDynamicGoalPlanner.EXEC_BROWSER_OPEN_URL ->
                JSONObject()
                    .put(
                        "app_key",
                        AyanaAppIntegrationRegistry.APP_BROWSER
                    )
                    .put(
                        "action_key",
                        AyanaAppIntegrationRegistry.ACTION_OPEN_URL
                    )
                    .put(
                        "payload",
                        plannerArguments.optString("url")
                    )

            AyanaDynamicGoalPlanner.EXEC_STRUCTURED_SCREEN_READ ->
                JSONObject()
                    .put(
                        "expected_package",
                        runtimeContext.optString(
                            "browser_package"
                        )
                    )
                    .put(
                        "mode",
                        "package_bound_structured_visual"
                    )

            AyanaDynamicGoalPlanner.EXEC_YOUTUBE_SEARCH,
            AyanaDynamicGoalPlanner.EXEC_PARTIAL_RESULT_CHECK -> {
                val key =
                    plannerArguments
                        .optString("input_result_key")
                        .trim()
                val partial =
                    longObjective.partialResult(
                        key = key,
                        consumerSubgoalId = subgoalId
                    )

                JSONObject()
                    .put("input_result_key", key)
                    .put(
                        "verified_input_fingerprint",
                        partial.optString("fingerprint")
                    )
                    .put(
                        "payload",
                        partial.optString("value")
                    )
            }

            AyanaDynamicGoalPlanner.EXEC_APP_INFO ->
                JSONObject()
                    .put("app", plannerArguments.optString("app"))

            AyanaDynamicGoalPlanner.EXEC_UNIVERSAL_UI_CLICK ->
                JSONObject()
                    .put("target", plannerArguments.optString("target"))
                    .put("confirmed", false)
                    .put("authority_source", "universal_ui_action_engine")

            AyanaDynamicGoalPlanner.EXEC_CALENDAR_DRAFT -> {
                val key =
                    plannerArguments
                        .optString("input_result_key")
                        .trim()
                val partial =
                    if (key.isNotBlank()) {
                        longObjective.partialResult(
                            key = key,
                            consumerSubgoalId = subgoalId
                        )
                    } else {
                        JSONObject()
                    }

                JSONObject()
                    .put("input_result_key", key)
                    .put("verified_input_fingerprint", partial.optString("fingerprint"))
                    .put(
                        "payload",
                        if (key.isNotBlank()) {
                            partial.optString("value")
                        } else {
                            plannerArguments.optString("title")
                        }
                    )
                    .put("commit_semantics", "DRAFT_ONLY")
            }

            else ->
                JSONObject(
                    plannerArguments.toString()
                )
        }

    private fun r10_10AttemptProductionSuffixReplan(
        command: String,
        planner: AyanaDynamicGoalPlanner,
        longObjective: AyanaLongObjectiveCoordinator,
        adaptiveLoop: AyanaAdaptiveExecutionLoop,
        failedSubgoalId: String,
        failureReason: String,
        stateFingerprint: String
    ): JSONObject {
        if (adaptiveLoop.hasUnresolvedSideEffect()) {
            return JSONObject()
                .put("applied", false)
                .put("reason", "unresolved_side_effect_blocks_replan")
                .put("failed_subgoal_id", failedSubgoalId)
                .put("blind_retry_blocked", true)
        }

        val proposal =
            try {
                AyanaDynamicGoalPlanner.alternativeProposalAfterVerifiedFailure(
                    objective = command,
                    current = planner,
                    failedSubgoalId = failedSubgoalId,
                    failureReason = failureReason
                )
            } catch (error: Throwable) {
                return JSONObject()
                    .put("applied", false)
                    .put(
                        "reason",
                        error.message ?: "replan_proposal_failed"
                    )
                    .put("failed_subgoal_id", failedSubgoalId)
            }

        if (!proposal.optBoolean("supported", false)) {
            return JSONObject()
                .put("applied", false)
                .put(
                    "reason",
                    proposal.optString(
                        "reason",
                        "no_safe_replan_proposal"
                    )
                )
                .put("failed_subgoal_id", failedSubgoalId)
                .put("blind_retry_blocked", true)
        }

        val candidate =
            try {
                AyanaDynamicGoalPlanner.compile(
                    objective = command,
                    proposal = proposal
                )
            } catch (error: Throwable) {
                return JSONObject()
                    .put("applied", false)
                    .put(
                        "reason",
                        error.message ?: "replan_validation_failed"
                    )
                    .put("failed_subgoal_id", failedSubgoalId)
            }

        if (
            candidate.planFingerprint() ==
            planner.planFingerprint()
        ) {
            return JSONObject()
                .put("applied", false)
                .put(
                    "reason",
                    "verified_failure_no_alternative_plan"
                )
                .put(
                    "failed_subgoal_id",
                    failedSubgoalId
                )
                .put(
                    "blind_retry_blocked",
                    true
                )
        }

        val adaptiveReplan =
            adaptiveLoop.beginReplan(
                reason = "production_verified_failure:$failedSubgoalId:$failureReason",
                stateFingerprint = stateFingerprint
            )

        if (!adaptiveReplan.optBoolean("allowed", false)) {
            return JSONObject(adaptiveReplan.toString())
                .put("applied", false)
                .put("failed_subgoal_id", failedSubgoalId)
                .put("blind_retry_blocked", true)
        }

        val gate =
            longObjective.applyPlanRevision(
                candidate.toLongObjectiveSpecs()
            )

        return JSONObject(gate.toString())
            .put(
                "applied",
                gate.optBoolean("allowed", false)
            )
            .put(
                "failed_subgoal_id",
                failedSubgoalId
            )
            .put(
                "candidate_plan",
                candidate.snapshot()
            )
            .put(
"candidate_plan_fingerprint",
                candidate.planFingerprint()
            )
            .put(
                "adaptive_replan_revision",
                adaptiveLoop.currentRevision()
            )
            .put(
                "verified_prefix_preserved",
                gate.optBoolean("verified_prefix_preserved", false)
            )
            .put(
                "partial_result_provenance_preserved",
                gate.optBoolean("partial_result_provenance_preserved", false)
            )
            .put("blind_retry_blocked", true)
    }

    private fun r10_11ContinueAfterAppliedReplan(
        goalId: String,
        command: String,
        replan: JSONObject,
        longObjective: AyanaLongObjectiveCoordinator,
        adaptiveLoop: AyanaAdaptiveExecutionLoop,
        continuity: AyanaCrossLaneAdaptiveContinuity,
        runtimeContext: JSONObject,
        commandToken: Long,
        automaticRecovery: Boolean,
        dispatchCount: Int,
        browserDispatchCount: Int,
        visualReadCount: Int,
        replanAttemptCount: Int,
        replanAppliedCount: Int,
        durableStepCheckpointCount: Int
    ): JSONObject {
        val candidate =
            try {
                AyanaDynamicGoalPlanner.restore(
                    replan.optJSONObject("candidate_plan")
                )
            } catch (error: Throwable) {
                return JSONObject()
                    .put("production_dynamic_planner", true)
                    .put("success", false)
                    .put("verified", false)
                    .put("terminal_verified", false)
                    .put("reason", "replan_candidate_restore_failed")
                    .put("error", error.message ?: error.javaClass.simpleName)
                    .put("goal_id", goalId)
                    .put("blind_replay_allowed", false)
            }

        runtimeContext
            .put("r10_11_dispatch_count", dispatchCount)
            .put("r10_11_browser_dispatch_count", browserDispatchCount)
            .put("r10_11_visual_read_count", visualReadCount)
            .put("r10_11_replan_attempt_count", replanAttemptCount)
            .put("r10_11_replan_applied_count", replanAppliedCount)
            .put("r10_11_replan_applied", true)
            .put("r10_11_revised_plan_fingerprint", candidate.planFingerprint())
            .put("r10_11_pre_restart_verified_prefix", longObjective.verifiedSubgoalCount())
            .put("r10_11_pre_restart_plan_revision", longObjective.planRevision())
            .put("r10_11_pre_restart_adaptive_revision", adaptiveLoop.currentRevision())

        val titleBeforeRestart =
            longObjective.partialResult(
                key = "page_title"
            )

        if (
            titleBeforeRestart.optBoolean("available", false) &&
            titleBeforeRestart.optBoolean("verified", false)
        ) {
            runtimeContext
                .put("r10_11_pre_restart_partial_fingerprint", titleBeforeRestart.optString("fingerprint"))
                .put("r10_11_pre_restart_partial_value", titleBeforeRestart.optString("value"))
        }

        val nextCheckpointCount = durableStepCheckpointCount + 1
        runtimeContext.put("r10_11_durable_checkpoint_count", nextCheckpointCount)

        val revisedCheckpoint =
            r10_10BuildProductionPlannerCheckpoint(
                planner = candidate,
                longObjective = longObjective,
                adaptiveLoop = adaptiveLoop,
                continuity = continuity,
                runtimeContext = runtimeContext,
                checkpointTag = "r10_11_revised_suffix_ready",
                safeAutoResume = true,
                stepInFlight = false,
                lastStepId = replan.optString("failed_subgoal_id"),
                lastExecutor = "verified_failure_replan"
            )
                .put("last_step_success", false)
                .put("last_step_status", "REPLANNED")
                .put("last_failure_layer", "verified_failure")

        val revisedPersisted =
            durableGoalStore.checkpoint(
                goalId,
                revisedCheckpoint
            )
                ?: return JSONObject()
                    .put("production_dynamic_planner", true)
                    .put("success", false)
                    .put("verified", false)
                    .put("terminal_verified", false)
                    .put("reason", "revised_plan_checkpoint_failed")
                    .put("goal_id", goalId)
                    .put("blind_replay_allowed", false)

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "r10_11_production_suffix_replanned",
            message = "R10.11 verified failure перестроил только unresolved suffix",
            details =
                "goal_id=$goalId; revision=${longObjective.planRevision()}; " +
                    "adaptive_revision=${adaptiveLoop.currentRevision()}; " +
                    "candidate=${candidate.planFingerprint()}; " +
                    "verified_prefix=${longObjective.verifiedSubgoalCount()}"
        )

        val forceDurableReload =
            runtimeContext.optBoolean(
                "r10_11_force_durable_reload_after_replan",
                false
            ) &&
                !runtimeContext.optBoolean(
                    "r10_11_durable_reload_completed",
                    false
                )

        if (forceDurableReload) {
            val reopenedStore =
                AyanaDurableGoalStore(
                    applicationContext
                )

            val interruptedCount =
                reopenedStore.markInterruptedGoals(
                    "r10_11_service_recreation_probe"
                )

            val recoverable = reopenedStore.getRecoverableJson(12)
            var interruptedGoal: JSONObject? = null
            for (index in 0 until recoverable.length()) {
                val item = recoverable.optJSONObject(index) ?: continue
                if (item.optString("id") == goalId) {
                    interruptedGoal = JSONObject(item.toString())
                    break
                }
            }

            if (interruptedGoal == null) {
                return JSONObject()
                    .put("production_dynamic_planner", true)
                    .put("success", false)
                    .put("verified", false)
                    .put("terminal_verified", false)
                    .put("reason", "durable_reload_goal_not_found")
                    .put("goal_id", goalId)
                    .put("interrupted_goal_count", interruptedCount)
                    .put("blind_replay_allowed", false)
            }

            val recoveryDecision =
                crossLaneRecoveryContinuity.evaluate(
                    goal = interruptedGoal,
                    automatic = true
                )

            val recoveryPolicyAllows =
                recoveryDecision.optString("strategy") ==
                    AyanaCrossLaneRecoveryContinuity.Strategy.RESTORE_AND_CONTINUE.name &&
                    recoveryDecision.optBoolean("automatic_resume_allowed", false) &&
                    !recoveryDecision.optBoolean("blind_replay_allowed", true)

            if (!recoveryPolicyAllows) {
                return JSONObject()
                    .put("production_dynamic_planner", true)
                    .put("success", false)
                    .put("verified", false)
                    .put("terminal_verified", false)
                    .put("reason", "r10_3_recovery_policy_blocked")
                    .put("goal_id", goalId)
                    .put("recovery_decision", recoveryDecision)
                    .put("blind_replay_allowed", false)
            }

            runtimeContext
                .put("r10_11_recovery_strategy", recoveryDecision.optString("strategy"))
                .put(
                    "r10_11_automatic_recovery_allowed",
                    recoveryDecision.optBoolean("automatic_resume_allowed", false)
                )
                .put(
                    "r10_11_interruption_checkpoint_preserved",
                    interruptedGoal.optString("interrupted_from_checkpoint") ==
                        "r10_11_revised_suffix_ready" &&
                        !interruptedGoal.optBoolean("interrupted_from_in_flight", true)
                )

            val recovered =
                reopenedStore.incrementRecovery(goalId)
                    ?: return JSONObject()
                        .put("production_dynamic_planner", true)
                        .put("success", false)
                        .put("verified", false)
                        .put("terminal_verified", false)
                        .put("reason", "durable_reload_recovery_increment_failed")
                        .put("goal_id", goalId)
                        .put("blind_replay_allowed", false)

            runtimeContext
                .put("r10_11_durable_reload_completed", true)
                .put("r10_11_durable_store_reopened", true)
                .put("r10_11_interrupted_goal_count", interruptedCount)
                .put("r10_11_recovery_count_incremented", recovered.optInt("recovery_count", 0) > 0)

            runtimeContext.put(
                "r10_11_durable_checkpoint_count",
                nextCheckpointCount + 1
            )

            val recoveredCheckpoint =
                r10_10BuildProductionPlannerCheckpoint(
                    planner = candidate,
                    longObjective = longObjective,
                    adaptiveLoop = adaptiveLoop,
                    continuity = continuity,
                    runtimeContext = runtimeContext,
                    checkpointTag = "r10_11_recovery_handoff_ready",
                    safeAutoResume = true,
                    stepInFlight = false,
                    lastStepId = "",
                    lastExecutor = ""
                )
                    .put("status", AyanaDurableGoalStore.STATUS_ACTIVE)
                    .put("recovery_count", recovered.optInt("recovery_count", 0))
                    .put("last_checkpoint", "r10_11_recovery_handoff_ready")

            val handoffSnapshot =
                reopenedStore.checkpoint(
                    goalId,
                    recoveredCheckpoint
                )
                    ?: return JSONObject()
                        .put("production_dynamic_planner", true)
                        .put("success", false)
                        .put("verified", false)
                        .put("terminal_verified", false)
                        .put("reason", "recovery_handoff_checkpoint_failed")
                        .put("goal_id", goalId)
                        .put("blind_replay_allowed", false)

            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "r10_11_durable_recovery_handoff",
                message = "R10.11 durable store переоткрыт; objective передан recovery worker",
                details =
                    "goal_id=$goalId; interrupted=$interruptedCount; " +
                        "recovery=${handoffSnapshot.optInt("recovery_count", 0)}; " +
                        "verified_prefix=${longObjective.verifiedSubgoalCount()}"
            )

            return JSONObject()
                .put("production_dynamic_planner", true)
                .put("r10_11_acceptance", runtimeContext.optBoolean("r10_11_acceptance", false))
                .put("restart_handoff_required", true)
                .put("resume_goal", handoffSnapshot)
                .put("goal_id", goalId)
                .put("success", false)
                .put("verified", false)
                .put("terminal_verified", false)
                .put("durable_store_reopened", true)
                .put("interrupted_goal_count", interruptedCount)
                .put("reason", "durable_recovery_handoff")
                .put("blind_replay_allowed", false)
        }

        return executeR10_10ProductionPlannerLoop(
            goalId = goalId,
            command = command,
            planner = candidate,
            longObjective = longObjective,
            adaptiveLoop = adaptiveLoop,
            continuity = continuity,
            runtimeContext = runtimeContext,
            commandToken = commandToken,
            automaticRecovery = automaticRecovery
        )
    }

    private fun r10_10BuildProductionPlannerCheckpoint(
        planner: AyanaDynamicGoalPlanner,
        longObjective: AyanaLongObjectiveCoordinator,
        adaptiveLoop: AyanaAdaptiveExecutionLoop,
        continuity: AyanaCrossLaneAdaptiveContinuity,
        runtimeContext: JSONObject,
        checkpointTag: String,
        safeAutoResume: Boolean,
        stepInFlight: Boolean,
        lastStepId: String,
        lastExecutor: String
    ): JSONObject =
        crossLaneRecoveryContinuity
            .buildRecoveryCheckpoint(
                adaptiveLoop = adaptiveLoop,
                continuity = continuity,
                checkpointTag = checkpointTag,
                safeAutoResume = safeAutoResume
            )
            .put(
                "mode",
                AyanaDurableGoalStore.MODE_ORCHESTRATOR
            )
            .put(
                "production_dynamic_planner",
                true
            )
            .put(
                "dynamic_planner_plan",
                planner.snapshot()
            )
            .put(
                "long_objective_plan",
                longObjective.snapshot()
            )
            .put(
                "dynamic_planner_runtime_context",
                JSONObject(runtimeContext.toString())
            )
            .put(
                "step_in_flight",
                stepInFlight
            )
            .put(
                "last_step_id",
                lastStepId
            )
            .put(
                "last_step_action",
                lastExecutor
            )
            .put(
                "safe_auto_resume",
                safeAutoResume
            )

    private fun resumeR10_10ProductionDynamicPlanner(
        goal: JSONObject,
        silent: Boolean,
        automaticRecovery: Boolean
    ) {
        val command =
            goal
                .optString("command")
                .trim()

        val planner =
            try {
                AyanaDynamicGoalPlanner.restore(
                    goal.optJSONObject(
                        "dynamic_planner_plan"
                    )
                )
            } catch (error: Throwable) {
                durableGoalStore.markPaused(
                    goal.optString("id"),
                    "R10.10 planner restore failed: ${error.message ?: error.javaClass.simpleName}"
                )
                respondAndResume(
                    text = "Сохранённая длинная цель остановлена: planner state не прошёл проверку.",
                    silent = silent,
                    success = false,
                    technical =
                        JSONObject()
                            .put("production_dynamic_planner", true)
                            .put("recovery", true)
                            .put("planner_restore_verified", false)
                            .put("blind_replay_allowed", false)
                            .put(
                                "reason",
                                error.message ?: error.javaClass.simpleName
                            )
                            .toString()
                )
                return
            }

        if (
            planner.objective().trim() !=
            command.trim()
        ) {
            durableGoalStore.markPaused(
                goal.optString("id"),
                "R10.10 planner objective mismatch on recovery"
            )
            respondAndResume(
                text = "Сохранённая длинная цель остановлена: objective не совпадает с persisted planner.",
                silent = silent,
                success = false,
                technical =
                    JSONObject()
                        .put("production_dynamic_planner", true)
                        .put("recovery", true)
                        .put("planner_restore_verified", false)
                        .put("blind_replay_allowed", false)
                        .put("reason", "planner_objective_mismatch")
                        .toString()
            )
            return
        }

        startR10_10ProductionDynamicPlannerWorker(
            command = command,
            silent = silent,
            planner = planner,
            resumeGoal = goal,
            automaticRecovery = automaticRecovery
        )
    }



    private fun isR10_23VoiceBackgroundAcceptanceCommand(
        command: String
    ): Boolean {
        val normalized =
            command
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()
                .removePrefix("аяна ")
                .trim()
                .replace(Regex("\\br10\\s+23\\b"), "r10.23")
                .replace(Regex("\\b2\\s+0\\b"), "2.0")

        return normalized in
            setOf(
                "проверь голос и фон 2.0",
                "проверь голос и фоновую работу 2.0",
                "проверь voice background 2.0",
                "проверь voice and background 2.0",
                "проверь r10.23"
            )
    }

    private fun runR10_23VoiceBackgroundAcceptance(
        silent: Boolean
    ) {
        executionPhase(
            phase = "r10_23_voice_background_2_0_acceptance",
            executor = "voice_background_coordinator_v2_0"
        )

        val localSelfTest =
            try {
                voiceBackgroundCoordinator.contractSelfTest()
            } catch (_: Throwable) {
                false
            }

        val micPermissionGranted =
            checkSelfPermission(
                Manifest.permission.RECORD_AUDIO
            ) == PackageManager.PERMISSION_GRANTED

        val serviceLive =
            isRunning &&
                !shuttingDown

        val recognitionReady =
            modelReady &&
                recognizer != null

        val wakeOnly =
            removeLeadingWakeWord(
                "аяна"
            )

        val wakeCommand =
            removeLeadingWakeWord(
                "аяна открой youtube"
            )

        val wakeGrammarVerified =
            wakeOnly.isBlank() &&
                wakeCommand == "открой youtube"

        val testCoordinator =
            AyanaVoiceBackgroundCoordinator()

        val followSession =
            testCoordinator.enterFollowUp(
                1_000L
            )
        val beforeDeadline =
            testCoordinator.evaluateFollowUp(
                sessionGeneration = followSession.generation,
                speechSeen = false,
                recognitionChangedAtMs = 1_000L,
                nowMs = 30_999L
            )
        val atDeadline =
            testCoordinator.evaluateFollowUp(
                sessionGeneration = followSession.generation,
                speechSeen = false,
                recognitionChangedAtMs = 1_000L,
                nowMs = 31_000L
            )

        val followUpThirtySecondsVerified =
            AyanaVoiceBackgroundCoordinator.DEFAULT_FOLLOW_UP_WINDOW_MS == 30_000L &&
                beforeDeadline.status ==
                AyanaVoiceBackgroundCoordinator.FollowUpStatus.ACTIVE &&
                atDeadline.status ==
                AyanaVoiceBackgroundCoordinator.FollowUpStatus.EXPIRED_SILENCE

        val staleSession =
            testCoordinator.enterFollowUp(
                40_000L
            )
        testCoordinator.enterWake(
            40_100L
        )
        val staleRejected =
            testCoordinator.evaluateFollowUp(
                sessionGeneration = staleSession.generation,
                speechSeen = false,
                recognitionChangedAtMs = 40_000L,
                nowMs = 70_000L
            ).status ==
            AyanaVoiceBackgroundCoordinator.FollowUpStatus.STALE_SESSION

        val recoverySource =
            testCoordinator.enterFollowUp(
                80_000L
            )
        val recovered =
            testCoordinator.recoverService(
                80_100L
            )
        val recoveryWakeOnly =
            recovered.mode ==
                AyanaVoiceBackgroundCoordinator.Mode.WAKE &&
                recovered.serviceEpoch >
                recoverySource.serviceEpoch &&
                !testCoordinator.isCurrent(
                    recoverySource.generation
                )

        val firstDispatch =
            testCoordinator.claimVoiceDispatch(
                "аяна открой youtube",
                100_000L
            )
        val duplicateDispatch =
            testCoordinator.claimVoiceDispatch(
                "Аяна, открой YouTube",
                100_600L
            )
        val laterDispatch =
            testCoordinator.claimVoiceDispatch(
                "аяна открой youtube",
                102_500L
            )
        val duplicateDispatchGuardVerified =
            firstDispatch.allowed &&
                !duplicateDispatch.allowed &&
                duplicateDispatch.duplicateSuppressed &&
                laterDispatch.allowed

        val acceptanceOk =
            localSelfTest &&
                serviceLive &&
                recognitionReady &&
                micPermissionGranted &&
                wakeGrammarVerified &&
                followUpThirtySecondsVerified &&
                staleRejected &&
                recoveryWakeOnly &&
                duplicateDispatchGuardVerified

        val evidence =
            JSONObject()
                .put("r10_23_acceptance", true)
                .put("r10_23_voice_background_2_0", true)
                .put("acceptance_ok", acceptanceOk)
                .put(
                    "voice_background_coordinator_version",
                    AyanaVoiceBackgroundCoordinator.VERSION
                )
                .put(
                    "voice_background_contract_version",
                    AyanaVoiceBackgroundCoordinator.CONTRACT_VERSION
                )
                .put("local_contract_self_test", localSelfTest)
                .put("service_live_verified", serviceLive)
                .put("recognition_model_ready", recognitionReady)
                .put("record_audio_permission_granted", micPermissionGranted)
                .put("wake_grammar_verified", wakeGrammarVerified)
                .put("wake_only_ack_contract_verified", wakeOnly.isBlank())
                .put("wake_plus_command_contract_verified", wakeCommand == "открой youtube")
                .put(
                    "follow_up_window_ms",
                    AyanaVoiceBackgroundCoordinator.DEFAULT_FOLLOW_UP_WINDOW_MS
                )
                .put("follow_up_30s_verified", followUpThirtySecondsVerified)
                .put("stale_voice_session_rejected", staleRejected)
                .put("service_recovery_returns_to_wake", recoveryWakeOnly)
                .put("voice_blind_command_replay_allowed", false)
                .put("duplicate_voice_dispatch_guard_verified", duplicateDispatchGuardVerified)
                .put(
                    "duplicate_voice_dispatch_window_ms",
                    AyanaVoiceBackgroundCoordinator.DEFAULT_DUPLICATE_VOICE_DISPATCH_WINDOW_MS
                )
                .put("durable_goal_recovery_owner_preserved", true)
                .put("human_acoustic_wake_self_proven", false)
                .put("manual_human_wake_test_required", true)
                .put("agent_core_used", false)
                .put("network_required", false)
                .put("unresolved_side_effect", false)
                .put("orb_visual_implementation_changed", false)

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state =
                if (acceptanceOk) {
                    "r10_23_voice_background_2_0_verified"
                } else {
                    "r10_23_voice_background_2_0_failed"
                },
            message =
                if (acceptanceOk) {
                    "R10.23 подтвердил live voice-service readiness + 30s follow-up + stale-session/recovery/duplicate-dispatch contracts"
                } else {
                    "R10.23 Voice & Background 2.0 не подтвердил все gates"
                },
            details = evidence.toString().take(5000)
        )

        if (acceptanceOk) {
            respondAndResume(
                text =
                    "R10.23 подтверждён на уровне voice/background control-plane: Service и локальная модель готовы, follow-up = 30 секунд, stale voice-session блокируется, lifecycle recovery возвращается в WAKE без blind replay, повторный voice-dispatch подавляется. Человеческое произнесение wake-word остаётся отдельным ручным acoustic test и не подменяется synthetic self-test.",
                silent = silent,
                success = true,
                technical = evidence.toString()
            )
        } else {
            respondAndResume(
                text = "R10.23 не прошёл acceptance. См. technical evidence в History.",
                silent = silent,
                success = false,
                technical = evidence.toString()
            )
        }
    }

    private fun isR10_22CommunicationAssistantAcceptanceCommand(
        command: String
    ): Boolean {
        val normalized =
            command
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()
                .removePrefix("аяна ")
                .trim()
                .replace(Regex("\\br10\\s+22\\b"), "r10.22")
                .replace(Regex("\\b2\\s+0\\b"), "2.0")

        return normalized in
            setOf(
                "проверь уведомления и коммуникации 2.0",
                "проверь уведомления и общение 2.0",
                "проверь communication assistant 2.0",
                "проверь notifications communication assistant",
                "проверь r10.22"
            )
    }

    private fun isCommunicationDigestRequest(
        command: String
    ): Boolean {
        val c =
            command
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()

        val notificationScope =
            c.contains("уведомлен") ||
                c.contains("сообщен")

        if (!notificationScope) return false
        if (
            c.contains("настрой") ||
            c.contains("разрешен") ||
            c.contains("доступ к уведом")
        ) {
            return false
        }

        return c.contains("разбери") ||
            c.contains("проанализ") ||
            c.contains("сгрупп") ||
            c.contains("сводк") ||
            c.contains("требуют ответа") ||
            c.contains("требует ответа") ||
            c.contains("нужен ответ") ||
            c.contains("важные уведом") ||
            c.contains("важные сообщ") ||
            c.contains("что требует внимания") ||
            c.contains("какие требуют внимания")
    }

    private fun isCommunicationDraftRequest(
        command: String
    ): Boolean {
        val c =
            command
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()

        val scope =
            c.contains("уведомлен") ||
                c.contains("сообщен")
        if (!scope || !c.contains("ответ")) return false

        return c.contains("подготов") ||
            c.contains("состав") ||
            c.contains("напиши") ||
            c.contains("предлож") ||
            c.contains("черновик")
    }

    private fun isCommunicationSendFromNotificationRequest(
        command: String
    ): Boolean {
        val c =
            command
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()

        val send =
            c.contains("отправ") ||
                c.contains("пошли") ||
                c.contains("ответь")
        val notificationScope =
            c.contains("последнее уведом") ||
                c.contains("последнему уведом") ||
                c.contains("последнее сообщ") ||
                c.contains("последнему сообщ") ||
                c.contains("на это уведом")

        return send && notificationScope
    }

    private fun runLocalCommunicationDigest(
        silent: Boolean
    ) {
        val source =
            AyanaNotificationListenerService.readRecent(
                context = this,
                limit = 32,
                appFilter = null,
                projection = AyanaNotificationListenerService.PROJECTION_FULL
            )

        val analysis =
            communicationAssistantEngine.analyzeReadResult(source)

        if (!analysis.optBoolean("success", false)) {
            respondAndResume(
                text = source.optString("message").ifBlank {
                    "Не удалось прочитать уведомления для анализа."
                },
                silent = silent,
                success = false,
                terminalStatus =
                    when (source.optString("terminal_status").uppercase(Locale.ROOT)) {
                        "BLOCKED" -> AyanaCommandHistoryStore.STATUS_BLOCKED
                        "UNSUPPORTED" -> AyanaCommandHistoryStore.STATUS_UNSUPPORTED
                        else -> null
                    },
                technical = analysis.toString()
            )
            return
        }

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "communication_digest_verified",
            message = "R10.22 локально сгруппировал уведомления и выделил требующие ответа",
            details = analysis.toString().take(5000)
        )

        respondAndResume(
            text = communicationAssistantEngine.renderRussian(analysis),
            silent = silent,
            success = true,
            technical = analysis.toString()
        )
    }

    private fun runLocalCommunicationDraft(
        silent: Boolean
    ) {
        val source =
            AyanaNotificationListenerService.readRecent(
                context = this,
                limit = 32,
                appFilter = null,
                projection = AyanaNotificationListenerService.PROJECTION_FULL
            )

        val draft =
            communicationAssistantEngine.buildDraftFromReadResult(source)

        if (!draft.optBoolean("success", false)) {
            respondAndResume(
                text = source.optString("message").ifBlank {
                    "Не нашлось уведомления, для которого можно подготовить черновик ответа."
                },
                silent = silent,
                success = false,
                terminalStatus =
                    when (source.optString("terminal_status").uppercase(Locale.ROOT)) {
                        "BLOCKED" -> AyanaCommandHistoryStore.STATUS_BLOCKED
                        "UNSUPPORTED" -> AyanaCommandHistoryStore.STATUS_UNSUPPORTED
                        else -> null
                    },
                technical = draft.toString()
            )
            return
        }

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "communication_draft_prepared",
            message = "R10.22 подготовил DRAFT_ONLY ответ без send authority",
            details = draft.toString().take(3500)
        )

        val app = draft.optString("target_app").ifBlank { "приложение" }
        respondAndResume(
            text =
                "Черновик ответа для $app:\n${draft.optString("draft")}\n\n" +
                    "Это только черновик — AYANA его не отправляла.",
            silent = silent,
            success = true,
            technical = draft.toString()
        )
    }

    private fun runLocalCommunicationSendBlocked(
        silent: Boolean
    ) {
        val policy =
            communicationAssistantEngine.actionPolicy(
                action = "send_message",
                explicitUserAction = true
            )

        respondUnsupportedAndResume(
            text =
                "Безопасная прямая отправка ответа из уведомления пока не зарегистрирована как проверяемый executor. " +
                    "AYANA может разобрать уведомления и подготовить черновик, но не будет выдавать отправку за выполненную.",
            silent = silent,
            technical = policy.toString()
        )
    }

    private fun createR10_22AcceptanceNotificationChannel() {
        if (Build.VERSION.SDK_INT < 26) return
        val manager = getSystemService(NotificationManager::class.java)
        if (manager.getNotificationChannel(R10_22_ACCEPTANCE_CHANNEL_ID) != null) return
        manager.createNotificationChannel(
            NotificationChannel(
                R10_22_ACCEPTANCE_CHANNEL_ID,
                "AYANA — R10.22 acceptance",
                NotificationManager.IMPORTANCE_LOW
            ).apply {
                description = "Временные тестовые уведомления Communication Assistant"
                setShowBadge(false)
            }
        )
    }

    private fun postR10_22AcceptanceNotification(
        notificationId: Int,
        marker: String
    ): Boolean {
        if (
            Build.VERSION.SDK_INT >= 33 &&
            checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS) !=
            PackageManager.PERMISSION_GRANTED
        ) {
            return false
        }

        createR10_22AcceptanceNotificationChannel()

        val builder =
            if (Build.VERSION.SDK_INT >= 26) {
                Notification.Builder(this, R10_22_ACCEPTANCE_CHANNEL_ID)
            } else {
                @Suppress("DEPRECATION")
                Notification.Builder(this)
            }

        val notification =
            builder
                .setSmallIcon(android.R.drawable.ic_dialog_email)
                .setContentTitle(marker)
                .setContentText("Можешь подтвердить встречу сегодня?")
                .setCategory(Notification.CATEGORY_MESSAGE)
                .setOnlyAlertOnce(true)
                .setAutoCancel(false)
                .build()

        return try {
            getSystemService(NotificationManager::class.java)
                .notify(notificationId, notification)
            true
        } catch (_: Throwable) {
            false
        }
    }

    private fun cancelR10_22AcceptanceNotification(
        notificationId: Int
    ) {
        try {
            getSystemService(NotificationManager::class.java)
                .cancel(notificationId)
        } catch (_: Throwable) {
        }
    }

    private fun markerNotificationCount(
        source: JSONObject,
        marker: String
    ): Int {
        val items = source.optJSONArray("notifications") ?: JSONArray()
        var count = 0
        for (index in 0 until items.length()) {
            val item = items.optJSONObject(index) ?: continue
            if (
                item.optString("title").contains(marker, ignoreCase = true) ||
                item.optString("text").contains(marker, ignoreCase = true)
            ) {
                count += 1
            }
        }
        return count
    }

    private fun runR10_22CommunicationAssistantAcceptance(
        silent: Boolean
    ) {
        executionPhase(
            phase = "r10_22_notifications_communication_assistant_acceptance",
            executor = "communication_assistant_v2_0+notification_listener"
        )

        val commandToken = activeCommandToken

        val worker =
            thread(
                start = false,
                name = "AyanaCommunicationR10_22Acceptance"
            ) {
                try {
                    val localSelfTest =
                        try {
                            communicationAssistantEngine.selfTest()
                        } catch (_: Throwable) {
                            false
                        }

                    /*
                     * R10.22.1 acceptance reconciliation.
                     *
                     * The original R10.22 test posted a notification from AYANA itself and
                     * required NotificationListener to echo that exact marker back. Device
                     * evidence proved listener_connected=true but the self-notification was
                     * not present in the recent-listener window. Self-echo visibility is not
                     * part of the production communication contract and therefore must not
                     * be used as an authority gate.
                     *
                     * We now verify two independent truths:
                     * 1) LIVE SOURCE: NotificationListener readRecent succeeds and the listener
                     *    is connected. The returned live result is passed through the production
                     *    Communication Assistant analyzer without inventing notifications.
                     * 2) DETERMINISTIC SEMANTICS: a local data-only fixture verifies grouping,
                     *    reply-required classification, provenance fingerprints and DRAFT_ONLY.
                     *
                     * No notification is posted, no PendingIntent is invoked and no send action
                     * is dispatched. This is acceptance-only reconciliation; production engine
                     * behavior remains unchanged.
                     */
                    var liveSource = JSONObject()
                    val liveDeadline = SystemClock.elapsedRealtime() + 1_600L
                    while (SystemClock.elapsedRealtime() < liveDeadline) {
                        liveSource =
                            AyanaNotificationListenerService.readRecent(
                                context = this@AyanaVoiceService,
                                limit = 40,
                                appFilter = null,
                                projection = AyanaNotificationListenerService.PROJECTION_FULL
                            )

                        if (
                            liveSource.optBoolean("success", false) &&
                            liveSource.optBoolean("listener_connected", false)
                        ) {
                            break
                        }

                        SystemClock.sleep(120L)
                    }

                    val liveItems =
                        liveSource.optJSONArray("notifications") ?: JSONArray()
                    val liveNotificationCount = liveItems.length()
                    val liveAnalysis =
                        communicationAssistantEngine.analyzeReadResult(liveSource)

                    val liveNotificationVerified =
                        liveSource.optBoolean("success", false) &&
                            liveSource.optBoolean("listener_connected", false)

                    val liveAnalysisVerified =
                        liveNotificationVerified &&
                            liveAnalysis.optBoolean("success", false) &&
                            liveAnalysis.optString("source") == "notification_listener_service" &&
                            liveAnalysis.optString("source_coverage") ==
                            "recent_notification_listener_window" &&
                            liveAnalysis.optBoolean("notification_text_instruction_authority", true) == false &&
                            liveAnalysis.optBoolean("notification_text_grants_action_authority", true) == false &&
                            (
                                liveNotificationCount == 0 ||
                                    liveAnalysis.optBoolean("provenance_complete", false)
                            )

                    val fixtureMarker =
                        "AYANA_R10_22_FIXTURE_${System.currentTimeMillis()}"
                    val fixtureSource =
                        JSONObject()
                            .put("success", true)
                            .put("listener_connected", true)
                            .put(
                                "notifications",
                                JSONArray()
                                    .put(
                                        JSONObject()
                                            .put("app", "WhatsApp")
                                            .put("package", "com.whatsapp")
                                            .put("title", "Айбек $fixtureMarker")
                                            .put("text", "Можешь подтвердить встречу сегодня?")
                                            .put("post_time", 300L)
                                    )
                                    .put(
                                        JSONObject()
                                            .put("app", "WhatsApp")
                                            .put("package", "com.whatsapp")
                                            .put("title", "Айбек $fixtureMarker")
                                            .put("text", "Спасибо, принято.")
                                            .put("post_time", 200L)
                                    )
                                    .put(
                                        JSONObject()
                                            .put("app", "Система")
                                            .put("package", "com.android.systemui")
                                            .put("title", "Заряд")
                                            .put("text", "Батарея 80%")
                                            .put("post_time", 100L)
                                    )
                            )

                    val fixtureAnalysis =
                        communicationAssistantEngine.analyzeReadResult(fixtureSource)
                    val draft =
                        communicationAssistantEngine.buildDraftFromReadResult(
                            fixtureSource,
                            fixtureMarker
                        )
                    val sendPolicy =
                        communicationAssistantEngine.actionPolicy(
                            action = "send_message",
                            explicitUserAction = true
                        )

                    val liveReplyClassificationVerified =
                        if (!fixtureAnalysis.optBoolean("success", false)) {
                            false
                        } else {
                            val items =
                                fixtureAnalysis.optJSONArray("notifications") ?: JSONArray()
                            var matched = false
                            for (index in 0 until items.length()) {
                                val item = items.optJSONObject(index) ?: continue
                                if (
                                    item.optString("title")
                                        .contains(fixtureMarker, ignoreCase = true) &&
                                    item.optBoolean("reply_required", false) &&
                                    item.optBoolean("needs_attention", false) &&
                                    item.optString("provenance") ==
                                    "notification_listener_service" &&
                                    item.optString("fingerprint").length == 64
                                ) {
                                    matched = true
                                    break
                                }
                            }
                            matched
                        }

                    val groupingVerified =
                        fixtureAnalysis.optBoolean("success", false) &&
                            fixtureAnalysis.optInt("notification_count", 0) == 3 &&
                            fixtureAnalysis.optInt("conversation_count", 0) == 2 &&
                            fixtureAnalysis.optInt("reply_required_count", 0) == 1 &&
                            fixtureAnalysis.optBoolean("provenance_complete", false)

                    val draftVerified =
                        draft.optBoolean("success", false) &&
                            draft.optBoolean("draft_generated", false) &&
                            draft.optBoolean("draft_only", false) &&
                            draft.optBoolean("requires_user_review", false) &&
                            draft.optString("source_fingerprint").length == 64 &&
                            draft.optString("draft_fingerprint").length == 64 &&
                            draft.optString("provenance") == "notification_listener_service" &&
                            !draft.optBoolean("send_authority", true)

                    val sendFailClosed =
                        !sendPolicy.optBoolean("allowed", true) &&
                            !sendPolicy.optBoolean("supported", true) &&
                            !sendPolicy.optBoolean("send_authority", true) &&
                            sendPolicy.optString("reason") ==
                            "verified_send_executor_not_registered"

                    val acceptanceOk =
                        localSelfTest &&
                            liveNotificationVerified &&
                            liveAnalysisVerified &&
                            liveReplyClassificationVerified &&
                            groupingVerified &&
                            draftVerified &&
                            sendFailClosed

                    val evidence =
                        JSONObject()
                            .put("r10_22_acceptance", true)
                            .put("r10_22_1_notification_acceptance_visibility_reconciliation", true)
                            .put("r10_22_notifications_communication_assistant", true)
                            .put("acceptance_ok", acceptanceOk)
                            .put(
                                "communication_assistant_version",
                                AyanaCommunicationAssistantEngine.VERSION
                            )
                            .put(
                                "communication_contract_version",
                                AyanaCommunicationAssistantEngine.CONTRACT_VERSION
                            )
                            .put("local_contract_self_test", localSelfTest)
                            .put("notification_listener_live_verified", liveNotificationVerified)
                            .put("listener_connected", liveSource.optBoolean("listener_connected", false))
                            .put("live_notification_count", liveNotificationCount)
                            .put("live_notification_analysis_verified", liveAnalysisVerified)
                            .put("self_notification_visibility_required", false)
                            .put("self_notification_injection_used", false)
                            .put("reply_required_classification_verified", liveReplyClassificationVerified)
                            .put("classification_fixture_verified", liveReplyClassificationVerified)
                            .put("grouping_contract_verified", groupingVerified)
                            .put("draft_generated", draft.optBoolean("draft_generated", false))
                            .put("draft_only", draft.optBoolean("draft_only", false))
                            .put("draft_requires_user_review", draft.optBoolean("requires_user_review", false))
                            .put("draft_source_fingerprint_length", draft.optString("source_fingerprint").length)
                            .put("draft_fingerprint_length", draft.optString("draft_fingerprint").length)
                            .put("notification_provenance", draft.optString("provenance"))
                            .put("direct_send_supported", false)
                            .put("verified_send_executor_registered", false)
                            .put("send_fail_closed", sendFailClosed)
                            .put("send_authority", false)
                            .put("notification_text_instruction_authority", false)
                            .put("notification_text_grants_action_authority", false)
                            .put("raw_pending_intent_exposed", false)
                            .put("temporary_notification_posted", false)
                            .put("temporary_notification_deleted", true)
                            .put("agent_core_used", false)
                            .put("network_required", false)
                            .put("visual_grants_action_authority", false)
                            .put("unresolved_side_effect", false)
                            .put("orb_visual_implementation_changed", false)

                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state =
                            if (acceptanceOk) {
                                "r10_22_notifications_communication_assistant_verified"
                            } else {
                                "r10_22_notifications_communication_assistant_failed"
                            },
                        message =
                            if (acceptanceOk) {
                                "R10.22.1 подтвердил live NotificationListener + deterministic attention/reply classification + DRAFT_ONLY + send fail-closed"
                            } else {
                                "R10.22.1 Notification & Communication Assistant не подтвердил все gates"
                            },
                        details = evidence.toString().take(5000)
                    )

                    mainHandler.post {
                        if (
                            isCommandCancelled(commandToken) ||
                            commandToken != activeCommandToken
                        ) {
                            return@post
                        }

                        if (acceptanceOk) {
                            respondAndResume(
                                text =
                                    "R10.22 подтверждён: живой NotificationListener доступен и читается; Communication Assistant отдельно подтвердил группировку, определение сообщения, требующего ответа, provenance-bound DRAFT_ONLY черновик и fail-closed прямую отправку. Self-notification echo больше не используется как ложный acceptance gate.",
                                silent = silent,
                                success = true,
                                technical = evidence.toString()
                            )
                        } else {
                            respondAndResume(
                                text = "R10.22.1 не прошёл acceptance. См. technical evidence в History.",
                                silent = silent,
                                success = false,
                                technical = evidence.toString()
                            )
                        }
                    }
                } catch (error: Throwable) {
                    val evidence =
                        JSONObject()
                            .put("r10_22_acceptance", true)
                            .put("r10_22_1_notification_acceptance_visibility_reconciliation", true)
                            .put("acceptance_ok", false)
                            .put("reason", "r10_22_1_acceptance_exception")
                            .put("error", (error.message ?: error.javaClass.simpleName).take(800))
                            .put("self_notification_injection_used", false)
                            .put("send_authority", false)
                            .put("unresolved_side_effect", false)

                    mainHandler.post {
                        if (
                            !isCommandCancelled(commandToken) &&
                            commandToken == activeCommandToken
                        ) {
                            respondAndResume(
                                text = "R10.22.1 Notification & Communication Assistant завершился ошибкой.",
                                silent = silent,
                                success = false,
                                technical = evidence.toString()
                            )
                        }
                    }
                } finally {
                    if (Thread.currentThread() === currentAgentThread) {
                        currentAgentThread = null
                    }
                }
            }

        currentAgentThread = worker
        executionKernel.bindThread(worker)
        worker.start()
    }

