                            )
                            .put(
                                JSONArray()
                                    .put("Проверка")
                                    .put("AYANA_R10_21_PPTX_VERIFIED")
                            )

                    val pptxResult =
                        officeDocumentEngine
                            .createPresentationArtifact(
                                arguments =
                                    JSONObject()
                                        .put("kind", "pptx")
                                        .put(
                                            "filename",
                                            "AYANA_R10_21_PPTX_${System.currentTimeMillis()}.pptx"
                                        )
                                        .put("title", "AYANA Office 2.0")
                                        .put(
                                            "content",
                                            "R10.21 PowerPoint production verification"
                                        )
                                        .put("columns", JSONArray())
                                        .put("rows", slides)
                                        .put("column_types", JSONArray())
                                        .put("chart_type", "none"),
                                tryBeginPublish = { true },
                                onPublishAccepted = { },
                                onPublishReconciliationStarted = { },
                                onPublishReconciled = { _, _ -> }
                            )

                    publishedReference =
                        pptxResult
                            .optString("artifact_reference")
                            .trim()

                    val pptxPublishedVerified =
                        pptxResult.optBoolean("success", false) &&
                            pptxResult.optBoolean("verified", false) &&
                            pptxResult.optInt("slide_count", 0) == 2 &&
                            pptxResult.optBoolean(
                                "package_reopened_verified",
                                false
                            ) &&
                            pptxResult.optBoolean(
                                "semantic_content_verified",
                                false
                            ) &&
                            publishedReference.isNotBlank()

                    pptxCleanupVerified =
                        if (publishedReference.isBlank()) {
                            false
                        } else {
                            try {
                                contentResolver.delete(
                                    Uri.parse(publishedReference),
                                    null,
                                    null
                                ) > 0
                            } catch (_: Throwable) {
                                false
                            }
                        }

                    publishedReference = ""

                    // R10.21 does not replace the already accepted production PDF writer.
                    // Re-run that exact production round-trip and cleanup to prove no regression.
                    val pdfProbe =
                        acceptanceArtifactRoundTripProbe("pdf")
                    val pdfProductionVerified =
                        pdfProbe.optBoolean("verified", false)

                    val scratchVerified =
                        scratch.optBoolean("verified", false) &&
                            scratch.optBoolean("txt_roundtrip_verified", false) &&
                            scratch.optBoolean("docx_roundtrip_verified", false) &&
                            scratch.optBoolean("docx_package_structure_preserved", false) &&
                            scratch.optBoolean("xlsx_roundtrip_verified", false) &&
                            scratch.optBoolean("xlsx_package_structure_preserved", false) &&
                            scratch.optBoolean("pptx_roundtrip_verified", false) &&
                            scratch.optBoolean("pptx_package_structure_preserved", false) &&
                            scratch.optInt("pptx_slide_count", 0) == 2 &&
                            scratch.optBoolean("pdf_structural_probe_verified", false) &&
                            scratch.optBoolean("scratch_cleanup_verified", false) &&
                            !scratch.optBoolean("source_modified_in_place", true)

                    val acceptanceOk =
                        localSelfTest &&
                            scratchVerified &&
                            pptxPublishedVerified &&
                            pptxCleanupVerified &&
                            pdfProductionVerified

                    val evidence =
                        JSONObject()
                            .put("r10_21_acceptance", true)
                            .put("r10_21_document_office_engine_2_0", true)
                            .put("acceptance_ok", acceptanceOk)
                            .put(
                                "office_document_engine_version",
                                AyanaOfficeDocumentEngine.VERSION
                            )
                            .put(
                                "office_contract_version",
                                AyanaOfficeDocumentEngine.CONTRACT_VERSION
                            )
                            .put("local_contract_self_test", localSelfTest)
                            .put("txt_roundtrip_verified", scratch.optBoolean("txt_roundtrip_verified", false))
                            .put("docx_roundtrip_verified", scratch.optBoolean("docx_roundtrip_verified", false))
                            .put("docx_package_structure_preserved", scratch.optBoolean("docx_package_structure_preserved", false))
                            .put("xlsx_roundtrip_verified", scratch.optBoolean("xlsx_roundtrip_verified", false))
                            .put("xlsx_package_structure_preserved", scratch.optBoolean("xlsx_package_structure_preserved", false))
                            .put("pptx_roundtrip_verified", scratch.optBoolean("pptx_roundtrip_verified", false))
                            .put("pptx_package_structure_preserved", scratch.optBoolean("pptx_package_structure_preserved", false))
                            .put("pptx_slide_count", scratch.optInt("pptx_slide_count", 0))
                            .put("pptx_create_artifact_supported", true)
                            .put("pptx_production_publish_verified", pptxPublishedVerified)
                            .put("pptx_production_reopen_verified", pptxResult.optBoolean("package_reopened_verified", false))
                            .put("pptx_production_semantic_content_verified", pptxResult.optBoolean("semantic_content_verified", false))
                            .put("pptx_artifact_reference_present", pptxResult.optString("artifact_reference").isNotBlank())
                            .put("pptx_test_artifact_deleted", pptxCleanupVerified)
                            .put("pdf_existing_production_roundtrip_verified", pdfProductionVerified)
                            .put("source_modified_in_place", false)
                            .put("document_text_instruction_authority", false)
                            .put("document_text_grants_action_authority", false)
                            .put("network_required", false)
                            .put("agent_core_used", false)
                            .put("unresolved_side_effect", false)
                            .put("orb_visual_implementation_changed", false)

                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state =
                            if (acceptanceOk) {
                                "r10_21_document_office_engine_2_0_verified"
                            } else {
                                "r10_21_document_office_engine_2_0_failed"
                            },
                        message =
                            if (acceptanceOk) {
                                "R10.21 подтвердил TXT/DOCX/XLSX/PPTX read-edit-reopen и production PPTX create_artifact"
                            } else {
                                "R10.21 Document & Office Engine 2.0 не подтвердил все gates"
                            },
                        details = evidence.toString().take(5000)
                    )

                    mainHandler.post {
                        if (
                            isCommandCancelled(commandToken) ||
                            commandToken != activeCommandToken
                        ) {
                            return@post
                        }

                        if (acceptanceOk) {
                            respondAndResume(
                                text =
                                    "R10.21 подтверждён: AYANA прочитала, изменила, повторно открыла и проверила TXT/DOCX/XLSX/PPTX без перестройки OOXML-пакета; production PowerPoint PPTX реально создан, повторно проверен и тестовый файл удалён. PDF production round-trip также подтверждён.",
                                silent = silent,
                                success = true,
                                technical = evidence.toString()
                            )
                        } else {
                            respondAndResume(
                                text = "R10.21 не прошёл acceptance. См. technical evidence в History.",
                                silent = silent,
                                success = false,
                                technical = evidence.toString()
                            )
                        }
                    }
                } catch (error: Throwable) {
                    if (publishedReference.isNotBlank()) {
                        try {
                            pptxCleanupVerified =
                                contentResolver.delete(
                                    Uri.parse(publishedReference),
                                    null,
                                    null
                                ) > 0
                        } catch (_: Throwable) {
                        }
                    }

                    val evidence =
                        JSONObject()
                            .put("r10_21_acceptance", true)
                            .put("acceptance_ok", false)
                            .put("reason", "r10_21_acceptance_exception")
                            .put("error", (error.message ?: error.javaClass.simpleName).take(800))
                            .put("pptx_test_artifact_deleted", pptxCleanupVerified)
                            .put("unresolved_side_effect", false)

                    mainHandler.post {
                        if (
                            !isCommandCancelled(commandToken) &&
                            commandToken == activeCommandToken
                        ) {
                            respondAndResume(
                                text = "R10.21 Document & Office Engine 2.0 завершился ошибкой.",
                                silent = silent,
                                success = false,
                                technical = evidence.toString()
                            )
                        }
                    }
                } finally {
                    if (Thread.currentThread() === currentAgentThread) {
                        currentAgentThread = null
                    }
                }
            }

        currentAgentThread = worker
        executionKernel.bindThread(worker)
        worker.start()
    }


    private fun isR10_20PersonalSearch2AcceptanceCommand(
        command: String
    ): Boolean {
        val normalized =
            command
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()
                .removePrefix("аяна ")
                .trim()
                .replace(Regex("\\br10\\s+20\\b"), "r10.20")

        return normalized in
            setOf(
                "проверь персональный поиск 2.0",
                "проверь персональный поиск 2 0",
                "протестируй персональный поиск 2.0",
                "протестируй персональный поиск 2 0",
                "проверь personal search 2.0",
                "проверь personal search 2 0",
                "проверь r10.20"
            )
    }

    private fun runR10_20PersonalSearch2Acceptance(
        silent: Boolean
    ) {
        executionPhase(
            phase = "r10_20_personal_search_2_0_acceptance",
            executor = "personal_search_engine_v2_0"
        )

        val commandToken =
            activeCommandToken

        val worker =
            thread(
                start = false,
                name = "AyanaPersonalSearchR10_20Acceptance"
            ) {
                var seedId: String? = null
                var seedDeleted = false
                var sessionCleanupVerified = false

                try {
                    val localContractOk =
                        try {
                            personalSearchEngine.contractSelfTest()
                        } catch (_: Throwable) {
                            false
                        }

                    val marker =
                        "AYANA_R10_20_SEARCH_" +
                            UUID.randomUUID()
                                .toString()
                                .take(8)

                    seedId =
                        commandHistoryStore.begin(
                            command = marker,
                            source = "self_test"
                        )

                    commandHistoryStore.finish(
                        id = seedId.orEmpty(),
                        success = true,
                        result =
                            "Контрольная запись R10.20: документ подготовлен в Word DOCX. Маркер $marker",
                        technical = "r10_20_personal_search_seed"
                    )

                    val report =
                        personalSearchEngine.search(
                            request =
                                AyanaPersonalSearchEngine.Request(
                                    query = "ворд",
                                    sources =
                                        linkedSetOf(
                                            AyanaPersonalSearchEngine.Source.HISTORY
                                        )
                                ),
                            perSourceLimit = 12,
                            totalLimit = 20
                        )

                    val hitIndex =
                        report.hits.indexOfFirst { hit ->
                            hit.source ==
                                AyanaPersonalSearchEngine.Source.HISTORY &&
                                (
                                    hit.title.contains(marker) ||
                                        hit.snippet.contains(marker)
                                    )
                        }

                    val hit =
                        report.hits
                            .getOrNull(
                                hitIndex
                            )

                    val envelope =
                        if (hitIndex >= 0) {
                            personalSearchEngine.verifiedResultEnvelope(
                                report = report,
                                resultNumber = hitIndex + 1
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                                .put("reason", "r10_20_seed_hit_not_found")
                        }

                    val semanticExpansionVerified =
                        hit?.matchKind == "semantic_lexical" &&
                            report.expandedQueryTerms.any {
                                it == "word" ||
                                    it == "docx"
                            }

                    val provenanceVerified =
                        hit?.verified == true &&
                            hit.provenance == "command_history_store" &&
                            hit.fingerprint.length == 64 &&
                            envelope.optBoolean("verified", false) &&
                            envelope.optString("fingerprint") == hit.fingerprint &&
                            !envelope.optBoolean("raw_action_uri_exposed", true)

                    val confidenceVerified =
                        (hit?.confidence ?: 0) >= 80

                    val coverageVerified =
                        report.sourceCoverage[
                            AyanaPersonalSearchEngine.Source.HISTORY
                        ]
                            .orEmpty()
                            .contains("local_command_history") &&
                            AyanaPersonalSearchEngine.Source.HISTORY !in
                                report.sourceErrors.keys

                    seedDeleted =
                        commandHistoryStore.delete(
                            seedId.orEmpty()
                        )

                    personalSearchEngine.clearLatestSession()

                    sessionCleanupVerified =
                        personalSearchEngine.latestRequestForSources(
                            setOf(
                                AyanaPersonalSearchEngine.Source.HISTORY
                            )
                        ) == null

                    val acceptanceOk =
                        localContractOk &&
                            hit != null &&
                            semanticExpansionVerified &&
                            provenanceVerified &&
                            confidenceVerified &&
                            coverageVerified &&
                            report.searchContractVersion ==
                                AyanaPersonalSearchEngine.SEARCH_CONTRACT_VERSION &&
                            report.provenanceComplete &&
                            seedDeleted &&
                            sessionCleanupVerified

                    val evidence =
                        JSONObject()
                            .put("r10_20_acceptance", true)
                            .put("r10_20_personal_search_2_0", true)
                            .put("acceptance_ok", acceptanceOk)
                            .put("personal_search_version", AyanaPersonalSearchEngine.VERSION)
                            .put("search_contract_version", report.searchContractVersion)
                            .put("local_contract_self_test", localContractOk)
                            .put("query", report.request.query)
                            .put("semantic_expansion_verified", semanticExpansionVerified)
                            .put("expanded_query_terms", JSONArray(report.expandedQueryTerms))
                            .put("live_history_hit_verified", hit != null)
                            .put("verified_hit_count", report.verifiedHitCount)
                            .put("high_confidence_hit_count", report.highConfidenceHitCount)
                            .put("provenance_complete", report.provenanceComplete)
                            .put("hit_confidence", hit?.confidence ?: 0)
                            .put("hit_match_kind", hit?.matchKind.orEmpty())
                            .put("hit_provenance", hit?.provenance.orEmpty())
                            .put("hit_fingerprint", hit?.fingerprint.orEmpty())
                            .put("verified_result_envelope", envelope.optBoolean("verified", false))
                            .put("verified_result_fingerprint_match", provenanceVerified)
                            .put("raw_action_uri_exposed", envelope.optBoolean("raw_action_uri_exposed", false))
                            .put("source_coverage_truth_verified", coverageVerified)
                            .put("source_errors", report.sourceErrors.keys.joinToString(",") { it.wireName })
                            .put("temporary_history_record_deleted", seedDeleted)
                            .put("temporary_search_session_cleared", sessionCleanupVerified)
                            .put("agent_core_used", false)
                            .put("network_required", false)
                            .put("visual_grants_action_authority", false)
                            .put("unresolved_side_effect", false)
                            .put("orb_visual_implementation_changed", false)

                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state =
                            if (acceptanceOk) {
                                "r10_20_personal_search_2_0_verified"
                            } else {
                                "r10_20_personal_search_2_0_failed"
                            },
                        message =
                            if (acceptanceOk) {
                                "R10.20 подтвердил semantic local search + provenance-bound verified result"
                            } else {
                                "R10.20 Personal Search 2.0 acceptance не подтвердил все обязательные gates"
                            },
                        details = evidence.toString().take(5000)
                    )

                    mainHandler.post {
                        if (
                            isCommandCancelled(commandToken) ||
                            commandToken != activeCommandToken
                        ) {
                            return@post
                        }

                        if (acceptanceOk) {
                            respondAndResume(
                                text =
                                    "R10.20 подтверждён: Personal Search 2.0 нашёл временную History-запись по семантическому варианту «ворд» -> Word/DOCX, закрепил provenance/confidence/fingerprint, сформировал verified-result envelope и полностью удалил тестовые данные.",
                                silent = silent,
                                success = true,
                                technical = evidence.toString()
                            )
                        } else {
                            respondAndResume(
                                text = "R10.20 не прошёл acceptance. См. technical evidence в History.",
                                silent = silent,
                                success = false,
                                technical = evidence.toString()
                            )
                        }
                    }
                } catch (error: Throwable) {
                    try {
                        if (!seedDeleted && !seedId.isNullOrBlank()) {
                            seedDeleted =
                                commandHistoryStore.delete(
                                    seedId.orEmpty()
                                )
                        }
                    } catch (_: Throwable) {
                    }

                    try {
                        personalSearchEngine.clearLatestSession()
                        sessionCleanupVerified =
                            personalSearchEngine.latestRequestForSources(
                                setOf(
                                    AyanaPersonalSearchEngine.Source.HISTORY
                                )
                            ) == null
                    } catch (_: Throwable) {
                    }

                    val evidence =
                        JSONObject()
                            .put("r10_20_acceptance", true)
                            .put("acceptance_ok", false)
                            .put("reason", "r10_20_acceptance_exception")
                            .put("error", (error.message ?: error.javaClass.simpleName).take(800))
                            .put("temporary_history_record_deleted", seedDeleted)
                            .put("temporary_search_session_cleared", sessionCleanupVerified)
                            .put("unresolved_side_effect", false)

                    mainHandler.post {
                        if (
                            !isCommandCancelled(commandToken) &&
                            commandToken == activeCommandToken
                        ) {
                            respondAndResume(
                                text = "R10.20 Personal Search 2.0 завершился ошибкой.",
                                silent = silent,
                                success = false,
                                technical = evidence.toString()
                            )
                        }
                    }
                } finally {
                    if (
                        Thread.currentThread() ===
                        currentAgentThread
                    ) {
                        currentAgentThread = null
                    }
                }
            }

        currentAgentThread =
            worker

        executionKernel
            .bindThread(worker)

        worker.start()
    }

