    private fun runR10_18UniversalUiActionAcceptance(
        silent: Boolean
    ) {
        executionPhase(
            phase = "r10_18_universal_ui_action_engine_acceptance",
            executor = "universal_ui_action_engine_v1_1+screen_intelligence_v6_0"
        )

        stopSherpaListening()
        listenMode = ListenMode.BUSY

        broadcastStatus(
            "Проверяю Universal UI Action Engine…",
            STATE_EXECUTING
        )

        val commandToken = activeCommandToken
        val originalPage = currentAyanaPageKeyForAppIntegrationProbe()

        val worker =
            thread(
                start = false,
                name = "AyanaR10_18UniversalUiAction"
            ) {
                var restore = JSONObject().put("verified", false)

                try {
                    val localContractOk = universalUiActionEngine.selfTest()

                    /*
                     * R10.18.3 acceptance intentionally uses App Info -> Permissions.
                     *
                     * Why:
                     * - YouTube is already a device-confirmed installed app in the AYANA baseline;
                     * - agentOpenAppInfo() is setup only and verifies the external Settings owner;
                     * - the actual action under test is generic Universal UI click("Разрешения");
                     * - AgentAccessibilityService's native exact-text query was specifically
                     *   designed for sparse One UI App Info panes where serialized descendants
                     *   may omit rows such as Permissions;
                     * - this avoids testing a target from another Samsung Settings pane.
                     *
                     * No destructive state is changed: opening Permissions is navigation only.
                     */
                    val appInfoAction =
                        agentOpenAppInfo(
                            "YouTube"
                        )

                    val appInfoScreen =
                        if (
                            appInfoAction.optBoolean("success", false) &&
                            appInfoAction.optBoolean("verified", false)
                        ) {
                            try {
                                Thread.sleep(220L)
                            } catch (_: InterruptedException) {
                            }

                            screenIntelligence.getScreenState()
                        } else {
                            JSONObject()
                        }

                    val appInfoReady =
                        appInfoAction.optBoolean("success", false) &&
                            appInfoAction.optBoolean("verified", false) &&
                            appInfoScreen.optString("effective_foreground_package") == "com.android.settings" &&
                            appInfoScreen.optBoolean("foreground_truth_verified", false) &&
                            !appInfoScreen.optBoolean("foreground_truth_conflict", false) &&
                            !appInfoScreen.optBoolean("visual_grants_action_authority", true)

                    if (
                        !appInfoReady ||
                        isCommandCancelled(commandToken) ||
                        commandToken != activeCommandToken
                    ) {
                        restore =
                            restoreAyanaAfterAppIntegrationProbe(
                                pageKey = originalPage,
                                stepKey = "r10.18.3-app-info-preflight"
                            )

                        val evidence =
                            JSONObject()
                                .put("r10_18_acceptance", true)
                                .put("r10_18_3_app_info_target_reconciliation", true)
                                .put("acceptance_ok", false)
                                .put("stage", "app_info_foreground_truth")
                                .put("local_contract_self_test", localContractOk)
                                .put("app_info_ready", appInfoReady)
                                .put("app_info_target_app", "YouTube")
                                .put("app_info_screen", appInfoScreen)
                                .put("restore_verified", restore.optBoolean("verified", false))
                                .put("unresolved_side_effect", false)

                        mainHandler.post {
                            if (
                                commandToken == activeCommandToken &&
                                !cancelRequested &&
                                !shuttingDown
                            ) {
                                respondAndResume(
                                    text = "R10.18.3 остановлен: App Info foreground truth не подтверждён.",
                                    silent = silent,
                                    success = false,
                                    technical = evidence.toString()
                                )
                            }
                        }
                        return@thread
                    }

                    val requestedTarget = "пункт Разрешения"
                    val expectedTarget = "Разрешения"

                    val action =
                        universalUiActionEngine.click(
                            target = requestedTarget,
                            confirmed = false
                        )

                    val after =
                        action.optJSONObject("screen")
                            ?: screenIntelligence.getScreenState()

                    val targetMarkerVerified =
                        r10_18ScreenContainsText(
                            after,
                            expectedTarget
                        )

                    val authoritySource =
                        action.optString("action_authority_source")

                    val authorityMode =
                        action.optString("pre_dispatch_authority_mode")

                    val actionOk =
                        action.optBoolean("success", false) &&
                            action.optBoolean("verified", false) &&
                            action.optBoolean("pre_dispatch_verified", false) &&
                            action.optBoolean("postcondition_verified", false) &&
                            action.optInt("dispatch_count", 0) == 1 &&
                            action.optString("normalized_target") == expectedTarget &&
                            action.optString("role_hint") == "item" &&
                            authorityMode in
                                setOf(
                                    "live_accessibility_structure",
                                    "live_accessibility_exact_target_query"
                                ) &&
                            authoritySource.startsWith("live_accessibility_") &&
                            !action.optBoolean("blind_retry_allowed", true) &&
                            action.optBoolean("mutation_blind_retry_blocked", false) &&
                            !action.optBoolean("visual_grants_action_authority", true) &&
                            !action.optBoolean("screen_text_instruction_authority", true) &&
                            !action.optBoolean("unresolved_side_effect", true) &&
                            after.optString("effective_foreground_package") == "com.android.settings" &&
                            after.optBoolean("foreground_truth_verified", false) &&
                            targetMarkerVerified

                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state =
                            if (actionOk) {
                                "r10_18_universal_ui_action_verified"
                            } else {
                                "r10_18_universal_ui_action_failed"
                            },
                        message =
                            if (actionOk) {
                                "R10.18.3 подтвердил App Info -> Permissions через Universal UI Action Engine"
                            } else {
                                "R10.18.3 universal UI action не подтверждён"
                            },
                        details =
                            JSONObject()
                                .put("app_info_ready", appInfoReady)
                                .put("app_info_target_app", "YouTube")
                                .put("requested_target", requestedTarget)
                                .put("expected_target", expectedTarget)
                                .put("action", action)
                                .put("authority_mode", authorityMode)
                                .put("authority_source", authoritySource)
                                .put("target_marker_verified", targetMarkerVerified)
                                .toString()
                                .take(5200)
                    )

                    restore =
                        restoreAyanaAfterAppIntegrationProbe(
                            pageKey = originalPage,
                            stepKey = "r10.18.3-universal-ui-action"
                        )

                    val accepted =
                        localContractOk &&
                            appInfoReady &&
                            actionOk &&
                            restore.optBoolean("verified", false)

                    val evidence =
                        JSONObject()
                            .put("r10_18_acceptance", true)
                            .put("r10_18_3_app_info_target_reconciliation", true)
                            .put("acceptance_ok", accepted)
                            .put("universal_ui_action_engine_version", AyanaUniversalUiActionEngine.VERSION)
                            .put("universal_ui_action_contract_version", AyanaUniversalUiActionEngine.CONTRACT_VERSION)
                            .put("screen_intelligence_version", AyanaScreenIntelligence.VERSION)
                            .put("screen_understanding_version", AyanaScreenUnderstandingEngine.VERSION)
                            .put("local_contract_self_test", localContractOk)
                            .put("app_info_foreground_truth_verified", appInfoReady)
                            .put("app_info_target_app", "YouTube")
                            .put("action_verified", actionOk)
                            .put("requested_target", requestedTarget)
                            .put("normalized_target", action.optString("normalized_target"))
                            .put("role_hint", action.optString("role_hint"))
                            .put("pre_dispatch_authority_mode", authorityMode)
                            .put("action_authority_source", authoritySource)
                            .put("delegated_live_exact_target_resolution_supported", true)
                            .put("single_dispatch_verified", action.optInt("dispatch_count", 0) == 1)
                            .put("postcondition_verified", action.optBoolean("postcondition_verified", false))
                            .put("target_marker_verified", targetMarkerVerified)
                            .put("visual_grants_action_authority", false)
                            .put("screen_text_instruction_authority", false)
                            .put("mutation_blind_retry_blocked", action.optBoolean("mutation_blind_retry_blocked", false))
                            .put("safe_replan_without_side_effect_supported", true)
                            .put("unresolved_side_effect", action.optBoolean("unresolved_side_effect", false))
                            .put("restore_verified", restore.optBoolean("verified", false))
                            .put("orb_visual_implementation_changed", false)

                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state =
                            if (accepted) {
                                "r10_18_universal_ui_action_engine_verified"
                            } else {
                                "r10_18_universal_ui_action_engine_failed"
                            },
                        message =
                            if (accepted) {
                                "R10.18.3 подтвердил Universal UI Action Engine на реальном App Info target"
                            } else {
                                "R10.18.3 Universal UI Action Engine acceptance не подтверждён"
                            },
                        details = evidence.toString().take(5200)
                    )

                    mainHandler.post {
                        if (
                            commandToken == activeCommandToken &&
                            !cancelRequested &&
                            !shuttingDown
                        ) {
                            if (accepted) {
                                respondAndResume(
                                    text =
                                        "R10.18 подтверждён: AYANA открыла App Info YouTube, " +
                                            "универсально нашла и открыла «Разрешения», выполнила один UI dispatch, " +
                                            "перечитала экран и подтвердила переход; visual action authority отсутствует, " +
                                            "blind mutation retry запрещён.",
                                    silent = silent,
                                    success = true,
                                    technical = evidence.toString()
                                )
                            } else {
                                respondAndResume(
                                    text = "R10.18.3 не прошёл acceptance. См. technical evidence в History.",
                                    silent = silent,
                                    success = false,
                                    technical = evidence.toString()
                                )
                            }
                        }
                    }
                } catch (error: Throwable) {
                    try {
                        restore =
                            restoreAyanaAfterAppIntegrationProbe(
                                pageKey = originalPage,
                                stepKey = "r10.18.3-exception-restore"
                            )
                    } catch (_: Throwable) {
                    }

                    val evidence =
                        JSONObject()
                            .put("r10_18_acceptance", true)
                            .put("r10_18_3_app_info_target_reconciliation", true)
                            .put("acceptance_ok", false)
                            .put("reason", "r10_18_3_acceptance_exception")
                            .put("error", (error.message ?: error.javaClass.simpleName).take(600))
                            .put("restore_verified", restore.optBoolean("verified", false))
                            .put("unresolved_side_effect", false)

                    mainHandler.post {
                        if (
                            commandToken == activeCommandToken &&
                            !cancelRequested &&
                            !shuttingDown
                        ) {
                            respondAndResume(
                                text = "R10.18.3 Universal UI Action Engine завершился ошибкой.",
                                silent = silent,
                                success = false,
                                technical = evidence.toString()
                            )
                        }
                    }
                }
            }

        currentAgentThread = worker
        executionKernel.bindThread(worker)
        worker.start()
    }

    private fun r10_18ScreenContainsText(
        screen: JSONObject,
        target: String
    ): Boolean {
        val needle = target.trim().lowercase(Locale.ROOT).replace('ё', 'е')
        if (needle.isBlank()) return false

        val scalar =
            listOf(
                screen.optString("verification_text"),
                screen.optString("primary_window_title"),
                screen.optString("semantic_title")
            )

        if (
            scalar.any {
                it.lowercase(Locale.ROOT).replace('ё', 'е').contains(needle)
            }
        ) {
            return true
        }

        for (key in listOf("visible_text", "all_visible_text", "semantic_primary_text")) {
            val values = screen.optJSONArray(key) ?: continue
            for (index in 0 until values.length()) {
                if (
                    values
                        .optString(index)
                        .lowercase(Locale.ROOT)
                        .replace('ё', 'е')
                        .contains(needle)
                ) {
                    return true
                }
            }
        }

        return false
    }

    private fun isR10_17ScreenIntelligenceAcceptanceCommand(
        command: String
    ): Boolean {
        val normalized =
            command
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()
                .removePrefix("аяна ")
                .trim()
                // R10.17.1: the shared ASR/text normalizer removes dots before routing.
                // Canonicalize only the known version tokens here so exact acceptance
                // phrases cannot fall through to Agent Core.
                .replace(Regex("\\b2\\s+0\\b"), "2.0")
                .replace(Regex("\\br10\\s+17\\b"), "r10.17")

        return normalized in
            setOf(
                "проверь screen intelligence 2.0",
                "проверь screen intelligence",
                "проверь понимание экрана 2.0",
                "проверь улучшенное понимание экрана",
                "проверь r10.17"
            )
    }

    private fun runR10_17ScreenIntelligenceAcceptance(
        silent: Boolean
    ) {
        executionPhase(
            phase = "r10_17_screen_intelligence_2_0_acceptance",
            executor = "screen_intelligence_v6_0+screen_understanding_v2_0+verified_semantic_observation_v2"
        )

        stopSherpaListening()
        listenMode = ListenMode.BUSY

        broadcastStatus(
            "Проверяю Screen Intelligence 2.0…",
            STATE_EXECUTING
        )

        val commandToken = activeCommandToken
        val originalPage = currentAyanaPageKeyForAppIntegrationProbe()

        val worker =
            thread(
                start = false,
                name = "AyanaR10_17ScreenIntelligence"
            ) {
                var settingsRestore = JSONObject().put("verified", false)
                var browserRestore = JSONObject().put("verified", false)

                try {
                    val localContractOk =
                        screenIntelligence.selfTestUnifiedTruth()

                    if (
                        isCommandCancelled(commandToken) ||
                        commandToken != activeCommandToken
                    ) {
                        return@thread
                    }

                    val settingsAction =
                        agentOpenSettings("apps")

                    val settingsScreen =
                        if (
                            settingsAction.optBoolean("success", false) &&
                            settingsAction.optBoolean("verified", false)
                        ) {
                            try {
                                Thread.sleep(120L)
                            } catch (_: InterruptedException) {
                            }
                            screenIntelligence.getScreenState()
                        } else {
                            JSONObject()
                        }

                    val settingsPackage =
                        settingsScreen
                            .optString("effective_foreground_package")
                            .trim()

                    val settingsUnderstandingStatus =
                        settingsScreen.optString("screen_understanding_status")

                    val settingsOk =
                        settingsAction.optBoolean("success", false) &&
                            settingsAction.optBoolean("verified", false) &&
                            settingsPackage == "com.android.settings" &&
                            settingsScreen.optBoolean("foreground_truth_verified", false) &&
                            settingsScreen.optString("screen_understanding_version") ==
                                AyanaScreenUnderstandingEngine.VERSION &&
                            settingsUnderstandingStatus in
                                setOf(
                                    AyanaScreenUnderstandingEngine.STATUS_VERIFIED_FULL,
                                    AyanaScreenUnderstandingEngine.STATUS_VERIFIED_SUFFICIENT
                                ) &&
                            settingsScreen.optBoolean("read_only_understanding_usable", false) &&
                            !settingsScreen.optBoolean("visual_grants_action_authority", true)

                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state =
                            if (settingsOk) {
                                "r10_17_settings_understanding_verified"
                            } else {
                                "r10_17_settings_understanding_failed"
                            },
                        message =
                            if (settingsOk) {
                                "R10.17 подтвердил Screen Understanding на Samsung Settings"
                            } else {
                                "R10.17 не подтвердил Screen Understanding на Samsung Settings"
                            },
                        details =
                            JSONObject()
                                .put("action", settingsAction)
                                .put("package", settingsPackage)
                                .put("coverage", settingsScreen.optString("accessibility_coverage_status"))
                                .put("understanding_status", settingsUnderstandingStatus)
                                .put("confidence", settingsScreen.optInt("screen_understanding_confidence", -1))
                                .put("read_only_usable", settingsScreen.optBoolean("read_only_understanding_usable", false))
                                .put("interaction_usable", settingsScreen.optBoolean("interaction_understanding_usable", false))
                                .put("text_count", settingsScreen.optInt("understanding_text_count", -1))
                                .toString()
                                .take(3600)
                    )

                    settingsRestore =
                        restoreAyanaAfterAppIntegrationProbe(
                            pageKey = originalPage,
                            stepKey = "r10.17-settings-understanding"
                        )

                    if (
                        !settingsOk ||
                        !settingsRestore.optBoolean("verified", false) ||
                        isCommandCancelled(commandToken) ||
                        commandToken != activeCommandToken
                    ) {
                        val evidence =
                            JSONObject()
                                .put("r10_17_acceptance", true)
                                .put("acceptance_ok", false)
                                .put("stage", "settings_understanding")
                                .put("settings_verified", settingsOk)
                                .put("settings_restore_verified", settingsRestore.optBoolean("verified", false))
                                .put("local_contract_self_test", localContractOk)
                                .put("settings_screen", settingsScreen)
                                .put("unresolved_side_effect", false)

                        mainHandler.post {
                            if (
                                commandToken == activeCommandToken &&
                                !cancelRequested &&
                                !shuttingDown
                            ) {
                                respondAndResume(
                                    text = "R10.17 остановлен: понимание Samsung Settings не подтверждено.",
                                    silent = silent,
                                    success = false,
                                    technical = evidence.toString()
                                )
                            }
                        }
                        return@thread
                    }

                    val browserAction =
                        executeAppIntegrationAction(
                            appKey = AyanaAppIntegrationRegistry.APP_BROWSER,
                            actionKey = AyanaAppIntegrationRegistry.ACTION_OPEN_URL,
                            payload = R9_7_STRUCTURED_ACCEPTANCE_URL
                        )

                    val browserPackage =
                        browserAction
                            .optString("observed_package")
                            .trim()
                            .ifBlank {
                                browserAction.optString("target_package").trim()
                            }

                    val visual =
                        if (
                            browserAction.optBoolean("success", false) &&
                            browserAction.optBoolean("verified", false) &&
                            browserPackage.isNotBlank()
                        ) {
                            attemptVerifiedStructuredSemanticScreenRead(
                                expectedPackage = browserPackage,
                                commandToken = commandToken
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                                .put("reason", "browser_open_not_verified")
                        }

                    val browserScreen =
                        if (
                            visual.optBoolean("verified", false) &&
                            !isCommandCancelled(commandToken) &&
                            commandToken == activeCommandToken
                        ) {
                            screenIntelligence.getScreenState()
                        } else {
                            JSONObject()
                        }

                    val browserUnderstandingStatus =
                        browserScreen.optString("screen_understanding_status")

                    val browserFusionOk =
                        visual.optBoolean("success", false) &&
                            visual.optBoolean("verified", false) &&
                            visual.optBoolean("semantic_structured_read_verified", false) &&
                            visual.optString("semantic_title").trim().equals(
                                R9_7_STRUCTURED_ACCEPTANCE_TITLE,
                                ignoreCase = true
                            ) &&
                            browserScreen.optString("effective_foreground_package").trim() == browserPackage &&
                            browserScreen.optBoolean("foreground_truth_verified", false) &&
                            browserScreen.optString("screen_understanding_version") ==
                                AyanaScreenUnderstandingEngine.VERSION &&
                            browserUnderstandingStatus in
                                setOf(
                                    AyanaScreenUnderstandingEngine.STATUS_VERIFIED_FULL,
                                    AyanaScreenUnderstandingEngine.STATUS_VERIFIED_SUFFICIENT
                                ) &&
                            browserScreen.optBoolean("read_only_understanding_usable", false) &&
                            browserScreen.optBoolean("visual_observation_used", false) &&
                            browserScreen.optBoolean("visual_read_only_corroboration_used", false) &&
                            browserScreen.optBoolean("semantic_structured_read_verified", false) &&
                            !browserScreen.optBoolean("visual_grants_action_authority", true) &&
                            !browserScreen.optBoolean("screen_text_instruction_authority", true)

                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state =
                            if (browserFusionOk) {
                                "r10_17_visual_fusion_verified"
                            } else {
                                "r10_17_visual_fusion_failed"
                            },
                        message =
                            if (browserFusionOk) {
                                "R10.17 подтвердил Accessibility + visual read-only fusion"
                            } else {
                                "R10.17 не подтвердил visual read-only fusion"
                            },
                        details =
                            JSONObject()
                                .put("browser_action", browserAction)
                                .put("browser_package", browserPackage)
                                .put("visual_verified", visual.optBoolean("verified", false))
                                .put("visual_title", visual.optString("semantic_title"))
                                .put("coverage", browserScreen.optString("accessibility_coverage_status"))
                                .put("understanding_status", browserUnderstandingStatus)
                                .put("confidence", browserScreen.optInt("screen_understanding_confidence", -1))
                                .put("visual_used", browserScreen.optBoolean("visual_observation_used", false))
                                .put("visual_read_only", browserScreen.optBoolean("visual_read_only_corroboration_used", false))
                                .put("visual_action_authority", browserScreen.optBoolean("visual_grants_action_authority", true))
                                .toString()
                                .take(4200)
                    )

                    browserRestore =
                        restoreAyanaAfterAppIntegrationProbe(
                            pageKey = originalPage,
                            stepKey = "r10.17-browser-fusion"
                        )

                    val accepted =
                        localContractOk &&
                            settingsOk &&
                            settingsRestore.optBoolean("verified", false) &&
                            browserFusionOk &&
                            browserRestore.optBoolean("verified", false)

                    val evidence =
                        JSONObject()
                            .put("r10_17_acceptance", true)
                            .put("acceptance_ok", accepted)
                            .put("screen_intelligence_version", AyanaScreenIntelligence.VERSION)
                            .put("unified_screen_truth_version", AyanaScreenIntelligence.UNIFIED_TRUTH_VERSION)
                            .put("screen_understanding_version", AyanaScreenUnderstandingEngine.VERSION)
                            .put("local_contract_self_test", localContractOk)
                            .put("settings_verified", settingsOk)
                            .put("settings_package", settingsPackage)
                            .put("settings_accessibility_coverage", settingsScreen.optString("accessibility_coverage_status"))
                            .put("settings_understanding_status", settingsUnderstandingStatus)
                            .put("settings_understanding_confidence", settingsScreen.optInt("screen_understanding_confidence", -1))
                            .put("settings_read_only_usable", settingsScreen.optBoolean("read_only_understanding_usable", false))
                            .put("settings_interaction_usable", settingsScreen.optBoolean("interaction_understanding_usable", false))
                            .put("settings_restore_verified", settingsRestore.optBoolean("verified", false))
                            .put("browser_verified", browserFusionOk)
                            .put("browser_package", browserPackage)
                            .put("browser_accessibility_coverage", browserScreen.optString("accessibility_coverage_status"))
                            .put("browser_understanding_status", browserUnderstandingStatus)
                            .put("browser_understanding_confidence", browserScreen.optInt("screen_understanding_confidence", -1))
                            .put("visual_observation_used", browserScreen.optBoolean("visual_observation_used", false))
                            .put("visual_read_only_corroboration_used", browserScreen.optBoolean("visual_read_only_corroboration_used", false))
                            .put("visual_grants_action_authority", false)
                            .put("screen_text_instruction_authority", false)
                            .put("browser_restore_verified", browserRestore.optBoolean("verified", false))
                            .put("unresolved_side_effect", false)
                            .put("orb_visual_implementation_changed", false)

                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state =
                            if (accepted) {
                                "r10_17_screen_intelligence_2_0_verified"
                            } else {
                                "r10_17_screen_intelligence_2_0_failed"
                            },
                        message =
                            if (accepted) {
                                "R10.17 подтвердил Screen Intelligence 2.0 на Settings + Browser visual fusion"
                            } else {
                                "R10.17 Screen Intelligence 2.0 acceptance не подтверждён"
                            },
                        details = evidence.toString().take(5200)
                    )

                    mainHandler.post {
                        if (
                            commandToken == activeCommandToken &&
                            !cancelRequested &&
                            !shuttingDown
                        ) {
                            if (accepted) {
                                respondAndResume(
                                    text =
                                        "R10.17 подтверждён: Screen Intelligence 2.0 отделяет raw coverage от понимания, " +
                                            "Samsung Settings читается по verified understanding contract, Browser visual evidence " +
                                            "усиливает только read-only понимание и не получает action authority.",
                                    silent = silent,
                                    success = true,
                                    technical = evidence.toString()
                                )
                            } else {
                                respondAndResume(
                                    text = "R10.17 не прошёл acceptance. См. technical evidence в History.",
                                    silent = silent,
                                    success = false,
                                    technical = evidence.toString()
                                )
                            }
                        }
                    }
                } catch (error: Throwable) {
                    try {
                        restoreAyanaAfterAppIntegrationProbe(
                            pageKey = originalPage,
                            stepKey = "r10.17-exception-restore"
                        )
                    } catch (_: Throwable) {
                    }

                    val evidence =
                        JSONObject()
                            .put("r10_17_acceptance", true)
                            .put("acceptance_ok", false)
                            .put("reason", "r10_17_acceptance_exception")
                            .put("error", (error.message ?: error.javaClass.simpleName).take(600))
                            .put("unresolved_side_effect", false)

                    mainHandler.post {
                        if (
                            commandToken == activeCommandToken &&
                            !cancelRequested &&
                            !shuttingDown
                        ) {
                            respondAndResume(
                                text = "R10.17 Screen Intelligence 2.0 завершился ошибкой.",
                                silent = silent,
                                success = false,
                                technical = evidence.toString()
                            )
                        }
                    }
                }
            }

        currentAgentThread = worker
        executionKernel.bindThread(worker)
        worker.start()
    }

