    private fun runR10_16PerceptionProcessRecoveryAcceptance(
        silent: Boolean
    ) {
        executionPhase(
            phase = "r10_16_1_perception_restart_telemetry_acceptance",
            executor = "perception_recovery_v1_0+perception_bridge_v1_3_1"
        )

        val commandToken = activeCommandToken

        stopSherpaListening()
        listenMode = ListenMode.BUSY

        broadcastStatus(
            "Проверяю восстановление процесса восприятия…",
            STATE_EXECUTING
        )

        val worker =
            thread(
                start = false,
                name = "AyanaR10_16PerceptionRecovery"
            ) {
                val mainPid = android.os.Process.myPid()

                try {
                    val preflight =
                        perceptionBridge.awaitReady(
                            timeoutMs = 3_000L
                        )

                    val policy =
                        perceptionBridge.recoveryPolicySelfTest()

                    val preflightOk =
                        preflight.optBoolean("perception_rebind_ready", false) &&
                            preflight.optBoolean("perception_route_verified", false) &&
                            preflight.optBoolean("provider_process_separated", false) &&
                            preflight.optBoolean("bridge_version_match", false) &&
                            preflight.optBoolean("provider_epoch_verified", false) &&
                            preflight.optBoolean("accessibility_connected", false) &&
                            preflight.optBoolean("route_contract_verified", false) &&
                            preflight.optInt("perception_process_id", -1) > 0 &&
                            preflight.optInt("perception_process_id", -1) != mainPid

                    val policyOk =
                        policy.optBoolean("verified", false) &&
                            policy.optBoolean("read_only_rebind_retry_supported", false) &&
                            policy.optBoolean("mutation_blind_retry_blocked", false) &&
                            policy.optBoolean("destructive_blind_retry_blocked", false) &&
                            !policy.optBoolean("mutation_blind_retry_allowed", true)

                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state = "r10_16_perception_recovery_preflight",
                        message =
                            if (preflightOk && policyOk) {
                                "R10.16 preflight подтверждён; :perception готов к controlled kill/rebind"
                            } else {
                                "R10.16 preflight не подтверждён"
                            },
                        details =
                            JSONObject()
                                .put("preflight", preflight)
                                .put("policy", policy)
                                .toString()
                                .take(4200)
                    )

                    if (!preflightOk || !policyOk) {
                        val evidence =
                            JSONObject()
                                .put("r10_16_acceptance", true)
                                .put("acceptance_ok", false)
                                .put("preflight_verified", preflightOk)
                                .put("recovery_policy_verified", policyOk)
                                .put("main_process_id", mainPid)
                                .put("preflight", preflight)
                                .put("recovery_policy", policy)
                                .put("reason", "r10_16_preflight_failed")

                        mainHandler.post {
                            if (
                                commandToken == activeCommandToken &&
                                !cancelRequested &&
                                !shuttingDown
                            ) {
                                respondAndResume(
                                    text = "R10.16 остановлен до kill: perception recovery preflight не подтверждён.",
                                    silent = silent,
                                    success = false,
                                    technical = evidence.toString()
                                )
                            }
                        }
                        return@thread
                    }

                    if (
                        isCommandCancelled(commandToken) ||
                        commandToken != activeCommandToken ||
                        Thread.currentThread().isInterrupted ||
                        shuttingDown
                    ) {
                        return@thread
                    }

                    val recovery =
                        perceptionProcessRecoveryCoordinator
                            .forceDeathAndAwaitRecovery(
                                timeoutMs = 12_000L
                            )

                    val postScreen =
                        if (recovery.optBoolean("verified", false)) {
                            try {
                                screenIntelligence.getScreenState()
                            } catch (error: Throwable) {
                                JSONObject()
                                    .put("success", false)
                                    .put("verified", false)
                                    .put("reason", "post_recovery_screen_exception")
                                    .put("error", error.message ?: error.javaClass.simpleName)
                            }
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                                .put("reason", "recovery_not_verified")
                        }

                    val originPid =
                        recovery.optInt("origin_perception_process_id", -1)
                    val restoredPid =
                        recovery.optInt("restored_perception_process_id", -1)
                    val originEpoch =
                        recovery.optString("origin_perception_process_epoch_id")
                    val restoredEpoch =
                        recovery.optString("restored_perception_process_epoch_id")

                    val mainProcessSurvived =
                        android.os.Process.myPid() == mainPid

                    val postScreenVerified =
                        postScreen.optBoolean("success", false) &&
                            postScreen.optBoolean("perception_route_verified", false) &&
                            postScreen.optBoolean("provider_process_separated", false) &&
                            postScreen.optBoolean("bridge_version_match", false) &&
                            postScreen.optBoolean("provider_epoch_verified", false) &&
                            postScreen.optInt("perception_process_id", -1) == restoredPid &&
                            postScreen.optString("perception_process_epoch_id") == restoredEpoch

                    val restoredTelemetry =
                        recovery.optJSONObject("restored") ?: JSONObject()

                    val restartTelemetryVerified =
                        restoredTelemetry.optBoolean("restart_telemetry_reconciled", false) &&
                            restoredTelemetry.optBoolean("perception_process_restarted", false) &&
                            restoredTelemetry.optInt("previous_perception_process_id", -1) == originPid &&
                            restoredTelemetry.optString("previous_perception_process_epoch_id") == originEpoch &&
                            restoredTelemetry.optInt("perception_process_id", -1) == restoredPid &&
                            restoredTelemetry.optString("perception_process_epoch_id") == restoredEpoch &&
                            restoredTelemetry.optLong("perception_bridge_generation", 0L) >
                                recovery.optLong("origin_bridge_generation", 0L)

                    val accepted =
                        recovery.optBoolean("success", false) &&
                            recovery.optBoolean("verified", false) &&
                            recovery.optBoolean("process_identity_changed", false) &&
                            recovery.optBoolean("process_epoch_changed", false) &&
                            recovery.optBoolean("accessibility_reconnected", false) &&
                            recovery.optBoolean("route_contract_verified", false) &&
                            mainProcessSurvived &&
                            originPid > 0 &&
                            restoredPid > 0 &&
                            originPid != restoredPid &&
                            originEpoch.isNotBlank() &&
                            restoredEpoch.isNotBlank() &&
                            originEpoch != restoredEpoch &&
                            postScreenVerified &&
                            restartTelemetryVerified &&
                            policyOk

                    val evidence =
                        JSONObject()
                            .put("r10_16_acceptance", true)
                            .put("acceptance_ok", accepted)
                            .put("perception_recovery_version", AyanaPerceptionProcessRecoveryCoordinator.VERSION)
                            .put("perception_bridge_version", AyanaPerceptionBridgeContract.VERSION)
                            .put("main_process_id", mainPid)
                            .put("main_process_survived", mainProcessSurvived)
                            .put("origin_perception_process_id", originPid)
                            .put("restored_perception_process_id", restoredPid)
                            .put("origin_perception_process_epoch_id", originEpoch)
                            .put("restored_perception_process_epoch_id", restoredEpoch)
                            .put("process_identity_changed", recovery.optBoolean("process_identity_changed", false))
                            .put("process_epoch_changed", recovery.optBoolean("process_epoch_changed", false))
                            .put("bridge_generation_advanced", recovery.optBoolean("bridge_generation_advanced", false))
                            .put("accessibility_reconnected", recovery.optBoolean("accessibility_reconnected", false))
                            .put("route_contract_verified", recovery.optBoolean("route_contract_verified", false))
                            .put("post_recovery_screen_verified", postScreenVerified)
                            .put("post_recovery_screen_package", postScreen.optString("effective_foreground_package"))
                            .put("restart_telemetry_verified", restartTelemetryVerified)
                            .put("restored_perception_process_restarted", restoredTelemetry.optBoolean("perception_process_restarted", false))
                            .put("telemetry_previous_perception_process_id", restoredTelemetry.optInt("previous_perception_process_id", -1))
                            .put("telemetry_previous_perception_process_epoch_id", restoredTelemetry.optString("previous_perception_process_epoch_id"))
                            .put("restart_telemetry_version", restoredTelemetry.optString("restart_telemetry_version"))
                            .put("read_only_rebind_retry_supported", policy.optBoolean("read_only_rebind_retry_supported", false))
                            .put("mutation_blind_retry_blocked", policy.optBoolean("mutation_blind_retry_blocked", false))
                            .put("destructive_blind_retry_blocked", policy.optBoolean("destructive_blind_retry_blocked", false))
                            .put("unresolved_side_effect", false)
                            .put("orb_visual_implementation_changed", false)
                            .put("recovery", recovery)

                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state =
                            if (accepted) {
                                "r10_16_1_restart_telemetry_verified"
                            } else {
                                "r10_16_1_restart_telemetry_failed"
                            },
                        message =
                            if (accepted) {
                                "R10.16.1 подтвердил restart :perception + согласованную restart telemetry"
                            } else {
                                "R10.16.1 restart telemetry reconciliation не подтверждён"
                            },
                        details = evidence.toString().take(5200)
                    )

                    mainHandler.post {
                        if (
                            commandToken == activeCommandToken &&
                            !cancelRequested &&
                            !shuttingDown
                        ) {
                            if (accepted) {
                                respondAndResume(
                                    text =
                                        "R10.16.1 подтверждён: :perception перезапущен, PID/epoch/generation изменились, " +
                                            "restart telemetry согласована и сохраняет предыдущую identity; " +
                                            "fresh screen read подтверждён, blind mutation replay запрещён.",
                                    silent = silent,
                                    success = true,
                                    technical = evidence.toString()
                                )
                            } else {
                                respondAndResume(
                                    text = "R10.16.1 не прошёл telemetry acceptance. См. technical evidence в History.",
                                    silent = silent,
                                    success = false,
                                    technical = evidence.toString()
                                )
                            }
                        }
                    }
                } catch (error: Throwable) {
                    val evidence =
                        JSONObject()
                            .put("r10_16_acceptance", true)
                            .put("acceptance_ok", false)
                            .put("main_process_id", mainPid)
                            .put("main_process_survived", android.os.Process.myPid() == mainPid)
                            .put("reason", "r10_16_acceptance_exception")
                            .put("error", (error.message ?: error.javaClass.simpleName).take(500))
                            .put("unresolved_side_effect", false)

                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state = "r10_16_perception_process_recovery_failed",
                        message = "R10.16 acceptance exception",
                        details = evidence.toString()
                    )

                    mainHandler.post {
                        if (
                            commandToken == activeCommandToken &&
                            !cancelRequested &&
                            !shuttingDown
                        ) {
                            respondAndResume(
                                text = "R10.16 perception process recovery завершился ошибкой.",
                                silent = silent,
                                success = false,
                                technical = evidence.toString()
                            )
                        }
                    }
                } finally {
                    if (Thread.currentThread() === currentAgentThread) {
                        currentAgentThread = null
                    }
                }
            }

        currentAgentThread = worker
        executionKernel.bindThread(worker)
        worker.start()
    }

    private fun isR10_14PerceptionProcessIsolationAcceptanceCommand(
        command: String
    ): Boolean {
        val normalized =
            command
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()
                .removePrefix("аяна ")
                .trim()

        return normalized in
            setOf(
                "проверь изоляцию восприятия после смерти процесса",
                "проверь восприятие после смерти процесса",
                "проверь cross-process accessibility",
                "проверь perception process isolation",
                "проверь r10.14"
            )
    }

    private fun runR10_14PerceptionProcessIsolationAcceptance(
        silent: Boolean
    ) {
        val objective =
            "сначала проверь состояние устройства, открой AYANA AI, затем открой Example Domain в браузере, прочитай заголовок страницы, найди этот заголовок в YouTube и в конце снова проверь состояние устройства"

        if (!AyanaLifecycleRecoveryCoordinator().selfTest()) {
            respondAndResume(
                text = "R10.14 остановлен: lifecycle recovery self-test не подтверждён.",
                silent = silent,
                success = false,
                technical =
                    JSONObject()
                        .put("r10_14_acceptance", true)
                        .put("acceptance_ok", false)
                        .put("lifecycle_recovery_self_test", false)
                        .toString()
            )
            return
        }

        val bridgeStatus =
            try {
                perceptionBridge.status()
            } catch (error: Throwable) {
                JSONObject()
                    .put("success", false)
                    .put("error", error.message ?: error.javaClass.simpleName)
            }

        val perceptionPid =
            bridgeStatus.optInt("perception_process_id", -1)
        val perceptionEpoch =
            bridgeStatus.optString("perception_process_epoch_id")
        val bridgePreflightOk =
            bridgeStatus.optBoolean("success", false) &&
                bridgeStatus.optBoolean("accessibility_connected", false) &&
                bridgeStatus.optBoolean("screen_evidence_available", false) &&
                perceptionPid > 0 &&
                perceptionPid != android.os.Process.myPid() &&
                perceptionEpoch.isNotBlank()

        if (!bridgePreflightOk) {
            respondAndResume(
                text = "R10.14 остановлен: отдельный perception process/Accessibility bridge не подтверждён.",
                silent = silent,
                success = false,
                technical =
                    JSONObject()
                        .put("r10_14_acceptance", true)
                        .put("acceptance_ok", false)
                        .put("perception_bridge_version", AyanaPerceptionBridgeContract.VERSION)
                        .put("main_process_id", android.os.Process.myPid())
                        .put("bridge_status", bridgeStatus)
                        .toString()
            )
            return
        }

        val proposal =
            try {
                AyanaDynamicGoalPlanner.localProposal(objective)
            } catch (error: Throwable) {
                respondAndResume(
                    text = "R10.14 остановлен: production plan не сформирован.",
                    silent = silent,
                    success = false,
                    technical =
                        JSONObject()
                            .put("r10_14_acceptance", true)
                            .put("acceptance_ok", false)
                            .put("reason", error.message ?: error.javaClass.simpleName)
                            .toString()
                )
                return
            }

        val planner =
            try {
                AyanaDynamicGoalPlanner.compile(
                    objective = objective,
                    proposal = proposal
                )
            } catch (error: Throwable) {
                respondAndResume(
                    text = "R10.14 остановлен: production plan не прошёл contract validation.",
                    silent = silent,
                    success = false,
                    technical =
                        JSONObject()
                            .put("r10_14_acceptance", true)
                            .put("acceptance_ok", false)
                            .put("reason", error.message ?: error.javaClass.simpleName)
                            .toString()
                )
                return
            }

        if (planner.subgoalCount() != 6) {
            respondAndResume(
                text = "R10.14 остановлен: неожиданный production DAG.",
                silent = silent,
                success = false,
                technical =
                    JSONObject()
                        .put("r10_14_acceptance", true)
                        .put("acceptance_ok", false)
                        .put("subgoal_count", planner.subgoalCount())
                        .toString()
            )
            return
        }

        val runtimeContext =
            JSONObject()
                .put("r10_14_acceptance", true)
                .put("r10_14_process_death_requested", false)
                .put("r10_14_pre_death_checkpoint_persisted", false)
                .put("r10_14_user_stop_requested", false)
                .put("r10_14_origin_service_instance_id", serviceInstanceId)
                .put("r10_14_origin_process_id", android.os.Process.myPid())
                .put("r10_14_origin_process_epoch_id", processEpochId)
                .put("r10_14_origin_perception_process_id", perceptionPid)
                .put("r10_14_origin_perception_process_epoch_id", perceptionEpoch)
                .put("r10_14_bridge_preflight_verified", true)
                .put("r10_14_external_ui_continuation_proven", false)

        startR10_10ProductionDynamicPlannerWorker(
            command = objective,
            silent = silent,
            planner = planner,
            resumeGoal = null,
            automaticRecovery = false,
            initialRuntimeContext = runtimeContext
        )
    }

    private fun scheduleR10_13ProcessDeath() {
        val appContext = applicationContext

        thread(
            start = true,
            name = "AyanaR10_13ProcessDeath"
        ) {
            try {
                val restartIntent =
                    Intent(
                        appContext,
                        AyanaVoiceService::class.java
                    ).apply {
                        action = ACTION_START
                    }

                val restartPendingIntent =
                    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                        PendingIntent.getForegroundService(
                            appContext,
                            101013,
                            restartIntent,
                            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
                        )
                    } else {
                        PendingIntent.getService(
                            appContext,
                            101013,
                            restartIntent,
                            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
                        )
                    }

                val alarmManager =
                    appContext.getSystemService(Context.ALARM_SERVICE) as AlarmManager

                val triggerAt =
                    SystemClock.elapsedRealtime() + 1_500L

                if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {
                    alarmManager.setAndAllowWhileIdle(
                        AlarmManager.ELAPSED_REALTIME_WAKEUP,
                        triggerAt,
                        restartPendingIntent
                    )
                } else {
                    alarmManager.set(
                        AlarmManager.ELAPSED_REALTIME_WAKEUP,
                        triggerAt,
                        restartPendingIntent
                    )
                }

                Thread.sleep(300L)

                // Deliberately kill the entire AYANA app process. No Service stop/shutdown
                // path is used, so user-stop semantics cannot be confused with recovery.
                android.os.Process.killProcess(android.os.Process.myPid())
            } catch (_: Throwable) {
                // The persisted goal remains safe/recoverable. If process termination itself
                // fails, R10.13's PID + process-epoch gates will fail closed on any resume.
            }
        }
    }

