    private fun r10_9VerifiedSuffixRevisionProposal(
        planner: AyanaDynamicGoalPlanner
    ): JSONObject {
        val snapshot = planner.snapshot()
        val source = snapshot.optJSONArray("subgoals") ?: JSONArray()
        val revised = JSONArray()

        for (index in 0 until source.length()) {
            val item = source.optJSONObject(index) ?: continue
            val id = item.optString("id")

            if (id == "youtube_search") {
                val contract =
                    AyanaDynamicGoalPlanner.executorRegistry()[
                        AyanaDynamicGoalPlanner.EXEC_PARTIAL_RESULT_CHECK
                    ] ?: throw IllegalStateException("R10.9 partial-result executor missing")

                revised.put(
                    JSONObject()
                        .put("id", "confirm_title")
                        .put("title", "Verify restored page-title provenance before consumer")
                        .put("executor", AyanaDynamicGoalPlanner.EXEC_PARTIAL_RESULT_CHECK)
                        .put("lane", contract.lane)
                        .put("authority", contract.authority)
                        .put("dependencies", JSONArray(listOf("read_title")))
                        .put("result_key", "")
                        .put("required", true)
                        .put(
                            "arguments",
                            JSONObject().put("input_result_key", "page_title")
                        )
                )

                val youtube = JSONObject(item.toString())
                youtube.put(
                    "dependencies",
                    JSONArray(listOf("read_title", "confirm_title"))
                )
                revised.put(youtube)
            } else {
                revised.put(JSONObject(item.toString()))
            }
        }

        return JSONObject()
            .put("supported", true)
            .put("source", "verified_suffix_revision")
            .put("objective", planner.objective())
            .put("subgoals", revised)
    }

    private fun r10_9VerifiedPrefixMutationProposal(
        planner: AyanaDynamicGoalPlanner
    ): JSONObject {
        val proposal = r10_9VerifiedSuffixRevisionProposal(planner)
        val items = proposal.optJSONArray("subgoals") ?: JSONArray()
        for (index in 0 until items.length()) {
            val item = items.optJSONObject(index) ?: continue
            if (item.optString("id") == "read_title") {
                // Still a structurally valid planner DAG, but it changes an already
                // VERIFIED execution dependency and must therefore be rejected by
                // LongObjectiveCoordinator v1.1 verified-prefix immutability.
                item.put(
                    "dependencies",
                    JSONArray(listOf("open_ayana"))
                )
                break
            }
        }
        proposal.put("source", "verified_prefix_mutation_probe")
        return proposal
    }

    private fun runR10_9DynamicGoalDecompositionAcceptance(
        silent: Boolean
    ) {
        executionPhase(
            phase = "r10_9_dynamic_goal_decomposition_acceptance",
            executor = "dynamic_goal_planner_v1"
        )

        stopSherpaListening()
        listenMode = ListenMode.BUSY

        broadcastStatus(
            "Проверяю динамическую декомпозицию цели…",
            STATE_EXECUTING
        )

        updateNotification(
            "AYANA проверяет R10.9 dynamic goal decomposition…"
        )

        val commandToken = activeCommandToken
        val originalPage = currentAyanaPageKeyForAppIntegrationProbe()

        val worker =
            thread(
                start = false,
                name = "AyanaR10_9DynamicGoalPlanner"
            ) {
                val testFileName =
                    "ayana_durable_goals_r10_9_acceptance.json"

                var acceptanceStore: AyanaDurableGoalStore? = null
                var acceptanceGoalId: String? = null
                var finalRestore: JSONObject? = null

                try {
                    val longObjectiveSelfTest =
                        try {
                            AyanaLongObjectiveCoordinator.selfTest()
                        } catch (_: Exception) {
                            false
                        }

                    val recoverySelfTest =
                        try {
                            AyanaCrossLaneRecoveryContinuity.selfTest()
                        } catch (_: Exception) {
                            false
                        }

                    val continuitySelfTest =
                        try {
                            AyanaCrossLaneAdaptiveContinuity.selfTest()
                        } catch (_: Exception) {
                            false
                        }

                    val adaptiveSelfTest =
                        try {
                            AyanaAdaptiveExecutionLoop.selfTest()
                        } catch (_: Exception) {
                            false
                        }

                    val longRecoverySelfTest =
                        try {
                            longTaskRecoveryCoordinator.selfTest()
                        } catch (_: Exception) {
                            false
                        }

                    val isolatedStore =
                        AyanaDurableGoalStore(
                            context = applicationContext,
                            storageFileName = testFileName
                        )

                    isolatedStore.clearAcceptanceStorage()
                    acceptanceStore = isolatedStore

                    val objective =
                        "Сначала проверь состояние устройства, открой AYANA AI, затем открой Example Domain в браузере, прочитай заголовок страницы, найди этот заголовок в YouTube и в конце снова проверь состояние устройства."

                    val plannerSelfTest =
                        try {
                            AyanaDynamicGoalPlanner.selfTest()
                        } catch (_: Exception) {
                            false
                        }

                    val initialPlannerProposal =
                        AyanaDynamicGoalPlanner.localProposal(objective)

                    var dynamicPlanner =
                        AyanaDynamicGoalPlanner.compile(
                            objective = objective,
                            proposal = initialPlannerProposal
                        )

                    val initialPlanSubgoalCount = dynamicPlanner.subgoalCount()
                    val initialPlanFingerprint = dynamicPlanner.planFingerprint()
                    val freeFormDecompositionVerified =
                        initialPlannerProposal.optBoolean("supported", false) &&
                            initialPlanSubgoalCount == 6

                    val initialExecutorBindingVerified =
                        dynamicPlanner.executorFor("device_state") ==
                            AyanaDynamicGoalPlanner.EXEC_DEVICE_STATE &&
                            dynamicPlanner.executorFor("open_ayana") ==
                            AyanaDynamicGoalPlanner.EXEC_ANDROID_GOAL &&
                            dynamicPlanner.executorFor("open_example") ==
                            AyanaDynamicGoalPlanner.EXEC_BROWSER_OPEN_URL &&
                            dynamicPlanner.executorFor("read_title") ==
                            AyanaDynamicGoalPlanner.EXEC_STRUCTURED_SCREEN_READ &&
                            dynamicPlanner.executorFor("youtube_search") ==
                            AyanaDynamicGoalPlanner.EXEC_YOUTUBE_SEARCH &&
                            dynamicPlanner.executorFor("final_device_state") ==
                            AyanaDynamicGoalPlanner.EXEC_DEVICE_STATE

                    val unknownExecutorProposal =
                        JSONObject(initialPlannerProposal.toString())
                    unknownExecutorProposal
                        .optJSONArray("subgoals")
                        ?.optJSONObject(0)
                        ?.put("executor", "github_repository_write")
                    val unknownExecutorBlocked =
                        !AyanaDynamicGoalPlanner
                            .validateProposal(objective, unknownExecutorProposal)
                            .optBoolean("valid", true)

                    val authorityLaunderingProposal =
                        JSONObject(initialPlannerProposal.toString())
                    authorityLaunderingProposal
                        .optJSONArray("subgoals")
                        ?.optJSONObject(0)
                        ?.put("authority", "github_repository_write")
                    val authorityLaunderingBlockedAtPlan =
                        !AyanaDynamicGoalPlanner
                            .validateProposal(objective, authorityLaunderingProposal)
                            .optBoolean("valid", true)

                    val cycleProposal = JSONObject(initialPlannerProposal.toString())
                    val cycleItems = cycleProposal.optJSONArray("subgoals") ?: JSONArray()
                    if (cycleItems.length() > 1) {
                        val first = cycleItems.optJSONObject(0)
                        val last = cycleItems.optJSONObject(cycleItems.length() - 1)
                        if (first != null && last != null) {
                            first.put(
                                "dependencies",
                                JSONArray(listOf(last.optString("id")))
                            )
                        }
                    }
                    val cyclicPlanBlocked =
                        !AyanaDynamicGoalPlanner
                            .validateProposal(objective, cycleProposal)
                            .optBoolean("valid", true)

                    // Plan-validation probes above are pure policy operations. No executor is
                    // called until every mandatory invalid-plan gate has been measured.
                    val invalidPlanDispatchCount = 0

                    val started =
                        isolatedStore.startGoal(
                            command = objective,
                            source = "r10_9_acceptance",
                            mode = AyanaDurableGoalStore.MODE_ORCHESTRATOR,
                            safeAutoResume = true
                        )

                    acceptanceGoalId =
                        started
                            .optString("id")
                            .trim()
                            .takeIf { it.isNotBlank() }

                    if (acceptanceGoalId == null) {
                        throw IllegalStateException(
                            "R10.9 isolated durable goal_id was not created"
                        )
                    }

                    val initialScreen =
                        try {
                            screenIntelligence.getScreenState()
                        } catch (_: Exception) {
                            JSONObject()
                        }

                    val initialState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            initialScreen.toString()
                        )

                    var adaptiveLoop =
                        AyanaAdaptiveExecutionLoop.create(
                            objective = objective,
                            stateFingerprint = initialState,
                            executionLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            authorityContext =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                        )

                    var continuity =
                        AyanaCrossLaneAdaptiveContinuity.create(
                            objective = objective,
                            adaptiveLoop = adaptiveLoop,
                            initialLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            initialAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE,
                            authorityCeiling =
                                AyanaCrossLaneAdaptiveContinuity.defaultUnifiedAuthorityCeiling()
                        )

                    var longObjective =
                        AyanaLongObjectiveCoordinator.create(
                            objectiveId = continuity.objectiveId(),
                            objective = objective,
                            specs = dynamicPlanner.toLongObjectiveSpecs()
                        )

                    val objectiveIdBefore = continuity.objectiveId()

                    val startPatch =
                        crossLaneRecoveryContinuity
                            .buildRecoveryCheckpoint(
                                adaptiveLoop = adaptiveLoop,
                                continuity = continuity,
                                checkpointTag = "r10_9_started",
                                safeAutoResume = true
                            )
                            .put(
                                "mode",
                                AyanaDurableGoalStore.MODE_ORCHESTRATOR
                            )
                            .put(
                                "long_objective_plan",
                                longObjective.snapshot()
                            )
                            .put(
                                "dynamic_planner_plan",
                                dynamicPlanner.snapshot()
                            )

                    val durableStartPersisted =
                        isolatedStore.checkpoint(
                            acceptanceGoalId,
                            startPatch
                        ) != null

                    if (!durableStartPersisted) {
                        throw IllegalStateException(
                            "R10.9 initial durable planner/long-objective checkpoint was not persisted"
                        )
                    }

                    // Dependency preflight: consumer cannot start before producer.
                    val dependencyBlockProbe =
                        longObjective.beginSubgoal(
                            subgoalId = "youtube_search",
                            lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                            authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                        )

                    val dependencyGateBlocked =
                        !dependencyBlockProbe.optBoolean("allowed", true) &&
                            dependencyBlockProbe.optString("reason") ==
                            "dependency_not_verified"

                    var browserOpenDispatchCount = 0

                    // Subgoal 1: factual Agent Core/local device state.
                    val deviceSubgoalGate =
                        longObjective.beginSubgoal(
                            subgoalId = "device_state",
                            lane = AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            authority = AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                        )

                    val agentLaneGate =
                        continuity.transitionTo(
                            adaptiveLoop = adaptiveLoop,
                            targetLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            targetAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE,
                            stateFingerprint = initialState,
                            reason = "r10_8_device_state"
                        )

                    val deviceArgs = JSONObject()
                    val deviceProposal =
                        if (
                            deviceSubgoalGate.optBoolean("allowed", false) &&
                            agentLaneGate.optBoolean("allowed", false)
                        ) {
                            adaptiveLoop.propose(
                                toolName = "get_device_state",
                                arguments = deviceArgs,
                                stateFingerprint = initialState,
                                mayMutate = false,
                                authoritySource =
                                    AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                            )
                        } else {
                            JSONObject().put("allowed", false)
                        }

                    val deviceResult =
                        if (deviceProposal.optBoolean("allowed", false)) {
                            executeAgentTool(
                                name = "get_device_state",
                                arguments = JSONObject()
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                        }

                    val deviceVerified =
                        deviceResult.optBoolean("success", false) &&
                            deviceResult.optBoolean(
                                "verified",
                                deviceResult.optBoolean("success", false)
                            )

                    val deviceAfterState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            deviceResult.toString()
                        )

                    val deviceAdaptiveRecord =
                        adaptiveLoop.recordResult(
                            toolName = "get_device_state",
                            arguments = deviceArgs,
                            beforeStateFingerprint = initialState,
                            afterStateFingerprint = deviceAfterState,
                            success = deviceVerified,
                            verified = deviceVerified,
                            actionDispatched = false,
                            actionCommitted = false,
                            reconciliationComplete = true,
                            evidence = "R10.9 factual device state"
                        )

                    val deviceSubgoalRecord =
                        if (deviceVerified) {
                            longObjective.recordVerified(
                                subgoalId = "device_state",
                                lane = AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                                authority = AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE,
                                evidence = "device state verified"
                            )
                        } else {
                            longObjective.recordFailure(
                                "device_state",
                                "device_state_not_verified"
                            )
                        }

                    // Subgoal 2: real Android Goal with isolated durable checkpoints.
                    val androidSubgoalGate =
                        longObjective.beginSubgoal(
                            subgoalId = "open_ayana",
                            lane = AyanaCrossLaneAdaptiveContinuity.LANE_ANDROID_GOAL,
                            authority = AyanaCrossLaneAdaptiveContinuity.AUTH_ANDROID_GOAL
                        )

                    val androidLaneGate =
                        continuity.transitionTo(
                            adaptiveLoop = adaptiveLoop,
                            targetLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_ANDROID_GOAL,
                            targetAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_ANDROID_GOAL,
                            stateFingerprint = deviceAfterState,
                            reason = "r10_8_android_goal"
                        )

                    val androidArgs =
                        dynamicPlanner.argumentsFor("open_ayana")

                    val androidProposal =
                        if (
                            androidSubgoalGate.optBoolean("allowed", false) &&
                            androidLaneGate.optBoolean("allowed", false)
                        ) {
                            adaptiveLoop.propose(
                                toolName = "execute_android_goal",
                                arguments = androidArgs,
                                stateFingerprint = deviceAfterState,
                                mayMutate = true,
                                authoritySource =
                                    AyanaCrossLaneAdaptiveContinuity.AUTH_ANDROID_GOAL
                            )
                        } else {
                            JSONObject().put("allowed", false)
                        }

                    val androidResult =
                        if (androidProposal.optBoolean("allowed", false)) {
                            executeAndroidGoal(
                                arguments = JSONObject(androidArgs.toString()),
                                checkpointStore = isolatedStore,
                                checkpointGoalId = acceptanceGoalId
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                        }

                    val androidVerified =
                        androidResult.optBoolean("success", false) &&
                            androidResult.optBoolean(
                                "verified",
                                androidResult.optBoolean("success", false)
                            )

                    val androidAfterState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            androidResult
                                .optJSONObject("screen")
                                ?.toString()
                                ?: androidResult.toString()
                        )

                    val androidAdaptiveRecord =
                        adaptiveLoop.recordResult(
                            toolName = "execute_android_goal",
                            arguments = androidArgs,
                            beforeStateFingerprint = deviceAfterState,
                            afterStateFingerprint = androidAfterState,
                            success = androidVerified,
                            verified = androidVerified,
                            actionDispatched =
                                androidResult.optBoolean(
                                    "action_dispatched",
                                    androidVerified
                                ),
                            actionCommitted = false,
                            reconciliationComplete = androidVerified,
                            evidence =
                                androidResult.optString(
                                    "message",
                                    "R10.9 Android Goal verification"
                                ),
                            failureLayer =
                                androidResult.optString("failure_layer")
                        )

                    val androidSubgoalRecord =
                        if (androidVerified) {
                            longObjective.recordVerified(
                                subgoalId = "open_ayana",
                                lane = AyanaCrossLaneAdaptiveContinuity.LANE_ANDROID_GOAL,
                                authority = AyanaCrossLaneAdaptiveContinuity.AUTH_ANDROID_GOAL,
                                evidence = "Android Goal verified"
                            )
                        } else {
                            longObjective.recordFailure(
                                "open_ayana",
                                "android_goal_not_verified"
                            )
                        }

                    // Subgoal 3: Browser source exactly once.
                    val browserSubgoalGate =
                        longObjective.beginSubgoal(
                            subgoalId = "open_example",
                            lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                            authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                        )

                    val multiLaneGate =
                        continuity.transitionTo(
                            adaptiveLoop = adaptiveLoop,
                            targetLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                            targetAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP,
                            stateFingerprint = androidAfterState,
                            reason = "r10_8_browser_source"
                        )

                    val plannedBrowserUrl =
                        dynamicPlanner
                            .argumentsFor("open_example")
                            .optString("url")
                            .trim()

                    val browserArgs =
                        JSONObject()
                            .put(
                                "app_key",
                                AyanaAppIntegrationRegistry.APP_BROWSER
                            )
                            .put(
                                "action_key",
                                AyanaAppIntegrationRegistry.ACTION_OPEN_URL
                            )
                            .put(
                                "payload",
                                plannedBrowserUrl
                            )

                    val browserProposal =
                        if (
                            browserSubgoalGate.optBoolean("allowed", false) &&
                            multiLaneGate.optBoolean("allowed", false)
                        ) {
                            adaptiveLoop.propose(
                                toolName = "app_integration:browser:open_url",
                                arguments = browserArgs,
                                stateFingerprint = androidAfterState,
                                mayMutate = false,
                                authoritySource =
                                    AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                            )
                        } else {
                            JSONObject().put("allowed", false)
                        }

                    val browserResult =
                        if (browserProposal.optBoolean("allowed", false)) {
                            browserOpenDispatchCount++
                            executeAppIntegrationAction(
                                appKey = AyanaAppIntegrationRegistry.APP_BROWSER,
                                actionKey = AyanaAppIntegrationRegistry.ACTION_OPEN_URL,
                                payload = plannedBrowserUrl
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                                .put("action_dispatched", false)
                        }

                    val browserVerified =
                        browserResult.optBoolean("success", false) &&
                            browserResult.optBoolean("verified", false)

                    val browserState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            browserResult.toString()
                        )

                    val browserAdaptiveRecord =
                        adaptiveLoop.recordResult(
                            toolName = "app_integration:browser:open_url",
                            arguments = browserArgs,
                            beforeStateFingerprint = androidAfterState,
                            afterStateFingerprint = browserState,
                            success = browserVerified,
                            verified = browserVerified,
                            actionDispatched =
                                browserResult.optBoolean(
                                    "action_dispatched",
                                    false
                                ),
                            actionCommitted = false,
                            reconciliationComplete = browserVerified,
                            evidence =
                                browserResult.optString(
                                    "message",
                                    "R10.9 Browser source verification"
                                )
                        )

                    val browserSubgoalRecord =
                        if (browserVerified) {
                            longObjective.recordVerified(
                                subgoalId = "open_example",
                                lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                                authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP,
                                evidence = "Browser source verified"
                            )
                        } else {
                            longObjective.recordFailure(
                                "open_example",
                                "browser_not_verified"
                            )
                        }

                    val expectedBrowserPackage =
                        browserResult
                            .optString("observed_package")
                            .trim()
                            .ifBlank {
                                browserResult
                                    .optString("target_package")
                                    .trim()
                            }

                    // Subgoal 4: verified partial result producer.
                    val readSubgoalGate =
                        longObjective.beginSubgoal(
                            subgoalId = "read_title",
                            lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                            authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                        )

                    val visualArgs =
                        JSONObject()
                            .put(
                                "expected_package",
                                expectedBrowserPackage
                            )
                            .put(
                                "mode",
                                "package_bound_structured_visual"
                            )

                    val visualProposal =
                        if (readSubgoalGate.optBoolean("allowed", false)) {
                            adaptiveLoop.propose(
                                toolName =
                                    "screen_observe_package_bound_visual",
                                arguments = visualArgs,
                                stateFingerprint = browserState,
                                mayMutate = false,
                                authoritySource =
                                    AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                            )
                        } else {
                            JSONObject().put("allowed", false)
                        }

                    val visual =
                        if (
                            visualProposal.optBoolean("allowed", false) &&
                            expectedBrowserPackage.isNotBlank()
                        ) {
                            attemptVerifiedStructuredSemanticScreenRead(
                                expectedPackage = expectedBrowserPackage,
                                commandToken = commandToken
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                        }

                    val visualVerified =
                        visual.optBoolean("success", false) &&
                            visual.optBoolean("verified", false) &&
                            visual.optBoolean(
                                "semantic_structured_read_verified",
                                false
                            ) &&
                            visual.optString("semantic_title")
                                .trim()
                                .equals(
                                    R9_7_STRUCTURED_ACCEPTANCE_TITLE,
                                    ignoreCase = true
                                )

                    val visualAfterState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            visual.toString()
                        )

                    val visualAdaptiveRecord =
                        if (visualProposal.optBoolean("allowed", false)) {
                            adaptiveLoop.recordResult(
                                toolName =
                                    "screen_observe_package_bound_visual",
                                arguments = visualArgs,
                                beforeStateFingerprint = browserState,
                                afterStateFingerprint = visualAfterState,
                                success = visualVerified,
                                verified = visualVerified,
                                actionDispatched = false,
                                actionCommitted = false,
                                reconciliationComplete = true,
                                evidence =
                                    visual.optString(
                                        "reason",
                                        "R10.9 structured visual verification"
                                    ),
                                failureLayer =
                                    if (visualVerified) "" else "verification"
                            )
                        } else {
                            JSONObject()
                                .put("recorded", false)
                                .put("verified", false)
                        }

                    val transferredTitle =
                        visual.optString("semantic_title")
                            .trim()

                    val readSubgoalRecord =
                        if (visualVerified) {
                            longObjective.recordVerified(
                                subgoalId = "read_title",
                                lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                                authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP,
                                evidence = "verified structured page title",
                                resultValue = transferredTitle
                            )
                        } else {
                            longObjective.recordFailure(
                                "read_title",
                                "structured_title_not_verified"
                            )
                        }

                    // R10.9 verified plan revision. First prove that a planner-valid
                    // mutation of an already VERIFIED execution contract is rejected.
                    val badRevisionProposal =
                        r10_9VerifiedPrefixMutationProposal(dynamicPlanner)
                    val badRevisionPlanner =
                        AyanaDynamicGoalPlanner.compile(
                            objective = objective,
                            proposal = badRevisionProposal
                        )
                    val badRevisionGate =
                        longObjective.applyPlanRevision(
                            badRevisionPlanner.toLongObjectiveSpecs()
                        )
                    val verifiedPrefixMutationBlocked =
                        !badRevisionGate.optBoolean("allowed", true) &&
                            badRevisionGate.optString("reason") ==
                            "verified_prefix_mutation_blocked" &&
                            longObjective.planRevision() == 0

                    // Now insert one new unresolved suffix gate. The first four VERIFIED
                    // subgoals and page_title provenance must remain immutable.
                    val revisedPlannerProposal =
                        r10_9VerifiedSuffixRevisionProposal(dynamicPlanner)
                    val revisedPlanner =
                        AyanaDynamicGoalPlanner.compile(
                            objective = objective,
                            proposal = revisedPlannerProposal
                        )
                    val planRevisionGate =
                        longObjective.applyPlanRevision(
                            revisedPlanner.toLongObjectiveSpecs()
                        )
                    val planRevisionApplied =
                        planRevisionGate.optBoolean("allowed", false) &&
                            longObjective.planRevision() == 1

                    dynamicPlanner = revisedPlanner
                    val revisedPlanSubgoalCount = dynamicPlanner.subgoalCount()
                    val revisedPlanFingerprint = dynamicPlanner.planFingerprint()

                    val verifiedPrefixPreservedOnPlanRevision =
                        planRevisionApplied &&
                            longObjective.verifiedSubgoalCount() == 4 &&
                            longObjective.statusOf("device_state") ==
                            AyanaLongObjectiveCoordinator.STATUS_VERIFIED &&
                            longObjective.statusOf("open_ayana") ==
                            AyanaLongObjectiveCoordinator.STATUS_VERIFIED &&
                            longObjective.statusOf("open_example") ==
                            AyanaLongObjectiveCoordinator.STATUS_VERIFIED &&
                            longObjective.statusOf("read_title") ==
                            AyanaLongObjectiveCoordinator.STATUS_VERIFIED &&
                            longObjective.statusOf("confirm_title") ==
                            AyanaLongObjectiveCoordinator.STATUS_PENDING

                    val partialAfterPlanRevision =
                        longObjective.partialResult(
                            key = "page_title",
                            consumerSubgoalId = "confirm_title"
                        )

                    val partialResultPreservedOnPlanRevision =
                        partialAfterPlanRevision.optBoolean("verified", false) &&
                            partialAfterPlanRevision.optString("value") ==
                            R9_7_STRUCTURED_ACCEPTANCE_TITLE &&
                            partialAfterPlanRevision.optString("producer_subgoal_id") ==
                            "read_title"

                    val partialBeforeRestart =
                        longObjective.partialResult(
                            key = "page_title",
                            consumerSubgoalId = "confirm_title"
                        )

                    val partialResultVerifiedBeforeRestart =
                        partialBeforeRestart.optBoolean("verified", false) &&
                            partialBeforeRestart.optString("value") ==
                            R9_7_STRUCTURED_ACCEPTANCE_TITLE

                    val longSnapshotBeforeRestart = longObjective.snapshot()
                    val adaptiveVerifiedBeforeRestart =
                        adaptiveLoop.verifiedStepCount()
                    val transitionCountBeforeRestart =
                        continuity.laneTransitionCount()

                    val preInterruptPatch =
                        crossLaneRecoveryContinuity
                            .buildRecoveryCheckpoint(
                                adaptiveLoop = adaptiveLoop,
                                continuity = continuity,
                                checkpointTag =
                                    "r10_9_revised_plan_pre_interrupt",
                                safeAutoResume = true
                            )
                            .put(
                                "mode",
                                AyanaDurableGoalStore.MODE_ORCHESTRATOR
                            )
                            .put("status", AyanaDurableGoalStore.STATUS_ACTIVE)
                            .put(
                                "long_objective_plan",
                                longSnapshotBeforeRestart
                            )
                            .put(
                                "dynamic_planner_plan",
                                dynamicPlanner.snapshot()
                            )
                            .put(
                                "partial_result_page_title",
                                partialBeforeRestart
                            )

                    val durablePreInterruptPersisted =
                        isolatedStore.checkpoint(
                            acceptanceGoalId,
                            preInterruptPatch
                        ) != null

                    val interruptedCount =
                        if (durablePreInterruptPersisted) {
                            isolatedStore.markInterruptedGoals(
                                "service_destroyed"
                            )
                        } else {
                            0
                        }

                    // New store instance = restart boundary.
                    val restartedStore =
                        AyanaDurableGoalStore(
                            context = applicationContext,
                            storageFileName = testFileName
                        )
                    acceptanceStore = restartedStore

                    val restoredGoal =
                        restartedStore.getById(
                            acceptanceGoalId.orEmpty()
                        )

                    val recoveryDecision =
                        crossLaneRecoveryContinuity.evaluate(
                            goal = restoredGoal,
                            automatic = true
                        )

                    val automaticRecoveryAllowed =
                        recoveryDecision.optString("strategy") ==
                            AyanaCrossLaneRecoveryContinuity.Strategy
                                .RESTORE_AND_CONTINUE.name &&
                            recoveryDecision.optBoolean(
                                "automatic_resume_allowed",
                                false
                            )

                    val persistedAdaptiveSnapshot =
                        restoredGoal?.optJSONObject(
"adaptive_execution_loop"
                        )
                    val persistedContinuitySnapshot =
                        restoredGoal?.optJSONObject(
                            "cross_lane_continuity"
                        )
                    val persistedLongObjectiveSnapshot =
                        restoredGoal?.optJSONObject(
                            "long_objective_plan"
                        )
                    val persistedDynamicPlannerSnapshot =
                        restoredGoal?.optJSONObject(
                            "dynamic_planner_plan"
                        )

                    dynamicPlanner =
                        AyanaDynamicGoalPlanner.restore(
                            persistedDynamicPlannerSnapshot
                        )

                    val dynamicPlannerRestoreVerified =
                        dynamicPlanner.planFingerprint() == revisedPlanFingerprint &&
                            dynamicPlanner.subgoalCount() == revisedPlanSubgoalCount

                    adaptiveLoop =
                        AyanaAdaptiveExecutionLoop.restore(
                            snapshot = persistedAdaptiveSnapshot,
                            fallbackObjective = objective,
                            fallbackExecutionLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            fallbackAuthorityContext =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                        )

                    continuity =
                        AyanaCrossLaneAdaptiveContinuity.restore(
                            snapshot = persistedContinuitySnapshot,
                            fallbackObjective = objective,
                            adaptiveLoop = adaptiveLoop,
                            fallbackAuthorityCeiling =
                                AyanaCrossLaneAdaptiveContinuity.defaultUnifiedAuthorityCeiling()
                        )

                    longObjective =
                        AyanaLongObjectiveCoordinator.restore(
                            persistedLongObjectiveSnapshot
                        )

                    val crossLaneRestore =
                        crossLaneRecoveryContinuity.verifyRestored(
                            persistedGoal = restoredGoal,
                            adaptiveLoop = adaptiveLoop,
                            continuity = continuity
                        )

                    val longObjectiveRestore =
                        longObjective.verifyRestoredAgainst(
                            persistedLongObjectiveSnapshot
                        )

                    val recoveryIncremented =
                        if (
                            automaticRecoveryAllowed &&
                            crossLaneRestore.optBoolean("verified", false) &&
                            longObjectiveRestore.optBoolean("verified", false)
                        ) {
                            restartedStore.incrementRecovery(
                                acceptanceGoalId
                            ) != null
                        } else {
                            false
                        }

                    val interruptionCheckpointPreserved =
                        restoredGoal?.optString(
                            "interrupted_from_checkpoint"
                        ) ==
                        "r10_9_revised_plan_pre_interrupt"

                    val restoredPartial =
                        longObjective.partialResult(
                            key = "page_title",
                            consumerSubgoalId = "confirm_title"
                        )

                    val partialResultPreserved =
                        restoredPartial.optBoolean("verified", false) &&
                            restoredPartial.optString("value") ==
                            R9_7_STRUCTURED_ACCEPTANCE_TITLE &&
                            restoredPartial.optString("producer_subgoal_id") ==
                            "read_title"

                    val restartStatePreserved =
                        interruptedCount == 1 &&
                            interruptionCheckpointPreserved &&
                            crossLaneRestore.optBoolean("verified", false) &&
                            longObjectiveRestore.optBoolean("verified", false) &&
                            continuity.objectiveId() == objectiveIdBefore &&
                            longObjective.objectiveId() == objectiveIdBefore &&
                            adaptiveLoop.verifiedStepCount() ==
                            adaptiveVerifiedBeforeRestart &&
                            continuity.laneTransitionCount() ==
                            transitionCountBeforeRestart &&
                            longObjective.verifiedSubgoalCount() == 4 &&
                            longObjective.planRevision() == 1 &&
                            dynamicPlannerRestoreVerified &&
                            partialResultPreserved

                    // Already verified producer work must not replay after restart.
                    val browserSubgoalReplay =
                        longObjective.beginSubgoal(
                            subgoalId = "open_example",
                            lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                            authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                        )

                    val visualSubgoalReplay =
                        longObjective.beginSubgoal(
                            subgoalId = "read_title",
                            lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                            authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                        )

                    val verifiedSubgoalReplayBlocked =
                        browserSubgoalReplay.optString("reason") ==
                            "verified_subgoal_replay_blocked" &&
                            visualSubgoalReplay.optString("reason") ==
                            "verified_subgoal_replay_blocked"

                    val browserAdaptiveReplay =
                        adaptiveLoop.propose(
                            toolName = "app_integration:browser:open_url",
                            arguments = browserArgs,
                            stateFingerprint = androidAfterState,
                            mayMutate = false,
                            authoritySource =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                        )

                    val adaptiveBrowserReplayBlocked =
                        !browserAdaptiveReplay.optBoolean("allowed", true) &&
                            browserAdaptiveReplay.optString("reason") ==
                            "verified_transition_replay_blocked" &&
                            browserOpenDispatchCount == 1

                    // R10.9 revised suffix gate inserted by plan revision. It consumes
                    // the restored verified page_title without any external dispatch.
                    val confirmSubgoalGate =
                        longObjective.beginSubgoal(
                            subgoalId = "confirm_title",
                            lane = AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            authority = AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                        )

                    val confirmAgentLaneGate =
                        continuity.transitionTo(
                            adaptiveLoop = adaptiveLoop,
                            targetLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            targetAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE,
                            stateFingerprint = visualAfterState,
                            reason = "r10_9_revised_suffix_partial_result_check"
                        )

                    val confirmArgs =
                        dynamicPlanner.argumentsFor("confirm_title")

                    val confirmProposal =
                        if (
                            confirmSubgoalGate.optBoolean("allowed", false) &&
                            confirmAgentLaneGate.optBoolean("allowed", false) &&
                            partialResultPreserved
                        ) {
                            adaptiveLoop.propose(
                                toolName = "planner:partial_result_check",
                                arguments = confirmArgs,
                                stateFingerprint = visualAfterState,
                                mayMutate = false,
                                authoritySource =
                                    AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                            )
                        } else {
                            JSONObject().put("allowed", false)
                        }

                    val confirmPartial =
                        longObjective.partialResult(
                            key = "page_title",
                            consumerSubgoalId = "confirm_title"
                        )

                    val confirmTitleVerified =
                        confirmProposal.optBoolean("allowed", false) &&
                            confirmPartial.optBoolean("verified", false) &&
                            confirmPartial.optString("value") ==
                            R9_7_STRUCTURED_ACCEPTANCE_TITLE

                    val confirmAfterState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            confirmPartial.toString()
                        )

                    val confirmAdaptiveRecord =
                        if (confirmProposal.optBoolean("allowed", false)) {
                            adaptiveLoop.recordResult(
                                toolName = "planner:partial_result_check",
                                arguments = confirmArgs,
                                beforeStateFingerprint = visualAfterState,
                                afterStateFingerprint = confirmAfterState,
                                success = confirmTitleVerified,
                                verified = confirmTitleVerified,
                                actionDispatched = false,
                                actionCommitted = false,
                                reconciliationComplete = true,
                                evidence = "R10.9 restored partial-result suffix gate"
                            )
                        } else {
                            JSONObject()
                                .put("recorded", false)
                                .put("verified", false)
                        }

                    val confirmSubgoalRecord =
                        if (confirmTitleVerified) {
                            longObjective.recordVerified(
                                subgoalId = "confirm_title",
                                lane = AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                                authority = AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE,
                                evidence = "restored page_title provenance verified"
                            )
                        } else {
                            longObjective.recordFailure(
                                "confirm_title",
                                "restored_partial_result_not_verified"
                            )
                        }

                    // Revised suffix consumer uses both read_title provenance and the
                    // newly inserted confirm_title gate.
                    val youtubeSubgoalGate =
                        longObjective.beginSubgoal(
                            subgoalId = "youtube_search",
                            lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                            authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                        )

                    val resumeMultiGate =
                        continuity.transitionTo(
                            adaptiveLoop = adaptiveLoop,
                            targetLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                            targetAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP,
                            stateFingerprint = confirmAfterState,
                            reason = "r10_9_resume_consumer"
                        )

                    val restoredTitle =
                        restoredPartial.optString("value").trim()

                    val youtubeArgs =
                        JSONObject()
                            .put(
                                "app_key",
                                AyanaAppIntegrationRegistry.APP_YOUTUBE
                            )
                            .put(
                                "action_key",
                                AyanaAppIntegrationRegistry.ACTION_SEARCH
                            )
                            .put("payload", restoredTitle)

                    val youtubeProposal =
                        if (
                            youtubeSubgoalGate.optBoolean("allowed", false) &&
                            resumeMultiGate.optBoolean("allowed", false) &&
                            partialResultPreserved
                        ) {
                            adaptiveLoop.propose(
                                toolName = "app_integration:youtube:search",
                                arguments = youtubeArgs,
                                stateFingerprint = confirmAfterState,
                                mayMutate = false,
                                authoritySource =
                                    AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                            )
                        } else {
                            JSONObject().put("allowed", false)
                        }

                    val youtubeResult =
                        if (youtubeProposal.optBoolean("allowed", false)) {
                            executeAppIntegrationAction(
                                appKey = AyanaAppIntegrationRegistry.APP_YOUTUBE,
                                actionKey = AyanaAppIntegrationRegistry.ACTION_SEARCH,
                                payload = restoredTitle
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                                .put("action_dispatched", false)
                        }

                    val youtubeVerified =
                        youtubeResult.optBoolean("success", false) &&
                            youtubeResult.optBoolean("verified", false)

                    val youtubeAfterState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            youtubeResult.toString()
                        )

                    val youtubeAdaptiveRecord =
                        if (youtubeProposal.optBoolean("allowed", false)) {
                            adaptiveLoop.recordResult(
                                toolName = "app_integration:youtube:search",
                                arguments = youtubeArgs,
                                beforeStateFingerprint = confirmAfterState,
                                afterStateFingerprint = youtubeAfterState,
                                success = youtubeVerified,
                                verified = youtubeVerified,
                                actionDispatched =
                                    youtubeResult.optBoolean(
                                        "action_dispatched",
                                        false
                                    ),
                                actionCommitted = false,
                                reconciliationComplete = youtubeVerified,
                                evidence =
                                    youtubeResult.optString(
                                        "message",
                                        "R10.9 YouTube consumer verification"
                                    )
                            )
                        } else {
                            JSONObject()
                                .put("recorded", false)
                                .put("verified", false)
                        }

                    val youtubeSubgoalRecord =
                        if (youtubeVerified) {
                            longObjective.recordVerified(
                                subgoalId = "youtube_search",
                                lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                                authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP,
                                evidence = "YouTube consumed restored page_title"
                            )
                        } else {
                            longObjective.recordFailure(
                                "youtube_search",
                                "youtube_consumer_not_verified"
                            )
                        }

                    // Subgoal 6 has two dependencies and moves back to Agent Core.
                    val finalSubgoalGate =
                        longObjective.beginSubgoal(
                            subgoalId = "final_device_state",
                            lane = AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            authority = AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                        )

                    val finalAgentGate =
                        continuity.transitionTo(
                            adaptiveLoop = adaptiveLoop,
                            targetLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            targetAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE,
                            stateFingerprint = youtubeAfterState,
                            reason = "r10_9_final_agent_verification"
                        )

                    val finalArgs = JSONObject()
                    val finalProposal =
                        if (
                            finalSubgoalGate.optBoolean("allowed", false) &&
                            finalAgentGate.optBoolean("allowed", false)
                        ) {
                            adaptiveLoop.propose(
                                toolName = "get_device_state",
                                arguments = finalArgs,
                                stateFingerprint = youtubeAfterState,
                                mayMutate = false,
                                authoritySource =
                                    AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                            )
                        } else {
                            JSONObject().put("allowed", false)
                        }

                    val finalDeviceResult =
                        if (finalProposal.optBoolean("allowed", false)) {
                            executeAgentTool(
                                name = "get_device_state",
                                arguments = JSONObject()
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                        }

                    val finalDeviceVerified =
                        finalDeviceResult.optBoolean("success", false) &&
                            finalDeviceResult.optBoolean(
                                "verified",
                                finalDeviceResult.optBoolean("success", false)
                            )

                    val finalAfterState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            finalDeviceResult.toString()
                        )

                    val finalAdaptiveRecord =
                        if (finalProposal.optBoolean("allowed", false)) {
                            adaptiveLoop.recordResult(
                                toolName = "get_device_state",
                                arguments = finalArgs,
                                beforeStateFingerprint = youtubeAfterState,
                                afterStateFingerprint = finalAfterState,
                                success = finalDeviceVerified,
                                verified = finalDeviceVerified,
                                actionDispatched = false,
                                actionCommitted = false,
                                reconciliationComplete = true,
                                evidence = "R10.9 final factual device state"
                            )
                        } else {
                            JSONObject()
                                .put("recorded", false)
                                .put("verified", false)
                        }

                    val finalSubgoalRecord =
                        if (finalDeviceVerified) {
                            longObjective.recordVerified(
                                subgoalId = "final_device_state",
                                lane = AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                                authority = AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE,
                                evidence = "final device state verified"
                            )
                        } else {
                            longObjective.recordFailure(
                                "final_device_state",
                                "final_device_state_not_verified"
                            )
                        }

                    finalRestore =
                        restoreAyanaAfterAppIntegrationProbe(
                            pageKey = originalPage,
                            stepKey = "r10-9-dynamic-plan-final-restore"
                        )

                    val restoreVerified =
                        finalRestore?.optBoolean("verified", false) == true

                    val longObjectiveTerminalReady =
                        longObjective.canDeclareSuccess()

                    val adaptiveTerminal =
                        adaptiveLoop.markTerminal(
                            verified =
                                plannerSelfTest &&
                                    longObjectiveSelfTest &&
                                    recoverySelfTest &&
                                    continuitySelfTest &&
                                    adaptiveSelfTest &&
                                    longRecoverySelfTest &&
                                    freeFormDecompositionVerified &&
                                    initialExecutorBindingVerified &&
                                    unknownExecutorBlocked &&
                                    authorityLaunderingBlockedAtPlan &&
                                    cyclicPlanBlocked &&
                                    invalidPlanDispatchCount == 0 &&
                                    verifiedPrefixMutationBlocked &&
                                    planRevisionApplied &&
                                    verifiedPrefixPreservedOnPlanRevision &&
                                    partialResultPreservedOnPlanRevision &&
                                    dynamicPlannerRestoreVerified &&
                                    confirmAdaptiveRecord.optBoolean("verified", false) &&
                                    dependencyGateBlocked &&
                                    restartStatePreserved &&
                                    recoveryIncremented &&
                                    verifiedSubgoalReplayBlocked &&
                                    adaptiveBrowserReplayBlocked &&
                                    youtubeAdaptiveRecord.optBoolean("verified", false) &&
                                    finalAdaptiveRecord.optBoolean("verified", false) &&
                                    longObjectiveTerminalReady &&
                                    restoreVerified &&
                                    !adaptiveLoop.hasUnresolvedSideEffect(),
                            evidence =
                                "dependency_gate=$dependencyGateBlocked; partial=$partialResultPreserved; restart=$restartStatePreserved; youtube=$youtubeVerified; final=$finalDeviceVerified; restore=$restoreVerified"
                        )

                    val finalPatch =
                        crossLaneRecoveryContinuity
                            .buildRecoveryCheckpoint(
                                adaptiveLoop = adaptiveLoop,
                                continuity = continuity,
                                checkpointTag =
                                    "r10_9_dynamic_plan_terminal",
                                safeAutoResume = false
                            )
                            .put(
                                "mode",
                                AyanaDurableGoalStore.MODE_ORCHESTRATOR
                            )
                            .put(
                                "long_objective_plan",
                                longObjective.snapshot()
                            )
                            .put(
                                "dynamic_planner_plan",
                                dynamicPlanner.snapshot()
                            )
                            .put(
                                "terminal_verified",
                                adaptiveLoop.canDeclareSuccess() &&
                                    longObjectiveTerminalReady
                            )

                    val durableFinalPersisted =
                        restartedStore.checkpoint(
                            acceptanceGoalId,
                            finalPatch
                        ) != null

                    val coreAccepted =
                        plannerSelfTest &&
                            longObjectiveSelfTest &&
                            recoverySelfTest &&
                            continuitySelfTest &&
                            adaptiveSelfTest &&
                            longRecoverySelfTest &&
                            freeFormDecompositionVerified &&
                            initialExecutorBindingVerified &&
                            unknownExecutorBlocked &&
                            authorityLaunderingBlockedAtPlan &&
                            cyclicPlanBlocked &&
                            invalidPlanDispatchCount == 0 &&
                            verifiedPrefixMutationBlocked &&
                            planRevisionApplied &&
                            verifiedPrefixPreservedOnPlanRevision &&
                            partialResultPreservedOnPlanRevision &&
                            dynamicPlannerRestoreVerified &&
                            durableStartPersisted &&
                            dependencyGateBlocked &&
                            deviceSubgoalGate.optBoolean("allowed", false) &&
                            deviceAdaptiveRecord.optBoolean("verified", false) &&
                            deviceSubgoalRecord.optBoolean("verified", false) &&
                            androidSubgoalGate.optBoolean("allowed", false) &&
                            androidAdaptiveRecord.optBoolean("verified", false) &&
                            androidSubgoalRecord.optBoolean("verified", false) &&
                            browserSubgoalGate.optBoolean("allowed", false) &&
                            browserAdaptiveRecord.optBoolean("verified", false) &&
                            browserSubgoalRecord.optBoolean("verified", false) &&
                            browserOpenDispatchCount == 1 &&
                            readSubgoalGate.optBoolean("allowed", false) &&
                            visualAdaptiveRecord.optBoolean("verified", false) &&
                            readSubgoalRecord.optBoolean("verified", false) &&
                            partialResultVerifiedBeforeRestart &&
                            durablePreInterruptPersisted &&
                            interruptedCount == 1 &&
                            automaticRecoveryAllowed &&
                            recoveryIncremented &&
                            restartStatePreserved &&
                            partialResultPreserved &&
                            verifiedSubgoalReplayBlocked &&
                            adaptiveBrowserReplayBlocked &&
                            browserOpenDispatchCount == 1 &&
                            youtubeSubgoalGate.optBoolean("allowed", false) &&
                            youtubeAdaptiveRecord.optBoolean("verified", false) &&
                            youtubeSubgoalRecord.optBoolean("verified", false) &&
                            finalSubgoalGate.optBoolean("allowed", false) &&
                            finalAdaptiveRecord.optBoolean("verified", false) &&
                            finalSubgoalRecord.optBoolean("verified", false) &&
                            longObjective.verifiedSubgoalCount() == 7 &&
                            longObjective.partialResultCount() == 1 &&
                            longObjective.planRevision() == 1 &&
                            confirmSubgoalGate.optBoolean("allowed", false) &&
                            confirmAdaptiveRecord.optBoolean("verified", false) &&
                            confirmSubgoalRecord.optBoolean("verified", false) &&
                            longObjectiveTerminalReady &&
                            adaptiveTerminal.optBoolean("allowed", false) &&
                            adaptiveLoop.canDeclareSuccess() &&
                            continuity.objectiveId() == objectiveIdBefore &&
                            longObjective.objectiveId() == objectiveIdBefore &&
                            !adaptiveLoop.hasUnresolvedSideEffect() &&
                            durableFinalPersisted &&
                            restoreVerified

                    if (coreAccepted) {
                        restartedStore.markCompleted(
                            acceptanceGoalId,
                            "R10.9 dynamic goal decomposition and verified suffix revision accepted"
                        )
                    } else {
                        restartedStore.markFailed(
                            acceptanceGoalId,
                            "R10.9 dynamic planner acceptance failed verification"
                        )
                    }

                    val cleanupVerified =
                        try {
                            restartedStore.clearAcceptanceStorage()
                        } catch (_: Exception) {
                            false
                        }

                    val accepted = coreAccepted && cleanupVerified

                    val evidence =
                        JSONObject()
                            .put(
                                "dynamic_goal_planner_version",
                                AyanaDynamicGoalPlanner.VERSION
                            )
                            .put("free_form_decomposition_verified", freeFormDecompositionVerified)
                            .put("initial_executor_binding_verified", initialExecutorBindingVerified)
                            .put("initial_plan_subgoal_count", initialPlanSubgoalCount)
                            .put("initial_plan_fingerprint", initialPlanFingerprint)
                            .put("revised_plan_subgoal_count", revisedPlanSubgoalCount)
                            .put("revised_plan_fingerprint", revisedPlanFingerprint)
                            .put("plan_revision", longObjective.planRevision())
                            .put("unknown_executor_blocked_pre_dispatch", unknownExecutorBlocked)
                            .put("cyclic_plan_blocked_pre_dispatch", cyclicPlanBlocked)
                            .put("authority_laundering_blocked_pre_dispatch", authorityLaunderingBlockedAtPlan)
                            .put("invalid_plan_dispatch_count", invalidPlanDispatchCount)
                            .put("verified_prefix_mutation_blocked", verifiedPrefixMutationBlocked)
                            .put("verified_prefix_preserved_on_plan_revision", verifiedPrefixPreservedOnPlanRevision)
                            .put("partial_result_preserved_on_plan_revision", partialResultPreservedOnPlanRevision)
                            .put("revised_suffix_gate_verified", confirmTitleVerified)
                            .put("dynamic_planner_restore_verified", dynamicPlannerRestoreVerified)
                            .put("plan_revision_preserved_after_restart", longObjectiveRestore.optBoolean("plan_revision_preserved", false))
                            .put(
                                "long_objective_coordinator_version",
                                AyanaLongObjectiveCoordinator.VERSION
                            )
                            .put(
                                "cross_lane_recovery_version",
                                AyanaCrossLaneRecoveryContinuity.VERSION
                            )
                            .put(
                                "cross_lane_continuity_version",
                                AyanaCrossLaneAdaptiveContinuity.VERSION
                            )
                            .put(
                                "adaptive_loop_version",
                                AyanaAdaptiveExecutionLoop.VERSION
                            )
                            .put("objective_id", objectiveIdBefore)
                            .put(
                                "objective_id_preserved_after_restart",
                                continuity.objectiveId() == objectiveIdBefore &&
                                    longObjective.objectiveId() == objectiveIdBefore
                            )
                            .put("subgoal_count", longObjective.subgoalCount())
                            .put(
                                "required_subgoal_count",
                                longObjective.requiredSubgoalCount()
                            )
                            .put(
                                "verified_subgoal_count",
                                longObjective.verifiedSubgoalCount()
                            )
                            .put(
                                "dependency_gate_blocked_early_consumer",
                                dependencyGateBlocked
                            )
                            .put(
                                "partial_result_verified_before_restart",
                                partialResultVerifiedBeforeRestart
                            )
                            .put(
                                "partial_result_preserved_after_restart",
                                partialResultPreserved
                            )
                            .put(
                                "partial_result_value",
                                restoredPartial.optString("value")
                            )
                            .put(
                                "partial_result_provenance_verified",
                                longObjectiveRestore.optBoolean(
                                    "partial_result_provenance_verified",
                                    false
                                )
                            )
                            .put("interrupted_goal_count", interruptedCount)
                            .put(
                                "interruption_checkpoint_preserved",
                                interruptionCheckpointPreserved
                            )
                            .put(
                                "recovery_strategy",
                                recoveryDecision.optString("strategy")
                            )
                            .put(
                                "automatic_recovery_allowed",
                                automaticRecoveryAllowed
                            )
                            .put(
                                "cross_lane_restore_verified",
                                crossLaneRestore.optBoolean("verified", false)
                            )
                            .put(
                                "long_objective_restore_verified",
                                longObjectiveRestore.optBoolean("verified", false)
                            )
                            .put(
                                "recovery_count_incremented",
                                recoveryIncremented
                            )
                            .put(
                                "verified_subgoal_replay_blocked_after_restart",
                                verifiedSubgoalReplayBlocked
                            )
                            .put(
                                "verified_browser_replay_blocked_after_restart",
                                adaptiveBrowserReplayBlocked
                            )
                            .put(
                                "browser_open_dispatch_count",
                                browserOpenDispatchCount
                            )
                            .put("browser_open_replayed", false)
                            .put("agent_core_step_verified", deviceVerified)
                            .put("android_goal_step_verified", androidVerified)
                            .put("browser_step_verified", browserVerified)
                            .put("structured_visual_verified", visualVerified)
                            .put("youtube_consumer_verified", youtubeVerified)
                            .put(
                                "final_agent_verification_verified",
                                finalDeviceVerified
                            )
                            .put(
                                "durable_start_snapshot_persisted",
                                durableStartPersisted
                            )
                            .put(
                                "durable_partial_result_snapshot_persisted",
                                durablePreInterruptPersisted
                            )
                            .put(
                                "durable_final_checkpoint_persisted",
                                durableFinalPersisted
                            )
                            .put(
                                "isolated_acceptance_storage_cleanup_verified",
                                cleanupVerified
                            )
                            .put(
                                "production_durable_goal_store_touched",
                                false
                            )
                            .put(
                                "long_objective_terminal_ready",
                                longObjectiveTerminalReady
                            )
                            .put(
                                "unresolved_side_effect",
                                adaptiveLoop.hasUnresolvedSideEffect()
                            )
                            .put(
                                "terminal_verified",
                                adaptiveLoop.canDeclareSuccess() &&
                                    longObjectiveTerminalReady
                            )
                            .put("restore_verified", restoreVerified)
                            .put("mutation_committed_detected", false)
                            .put("blind_replay_allowed", false)
                            .put("persistent_user_data_mutation", false)
                            .put("worker_visual_turns", if (visualVerified) 1 else 0)
                            .put("agent_core_model_turns", 0)
                            .put("acceptance_ok", accepted)
                            .put(
                                "long_objective_summary",
                                longObjective.compactSummary()
                            )
                            .put(
                                "continuity_summary",
                                continuity.compactSummary(adaptiveLoop)
                            )
                            .put(
                                "voice_service_release",
                                AYANA_VOICE_SERVICE_RELEASE
                            )
                            .put(
                                "accepted_checkpoint",
                                AYANA_ACCEPTED_FEATURE_CHECKPOINT
                            )
                            .put(
                                "current_release",
                                AYANA_CURRENT_FEATURE_RELEASE
                            )

                    mainHandler.post {
                        if (
                            isCommandCancelled(commandToken) ||
                            commandToken != activeCommandToken
                        ) {
                            return@post
                        }

                        if (!accepted) {
                            commandHistoryStore.addEvent(
                                activeCommandHistoryId,
                                state =
                                    "r10_9_dynamic_goal_decomposition_not_verified",
                                message =
                                    "R10.9 dynamic planner не прошёл decomposition/plan-validation/revision/recovery/terminal gates",
                                details = evidence.toString().take(3900)
                            )

                            respondAndResume(
                                text =
                                    "R10.9 выполнен fail-closed: динамическая декомпозиция/plan revision не подтверждены по всем обязательным gates.",
                                silent = silent,
                                success = false,
                                technical = evidence.toString()
                            )
                            return@post
                        }

                        commandHistoryStore.addEvent(
                            activeCommandHistoryId,
                            state =
                                "r10_9_dynamic_goal_decomposition_verified",
                            message =
                                "R10.9 подтверждён: free-form objective прошёл bounded decomposition, plan-validation и verified suffix revision; после restart продолжен только новый unresolved suffix",
                            details = evidence.toString().take(3900)
                        )

                        respondAndResume(
                            text =
                                "R10.9 Dynamic Goal Decomposition подтверждён: free-form objective был преобразован в проверенный DAG, invalid plans заблокированы до dispatch, VERIFIED prefix пережил plan revision/restart, а revised suffix завершён без replay Browser/visual.",
                            silent = silent,
                            success = true,
                            technical = evidence.toString()
                        )
                    }
                } catch (error: Exception) {
                    try {
                        acceptanceStore?.markFailed(
                            acceptanceGoalId,
                            "R10.9 acceptance exception: ${error.message ?: error.javaClass.simpleName}"
                        )
                    } catch (_: Exception) {
                    }

                    try {
                        finalRestore =
                            restoreAyanaAfterAppIntegrationProbe(
                                pageKey = originalPage,
                                stepKey = "r10-9-dynamic-plan-error-restore"
                            )
                    } catch (_: Exception) {
                    }

                    val evidence =
                        JSONObject()
                            .put(
                                "dynamic_goal_planner_version",
                                AyanaDynamicGoalPlanner.VERSION
                            )
                            .put(
                                "long_objective_coordinator_version",
                                AyanaLongObjectiveCoordinator.VERSION
                            )
                            .put("acceptance_ok", false)
                            .put(
                                "exception",
                                (error.message ?: error.javaClass.simpleName)
                                    .take(600)
                            )
                            .put(
                                "restore_verified",
                                finalRestore?.optBoolean("verified", false) == true
                            )
                            .put("blind_replay_allowed", false)
                            .put("persistent_user_data_mutation", false)

                    mainHandler.post {
                        if (
                            commandToken == activeCommandToken &&
                            !shuttingDown
                        ) {
                            commandHistoryStore.addEvent(
                                activeCommandHistoryId,
                                state =
                                    "r10_9_dynamic_goal_decomposition_not_verified",
                                message = "R10.9 acceptance exception",
                                details = evidence.toString().take(2500)
                            )

                            respondAndResume(
                                text =
                                    "R10.9 dynamic goal decomposition не подтверждён: acceptance завершился fail-closed.",
                                silent = silent,
                                success = false,
                                technical = evidence.toString()
                            )
                        }
                    }
                } finally {
                    if (
                        finalRestore == null ||
                        finalRestore?.optBoolean("verified", false) != true
                    ) {
                        try {
                            restoreAyanaAfterAppIntegrationProbe(
                                pageKey = originalPage,
                                stepKey = "r10-9-dynamic-plan-finally-restore"
                            )
                        } catch (_: Exception) {
                        }
                    }

                    try {
                        acceptanceStore?.clearAcceptanceStorage()
                    } catch (_: Exception) {
                    }

                    if (Thread.currentThread() === currentAgentThread) {
                        currentAgentThread = null
                    }
                }
            }

        currentAgentThread = worker
        executionKernel.bindThread(worker)
        worker.start()
    }

    private fun isR10_8GeneralPurposeLongObjectiveAcceptanceCommand(
        command: String
    ): Boolean {
        val normalized =
            command
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()
                .removePrefix("аяна ")
                .trim()

        return normalized in
            setOf(
                "проверь длинную автономную цель",
                "проверь общую длинную автономную цель",
                "проверь многоэтапную автономную цель",
                "проверь general-purpose long autonomous objective",
                "проверь general purpose long autonomous objective",
                "проверь r10.8"
            )
    }

    private fun r10_8LongObjectiveSpecs(): List<AyanaLongObjectiveCoordinator.SubgoalSpec> =
        listOf(
            AyanaLongObjectiveCoordinator.SubgoalSpec(
                id = "device_state",
                title = "Verify factual device state",
                lane = AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                authority = AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
            ),
            AyanaLongObjectiveCoordinator.SubgoalSpec(
                id = "open_ayana",
                title = "Verify Android Goal execution",
                lane = AyanaCrossLaneAdaptiveContinuity.LANE_ANDROID_GOAL,
                authority = AyanaCrossLaneAdaptiveContinuity.AUTH_ANDROID_GOAL,
                dependencies = listOf("device_state")
            ),
            AyanaLongObjectiveCoordinator.SubgoalSpec(
                id = "open_example",
                title = "Open verified Browser source",
                lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP,
                dependencies = listOf("open_ayana")
            ),
            AyanaLongObjectiveCoordinator.SubgoalSpec(
                id = "read_title",
                title = "Extract verified page title",
                lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP,
                dependencies = listOf("open_example"),
                resultKey = "page_title"
            ),
            AyanaLongObjectiveCoordinator.SubgoalSpec(
                id = "youtube_search",
                title = "Consume verified title in YouTube",
                lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP,
                dependencies = listOf("read_title")
),
            AyanaLongObjectiveCoordinator.SubgoalSpec(
                id = "final_device_state",
                title = "Final factual verification after consumer",
                lane = AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                authority = AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE,
                dependencies = listOf("read_title", "youtube_search")
            )
        )

    private fun runR10_8GeneralPurposeLongObjectiveAcceptance(
        silent: Boolean
    ) {
        executionPhase(
            phase = "r10_8_general_purpose_long_objective_acceptance",
            executor = "long_objective_coordinator_v1"
        )

        stopSherpaListening()
        listenMode = ListenMode.BUSY

        broadcastStatus(
            "Проверяю длинную автономную цель…",
            STATE_EXECUTING
        )

        updateNotification(
            "AYANA проверяет R10.8 long autonomous objective…"
        )

        val commandToken = activeCommandToken
        val originalPage = currentAyanaPageKeyForAppIntegrationProbe()

        val worker =
            thread(
                start = false,
                name = "AyanaR10_8LongObjective"
            ) {
                val testFileName =
                    "ayana_durable_goals_r10_8_acceptance.json"

                var acceptanceStore: AyanaDurableGoalStore? = null
                var acceptanceGoalId: String? = null
                var finalRestore: JSONObject? = null

                try {
                    val longObjectiveSelfTest =
                        try {
                            AyanaLongObjectiveCoordinator.selfTest()
                        } catch (_: Exception) {
                            false
                        }

                    val recoverySelfTest =
                        try {
                            AyanaCrossLaneRecoveryContinuity.selfTest()
                        } catch (_: Exception) {
                            false
                        }

                    val continuitySelfTest =
                        try {
                            AyanaCrossLaneAdaptiveContinuity.selfTest()
                        } catch (_: Exception) {
                            false
                        }

                    val adaptiveSelfTest =
                        try {
                            AyanaAdaptiveExecutionLoop.selfTest()
                        } catch (_: Exception) {
                            false
                        }

                    val longRecoverySelfTest =
                        try {
                            longTaskRecoveryCoordinator.selfTest()
                        } catch (_: Exception) {
                            false
                        }

                    val isolatedStore =
                        AyanaDurableGoalStore(
                            context = applicationContext,
                            storageFileName = testFileName
                        )

                    isolatedStore.clearAcceptanceStorage()
                    acceptanceStore = isolatedStore

                    val objective =
                        "R10.8 acceptance: dependency-aware long objective preserves verified partial results across restart and resumes only unresolved subgoals"

                    val started =
                        isolatedStore.startGoal(
                            command = objective,
                            source = "r10_8_acceptance",
                            mode = AyanaDurableGoalStore.MODE_ORCHESTRATOR,
                            safeAutoResume = true
                        )

                    acceptanceGoalId =
                        started
                            .optString("id")
                            .trim()
                            .takeIf { it.isNotBlank() }

                    if (acceptanceGoalId == null) {
                        throw IllegalStateException(
                            "R10.8 isolated durable goal_id was not created"
                        )
                    }

                    val initialScreen =
                        try {
                            screenIntelligence.getScreenState()
                        } catch (_: Exception) {
                            JSONObject()
                        }

                    val initialState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            initialScreen.toString()
                        )

                    var adaptiveLoop =
                        AyanaAdaptiveExecutionLoop.create(
                            objective = objective,
                            stateFingerprint = initialState,
                            executionLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            authorityContext =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                        )

                    var continuity =
                        AyanaCrossLaneAdaptiveContinuity.create(
                            objective = objective,
                            adaptiveLoop = adaptiveLoop,
                            initialLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            initialAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE,
                            authorityCeiling =
                                AyanaCrossLaneAdaptiveContinuity.defaultUnifiedAuthorityCeiling()
                        )

                    var longObjective =
                        AyanaLongObjectiveCoordinator.create(
                            objectiveId = continuity.objectiveId(),
                            objective = objective,
                            specs = r10_8LongObjectiveSpecs()
                        )

                    val objectiveIdBefore = continuity.objectiveId()

                    val startPatch =
                        crossLaneRecoveryContinuity
                            .buildRecoveryCheckpoint(
                                adaptiveLoop = adaptiveLoop,
                                continuity = continuity,
                                checkpointTag = "r10_8_started",
                                safeAutoResume = true
                            )
                            .put(
                                "mode",
                                AyanaDurableGoalStore.MODE_ORCHESTRATOR
                            )
                            .put(
                                "long_objective_plan",
                                longObjective.snapshot()
                            )

                    val durableStartPersisted =
                        isolatedStore.checkpoint(
                            acceptanceGoalId,
                            startPatch
                        ) != null

                    if (!durableStartPersisted) {
                        throw IllegalStateException(
                            "R10.8 initial durable long-objective checkpoint was not persisted"
                        )
                    }

                    // Dependency preflight: consumer cannot start before producer.
                    val dependencyBlockProbe =
                        longObjective.beginSubgoal(
                            subgoalId = "youtube_search",
                            lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                            authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                        )

                    val dependencyGateBlocked =
                        !dependencyBlockProbe.optBoolean("allowed", true) &&
                            dependencyBlockProbe.optString("reason") ==
                            "dependency_not_verified"

                    var browserOpenDispatchCount = 0

                    // Subgoal 1: factual Agent Core/local device state.
                    val deviceSubgoalGate =
                        longObjective.beginSubgoal(
                            subgoalId = "device_state",
                            lane = AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            authority = AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                        )

                    val agentLaneGate =
                        continuity.transitionTo(
                            adaptiveLoop = adaptiveLoop,
                            targetLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            targetAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE,
                            stateFingerprint = initialState,
                            reason = "r10_8_device_state"
                        )

                    val deviceArgs = JSONObject()
                    val deviceProposal =
                        if (
                            deviceSubgoalGate.optBoolean("allowed", false) &&
                            agentLaneGate.optBoolean("allowed", false)
                        ) {
                            adaptiveLoop.propose(
                                toolName = "get_device_state",
                                arguments = deviceArgs,
                                stateFingerprint = initialState,
                                mayMutate = false,
                                authoritySource =
                                    AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                            )
                        } else {
                            JSONObject().put("allowed", false)
                        }

                    val deviceResult =
                        if (deviceProposal.optBoolean("allowed", false)) {
                            executeAgentTool(
                                name = "get_device_state",
                                arguments = JSONObject()
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                        }

                    val deviceVerified =
                        deviceResult.optBoolean("success", false) &&
                            deviceResult.optBoolean(
                                "verified",
                                deviceResult.optBoolean("success", false)
                            )

                    val deviceAfterState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            deviceResult.toString()
                        )

                    val deviceAdaptiveRecord =
                        adaptiveLoop.recordResult(
                            toolName = "get_device_state",
                            arguments = deviceArgs,
                            beforeStateFingerprint = initialState,
                            afterStateFingerprint = deviceAfterState,
                            success = deviceVerified,
                            verified = deviceVerified,
                            actionDispatched = false,
                            actionCommitted = false,
                            reconciliationComplete = true,
                            evidence = "R10.8 factual device state"
                        )

                    val deviceSubgoalRecord =
                        if (deviceVerified) {
                            longObjective.recordVerified(
                                subgoalId = "device_state",
                                lane = AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                                authority = AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE,
                                evidence = "device state verified"
                            )
                        } else {
                            longObjective.recordFailure(
                                "device_state",
                                "device_state_not_verified"
                            )
                        }

                    // Subgoal 2: real Android Goal with isolated durable checkpoints.
                    val androidSubgoalGate =
                        longObjective.beginSubgoal(
                            subgoalId = "open_ayana",
                            lane = AyanaCrossLaneAdaptiveContinuity.LANE_ANDROID_GOAL,
                            authority = AyanaCrossLaneAdaptiveContinuity.AUTH_ANDROID_GOAL
                        )

                    val androidLaneGate =
                        continuity.transitionTo(
                            adaptiveLoop = adaptiveLoop,
                            targetLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_ANDROID_GOAL,
                            targetAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_ANDROID_GOAL,
                            stateFingerprint = deviceAfterState,
                            reason = "r10_8_android_goal"
                        )

                    val androidArgs =
                        JSONObject()
                            .put("type", "open_app")
                            .put("app", "AYANA AI")
                            .put("max_actions", 2)

                    val androidProposal =
                        if (
                            androidSubgoalGate.optBoolean("allowed", false) &&
                            androidLaneGate.optBoolean("allowed", false)
                        ) {
                            adaptiveLoop.propose(
                                toolName = "execute_android_goal",
                                arguments = androidArgs,
                                stateFingerprint = deviceAfterState,
                                mayMutate = true,
                                authoritySource =
                                    AyanaCrossLaneAdaptiveContinuity.AUTH_ANDROID_GOAL
                            )
                        } else {
                            JSONObject().put("allowed", false)
                        }

                    val androidResult =
                        if (androidProposal.optBoolean("allowed", false)) {
                            executeAndroidGoal(
                                arguments = JSONObject(androidArgs.toString()),
                                checkpointStore = isolatedStore,
                                checkpointGoalId = acceptanceGoalId
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                        }

                    val androidVerified =
                        androidResult.optBoolean("success", false) &&
                            androidResult.optBoolean(
                                "verified",
                                androidResult.optBoolean("success", false)
                            )

                    val androidAfterState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            androidResult
                                .optJSONObject("screen")
                                ?.toString()
                                ?: androidResult.toString()
                        )

                    val androidAdaptiveRecord =
                        adaptiveLoop.recordResult(
                            toolName = "execute_android_goal",
                            arguments = androidArgs,
                            beforeStateFingerprint = deviceAfterState,
                            afterStateFingerprint = androidAfterState,
                            success = androidVerified,
                            verified = androidVerified,
                            actionDispatched =
                                androidResult.optBoolean(
                                    "action_dispatched",
                                    androidVerified
                                ),
                            actionCommitted = false,
                            reconciliationComplete = androidVerified,
                            evidence =
                                androidResult.optString(
                                    "message",
                                    "R10.8 Android Goal verification"
                                ),
                            failureLayer =
                                androidResult.optString("failure_layer")
                        )

                    val androidSubgoalRecord =
                        if (androidVerified) {
                            longObjective.recordVerified(
                                subgoalId = "open_ayana",
                                lane = AyanaCrossLaneAdaptiveContinuity.LANE_ANDROID_GOAL,
                                authority = AyanaCrossLaneAdaptiveContinuity.AUTH_ANDROID_GOAL,
                                evidence = "Android Goal verified"
                            )
                        } else {
                            longObjective.recordFailure(
                                "open_ayana",
                                "android_goal_not_verified"
                            )
                        }

                    // Subgoal 3: Browser source exactly once.
                    val browserSubgoalGate =
                        longObjective.beginSubgoal(
                            subgoalId = "open_example",
                            lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                            authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                        )

                    val multiLaneGate =
                        continuity.transitionTo(
                            adaptiveLoop = adaptiveLoop,
                            targetLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                            targetAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP,
                            stateFingerprint = androidAfterState,
                            reason = "r10_8_browser_source"
                        )

                    val browserArgs =
                        JSONObject()
                            .put(
                                "app_key",
                                AyanaAppIntegrationRegistry.APP_BROWSER
                            )
                            .put(
                                "action_key",
                                AyanaAppIntegrationRegistry.ACTION_OPEN_URL
                            )
                            .put(
                                "payload",
                                R9_7_STRUCTURED_ACCEPTANCE_URL
                            )

                    val browserProposal =
                        if (
                            browserSubgoalGate.optBoolean("allowed", false) &&
                            multiLaneGate.optBoolean("allowed", false)
                        ) {
                            adaptiveLoop.propose(
                                toolName = "app_integration:browser:open_url",
                                arguments = browserArgs,
                                stateFingerprint = androidAfterState,
                                mayMutate = false,
                                authoritySource =
                                    AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                            )
                        } else {
                            JSONObject().put("allowed", false)
                        }

                    val browserResult =
                        if (browserProposal.optBoolean("allowed", false)) {
                            browserOpenDispatchCount++
                            executeAppIntegrationAction(
                                appKey = AyanaAppIntegrationRegistry.APP_BROWSER,
                                actionKey = AyanaAppIntegrationRegistry.ACTION_OPEN_URL,
                                payload = R9_7_STRUCTURED_ACCEPTANCE_URL
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                                .put("action_dispatched", false)
                        }

                    val browserVerified =
                        browserResult.optBoolean("success", false) &&
                            browserResult.optBoolean("verified", false)

                    val browserState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            browserResult.toString()
                        )

                    val browserAdaptiveRecord =
                        adaptiveLoop.recordResult(
                            toolName = "app_integration:browser:open_url",
                            arguments = browserArgs,
                            beforeStateFingerprint = androidAfterState,
                            afterStateFingerprint = browserState,
                            success = browserVerified,
                            verified = browserVerified,
                            actionDispatched =
                                browserResult.optBoolean(
                                    "action_dispatched",
                                    false
                                ),
                            actionCommitted = false,
                            reconciliationComplete = browserVerified,
                            evidence =
                                browserResult.optString(
                                    "message",
                                    "R10.8 Browser source verification"
                                )
                        )

                    val browserSubgoalRecord =
                        if (browserVerified) {
                            longObjective.recordVerified(
                                subgoalId = "open_example",
                                lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                                authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP,
                                evidence = "Browser source verified"
                            )
                        } else {
                            longObjective.recordFailure(
                                "open_example",
                                "browser_not_verified"
                            )
                        }

                    val expectedBrowserPackage =
                        browserResult
                            .optString("observed_package")
                            .trim()
                            .ifBlank {
                                browserResult
                                    .optString("target_package")
                                    .trim()
                            }

                    // Subgoal 4: verified partial result producer.
                    val readSubgoalGate =
                        longObjective.beginSubgoal(
                            subgoalId = "read_title",
                            lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                            authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                        )

                    val visualArgs =
                        JSONObject()
                            .put(
                                "expected_package",
                                expectedBrowserPackage
                            )
                            .put(
                                "mode",
                                "package_bound_structured_visual"
                            )

                    val visualProposal =
                        if (readSubgoalGate.optBoolean("allowed", false)) {
                            adaptiveLoop.propose(
                                toolName =
                                    "screen_observe_package_bound_visual",
                                arguments = visualArgs,
                                stateFingerprint = browserState,
                                mayMutate = false,
                                authoritySource =
                                    AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                            )
                        } else {
                            JSONObject().put("allowed", false)
                        }

                    val visual =
                        if (
                            visualProposal.optBoolean("allowed", false) &&
                            expectedBrowserPackage.isNotBlank()
                        ) {
                            attemptVerifiedStructuredSemanticScreenRead(
                                expectedPackage = expectedBrowserPackage,
                                commandToken = commandToken
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                        }

                    val visualVerified =
                        visual.optBoolean("success", false) &&
                            visual.optBoolean("verified", false) &&
                            visual.optBoolean(
                                "semantic_structured_read_verified",
                                false
                            ) &&
                            visual.optString("semantic_title")
                                .trim()
                                .equals(
                                    R9_7_STRUCTURED_ACCEPTANCE_TITLE,
                                    ignoreCase = true
                                )

                    val visualAfterState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            visual.toString()
                        )

                    val visualAdaptiveRecord =
                        if (visualProposal.optBoolean("allowed", false)) {
                            adaptiveLoop.recordResult(
                                toolName =
                                    "screen_observe_package_bound_visual",
                                arguments = visualArgs,
                                beforeStateFingerprint = browserState,
                                afterStateFingerprint = visualAfterState,
                                success = visualVerified,
                                verified = visualVerified,
                                actionDispatched = false,
                                actionCommitted = false,
                                reconciliationComplete = true,
                                evidence =
                                    visual.optString(
                                        "reason",
                                        "R10.8 structured visual verification"
                                    ),
                                failureLayer =
                                    if (visualVerified) "" else "verification"
                            )
                        } else {
                            JSONObject()
                                .put("recorded", false)
                                .put("verified", false)
                        }

                    val transferredTitle =
                        visual.optString("semantic_title")
                            .trim()

                    val readSubgoalRecord =
                        if (visualVerified) {
                            longObjective.recordVerified(
                                subgoalId = "read_title",
                                lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                                authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP,
                                evidence = "verified structured page title",
                                resultValue = transferredTitle
                            )
                        } else {
                            longObjective.recordFailure(
                                "read_title",
                                "structured_title_not_verified"
                            )
                        }

                    val partialBeforeRestart =
                        longObjective.partialResult(
                            key = "page_title",
                            consumerSubgoalId = "youtube_search"
                        )

                    val partialResultVerifiedBeforeRestart =
                        partialBeforeRestart.optBoolean("verified", false) &&
                            partialBeforeRestart.optString("value") ==
                            R9_7_STRUCTURED_ACCEPTANCE_TITLE

                    val longSnapshotBeforeRestart = longObjective.snapshot()
                    val adaptiveVerifiedBeforeRestart =
                        adaptiveLoop.verifiedStepCount()
                    val transitionCountBeforeRestart =
                        continuity.laneTransitionCount()

                    val preInterruptPatch =
                        crossLaneRecoveryContinuity
                            .buildRecoveryCheckpoint(
                                adaptiveLoop = adaptiveLoop,
                                continuity = continuity,
                                checkpointTag =
                                    "r10_8_partial_result_verified_pre_interrupt",
                                safeAutoResume = true
                            )
                            .put(
                                "mode",
                                AyanaDurableGoalStore.MODE_ORCHESTRATOR
                            )
                            .put("status", AyanaDurableGoalStore.STATUS_ACTIVE)
                            .put(
                                "long_objective_plan",
                                longSnapshotBeforeRestart
                            )
                            .put(
                                "partial_result_page_title",
                                partialBeforeRestart
                            )

                    val durablePreInterruptPersisted =
                        isolatedStore.checkpoint(
                            acceptanceGoalId,
                            preInterruptPatch
                        ) != null

                    val interruptedCount =
                        if (durablePreInterruptPersisted) {
                            isolatedStore.markInterruptedGoals(
                                "service_destroyed"
                            )
                        } else {
                            0
                        }

                    // New store instance = restart boundary.
                    val restartedStore =
                        AyanaDurableGoalStore(
                            context = applicationContext,
                            storageFileName = testFileName
                        )
                    acceptanceStore = restartedStore

                    val restoredGoal =
                        restartedStore.getById(
                            acceptanceGoalId.orEmpty()
                        )

                    val recoveryDecision =
                        crossLaneRecoveryContinuity.evaluate(
                            goal = restoredGoal,
                            automatic = true
                        )

                    val automaticRecoveryAllowed =
                        recoveryDecision.optString("strategy") ==
                            AyanaCrossLaneRecoveryContinuity.Strategy
                                .RESTORE_AND_CONTINUE.name &&
                            recoveryDecision.optBoolean(
                                "automatic_resume_allowed",
                                false
                            )

                    val persistedAdaptiveSnapshot =
                        restoredGoal?.optJSONObject(
                            "adaptive_execution_loop"
                        )
                    val persistedContinuitySnapshot =
                        restoredGoal?.optJSONObject(
                            "cross_lane_continuity"
                        )
                    val persistedLongObjectiveSnapshot =
                        restoredGoal?.optJSONObject(
                            "long_objective_plan"
                        )

                    adaptiveLoop =
                        AyanaAdaptiveExecutionLoop.restore(
                            snapshot = persistedAdaptiveSnapshot,
                            fallbackObjective = objective,
                            fallbackExecutionLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            fallbackAuthorityContext =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                        )

                    continuity =
                        AyanaCrossLaneAdaptiveContinuity.restore(
                            snapshot = persistedContinuitySnapshot,
                            fallbackObjective = objective,
                            adaptiveLoop = adaptiveLoop,
                            fallbackAuthorityCeiling =
                                AyanaCrossLaneAdaptiveContinuity.defaultUnifiedAuthorityCeiling()
                        )

                    longObjective =
                        AyanaLongObjectiveCoordinator.restore(
                            persistedLongObjectiveSnapshot
                        )

                    val crossLaneRestore =
                        crossLaneRecoveryContinuity.verifyRestored(
                            persistedGoal = restoredGoal,
                            adaptiveLoop = adaptiveLoop,
                            continuity = continuity
                        )

                    val longObjectiveRestore =
                        longObjective.verifyRestoredAgainst(
                            persistedLongObjectiveSnapshot
                        )

                    val recoveryIncremented =
                        if (
                            automaticRecoveryAllowed &&
                            crossLaneRestore.optBoolean("verified", false) &&
                            longObjectiveRestore.optBoolean("verified", false)
                        ) {
                            restartedStore.incrementRecovery(
                                acceptanceGoalId
                            ) != null
                        } else {
                            false
                        }

                    val interruptionCheckpointPreserved =
                        restoredGoal?.optString(
                            "interrupted_from_checkpoint"
                        ) ==
                        "r10_8_partial_result_verified_pre_interrupt"

                    val restoredPartial =
                        longObjective.partialResult(
                            key = "page_title",
                            consumerSubgoalId = "youtube_search"
                        )

                    val partialResultPreserved =
                        restoredPartial.optBoolean("verified", false) &&
                            restoredPartial.optString("value") ==
                            R9_7_STRUCTURED_ACCEPTANCE_TITLE &&
                            restoredPartial.optString("producer_subgoal_id") ==
                            "read_title"

                    val restartStatePreserved =
                        interruptedCount == 1 &&
                            interruptionCheckpointPreserved &&
                            crossLaneRestore.optBoolean("verified", false) &&
                            longObjectiveRestore.optBoolean("verified", false) &&
                            continuity.objectiveId() == objectiveIdBefore &&
                            longObjective.objectiveId() == objectiveIdBefore &&
                            adaptiveLoop.verifiedStepCount() ==
                            adaptiveVerifiedBeforeRestart &&
                            continuity.laneTransitionCount() ==
                            transitionCountBeforeRestart &&
                            longObjective.verifiedSubgoalCount() == 4 &&
                            partialResultPreserved

                    // Already verified producer work must not replay after restart.
                    val browserSubgoalReplay =
                        longObjective.beginSubgoal(
                            subgoalId = "open_example",
                            lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                            authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                        )

                    val visualSubgoalReplay =
                        longObjective.beginSubgoal(
                            subgoalId = "read_title",
                            lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                            authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                        )

                    val verifiedSubgoalReplayBlocked =
                        browserSubgoalReplay.optString("reason") ==
                            "verified_subgoal_replay_blocked" &&
                            visualSubgoalReplay.optString("reason") ==
                            "verified_subgoal_replay_blocked"

                    val browserAdaptiveReplay =
                        adaptiveLoop.propose(
                            toolName = "app_integration:browser:open_url",
                            arguments = browserArgs,
                            stateFingerprint = androidAfterState,
                            mayMutate = false,
                            authoritySource =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                        )

                    val adaptiveBrowserReplayBlocked =
                        !browserAdaptiveReplay.optBoolean("allowed", true) &&
                            browserAdaptiveReplay.optString("reason") ==
                            "verified_transition_replay_blocked" &&
                            browserOpenDispatchCount == 1

                    // Subgoal 5 consumes the restored verified partial result.
                    val youtubeSubgoalGate =
                        longObjective.beginSubgoal(
                            subgoalId = "youtube_search",
                            lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                            authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                        )

                    val resumeMultiGate =
                        continuity.transitionTo(
                            adaptiveLoop = adaptiveLoop,
                            targetLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                            targetAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP,
                            stateFingerprint = visualAfterState,
                            reason = "r10_8_resume_consumer"
                        )

                    val restoredTitle =
                        restoredPartial.optString("value").trim()

                    val youtubeArgs =
                        JSONObject()
                            .put(
                                "app_key",
                                AyanaAppIntegrationRegistry.APP_YOUTUBE
                            )
                            .put(
                                "action_key",
                                AyanaAppIntegrationRegistry.ACTION_SEARCH
                            )
                            .put("payload", restoredTitle)

                    val youtubeProposal =
                        if (
                            youtubeSubgoalGate.optBoolean("allowed", false) &&
                            resumeMultiGate.optBoolean("allowed", false) &&
                            partialResultPreserved
                        ) {
                            adaptiveLoop.propose(
                                toolName = "app_integration:youtube:search",
                                arguments = youtubeArgs,
                                stateFingerprint = visualAfterState,
                                mayMutate = false,
                                authoritySource =
                                    AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                            )
                        } else {
                            JSONObject().put("allowed", false)
                        }

                    val youtubeResult =
                        if (youtubeProposal.optBoolean("allowed", false)) {
                            executeAppIntegrationAction(
                                appKey = AyanaAppIntegrationRegistry.APP_YOUTUBE,
                                actionKey = AyanaAppIntegrationRegistry.ACTION_SEARCH,
                                payload = restoredTitle
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                                .put("action_dispatched", false)
                        }

                    val youtubeVerified =
                        youtubeResult.optBoolean("success", false) &&
                            youtubeResult.optBoolean("verified", false)

                    val youtubeAfterState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            youtubeResult.toString()
                        )

                    val youtubeAdaptiveRecord =
                        if (youtubeProposal.optBoolean("allowed", false)) {
                            adaptiveLoop.recordResult(
                                toolName = "app_integration:youtube:search",
                                arguments = youtubeArgs,
                                beforeStateFingerprint = visualAfterState,
                                afterStateFingerprint = youtubeAfterState,
                                success = youtubeVerified,
                                verified = youtubeVerified,
                                actionDispatched =
                                    youtubeResult.optBoolean(
                                        "action_dispatched",
                                        false
                                    ),
                                actionCommitted = false,
                                reconciliationComplete = youtubeVerified,
                                evidence =
                                    youtubeResult.optString(
                                        "message",
                                        "R10.8 YouTube consumer verification"
                                    )
                            )
                        } else {
                            JSONObject()
                                .put("recorded", false)
                                .put("verified", false)
                        }

                    val youtubeSubgoalRecord =
                        if (youtubeVerified) {
                            longObjective.recordVerified(
                                subgoalId = "youtube_search",
                                lane = AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                                authority = AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP,
                                evidence = "YouTube consumed restored page_title"
                            )
                        } else {
                            longObjective.recordFailure(
                                "youtube_search",
                                "youtube_consumer_not_verified"
                            )
                        }

                    // Subgoal 6 has two dependencies and moves back to Agent Core.
                    val finalSubgoalGate =
                        longObjective.beginSubgoal(
                            subgoalId = "final_device_state",
                            lane = AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            authority = AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                        )

                    val finalAgentGate =
                        continuity.transitionTo(
                            adaptiveLoop = adaptiveLoop,
                            targetLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            targetAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE,
                            stateFingerprint = youtubeAfterState,
                            reason = "r10_8_final_agent_verification"
                        )

                    val finalArgs = JSONObject()
                    val finalProposal =
                        if (
                            finalSubgoalGate.optBoolean("allowed", false) &&
                            finalAgentGate.optBoolean("allowed", false)
                        ) {
                            adaptiveLoop.propose(
                                toolName = "get_device_state",
                                arguments = finalArgs,
                                stateFingerprint = youtubeAfterState,
                                mayMutate = false,
                                authoritySource =
AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                            )
                        } else {
                            JSONObject().put("allowed", false)
                        }

                    val finalDeviceResult =
                        if (finalProposal.optBoolean("allowed", false)) {
                            executeAgentTool(
                                name = "get_device_state",
                                arguments = JSONObject()
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                        }

                    val finalDeviceVerified =
                        finalDeviceResult.optBoolean("success", false) &&
                            finalDeviceResult.optBoolean(
                                "verified",
                                finalDeviceResult.optBoolean("success", false)
                            )

                    val finalAfterState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            finalDeviceResult.toString()
                        )

                    val finalAdaptiveRecord =
                        if (finalProposal.optBoolean("allowed", false)) {
                            adaptiveLoop.recordResult(
                                toolName = "get_device_state",
                                arguments = finalArgs,
                                beforeStateFingerprint = youtubeAfterState,
                                afterStateFingerprint = finalAfterState,
                                success = finalDeviceVerified,
                                verified = finalDeviceVerified,
                                actionDispatched = false,
                                actionCommitted = false,
                                reconciliationComplete = true,
                                evidence = "R10.8 final factual device state"
                            )
                        } else {
                            JSONObject()
                                .put("recorded", false)
                                .put("verified", false)
                        }

                    val finalSubgoalRecord =
                        if (finalDeviceVerified) {
                            longObjective.recordVerified(
                                subgoalId = "final_device_state",
                                lane = AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                                authority = AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE,
                                evidence = "final device state verified"
                            )
                        } else {
                            longObjective.recordFailure(
                                "final_device_state",
                                "final_device_state_not_verified"
                            )
                        }

                    finalRestore =
                        restoreAyanaAfterAppIntegrationProbe(
                            pageKey = originalPage,
                            stepKey = "r10-8-long-objective-final-restore"
                        )

                    val restoreVerified =
                        finalRestore?.optBoolean("verified", false) == true

                    val longObjectiveTerminalReady =
                        longObjective.canDeclareSuccess()

                    val adaptiveTerminal =
                        adaptiveLoop.markTerminal(
                            verified =
                                longObjectiveSelfTest &&
                                    recoverySelfTest &&
                                    continuitySelfTest &&
                                    adaptiveSelfTest &&
                                    longRecoverySelfTest &&
                                    dependencyGateBlocked &&
                                    restartStatePreserved &&
                                    recoveryIncremented &&
                                    verifiedSubgoalReplayBlocked &&
                                    adaptiveBrowserReplayBlocked &&
                                    youtubeAdaptiveRecord.optBoolean("verified", false) &&
                                    finalAdaptiveRecord.optBoolean("verified", false) &&
                                    longObjectiveTerminalReady &&
                                    restoreVerified &&
                                    !adaptiveLoop.hasUnresolvedSideEffect(),
                            evidence =
                                "dependency_gate=$dependencyGateBlocked; partial=$partialResultPreserved; restart=$restartStatePreserved; youtube=$youtubeVerified; final=$finalDeviceVerified; restore=$restoreVerified"
                        )

                    val finalPatch =
                        crossLaneRecoveryContinuity
                            .buildRecoveryCheckpoint(
                                adaptiveLoop = adaptiveLoop,
                                continuity = continuity,
                                checkpointTag =
                                    "r10_8_long_objective_terminal",
                                safeAutoResume = false
                            )
                            .put(
                                "mode",
                                AyanaDurableGoalStore.MODE_ORCHESTRATOR
                            )
                            .put(
                                "long_objective_plan",
                                longObjective.snapshot()
                            )
                            .put(
                                "terminal_verified",
                                adaptiveLoop.canDeclareSuccess() &&
                                    longObjectiveTerminalReady
                            )

                    val durableFinalPersisted =
                        restartedStore.checkpoint(
                            acceptanceGoalId,
                            finalPatch
                        ) != null

                    val coreAccepted =
                        longObjectiveSelfTest &&
                            recoverySelfTest &&
                            continuitySelfTest &&
                            adaptiveSelfTest &&
                            longRecoverySelfTest &&
                            durableStartPersisted &&
                            dependencyGateBlocked &&
                            deviceSubgoalGate.optBoolean("allowed", false) &&
                            deviceAdaptiveRecord.optBoolean("verified", false) &&
                            deviceSubgoalRecord.optBoolean("verified", false) &&
                            androidSubgoalGate.optBoolean("allowed", false) &&
                            androidAdaptiveRecord.optBoolean("verified", false) &&
                            androidSubgoalRecord.optBoolean("verified", false) &&
                            browserSubgoalGate.optBoolean("allowed", false) &&
                            browserAdaptiveRecord.optBoolean("verified", false) &&
                            browserSubgoalRecord.optBoolean("verified", false) &&
                            browserOpenDispatchCount == 1 &&
                            readSubgoalGate.optBoolean("allowed", false) &&
                            visualAdaptiveRecord.optBoolean("verified", false) &&
                            readSubgoalRecord.optBoolean("verified", false) &&
                            partialResultVerifiedBeforeRestart &&
                            durablePreInterruptPersisted &&
                            interruptedCount == 1 &&
                            automaticRecoveryAllowed &&
                            recoveryIncremented &&
                            restartStatePreserved &&
                            partialResultPreserved &&
                            verifiedSubgoalReplayBlocked &&
                            adaptiveBrowserReplayBlocked &&
                            browserOpenDispatchCount == 1 &&
                            youtubeSubgoalGate.optBoolean("allowed", false) &&
                            youtubeAdaptiveRecord.optBoolean("verified", false) &&
                            youtubeSubgoalRecord.optBoolean("verified", false) &&
                            finalSubgoalGate.optBoolean("allowed", false) &&
                            finalAdaptiveRecord.optBoolean("verified", false) &&
                            finalSubgoalRecord.optBoolean("verified", false) &&
                            longObjective.verifiedSubgoalCount() == 6 &&
                            longObjective.partialResultCount() == 1 &&
                            longObjectiveTerminalReady &&
                            adaptiveTerminal.optBoolean("allowed", false) &&
                            adaptiveLoop.canDeclareSuccess() &&
                            continuity.objectiveId() == objectiveIdBefore &&
                            longObjective.objectiveId() == objectiveIdBefore &&
                            !adaptiveLoop.hasUnresolvedSideEffect() &&
                            durableFinalPersisted &&
                            restoreVerified

                    if (coreAccepted) {
                        restartedStore.markCompleted(
                            acceptanceGoalId,
                            "R10.8 general-purpose long autonomous objective verified"
                        )
                    } else {
                        restartedStore.markFailed(
                            acceptanceGoalId,
                            "R10.8 long-objective acceptance failed verification"
                        )
                    }

                    val cleanupVerified =
                        try {
                            restartedStore.clearAcceptanceStorage()
                        } catch (_: Exception) {
                            false
                        }

                    val accepted = coreAccepted && cleanupVerified

                    val evidence =
                        JSONObject()
                            .put(
                                "long_objective_coordinator_version",
                                AyanaLongObjectiveCoordinator.VERSION
                            )
                            .put(
                                "cross_lane_recovery_version",
                                AyanaCrossLaneRecoveryContinuity.VERSION
                            )
                            .put(
                                "cross_lane_continuity_version",
                                AyanaCrossLaneAdaptiveContinuity.VERSION
                            )
                            .put(
                                "adaptive_loop_version",
                                AyanaAdaptiveExecutionLoop.VERSION
                            )
                            .put("objective_id", objectiveIdBefore)
                            .put(
                                "objective_id_preserved_after_restart",
                                continuity.objectiveId() == objectiveIdBefore &&
                                    longObjective.objectiveId() == objectiveIdBefore
                            )
                            .put("subgoal_count", longObjective.subgoalCount())
                            .put(
                                "required_subgoal_count",
                                longObjective.requiredSubgoalCount()
                            )
                            .put(
                                "verified_subgoal_count",
                                longObjective.verifiedSubgoalCount()
                            )
                            .put(
                                "dependency_gate_blocked_early_consumer",
                                dependencyGateBlocked
                            )
                            .put(
                                "partial_result_verified_before_restart",
                                partialResultVerifiedBeforeRestart
                            )
                            .put(
                                "partial_result_preserved_after_restart",
                                partialResultPreserved
                            )
                            .put(
                                "partial_result_value",
                                restoredPartial.optString("value")
                            )
                            .put(
                                "partial_result_provenance_verified",
                                longObjectiveRestore.optBoolean(
                                    "partial_result_provenance_verified",
                                    false
                                )
                            )
                            .put("interrupted_goal_count", interruptedCount)
                            .put(
                                "interruption_checkpoint_preserved",
                                interruptionCheckpointPreserved
                            )
                            .put(
                                "recovery_strategy",
                                recoveryDecision.optString("strategy")
                            )
                            .put(
                                "automatic_recovery_allowed",
                                automaticRecoveryAllowed
                            )
                            .put(
                                "cross_lane_restore_verified",
                                crossLaneRestore.optBoolean("verified", false)
                            )
                            .put(
                                "long_objective_restore_verified",
                                longObjectiveRestore.optBoolean("verified", false)
                            )
                            .put(
                                "recovery_count_incremented",
                                recoveryIncremented
                            )
                            .put(
                                "verified_subgoal_replay_blocked_after_restart",
                                verifiedSubgoalReplayBlocked
                            )
                            .put(
                                "verified_browser_replay_blocked_after_restart",
                                adaptiveBrowserReplayBlocked
                            )
                            .put(
                                "browser_open_dispatch_count",
                                browserOpenDispatchCount
                            )
                            .put("browser_open_replayed", false)
                            .put("agent_core_step_verified", deviceVerified)
                            .put("android_goal_step_verified", androidVerified)
                            .put("browser_step_verified", browserVerified)
                            .put("structured_visual_verified", visualVerified)
                            .put("youtube_consumer_verified", youtubeVerified)
                            .put(
                                "final_agent_verification_verified",
                                finalDeviceVerified
                            )
                            .put(
                                "durable_start_snapshot_persisted",
                                durableStartPersisted
                            )
                            .put(
                                "durable_partial_result_snapshot_persisted",
                                durablePreInterruptPersisted
                            )
                            .put(
                                "durable_final_checkpoint_persisted",
                                durableFinalPersisted
                            )
                            .put(
                                "isolated_acceptance_storage_cleanup_verified",
                                cleanupVerified
                            )
                            .put(
                                "production_durable_goal_store_touched",
                                false
                            )
                            .put(
                                "long_objective_terminal_ready",
                                longObjectiveTerminalReady
                            )
                            .put(
                                "unresolved_side_effect",
                                adaptiveLoop.hasUnresolvedSideEffect()
                            )
                            .put(
                                "terminal_verified",
                                adaptiveLoop.canDeclareSuccess() &&
                                    longObjectiveTerminalReady
                            )
                            .put("restore_verified", restoreVerified)
                            .put("mutation_committed_detected", false)
                            .put("blind_replay_allowed", false)
                            .put("persistent_user_data_mutation", false)
                            .put("worker_visual_turns", if (visualVerified) 1 else 0)
                            .put("agent_core_model_turns", 0)
                            .put("acceptance_ok", accepted)
                            .put(
                                "long_objective_summary",
                                longObjective.compactSummary()
                            )
                            .put(
                                "continuity_summary",
                                continuity.compactSummary(adaptiveLoop)
                            )
                            .put(
                                "voice_service_release",
                                AYANA_VOICE_SERVICE_RELEASE
                            )
                            .put(
                                "accepted_checkpoint",
                                AYANA_ACCEPTED_FEATURE_CHECKPOINT
                            )
                            .put(
                                "current_release",
                                AYANA_CURRENT_FEATURE_RELEASE
                            )

                    mainHandler.post {
                        if (
                            isCommandCancelled(commandToken) ||
                            commandToken != activeCommandToken
                        ) {
                            return@post
                        }

                        if (!accepted) {
                            commandHistoryStore.addEvent(
                                activeCommandHistoryId,
                                state =
                                    "r10_8_general_purpose_long_objective_not_verified",
                                message =
                                    "R10.8 long autonomous objective не прошёл dependency/partial-result/recovery/terminal gates",
                                details = evidence.toString().take(3900)
                            )

                            respondAndResume(
                                text =
                                    "R10.8 выполнен fail-closed: длинная автономная цель не подтверждена по всем обязательным gates.",
                                silent = silent,
                                success = false,
                                technical = evidence.toString()
                            )
                            return@post
                        }

                        commandHistoryStore.addEvent(
                            activeCommandHistoryId,
                            state =
                                "r10_8_general_purpose_long_objective_verified",
                            message =
                                "R10.8 подтверждён: dependency-aware objective сохранил verified partial result через restart и продолжил только незавершённые subgoals",
                            details = evidence.toString().take(3900)
                        )

                        respondAndResume(
                            text =
                                "R10.8 General-Purpose Long Autonomous Objective подтверждён: одна dependency-aware цель выполнила 6 subgoals через Agent Core → Android Goal → Multi-App, сохранила verified partial result через restart и продолжила только оставшиеся шаги без replay Browser/visual.",
                            silent = silent,
                            success = true,
                            technical = evidence.toString()
                        )
                    }
                } catch (error: Exception) {
                    try {
                        acceptanceStore?.markFailed(
                            acceptanceGoalId,
                            "R10.8 acceptance exception: ${error.message ?: error.javaClass.simpleName}"
                        )
                    } catch (_: Exception) {
                    }

                    try {
                        finalRestore =
                            restoreAyanaAfterAppIntegrationProbe(
                                pageKey = originalPage,
                                stepKey = "r10-8-long-objective-error-restore"
                            )
                    } catch (_: Exception) {
                    }

                    val evidence =
                        JSONObject()
                            .put(
                                "long_objective_coordinator_version",
                                AyanaLongObjectiveCoordinator.VERSION
                            )
                            .put("acceptance_ok", false)
                            .put(
                                "exception",
                                (error.message ?: error.javaClass.simpleName)
                                    .take(600)
                            )
                            .put(
                                "restore_verified",
                                finalRestore?.optBoolean("verified", false) == true
                            )
                            .put("blind_replay_allowed", false)
                            .put("persistent_user_data_mutation", false)

                    mainHandler.post {
                        if (
                            commandToken == activeCommandToken &&
                            !shuttingDown
                        ) {
                            commandHistoryStore.addEvent(
                                activeCommandHistoryId,
                                state =
                                    "r10_8_general_purpose_long_objective_not_verified",
                                message = "R10.8 acceptance exception",
                                details = evidence.toString().take(2500)
                            )

                            respondAndResume(
                                text =
                                    "R10.8 long autonomous objective не подтверждён: acceptance завершился fail-closed.",
                                silent = silent,
                                success = false,
                                technical = evidence.toString()
                            )
                        }
                    }
                } finally {
                    if (
                        finalRestore == null ||
                        finalRestore?.optBoolean("verified", false) != true
                    ) {
                        try {
                            restoreAyanaAfterAppIntegrationProbe(
                                pageKey = originalPage,
                                stepKey = "r10-8-long-objective-finally-restore"
                            )
                        } catch (_: Exception) {
                        }
                    }

                    try {
                        acceptanceStore?.clearAcceptanceStorage()
                    } catch (_: Exception) {
                    }

                    if (Thread.currentThread() === currentAgentThread) {
                        currentAgentThread = null
                    }
                }
            }

        currentAgentThread = worker
        executionKernel.bindThread(worker)
        worker.start()
    }

    private fun isR10_7CrossLaneDurableRecoveryAcceptanceCommand(
        command: String
    ): Boolean {
        val normalized =
            command
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()
                .removePrefix("аяна ")
                .trim()

        return normalized in
            setOf(
                "проверь восстановление длинной межконтурной задачи",
                "проверь восстановление межконтурной задачи",
                "проверь межконтурное восстановление",
                "проверь cross-lane durable recovery",
                "проверь cross lane durable recovery",
                "проверь r10.7"
            )
    }

    private fun runR10_7CrossLaneDurableRecoveryAcceptance(
        silent: Boolean
    ) {
        executionPhase(
            phase = "r10_7_cross_lane_durable_recovery_acceptance",
            executor = "cross_lane_recovery_continuity_v1"
        )

        stopSherpaListening()
        listenMode = ListenMode.BUSY

        broadcastStatus(
            "Проверяю восстановление длинной межконтурной задачи…",
            STATE_EXECUTING
        )

        updateNotification(
            "AYANA проверяет R10.7 cross-lane durable recovery…"
        )

        val commandToken = activeCommandToken
        val originalPage = currentAyanaPageKeyForAppIntegrationProbe()

        val worker =
            thread(
                start = false,
                name = "AyanaR10_7CrossLaneDurableRecovery"
            ) {
                val testFileName =
                    "ayana_durable_goals_r10_7_acceptance.json"

                var acceptanceStore: AyanaDurableGoalStore? = null
                var acceptanceGoalId: String? = null
                var finalRestore: JSONObject? = null
                var cleanupVerified = false

                try {
                    val recoverySelfTest =
                        try {
                            AyanaCrossLaneRecoveryContinuity.selfTest()
                        } catch (_: Exception) {
                            false
                        }

                    val continuitySelfTest =
                        try {
                            AyanaCrossLaneAdaptiveContinuity.selfTest()
                        } catch (_: Exception) {
                            false
                        }

                    val adaptiveSelfTest =
                        try {
                            AyanaAdaptiveExecutionLoop.selfTest()
                        } catch (_: Exception) {
                            false
                        }

                    val longRecoverySelfTest =
                        try {
                            longTaskRecoveryCoordinator.selfTest()
                        } catch (_: Exception) {
                            false
                        }

                    val isolatedStore =
                        AyanaDurableGoalStore(
                            context = applicationContext,
                            storageFileName = testFileName
                        )

                    isolatedStore.clearAcceptanceStorage()
                    acceptanceStore = isolatedStore

                    val objective =
                        "R10.7 acceptance: one long objective crosses Agent Core, Android Goal and Multi-App, survives interruption and continues without replay"

                    val started =
                        isolatedStore.startGoal(
                            command = objective,
                            source = "r10_7_acceptance",
                            mode = AyanaDurableGoalStore.MODE_ORCHESTRATOR,
                            safeAutoResume = true
                        )

                    acceptanceGoalId =
                        started
                            .optString("id")
                            .trim()
                            .takeIf { it.isNotBlank() }

                    if (acceptanceGoalId == null) {
                        throw IllegalStateException(
                            "R10.7 isolated durable goal_id was not created"
                        )
                    }

                    val initialScreen =
                        try {
                            screenIntelligence.getScreenState()
                        } catch (_: Exception) {
                            JSONObject()
                        }

                    val initialState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            initialScreen.toString()
                        )

                    var adaptiveLoop =
                        AyanaAdaptiveExecutionLoop.create(
                            objective = objective,
                            stateFingerprint = initialState,
                            executionLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            authorityContext =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                        )

                    var continuity =
                        AyanaCrossLaneAdaptiveContinuity.create(
                            objective = objective,
                            adaptiveLoop = adaptiveLoop,
                            initialLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            initialAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE,
                            authorityCeiling =
                                AyanaCrossLaneAdaptiveContinuity.defaultUnifiedAuthorityCeiling()
                        )

                    val objectiveIdBefore = continuity.objectiveId()

                    val startCheckpoint =
                        crossLaneRecoveryContinuity
                            .buildRecoveryCheckpoint(
                                adaptiveLoop = adaptiveLoop,
                                continuity = continuity,
                                checkpointTag = "r10_7_started",
                                safeAutoResume = true
                            )
                            .put(
                                "mode",
                                AyanaDurableGoalStore.MODE_ORCHESTRATOR
                            )

                    val durableStartPersisted =
                        isolatedStore.checkpoint(
                            acceptanceGoalId,
                            startCheckpoint
                        ) != null

                    if (!durableStartPersisted) {
                        throw IllegalStateException(
                            "R10.7 initial durable cross-lane checkpoint was not persisted"
                        )
                    }

                    var browserOpenDispatchCount = 0

                    // 1) Agent Core read-only factual step.
                    val agentArgs = JSONObject()
                    val agentGate =
                        continuity.transitionTo(
                            adaptiveLoop = adaptiveLoop,
                            targetLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            targetAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE,
                            stateFingerprint = initialState,
                            reason = "r10_7_agent_core_start"
                        )

                    val agentProposal =
                        if (agentGate.optBoolean("allowed", false)) {
                            adaptiveLoop.propose(
                                toolName = "get_device_state",
                                arguments = agentArgs,
                                stateFingerprint = initialState,
                                mayMutate = false,
                                authoritySource =
                                    AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                            )
                        } else {
                            JSONObject(agentGate.toString())
                                .put("allowed", false)
                        }

                    val agentResult =
                        if (agentProposal.optBoolean("allowed", false)) {
                            executeAgentTool(
                                name = "get_device_state",
                                arguments = JSONObject()
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                                .put("reason", "agent_core_gate_blocked")
                        }

                    val agentVerified =
                        agentResult.optBoolean("success", false) &&
                            agentResult.optBoolean(
                                "verified",
                                agentResult.optBoolean("success", false)
                            )

                    val agentAfterState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            agentResult.toString()
                        )

                    val agentRecord =
                        adaptiveLoop.recordResult(
                            toolName = "get_device_state",
                            arguments = agentArgs,
                            beforeStateFingerprint = initialState,
                            afterStateFingerprint = agentAfterState,
                            success = agentVerified,
                            verified = agentVerified,
                            actionDispatched = false,
                            actionCommitted = false,
                            reconciliationComplete = true,
                            evidence = "R10.7 factual device state"
                        )

                    // 2) Android Goal real Task Engine step using the same isolated durable goal.
                    val androidGate =
                        continuity.transitionTo(
                            adaptiveLoop = adaptiveLoop,
                            targetLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_ANDROID_GOAL,
                            targetAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_ANDROID_GOAL,
                            stateFingerprint = agentAfterState,
                            reason = "r10_7_android_goal_handoff"
                        )

                    val androidArgs =
                        JSONObject()
                            .put("type", "open_app")
                            .put("app", "AYANA AI")
                            .put("max_actions", 2)

                    val androidProposal =
                        if (androidGate.optBoolean("allowed", false)) {
                            adaptiveLoop.propose(
                                toolName = "execute_android_goal",
                                arguments = androidArgs,
                                stateFingerprint = agentAfterState,
                                mayMutate = true,
                                authoritySource =
                                    AyanaCrossLaneAdaptiveContinuity.AUTH_ANDROID_GOAL
                            )
                        } else {
                            JSONObject(androidGate.toString())
                                .put("allowed", false)
                        }

                    val androidResult =
                        if (androidProposal.optBoolean("allowed", false)) {
                            executeAndroidGoal(
                                arguments = JSONObject(androidArgs.toString()),
                                checkpointStore = isolatedStore,
                                checkpointGoalId = acceptanceGoalId
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                                .put("reason", "android_goal_gate_blocked")
                        }

                    val androidVerified =
                        androidResult.optBoolean("success", false) &&
                            androidResult.optBoolean(
                                "verified",
                                androidResult.optBoolean("success", false)
                            )

                    val androidAfterState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            androidResult
                                .optJSONObject("screen")
                                ?.toString()
                                ?: androidResult.toString()
                        )

                    val androidRecord =
                        adaptiveLoop.recordResult(
                            toolName = "execute_android_goal",
                            arguments = androidArgs,
                            beforeStateFingerprint = agentAfterState,
                            afterStateFingerprint = androidAfterState,
                            success = androidVerified,
                            verified = androidVerified,
                            actionDispatched =
                                androidResult.optBoolean(
                                    "action_dispatched",
                                    androidVerified
                                ),
                            actionCommitted = false,
                            reconciliationComplete = androidVerified,
                            evidence =
                                androidResult.optString(
                                    "message",
                                    "R10.7 Android Goal verification"
                                ),
                            failureLayer =
                                androidResult.optString("failure_layer")
                        )

                    // 3) Multi-App Browser dispatch exactly once.
                    val multiGate =
                        continuity.transitionTo(
                            adaptiveLoop = adaptiveLoop,
                            targetLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                            targetAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP,
                            stateFingerprint = androidAfterState,
                            reason = "r10_7_multi_app_handoff"
                        )

                    val browserArgs =
                        JSONObject()
                            .put(
                                "app_key",
                                AyanaAppIntegrationRegistry.APP_BROWSER
                            )
                            .put(
                                "action_key",
                                AyanaAppIntegrationRegistry.ACTION_OPEN_URL
                            )
                            .put(
                                "payload",
                                R9_7_STRUCTURED_ACCEPTANCE_URL
                            )

                    val browserProposal =
                        if (multiGate.optBoolean("allowed", false)) {
                            adaptiveLoop.propose(
                                toolName = "app_integration:browser:open_url",
                                arguments = browserArgs,
                                stateFingerprint = androidAfterState,
                                mayMutate = false,
                                authoritySource =
                                    AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                            )
                        } else {
                            JSONObject(multiGate.toString())
                                .put("allowed", false)
                        }

                    val browserResult =
                        if (browserProposal.optBoolean("allowed", false)) {
                            browserOpenDispatchCount++
                            executeAppIntegrationAction(
                                appKey = AyanaAppIntegrationRegistry.APP_BROWSER,
                                actionKey = AyanaAppIntegrationRegistry.ACTION_OPEN_URL,
                                payload = R9_7_STRUCTURED_ACCEPTANCE_URL
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                                .put("action_dispatched", false)
                                .put("reason", "browser_gate_blocked")
                        }

                    val browserVerified =
                        browserResult.optBoolean("success", false) &&
                            browserResult.optBoolean("verified", false)

                    val browserState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            browserResult.toString()
                        )

                    val browserRecord =
                        adaptiveLoop.recordResult(
                            toolName = "app_integration:browser:open_url",
                            arguments = browserArgs,
                            beforeStateFingerprint = androidAfterState,
                            afterStateFingerprint = browserState,
                            success = browserVerified,
                            verified = browserVerified,
                            actionDispatched =
                                browserResult.optBoolean(
                                    "action_dispatched",
                                    false
                                ),
                            actionCommitted = false,
                            reconciliationComplete = browserVerified,
                            evidence =
                                browserResult.optString(
                                    "message",
                                    "R10.7 Browser open verification"
                                )
                        )

                    val expectedBrowserPackage =
                        browserResult
                            .optString("observed_package")
                            .trim()
                            .ifBlank {
                                browserResult
                                    .optString("target_package")
                                    .trim()
                            }

                    // 4) Record one safe failed read transition and revision before interruption.
                    val observationArgs =
                        JSONObject()
                            .put(
                                "expected_package",
                                expectedBrowserPackage
                            )
                            .put(
                                "marker",
                                R9_7_STRUCTURED_ACCEPTANCE_TITLE
                            )
                            .put("mode", "accessibility_primary")

                    val failedReadProposal =
                        adaptiveLoop.propose(
                            toolName = "screen_observe_accessibility",
                            arguments = observationArgs,
                            stateFingerprint = browserState,
                            mayMutate = false,
                            authoritySource =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                        )

                    val failedReadRecord =
                        if (failedReadProposal.optBoolean("allowed", false)) {
                            adaptiveLoop.recordResult(
                                toolName = "screen_observe_accessibility",
                                arguments = observationArgs,
                                beforeStateFingerprint = browserState,
                                afterStateFingerprint = browserState,
                                success = false,
                                verified = false,
                                actionDispatched = false,
                                actionCommitted = false,
                                reconciliationComplete = true,
                                evidence =
                                    "R10.7 bounded read-only miss before interruption",
                                failureLayer = "verification",
                                replanRecommended = true
                            )
                        } else {
                            JSONObject()
                                .put("recorded", false)
                                .put("replan_recommended", false)
                        }

                    val replan =
                        adaptiveLoop.beginReplan(
                            reason =
                                "R10.7 persist revised suffix before interruption",
                            stateFingerprint = browserState
                        )

                    val revisionBeforeInterruption =
                        adaptiveLoop.currentRevision()
                    val verifiedPrefixBeforeInterruption =
                        adaptiveLoop.verifiedStepCount()
                    val failedBeforeInterruption =
                        adaptiveLoop.failedTransitionCount()
                    val transitionsBeforeInterruption =
                        continuity.laneTransitionCount()

                    val preInterruptPatch =
                        crossLaneRecoveryContinuity
                            .buildRecoveryCheckpoint(
                                adaptiveLoop = adaptiveLoop,
                                continuity = continuity,
                                checkpointTag =
                                    "r10_7_browser_verified_pre_interrupt",
                                safeAutoResume = true
)
                            .put(
                                "mode",
                                AyanaDurableGoalStore.MODE_ORCHESTRATOR
                            )
                            .put("status", AyanaDurableGoalStore.STATUS_ACTIVE)

                    val preInterruptPersisted =
                        isolatedStore.checkpoint(
                            acceptanceGoalId,
                            preInterruptPatch
                        ) != null

                    val interruptedCount =
                        if (preInterruptPersisted) {
                            isolatedStore.markInterruptedGoals(
                                "service_destroyed"
                            )
                        } else {
                            0
                        }

                    // 5) New store instance = process/service-style persistence boundary.
                    val restartedStore =
                        AyanaDurableGoalStore(
                            context = applicationContext,
                            storageFileName = testFileName
                        )
                    acceptanceStore = restartedStore

                    val restoredGoal =
                        restartedStore.getById(
                            acceptanceGoalId.orEmpty()
                        )

                    val recoveryDecision =
                        crossLaneRecoveryContinuity.evaluate(
                            goal = restoredGoal,
                            automatic = true
                        )

                    val automaticRecoveryAllowed =
                        recoveryDecision.optString("strategy") ==
                            AyanaCrossLaneRecoveryContinuity.Strategy
                                .RESTORE_AND_CONTINUE.name &&
                            recoveryDecision.optBoolean(
                                "automatic_resume_allowed",
                                false
                            )

                    val restoredAdaptiveSnapshot =
                        restoredGoal
                            ?.optJSONObject("adaptive_execution_loop")

                    val restoredContinuitySnapshot =
                        restoredGoal
                            ?.optJSONObject("cross_lane_continuity")

                    adaptiveLoop =
                        AyanaAdaptiveExecutionLoop.restore(
                            snapshot = restoredAdaptiveSnapshot,
                            fallbackObjective = objective,
                            fallbackExecutionLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            fallbackAuthorityContext =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                        )

                    continuity =
                        AyanaCrossLaneAdaptiveContinuity.restore(
                            snapshot = restoredContinuitySnapshot,
                            fallbackObjective = objective,
                            adaptiveLoop = adaptiveLoop,
                            fallbackAuthorityCeiling =
                                AyanaCrossLaneAdaptiveContinuity.defaultUnifiedAuthorityCeiling()
                        )

                    val exactRestore =
                        crossLaneRecoveryContinuity.verifyRestored(
                            persistedGoal = restoredGoal,
                            adaptiveLoop = adaptiveLoop,
                            continuity = continuity
                        )

                    val recoveryIncremented =
                        if (
                            automaticRecoveryAllowed &&
                            exactRestore.optBoolean("verified", false)
                        ) {
                            restartedStore.incrementRecovery(
                                acceptanceGoalId
                            ) != null
                        } else {
                            false
                        }

                    val interruptionCheckpointPreserved =
                        restoredGoal
                            ?.optString("interrupted_from_checkpoint") ==
                            "r10_7_browser_verified_pre_interrupt"

                    val restartStatePreserved =
                        interruptedCount == 1 &&
                            interruptionCheckpointPreserved &&
                            exactRestore.optBoolean("verified", false) &&
                            continuity.objectiveId() == objectiveIdBefore &&
                            adaptiveLoop.currentRevision() ==
                            revisionBeforeInterruption &&
                            adaptiveLoop.verifiedStepCount() ==
                            verifiedPrefixBeforeInterruption &&
                            adaptiveLoop.failedTransitionCount() ==
                            failedBeforeInterruption &&
                            continuity.laneTransitionCount() ==
                            transitionsBeforeInterruption

                    // Verified Browser action must remain blocked after restart.
                    val browserReplayProbe =
                        adaptiveLoop.propose(
                            toolName = "app_integration:browser:open_url",
                            arguments = browserArgs,
                            stateFingerprint = androidAfterState,
                            mayMutate = false,
                            authoritySource =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                        )

                    val verifiedBrowserReplayBlocked =
                        !browserReplayProbe.optBoolean("allowed", true) &&
                            browserReplayProbe.optString("reason") ==
                            "verified_transition_replay_blocked" &&
                            browserOpenDispatchCount == 1

                    // Switch lane after restart; failed read must remain blocked too.
                    val postRestartAgentGate =
                        continuity.transitionTo(
                            adaptiveLoop = adaptiveLoop,
                            targetLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            targetAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE,
                            stateFingerprint = browserState,
                            reason = "r10_7_post_restart_failed_transition_probe"
                        )

                    val failedReadReplayProbe =
                        if (postRestartAgentGate.optBoolean("allowed", false)) {
                            adaptiveLoop.propose(
                                toolName = "screen_observe_accessibility",
                                arguments = observationArgs,
                                stateFingerprint = browserState,
                                mayMutate = false,
                                authoritySource =
                                    AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                            )
                        } else {
                            JSONObject(postRestartAgentGate.toString())
                                .put("allowed", false)
                        }

                    val failedTransitionReplayBlockedAfterRestart =
                        !failedReadReplayProbe.optBoolean("allowed", true) &&
                            failedReadReplayProbe.optString("reason") ==
                            "failed_transition_replay_blocked"

                    val backToMulti =
                        continuity.transitionTo(
                            adaptiveLoop = adaptiveLoop,
                            targetLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                            targetAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP,
                            stateFingerprint = browserState,
                            reason = "r10_7_resume_verified_suffix"
                        )

                    // 6) Continue only the unverified suffix from the existing Browser state.
                    val visual =
                        if (
                            restartStatePreserved &&
                            recoveryIncremented &&
                            backToMulti.optBoolean("allowed", false) &&
                            expectedBrowserPackage.isNotBlank()
                        ) {
                            attemptVerifiedStructuredSemanticScreenRead(
                                expectedPackage = expectedBrowserPackage,
                                commandToken = commandToken
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                                .put("reason", "recovery_state_not_verified")
                        }

                    val visualVerified =
                        visual.optBoolean("success", false) &&
                            visual.optBoolean("verified", false) &&
                            visual.optBoolean(
                                "semantic_structured_read_verified",
                                false
                            ) &&
                            visual.optString("semantic_title")
                                .trim()
                                .equals(
                                    R9_7_STRUCTURED_ACCEPTANCE_TITLE,
                                    ignoreCase = true
                                )

                    val visualArgs =
                        JSONObject()
                            .put(
                                "expected_package",
                                expectedBrowserPackage
                            )
                            .put(
                                "mode",
                                "package_bound_structured_visual"
                            )

                    val visualProposal =
                        adaptiveLoop.propose(
                            toolName =
                                "screen_observe_package_bound_visual",
                            arguments = visualArgs,
                            stateFingerprint = browserState,
                            mayMutate = false,
                            authoritySource =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                        )

                    val visualAfterState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            visual.toString()
                        )

                    val visualRecord =
                        if (visualProposal.optBoolean("allowed", false)) {
                            adaptiveLoop.recordResult(
                                toolName =
                                    "screen_observe_package_bound_visual",
                                arguments = visualArgs,
                                beforeStateFingerprint = browserState,
                                afterStateFingerprint = visualAfterState,
                                success = visualVerified,
                                verified = visualVerified,
                                actionDispatched = false,
                                actionCommitted = false,
                                reconciliationComplete = true,
                                evidence =
                                    visual.optString(
                                        "reason",
                                        "R10.7 post-restart visual verification"
                                    ),
                                failureLayer =
                                    if (visualVerified) "" else "verification"
                            )
                        } else {
                            JSONObject()
                                .put("recorded", false)
                                .put("verified", false)
                        }

                    val transferredTitle =
                        visual.optString("semantic_title")
                            .trim()
                            .ifBlank {
                                R9_7_STRUCTURED_ACCEPTANCE_TITLE
                            }

                    val youtubeArgs =
                        JSONObject()
                            .put(
                                "app_key",
                                AyanaAppIntegrationRegistry.APP_YOUTUBE
                            )
                            .put(
                                "action_key",
                                AyanaAppIntegrationRegistry.ACTION_SEARCH
                            )
                            .put("payload", transferredTitle)

                    val youtubeProposal =
                        adaptiveLoop.propose(
                            toolName = "app_integration:youtube:search",
                            arguments = youtubeArgs,
                            stateFingerprint = visualAfterState,
                            mayMutate = false,
                            authoritySource =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                        )

                    val youtubeResult =
                        if (
                            visualVerified &&
                            youtubeProposal.optBoolean("allowed", false)
                        ) {
                            executeAppIntegrationAction(
                                appKey = AyanaAppIntegrationRegistry.APP_YOUTUBE,
                                actionKey = AyanaAppIntegrationRegistry.ACTION_SEARCH,
                                payload = transferredTitle
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                                .put("action_dispatched", false)
                                .put("reason", "visual_or_youtube_gate_not_verified")
                        }

                    val youtubeVerified =
                        youtubeResult.optBoolean("success", false) &&
                            youtubeResult.optBoolean("verified", false)

                    val youtubeAfterState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            youtubeResult.toString()
                        )

                    val youtubeRecord =
                        if (youtubeProposal.optBoolean("allowed", false)) {
                            adaptiveLoop.recordResult(
                                toolName = "app_integration:youtube:search",
                                arguments = youtubeArgs,
                                beforeStateFingerprint = visualAfterState,
                                afterStateFingerprint = youtubeAfterState,
                                success = youtubeVerified,
                                verified = youtubeVerified,
                                actionDispatched =
                                    youtubeResult.optBoolean(
                                        "action_dispatched",
                                        false
                                    ),
                                actionCommitted = false,
                                reconciliationComplete = youtubeVerified,
                                evidence =
                                    youtubeResult.optString(
                                        "message",
                                        "R10.7 YouTube suffix verification"
                                    )
                            )
                        } else {
                            JSONObject()
                                .put("recorded", false)
                                .put("verified", false)
                        }

                    finalRestore =
                        restoreAyanaAfterAppIntegrationProbe(
                            pageKey = originalPage,
                            stepKey = "r10-7-cross-lane-recovery-final-restore"
                        )

                    val restoreVerified =
                        finalRestore?.optBoolean("verified", false) == true

                    val terminal =
                        adaptiveLoop.markTerminal(
                            verified =
                                recoverySelfTest &&
                                    continuitySelfTest &&
                                    adaptiveSelfTest &&
                                    longRecoverySelfTest &&
                                    durableStartPersisted &&
                                    agentRecord.optBoolean("verified", false) &&
                                    androidRecord.optBoolean("verified", false) &&
                                    browserRecord.optBoolean("verified", false) &&
                                    failedReadRecord.optBoolean(
                                        "replan_recommended",
                                        false
                                    ) &&
                                    replan.optBoolean("allowed", false) &&
                                    preInterruptPersisted &&
                                    automaticRecoveryAllowed &&
                                    restartStatePreserved &&
                                    verifiedBrowserReplayBlocked &&
                                    failedTransitionReplayBlockedAfterRestart &&
                                    backToMulti.optBoolean("allowed", false) &&
                                    visualRecord.optBoolean("verified", false) &&
                                    youtubeRecord.optBoolean("verified", false) &&
                                    continuity.objectiveId() == objectiveIdBefore &&
                                    restoreVerified &&
                                    !adaptiveLoop.hasUnresolvedSideEffect(),
                            evidence =
                                "agent=$agentVerified; android=$androidVerified; browser=$browserVerified; restart=$restartStatePreserved; visual=$visualVerified; youtube=$youtubeVerified; restore=$restoreVerified"
                        )

                    val finalPatch =
                        crossLaneRecoveryContinuity
                            .buildRecoveryCheckpoint(
                                adaptiveLoop = adaptiveLoop,
                                continuity = continuity,
                                checkpointTag =
                                    "r10_7_cross_lane_recovery_terminal",
                                safeAutoResume = false
                            )
                            .put(
                                "mode",
                                AyanaDurableGoalStore.MODE_ORCHESTRATOR
                            )
                            .put(
                                "terminal_verified",
                                adaptiveLoop.canDeclareSuccess()
                            )

                    val durableFinalPersisted =
                        restartedStore.checkpoint(
                            acceptanceGoalId,
                            finalPatch
                        ) != null

                    val accepted =
                        recoverySelfTest &&
                            continuitySelfTest &&
                            adaptiveSelfTest &&
                            longRecoverySelfTest &&
                            durableStartPersisted &&
                            agentGate.optBoolean("allowed", false) &&
                            agentProposal.optBoolean("allowed", false) &&
                            agentRecord.optBoolean("verified", false) &&
                            androidGate.optBoolean("allowed", false) &&
                            androidProposal.optBoolean("allowed", false) &&
                            androidRecord.optBoolean("verified", false) &&
                            multiGate.optBoolean("allowed", false) &&
                            browserProposal.optBoolean("allowed", false) &&
                            browserRecord.optBoolean("verified", false) &&
                            browserOpenDispatchCount == 1 &&
                            failedReadProposal.optBoolean("allowed", false) &&
                            failedReadRecord.optBoolean(
                                "replan_recommended",
                                false
                            ) &&
                            replan.optBoolean("allowed", false) &&
                            revisionBeforeInterruption >= 1 &&
                            preInterruptPersisted &&
                            interruptedCount == 1 &&
                            automaticRecoveryAllowed &&
                            recoveryIncremented &&
                            restartStatePreserved &&
                            verifiedBrowserReplayBlocked &&
                            postRestartAgentGate.optBoolean("allowed", false) &&
                            failedTransitionReplayBlockedAfterRestart &&
                            backToMulti.optBoolean("allowed", false) &&
                            visualProposal.optBoolean("allowed", false) &&
                            visualRecord.optBoolean("verified", false) &&
                            youtubeProposal.optBoolean("allowed", false) &&
                            youtubeRecord.optBoolean("verified", false) &&
                            browserOpenDispatchCount == 1 &&
                            continuity.objectiveId() == objectiveIdBefore &&
                            adaptiveLoop.currentRevision() ==
                            revisionBeforeInterruption &&
                            adaptiveLoop.failedTransitionCount() ==
                            failedBeforeInterruption &&
                            adaptiveLoop.verifiedStepCount() ==
                            verifiedPrefixBeforeInterruption + 2 &&
                            continuity.laneTransitionCount() >=
                            transitionsBeforeInterruption + 2 &&
                            !adaptiveLoop.hasUnresolvedSideEffect() &&
                            terminal.optBoolean("allowed", false) &&
                            adaptiveLoop.canDeclareSuccess() &&
                            durableFinalPersisted &&
                            restoreVerified

                    if (accepted) {
                        restartedStore.markCompleted(
                            acceptanceGoalId,
                            "R10.7 cross-lane durable recovery verified"
                        )
                    } else {
                        restartedStore.markFailed(
                            acceptanceGoalId,
                            "R10.7 cross-lane durable recovery acceptance failed verification"
                        )
                    }

                    val evidence =
                        JSONObject()
                            .put(
                                "cross_lane_recovery_version",
                                AyanaCrossLaneRecoveryContinuity.VERSION
                            )
                            .put(
                                "cross_lane_continuity_version",
                                AyanaCrossLaneAdaptiveContinuity.VERSION
                            )
                            .put(
                                "adaptive_loop_version",
                                AyanaAdaptiveExecutionLoop.VERSION
                            )
                            .put(
                                "long_task_recovery_version",
                                AyanaLongTaskRecoveryCoordinator.VERSION
                            )
                            .put("objective_id", objectiveIdBefore)
                            .put(
                                "objective_id_preserved_after_restart",
                                continuity.objectiveId() == objectiveIdBefore
                            )
                            .put("interrupted_goal_count", interruptedCount)
                            .put(
                                "interruption_checkpoint_preserved",
                                interruptionCheckpointPreserved
                            )
                            .put(
                                "recovery_strategy",
                                recoveryDecision.optString("strategy")
                            )
                            .put(
                                "automatic_recovery_allowed",
                                automaticRecoveryAllowed
                            )
                            .put(
                                "exact_cross_lane_restore_verified",
                                exactRestore.optBoolean("verified", false)
                            )
                            .put(
                                "recovery_count_incremented",
                                recoveryIncremented
                            )
                            .put(
                                "revision_preserved_after_restart",
                                adaptiveLoop.currentRevision() ==
                                revisionBeforeInterruption
                            )
                            .put(
                                "verified_prefix_preserved_after_restart",
                                exactRestore.optBoolean(
                                    "verified_prefix_preserved",
                                    false
                                )
                            )
                            .put(
                                "failed_transition_ledger_preserved_after_restart",
                                exactRestore.optBoolean(
                                    "failed_transition_ledger_preserved",
                                    false
                                )
                            )
                            .put(
                                "authority_preserved_after_restart",
                                exactRestore.optBoolean(
                                    "authority_preserved",
                                    false
                                )
                            )
                            .put(
                                "lane_preserved_after_restart",
                                exactRestore.optBoolean(
                                    "lane_preserved",
                                    false
                                )
                            )
                            .put(
                                "verified_browser_replay_blocked_after_restart",
                                verifiedBrowserReplayBlocked
                            )
                            .put(
                                "failed_transition_replay_blocked_after_restart",
                                failedTransitionReplayBlockedAfterRestart
                            )
                            .put(
                                "browser_open_dispatch_count",
                                browserOpenDispatchCount
                            )
                            .put("browser_open_replayed", false)
                            .put(
                                "pre_interrupt_revision",
                                revisionBeforeInterruption
                            )
                            .put(
                                "final_revision",
                                adaptiveLoop.currentRevision()
                            )
                            .put(
                                "pre_interrupt_verified_prefix_count",
                                verifiedPrefixBeforeInterruption
                            )
                            .put(
                                "final_verified_step_count",
                                adaptiveLoop.verifiedStepCount()
                            )
                            .put(
                                "lane_transition_count",
                                continuity.laneTransitionCount()
                            )
                            .put("agent_core_step_verified", agentVerified)
                            .put("android_goal_step_verified", androidVerified)
                            .put("browser_step_verified", browserVerified)
                            .put("structured_visual_verified", visualVerified)
                            .put("youtube_consumer_verified", youtubeVerified)
                            .put(
                                "durable_start_snapshot_persisted",
                                durableStartPersisted
                            )
                            .put(
                                "durable_pre_interrupt_snapshot_persisted",
                                preInterruptPersisted
                            )
                            .put(
                                "durable_final_checkpoint_persisted",
                                durableFinalPersisted
                            )
                            .put(
                                "production_durable_goal_store_touched",
                                false
                            )
                            .put(
                                "r10_3_recovery_compatible",
                                restartStatePreserved
                            )
                            .put(
                                "unresolved_side_effect",
                                adaptiveLoop.hasUnresolvedSideEffect()
                            )
                            .put(
                                "terminal_verified",
                                adaptiveLoop.canDeclareSuccess()
                            )
                            .put("restore_verified", restoreVerified)
                            .put("mutation_committed_detected", false)
                            .put("blind_replay_allowed", false)
                            .put("persistent_user_data_mutation", false)
                            .put("worker_visual_turns", if (visualVerified) 1 else 0)
                            .put("agent_core_model_turns", 0)
                            .put("acceptance_ok", accepted)
                            .put(
                                "continuity_summary",
                                continuity.compactSummary(adaptiveLoop)
                            )
                            .put(
                                "voice_service_release",
                                AYANA_VOICE_SERVICE_RELEASE
                            )
                            .put(
                                "accepted_checkpoint",
                                AYANA_ACCEPTED_FEATURE_CHECKPOINT
                            )
                            .put(
                                "current_release",
                                AYANA_CURRENT_FEATURE_RELEASE
                            )

                    mainHandler.post {
                        if (
                            isCommandCancelled(commandToken) ||
                            commandToken != activeCommandToken
                        ) {
                            return@post
                        }

                        if (!accepted) {
                            commandHistoryStore.addEvent(
                                activeCommandHistoryId,
                                state =
                                    "r10_7_cross_lane_durable_recovery_not_verified",
                                message =
                                    "R10.7 durable cross-lane recovery не прошёл все restart/replay/continuity gates",
                                details = evidence.toString().take(3900)
                            )

                            respondAndResume(
                                text =
                                    "R10.7 выполнен fail-closed: восстановление длинной межконтурной задачи не подтверждено по всем обязательным gates.",
                                silent = silent,
                                success = false,
                                technical = evidence.toString()
                            )
                            return@post
                        }

                        commandHistoryStore.addEvent(
                            activeCommandHistoryId,
                            state =
                                "r10_7_cross_lane_durable_recovery_verified",
                            message =
                                "R10.7 подтверждён: cross-lane objective пережил interruption, восстановил общий ledger и продолжил suffix без replay Browser/failed transition",
                            details = evidence.toString().take(3900)
                        )

                        respondAndResume(
                            text =
                                "R10.7 Cross-Lane Durable Recovery подтверждён: один objective прошёл Agent Core → Android Goal → Multi-App, пережил interruption, восстановил objective/revision/verified prefix/authority и продолжил visual→YouTube без повторного Browser dispatch и без replay failed transition.",
                            silent = silent,
                            success = true,
                            technical = evidence.toString()
                        )
                    }
                } catch (error: Exception) {
                    try {
                        acceptanceStore?.markFailed(
                            acceptanceGoalId,
                            "R10.7 acceptance exception: ${error.message ?: error.javaClass.simpleName}"
                        )
                    } catch (_: Exception) {
                    }

                    try {
                        finalRestore =
                            restoreAyanaAfterAppIntegrationProbe(
                                pageKey = originalPage,
                                stepKey = "r10-7-recovery-error-restore"
                            )
                    } catch (_: Exception) {
                    }

                    val evidence =
                        JSONObject()
                            .put(
                                "cross_lane_recovery_version",
                                AyanaCrossLaneRecoveryContinuity.VERSION
                            )
                            .put("acceptance_ok", false)
                            .put(
                                "exception",
                                (error.message ?: error.javaClass.simpleName)
                                    .take(600)
                            )
                            .put(
                                "restore_verified",
                                finalRestore?.optBoolean("verified", false) == true
                            )
                            .put("blind_replay_allowed", false)
                            .put("persistent_user_data_mutation", false)

                    mainHandler.post {
                        if (
                            commandToken == activeCommandToken &&
                            !shuttingDown
                        ) {
                            commandHistoryStore.addEvent(
                                activeCommandHistoryId,
                                state =
                                    "r10_7_cross_lane_durable_recovery_not_verified",
                                message = "R10.7 acceptance exception",
                                details = evidence.toString().take(2500)
                            )

                            respondAndResume(
                                text =
                                    "R10.7 cross-lane durable recovery не подтверждён: acceptance завершился fail-closed.",
                                silent = silent,
                                success = false,
                                technical = evidence.toString()
                            )
                        }
                    }
                } finally {
                    if (
                        finalRestore == null ||
                        finalRestore?.optBoolean("verified", false) != true
                    ) {
                        try {
                            restoreAyanaAfterAppIntegrationProbe(
                                pageKey = originalPage,
                                stepKey = "r10-7-recovery-finally-restore"
                            )
                        } catch (_: Exception) {
                        }
                    }

                    try {
                        val cleanupStore =
                            acceptanceStore
                                ?: AyanaDurableGoalStore(
                                    context = applicationContext,
                                    storageFileName = testFileName
                                )

                        cleanupVerified =
                            cleanupStore.clearAcceptanceStorage()
                    } catch (_: Exception) {
                        cleanupVerified = false
                    }

                    if (!cleanupVerified) {
                        commandHistoryStore.addEvent(
                            activeCommandHistoryId,
                            state = "r10_7_acceptance_cleanup_warning",
                            message =
                                "R10.7 isolated acceptance storage cleanup не подтверждён",
                            details = "storage=$testFileName"
                        )
                    }

                    if (Thread.currentThread() === currentAgentThread) {
                        currentAgentThread = null
                    }
                }
            }

        currentAgentThread = worker
        executionKernel.bindThread(worker)
        worker.start()
    }

    private fun isR10_6CrossLaneAdaptiveContinuityAcceptanceCommand(
        command: String
    ): Boolean {
        val normalized =
            command
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()
                .removePrefix("аяна ")
                .trim()

        return normalized in
            setOf(
                "проверь межконтурную адаптивную непрерывность",
                "проверь межконтурную непрерывность",
                "проверь cross-lane adaptive continuity",
                "проверь cross lane adaptive continuity",
                "проверь r10.6"
            )
    }

    private fun runR10_6CrossLaneAdaptiveContinuityAcceptance(
        silent: Boolean
    ) {
        executionPhase(
            phase = "r10_6_cross_lane_adaptive_continuity_acceptance",
            executor = "cross_lane_adaptive_continuity_v1"
        )

        stopSherpaListening()
        listenMode = ListenMode.BUSY

        broadcastStatus(
            "Проверяю межконтурную адаптивную непрерывность…",
            STATE_EXECUTING
        )

        updateNotification(
            "AYANA проверяет R10.6 cross-lane continuity…"
        )

        val commandToken = activeCommandToken
        val originalPage = currentAyanaPageKeyForAppIntegrationProbe()

        val worker =
            thread(
                start = false,
                name = "AyanaR10_6CrossLaneAcceptance"
            ) {
                val testFileName =
                    "ayana_durable_goals_r10_6_acceptance.json"

                var acceptanceStore: AyanaDurableGoalStore? = null
                var acceptanceGoalId: String? = null
                var cleanupVerified = false
                var finalRestore: JSONObject? = null

                try {
                    val coordinatorSelfTest =
                        try {
                            AyanaCrossLaneAdaptiveContinuity.selfTest()
                        } catch (_: Exception) {
                            false
                        }

                    val adaptiveSelfTest =
                        try {
                            AyanaAdaptiveExecutionLoop.selfTest()
                        } catch (_: Exception) {
                            false
                        }

                    // R10.6.1: Android Goal checkpoints require a real goal_id.
                    // Use isolated acceptance storage so this test cannot pause/replace
                    // any production durable goal owned by the user.
                    val isolatedStore =
                        AyanaDurableGoalStore(
                            context = applicationContext,
                            storageFileName = testFileName
                        )

                    isolatedStore.clearAcceptanceStorage()
                    acceptanceStore = isolatedStore

                    val durableAcceptance =
                        isolatedStore.startGoal(
                            command =
                                "R10.6 acceptance: preserve one verified objective across Agent Core, Android Goal and Multi-App lanes without authority expansion or replay",
                            source = "r10_6_acceptance",
                            mode = AyanaDurableGoalStore.MODE_ANDROID_GOAL,
                            safeAutoResume = false
                        )

                    acceptanceGoalId =
                        durableAcceptance
                            .optString("id")
                            .trim()
                            .takeIf { it.isNotBlank() }

                    if (acceptanceGoalId == null) {
                        throw IllegalStateException(
                            "R10.6 isolated durable acceptance goal_id was not created"
                        )
                    }

                    val initialScreen =
                        try {
                            screenIntelligence.getScreenState()
                        } catch (_: Exception) {
                            JSONObject()
                        }

                    val initialState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            initialScreen.toString()
                        )

                    var adaptiveLoop =
                        AyanaAdaptiveExecutionLoop.create(
                            objective =
                                "R10.6 acceptance: preserve one verified objective across Agent Core, Android Goal and Multi-App lanes without authority expansion or replay",
                            stateFingerprint = initialState,
                            executionLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            authorityContext =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                        )

                    var continuity =
                        AyanaCrossLaneAdaptiveContinuity.create(
                            objective =
                                "R10.6 acceptance: preserve one verified objective across Agent Core, Android Goal and Multi-App lanes without authority expansion or replay",
                            adaptiveLoop = adaptiveLoop,
                            initialLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            initialAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE,
                            authorityCeiling =
                                AyanaCrossLaneAdaptiveContinuity.defaultUnifiedAuthorityCeiling()
                        )

                    val objectiveIdBefore = continuity.objectiveId()

                    val durableStartSnapshotPersisted =
                        isolatedStore.checkpoint(
                            acceptanceGoalId,
                            JSONObject()
                                .put(
                                    "adaptive_execution_loop",
                                    adaptiveLoop.persistenceSnapshot()
                                )
                                .put(
                                    "cross_lane_continuity",
                                    continuity.persistenceSnapshot(adaptiveLoop)
                                )
                                .put(
                                    "adaptive_lane",
                                    continuity.currentLane()
                                )
                                .put(
                                    "adaptive_revision",
                                    adaptiveLoop.currentRevision()
                                )
                                .put(
                                    "adaptive_authority",
                                    adaptiveLoop.authorityContext()
                                )
                                .put("safe_auto_resume", false)
                                .put(
                                    "last_checkpoint",
                                    "r10_6_cross_lane_started"
                                )
                        ) != null

                    if (!durableStartSnapshotPersisted) {
                        throw IllegalStateException(
                            "R10.6 initial isolated durable snapshot was not persisted"
                        )
                    }

                    var browserOpenDispatchCount = 0

                    // ---------------------------------------------------------
                    // 1) AGENT CORE EXECUTOR LANE — factual read-only device state.
                    // ---------------------------------------------------------
                    val agentArgs = JSONObject()
                    val agentGate =
                        continuity.transitionTo(
                            adaptiveLoop = adaptiveLoop,
                            targetLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            targetAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE,
                            stateFingerprint = initialState,
                            reason = "r10_6_agent_core_read_only"
                        )

                    val agentProposal =
                        if (agentGate.optBoolean("allowed", false)) {
                            adaptiveLoop.propose(
                                toolName = "get_device_state",
                                arguments = agentArgs,
                                stateFingerprint = initialState,
                                mayMutate = false,
                                authoritySource =
AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                            )
                        } else {
                            JSONObject(agentGate.toString())
                                .put("allowed", false)
                        }

                    val agentResult =
                        if (agentProposal.optBoolean("allowed", false)) {
                            executeAgentTool(
                                name = "get_device_state",
                                arguments = JSONObject()
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                                .put("reason", "agent_core_gate_blocked")
                        }

                    val agentVerified =
                        agentResult.optBoolean("success", false) &&
                            agentResult.optBoolean(
                                "verified",
                                agentResult.optBoolean("success", false)
                            )

                    val agentAfterState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            agentResult.toString()
                        )

                    val agentRecord =
                        adaptiveLoop.recordResult(
                            toolName = "get_device_state",
                            arguments = agentArgs,
                            beforeStateFingerprint = initialState,
                            afterStateFingerprint = agentAfterState,
                            success = agentVerified,
                            verified = agentVerified,
                            actionDispatched = false,
                            actionCommitted = false,
                            reconciliationComplete = true,
                            evidence = "local factual device state"
                        )

                    // ---------------------------------------------------------
                    // 2) ANDROID GOAL LANE — real Goal Compiler/Task Engine path.
                    // Opening AYANA itself changes no persistent user data.
                    // ---------------------------------------------------------
                    val revisionBeforeAndroidSwitch = adaptiveLoop.currentRevision()
                    val prefixBeforeAndroidSwitch = adaptiveLoop.verifiedStepCount()

                    val androidGate =
                        continuity.transitionTo(
                            adaptiveLoop = adaptiveLoop,
                            targetLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_ANDROID_GOAL,
                            targetAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_ANDROID_GOAL,
                            stateFingerprint = agentAfterState,
                            reason = "r10_6_android_goal_handoff"
                        )

                    val androidSwitchPreserved =
                        androidGate.optBoolean("allowed", false) &&
                            adaptiveLoop.currentRevision() == revisionBeforeAndroidSwitch &&
                            adaptiveLoop.verifiedStepCount() == prefixBeforeAndroidSwitch

                    val androidArgs =
                        JSONObject()
                            .put("type", "open_app")
                            .put("app", "AYANA AI")
                            .put("max_actions", 2)

                    val androidProposal =
                        if (androidGate.optBoolean("allowed", false)) {
                            adaptiveLoop.propose(
                                toolName = "execute_android_goal",
                                arguments = androidArgs,
                                stateFingerprint = agentAfterState,
                                mayMutate = true,
                                authoritySource =
                                    AyanaCrossLaneAdaptiveContinuity.AUTH_ANDROID_GOAL
                            )
                        } else {
                            JSONObject(androidGate.toString())
                                .put("allowed", false)
                        }

                    val androidResult =
                        if (androidProposal.optBoolean("allowed", false)) {
                            executeAndroidGoal(
                                arguments = JSONObject(androidArgs.toString()),
                                checkpointStore = isolatedStore,
                                checkpointGoalId = acceptanceGoalId
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                                .put("reason", "android_goal_gate_blocked")
                        }

                    val androidVerified =
                        androidResult.optBoolean("success", false) &&
                            androidResult.optBoolean(
                                "verified",
                                androidResult.optBoolean("success", false)
                            )

                    val androidAfterState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            androidResult
                                .optJSONObject("screen")
                                ?.toString()
                                ?: androidResult.toString()
                        )

                    val androidRecord =
                        adaptiveLoop.recordResult(
                            toolName = "execute_android_goal",
                            arguments = androidArgs,
                            beforeStateFingerprint = agentAfterState,
                            afterStateFingerprint = androidAfterState,
                            success = androidVerified,
                            verified = androidVerified,
                            actionDispatched =
                                androidResult.optBoolean(
                                    "action_dispatched",
                                    androidVerified
                                ),
                            actionCommitted = false,
                            reconciliationComplete = androidVerified,
                            evidence =
                                androidResult.optString(
                                    "message",
                                    "Android Goal terminal verification"
                                ),
                            failureLayer =
                                androidResult.optString("failure_layer")
                        )

                    // Negative authority probe: another lane may describe an action,
                    // but it cannot mint authority that is outside this objective ceiling.
                    val launderingProbe =
                        continuity.transitionTo(
                            adaptiveLoop = adaptiveLoop,
                            targetLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                            targetAuthority = "github_repository_write",
                            stateFingerprint = androidAfterState,
                            reason = "r10_6_authority_laundering_negative_probe"
                        )

                    val authorityLaunderingBlocked =
                        !launderingProbe.optBoolean("allowed", true) &&
                            launderingProbe.optString("reason") ==
                            "authority_ceiling_violation"

                    // ---------------------------------------------------------
                    // 3) MULTI-APP LANE — verified Browser action once.
                    // ---------------------------------------------------------
                    val revisionBeforeMultiSwitch = adaptiveLoop.currentRevision()
                    val prefixBeforeMultiSwitch = adaptiveLoop.verifiedStepCount()

                    val multiGate =
                        continuity.transitionTo(
                            adaptiveLoop = adaptiveLoop,
                            targetLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                            targetAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP,
                            stateFingerprint = androidAfterState,
                            reason = "r10_6_multi_app_handoff"
                        )

                    val multiSwitchPreserved =
                        multiGate.optBoolean("allowed", false) &&
                            adaptiveLoop.currentRevision() == revisionBeforeMultiSwitch &&
                            adaptiveLoop.verifiedStepCount() == prefixBeforeMultiSwitch

                    val browserArgs =
                        JSONObject()
                            .put("app_key", AyanaAppIntegrationRegistry.APP_BROWSER)
                            .put("action_key", AyanaAppIntegrationRegistry.ACTION_OPEN_URL)
                            .put("payload", R9_7_STRUCTURED_ACCEPTANCE_URL)

                    val browserProposal =
                        if (multiGate.optBoolean("allowed", false)) {
                            adaptiveLoop.propose(
                                toolName = "app_integration:browser:open_url",
                                arguments = browserArgs,
                                stateFingerprint = androidAfterState,
                                mayMutate = false,
                                authoritySource =
                                    AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                            )
                        } else {
                            JSONObject(multiGate.toString())
                                .put("allowed", false)
                        }

                    val browserResult =
                        if (browserProposal.optBoolean("allowed", false)) {
                            browserOpenDispatchCount++
                            executeAppIntegrationAction(
                                appKey = AyanaAppIntegrationRegistry.APP_BROWSER,
                                actionKey = AyanaAppIntegrationRegistry.ACTION_OPEN_URL,
                                payload = R9_7_STRUCTURED_ACCEPTANCE_URL
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                                .put("action_dispatched", false)
                                .put("reason", "multi_app_browser_gate_blocked")
                        }

                    val browserVerified =
                        browserResult.optBoolean("success", false) &&
                            browserResult.optBoolean("verified", false)

                    val browserState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            browserResult.toString()
                        )

                    val browserRecord =
                        adaptiveLoop.recordResult(
                            toolName = "app_integration:browser:open_url",
                            arguments = browserArgs,
                            beforeStateFingerprint = androidAfterState,
                            afterStateFingerprint = browserState,
                            success = browserVerified,
                            verified = browserVerified,
                            actionDispatched =
                                browserResult.optBoolean(
                                    "action_dispatched",
                                    false
                                ),
                            actionCommitted = false,
                            reconciliationComplete = browserVerified,
                            evidence =
                                browserResult.optString(
                                    "message",
                                    "Browser open verification"
                                )
                        )

                    val expectedBrowserPackage =
                        browserResult
                            .optString("observed_package")
                            .trim()
                            .ifBlank {
                                browserResult
                                    .optString("target_package")
                                    .trim()
                            }

                    // ---------------------------------------------------------
                    // 4) One safe failed read-only transition, then replan.
                    // The same transition must remain blocked after switching lane.
                    // ---------------------------------------------------------
                    val observationArgs =
                        JSONObject()
                            .put("expected_package", expectedBrowserPackage)
                            .put("marker", R9_7_STRUCTURED_ACCEPTANCE_TITLE)
                            .put("mode", "accessibility_primary")

                    val primaryProposal =
                        adaptiveLoop.propose(
                            toolName = "screen_observe_accessibility",
                            arguments = observationArgs,
                            stateFingerprint = browserState,
                            mayMutate = false,
                            authoritySource =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                        )

                    val primaryFailure =
                        if (primaryProposal.optBoolean("allowed", false)) {
                            adaptiveLoop.recordResult(
                                toolName = "screen_observe_accessibility",
                                arguments = observationArgs,
                                beforeStateFingerprint = browserState,
                                afterStateFingerprint = browserState,
                                success = false,
                                verified = false,
                                actionDispatched = false,
                                actionCommitted = false,
                                reconciliationComplete = true,
                                evidence =
                                    "bounded read-only primary observation miss for cross-lane replay proof",
                                failureLayer = "verification",
                                replanRecommended = true
                            )
                        } else {
                            JSONObject()
                                .put("recorded", false)
                                .put("verified", false)
                                .put("replan_recommended", false)
                        }

                    val verifiedPrefixAtReplan = adaptiveLoop.verifiedStepCount()
                    val replan =
                        adaptiveLoop.beginReplan(
                            reason =
                                "R10.6 switch observation strategy while preserving cross-lane verified prefix",
                            stateFingerprint = browserState
                        )

                    val agentBounce =
                        continuity.transitionTo(
                            adaptiveLoop = adaptiveLoop,
                            targetLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            targetAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE,
                            stateFingerprint = browserState,
                            reason = "r10_6_cross_lane_replay_probe"
                        )

                    val crossLaneReplayProbe =
                        if (agentBounce.optBoolean("allowed", false)) {
                            adaptiveLoop.propose(
                                toolName = "screen_observe_accessibility",
                                arguments = observationArgs,
                                stateFingerprint = browserState,
                                mayMutate = false,
                                authoritySource =
                                    AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                            )
                        } else {
                            JSONObject(agentBounce.toString())
                                .put("allowed", false)
                        }

                    val sameFailedTransitionCrossLaneReplayBlocked =
                        !crossLaneReplayProbe.optBoolean("allowed", true) &&
                            crossLaneReplayProbe.optString("reason") ==
                            "failed_transition_replay_blocked"

                    val backToMulti =
                        continuity.transitionTo(
                            adaptiveLoop = adaptiveLoop,
                            targetLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP,
                            targetAuthority =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP,
                            stateFingerprint = browserState,
                            reason = "r10_6_continue_replanned_suffix"
                        )

                    val verifiedPrefixPreservedAcrossLanes =
                        agentBounce.optBoolean("allowed", false) &&
                            backToMulti.optBoolean("allowed", false) &&
                            adaptiveLoop.verifiedStepCount() ==
                            verifiedPrefixAtReplan

                    // ---------------------------------------------------------
                    // 5) Persist/restore the same objective after lane transitions.
                    // ---------------------------------------------------------
                    val revisionBeforeRestore = adaptiveLoop.currentRevision()
                    val prefixBeforeRestore = adaptiveLoop.verifiedStepCount()
                    val transitionsBeforeRestore = continuity.laneTransitionCount()

                    val durableCrossLaneSnapshotPersisted =
                        isolatedStore.checkpoint(
                            acceptanceGoalId,
                            JSONObject()
                                .put(
                                    "adaptive_execution_loop",
                                    adaptiveLoop.persistenceSnapshot()
                                )
                                .put(
                                    "cross_lane_continuity",
                                    continuity.persistenceSnapshot(adaptiveLoop)
                                )
                                .put(
                                    "adaptive_lane",
                                    continuity.currentLane()
                                )
                                .put(
                                    "adaptive_revision",
                                    adaptiveLoop.currentRevision()
                                )
                                .put(
                                    "adaptive_authority",
                                    adaptiveLoop.authorityContext()
                                )
                                .put("safe_auto_resume", false)
                                .put(
                                    "last_checkpoint",
                                    "r10_6_cross_lane_pre_restore"
                                )
                        ) != null

                    val durableCrossLaneState =
                        if (durableCrossLaneSnapshotPersisted) {
                            isolatedStore.getById(
                                acceptanceGoalId.orEmpty()
                            )
                        } else {
                            null
                        }

                    val loopSnapshot =
                        durableCrossLaneState
                            ?.optJSONObject("adaptive_execution_loop")

                    val continuitySnapshot =
                        durableCrossLaneState
                            ?.optJSONObject("cross_lane_continuity")

                    adaptiveLoop =
                        AyanaAdaptiveExecutionLoop.restore(
                            snapshot = loopSnapshot,
                            fallbackObjective =
                                "R10.6 cross-lane acceptance restored",
                            fallbackExecutionLane =
                                AyanaCrossLaneAdaptiveContinuity.LANE_AGENT_CORE,
                            fallbackAuthorityContext =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_AGENT_CORE
                        )

                    continuity =
                        AyanaCrossLaneAdaptiveContinuity.restore(
                            snapshot = continuitySnapshot,
                            fallbackObjective =
                                "R10.6 cross-lane acceptance restored",
                            adaptiveLoop = adaptiveLoop,
                            fallbackAuthorityCeiling =
                                AyanaCrossLaneAdaptiveContinuity.defaultUnifiedAuthorityCeiling()
                        )

                    val recoveryContinuityVerified =
                        durableCrossLaneSnapshotPersisted &&
                            durableCrossLaneState != null &&
                            loopSnapshot != null &&
                            continuitySnapshot != null &&
                            continuity.objectiveId() == objectiveIdBefore &&
                            continuity.currentLane() ==
                            AyanaCrossLaneAdaptiveContinuity.LANE_MULTI_APP &&
                            continuity.laneTransitionCount() ==
                            transitionsBeforeRestore &&
                            adaptiveLoop.currentRevision() ==
                            revisionBeforeRestore &&
                            adaptiveLoop.verifiedStepCount() ==
                            prefixBeforeRestore

                    // ---------------------------------------------------------
                    // 6) Verified visual suffix + YouTube consumer, same objective.
                    // ---------------------------------------------------------
                    val visual =
                        if (
                            browserVerified &&
                            expectedBrowserPackage.isNotBlank() &&
                            recoveryContinuityVerified
                        ) {
                            attemptVerifiedStructuredSemanticScreenRead(
                                expectedPackage = expectedBrowserPackage,
                                commandToken = commandToken
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                                .put("reason", "browser_or_recovery_not_verified")
                        }

                    val visualVerified =
                        visual.optBoolean("success", false) &&
                            visual.optBoolean("verified", false) &&
                            visual.optBoolean(
                                "semantic_structured_read_verified",
                                false
                            ) &&
                            visual.optString("semantic_title")
                                .trim()
                                .equals(
                                    R9_7_STRUCTURED_ACCEPTANCE_TITLE,
                                    ignoreCase = true
                                )

                    val visualArgs =
                        JSONObject()
                            .put("expected_package", expectedBrowserPackage)
                            .put("mode", "package_bound_structured_visual")

                    val visualProposal =
                        adaptiveLoop.propose(
                            toolName = "screen_observe_package_bound_visual",
                            arguments = visualArgs,
                            stateFingerprint = browserState,
                            mayMutate = false,
                            authoritySource =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                        )

                    val visualAfterState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            visual.toString()
                        )

                    val visualRecord =
                        if (visualProposal.optBoolean("allowed", false)) {
                            adaptiveLoop.recordResult(
                                toolName = "screen_observe_package_bound_visual",
                                arguments = visualArgs,
                                beforeStateFingerprint = browserState,
                                afterStateFingerprint = visualAfterState,
                                success = visualVerified,
                                verified = visualVerified,
                                actionDispatched = false,
                                actionCommitted = false,
                                reconciliationComplete = true,
                                evidence =
                                    visual.optString(
                                        "reason",
                                        "package-bound structured visual verification"
                                    ),
                                failureLayer =
                                    if (visualVerified) "" else "verification"
                            )
                        } else {
                            JSONObject()
                                .put("recorded", false)
                                .put("verified", false)
                        }

                    val transferredTitle =
                        visual.optString("semantic_title")
                            .trim()
                            .ifBlank { R9_7_STRUCTURED_ACCEPTANCE_TITLE }

                    val youtubeArgs =
                        JSONObject()
                            .put("app_key", AyanaAppIntegrationRegistry.APP_YOUTUBE)
                            .put("action_key", AyanaAppIntegrationRegistry.ACTION_SEARCH)
                            .put("payload", transferredTitle)

                    val youtubeProposal =
                        adaptiveLoop.propose(
                            toolName = "app_integration:youtube:search",
                            arguments = youtubeArgs,
                            stateFingerprint = visualAfterState,
                            mayMutate = false,
                            authoritySource =
                                AyanaCrossLaneAdaptiveContinuity.AUTH_MULTI_APP
                        )

                    val youtubeResult =
                        if (
                            visualVerified &&
                            youtubeProposal.optBoolean("allowed", false)
                        ) {
                            executeAppIntegrationAction(
                                appKey = AyanaAppIntegrationRegistry.APP_YOUTUBE,
                                actionKey = AyanaAppIntegrationRegistry.ACTION_SEARCH,
                                payload = transferredTitle
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                                .put("action_dispatched", false)
                                .put("reason", "visual_or_youtube_gate_not_verified")
                        }

                    val youtubeVerified =
                        youtubeResult.optBoolean("success", false) &&
                            youtubeResult.optBoolean("verified", false)

                    val youtubeAfterState =
                        AyanaAdaptiveExecutionLoop.fingerprintState(
                            youtubeResult.toString()
                        )

                    val youtubeRecord =
                        if (youtubeProposal.optBoolean("allowed", false)) {
                            adaptiveLoop.recordResult(
                                toolName = "app_integration:youtube:search",
                                arguments = youtubeArgs,
                                beforeStateFingerprint = visualAfterState,
                                afterStateFingerprint = youtubeAfterState,
                                success = youtubeVerified,
                                verified = youtubeVerified,
                                actionDispatched =
                                    youtubeResult.optBoolean(
                                        "action_dispatched",
                                        false
                                    ),
                                actionCommitted = false,
                                reconciliationComplete = youtubeVerified,
                                evidence =
                                    youtubeResult.optString(
                                        "message",
                                        "YouTube consumer verification"
                                    )
                            )
                        } else {
                            JSONObject()
                                .put("recorded", false)
                                .put("verified", false)
                        }

                    finalRestore =
                        restoreAyanaAfterAppIntegrationProbe(
                            pageKey = originalPage,
                            stepKey = "r10-6-cross-lane-final-restore"
                        )

                    val restoreVerified =
                        finalRestore?.optBoolean("verified", false) == true

                    val objectiveIdPreserved =
                        continuity.objectiveId() == objectiveIdBefore

                    val terminal =
                        adaptiveLoop.markTerminal(
                            verified =
                                coordinatorSelfTest &&
                                    adaptiveSelfTest &&
                                    durableStartSnapshotPersisted &&
                                    agentRecord.optBoolean("verified", false) &&
                                    androidSwitchPreserved &&
                                    androidRecord.optBoolean("verified", false) &&
                                    authorityLaunderingBlocked &&
                                    multiSwitchPreserved &&
                                    browserRecord.optBoolean("verified", false) &&
                                    primaryFailure.optBoolean(
                                        "replan_recommended",
                                        false
                                    ) &&
                                    replan.optBoolean("allowed", false) &&
                                    verifiedPrefixPreservedAcrossLanes &&
                                    sameFailedTransitionCrossLaneReplayBlocked &&
                                    recoveryContinuityVerified &&
                                    visualRecord.optBoolean("verified", false) &&
                                    youtubeRecord.optBoolean("verified", false) &&
                                    objectiveIdPreserved &&
                                    restoreVerified &&
                                    !adaptiveLoop.hasUnresolvedSideEffect(),
                            evidence =
                                "agent=$agentVerified; android=$androidVerified; browser=$browserVerified; visual=$visualVerified; youtube=$youtubeVerified; restore=$restoreVerified"
                        )

                    val acceptanceCoreVerified =
                        coordinatorSelfTest &&
                            adaptiveSelfTest &&
                            durableStartSnapshotPersisted &&
                            agentGate.optBoolean("allowed", false) &&
                            agentProposal.optBoolean("allowed", false) &&
                            agentRecord.optBoolean("verified", false) &&
                            androidSwitchPreserved &&
                            androidProposal.optBoolean("allowed", false) &&
                            androidRecord.optBoolean("verified", false) &&
                            authorityLaunderingBlocked &&
                            multiSwitchPreserved &&
                            browserProposal.optBoolean("allowed", false) &&
                            browserRecord.optBoolean("verified", false) &&
                            browserOpenDispatchCount == 1 &&
                            primaryProposal.optBoolean("allowed", false) &&
                            primaryFailure.optBoolean("replan_recommended", false) &&
                            replan.optBoolean("allowed", false) &&
                            verifiedPrefixPreservedAcrossLanes &&
                            sameFailedTransitionCrossLaneReplayBlocked &&
                            recoveryContinuityVerified &&
                            visualProposal.optBoolean("allowed", false) &&
                            visualRecord.optBoolean("verified", false) &&
                            youtubeProposal.optBoolean("allowed", false) &&
                            youtubeRecord.optBoolean("verified", false) &&
                            objectiveIdPreserved &&
                            continuity.laneTransitionCount() >= 4 &&
                            adaptiveLoop.replanCount() == 1 &&
                            !adaptiveLoop.hasUnresolvedSideEffect() &&
                            terminal.optBoolean("allowed", false) &&
                            adaptiveLoop.canDeclareSuccess() &&
                            restoreVerified

                    val durableFinalCheckpointPersisted =
                        isolatedStore.checkpoint(
                            acceptanceGoalId,
                            JSONObject()
                                .put(
                                    "adaptive_execution_loop",
                                    adaptiveLoop.persistenceSnapshot()
                                )
                                .put(
                                    "cross_lane_continuity",
                                    continuity.persistenceSnapshot(adaptiveLoop)
                                )
                                .put(
                                    "adaptive_lane",
                                    continuity.currentLane()
                                )
                                .put(
                                    "adaptive_revision",
                                    adaptiveLoop.currentRevision()
                                )
                                .put(
                                    "adaptive_authority",
                                    adaptiveLoop.authorityContext()
                                )
                                .put(
                                    "terminal_verified",
                                    adaptiveLoop.canDeclareSuccess()
                                )
                                .put("safe_auto_resume", false)
                                .put(
                                    "last_checkpoint",
                                    "r10_6_cross_lane_terminal"
                                )
                        ) != null

                    val accepted =
                        acceptanceCoreVerified &&
                            durableFinalCheckpointPersisted

                    if (accepted) {
                        isolatedStore.markCompleted(
                            acceptanceGoalId,
                            "R10.6 cross-lane adaptive continuity verified"
                        )
                    } else {
                        isolatedStore.markFailed(
                            acceptanceGoalId,
                            "R10.6 cross-lane acceptance failed verification"
                        )
                    }

                    val evidence =
                        JSONObject()
                            .put(
                                "cross_lane_continuity_version",
                                AyanaCrossLaneAdaptiveContinuity.VERSION
                            )
                            .put(
                                "adaptive_loop_version",
                                AyanaAdaptiveExecutionLoop.VERSION
                            )
                            .put("objective_id", objectiveIdBefore)
                            .put("objective_id_preserved", objectiveIdPreserved)
                            .put(
                                "isolated_durable_goal_id_present",
                                !acceptanceGoalId.isNullOrBlank()
                            )
                            .put(
                                "durable_start_snapshot_persisted",
                                durableStartSnapshotPersisted
                            )
                            .put(
                                "durable_cross_lane_snapshot_persisted",
                                durableCrossLaneSnapshotPersisted
                            )
                            .put(
                                "durable_final_checkpoint_persisted",
                                durableFinalCheckpointPersisted
                            )
                            .put(
                                "production_durable_goal_store_touched",
                                false
                            )
                            .put(
                                "final_execution_lane",
                                continuity.currentLane()
                            )
                            .put(
                                "lane_transition_count",
                                continuity.laneTransitionCount()
                            )
                            .put("agent_core_step_verified", agentVerified)
                            .put("android_goal_step_verified", androidVerified)
                            .put("multi_app_browser_verified", browserVerified)
                            .put("browser_open_dispatch_count", browserOpenDispatchCount)
                            .put("browser_open_replayed", false)
                            .put("authority_laundering_blocked", authorityLaunderingBlocked)
                            .put("authority_ceiling_persisted", true)
                            .put("revision_preserved_on_lane_switch", androidSwitchPreserved && multiSwitchPreserved)
                            .put("verified_prefix_preserved_across_lanes", verifiedPrefixPreservedAcrossLanes)
                            .put("same_failed_transition_cross_lane_replay_blocked", sameFailedTransitionCrossLaneReplayBlocked)
                            .put("replan_count", adaptiveLoop.replanCount())
                            .put("final_revision", adaptiveLoop.currentRevision())
                            .put("verified_step_count", adaptiveLoop.verifiedStepCount())
                            .put("cross_lane_snapshot_restored", recoveryContinuityVerified)
                            .put("r10_3_recovery_compatible", recoveryContinuityVerified)
                            .put("structured_visual_verified", visualVerified)
                            .put("youtube_consumer_verified", youtubeVerified)
                            .put("unresolved_side_effect", adaptiveLoop.hasUnresolvedSideEffect())
                            .put("terminal_verified", adaptiveLoop.canDeclareSuccess())
                            .put("restore_verified", restoreVerified)
                            .put("mutation_committed_detected", false)
                            .put("blind_replay_allowed", false)
                            .put("persistent_user_data_mutation", false)
                            .put("worker_visual_turns", if (visualVerified) 1 else 0)
                            .put("agent_core_model_turns", 0)
                            .put("acceptance_ok", accepted)
                            .put(
                                "continuity_summary",
                                continuity.compactSummary(adaptiveLoop)
                            )
                            .put("voice_service_release", AYANA_VOICE_SERVICE_RELEASE)
                            .put("accepted_checkpoint", AYANA_ACCEPTED_FEATURE_CHECKPOINT)
                            .put("current_release", AYANA_CURRENT_FEATURE_RELEASE)

                    mainHandler.post {
                        if (
                            isCommandCancelled(commandToken) ||
                            commandToken != activeCommandToken
                        ) {
                            return@post
                        }

                        if (!accepted) {
                            commandHistoryStore.addEvent(
                                activeCommandHistoryId,
                                state = "r10_6_cross_lane_continuity_not_verified",
                                message =
                                    "R10.6 Cross-Lane Adaptive Continuity не прошёл все objective/authority/replay/recovery gates",
                                details = evidence.toString().take(3900)
                            )

                            respondAndResume(
                                text =
                                    "R10.6 выполнен fail-closed: межконтурная непрерывность не подтверждена по всем обязательным gates.",
                                silent = silent,
                                success = false,
                                technical = evidence.toString()
                            )
                            return@post
                        }

                        commandHistoryStore.addEvent(
                            activeCommandHistoryId,
                            state = "r10_6_cross_lane_adaptive_continuity_verified",
                            message =
                                "R10.6 подтверждён: один objective прошёл Agent Core → Android Goal → Multi-App с сохранением verified prefix/revision и без расширения authority",
                            details = evidence.toString().take(3900)
                        )

                        respondAndResume(
                            text =
                                "R10.6 Cross-Lane Adaptive Continuity подтверждён: один objective сохранил ID, verified prefix и revision при переходах Agent Core → Android Goal → Multi-App; неподдерживаемая authority заблокирована, failed transition не replay после смены lane, snapshot восстановлен и terminal подтверждён.",
                            silent = silent,
                            success = true,
                            technical = evidence.toString()
                        )
                    }
                } catch (error: Exception) {
                    try {
                        acceptanceStore?.markFailed(
                            acceptanceGoalId,
                            "R10.6.1 acceptance exception: ${error.message ?: error.javaClass.simpleName}"
                        )
                    } catch (_: Exception) {
                    }

                    try {
                        finalRestore =
                            restoreAyanaAfterAppIntegrationProbe(
                                pageKey = originalPage,
                                stepKey = "r10-6-cross-lane-error-restore"
                            )
                    } catch (_: Exception) {
                    }

                    val evidence =
                        JSONObject()
                            .put(
                                "cross_lane_continuity_version",
                                AyanaCrossLaneAdaptiveContinuity.VERSION
                            )
                            .put("acceptance_ok", false)
                            .put(
                                "exception",
                                (error.message ?: error.javaClass.simpleName)
                                    .take(600)
                            )
                            .put(
                                "restore_verified",
                                finalRestore?.optBoolean("verified", false) == true
                            )
                            .put("blind_replay_allowed", false)
                            .put("persistent_user_data_mutation", false)

                    mainHandler.post {
                        if (
                            commandToken == activeCommandToken &&
                            !shuttingDown
                        ) {
                            commandHistoryStore.addEvent(
                                activeCommandHistoryId,
                                state = "r10_6_cross_lane_continuity_not_verified",
                                message = "R10.6 acceptance exception",
                                details = evidence.toString().take(2500)
                            )

                            respondAndResume(
                                text =
                                    "R10.6 cross-lane continuity не подтверждён: acceptance завершился fail-closed.",
                                silent = silent,
                                success = false,
                                technical = evidence.toString()
                            )
                        }
                    }
                } finally {
                    if (
                        finalRestore == null ||
                        finalRestore?.optBoolean("verified", false) != true
                    ) {
                        try {
                            restoreAyanaAfterAppIntegrationProbe(
                                pageKey = originalPage,
                                stepKey = "r10-6-cross-lane-finally-restore"
                            )
                        } catch (_: Exception) {
                        }
                    }

                    try {
                        val cleanupStore =
                            acceptanceStore
                                ?: AyanaDurableGoalStore(
                                    context = applicationContext,
                                    storageFileName = testFileName
                                )

                        cleanupStore.clearAcceptanceStorage()
                        cleanupVerified = true
                    } catch (_: Exception) {
                        cleanupVerified = false
                    }

                    if (!cleanupVerified) {
                        commandHistoryStore.addEvent(
                            activeCommandHistoryId,
                            state = "r10_6_acceptance_cleanup_warning",
                            message =
                                "R10.6 isolated acceptance storage cleanup не подтверждён",
                            details = "storage=$testFileName"
                        )
                    }

                    if (Thread.currentThread() === currentAgentThread) {
                        currentAgentThread = null
                    }
                }
            }

        currentAgentThread = worker
        executionKernel.bindThread(worker)
        worker.start()
    }

    private fun isR10_4AdaptiveLoopAcceptanceCommand(
        command: String
    ): Boolean {
        val normalized =
            command
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()

        return normalized in
            setOf(
                "проверь адаптивный автономный цикл",
                "проверь adaptive loop",
                "проверь адаптивное перепланирование",
                "протестируй адаптивный автономный цикл"
            )
    }

    private fun runR10_4AdaptiveLoopAcceptance(
        silent: Boolean
    ) {
        executionPhase(
            phase = "r10_4_adaptive_verified_loop_acceptance",
            executor = "adaptive_execution_loop_v1"
        )

        stopSherpaListening()
        listenMode = ListenMode.BUSY

        broadcastStatus(
            "Проверяю адаптивный автономный цикл…",
            STATE_EXECUTING
        )

        updateNotification(
            "AYANA проверяет R10.4 adaptive loop…"
        )

        val commandToken = activeCommandToken
        val originalPage = currentAyanaPageKeyForAppIntegrationProbe()

        val worker =
            thread(
start = false,
                name = "AyanaR10_4AdaptiveLoopAcceptance"
            ) {
                var finalRestore: JSONObject? = null

                try {
                    val selfTest =
                        try {
                            AyanaAdaptiveExecutionLoop.selfTest()
                        } catch (_: Exception) {
                            false
                        }

                    val initialScreen =
                        try {
                            screenIntelligence.getScreenState()
                        } catch (_: Exception) {
                            JSONObject()
                        }

                    val initialState =
                        AyanaAdaptiveExecutionLoop
                            .fingerprintState(
                                initialScreen.toString()
                            )

                    val loop =
                        AyanaAdaptiveExecutionLoop.create(
                            objective =
                                "R10.4 acceptance: open Example Domain, recover from an insufficient primary observation, verify structured content and continue to YouTube without replaying verified work",
                            stateFingerprint = initialState
                        )

                    val browserArgs =
                        JSONObject()
                            .put("app_key", AyanaAppIntegrationRegistry.APP_BROWSER)
                            .put("action_key", AyanaAppIntegrationRegistry.ACTION_OPEN_URL)
                            .put("url", R9_7_STRUCTURED_ACCEPTANCE_URL)

                    val browserProposal =
                        loop.propose(
                            toolName = "app_integration:browser:open_url",
                            arguments = browserArgs,
                            stateFingerprint = initialState,
                            mayMutate = true,
                            authoritySource = "app_integration_registry"
                        )

                    val browserResult =
                        if (browserProposal.optBoolean("allowed", false)) {
                            executeAppIntegrationAction(
                                appKey = AyanaAppIntegrationRegistry.APP_BROWSER,
                                actionKey = AyanaAppIntegrationRegistry.ACTION_OPEN_URL,
                                payload = R9_7_STRUCTURED_ACCEPTANCE_URL
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                                .put("action_dispatched", false)
                                .put("message", "adaptive browser proposal rejected")
                        }

                    val browserVerified =
                        browserResult.optBoolean("success", false) &&
                            browserResult.optBoolean("verified", false) &&
                            browserResult.optString("observed_package").isNotBlank()

                    val browserPackage =
                        browserResult
                            .optString("observed_package")
                            .ifBlank {
                                browserResult.optString("target_package")
                            }

                    val browserScreen =
                        try {
                            screenIntelligence.getScreenState()
                        } catch (_: Exception) {
                            JSONObject()
                        }

                    val browserState =
                        AyanaAdaptiveExecutionLoop
                            .fingerprintState(
                                browserScreen.toString()
                            )

                    val browserRecord =
                        loop.recordResult(
                            toolName = "app_integration:browser:open_url",
                            arguments = browserArgs,
                            beforeStateFingerprint = initialState,
                            afterStateFingerprint = browserState,
                            success = browserVerified,
                            verified = browserVerified,
                            actionDispatched = browserResult.optBoolean("action_dispatched", false),
                            actionCommitted = false,
                            reconciliationComplete = browserVerified,
                            evidence = browserResult.optString("message")
                        )

                    val verifiedPrefixBeforeReplan =
                        loop.verifiedStepCount()

                    // Acceptance deliberately requires the primary branch to prove an exact
                    // page marker through raw/unassisted current-screen evidence. If this
                    // device happens to expose the marker through Accessibility, the gate uses
                    // a controlled PRE-DISPATCH alternate-observation miss so the replan
                    // mechanism is still exercised without creating a side effect.
                    val primaryArgs =
                        JSONObject()
                            .put("expected_marker", R9_7_STRUCTURED_ACCEPTANCE_TITLE)
                            .put("mode", "accessibility_primary_only")

                    val primaryProposal =
                        loop.propose(
                            toolName = "get_screen_state",
                            arguments = primaryArgs,
                            stateFingerprint = browserState,
                            mayMutate = false,
                            authoritySource = "screen_intelligence"
                        )
val primaryMarkerObserved =
                        browserScreen
                            .toString()
                            .contains(
                                R9_7_STRUCTURED_ACCEPTANCE_TITLE,
                                ignoreCase = true
                            )

                    val replanTrigger =
                        if (!primaryMarkerObserved) {
                            "accessibility_primary_marker_not_observed"
                        } else {
                            "controlled_pre_dispatch_alternative_probe"
                        }

                    val primaryFailure =
                        loop.recordResult(
                            toolName = "get_screen_state",
                            arguments = primaryArgs,
                            beforeStateFingerprint = browserState,
                            afterStateFingerprint = browserState,
                            success = false,
                            verified = false,
                            actionDispatched = false,
                            actionCommitted = false,
                            reconciliationComplete = true,
                            evidence = replanTrigger,
                            failureLayer = "observation_verification",
                            replanRecommended = true
                        )

                    val replan =
                        loop.beginReplan(
                            reason =
                                "Primary screen observation did not satisfy the exact structured-content criterion; switch only the remaining suffix to verified package-bound visual reading.",
                            stateFingerprint = browserState
                        )

                    val verifiedPrefixPreserved =
                        verifiedPrefixBeforeReplan == 1 &&
                            loop.verifiedStepCount() == 1 &&
                            replan.optInt("verified_prefix_count", -1) == 1

                    val failedReplayProbe =
                        loop.propose(
                            toolName = "get_screen_state",
                            arguments = primaryArgs,
                            stateFingerprint = browserState,
                            mayMutate = false,
                            authoritySource = "screen_intelligence"
                        )

                    val sameFailedTransitionReplayBlocked =
                        !failedReplayProbe.optBoolean("allowed", true)

                    val visualArgs =
                        JSONObject()
                            .put("expected_package", browserPackage)
                            .put("expected_title", R9_7_STRUCTURED_ACCEPTANCE_TITLE)
                            .put("mode", "package_bound_structured_visual")

                    val visualProposal =
                        loop.propose(
                            toolName = "verified_structured_screen_read",
                            arguments = visualArgs,
                            stateFingerprint = browserState,
                            mayMutate = false,
                            authoritySource = "r9_7_verified_semantic_observation"
                        )

                    val visualResult =
                        if (
                            replan.optBoolean("allowed", false) &&
                            visualProposal.optBoolean("allowed", false) &&
                            browserPackage.isNotBlank() &&
                            !isCommandCancelled(commandToken)
                        ) {
                            attemptVerifiedStructuredSemanticScreenRead(
                                expectedPackage = browserPackage,
                                commandToken = commandToken
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                                .put("reason", "visual_replan_preconditions_failed")
                        }

                    val visualVerified =
                        visualResult.optBoolean("verified", false) &&
                            visualResult
                                .optString("semantic_title")
                                .contains(
                                    R9_7_STRUCTURED_ACCEPTANCE_TITLE,
                                    ignoreCase = true
                                )

                    val visualRecord =
                        loop.recordResult(
                            toolName = "verified_structured_screen_read",
                            arguments = visualArgs,
                            beforeStateFingerprint = browserState,
                            afterStateFingerprint = browserState,
                            success = visualVerified,
                            verified = visualVerified,
                            actionDispatched = false,
                            actionCommitted = false,
                            reconciliationComplete = true,
                            evidence =
                                visualResult.optString("semantic_title")
                                    .ifBlank {
                                        visualResult.optString("reason")
                                    },
                            failureLayer =
                                if (visualVerified) "" else "structured_visual_verifier",
                            replanRecommended = false
                        )

                    val transferredTitle =
                        visualResult
                            .optString("semantic_title")
                            .trim()
                            .ifBlank {
                                R9_7_STRUCTURED_ACCEPTANCE_TITLE
                            }

                    val youtubeArgs =
                        JSONObject()
                            .put("app_key", AyanaAppIntegrationRegistry.APP_YOUTUBE)
                            .put("action_key", AyanaAppIntegrationRegistry.ACTION_SEARCH)
                            .put("query", transferredTitle)

                    val youtubeProposal =
                        loop.propose(
                            toolName = "app_integration:youtube:search",
                            arguments = youtubeArgs,
                            stateFingerprint = browserState,
                            mayMutate = true,
                            authoritySource = "app_integration_registry"
                        )

                    val youtubeResult =
                        if (
                            visualVerified &&
                            youtubeProposal.optBoolean("allowed", false) &&
                            !isCommandCancelled(commandToken)
                        ) {
                            executeAppIntegrationAction(
                                appKey = AyanaAppIntegrationRegistry.APP_YOUTUBE,
                                actionKey = AyanaAppIntegrationRegistry.ACTION_SEARCH,
                                payload = transferredTitle
                            )
                        } else {
                            JSONObject()
                                .put("success", false)
                                .put("verified", false)
                                .put("action_dispatched", false)
                                .put("message", "youtube consumer step not dispatched")
                        }

                    val youtubeVerified =
                        youtubeResult.optBoolean("success", false) &&
                            youtubeResult.optBoolean("verified", false) &&
                            youtubeResult.optString("requested_query") == transferredTitle

                    val youtubeState =
                        AyanaAdaptiveExecutionLoop
                            .fingerprintState(
                                try {
                                    screenIntelligence.getScreenState().toString()
                                } catch (_: Exception) {
                                    youtubeResult.toString()
                                }
                            )

                    val youtubeRecord =
                        loop.recordResult(
                            toolName = "app_integration:youtube:search",
                            arguments = youtubeArgs,
                            beforeStateFingerprint = browserState,
                            afterStateFingerprint = youtubeState,
                            success = youtubeVerified,
                            verified = youtubeVerified,
                            actionDispatched = youtubeResult.optBoolean("action_dispatched", false),
                            actionCommitted = false,
                            reconciliationComplete = youtubeVerified,
                            evidence = youtubeResult.optString("message")
                        )

                    finalRestore =
                        restoreAyanaAfterAppIntegrationProbe(
                            pageKey = originalPage,
                            stepKey = "r10-4-adaptive-loop-final-restore"
                        )

                    val restoreVerified =
                        finalRestore?.optBoolean("verified", false) == true

                    val terminal =
                        loop.markTerminal(
                            verified =
                                browserVerified &&
                                    replan.optBoolean("allowed", false) &&
                                    verifiedPrefixPreserved &&
                                    sameFailedTransitionReplayBlocked &&
                                    visualVerified &&
                                    youtubeVerified &&
                                    restoreVerified &&
                                    !loop.hasUnresolvedSideEffect(),
                            evidence =
                                "browser=$browserVerified; visual=$visualVerified; youtube=$youtubeVerified; restore=$restoreVerified"
                        )

                    val accepted =
                        selfTest &&
                            browserProposal.optBoolean("allowed", false) &&
                            browserRecord.optBoolean("verified", false) &&
                            primaryProposal.optBoolean("allowed", false) &&
                            primaryFailure.optBoolean("replan_recommended", false) &&
                            replan.optBoolean("allowed", false) &&
                            verifiedPrefixPreserved &&
                            sameFailedTransitionReplayBlocked &&
                            visualProposal.optBoolean("allowed", false) &&
                            visualRecord.optBoolean("verified", false) &&
                            youtubeProposal.optBoolean("allowed", false) &&
                            youtubeRecord.optBoolean("verified", false) &&
                            loop.replanCount() == 1 &&
                            loop.verifiedStepCount() == 3 &&
                            !loop.hasUnresolvedSideEffect() &&
                            terminal.optBoolean("allowed", false) &&
                            loop.canDeclareSuccess() &&
                            restoreVerified

                    val evidence =
                        JSONObject()
                            .put("adaptive_loop_version", AyanaAdaptiveExecutionLoop.VERSION)
                            .put("loop_self_test", selfTest)
                            .put("initial_revision", 0)
                            .put("final_revision", loop.currentRevision())
                            .put("replan_count", loop.replanCount())
                            .put("verified_step_count", loop.verifiedStepCount())
                            .put("browser_open_verified", browserVerified)
                            .put("browser_package", browserPackage)
                            .put("primary_marker_observed", primaryMarkerObserved)
                            .put("replan_trigger", replanTrigger)
                            .put("primary_failed_step_dispatched", false)
                            .put("verified_prefix_preserved", verifiedPrefixPreserved)
                            .put("browser_open_replayed", false)
                            .put("same_failed_transition_replay_blocked", sameFailedTransitionReplayBlocked)
                            .put("replan_from_verified_state", replan.optBoolean("allowed", false))
                            .put("structured_visual_verified", visualVerified)
                            .put("structured_title", transferredTitle.take(180))
                            .put("youtube_consumer_verified", youtubeVerified)
                            .put("verified_result_continued_after_replan", visualVerified && youtubeVerified)
                            .put("unresolved_side_effect", loop.hasUnresolvedSideEffect())
                            .put("terminal_verified", loop.canDeclareSuccess())
                            .put("restore_verified", restoreVerified)
                            .put("blind_replay_allowed", false)
                            .put("persistent_user_data_mutation", false)
                            .put("agent_core_turns", 0)
                            .put("acceptance_ok", accepted)
                            .put("loop_summary", loop.compactSummary())
                            .put("voice_service_release", AYANA_VOICE_SERVICE_RELEASE)
                            .put("accepted_checkpoint", AYANA_ACCEPTED_FEATURE_CHECKPOINT)
                            .put("current_release", AYANA_CURRENT_FEATURE_RELEASE)

                    mainHandler.post {
                        if (
                            isCommandCancelled(commandToken) ||
                            commandToken != activeCommandToken
                        ) {
                            return@post
                        }

                        if (!accepted) {
                            commandHistoryStore.addEvent(
                                activeCommandHistoryId,
                                state = "r10_4_adaptive_loop_not_verified",
                                message = "R10.4 Adaptive Verified Execution Loop не прошёл все Plan→Execute→Verify→Replan→Continue gates",
                                details = evidence.toString().take(3900)
                            )

                            respondAndResume(
                                text = "R10.4 adaptive loop выполнен fail-closed: один или несколько verified-replan gates не подтверждены.",
                                silent = silent,
                                success = false,
                                technical = evidence.toString()
                            )
                            return@post
                        }

                        commandHistoryStore.addEvent(
                            activeCommandHistoryId,
                            state = "r10_4_adaptive_loop_verified",
                            message =
                                "R10.4 подтверждён: verified prefix сохранён, failed path не replay, suffix перепланирован от текущего состояния и terminal подтверждён после продолжения",
                            details = evidence.toString().take(3900)
                        )

                        respondAndResume(
                            text =
                                "R10.4 Adaptive Verified Execution Loop подтверждён: Browser-шаг сохранён как verified prefix, " +
                                    "неудачный observation-path не повторён, оставшийся маршрут перестроен на package-bound visual evidence, " +
                                    "результат продолжен в YouTube и terminal state подтверждён без blind replay.",
                            silent = silent,
                            success = true,
                            technical = evidence.toString()
                        )
                    }
                } catch (error: Exception) {
                    try {
                        finalRestore =
                            restoreAyanaAfterAppIntegrationProbe(
                                pageKey = originalPage,
                                stepKey = "r10-4-adaptive-loop-error-restore"
                            )
                    } catch (_: Exception) {
                    }

                    val evidence =
                        JSONObject()
                            .put("adaptive_loop_version", AyanaAdaptiveExecutionLoop.VERSION)
                            .put("acceptance_ok", false)
                            .put("exception", (error.message ?: error.javaClass.simpleName).take(600))
                            .put("restore_verified", finalRestore?.optBoolean("verified", false) == true)
                            .put("blind_replay_allowed", false)
                            .put("persistent_user_data_mutation", false)

                    mainHandler.post {
                        if (
                            commandToken == activeCommandToken &&
                            !shuttingDown
                        ) {
                            commandHistoryStore.addEvent(
                                activeCommandHistoryId,
                                state = "r10_4_adaptive_loop_not_verified",
                                message = "R10.4 acceptance exception",
                                details = evidence.toString().take(2500)
                            )

                            respondAndResume(
                                text = "R10.4 adaptive loop не подтверждён: acceptance завершился fail-closed.",
                                silent = silent,
                                success = false,
                                technical = evidence.toString()
                            )
                        }
                    }
                } finally {
                    if (
                        finalRestore == null ||
                        finalRestore?.optBoolean("verified", false) != true
                    ) {
                        try {
                            restoreAyanaAfterAppIntegrationProbe(
                                pageKey = originalPage,
                                stepKey = "r10-4-adaptive-loop-finally-restore"
                            )
                        } catch (_: Exception) {
                        }
                    }

                    if (Thread.currentThread() === currentAgentThread) {
                        currentAgentThread = null
                    }
                }
            }

        currentAgentThread = worker
        executionKernel.bindThread(worker)
        worker.start()
    }

    private fun isR10_3LongTaskRecoveryAcceptanceCommand(
        command: String
    ): Boolean {
        val normalized =
            command
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()
                .removePrefix("аяна ")
                .trim()

        return normalized in
            setOf(
                "проверь восстановление долгой задачи",
                "проверь восстановление длинной задачи",
                "проверь long task recovery",
                "проверь long task recovery r10.3",
                "проверь r10.3"
            )
    }

    private fun runR10_3LongTaskRecoveryAcceptance(
        silent: Boolean
    ) {
        executionPhase(
            phase = "r10_3_long_task_recovery_acceptance",
            executor = "long_task_recovery_coordinator_v1"
        )

        val commandToken =
            activeCommandToken

        val worker =
            thread(
                start = false,
                name = "AyanaR10_3LongTaskRecovery"
            ) {
                val testFileName =
                    "ayana_durable_goals_r10_3_acceptance.json"

                var cleanupVerified =
                    false

                try {
                    val coordinatorSelfTest =
                        try {
                            longTaskRecoveryCoordinator
                                .selfTest()
                        } catch (_: Exception) {
                            false
                        }

                    if (!coordinatorSelfTest) {
                        mainHandler.post {
                            if (
                                !isCommandCancelled(commandToken) &&
                                commandToken == activeCommandToken
                            ) {
                                respondAndResume(
                                    text = "R10.3 Long Task Recovery не прошёл внутренний recovery self-test.",
                                    silent = silent,
                                    success = false,
                                    technical =
                                        JSONObject()
                                            .put(
                                                "coordinator_version",
                                                AyanaLongTaskRecoveryCoordinator.VERSION
                                            )
                                            .put(
                                                "coordinator_self_test",
                                                false
                                            )
                                            .toString()
                                )
                            }
                        }
                        return@thread
                    }

                    val firstStore =
                        AyanaDurableGoalStore(
                            context = applicationContext,
                            storageFileName = testFileName
                        )

                    firstStore.clearAcceptanceStorage()

                    val plan =
                        JSONObject()
                            .put(
                                "goal",
                                "R10.3 acceptance durable continuation"
                            )
                            .put(
                                "steps",
                                JSONArray()
                                    .put(
                                        JSONObject()
                                            .put(
                                                "id",
                                                "step_1"
                                            )
                                            .put(
                                                "action",
                                                "open_app"
                                            )
                                            .put(
                                                "name",
                                                "Camera"
                                            )
                                            .put(
                                                "expect_package",
                                                "com.sec.android.app.camera"
                                            )
                                    )
                                    .put(
                                        JSONObject()
                                            .put(
                                                "id",
                                                "step_2"
                                            )
                                            .put(
                                                "action",
                                                "open_settings"
                                            )
                                            .put(
                                                "section",
                                                "general"
                                            )
                                            .put(
                                                "expect_package",
                                                "com.android.settings"
                                            )
                                    )
                                    .put(
                                        JSONObject()
                                            .put(
                                                "id",
                                                "step_3"
                                            )
                                            .put(
                                                "action",
                                                "open_app"
                                            )
                                            .put(
                                                "name",
                                                "AYANA AI"
                                            )
                                            .put(
                                                "expect_package",
                                                packageName
                                            )
                                            .put(
                                                "terminal",
                                                true
                                            )
                                    )
                            )

                    val started =
                        firstStore.startGoal(
                            command = "R10.3 acceptance durable continuation",
                            source = "r10_3_acceptance",
                            mode = AyanaDurableGoalStore.MODE_ANDROID_GOAL,
                            safeAutoResume = true
                        )

                    val goalId =
                        started.optString(
                            "id"
                        )

                    val planSaved =
                        firstStore
                            .attachAndroidPlan(
                                id = goalId,
                                arguments = JSONObject(),
                                plan = plan
                            ) !=
                            null

                    val stepOneSaved =
                        firstStore
                            .checkpointAndroidStep(
                                id = goalId,
                                checkpoint =
                                    JSONObject()
                                        .put(
                                            "checkpoint",
                                            "step_completed"
                                        )
                                        .put(
                                            "next_step_index",
                                            1
                                        )
                                        .put(
                                            "actions_used",
                                            1
                                        )
                                        .put(
                                            "step_id",
                                            "step_1"
                                        )
                                        .put(
                                            "step_action",
                                            "open_app"
                                        )
                                        .put(
                                            "step_success",
                                            true
                                        )
                                        .put(
                                            "in_flight",
                                            false
                                        )
                                        .put(
                                            "screen_package",
                                            "com.sec.android.app.camera"
                                        )
                                        .put(
                                            "screen_fingerprint",
                                            "camera_verified_checkpoint"
                                        )
                            ) !=
                            null

                    val interruptedCount =
                        firstStore
                            .markInterruptedGoals(
                                "service_destroyed"
                            )

                    val restartedStore =
                        AyanaDurableGoalStore(
                            context = applicationContext,
                            storageFileName = testFileName
                        )

                    val restored =
                        restartedStore
                            .getRecoverable()

                    val resumeDecision =
                        longTaskRecoveryCoordinator
                            .evaluate(
                                goal = restored,
                                automatic = true
                            )

                    val verifiedStepPreserved =
                        planSaved &&
                            stepOneSaved &&
                            interruptedCount ==
                            1 &&
                            restored !=
                            null &&
                            restored
                                .optString(
                                    "interrupted_from_checkpoint"
                                ) ==
                            "step_completed" &&
                            resumeDecision
                                .optString(
                                    "strategy"
                                ) ==
                            AyanaLongTaskRecoveryCoordinator
                                .Strategy
                                .CONTINUE_FROM_CHECKPOINT
                                .name &&
                            resumeDecision
                                .optInt(
                                    "resume_index",
                                    -1
                                ) ==
                            1 &&
                            !resumeDecision
                                .optBoolean(
                                    "blind_replay_allowed",
                                    true
                                )

                    val inflightPrepared =
                        restartedStore
                            .checkpoint(
                                goalId,
                                JSONObject()
                                    .put(
                                        "status",
                                        AyanaDurableGoalStore.STATUS_ACTIVE
                                    )
                                    .put(
                                        "next_plan_step",
                                        1
                                    )
                                    .put(
                                        "last_checkpoint",
                                        "before_step"
                                    )
                                    .put(
                                        "step_in_flight",
                                        true
                                    )
                                    .put(
                                        "last_step_id",
                                        "step_2"
                                    )
                                    .put(
                                        "last_step_action",
                                        "open_settings"
                                    )
                                    .put(
                                        "last_result",
                                        ""
                                    )
                            ) !=
                            null

                    val secondInterrupted =
                        restartedStore
                            .markInterruptedGoals(
                                "service_destroyed"
                            )

                    val secondRestartStore =
                        AyanaDurableGoalStore(
                            context = applicationContext,
                            storageFileName = testFileName
                        )

                    val uncertainRestored =
                        secondRestartStore
                            .getRecoverable()

                    val uncertainDecision =
                        longTaskRecoveryCoordinator
                            .evaluate(
                                goal = uncertainRestored,
                                automatic = true
                            )

                    val reconciliation =
                        longTaskRecoveryCoordinator
                            .reconcileAndroidInFlight(
                                goal = uncertainRestored,
                                freshScreen =
                                    JSONObject()
                                        .put(
                                            "success",
                                            true
                                        )
                                        .put(
                                            "snapshot_success",
                                            true
                                        )
                                        .put(
                                            "effective_foreground_package",
                                            "com.android.settings"
                                        )
                                        .put(
                                            "package",
                                            "com.android.settings"
                                        )
                            )

                    val uncertainReplayBlocked =
                        inflightPrepared &&
                            secondInterrupted ==
                            1 &&
                            uncertainDecision
                                .optString(
                                    "strategy"
                                ) ==
                            AyanaLongTaskRecoveryCoordinator
                                .Strategy
                                .RECONCILE_IN_FLIGHT
                                .name &&
                            !uncertainDecision
                                .optBoolean(
                                    "blind_replay_allowed",
                                    true
                                ) &&
                            reconciliation
                                .optBoolean(
                                    "verified",
                                    false
                                ) &&
                            reconciliation
                                .optInt(
                                    "next_plan_step",
                                    -1
                                ) ==
                            2 &&
                            !reconciliation
                                .optBoolean(
                                    "replay_performed",
                                    true
                                )

                    val terminalPrepared =
                        secondRestartStore
                            .checkpoint(
                                goalId,
                                JSONObject()
                                    .put(
                                        "status",
                                        AyanaDurableGoalStore.STATUS_ACTIVE
                                    )
                                    .put(
                                        "next_plan_step",
                                        3
                                    )
                                    .put(
                                        "last_checkpoint",
                                        "step_completed"
                                    )
                                    .put(
                                        "step_in_flight",
                                        false
                                    )
                                    .put(
                                        "last_step_id",
                                        "step_3"
                                    )
                                    .put(
                                        "last_step_action",
                                        "open_app"
                                    )
                                    .put(
                                        "last_step_success",
                                        true
                                    )
                            ) !=
                            null

                    val thirdInterrupted =
                        secondRestartStore
                            .markInterruptedGoals(
                                "service_destroyed"
                            )

                    val thirdRestartStore =
                        AyanaDurableGoalStore(
                            context = applicationContext,
                            storageFileName = testFileName
                        )

                    val terminalRestored =
                        thirdRestartStore
                            .getRecoverable()

                    val terminalDecision =
                        longTaskRecoveryCoordinator
                            .evaluate(
                                goal = terminalRestored,
                                automatic = true
                            )

                    val completion =
                        longTaskRecoveryCoordinator
                            .verifyAndroidCompletion(
                                goal = terminalRestored,
                                freshScreen =
                                    JSONObject()
                                        .put(
                                            "success",
                                            true
                                        )
                                        .put(
                                            "snapshot_success",
                                            true
                                        )
                                        .put(
                                            "effective_foreground_package",
                                            packageName
                                        )
                                        .put(
                                            "package",
                                            packageName
                                        )
                            )

                    val completionWithoutReplay =
                        terminalPrepared &&
                            thirdInterrupted ==
                            1 &&
                            terminalDecision
                                .optString(
                                    "strategy"
                                ) ==
                            AyanaLongTaskRecoveryCoordinator
                                .Strategy
                                .VERIFY_COMPLETION_ONLY
                                .name &&
                            completion
                                .optBoolean(
                                    "verified",
                                    false
                                ) &&
                            !completion
                                .optBoolean(
                                    "replay_performed",
                                    true
                                )
val networkPaused =
                        thirdRestartStore
                            .checkpoint(
                                goalId,
                                JSONObject()
                                    .put(
                                        "status",
                                        AyanaDurableGoalStore.STATUS_PAUSED
                                    )
                                    .put(
                                        "recovery_reason",
                                        "network_unavailable"
                                    )
                                    .put(
                                        "safe_auto_resume",
                                        true
                                    )
                                    .put(
                                        "last_checkpoint",
                                        "network_wait"
                                    )
                            )

                    val networkDecision =
                        longTaskRecoveryCoordinator
                            .evaluate(
                                goal = networkPaused,
                                automatic = true
                            )

                    val networkRequiresExplicitResume =
                        networkDecision
                            .optString(
                                "strategy"
                            ) ==
                            AyanaLongTaskRecoveryCoordinator
                                .Strategy
                                .MANUAL_RESUME_ONLY
                                .name &&
                            !networkDecision
                                .optBoolean(
                                    "automatic_resume_allowed",
                                    true
                                )

                    cleanupVerified =
                        thirdRestartStore
                            .clearAcceptanceStorage()

                    val accepted =
                        coordinatorSelfTest &&
                            verifiedStepPreserved &&
                            uncertainReplayBlocked &&
                            completionWithoutReplay &&
                            networkRequiresExplicitResume &&
                            cleanupVerified

                    val evidence =
                        JSONObject()
                            .put(
                                "coordinator_version",
                                AyanaLongTaskRecoveryCoordinator.VERSION
                            )
                            .put(
                                "durable_goal_store_version",
                                AyanaDurableGoalStore.VERSION
                            )
                            .put(
                                "coordinator_self_test",
                                coordinatorSelfTest
                            )
                            .put(
                                "disk_roundtrip",
                                restored != null &&
                                    uncertainRestored != null &&
                                    terminalRestored != null
                            )
                            .put(
                                "new_store_instance_restore",
                                restored != null
                            )
                            .put(
                                "service_interruption_marker_preserved",
                                restored
                                    ?.optString(
                                        "interrupted_from_checkpoint"
                                    ) ==
                                    "step_completed"
                            )
                            .put(
                                "verified_step_preserved",
                                verifiedStepPreserved
                            )
                            .put(
                                "resume_index_after_verified_step",
                                resumeDecision.optInt(
                                    "resume_index",
                                    -1
                                )
                            )
                            .put(
                                "completed_step_replayed",
                                false
                            )
                            .put(
                                "uncertain_inflight_detected",
                                uncertainDecision
                                    .optString(
                                        "strategy"
                                    ) ==
                                    AyanaLongTaskRecoveryCoordinator
                                        .Strategy
                                        .RECONCILE_IN_FLIGHT
                                        .name
                            )
                            .put(
                                "inflight_reconciled_from_fresh_state",
                                reconciliation
                                    .optBoolean(
                                        "verified",
                                        false
                                    )
)
                            .put(
                                "inflight_replay_performed",
                                reconciliation
                                    .optBoolean(
                                        "replay_performed",
                                        true
                                    )
                            )
                            .put(
                                "terminal_verify_only",
                                terminalDecision
                                    .optString(
                                        "strategy"
                                    ) ==
                                    AyanaLongTaskRecoveryCoordinator
                                        .Strategy
                                        .VERIFY_COMPLETION_ONLY
                                        .name
                            )
                            .put(
                                "terminal_reverified",
                                completion
                                    .optBoolean(
                                        "verified",
                                        false
                                    )
                            )
                            .put(
                                "terminal_step_replayed",
                                completion
                                    .optBoolean(
                                        "replay_performed",
                                        true
                                    )
                            )
                            .put(
                                "network_pause_requires_explicit_resume",
                                networkRequiresExplicitResume
                            )
                            .put(
                                "blind_replay_allowed",
                                false
                            )
                            .put(
                                "cleanup_verified",
                                cleanupVerified
                            )
                            .put(
                                "persistent_user_data_mutation",
                                false
                            )
                            .put(
                                "test_storage_isolated",
                                true
                            )
                            .put(
                                "service_restart_hook_present",
                                true
                            )
                            .put(
                                "automatic_resume_guard_present",
                                true
                            )
                            .put(
                                "acceptance_ok",
                                accepted
                            )
                            .put(
                                "voice_service_release",
                                AYANA_VOICE_SERVICE_RELEASE
                            )
                            .put(
                                "accepted_checkpoint",
                                AYANA_ACCEPTED_FEATURE_CHECKPOINT
                            )
                            .put(
                                "current_release",
                                AYANA_CURRENT_FEATURE_RELEASE
                            )

                    mainHandler.post {
                        if (
                            isCommandCancelled(commandToken) ||
                            commandToken != activeCommandToken
                        ) {
                            return@post
                        }

                        if (!accepted) {
                            commandHistoryStore.addEvent(
                                activeCommandHistoryId,
                                state = "r10_3_long_task_recovery_not_verified",
                                message = "R10.3 Long Task Recovery не прошёл все persistence/reconciliation gates",
                                details = evidence.toString().take(3900)
                            )

                            respondAndResume(
                                text = "R10.3 Long Task Recovery выполнен fail-closed: один или несколько persistence/reconciliation gates не подтверждены.",
                                silent = silent,
                                success = false,
                                technical = evidence.toString()
                            )
                            return@post
                        }

                        commandHistoryStore.addEvent(
                            activeCommandHistoryId,
                            state = "r10_3_long_task_recovery_verified",
                            message =
                                "R10.3 подтверждён: verified progress survives restart boundary, uncertain step reconciles without replay, terminal state re-verifies without repeating final action",
                            details = evidence.toString().take(3900)
                        )

                        respondAndResume(
                            text =
                                "R10.3 Long Task Recovery подтверждён: сохранённый verified progress восстановлен с нужного шага, " +
                                    "неопределённый in-flight шаг не повторяется вслепую, terminal state подтверждается без replay, " +
                                    "сетевой pause требует явного продолжения.",
                            silent = silent,
                            success = true,
                            technical = evidence.toString()
                        )
                    }
                } finally {
                    if (!cleanupVerified) {
                        try {
                            AyanaDurableGoalStore(
                                context = applicationContext,
                                storageFileName = testFileName
                            )
                                .clearAcceptanceStorage()
                        } catch (_: Exception) {
                        }
                    }

                    if (Thread.currentThread() === currentAgentThread) {
                        currentAgentThread = null
                    }
                }
            }

        currentAgentThread = worker
        executionKernel.bindThread(worker)
        worker.start()
    }


    private fun isR10_2UnifiedPersonalSearchAcceptanceCommand(
        command: String
    ): Boolean {
        val normalized =
            command
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()
                .removePrefix("аяна ")
                .trim()

        return normalized in
            setOf(
                "проверь единый personal search",
                "проверь единый персональный поиск",
                "проверь единый личный поиск",
                "проверь personal search r10.2",
                "проверь personal search"
            )
    }

    private fun runR10_2UnifiedPersonalSearchAcceptance(
        silent: Boolean
    ) {
        executionPhase(
            phase = "r10_2_unified_personal_search_acceptance",
            executor = "unified_personal_search_contract_v1"
        )

        val commandToken =
            activeCommandToken

        val worker =
            thread(
                start = false,
                name = "AyanaR10_2UnifiedPersonalSearch"
            ) {
                try {
                    val selfTest =
                        try {
                            unifiedPersonalSearchContract.selfTest()
                        } catch (_: Exception) {
                            false
                        }

                    if (!selfTest) {
                        mainHandler.post {
                            if (
                                !isCommandCancelled(commandToken) &&
                                commandToken == activeCommandToken
                            ) {
                                respondAndResume(
                                    text = "R10.2 Unified Personal Search не прошёл внутренний contract self-test.",
                                    silent = silent,
                                    success = false,
                                    technical =
                                        JSONObject()
                                            .put("contract_version", AyanaUnifiedPersonalSearchContract.VERSION)
                                            .put("contract_self_test", false)
                                            .toString()
                                )
                            }
                        }
                        return@thread
                    }

                    val request =
                        AyanaPersonalSearchEngine.Request(
                            query = "AYANA",
                            sources =
                                AyanaPersonalSearchEngine.Source
                                    .values()
                                    .toSet()
                        )

                    val report =
                        try {
                            personalSearchEngine.search(
                                request = request,
                                perSourceLimit = 3,
                                totalLimit = 18
                            )
                        } catch (error: Exception) {
                            mainHandler.post {
                                if (
                                    !isCommandCancelled(commandToken) &&
                                    commandToken == activeCommandToken
                                ) {
                                    respondAndResume(
                                        text = "R10.2 Unified Personal Search не смог выполнить локальный multi-source probe: ${error.message ?: "ошибка локального поиска"}.",
                                        silent = silent,
                                        success = false,
                                        technical =
                                            JSONObject()
                                                .put("contract_version", AyanaUnifiedPersonalSearchContract.VERSION)
                                                .put("contract_self_test", true)
                                                .put("probe_exception", error.javaClass.simpleName)
                                                .toString()
                                    )
                                }
                            }
                            return@thread
                        }

                    if (
                        isCommandCancelled(commandToken) ||
                        commandToken != activeCommandToken
                    ) {
                        return@thread
                    }

                    val evidence =
                        unifiedPersonalSearchContract
                            .inspect(report)
                            .put("contract_self_test", true)
                            .put("probe_query", request.query)
                            .put("personal_search_engine_release", AYANA_PERSONAL_SEARCH_ENGINE_RELEASE)
                            .put("voice_service_release", AYANA_VOICE_SERVICE_RELEASE)
                            .put("accepted_checkpoint", AYANA_ACCEPTED_FEATURE_CHECKPOINT)
                            .put("current_release", AYANA_CURRENT_FEATURE_RELEASE)

                    val accepted =
                        unifiedPersonalSearchContract
                            .acceptanceOk(evidence)

                    if (!accepted) {
                        mainHandler.post {
                            if (
                                !isCommandCancelled(commandToken) &&
                                commandToken == activeCommandToken
                            ) {
                                commandHistoryStore.addEvent(
                                    activeCommandHistoryId,
                                    state = "r10_2_unified_personal_search_not_verified",
                                    message = "R10.2 Unified Personal Search не подтвердил все обязательные локальные источники",
                                    details = evidence.toString().take(3900)
                                )

                                respondAndResume(
                                    text =
                                        "R10.2 Unified Personal Search выполнен fail-closed: не все обязательные источники/индексы подтверждены. Проверь technical evidence.",
                                    silent = silent,
                                    success = false,
                                    technical = evidence.toString()
                                )
                            }
                        }
                        return@thread
                    }

                    evidence
                        .put("r10_2_verified", true)
                        .put("persistent_mutation_detected", false)
                        .put("face_identity_claimed", false)

                    mainHandler.post {
                        if (
                            isCommandCancelled(commandToken) ||
                            commandToken != activeCommandToken
                        ) {
                            return@post
                        }

                        commandHistoryStore.addEvent(
                            activeCommandHistoryId,
                            state = "r10_2_unified_personal_search_verified",
                            message =
                                "R10.2 Unified Personal Search подтверждён реальным local multi-source probe",
                            details = evidence.toString().take(3900)
                        )

                        val sourceCount =
                            evidence.optInt(
                                "registered_source_count",
                                0
                            )

                        val hits =
                            evidence.optInt(
                                "total_hits",
                                0
                            )

                        respondAndResume(
                            text =
                                "R10.2 Unified Personal Search подтверждён: источников=$sourceCount; " +
                                    "история/уведомления/файлы/документы/фото доступны; " +
                                    "локальные OCR/labels и date signals включены; совпадений probe=$hits; " +
                                    "идентификация личности по лицу не используется.",
                            silent = silent,
                            success = true,
                            technical = evidence.toString()
                        )
                    }
                } finally {
                    if (Thread.currentThread() === currentAgentThread) {
                        currentAgentThread = null
                    }
                }
            }

        currentAgentThread = worker
        executionKernel.bindThread(worker)
        worker.start()
    }

    private fun isR10LocalSelfAuditRequest(
        command: String
    ): Boolean {
        val normalized =
            command
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .replace(Regex("\\s+"), " ")
                .trim()

        if (normalized.isBlank()) return false

        if (
            normalized == "проверь локальный самоаудит" ||
            normalized == "проверь локальный self audit" ||
            normalized == "проверь local self audit"
        ) {
            return true
        }

        val explicitAudit =
            normalized.contains("самоаудит") ||
                normalized.contains("self audit") ||
                normalized.contains("self-audit")

        val fullCapabilityInventory =
            (
                normalized.contains("зарегистрированные возможности") ||
                    normalized.contains("зарегистрированных возможностей") ||
                    normalized.contains("зарегистрированные функции") ||
                    normalized.contains("зарегистрированных функций")
                ) &&
                (
                    normalized.contains("подтверж") ||
                        normalized.contains("доступн") ||
                        normalized.contains("огранич") ||
                        normalized.contains("release lineage") ||
                        normalized.contains("верси")
                    )

        return explicitAudit || fullCapabilityInventory
    }

    private fun crossProcessAccessibilityTruth(
        registrySnapshot: JSONObject? = null
    ): JSONObject {
        val runtime =
            registrySnapshot
                ?.optJSONObject("runtime")
                ?: JSONObject()

        val localConnected =
            runtime.optBoolean(
                "accessibility_connected",
                false
            )

        val runningInPerceptionProcess =
            try {
                perceptionBridge.isLocalPerceptionProcess()
            } catch (_: Throwable) {
                false
            }

        val bridge =
            if (!runningInPerceptionProcess) {
                try {
                    perceptionBridge.status()
                } catch (error: Throwable) {
                    JSONObject()
                        .put("success", false)
                        .put("error", error.message ?: error.javaClass.simpleName)
                }
            } else {
                JSONObject()
            }

        val bridgeVersionOk =
            !bridge.has("bridge_version_match") ||
                bridge.optBoolean("bridge_version_match", false)

        val providerProcessOk =
            !bridge.has("provider_process_separated") ||
                bridge.optBoolean("provider_process_separated", false)

        val bridgeConnected =
            bridge.optBoolean("success", false) &&
                bridge.optBoolean("accessibility_connected", false) &&
                bridgeVersionOk &&
                providerProcessOk

        val effectiveConnected =
            localConnected || bridgeConnected

        return JSONObject()
            .put("effective_connected", effectiveConnected)
            .put("local_process_connected", localConnected)
            .put("bridge_connected", bridgeConnected)
            .put("running_in_perception_process", runningInPerceptionProcess)
            .put(
                "source",
                when {
                    localConnected -> "local_process"
                    bridgeConnected -> "perception_bridge"
                    else -> "none"
                }
            )
            .put("screen_evidence_available", bridge.optBoolean("screen_evidence_available", false))
            .put("content_status", bridge.optString("content_status"))
            .put("effective_foreground_package", bridge.optString("effective_foreground_package"))
            .put(
                "window_count",
                bridge.optInt(
                    "window_count",
                    bridge.optInt("raw_window_count", 0)
                )
            )
            .put("bridge_version_match", bridgeVersionOk)
            .put("provider_process_separated", providerProcessOk)
            .put("perception_process_id", bridge.optInt("perception_process_id", -1))
    }

    private fun reconcileCrossProcessAccessibilityRegistry(
        registrySnapshot: JSONObject
    ): JSONObject {
        val reconciled =
            try {
                JSONObject(registrySnapshot.toString())
            } catch (_: Exception) {
                registrySnapshot
            }

        val runtime =
            reconciled.optJSONObject("runtime")
                ?: JSONObject().also {
                    reconciled.put("runtime", it)
                }

        val truth =
            crossProcessAccessibilityTruth(registrySnapshot)

        val effectiveConnected =
            truth.optBoolean("effective_connected", false)

        runtime
            .put("accessibility_connected_legacy_local_process", truth.optBoolean("local_process_connected", false))
            .put("accessibility_connected_cross_process", truth.optBoolean("bridge_connected", false))
            .put("accessibility_connected", effectiveConnected)
            .put("accessibility_truth_source", truth.optString("source", "none"))
            .put("perception_process_id", truth.optInt("perception_process_id", -1))

        if (!effectiveConnected) {
            return reconciled
        }

        val screen =
            try {
                screenIntelligence.getScreenState()
            } catch (_: Throwable) {
                JSONObject()
            }

        val contentState =
            screen.optString(
                "primary_content_state",
                truth.optString("content_status", "unknown")
            )

        val screenReadable =
            contentState == "readable" || contentState == "partial"

        val screenEvidenceUsable =
            screen.optBoolean("success", false) &&
                screen.optBoolean(
                    "execution_evidence_usable",
                    truth.optBoolean("screen_evidence_available", false)
                )

        val effectivePackage =
            screen.optString(
                "effective_foreground_package",
                truth.optString("effective_foreground_package")
            ).trim()

        val windowCount =
            screen.optInt(
                "window_count",
                screen.optInt(
                    "raw_window_count",
                    truth.optInt("window_count", 0)
                )
            )

        val capabilities =
            reconciled.optJSONArray("capabilities")
                ?: return reconciled

        val connectionGated =
            setOf(
                "window_detection",
                "app_task_removal",
                "strict_terminal_verification",
                "settings_intent_attestation",
                "app_detail_permissions_navigation"
            )

        fun applyAvailabilityTruth(
            item: JSONObject,
            availableNow: Boolean
        ) {
            val implemented =
                item.optBoolean("implemented", false)

            val deviceConfirmed =
                item.optBoolean("device_confirmed", false)

            item
                .put("available_now", availableNow)
                .put(
                    "truth_state",
                    when {
                        !implemented -> "UNIMPLEMENTED"
                        !availableNow && deviceConfirmed -> "DEVICE_CONFIRMED_UNAVAILABLE_NOW"
                        !availableNow -> "IMPLEMENTED_UNAVAILABLE_NOW"
                        deviceConfirmed -> "DEVICE_CONFIRMED_AVAILABLE"
                        else -> "IMPLEMENTED_AVAILABLE_UNCONFIRMED"
                    }
                )
        }

        for (index in 0 until capabilities.length()) {
            val item = capabilities.optJSONObject(index) ?: continue
            when (item.optString("id")) {
                in connectionGated ->
                    applyAvailabilityTruth(
                        item = item,
                        availableNow = true
                    )

                "screen_content_reading" ->
                    applyAvailabilityTruth(
                        item = item,
                        availableNow = screenReadable && screenEvidenceUsable
                    )

                "perception_owner_fusion" ->
                    applyAvailabilityTruth(
                        item = item,
                        availableNow =
                            screenEvidenceUsable &&
                                effectivePackage.isNotBlank()
                    )

                "extended_accessibility_semantics" ->
                    applyAvailabilityTruth(
                        item = item,
                        availableNow =
                            screenEvidenceUsable &&
                                effectivePackage.isNotBlank() &&
                                windowCount >= 1
                    )
            }
        }

        return reconciled
    }

    private fun reconcileGitHubCapabilityRegistry(
        registrySnapshot: JSONObject
    ): JSONObject {
        val reconciled =
            try {
                JSONObject(registrySnapshot.toString())
            } catch (_: Exception) {
                registrySnapshot
            }

        val runtime =
            reconciled.optJSONObject("runtime")
                ?: JSONObject().also {
                    reconciled.put("runtime", it)
                }

        val github = githubRepositoryExecutor.runtimeSnapshot()
        val connected = github.optBoolean("connected", false)
        val writeAvailable =
            connected &&
                github.optBoolean("repository_write_available", false)
        val deviceConfirmed =
            github.optBoolean("device_confirmed_write", false)
        val actionsWriteAvailable =
            connected &&
                github.optBoolean("actions_write_available", false)
        val buildDeviceConfirmed =
            github.optBoolean("device_confirmed_build", false)
        val developmentAvailable =
            writeAvailable && actionsWriteAvailable
        val developmentDeviceConfirmed =
            github.optBoolean("development_transaction_device_confirmed", false)

        runtime
            .put("github_repository_executor_version", github.optString("version", AyanaGitHubRepositoryExecutor.VERSION))
            .put("github_repository", github.optString("repository", AyanaGitHubRepositoryExecutor.REPOSITORY_SLUG))
            .put("github_branch", github.optString("branch", AyanaGitHubRepositoryExecutor.BRANCH))
            .put("github_client_id_configured", github.optBoolean("client_id_configured", false))
            .put("github_authorization_pending", github.optBoolean("authorization_pending", false))
            .put("github_repository_connected", connected)
            .put("github_repository_write_available", writeAvailable)
            .put("github_repository_device_confirmed_write", deviceConfirmed)
            .put("github_repository_last_verified_at_ms", github.optLong("last_verified_at_ms", 0L))
            .put("github_actions_permission", github.optString("actions_permission", "unknown"))
            .put("github_actions_write_available", actionsWriteAvailable)
            .put("github_actions_last_verified_at_ms", github.optLong("actions_last_verified_at_ms", 0L))
            .put("github_apk_build_device_confirmed", buildDeviceConfirmed)
            .put("github_apk_build_last_run_id", github.optLong("last_build_run_id", 0L))
            .put("github_apk_build_last_head_sha", github.optString("last_build_head_sha", ""))
            .put("github_apk_build_last_event", github.optString("last_build_event", ""))
            .put("github_apk_build_last_status", github.optString("last_build_status", ""))
            .put("github_apk_build_last_conclusion", github.optString("last_build_conclusion", ""))
            .put("github_apk_build_last_artifact_id", github.optLong("last_build_artifact_id", 0L))
            .put("github_apk_build_last_artifact_digest", github.optString("last_build_artifact_digest", ""))
            .put("github_apk_build_last_artifact_size_bytes", github.optLong("last_build_artifact_size_bytes", 0L))
            .put("github_apk_build_last_verified_at_ms", github.optLong("last_build_verified_at_ms", 0L))
            .put("development_transaction_implemented", true)
            .put("development_transaction_available", developmentAvailable)
            .put("development_transaction_device_confirmed", developmentDeviceConfirmed)
            .put("development_transaction_status", github.optString("development_transaction_status", "none"))
            .put("development_transaction_id", github.optString("development_transaction_id", ""))
            .put("development_transaction_last_commit_sha", github.optString("development_transaction_last_commit_sha", ""))
            .put("development_transaction_last_rollback_commit_sha", github.optString("development_transaction_last_rollback_commit_sha", ""))

        val capabilities = reconciled.optJSONArray("capabilities") ?: JSONArray()

        for (index in 0 until capabilities.length()) {
            val item = capabilities.optJSONObject(index) ?: continue
            when (item.optString("id")) {
                "github_repository_write",
                "github_commit_push" -> {
                    item
                        .put("implemented", true)
                        .put("available_now", writeAvailable)
                        .put("device_confirmed", deviceConfirmed)
                        .put(
                            "truth_state",
                            when {
                                deviceConfirmed && writeAvailable -> "DEVICE_CONFIRMED_AVAILABLE"
                                writeAvailable -> "AVAILABLE_UNCONFIRMED"
                                deviceConfirmed -> "DEVICE_CONFIRMED_UNAVAILABLE_NOW"
                                else -> "IMPLEMENTED_UNAVAILABLE"
                            }
                        )
                        .put(
                            "note",
                            "R10.27.1 fixed-repository GitHub App Device Flow executor; prepare is read-only, mutation requires fresh explicit confirmation and verified blob/commit SHA; repo=${AyanaGitHubRepositoryExecutor.REPOSITORY_SLUG}; branch=${AyanaGitHubRepositoryExecutor.BRANCH}"
                        )
                }

                "development_agent_transaction" -> {
                    item
                        .put("implemented", true)
                        .put("available_now", developmentAvailable)
                        .put("device_confirmed", developmentDeviceConfirmed)
                        .put(
                            "truth_state",
                            when {
                                developmentDeviceConfirmed && developmentAvailable -> "DEVICE_CONFIRMED_AVAILABLE"
                                developmentAvailable -> "AVAILABLE_UNCONFIRMED"
                                developmentDeviceConfirmed -> "DEVICE_CONFIRMED_UNAVAILABLE_NOW"
                                else -> "IMPLEMENTED_UNAVAILABLE"
                            }
                        )
                        .put(
                            "note",
                            "R10.27.3 bounded project-workspace transaction: immutable Git blob snapshot -> exact single replacement -> static integrity checks -> fresh confirmation -> verified commit -> exact push-triggered fixed APK build (no duplicate workflow_dispatch) -> explicit accept or verified rollback; workflows/secrets/arbitrary repos remain blocked"
                        )
                }

                "android_apk_build" -> {
                    item
                        .put("implemented", true)
                        .put("available_now", actionsWriteAvailable)
                        .put("device_confirmed", buildDeviceConfirmed)
                        .put(
                            "truth_state",
                            when {
                                buildDeviceConfirmed && actionsWriteAvailable -> "DEVICE_CONFIRMED_AVAILABLE"
                                actionsWriteAvailable -> "AVAILABLE_UNCONFIRMED"
                                buildDeviceConfirmed -> "DEVICE_CONFIRMED_UNAVAILABLE_NOW"
                                else -> "IMPLEMENTED_UNAVAILABLE"
                            }
                        )
                        .put(
                            "note",
                            "R10.27.2 fixed GitHub Actions APK build executor: exact workflow=${AyanaGitHubRepositoryExecutor.BUILD_WORKFLOW_NAME}; branch=${AyanaGitHubRepositoryExecutor.BRANCH}; explicit confirmation before workflow_dispatch; SUCCESS requires completed conclusion=success plus verified artifact=${AyanaGitHubRepositoryExecutor.APK_ARTIFACT_NAME} with non-zero size and SHA-256 digest"
                        )
                }
            }
        }

        return reconciled
    }

