    private fun inferOriginalGoalTerminalCriterion(
        originalGoal: String
    ): String {
        val normalized =
            repairCommonRecognitionForRouting(
                normalizeRecognitionText(
                    originalGoal
                )
            )

        val inputIntent =
            (
                normalized.contains("введи") ||
                    normalized.contains("ввести") ||
                    normalized.contains("напечатай") ||
                    normalized.contains("впиши")
                ) &&
                (
                    normalized.contains("текст") ||
                        normalized.contains("поле")
                    )

        if (inputIntent) {
            return "input_text"
        }

        val clickIntent =
            normalized.startsWith("нажми ") ||
                normalized.startsWith("выбери ") ||
                normalized.startsWith("кликни ")

        if (clickIntent) {
            return "semantic_click"
        }

        val scrollIntent =
            normalized.contains("прокрути") ||
                normalized.contains("пролистай")

        if (scrollIntent) {
            return "scroll"
        }

        if (
            isLocalScreenStateRequest(
                normalized
            )
        ) {
            return "screen_read"
        }

        return ""
    }

    private fun toolSatisfiesOriginalGoalTerminalCriterion(
        criterion: String,
        toolName: String,
        arguments: JSONObject,
        result: JSONObject
    ): Boolean {
        val verified =
            result.optBoolean(
                "verified",
                result.optBoolean(
                    "success",
                    false
                )
            )

        if (!verified) {
            return false
        }

        return when (criterion) {
            "input_text" ->
                toolName ==
                    "input_screen_text" ||
                    (
                        toolName ==
                            "execute_android_goal" &&
                            result
                                .optString(
                                    "goal_type"
                                )
                                .lowercase(
                                    Locale.ROOT
                                )
                                .contains(
                                    "input"
                                )
                        )

            "semantic_click" ->
                toolName in
                    setOf(
                        "click_text",
                        "click_screen_element"
                    ) ||
                    (
                        toolName ==
                            "execute_android_goal" &&
                            result
                                .optString(
                                    "goal_type"
                                )
                                .lowercase(
                                    Locale.ROOT
                                )
                                .contains(
                                    "click"
                                )
                        )

            "scroll" ->
                toolName ==
                    "scroll_screen" ||
                    (
                        toolName ==
                            "execute_android_goal" &&
                            result
                                .optString(
                                    "goal_type"
                                )
                                .lowercase(
                                    Locale.ROOT
                                )
                                .contains(
                                    "scroll"
                                )
                        )

            "screen_read" ->
                toolName ==
                    "get_screen_state"

            else ->
                true
        }
    }

    private fun originalGoalTerminalCriterionFailureMessage(
        criterion: String
    ): String =
        when (criterion) {
            "input_text" ->
                "Исходная команда не выполнена: требуемый текст не подтверждён в целевом поле. Успех другого действия не считается выполнением ввода."

            "semantic_click" ->
                "Исходная команда не выполнена: требуемое нажатие не подтверждено. Успех другого действия не считается выполнением этой цели."

            "scroll" ->
                "Исходная команда не выполнена: требуемая прокрутка не подтверждена."

            "screen_read" ->
                "Исходная команда не выполнена: фактическое состояние экрана не подтверждено."

            else ->
                "Исходная цель не подтверждена фактическим результатом."
        }

    private fun shouldApplyCompletionContract(
        request: String
    ): Boolean {
        val normalized =
            request
                .lowercase(
                    Locale.ROOT
                )
                .replace(
                    'ё',
                    'е'
                )
                .replace(
                    Regex("\\s+"),
                    " "
                )
                .trim()

        // Input nouns such as «исходный документ» describe context, not a
        // requested output artifact. Completion validation activates only when
        // the user asks to create/deliver/transform an output or explicitly asks
        // for a textual deliverable such as an analysis/report/table.
        val artifactOutputIntent =
            listOf(
                "создай",
                "создать",
                "сделай",
                "сгенер",
                "сохрани",
                "экспорт",
                "построй график",
                "построить график",
                "новый файл",
                "готовый файл",
                "создай новый"
            )
                .any {
                    normalized.contains(
                        it
                    )
                }

        val textualDeliverableIntent =
            normalized.contains("проанализ") ||
                normalized.startsWith("дай анализ") ||
                normalized.startsWith("сделай анализ") ||
                normalized.startsWith("подготовь отчет") ||
                normalized.startsWith("подготовь отчёт") ||
                normalized.startsWith("составь отчет") ||
                normalized.startsWith("составь отчёт") ||
                normalized.startsWith("сделай таблиц")

        return artifactOutputIntent ||
            textualDeliverableIntent
    }

    private fun shouldFinishAfterSingleTool(
        originalGoal: String,
        toolName: String,
        arguments: JSONObject,
        result: JSONObject
    ): Boolean {

        if (
            !result.optBoolean(
                "success",
                false
            )
        ) {
            return false
        }

        val normalizedGoal =
            repairCommonRecognitionForRouting(
                normalizeRecognitionText(
                    originalGoal
                )
            )

        if (
            isMultiStepAgentCommand(
                normalizedGoal
            )
        ) {
            return false
        }

        if (
            toolName in
            setOf(
                "press_home",
                "press_back"
            ) &&
            isTrueAppCloseRequest(
                originalGoal
            )
        ) {
            return false
}

        // Only terminal, low-risk actions that already have an observable local
        // success result are eligible. UI clicks/text entry remain orchestrated.
        return toolName in
            setOf(
                "open_app",
                "open_settings",
                "open_app_info",
                "open_app_settings",
                "press_back",
                "press_home",
                "change_volume",
                "youtube_search",
                "google_search",
                "map_search"
            )
    }

    private fun localSingleToolReply(
        toolName: String,
        arguments: JSONObject,
        result: JSONObject
    ): String {

        return when (toolName) {
            "open_app" ->
                "Открываю ${arguments.optString("name", "приложение")}."

            "open_settings" -> {
                val section =
                    arguments.optString(
                        "section"
                    )

                when (section) {
                    "bluetooth" -> "Настройки Bluetooth открыты."
                    "wifi" -> "Настройки Wi-Fi открыты."
                    "sound" -> "Настройки звука открыты."
                    "display" -> "Настройки экрана открыты."
                    "apps" -> "Настройки приложений открыты."
                    "accessibility" -> "Специальные возможности открыты."
                    else -> result.optString(
                        "message",
                        "Настройки открыты."
                    )
                }
            }

            "open_app_info" ->
                "Информация о приложении ${arguments.optString("name", "")} открыта."
                    .replace(
                        "  ",
                        " "
                    )

            "open_app_settings" -> {
                val app =
                    arguments.optString(
                        "name"
                    )

                when (
                    arguments.optString(
                        "section"
                    )
                ) {
                    "notifications" -> "Уведомления приложения $app открыты."
                    "open_by_default" -> "Параметры открытия приложения $app открыты."
                    "language" -> "Языковые настройки приложения $app открыты."
                    else -> "Настройки приложения $app открыты."
                }
            }

            "press_back" -> "Назад."
            "press_home" -> "Главный экран."
            "change_volume" -> "Громкость изменена."
            "youtube_search" -> "Открываю поиск в YouTube."
            "google_search" -> "Открываю поиск Google."
            "map_search" -> "Открываю поиск на карте."
            else ->
                result.optString(
                    "message",
                    "Готово."
                )
        }
    }

    private fun isVideoAudioAnalysisRequest(
        prompt: String
    ): Boolean {
        val normalized =
            prompt
                .lowercase(
                    Locale.ROOT
                )
                .replace(
                    'ё',
                    'е'
                )
                .replace(
                    Regex("\\s+"),
                    " "
                )
                .trim()

        val audioScope =
            normalized.contains("звук") ||
                normalized.contains("аудио") ||
                normalized.contains("речь") ||
                normalized.contains("говорят") ||
                normalized.contains("голос") ||
                normalized.contains("музык") ||
                normalized.contains("слышно")

        val transcriptionScope =
            normalized.contains("расшифр") ||
                normalized.contains("транскриб") ||
                normalized.contains("дословно") ||
                normalized.contains("временн") ||
                normalized.contains("таймкод")

        return audioScope ||
            transcriptionScope
    }

    private fun recordMultimodalPerformanceTelemetry(
        totalMs: Long,
        prepareMs: Long,
        uploadMs: Long,
        headersWaitMs: Long,
        bodyReadMs: Long,
        jsonParseMs: Long,
        requestBytes: Int,
        responseBytes: Int,
        httpCode: Int,
        kind: String
    ) {
        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "multimodal_performance",
            message = "Multimodal phase telemetry",
            details =
                (
                    "kind=${kind.take(40)}; " +
                        "total_ms=${totalMs.coerceAtLeast(0L)}; " +
                        "prepare_ms=${prepareMs.coerceAtLeast(0L)}; " +
                        "upload_ms=${uploadMs.coerceAtLeast(0L)}; " +
                        "headers_wait_ms=${headersWaitMs.coerceAtLeast(0L)}; " +
                        "body_read_ms=${bodyReadMs.coerceAtLeast(0L)}; " +
                        "json_parse_ms=${jsonParseMs.coerceAtLeast(0L)}; " +
                        "request_bytes=${requestBytes.coerceAtLeast(0)}; " +
                        "response_bytes=${responseBytes.coerceAtLeast(0)}; " +
                        "http_code=$httpCode"
                    )
                    .take(
                        1000
                    )
        )
    }

    private fun multimodalManifestContainsKind(
        manifest: JSONObject,
        targetKind: String
    ): Boolean {
        val kind = manifest.optString("kind")
        if (kind == targetKind) {
            return true
        }
        if (kind != AyanaMultimodalAttachmentManager.KIND_BATCH) {
            return false
        }

        val items = manifest.optJSONArray("items") ?: return false
        for (index in 0 until items.length()) {
            val item = items.optJSONObject(index) ?: continue
            if (multimodalManifestContainsKind(item, targetKind)) {
                return true
            }
        }
        return false
    }

    private fun multimodalManifestItemCount(
        manifest: JSONObject
    ): Int {
        return if (
            manifest.optString("kind") ==
            AyanaMultimodalAttachmentManager.KIND_BATCH
        ) {
            manifest.optJSONArray("items")?.length() ?: 0
        } else {
            1
        }
    }

    private fun multimodalAttachmentCountLabel(
        count: Int
    ): String {
        val safe = count.coerceAtLeast(0)
        val mod100 = safe % 100
        val mod10 = safe % 10
        val noun =
            when {
                mod100 in 11..14 -> "вложений"
                mod10 == 1 -> "вложение"
                mod10 in 2..4 -> "вложения"
                else -> "вложений"
            }
        return "$safe $noun"
    }

    private fun isMultiAttachmentDocxTranslationRequest(
        prompt: String,
        manifest: JSONObject
    ): Boolean {
        if (
            manifest.optString("kind") !=
            AyanaMultimodalAttachmentManager.KIND_BATCH
        ) {
            return false
        }

        val items = manifest.optJSONArray("items") ?: return false
        for (index in 0 until items.length()) {
            val item = items.optJSONObject(index) ?: continue
            if (
                isStylePreservingDocxTranslationRequest(
                    prompt = prompt,
                    manifest = item
                )
            ) {
                return true
            }
        }
        return false
    }

    private fun executeMultimodalCommand(
        prompt: String,
        manifestText: String
    ) {

        // v12.9.0: multimodal validation, file handling and network/model work are
        // never executed on Android's main looper.
        if (Looper.myLooper() == Looper.getMainLooper()) {
            val promptSnapshot =
                prompt
            val manifestSnapshot =
                manifestText

            thread(
                start = true,
                name = "AyanaMultimodalCommand"
            ) {
                synchronized(
                    commandDispatchLock
                ) {
                    if (!shuttingDown) {
                        executeMultimodalCommand(
                            prompt = promptSnapshot,
                            manifestText = manifestSnapshot
                        )
                    }
                }
            }
            return
        }

        stopSherpaListening()
        listenMode = ListenMode.BUSY
        cancelRequested = false
        activeCommandToken = ++commandGeneration
        val commandToken = activeCommandToken

        val manifest =
            try {
                JSONObject(manifestText)
            } catch (_: Exception) {
                activeCommandHistoryId =
                    commandHistoryStore.begin(
                        command = "$prompt [мультимодальное вложение]",
                        source = "text"
                    )
                beginExecutionSession(
                    objective = prompt,
                    source = "text",
                    lane = "multimodal",
                    executor = "multimodal_manifest_validator"
                )
                respondAndResume(
                    "Вложение повреждено или уже недоступно.",
                    silent = true,
                    success = false,
                    technical = "invalid_multimodal_manifest"
                )
                return
            }

        // Defense in depth: MainActivity normally keeps an attachment pending when
        // the typed command is clearly a deterministic Android/local command. If a
        // malformed/old client still sends such a command through the multimodal
        // action, never let the attachment bypass AYANA's execution router.
        if (
            !AyanaMultimodalAttachmentManager
                .shouldUseAttachmentForCommand(
                    prompt
                )
        ) {
            try {
                AyanaMultimodalAttachmentManager(applicationContext)
                    .cleanupPrepared(manifest)
            } catch (_: Exception) {
            }
            executeCommand(
                originalCommand = prompt,
                silent = true
            )
            return
        }

        // FILE & DOCUMENT ENGINE v12.7: a DOCX translation request is an output
        // transformation, not an ordinary multimodal Q&A turn. Route it to the
        // style-preserving OOXML executor so success requires a real new DOCX.
        if (
            isStylePreservingDocxTranslationRequest(
                prompt = prompt,
                manifest = manifest
            )
        ) {
            executeDocxTranslationCommand(
                prompt = prompt,
                manifest = manifest
            )
            return
        }

        if (
            isMultiAttachmentDocxTranslationRequest(
                prompt = prompt,
                manifest = manifest
            )
        ) {
            activeCommandHistoryId =
                commandHistoryStore.begin(
                    command = "$prompt [несколько вложений]",
                    source = "text"
                )
            beginExecutionSession(
                objective = prompt,
                source = "text",
                lane = "multimodal",
                executor = "multimodal_batch_guard"
            )
            try {
                AyanaMultimodalAttachmentManager(applicationContext)
                    .cleanupPrepared(manifest)
            } catch (_: Exception) {
            }
            respondUnsupportedAndResume(
                text =
                    "Одновременный перевод нескольких вложений с созданием новых DOCX-файлов пока не поддерживается. Выберите один DOCX — тогда AYANA сохранит оформление и создаст проверенный переведённый файл.",
                silent = true,
                technical =
                    "multi_attachment_docx_translation_unsupported; fail_closed=true"
            )
            return
        }

        // A newly attached artifact starts a fresh grounded multimodal context.
        // On success the Worker returns a Responses response_id which becomes the
        // next Agent Core previous_response_id. On failure/cancel we intentionally
        // keep this null rather than leaking context from an older attachment.
        agentPreviousResponseId =
            null

        activeCommandHistoryId =
            commandHistoryStore.begin(
                command = "$prompt [мультимодальное вложение]",
                source = "text"
            )

        beginExecutionSession(
            objective = prompt,
            source = "text",
            lane = "multimodal",
            executor = "multimodal_executor"
        )

        if (
            multimodalManifestContainsKind(
                manifest = manifest,
                targetKind =
                    AyanaMultimodalAttachmentManager.KIND_VIDEO_VISUAL
            ) &&
            isVideoAudioAnalysisRequest(
                prompt
            )
        ) {
            try {
                AyanaMultimodalAttachmentManager(applicationContext)
                    .cleanupPrepared(
                        manifest
                    )
            } catch (_: Exception) {
            }

            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "unsupported_video_audio",
                message = "Запрошен аудиоанализ видео, но текущий video pipeline передаёт только кадры",
                details =
                    "kind=video_visual; audio_analysis=false; transcription_engine=unimplemented"
            )

            respondUnsupportedAndResume(
                text =
                    "Текущая версия AYANA получает из видео только ограниченную выборку визуальных кадров и не получает звуковую дорожку. Поэтому дословная расшифровка речи, анализ звука и таймкоды по аудио сейчас не поддерживаются. Повторная отправка этого видео или отдельного аудиофайла не добавит эту возможность, пока Audio Transcription Engine не реализован.",
                silent = true,
                technical =
                    "video_audio_unavailable; audio_analysis=false"
            )
            return
        }

        val displayName =
            manifest.optString("display_name", "вложение")
                .trim()
                .take(160)
                .ifBlank { "вложение" }

        capabilityRegistry.recordCommandContext(
            source = "text",
            ttsExpected = false
        )

        val attachmentCount =
            multimodalManifestItemCount(
                manifest
            )

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "multimodal_attachment",
            message =
                if (attachmentCount > 1) {
                    "Вложения подготовлены для совместного мультимодального анализа"
                } else {
                    "Вложение подготовлено для мультимодального анализа"
                },
            details =
                "kind=${manifest.optString("kind")}; items=$attachmentCount; " +
                    "name=${displayName.take(120)}; mime=${manifest.optString("mime_type").take(80)}"
        )

        broadcastStatus(
            if (attachmentCount > 1) {
                "Анализирую ${multimodalAttachmentCountLabel(attachmentCount)}…"
            } else {
                "Анализирую $displayName…"
            },
            STATE_THINKING
        )

        executionPhase(
            phase = "multimodal_network",
            executor = "multimodal_executor"
        )

        // v12.10.1 cancellation modality truth: this lane is text-authored.
        // Ambient speech must never cancel it. UI/button STOP remains available
        // through ACTION_CANCEL_COMMAND exactly as for text Agent Core.
        stopCancelListenerWatchdog()
        stopSherpaListening()
        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "cancel_listener_text_isolated",
            message = "Текстовый мультимодальный анализ выполняется без фонового микрофонного STOP",
            details =
                "lane=multimodal; source=text; button_stop_available=true; " +
                    "execution=${executionKernel.current()?.id.orEmpty()}"
        )

        val worker =
            thread(
                start = false,
                name = "AyanaMultimodalCore"
            ) {
                try {
                    val result =
                        callMultimodalCore(
                            prompt = prompt,
                            manifest = manifest
                        )

                    if (
                        cancelRequested ||
                        shuttingDown ||
                        commandToken != activeCommandToken
                    ) {
                        return@thread
                    }

                    val success = result.optBoolean("success", false)
                    val responseId =
                        result.optString("response_id")
                            .trim()
                    val reply = result.optString(
                        "reply",
                        if (success) {
"Анализ завершён."
                        } else {
                            "Не удалось проанализировать вложение."
                        }
                    ).trim()

                    mainHandler.post {
                        if (
                            !cancelRequested &&
                            !shuttingDown &&
                            commandToken == activeCommandToken
                        ) {
                            agentPreviousResponseId =
                                if (success && responseId.isNotBlank()) {
                                    responseId
                                } else {
                                    null
                                }

                            if (success && responseId.isNotBlank()) {
                                commandHistoryStore.addEvent(
                                    activeCommandHistoryId,
                                    state = "multimodal_context_linked",
                                    message = "Мультимодальный контекст сохранён для следующего вопроса",
                                    details = "response_id=${responseId.take(120)}"
                                )
                            }

                            respondAndResume(
                                reply.ifBlank {
                                    if (success) "Анализ завершён." else "Не удалось проанализировать вложение."
                                },
                                silent = true,
                                success = success,
                                technical = result.optString("technical").take(500)
                            )
                        }
                    }
                } catch (error: Exception) {
                    if (
                        !cancelRequested &&
                        !shuttingDown &&
                        commandToken == activeCommandToken
                    ) {
                        mainHandler.post {
                            respondAndResume(
                                "Не удалось проанализировать вложение: ${error.message ?: "ошибка соединения"}.",
                                silent = true,
                                success = false,
                                technical = error.javaClass.simpleName
                            )
                        }
                    }
                } finally {
                    try {
                        AyanaMultimodalAttachmentManager(applicationContext)
                            .cleanupPrepared(manifest)
                    } catch (_: Exception) {
                    }

                    if (Thread.currentThread() === currentAgentThread) {
                        currentAgentThread = null
                    }
                }
            }

        currentAgentThread = worker
        executionKernel.bindThread(worker)
        worker.start()
    }


    private data class DocxTranslationTarget(
        val code: String,
        val label: String
    )

    private fun isStylePreservingDocxTranslationRequest(
        prompt: String,
        manifest: JSONObject
    ): Boolean {
        val normalized = normalizeRecognitionText(prompt)
        val asksTranslation =
            normalized.contains("перевед") ||
                normalized.contains("перевести") ||
                normalized.contains("перевод документа") ||
                normalized.contains("translate") ||
                normalized.contains("translation")

        if (!asksTranslation) {
            return false
        }

        val displayName = manifest
            .optString("display_name")
            .trim()
            .lowercase(Locale.ROOT)
        val mime = manifest
            .optString("mime_type")
            .trim()
            .lowercase(Locale.ROOT)

        return displayName.endsWith(".docx") ||
            mime == "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
    }

    private fun resolveDocxTranslationTarget(
        prompt: String
    ): DocxTranslationTarget? {
        val text = normalizeRecognitionText(prompt)

        return when {
            Regex("(?:на|в)\\s+(?:русск(?:ий|ого|ом)|русский язык)|по[-\\s]?русски")
                .containsMatchIn(text) ->
                DocxTranslationTarget("ru", "русский")
Regex("(?:на|в)\\s+(?:английск(?:ий|ого|ом)|английский язык)|по[-\\s]?английски")
                .containsMatchIn(text) ->
                DocxTranslationTarget("en", "английский")

            Regex("(?:на|в)\\s+(?:кыргызск(?:ий|ого|ом)|киргизск(?:ий|ого|ом)|кыргызский язык|киргизский язык)|по[-\\s]?(?:кыргызски|киргизски)")
                .containsMatchIn(text) ->
                DocxTranslationTarget("ky", "кыргызский")

            Regex("(?:на|в)\\s+(?:немецк(?:ий|ого|ом)|немецкий язык)|по[-\\s]?немецки")
                .containsMatchIn(text) ->
                DocxTranslationTarget("de", "немецкий")

            Regex("(?:на|в)\\s+(?:французск(?:ий|ого|ом)|французский язык)|по[-\\s]?французски")
                .containsMatchIn(text) ->
                DocxTranslationTarget("fr", "французский")

            Regex("(?:на|в)\\s+(?:испанск(?:ий|ого|ом)|испанский язык)|по[-\\s]?испански")
                .containsMatchIn(text) ->
                DocxTranslationTarget("es", "испанский")

            Regex("(?:на|в)\\s+(?:турецк(?:ий|ого|ом)|турецкий язык)|по[-\\s]?турецки")
                .containsMatchIn(text) ->
                DocxTranslationTarget("tr", "турецкий")

            else -> null
        }
    }

    private fun executeDocxTranslationCommand(
        prompt: String,
        manifest: JSONObject
    ) {
        val commandToken = activeCommandToken
        val displayName = manifest
            .optString("display_name", "document.docx")
            .trim()
            .take(160)
            .ifBlank { "document.docx" }

        activeCommandHistoryId =
            commandHistoryStore.begin(
                command = "$prompt [DOCX перевод: $displayName]",
                source = "text"
            )

        beginExecutionSession(
            objective = prompt,
            source = "text",
            lane = "document_translation",
            executor = "docx_translation_executor"
        )

        val target = resolveDocxTranslationTarget(prompt)
        if (target == null) {
            try {
                AyanaMultimodalAttachmentManager(applicationContext)
                    .cleanupPrepared(manifest)
            } catch (_: Exception) {
            }
            respondAndResume(
                "Укажите язык перевода, например: «переведи документ на русский».",
                silent = true,
                success = false,
                technical = "docx_translation_target_missing"
            )
            return
        }

        capabilityRegistry.recordCommandContext(
            source = "text",
            ttsExpected = false
        )

        broadcastStatus(
            "Перевожу $displayName на ${target.label}…",
            STATE_THINKING
        )
        updateNotification(
            "AYANA переводит Word-документ…"
        )

        executionPhase(
            phase = "docx_inspect",
            executor = "docx_translation_executor"
        )

        stopCancelListenerWatchdog()
        stopSherpaListening()
        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "cancel_listener_text_isolated",
            message = "Текстовый перевод DOCX выполняется без фонового микрофонного STOP",
            details =
                "lane=document_translation; source=text; button_stop_available=true; " +
                    "execution=${executionKernel.current()?.id.orEmpty()}"
        )

        val worker =
            thread(
                start = false,
                name = "AyanaDocxTranslation"
            ) {
                var outputFile: File? = null
                try {
                    val sourceFile = validatedMultimodalCacheFile(
                        manifest.optString("path")
                    )

                    val inspection = docxTranslationEngine.inspect(sourceFile)
                    if (!inspection.valid) {
                        mainHandler.post {
                            if (
                                commandToken == activeCommandToken &&
                                !shuttingDown &&
                                !cancelRequested
                            ) {
                                respondAndResume(
                                    "Не удалось подготовить Word-документ к переводу.",
                                    silent = true,
                                    success = false,
                                    technical = "docx_inspect=${inspection.reason}"
                                )
                            }
                        }
                        return@thread
                    }

                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state = "docx_translation_plan",
                        message = "DOCX разобран без изменения структуры",
                        details =
                            "segments=${inspection.segments.size}; " +
                                "inflated_bytes=${inspection.inflatedBytes}; entries=${inspection.sourceEntries}; " +
                                "target=${target.code}"
                    )

                    val translated = linkedMapOf<String, String>()
                    val batches = buildDocxTranslationBatches(inspection.segments)
                    executionPhase(
                        phase = "docx_translate_batches",
                        executor = "docx_translation_executor"
                    )

                    for ((batchIndex, batch) in batches.withIndex()) {
                        if (isCommandCancelled(commandToken)) {
                            return@thread
                        }

                        var result = callDocxTranslationBatch(
                            userRequest = prompt,
                            target = target,
                            segments = batch
                        )

                        if (
                            !result.optBoolean("success", false) &&
                            !isCommandCancelled(commandToken)
                        ) {
                            // One bounded retry for malformed/partial structured output.
                            result = callDocxTranslationBatch(
                                userRequest = prompt,
                                target = target,
                                segments = batch
                            )
                        }

                        if (!result.optBoolean("success", false)) {
                            if (isCommandCancelled(commandToken)) {
                                return@thread
                            }
                            val technical = result
                                .optString("technical", "docx_translation_batch_failed")
                                .take(700)
                            mainHandler.post {
                                if (
                                    commandToken == activeCommandToken &&
                                    !shuttingDown &&
                                    !cancelRequested
                                ) {
                                    respondAndResume(
                                        "Перевод Word-документа не завершён: один из фрагментов не прошёл проверку.",
                                        silent = true,
                                        success = false,
                                        technical = technical
                                    )
                                }
                            }
                            return@thread
                        }

                        val items = result.optJSONArray("translations") ?: JSONArray()
                        for (i in 0 until items.length()) {
                            val item = items.optJSONObject(i) ?: continue
                            val id = item.optString("id").trim()
                            val text = item.optString("text")
                            if (id.isNotBlank()) {
                                translated[id] = text
                            }
                        }

                        val expectedIds = batch.map { it.id }.toSet()
                        if (!translated.keys.containsAll(expectedIds)) {
                            mainHandler.post {
                                if (
                                    commandToken == activeCommandToken &&
                                    !shuttingDown &&
                                    !cancelRequested
                                ) {
                                    respondAndResume(
                                        "Перевод Word-документа остановлен: ответ перевода оказался неполным.",
                                        silent = true,
                                        success = false,
                                        technical = "translation_ids_missing_batch_${batchIndex + 1}"
                                    )
                                }
                            }
                            return@thread
                        }

                        commandHistoryStore.addEvent(
                            activeCommandHistoryId,
                            state = "docx_translation_progress",
                            message = "Переведён пакет ${batchIndex + 1} из ${batches.size}",
                            details = "segments=${batch.size}; translated_total=${translated.size}"
                        )
                    }

                    if (isCommandCancelled(commandToken)) {
                        return@thread
                    }

                    executionPhase(
                        phase = "docx_transform",
                        executor = "docx_translation_executor"
                    )

                    // Never reuse user-controlled displayName as a filesystem path.
                    // The visible output name is sanitized separately by ArtifactEngine;
                    // the private transform target is an opaque AYANA-owned cache path.
                    outputFile = File(
                        File(cacheDir, "ayana_docx_translation").apply { mkdirs() },
                        "${UUID.randomUUID()}.docx"
                    )

                    val transform = docxTranslationEngine.transform(
                        sourceFile = sourceFile,
                        outputFile = outputFile!!,
                        segments = inspection.segments,
                        translatedById = translated
                    )

                    if (!transform.success || isCommandCancelled(commandToken)) {
                        if (!isCommandCancelled(commandToken)) {
                            mainHandler.post {
                                if (
                                    commandToken == activeCommandToken &&
                                    !shuttingDown &&
                                    !cancelRequested
                                ) {
                                    respondAndResume(
                                        "Перевод выполнен, но новый Word-файл не прошёл проверку целостности.",
                                        silent = true,
                                        success = false,
                                        technical = "docx_transform=${transform.reason}"
                                    )
                                }
                            }
                        }
                        return@thread
                    }

                    executionPhase(
                        phase = "artifact_publish",
                        executor = "docx_translation_executor"
                    )

                    val outputName = docxTranslationEngine.translatedFileName(
                        sourceName = displayName,
                        targetLanguageCode = target.code
                    )

                    val published = artifactEngine.publishPreparedFile(
                        sourceFile = outputFile!!,
                        kind = "docx",
                        filename = outputName,
                        declaredKindOverride = "document",
                        tryBeginPublish = { detail ->
                            executionKernel.tryBeginIrreversibleDispatch(
                                kind = "artifact_publish",
                                detail = detail
                            )
                        },
                        onPublishAccepted = { detail ->
                            executionKernel.markIrreversibleDispatchAccepted(detail)
                        },
                        onPublishReconciliationStarted = { detail ->
                            executionKernel.markSideEffectReconciliationStarted(detail)
                        },
                        onPublishReconciled = { committed, detail ->
                            executionKernel.markSideEffectReconciled(
                                committed = committed,
                                detail = detail
                            )
                        }
                    )

                    val publishedSuccess = published.optBoolean("success", false)
                    val technical = published.toString().take(1800)

                    mainHandler.post {
                        if (
                            commandToken != activeCommandToken ||
                            shuttingDown
                        ) {
                            return@post
                        }

                        if (publishedSuccess) {
                            val finalName = published
                                .optString("name", outputName)
                                .ifBlank { outputName }
                            val finalMessage =
                                "Перевод готов. Word-файл сохранён в Downloads/AYANA: $finalName"

                            commandHistoryStore.addEvent(
                                activeCommandHistoryId,
                                state = "artifact_verified",
                                message = "Переведённый DOCX создан и проверен",
                                details = technical
                            )

                            if (cancelRequested) {
                                // STOP arrived after actual publication. Preserve factual
                                // SUCCESS and cancel only the remaining presentation path.
                                commandHistoryStore.addEvent(
                                    activeCommandHistoryId,
                                    state = "cancel_after_commit",
                                    message = "STOP получен после подтверждённой публикации DOCX",
                                    details = "semantic_terminal=SUCCESS; source=${pendingCancelSource.ifBlank { "voice" }}"
                                )
                                finishActiveCommandHistory(
                                    success = true,
                                    result = finalMessage,
                                    technical = technical
                                )
                                broadcastStatus(finalMessage, STATE_SUCCESS)
                                updateNotification("Перевод сохранён • STOP после commit")
                                resumeAfterCancellation(attempt = 0)
                            } else {
                                respondAndResume(
                                    finalMessage,
                                    silent = true,
                                    success = true,
                                    technical = technical
                                )
                            }
                        } else if (cancelRequested) {
                            val state = executionKernel.sideEffectState()
                            if (
                                state == AyanaExecutionKernel.SideEffectState.VERIFIED_NOT_COMMITTED ||
                                published.optString("reason") == "cancelled_before_artifact_publish"
                            ) {
                                finishDeferredCancellationFromExecutor(
                                    source = pendingCancelSource.ifBlank { "voice" }
                                )
                            } else {
                                val message = published.optString(
                                    "message",
                                    "Переведённый Word-файл не удалось сохранить."
                                )
                                finishActiveCommandHistory(
                                    success = false,
                                    result = message,
technical = technical
                                )
                                broadcastStatus(message, STATE_ERROR)
                                updateNotification("Ошибка сохранения перевода")
                                resumeAfterCancellation(attempt = 0)
                            }
                        } else {
                            respondAndResume(
                                published.optString(
                                    "message",
                                    "Переведённый Word-файл не удалось сохранить."
                                ),
                                silent = true,
                                success = false,
                                technical = technical
                            )
                        }
                    }
                } catch (error: Exception) {
                    if (!isCommandCancelled(commandToken)) {
                        mainHandler.post {
                            if (
                                commandToken == activeCommandToken &&
                                !shuttingDown &&
                                !cancelRequested
                            ) {
                                respondAndResume(
                                    "Не удалось перевести Word-документ: ${error.message ?: "ошибка обработки"}.",
                                    silent = true,
                                    success = false,
                                    technical = error.javaClass.simpleName
                                )
                            }
                        }
                    }
                } finally {
                    try {
                        outputFile?.delete()
                    } catch (_: Exception) {
                    }
                    try {
                        AyanaMultimodalAttachmentManager(applicationContext)
                            .cleanupPrepared(manifest)
                    } catch (_: Exception) {
                    }
                    if (Thread.currentThread() === currentAgentThread) {
                        currentAgentThread = null
                    }
                }
            }

        currentAgentThread = worker
        executionKernel.bindThread(worker)
        worker.start()
    }

    private fun buildDocxTranslationBatches(
        segments: List<AyanaDocxTranslationEngine.Segment>
    ): List<List<AyanaDocxTranslationEngine.Segment>> {
        val result = ArrayList<List<AyanaDocxTranslationEngine.Segment>>()
        var current = ArrayList<AyanaDocxTranslationEngine.Segment>()
        var currentChars = 0

        fun flush() {
            if (current.isNotEmpty()) {
                result += current.toList()
                current = ArrayList()
                currentChars = 0
            }
        }

        for (segment in segments) {
            val chars = segment.translatableText.length
            if (
                current.isNotEmpty() &&
                (current.size >= MAX_DOCX_TRANSLATION_SEGMENTS_PER_BATCH ||
                    currentChars + chars > MAX_DOCX_TRANSLATION_CHARS_PER_BATCH)
            ) {
                flush()
            }
            current += segment
            currentChars += chars
        }
        flush()
        return result
    }

    private fun callDocxTranslationBatch(
        userRequest: String,
        target: DocxTranslationTarget,
        segments: List<AyanaDocxTranslationEngine.Segment>
    ): JSONObject {
        var connection: HttpsURLConnection? = null

        try {
            val items = JSONArray()
            segments.forEach { segment ->
                items.put(
                    JSONObject()
                        .put("id", segment.id)
                        .put("text", segment.translatableText)
                )
            }

            val requestJson = JSONObject()
                .put("user_request", userRequest.take(1800))
                .put("target_language_code", target.code)
                .put("target_language", target.label)
                .put("segments", items)

            connection =
                URL("$WORKER_URL/translate-docx-batch")
                    .openConnection() as HttpsURLConnection

            currentAgentConnection = connection
            executionKernel.bindConnection(connection)
            connection.requestMethod = "POST"
            connection.setRequestProperty("Content-Type", "application/json")
            connection.connectTimeout = DOCX_TRANSLATION_CONNECT_TIMEOUT_MS
            connection.readTimeout = DOCX_TRANSLATION_READ_TIMEOUT_MS
            connection.doOutput = true

            connection.outputStream.use { output ->
                output.write(requestJson.toString().toByteArray(Charsets.UTF_8))
            }

            val code = connection.responseCode
            val stream = if (code in 200..299) connection.inputStream else connection.errorStream
            val raw = stream?.bufferedReader(Charsets.UTF_8)?.use { it.readText() }.orEmpty()
            val response = try { JSONObject(raw) } catch (_: Exception) { JSONObject() }

            if (code !in 200..299) {
                return JSONObject()
                    .put("success", false)
                    .put("technical", "http=$code; ${response.optString("error").take(260)}")
            }

            val translations = response.optJSONArray("translations") ?: JSONArray()
            val expectedIds = segments.map { it.id }.toSet()
            val returnedIds = mutableSetOf<String>()
            var invalid = false

            for (i in 0 until translations.length()) {
                val item = translations.optJSONObject(i)
                if (item == null) {
                    invalid = true
                    continue
                }
                val id = item.optString("id").trim()
                if (
                    id.isBlank() ||
                    id !in expectedIds ||
                    !returnedIds.add(id) ||
                    !item.has("text")
                ) {
                    invalid = true
                }
            }

            if (
                invalid ||
                returnedIds != expectedIds ||
                translations.length() != segments.size
            ) {
                return JSONObject()
                    .put("success", false)
                    .put("technical", "translation_batch_contract_mismatch")
            }

            return JSONObject()
                .put("success", true)
                .put("translations", translations)
                .put("technical", "segments=${segments.size}; target=${target.code}")
        } finally {
            if (currentAgentConnection === connection) {
                currentAgentConnection = null
            }
            executionKernel.clearConnection(connection)
            try { connection?.disconnect() } catch (_: Exception) { }
        }
    }

    private fun callMultimodalCore(
        prompt: String,
        manifest: JSONObject
    ): JSONObject {
        var connection: HttpsURLConnection? = null

        val requestStartedAt =
            SystemClock.elapsedRealtime()

        var requestPreparedAt =
            requestStartedAt

        var requestBodySentAt =
            requestStartedAt

        var responseHeadersAt =
            requestStartedAt

        var responseBodyReadAt =
            requestStartedAt

        var responseParsedAt =
            requestStartedAt

        var requestByteCount =
            0

        var responseByteCount =
            0

        var responseCodeForTelemetry =
            -1

        var telemetryRecorded =
            false

        var kindForTelemetry =
            manifest.optString("kind").take(40)

        fun recordTelemetryOnce() {
            if (telemetryRecorded) {
                return
            }

            telemetryRecorded =
                true

            val now =
                SystemClock.elapsedRealtime()

            val endAt =
                if (
                    responseParsedAt >
                    requestStartedAt
                ) {
                    responseParsedAt
                } else {
                    now
                }

            val preparedAt =
                requestPreparedAt.coerceAtLeast(
                    requestStartedAt
                )

            val sentAt =
                requestBodySentAt.coerceAtLeast(
                    preparedAt
                )

            val headersAt =
                responseHeadersAt.coerceAtLeast(
                    sentAt
                )

            val bodyAt =
                responseBodyReadAt.coerceAtLeast(
                    headersAt
                )

            val parsedAt =
                if (
                    responseParsedAt >
                    requestStartedAt
                ) {
                    responseParsedAt.coerceAtLeast(
                        bodyAt
                    )
                } else {
                    bodyAt
                }

            recordMultimodalPerformanceTelemetry(
                totalMs =
                    endAt -
                        requestStartedAt,
                prepareMs =
                    preparedAt -
                        requestStartedAt,
                uploadMs =
                    sentAt -
                        preparedAt,
                headersWaitMs =
                    headersAt -
                        sentAt,
                bodyReadMs =
                    bodyAt -
                        headersAt,
                jsonParseMs =
                    parsedAt -
                        bodyAt,
                requestBytes =
                    requestByteCount,
                responseBytes =
                    responseByteCount,
                httpCode =
                    responseCodeForTelemetry,
                kind =
                    kindForTelemetry
            )
        }

        try {
            val kind =
                manifest.optString(
                    "kind"
                )

            kindForTelemetry =
                kind.take(
                    40
                )

            val requestJson =
                JSONObject()
                    .put(
                        "prompt",
                        prompt.take(
                            MAX_MULTIMODAL_PROMPT_CHARS
                        )
                    )
                    .put(
                        "kind",
                        kind
                    )
                    .put(
                        "display_name",
                        manifest
                            .optString(
                                "display_name"
                            )
                            .take(
                                160
                            )
                    )
                    .put(
                        "mime_type",
                        manifest
                            .optString(
                                "mime_type"
                            )
                            .take(
                                120
                            )
                    )

            when (kind) {
                AyanaMultimodalAttachmentManager.KIND_IMAGE,
                AyanaMultimodalAttachmentManager.KIND_DOCUMENT -> {
                    val file =
                        validatedMultimodalCacheFile(
                            manifest.optString(
                                "path"
                            )
                        )

                    val maxBytes =
                        MAX_MULTIMODAL_DIRECT_BYTES

                    if (
                        file.length() <=
                        0L ||
                        file.length() >
                        maxBytes
                    ) {
                        throw IllegalArgumentException(
                            "Размер подготовленного вложения недопустим"
                        )
                    }

                    requestJson.put(
                        "data_base64",
                        Base64.encodeToString(
                            file.readBytes(),
                            Base64.NO_WRAP
                        )
                    )
                }

                AyanaMultimodalAttachmentManager.KIND_VIDEO_VISUAL -> {
                    val sourceFrames =
                        manifest.optJSONArray(
                            "frames"
                        )
                            ?: JSONArray()

                    val frames =
                        JSONArray()

                    var totalBytes =
                        0L

                    val frameCount =
                        minOf(
                            sourceFrames.length(),
                            MAX_MULTIMODAL_VIDEO_FRAMES
                        )

                    for (
                        i in
                        0 until frameCount
                    ) {
                        val item =
                            sourceFrames.optJSONObject(
                                i
                            )
                                ?: continue

                        val file =
                            validatedMultimodalCacheFile(
                                item.optString(
                                    "path"
                                )
                            )

                        if (
                            file.length() <=
                            0L
                        ) {
                            continue
                        }

                        totalBytes +=
                            file.length()

                        if (
                            totalBytes >
                            MAX_MULTIMODAL_VIDEO_FRAME_BYTES
                        ) {
                            throw IllegalArgumentException(
                                "Слишком большой набор видеокадров"
                            )
                        }

                        frames.put(
                            JSONObject()
                                .put(
                                    "timestamp_ms",
                                    item.optLong(
                                        "timestamp_ms",
                                        0L
                                    )
                                )
                                .put(
                                    "data_base64",
                                    Base64.encodeToString(
                                        file.readBytes(),
                                        Base64.NO_WRAP
                                    )
                                )
                        )
                    }

                    if (
                        frames.length() <
                        2
                    ) {
                        throw IllegalArgumentException(
                            "Недостаточно видеокадров для анализа"
                        )
                    }

                    requestJson.put(
                        "frames",
                        frames
                    )
                    requestJson.put(
                        "duration_ms",
                        manifest.optLong(
                            "duration_ms",
                            0L
                        )
                    )
                    requestJson.put(
                        "audio_analysis",
                        false
                    )
                }

                AyanaMultimodalAttachmentManager.KIND_BATCH -> {
                    val sourceItems =
                        manifest.optJSONArray(
                            "items"
                        )
                            ?: JSONArray()

                    if (
                        sourceItems.length() < 2 ||
                        sourceItems.length() >
                        MAX_MULTIMODAL_BATCH_ITEMS
                    ) {
                        throw IllegalArgumentException(
                            "Недопустимое количество вложений в пакете"
                        )
                    }

                    val attachments =
                        JSONArray()
                    var batchBytes =
                        0L
                    var batchVideoFrames =
                        0

                    for (index in 0 until sourceItems.length()) {
                        val sourceItem =
                            sourceItems.optJSONObject(index)
                                ?: throw IllegalArgumentException(
                                    "Повреждён элемент пакета вложений"
                                )
                        val itemKind =
                            sourceItem.optString("kind")
                        if (
                            itemKind ==
                            AyanaMultimodalAttachmentManager.KIND_BATCH
                        ) {
                            throw IllegalArgumentException(
                                "Вложенные пакеты не поддерживаются"
                            )
                        }

                        val workerItem =
                            JSONObject()
                                .put("kind", itemKind)
                                .put(
                                    "display_name",
                                    sourceItem
                                        .optString("display_name")
                                        .take(160)
                                )
                                .put(
                                    "mime_type",
                                    sourceItem
                                        .optString("mime_type")
                                        .take(120)
                                )

                        when (itemKind) {
                            AyanaMultimodalAttachmentManager.KIND_IMAGE,
                            AyanaMultimodalAttachmentManager.KIND_DOCUMENT -> {
                                val file =
                                    validatedMultimodalCacheFile(
                                        sourceItem.optString("path")
                                    )
                                val bytes =
                                    file.length()
                                if (
                                    bytes <= 0L ||
                                    bytes > MAX_MULTIMODAL_DIRECT_BYTES
                                ) {
                                    throw IllegalArgumentException(
                                        "Размер одного вложения в пакете недопустим"
                                    )
                                }
                                batchBytes += bytes
                                if (
                                    batchBytes >
                                    MAX_MULTIMODAL_BATCH_BYTES
                                ) {
                                    throw IllegalArgumentException(
                                        "Общий размер пакета вложений слишком большой"
                                    )
                                }
                                workerItem.put(
                                    "data_base64",
                                    Base64.encodeToString(
                                        file.readBytes(),
                                        Base64.NO_WRAP
                                    )
                                )
                            }

                            AyanaMultimodalAttachmentManager.KIND_VIDEO_VISUAL -> {
                                val sourceFrames =
                                    sourceItem.optJSONArray("frames")
                                        ?: JSONArray()
                                val frames =
                                    JSONArray()
                                var videoBytes =
                                    0L
                                val frameCount =
                                    minOf(
                                        sourceFrames.length(),
                                        MAX_MULTIMODAL_VIDEO_FRAMES
                                    )
                                for (frameIndex in 0 until frameCount) {
                                    val frameItem =
                                        sourceFrames.optJSONObject(frameIndex)
                                            ?: continue
                                    val file =
                                        validatedMultimodalCacheFile(
                                            frameItem.optString("path")
                                        )
                                    val bytes =
                                        file.length()
                                    if (bytes <= 0L) {
                                        continue
                                    }
                                    videoBytes += bytes
                                    batchBytes += bytes
                                    batchVideoFrames++
                                    if (
                                        videoBytes >
                                        MAX_MULTIMODAL_VIDEO_FRAME_BYTES ||
                                        batchBytes >
                                        MAX_MULTIMODAL_BATCH_BYTES ||
                                        batchVideoFrames >
                                        MAX_MULTIMODAL_BATCH_VIDEO_FRAMES
                                    ) {
                                        throw IllegalArgumentException(
                                            "Слишком большой набор вложений или видеокадров"
                                        )
                                    }
                                    frames.put(
                                        JSONObject()
                                            .put(
                                                "timestamp_ms",
                                                frameItem.optLong(
                                                    "timestamp_ms",
                                                    0L
                                                )
                                            )
                                            .put(
                                                "data_base64",
                                                Base64.encodeToString(
file.readBytes(),
                                                    Base64.NO_WRAP
                                                )
                                            )
                                    )
                                }
                                if (frames.length() < 2) {
                                    throw IllegalArgumentException(
                                        "Недостаточно видеокадров в одном из вложений"
                                    )
                                }
                                workerItem
                                    .put("frames", frames)
                                    .put(
                                        "duration_ms",
                                        sourceItem.optLong(
                                            "duration_ms",
                                            0L
                                        )
                                    )
                                    .put("audio_analysis", false)
                            }

                            else ->
                                throw IllegalArgumentException(
                                    "Неподдерживаемый тип вложения в пакете"
                                )
                        }

                        attachments.put(workerItem)
                    }

                    requestJson
                        .put("attachments", attachments)
                        .put("item_count", attachments.length())
                }

                else ->
                    throw IllegalArgumentException(
                        "Неподдерживаемый тип мультимодального вложения"
                    )
            }

            val requestBytes =
                requestJson
                    .toString()
                    .toByteArray(
                        Charsets.UTF_8
                    )

            requestByteCount =
                requestBytes.size

            requestPreparedAt =
                SystemClock.elapsedRealtime()

            connection =
                URL(
                    "$WORKER_URL/multimodal"
                )
                    .openConnection() as HttpsURLConnection

            currentAgentConnection =
                connection

            executionKernel.bindConnection(
connection
            )

            connection.requestMethod =
                "POST"

            connection.setRequestProperty(
                "Content-Type",
                "application/json"
            )

            connection.connectTimeout =
                MULTIMODAL_CONNECT_TIMEOUT_MS

            connection.readTimeout =
                MULTIMODAL_READ_TIMEOUT_MS

            connection.doOutput =
                true

            connection.setFixedLengthStreamingMode(
                requestBytes.size
            )

            connection.outputStream.use {
                output ->
                output.write(
                    requestBytes
                )
                output.flush()
            }

            requestBodySentAt =
                SystemClock.elapsedRealtime()

            val code =
                connection.responseCode

            responseCodeForTelemetry =
                code

            responseHeadersAt =
                SystemClock.elapsedRealtime()

            val stream =
                if (
                    code in
                    200..299
                ) {
                    connection.inputStream
                } else {
                    connection.errorStream
                }

            val raw =
                stream
                    ?.bufferedReader(
                        Charsets.UTF_8
                    )
                    ?.use {
                        it.readText()
                    }
                    .orEmpty()

            responseBodyReadAt =
                SystemClock.elapsedRealtime()

            responseByteCount =
                raw
                    .toByteArray(
                        Charsets.UTF_8
                    )
                    .size

            val response =
                try {
                    JSONObject(
                        raw
                    )
                } catch (_: Exception) {
                    JSONObject()
                }

            responseParsedAt =
                SystemClock.elapsedRealtime()

            recordTelemetryOnce()

            if (
                code !in
                200..299
            ) {
                val detail =
                    response
                        .optString(
                            "error"
                        )
                        .ifBlank {
                            response.optString(
                                "details"
                            )
                        }
                        .ifBlank {
                            "HTTP $code"
                        }

                return JSONObject()
                    .put(
                        "success",
                        false
                    )
                    .put(
                        "reply",
                        "Мультимодальный анализ не выполнен: ${detail.take(220)}"
                    )
                    .put(
                        "technical",
                        "http=$code"
                    )
            }

            val reply =
                response
                    .optString(
                        "reply"
                    )
                    .trim()

            return JSONObject()
                .put(
                    "success",
                    response.optBoolean(
                        "ok",
                        reply.isNotBlank()
                    )
                )
                .put(
                    "reply",
                    reply
                )
                .put(
                    "response_id",
                    response
                        .optString(
                            "response_id"
                        )
                        .trim()
                )
                .put(
                    "technical",
                    "kind=$kind; " +
                        "continuation_count=${response.optInt("continuation_count", 0)}; " +
                        "completion_integrity=${response.optString("completion_integrity").ifBlank { "unknown" }}"
                )

        } finally {
            recordTelemetryOnce()

            if (
                currentAgentConnection ===
                connection
            ) {
                currentAgentConnection =
                    null
            }

            executionKernel.clearConnection(
                connection
            )

            try {
                connection?.disconnect()
            } catch (_: Exception) {
            }
        }
    }

    private fun validatedMultimodalCacheFile(
        path: String
    ): File {
        if (path.isBlank()) {
            throw IllegalArgumentException("Путь вложения отсутствует")
        }
        val root = File(cacheDir, "ayana_multimodal").canonicalFile
        val file = File(path).canonicalFile
        if (!file.path.startsWith(root.path + File.separator) || !file.isFile) {
            throw SecurityException("Вложение находится вне приватного cache AYANA")
        }
        return file
    }

    private data class AgentCoreTransportPolicy(
        val readTimeoutMs: Int,
        val retryCount: Int,
        val profile: String
    )

    /**
     * v12.15.1 transport policy. A deep read-only text request benefits more from one
     * longer server window than from restarting the same generation after 18 seconds.
     * Tool-result/verified-device-fact turns remain on the existing short bounded policy
     * so device/action orchestration keeps its fail-closed latency and semantics.
     */
    private fun resolveAgentCoreTransportPolicy(
        message: String?,
        toolResults: JSONArray?,
        verifiedDeviceFacts: String?,
        verifiedLocalEvidence: String?,
        source: String
    ): AgentCoreTransportPolicy {
        val hasToolResults =
            toolResults != null &&
                toolResults.length() > 0

        val normalized =
            message
                .orEmpty()
                .lowercase(Locale.ROOT)
                .replace('ё', 'е')
                .trim()

        val hasPotentialSideEffectVerb =
            Regex("(?:^|\\s)(?:открой|открыть|закрой|закрыть|сверни|свернуть|измени|изменить|установи|установить|создай|создать|сохрани|сохранить|удали|удалить|отправь|отправить|введи|ввести|нажми|нажать|включи|включить|выключи|выключить|запусти|запустить|собери|собрать|подпиши|подписать|загрузи|загрузить|commit|push|коммит|пуш)(?:\\s|$)")
                .containsMatchIn(normalized)

        val deepTextRequest =
            source == "text" &&
                !hasToolResults &&
                verifiedDeviceFacts.isNullOrBlank() &&
                verifiedLocalEvidence.isNullOrBlank() &&
                normalized.isNotBlank() &&
                !hasPotentialSideEffectVerb &&
                (
                    Regex("(?:подробн|детальн|развернут|тщательн|глубок|полный\\s+(?:обзор|анализ|список|перечень)|проанализируй|сравни|исследуй|пошагов)")
                        .containsMatchIn(normalized) ||
                        (
                            Regex("(?:все|весь|полный)\\s+(?:основн\\w*\\s+)?(?:возможност|пункт|этап|шаг|требован)")
                                .containsMatchIn(normalized)
                            )
                    )

        return if (deepTextRequest) {
                AgentCoreTransportPolicy(
                    readTimeoutMs = AGENT_CORE_LONG_READ_TIMEOUT_MS,
                    retryCount = AGENT_CORE_LONG_READ_TIMEOUT_RETRY_COUNT,
                    profile = "long_read_only"
                )
            } else {
                AgentCoreTransportPolicy(
                    readTimeoutMs = AGENT_CORE_READ_TIMEOUT_MS,
                    retryCount = AGENT_CORE_TIMEOUT_RETRY_COUNT,
                    profile = "bounded_default"
                )
            }
    }

    /**
     * v12.14 bounded Agent Core recovery. A timeout occurs before any returned
     * device tool call is dispatched, so retrying the same model request is
     * side-effect safe. One retry only; cancellation always wins.
     */
    private fun callAgentCoreWithRecovery(
        message: String?,
        previousResponseId: String?,
        toolResults: JSONArray?,
        memoryContext: String?,
        intelligenceContext: String?,
        source: String,
        commandToken: Long,
        recoveryObserver: ((String, String) -> Unit)? = null,
        verifiedDeviceFacts: String? = null,
        verifiedLocalEvidence: String? = null
    ): JSONObject {
        val transportPolicy =
            resolveAgentCoreTransportPolicy(
                message = message,
                toolResults = toolResults,
                verifiedDeviceFacts = verifiedDeviceFacts,
                verifiedLocalEvidence = verifiedLocalEvidence,
                source = source
            )

        if (transportPolicy.profile != "bounded_default") {
            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "agent_transport_policy",
                message = "Для длинного read-only запроса выбран расширенный Agent Core budget",
                details =
                    "profile=${transportPolicy.profile}; read_timeout_ms=${transportPolicy.readTimeoutMs}; retry_count=${transportPolicy.retryCount}"
            )
        }

        val originalMessage =
            message

        var currentMessage =
            message

        var currentPreviousResponseId =
            previousResponseId

        var timeoutAttempt =
            0

        var timeoutBackoffMs =
            AGENT_CORE_RETRY_BACKOFF_MS

        var compactRestartUsed =
            false

        while (true) {
            try {
return callAgentCore(
                    message = currentMessage,
                    previousResponseId = currentPreviousResponseId,
                    toolResults = toolResults,
                    memoryContext = memoryContext,
                    intelligenceContext = intelligenceContext,
                    source = source,
                    verifiedDeviceFacts = verifiedDeviceFacts,
                    verifiedLocalEvidence = verifiedLocalEvidence,
                    readTimeoutMs = transportPolicy.readTimeoutMs
                )
            } catch (timeout: SocketTimeoutException) {
                if (
                    timeoutAttempt >= transportPolicy.retryCount ||
                    isCommandCancelled(commandToken) ||
                    shuttingDown
                ) {
                    throw timeout
                }

                timeoutAttempt++

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "agent_retry",
                    message = "Agent Core timeout: выполняю bounded retry",
                    details =
                        "attempt=$timeoutAttempt/${transportPolicy.retryCount}; backoff_ms=$timeoutBackoffMs; " +
                            "reason=${timeout.message.orEmpty().take(180)}"
                )

                recoveryObserver?.invoke(
                    "timeout_retry",
                    "attempt=$timeoutAttempt/${transportPolicy.retryCount}; ${timeout.message.orEmpty().take(260)}"
                )

                try {
                    Thread.sleep(timeoutBackoffMs)
                } catch (_: InterruptedException) {
                    Thread.currentThread().interrupt()
                    throw timeout
                }

                timeoutBackoffMs =
                    (timeoutBackoffMs * 2L)
                        .coerceAtMost(
                            AGENT_CORE_RETRY_BACKOFF_MAX_MS
                        )
            } catch (error: IllegalStateException) {
                val decision =
                    agentCoreRecoveryPolicy.decide(
                        error = error,
                        originalMessage = originalMessage,
                        source = source,
                        hasToolResults =
                            toolResults != null &&
                                toolResults.length() > 0,
                        hasVerifiedDeviceFacts =
                            !verifiedDeviceFacts.isNullOrBlank() ||
                                !verifiedLocalEvidence.isNullOrBlank(),
                        compactRestartAlreadyUsed =
                            compactRestartUsed
                    )

                if (
                    !decision.recoverable ||
                    decision.strategy !=
                    AyanaAgentCoreRecoveryPolicy.Strategy.COMPACT_RESTART ||
                    isCommandCancelled(commandToken) ||
                    shuttingDown
                ) {
                    throw error
                }

                compactRestartUsed =
                    true

                currentMessage =
                    decision.retryMessage
                        ?: throw error

                if (!decision.preservePreviousResponseId) {
                    currentPreviousResponseId =
                        null
                }

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "agent_completion_recovery",
                    message = "Незавершённый read-only ответ перезапускается в компактном bounded-режиме",
                    details =
                        (
                            "strategy=${decision.strategy}; " +
                                "reason=${decision.reason}; " +
                                "previous_response_preserved=${decision.preservePreviousResponseId}; " +
                                "budget=1"
                            )
                            .take(
                                700
                            )
                )

                recoveryObserver?.invoke(
                    "compact_restart",
                    "reason=${decision.reason}; previous_response_preserved=${decision.preservePreviousResponseId}"
                )

                try {
                    Thread.sleep(
                        AGENT_CORE_COMPLETION_RECOVERY_BACKOFF_MS
                    )
                } catch (_: InterruptedException) {
                    Thread.currentThread().interrupt()
                    throw error
                }
            }
        }
    }

    private fun callAgentCore(
        message: String?,
        previousResponseId: String?,
        toolResults: JSONArray?,
        memoryContext: String?,
        intelligenceContext: String?,
        source: String,
        verifiedDeviceFacts: String? = null,
        verifiedLocalEvidence: String? = null,
        readTimeoutMs: Int = AGENT_CORE_READ_TIMEOUT_MS
    ): JSONObject {

        var connection:
            HttpsURLConnection? = null

        val requestStartedAt =
            SystemClock.elapsedRealtime()

        var requestPreparedAt =
            requestStartedAt

        var requestBodySentAt =
            requestStartedAt

        var responseHeadersAt =
            requestStartedAt

        var responseBodyReadAt =
            requestStartedAt

        var responseParsedAt =
            requestStartedAt

        var requestByteCount =
            0

        var responseByteCount =
            0

        var responseCodeForTelemetry =
            -1

        var requestPrepared =
            false

        var requestSent =
            false

        var headersReceived =
            false

        var bodyRead =
            false

        try {

            val url =
                URL(
                    "$WORKER_URL/agent"
                )

            connection =
                url.openConnection()
                    as HttpsURLConnection

            currentAgentConnection =
                connection

            executionKernel.bindConnection(
                connection
            )

            connection.requestMethod =
                "POST"

            connection.setRequestProperty(
                "Content-Type",
                "application/json"
            )

            connection.setRequestProperty(
                "Accept",
                "application/json"
            )

            connection.connectTimeout =
                AGENT_CORE_CONNECT_TIMEOUT_MS

            connection.readTimeout =
                readTimeoutMs

            connection.doOutput =
                true

            val requestJson =
                JSONObject()

            requestJson.put(
                "source",
                source
            )

            if (
                !message.isNullOrBlank()
            ) {

                requestJson.put(
                    "message",
                    message
                )

                val zoneId =
                    ZoneId.systemDefault()

                val localDateTime =
                    LocalDateTime
                        .now(zoneId)
                        .format(
                            DateTimeFormatter
                                .ofPattern(
                                    "yyyy-MM-dd'T'HH:mm:ss"
                                )
                        )

                requestJson.put(
                    "device_local_datetime",
                    localDateTime
                )

                requestJson.put(
                    "device_timezone",
                    zoneId.id
                )
            }

            if (
                !memoryContext.isNullOrBlank()
            ) {
                requestJson.put(
                    "memory_context",
                    memoryContext
                )
            }

            if (
                !intelligenceContext
                    .isNullOrBlank()
            ) {
                requestJson.put(
                    "agent_intelligence_context",
                    intelligenceContext
                )
            }

            if (
                !verifiedDeviceFacts
                    .isNullOrBlank()
            ) {
                requestJson.put(
                    "verified_device_facts",
                    verifiedDeviceFacts
                )
            }

            if (
                !verifiedLocalEvidence
                    .isNullOrBlank()
            ) {
                requestJson.put(
                    "verified_local_evidence",
                    verifiedLocalEvidence
                )
            }

            if (
                !previousResponseId
                    .isNullOrBlank()
            ) {
                requestJson.put(
                    "previous_response_id",
                    previousResponseId
                )
            }

            if (
                toolResults != null &&
                toolResults.length() >
                0
            ) {
                requestJson.put(
                    "tool_results",
                    toolResults
                )
            }

            // Serialize exactly once. Fixed-length streaming avoids implicit
            // chunked framing for this bounded JSON payload.
            val requestBytes =
                requestJson
                    .toString()
                    .toByteArray(
                        Charsets.UTF_8
                    )

            requestByteCount =
                requestBytes.size

            connection.setFixedLengthStreamingMode(
                requestBytes.size
            )

            requestPreparedAt =
                SystemClock.elapsedRealtime()

            requestPrepared =
                true

            connection
                .outputStream
                .use { output ->
                    output.write(
                        requestBytes
                    )
                    output.flush()
                }

            requestBodySentAt =
                SystemClock.elapsedRealtime()

            requestSent =
                true

            val responseCode =
                connection
                    .responseCode

            responseCodeForTelemetry =
                responseCode

            responseHeadersAt =
                SystemClock.elapsedRealtime()

            headersReceived =
                true

            val stream =
                if (
                    responseCode in
                    200..299
                ) {
                    connection.inputStream
                } else {
                    connection.errorStream
                }

            val responseText =
                stream
                    ?.bufferedReader()
                    ?.use {
                        it.readText()
                    }
                    .orEmpty()

            responseBodyReadAt =
                SystemClock.elapsedRealtime()

            bodyRead =
                true

            responseByteCount =
                responseText
                    .toByteArray(
                        Charsets.UTF_8
                    )
                    .size

            if (
                responseCode !in
                200..299
            ) {
                throw IllegalStateException(
                    "Agent HTTP " +
                        responseCode +
                        ": " +
                        responseText
                )
            }

            val parsed =
                JSONObject(
                    responseText
                )

            responseParsedAt =
                SystemClock.elapsedRealtime()

            val totalMs =
                (
                    responseParsedAt -
                        requestStartedAt
                    )
                    .coerceAtLeast(
                        0L
                    )

            capabilityRegistry
                .recordAgentCoreResult(
                    success = true,
                    latencyMs = totalMs
                )

            recordAgentCorePerformanceTelemetry(
                totalMs = totalMs,
                prepareMs =
                    requestPreparedAt -
                        requestStartedAt,
                uploadMs =
                    requestBodySentAt -
                        requestPreparedAt,
                headersWaitMs =
                    responseHeadersAt -
                        requestBodySentAt,
                bodyReadMs =
                    responseBodyReadAt -
                        responseHeadersAt,
                jsonParseMs =
                    responseParsedAt -
                        responseBodyReadAt,
                requestBytes =
                    requestByteCount,
                responseBytes =
                    responseByteCount,
                httpCode =
                    responseCodeForTelemetry
            )

            return parsed

        } catch (
            error: Exception
        ) {

            val failedAt =
                SystemClock.elapsedRealtime()

            capabilityRegistry
                .recordAgentCoreResult(
                    success = false,
                    latencyMs =
                        failedAt -
                            requestStartedAt,
                    error =
                        error.message
                            ?: error.javaClass.simpleName
                )

            val failurePrepareMs =
                if (requestPrepared) {
                    requestPreparedAt -
                        requestStartedAt
                } else {
                    failedAt -
                        requestStartedAt
                }

            val failureUploadMs =
                when {
                    requestSent ->
                        requestBodySentAt -
                            requestPreparedAt

                    requestPrepared ->
                        failedAt -
                            requestPreparedAt

                    else ->
                        0L
                }

            val failureHeadersMs =
                when {
                    headersReceived ->
                        responseHeadersAt -
                            requestBodySentAt

                    requestSent ->
                        failedAt -
                            requestBodySentAt

                    else ->
                        0L
                }

            val failureBodyMs =
                when {
                    bodyRead ->
                        responseBodyReadAt -
                            responseHeadersAt

                    headersReceived ->
                        failedAt -
                            responseHeadersAt

                    else ->
                        0L
                }

            recordAgentCorePerformanceTelemetry(
                totalMs =
                    failedAt -
                        requestStartedAt,
                prepareMs =
                    failurePrepareMs,
                uploadMs =
                    failureUploadMs,
                headersWaitMs =
                    failureHeadersMs,
                bodyReadMs =
                    failureBodyMs,
                jsonParseMs = 0L,
                requestBytes =
                    requestByteCount,
                responseBytes =
                    responseByteCount,
                httpCode =
                    responseCodeForTelemetry
            )

            throw error

        } finally {

            if (
                currentAgentConnection ===
                connection
            ) {
                currentAgentConnection =
                    null
            }

            executionKernel.clearConnection(
                connection
            )

            connection
                ?.disconnect()
        }
    }

    private fun recordAgentCorePerformanceTelemetry(
        totalMs: Long,
        prepareMs: Long,
        uploadMs: Long,
        headersWaitMs: Long,
        bodyReadMs: Long,
        jsonParseMs: Long,
        requestBytes: Int,
        responseBytes: Int,
        httpCode: Int
    ) {
        val safeTotal =
            totalMs.coerceAtLeast(
                0L
            )

        val safePrepare =
            prepareMs.coerceAtLeast(
                0L
            )

        val safeUpload =
            uploadMs.coerceAtLeast(
                0L
            )

        val safeHeaders =
            headersWaitMs.coerceAtLeast(
                0L
            )

        val safeBody =
            bodyReadMs.coerceAtLeast(
                0L
            )

        val safeParse =
            jsonParseMs.coerceAtLeast(
                0L
            )

        capabilityRegistry
            .recordAgentCorePerformance(
                totalMs = safeTotal,
                prepareMs = safePrepare,
                uploadMs = safeUpload,
                headersWaitMs = safeHeaders,
                bodyReadMs = safeBody,
                jsonParseMs = safeParse,
                requestBytes =
                    requestBytes.coerceAtLeast(
                        0
                    ),
                responseBytes =
                    responseBytes.coerceAtLeast(
                        0
                    ),
                httpCode = httpCode
            )

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "agent_performance",
            message =
                "Agent Core phase telemetry",
            details =
                (
                    "total_ms=$safeTotal; " +
                        "prepare_ms=$safePrepare; " +
                        "upload_ms=$safeUpload; " +
                        "headers_wait_ms=$safeHeaders; " +
"latency_class=${capabilityRegistry.agentCoreLatencySnapshot().optString("classification", "NO_DATA")}; " +
                        "bottleneck=${capabilityRegistry.agentCoreLatencySnapshot().optString("bottleneck", "unknown")}; " +
                        "body_read_ms=$safeBody; " +
                        "json_parse_ms=$safeParse; " +
                        "request_bytes=${requestBytes.coerceAtLeast(0)}; " +
                        "response_bytes=${responseBytes.coerceAtLeast(0)}; " +
                        "http_code=$httpCode"
                    )
                    .take(
                        900
                    )
        )
    }

