                                        "branch=${AyanaGitHubRepositoryExecutor.BRANCH}; " +
                                        "transaction_id=${arguments.optString("_github_dev_transaction_id").take(120)}"
                            )

                        if (!dispatchAllowed) {
                            toolResult(
                                false,
                                "Development transaction остановлена Execution Kernel до внешнего side effect."
                            )
                                .put("status", "dispatch_gate_rejected")
                                .put("action_dispatched", false)
                                .put("action_committed", false)
                                .put("reconciliation_complete", true)
                        } else {
                            val txResult =
                                githubRepositoryExecutor.developmentTransaction(
                                    arguments = arguments,
                                    confirmed = true,
                                    shouldCancel = {
                                        cancelRequested ||
                                            Thread.currentThread().isInterrupted
                                    }
                                )

                            val dispatched = txResult.optBoolean("action_dispatched", false)
                            val committed = txResult.optBoolean("action_committed", false)
                            val reconciliationComplete = txResult.optBoolean("reconciliation_complete", false)

                            if (dispatched) {
                                executionKernel.markIrreversibleDispatchAccepted(
                                    "GitHub development transaction external mutation accepted: " +
                                        "transaction_id=${txResult.optString("transaction_id").take(120)}"
                                )
                            }

                            executionKernel.markSideEffectReconciliationStarted(
                                "GitHub development transaction reconciliation: status=${txResult.optString("status")}"
                            )

                            when {
                                !dispatched ->
                                    executionKernel.markSideEffectReconciled(
                                        committed = false,
                                        detail = "Development transaction mutation не отправлялась."
                                    )

                                reconciliationComplete ->
                                    executionKernel.markSideEffectReconciled(
                                        committed = committed,
                                        detail =
                                            "Development transaction reconciliation complete; committed=$committed; " +
                                                "status=${txResult.optString("status")}; " +
                                                "commit=${txResult.optString("commit_sha").take(40)}"
                                    )
                            }

                            txResult
                        }
                    }
                }

                "github_development_transaction_control" -> {
                    when (arguments.optString("action").trim().lowercase(Locale.ROOT)) {
                        "status" ->
                            githubRepositoryExecutor.developmentTransactionStatus()

                        "accept" ->
                            githubRepositoryExecutor.acceptDevelopmentTransaction()

                        "cancel" ->
                            githubRepositoryExecutor.cancelPreparedDevelopmentTransaction()

                        "rollback" -> {
                            val dispatchAllowed =
                                executionKernel.tryBeginIrreversibleDispatch(
                                    kind = "github_development_transaction_rollback",
                                    detail = "explicit verified rollback for fixed AYANA repository"
                                )

                            if (!dispatchAllowed) {
                                toolResult(
                                    false,
                                    "Development rollback остановлен Execution Kernel до внешнего side effect."
                                )
                                    .put("status", "dispatch_gate_rejected")
                                    .put("action_dispatched", false)
                                    .put("action_committed", false)
                                    .put("reconciliation_complete", true)
                            } else {
                                val rollback =
                                    githubRepositoryExecutor.rollbackDevelopmentTransaction(
                                        shouldCancel = {
                                            cancelRequested ||
                                                Thread.currentThread().isInterrupted
                                        }
                                    )

                                val dispatched = rollback.optBoolean("action_dispatched", false)
                                val committed = rollback.optBoolean("action_committed", false)
                                val reconciliationComplete = rollback.optBoolean("reconciliation_complete", false)

                                if (dispatched) {
                                    executionKernel.markIrreversibleDispatchAccepted(
                                        "GitHub development rollback commit/build dispatched"
                                    )
                                }
                                executionKernel.markSideEffectReconciliationStarted(
                                    "GitHub development rollback reconciliation: status=${rollback.optString("status")}"
                                )
                                if (!dispatched || reconciliationComplete) {
                                    executionKernel.markSideEffectReconciled(
                                        committed = committed,
                                        detail =
                                            "Development rollback reconciliation complete=${reconciliationComplete}; committed=$committed; " +
                                                "rollback_commit=${rollback.optString("rollback_commit_sha").take(40)}"
                                    )
                                }
                                rollback
                            }
                        }

                        else ->
                            toolResult(false, "Неизвестное действие development transaction control.")
                                .put("status", "development_transaction_control_unknown")
                    }
                }

                "github_write_commit" -> {
                    val confirmed = arguments.optBoolean("confirmed", false)

                    if (!confirmed) {
                        githubRepositoryExecutor.writeCommit(
                            arguments = arguments,
                            confirmed = false
                        )
                    } else {
                        val dispatchAllowed =
                            executionKernel.tryBeginIrreversibleDispatch(
                                kind = "github_contents_commit",
                                detail =
                                    "repository=${AyanaGitHubRepositoryExecutor.REPOSITORY_SLUG}; " +
                                        "branch=${AyanaGitHubRepositoryExecutor.BRANCH}; " +
                                        "path=${arguments.optString("path").take(320)}"
                            )

                        if (!dispatchAllowed) {
                            toolResult(
                                false,
                                "GitHub commit остановлен Execution Kernel до внешнего side effect."
                            )
                                .put("status", "dispatch_gate_rejected")
                                .put("action_dispatched", false)
                                .put("action_committed", false)
                                .put("reconciliation_complete", true)
                        } else {
                            val githubResult =
                                githubRepositoryExecutor.writeCommit(
                                    arguments = arguments,
                                    confirmed = true
                                )

                            val dispatched =
                                githubResult.optBoolean("action_dispatched", false)
                            val committed =
                                githubResult.optBoolean("action_committed", false)
                            val reconciliationComplete =
                                githubResult.optBoolean("reconciliation_complete", false)

                            if (dispatched) {
                                executionKernel.markIrreversibleDispatchAccepted(
                                    "GitHub PUT dispatched: ${arguments.optString("path").take(320)}"
                                )
                            }

                            executionKernel.markSideEffectReconciliationStarted(
                                "GitHub commit reconciliation: status=${githubResult.optString("status")}"
                            )

                            when {
                                !dispatched ->
                                    executionKernel.markSideEffectReconciled(
                                        committed = false,
                                        detail = "GitHub PUT не был отправлен; side effect отсутствует."
                                    )

                                reconciliationComplete ->
                                    executionKernel.markSideEffectReconciled(
                                        committed = committed,
                                        detail =
                                            "GitHub reconciliation complete; committed=$committed; " +
                                                "sha=${githubResult.optString("commit_sha").take(64)}"
                                    )
                            }

                            githubResult
                        }
                    }
                }

                "tap_screen_coordinates" -> {

                    screenIntelligence
                        .tap(
                            x =
                                arguments
                                    .optInt(
                                        "x",
                                        -1
                                    ),
                            y =
                                arguments
                                    .optInt(
                                        "y",
                                        -1
                                    ),
                            confirmed =
                                arguments
                                    .optBoolean(
                                        "confirmed",
                                        false
                                    )
                        )
                }

                else ->
                    toolResult(
                        false,
                        "Неизвестный инструмент: $name"
                    )
            }

        } catch (
            error: Exception
        ) {

            toolResult(
                false,
                error.message
                    ?: "Ошибка выполнения инструмента"
            )
        }
    }

    private fun executeAndroidGoal(
        arguments: JSONObject,
        checkpointStore: AyanaDurableGoalStore = durableGoalStore,
        checkpointGoalId: String? = currentDurableGoalId
    ): JSONObject {

        val compiled =
            androidGoalCompiler
                .compile(
                    arguments
                )

        if (
            !compiled.optBoolean(
                "success",
                false
            )
        ) {
            return JSONObject(
                compiled.toString()
            )
                .put(
                    "local_reply",
                    localAndroidGoalReply(
                        arguments = arguments,
                        result = compiled
                    )
                )
        }

        val executionContract =
            compiled.optJSONObject(
                "execution_contract"
            ) ?: JSONObject()

        val executorKey =
            executionContract.optString(
                "executor_key",
                "android_goal_executor"
            )

        executionPhase(
            phase = "android_goal_execution",
            executor = executorKey
        )

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "goal_compiled",
            message = "Goal Compiler v2: контракт выполнения готов",
            details =
                "goal_type=${compiled.optString("goal_type")}; executor=$executorKey; " +
                    "verify=${executionContract.optString("verification_policy")}; " +
                    "terminal=${executionContract.optString("terminal_policy")}".take(1000)
        )

        executionKernel.addEvidence(
            type = "goal_compiled",
            source = "goal_compiler_v2",
            detail = executionContract.toString(),
            confidence = 100
        )

        val plan =
            compiled.optJSONObject(
                "plan"
            )
                ?: return toolResult(
                    false,
                    "Goal Compiler не вернул локальный план"
                )
                    .put(
                        "status",
                        "invalid_goal"
                    )
                    .put(
                        "local_reply",
                        "Не удалось подготовить Android-задачу."
                    )

        val normalizedArguments =
            compiled.optJSONObject(
                "normalized_goal"
            )
                ?: JSONObject(
                    arguments.toString()
                )

        if (
            compiled.optBoolean(
                "goal_repaired",
                false
            )
        ) {
            commandHistoryStore.addEvent(
                activeCommandHistoryId,
                state = "goal_integrity_repair",
                message = "Классификация Android-цели уточнена локально",
                details =
                    "original=${compiled.optString("original_goal_type")}; " +
                        "effective=${compiled.optString("goal_type")}; " +
                        "target=${compiled.optString("target")}"
            )
        }

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "compiled_plan",
            message = compiled.optString(
                "goal_type",
                "android_goal"
            ),
            details = plan.toString()
        )

        broadcastStatus(
            "Выполняю задачу на устройстве…",
            STATE_EXECUTING
        )

        val goalCommandToken =
            activeCommandToken

        val durableId =
            checkpointGoalId

        if (durableId != null) {
            val planSaved =
                try {
                    checkpointStore
                        .attachAndroidPlan(
                            id = durableId,
                            arguments = normalizedArguments,
                            plan = plan
                        ) !=
                        null
                } catch (error: Exception) {
                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state = "goal_checkpoint_error",
                        message = "Compiled Android plan не сохранён перед выполнением",
                        details = error.message.orEmpty().take(220)
)
                    false
                }

            if (!planSaved) {
                return toolResult(
                    false,
                    "Android-задача не запущена: compiled plan не удалось надёжно сохранить."
                )
                    .put(
                        "status",
                        "checkpoint_failed"
                    )
                    .put(
                        "checkpoint_failed",
                        true
                    )
                    .put(
                        "replan_recommended",
                        false
                    )
                    .put(
                        "local_reply",
                        "Я остановила Android-задачу до первого действия: план не удалось сохранить."
                    )
            }
        }

        val result =
            AyanaAndroidTaskEngine(
                screenIntelligence = screenIntelligence,
                gateway =
                    object : AyanaAndroidTaskEngine.ActionGateway {

                        override fun openSettings(
                            section: String
                        ): JSONObject =
                            this@AyanaVoiceService
                                .agentOpenSettings(
                                    section
                                )

                        override fun openApp(
                            name: String
                        ): JSONObject =
                            this@AyanaVoiceService
                                .agentOpenApp(
                                    name
                                )

                        override fun openAppInfo(
                            name: String
                        ): JSONObject =
                            this@AyanaVoiceService
                                .agentOpenAppInfo(
                                    name
                                )

                        override fun openAppSettings(
                            name: String,
                            section: String
                        ): JSONObject =
                            this@AyanaVoiceService
                                .agentOpenAppSettings(
                                    requestedName =
                                        name,
                                    section =
                                        section
                                )

                        override fun changeVolume(
                            action: String
                        ): JSONObject =
                            this@AyanaVoiceService
                                .agentChangeVolume(
                                    action
                                )
                    },
                shouldCancel = {
                    cancelRequested ||
                        executionKernel.isCancelled() ||
                        shuttingDown ||
                        goalCommandToken !=
                        activeCommandToken
                }
            )
                .execute(
                    plan = plan,
                    confirmed = false,
                    startIndex = 0,
                    initialActionsUsed = 0,
                    onCheckpoint =
                        { checkpoint ->
                            persistAndroidGoalCheckpoint(
                                goalId = durableId,
                                checkpoint = checkpoint,
                                historyMessage = "Android checkpoint",
                                store = checkpointStore
                            )
                        }
                )

        result
            .optJSONObject(
                "screen"
            )
            ?.let {
                screen ->
                capabilityRegistry
                    .recordScreenObservation(
                        screen
                    )
            }

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "engine_result",
            message = result.optString(
                "status",
                if (result.optBoolean("success", false)) "success" else "blocked"
            ),
            details = result.toString()
        )

        return JSONObject(
            result.toString()
        )
            .put(
                "goal_type",
                compiled.optString(
                    "goal_type"
                )
            )
            .put(
                "execution_contract",
                executionContract
            )
            .put(
                "compiled_target",
                compiled.optString(
                    "target"
                )
            )
            .put(
                "stop_if_missing",
                compiled.optBoolean(
                    "stop_if_missing",
                    false
                )
            )
            .put(
                "normalized_goal",
                normalizedArguments
            )
            .put(
                "local_reply",
                localAndroidGoalReply(
                    arguments = normalizedArguments,
result = result
                )
            )
    }

    private fun localAndroidGoalReply(
        arguments: JSONObject,
        result: JSONObject
    ): String {

        val status =
            result
                .optString(
                    "status"
                )
                .trim()
                .lowercase(
                    Locale.ROOT
                )

        val message =
            result
                .optString(
                    "message"
                )
                .trim()

        val target =
            arguments
                .optString(
                    "target"
                )
                .trim()

        val stopIfMissing =
            arguments
                .optBoolean(
                    "stop_if_missing",
                    false
                )

        return when (status) {

            "success" ->
                "Готово."

            "needs_confirmation" ->
                message
                    .ifBlank {
                        "Для этого действия нужно ваше подтверждение."
                    }

            "blocked" -> {

                val missing =
                    message
                        .lowercase(
                            Locale.ROOT
                        )
                        .let { text ->
                            text.contains(
                                "не найден"
                            ) ||
                                text.contains(
                                    "не найдена"
                                ) ||
                                text.contains(
                                    "не найдено"
                                )
                        }

                if (
                    stopIfMissing &&
                    missing &&
                    target.isNotBlank()
                ) {
                    "Пункт «$target» не найден, поэтому прекращаю задачу."
                } else {
                    message
                        .ifBlank {
                            "Не удалось завершить задачу на устройстве."
                        }
                }
            }

            "invalid_goal",
            "invalid_plan" ->
                message
                    .ifBlank {
                        "Не удалось подготовить эту Android-задачу."
                    }

            else ->
                if (
                    result.optBoolean(
                        "success",
                        false
                    )
                ) {
                    "Готово."
                } else {
                    message
                        .ifBlank {
                            "Не удалось завершить задачу на устройстве."
                        }
                }
        }
    }

    private fun agentRememberMemory(
        text: String,
        category: String
    ): JSONObject {

        val conflicts =
            memoryStore
                .findPotentialConflicts(
                    text
                )

        val item =
            memoryStore.remember(
                text = text,
                category = category,
                source = "user",
                provenance = "explicit",
                confidence = 1.0
            )

        return if (item != null) {

            val conflictArray =
                JSONArray()

            conflicts.forEach { conflict ->
                if (
                    conflict.id !=
                    item.id
                ) {
                    conflictArray.put(
                        JSONObject()
                            .put(
                                "id",
                                conflict.id
                            )
                            .put(
                                "text",
                                conflict.text
                            )
                            .put(
                                "category",
                                conflict.category
                            )
                    )
                }
            }

            JSONObject()
                .put(
                    "success",
                    true
                )
                .put(
                    "message",
                    "Сохранено в долговременную память v2"
                )
                .put(
                    "memory",
                    JSONObject()
                        .put(
                            "id",
                            item.id
                        )
                        .put(
                            "text",
                            item.text
                        )
                        .put(
                            "category",
                            item.category
                        )
                        .put(
                            "source",
                            item.source
                        )
                        .put(
                            "provenance",
                            item.provenance
                        )
                        .put(
                            "confidence",
                            item.confidence
                        )
                )
                .put(
                    "potential_conflicts",
                    conflictArray
                )

        } else {

            toolResult(
                false,
                "Пустую запись сохранить нельзя"
            )
        }
    }

    private fun agentForgetMemory(
        query: String
    ): JSONObject {

        val normalized =
            query
                .lowercase(
                    Locale.getDefault()
                )
                .replace('ё', 'е')
.trim()

        val clearAll =
            normalized in
                setOf(
                    "все",
                    "всё",
                    "всю память",
                    "все воспоминания",
                    "all",
                    "everything",
                    "all memories"
                )

        val removed =
            if (clearAll) {
                memoryStore.clear()
            } else {
                memoryStore.forget(
                    query
                )
            }

        return JSONObject()
            .put(
                "success",
                true
            )
            .put(
                "removed",
                removed
            )
            .put(
                "message",
                if (removed > 0) {
                    "Удалено записей из памяти: $removed"
                } else {
                    "Подходящих записей в памяти не найдено"
                }
            )
    }

    private fun agentRecallMemory(
        query: String
    ): JSONObject {

        val memories =
            if (query.isBlank()) {

                memoryStore.getAll(
                    20
                )

            } else {

                memoryStore.search(
                    query = query,
                    limit = 20
                )
            }

        val array =
            JSONArray()

        memories.forEach { item ->

            array.put(
                JSONObject()
                    .put(
                        "id",
                        item.id
                    )
                    .put(
                        "text",
                        item.text
                    )
                    .put(
                        "category",
                        item.category
                    )
            )
        }

        return JSONObject()
            .put(
                "success",
                true
            )
            .put(
                "count",
                memories.size
            )
            .put(
                "memories",
                array
            )
            .put(
                "message",
                if (memories.isEmpty()) {
                    "Подходящих записей в памяти нет"
                } else {
