    private fun agentListGoals(): JSONObject {

        val goals =
            durableGoalStore
                .getRecoverableJson(
                    20
                )

        val safeGoals =
            JSONArray()

        for (
            i in
            0 until goals.length()
        ) {
            val item =
                goals.optJSONObject(i)
                    ?: continue

            val planner =
                item.optJSONObject(
                    "planner_envelope"
                )
                    ?: JSONObject()

            safeGoals.put(
                JSONObject()
                    .put(
                        "id",
                        item.optString(
                            "id"
                        )
                    )
                    .put(
                        "command",
                        item.optString(
                            "command"
                        )
                    )
                    .put(
                        "status",
                        item.optString(
                            "status"
                        )
                    )
                    .put(
                        "is_current",
                        item.optBoolean(
                            "is_current",
                            false
                        )
                    )
                    .put(
                        "updated_at",
                        item.optLong(
                            "updated_at",
                            0L
                        )
                    )
                    .put(
                        "next_plan_step",
                        item.optInt(
                            "next_plan_step",
                            0
                        )
                    )
                    .put(
                        "plan_size",
                        item.optInt(
                            "plan_size",
                            0
                        )
                    )
                    .put(
                        "last_checkpoint",
                        item.optString(
                            "last_checkpoint"
                        )
                    )
                    .put(
                        "last_error",
                        item.optString(
                            "last_error"
                        )
                    )
                    .put(
                        "planner_domain",
                        planner.optString(
                            "domain"
                        )
)
                    .put(
                        "planner_subgoals",
                        planner.optJSONArray(
                            "subgoals"
                        )
                            ?.length()
                            ?: 0
                    )
            )
        }

        return JSONObject()
            .put(
                "success",
                true
            )
            .put(
                "count",
                safeGoals.length()
            )
            .put(
                "goals",
                safeGoals
            )
    }

