    private fun parseLocalTaskTimeOrNull(
        value: String
    ): Long? {

        val clean =
            value.trim()

        if (
            clean.isBlank()
        ) {
            return null
        }

        return try {
            LocalDateTime
                .parse(
                    clean,
                    DateTimeFormatter
                        .ofPattern(
                            "yyyy-MM-dd'T'HH:mm:ss"
                        )
                )
                .atZone(
                    ZoneId.systemDefault()
                )
                .toInstant()
                .toEpochMilli()
        } catch (_: Exception) {
            null
        }
    }

    private fun agentUpdateReminder(
        query: String,
        title: String,
        message: String,
        triggerAtLocal: String,
        recurrence: String,
        enabledMode: String
    ): JSONObject {

        val matches =
            taskStore
                .findByQuery(
                    query,
                    3
                )

        if (
            matches.size !=
            1
        ) {
            val candidates =
                JSONArray()

            matches.forEach { task ->
                candidates.put(
                    JSONObject()
                        .put(
                            "id",
                            task.id
                        )
                        .put(
                            "title",
                            task.title
                        )
                )
            }

            return JSONObject()
                .put(
                    "success",
                    false
                )
                .put(
                    "message",
                    if (matches.isEmpty()) {
                        "Напоминание не найдено"
                    } else {
                        "Найдено несколько похожих напоминаний; уточните"
                    }
                )
                .put(
                    "candidates",
                    candidates
                )
        }

        val old =
            matches.first()

        val parsedTrigger =
            if (
                triggerAtLocal.isBlank()
            ) {
                null
            } else {
                parseLocalTaskTimeOrNull(
                    triggerAtLocal
                )
                    ?: return toolResult(
                        false,
                        "Неверный формат нового времени; нужен YYYY-MM-DDTHH:mm:ss"
                    )
            }

        if (
            parsedTrigger !=
            null &&
            parsedTrigger <=
            System.currentTimeMillis()
        ) {
            return toolResult(
                false,
                "Новое время напоминания уже прошло"
            )
        }

        val enabled =
            when (
                enabledMode
                    .trim()
                    .lowercase(
                        Locale.ROOT
                    )
            ) {
                "true",
                "enable",
                "enabled",
                "включить" ->
                    true
                "false",
                "disable",
                "disabled",
                "отключить" ->
                    false
                else ->
                    null
            }

        val updated =
            taskStore
                .updateTask(
                    id = old.id,
                    title = title.trim()
                        .ifBlank {
                            null
                        },
                    message = message.trim()
                        .ifBlank {
                            null
                        },
                    triggerAtMillis = parsedTrigger,
                    recurrence = recurrence.trim()
                        .ifBlank {
                            null
                        },
                    enabled = enabled
                )
                ?: return toolResult(
                    false,
                    "Не удалось изменить напоминание"
                )

        taskScheduler
            .cancel(
                old
            )

        if (
            updated.enabled &&
            updated.triggerAtMillis >
            System.currentTimeMillis()
        ) {
            val schedule =
                taskScheduler
                    .schedule(
                        updated
                    )

            if (!schedule.success) {
                // Fail closed: restore the old task and schedule rather than
                // silently leaving edited metadata without a real alarm.
                taskStore.updateTask(
                    id = old.id,
                    title = old.title,
                    message = old.message,
                    triggerAtMillis = old.triggerAtMillis,
recurrence = old.recurrence,
                    enabled = old.enabled
                )
                if (
                    old.enabled &&
                    old.triggerAtMillis >
                    System.currentTimeMillis()
                ) {
                    taskScheduler.schedule(
                        old
                    )
                }
                return toolResult(
                    false,
                    "Изменение отменено: Android не смог перепланировать напоминание"
                )
            }
        }

        return JSONObject()
            .put(
                "success",
                true
            )
            .put(
                "task_id",
                updated.id
            )
            .put(
                "title",
                updated.title
            )
            .put(
                "enabled",
                updated.enabled
            )
            .put(
                "recurrence",
                updated.recurrence
            )
            .put(
                "trigger_at_millis",
                updated.triggerAtMillis
            )
            .put(
                "message",
                "Напоминание обновлено"
            )
    }

    private fun agentSetReminderEnabled(
        query: String,
        enabled: Boolean
    ): JSONObject =
        agentUpdateReminder(
            query = query,
            title = "",
            message = "",
            triggerAtLocal = "",
            recurrence = "",
            enabledMode =
                if (enabled) {
                    "true"
                } else {
                    "false"
                }
        )

    private fun toolResult(
        success: Boolean,
        message: String
    ): JSONObject {

        return JSONObject()
            .put(
                "success",
                success
            )
            .put(
                "message",
                message
            )
    }

    private fun agentOpenApp(
        requestedName: String
    ): JSONObject {

        val result =
            appResolver
                .launch(
                    requestedName
                )

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state =
                if (
                    result.optBoolean(
                        "success",
                        false
                    )
                ) {
                    "app_resolved"
                } else {
                    "app_resolver_miss"
                },
            message =
                result.optString(
                    "message",
                    "App Resolver v2"
                ),
            details =
                "package=${result.optString("package")}; " +
                    "confidence=${result.optInt("confidence", 0)}; " +
                    "source=${result.optString("source")}; " +
                    "reason=${result.optString("reason")}".take(520)
        )

        return result
    }

    private fun agentOpenAppInfo(
        requestedName: String
    ): JSONObject {

        val resolved =
            appResolver
                .resolve(
                    requestedName
                )

        if (
            !resolved.success
        ) {
            return resolved.toJson()
                .put(
                    "message",
                    "Приложение не найдено: $requestedName"
                )
        }

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state = "app_resolved",
            message = "App Resolver v2: ${resolved.label}",
            details =
                "package=${resolved.packageName}; confidence=${resolved.confidence}; source=${resolved.source}"
        )

        return try {

            val intentDispatchedAt =
                System.currentTimeMillis()

            startAppInfoIntent(
                resolved.packageName
            )

            val verification =
                awaitVerifiedAppDetailScreen(
                    appTarget = resolved.label,
                    section = "info",
                    timeoutMs = APP_DETAIL_VERIFY_TIMEOUT_MS
                )

            val intentAttestation =
                if (verification.optBoolean("success", false)) {
                    JSONObject().put("success", false)
                } else {
                    verifySettingsIntentAttestation(
                        screen = verification.optJSONObject("screen") ?: JSONObject(),
                        targetPackage = resolved.packageName,
                        section = "info",
                        dispatchedAtMs = intentDispatchedAt
                    )
                }

            if (
                verification.optBoolean(
                    "success",
                    false
                ) ||
                intentAttestation.optBoolean("success", false)
            ) {

                if (intentAttestation.optBoolean("success", false)) {
                    commandHistoryStore.addEvent(
                        activeCommandHistoryId,
                        state = "settings_intent_attested",
                        message = "App Info подтверждён exact-intent attestation",
                        details = intentAttestation.toString().take(900)
                    )
                    executionKernel.addEvidence(
                        type = "settings_intent_attestation",
                        source = "settings_verifier",
                        detail = intentAttestation.toString(),
                        confidence = intentAttestation.optInt("confidence", 80)
                    )
                }

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "app_info_verified",
                    message = "Экран App Info подтверждён",
                    details =
                        "package=${resolved.packageName}; label=${resolved.label}".take(420)
                )

                resolved.toJson()
                    .put(
                        "success",
                        true
                    )
                    .put(
                        "verified",
                        true
                    )
                    .put(
                        "message",
                        "Открыта информация о приложении ${resolved.label}"
                    )

            } else {

                commandHistoryStore.addEvent(
                    activeCommandHistoryId,
                    state = "app_info_verify_failed",
                    message = "App Info не подтверждён по экрану",
                    details =
                        (
                            "package=${resolved.packageName}; label=${resolved.label}; " +
                                appDetailVerificationDiagnosticSummary(
                                    verification.optJSONObject("screen") ?: JSONObject()
                                )
                            ).take(1800)
                )

                resolved.toJson()
                    .put(
                        "success",
                        false
                    )
                    .put(
                        "verified",
                        false
                    )
                    .put(
                        "message",
                        "Android принял переход, но экран информации о приложении ${resolved.label} не подтверждён"
                    )
            }

        } catch (
            error: Exception
        ) {

            resolved.toJson()
                .put(
                    "success",
                    false
                )
                .put(
                    "verified",
                    false
                )
                .put(
                    "message",
                    "Не удалось открыть информацию о приложении ${resolved.label}: ${error.message ?: "неизвестная ошибка"}"
                )
        }
    }

    private fun startAppInfoIntent(
        packageName: String
    ) {

        startActivity(
            Intent(
                Settings.ACTION_APPLICATION_DETAILS_SETTINGS,
                Uri.parse(
                    "package:$packageName"
                )
            ).apply {
                addFlags(
                    Intent.FLAG_ACTIVITY_NEW_TASK
                )
            }
        )
    }

    private fun agentOpenSettings(
        section: String
    ): JSONObject {

        val result =
            try {
                systemSettingsNavigator
                    .open(
                        section
                    )
            } catch (error: Exception) {
                toolResult(
                    false,
                    "Не удалось открыть и подтвердить системный раздел настроек: " +
                        (error.message ?: error.javaClass.simpleName)
                )
                    .put(
                        "verified",
                        false
                    )
                    .put(
                        "terminal_status",
                        "ERROR"
                    )
                    .put(
                        "section",
                        section
                    )
            }

        commandHistoryStore.addEvent(
            activeCommandHistoryId,
            state =
                if (
                    result.optBoolean(
                        "success",
                        false
                    ) &&
                    result.optBoolean(
                        "verified",
                        false
                    )
                ) {
                    "settings_section_verified"
                } else {
                    "settings_section_verify_failed"
                },
            message =
                result.optString(
                    "reason",
                    "settings_navigation"
                ),
            details =
                (
                    "requested=${section.take(80)}; " +
                        "canonical=${result.optString("canonical_section").take(80)}; " +
                        "owner=${result.optBoolean("settings_owner_verified", false)}; " +
                        "mode=${result.optString("verification_mode").take(120)}; " +
                        "marker=${result.optString("matched_marker").take(120)}; " +
                        "terminal=${result.optString("terminal_status").take(32)}"
                    ).take(700)
        )

        return result
    }

